  const esAcril = P === 'TRANS' || P === 'NEGRO';
  return corteNormNombre(cliente) + '|' + (esAcril ? 'T:' + corteNormNombre(diseno || producto) : 'I:' + corteNormNombre(producto)) + '|' + (Math.max(1, parseInt(String(cantidad || '').replace(/\D/g, ''), 10) || 1));
