async function corteLandingClienteLtv(token, e) {
  const datos = (() => { try { return JSON.parse(e.datos_json || '{}') || {}; } catch (_) { return {}; } })();
  const txt = corteLandingDatosTxt(e.nombre_hoja, datos.nuevo || {}, e.entrega);
  const ltv = await corteHojaLeer(token, CORTE_SHEET_ID, 'LTV_Alumnos!A1:F');
  if (ltv.some((r, i) => i > 0 && corteTel((r || [])[5]) === e.telefono)) return;
  const fila = corteHojaUltima(ltv, 1) + 1;
  await corteHojaEscribir(token, CORTE_SHEET_ID, 'RAW', [{ range: `LTV_Alumnos!B${fila}`, values: [[e.nombre_hoja]] }, { range: `LTV_Alumnos!E${fila}:F${fila}`, values: [[txt, '54 9 ' + String(e.telefono).slice(3)]] }]);
}
// Cron: (1) filas de la planilla para las piezas web listas (diseños medidos por Emma; insumos al cierre), con el
// cliente nuevo antes; (2) resumen del cierre a Gaspar; (3) carga automática de la tanda. Candado de 4 min.
async function corteLandingCron(env) {
  try {
    if (!(await ensureCorteLandingSchema(env))) return;
    const ahora = Date.now();
    const lockId = String(ahora) + Math.random().toString(36).slice(2);
    let lk = null;
    try { lk = await env.DB.prepare("INSERT INTO kv_cache (k, v, updated_at) VALUES ('corte_landing_lock', ?, ?) ON CONFLICT(k) DO UPDATE SET v=excluded.v, updated_at=excluded.updated_at WHERE kv_cache.updated_at < ? RETURNING k").bind(lockId, new Date(ahora).toISOString(), new Date(ahora - 4 * 60000).toISOString()).first(); } catch (_) {}
    if (!lk) return;
    try {
      await corteLandingEscribirPendientes(env, ahora);
      await corteLandingResumenes(env, ahora);
      await corteAutoCarga(env, ahora);
      if (new Date(ahora - 3 * 3600000).getUTCHours() === 4 && new Date(ahora).getUTCMinutes() < 5) { // 4 AR: contadores viejos
        try { await env.DB.prepare("DELETE FROM kv_cache WHERE k LIKE 'corte_rl:%' AND updated_at < ?").bind(new Date(ahora - 86400000).toISOString()).run(); } catch (_) {}
      }
    } finally { try { await env.DB.prepare("DELETE FROM kv_cache WHERE k='corte_landing_lock' AND v=?").bind(lockId).run(); } catch (_) {} }
  } catch (e) { try { console.log('corteLandingCron: ' + String((e && e.message) || e)); } catch (_) {} }
}
async function corteLandingEscribirPendientes(env, ahora) {
  if ((await kvGet(env, 'corte_hoja_auto_on', '1')) !== '1') return;
  const cand = (await env.DB.prepare("SELECT id, telefono, cliente_nombre, hoja_cliente, hoja_fecha, diseno_nombre, aclaraciones, cantidad, ancho_real, alto_real, producto, estado, precio FROM corte_pedidos WHERE origen='landing' AND hoja_fila IS NULL AND IFNULL(hoja_fecha,'')!='' AND estado NOT IN ('prueba','cancelado') ORDER BY id LIMIT 60").all()).results || [];
  // Diseño: cuando Emma ya cargó la medida final. Insumo: al cierre de su tanda (sábado 12 h).
  const listas = cand.filter(p => p.producto === 'TRANS' ? (p.estado !== 'pedido' && +p.ancho_real > 0 && +p.alto_real > 0) : ahora >= corteLandingCierreDe(p.hoja_fecha)).slice(0, 15);
  if (!listas.length) return;
  const token = await sheetsAccessToken(env);
  if (!token) return;
  // Clientes nuevos de estas piezas: primero a LTV (así la carga y logística los reconocen).
  for (const tel of new Set(listas.map(p => p.telefono).filter(Boolean))) {
    const e = await env.DB.prepare(`SELECT ${CORTE_LANDING_COLS} FROM corte_landing_envios WHERE telefono=? AND nuevo=1 AND prueba=0 AND IFNULL(cliente_hoja,'')='' ORDER BY id LIMIT 1`).bind(tel).first();
    if (!e) continue;
    try { await corteLandingClienteLtv(token, e); await env.DB.prepare("UPDATE corte_landing_envios SET cliente_hoja='escrito' WHERE telefono=? AND nuevo=1").bind(tel).run(); }
    catch (err) { await corteLandingError(env, 'cliente nuevo ' + e.nombre_hoja + ' en LTV: ' + String((err && err.message) || err)); }
  }
  const fechas = [...new Set(listas.map(p => p.hoja_fecha))];
  const ocupadas = new Set();
  for (const f of fechas) { try { ((await env.DB.prepare("SELECT hoja_fila FROM corte_pedidos WHERE hoja_fecha=? AND hoja_fila IS NOT NULL").bind(f).all()).results || []).forEach(r => ocupadas.add(+r.hoja_fila)); } catch (_) {} }
  const memo = {}, nombres = {};
  let ok = 0;
  for (const p of listas) {
    try {
      // Nombre exacto de la pestaña Clientes (si no está, se suma con sus datos de envío).
      const tel = p.telefono || '';
      if (!nombres[tel + '|' + p.hoja_cliente]) {
        const c = tel ? await corteLandingCliente(env, tel) : { datos: '' };
        let datos = /^retira\b/i.test(String(c.datos || '').trim()) || !String(c.datos || '').trim() ? 'retira' : String(c.datos).replace(/\s+/g, ' ').trim().slice(0, 300);
        const e = tel ? await env.DB.prepare(`SELECT ${CORTE_LANDING_COLS} FROM corte_landing_envios WHERE telefono=? AND prueba=0 ORDER BY id DESC LIMIT 1`).bind(tel).first() : null;
        if (e && +e.nuevo === 1) { try { const d = JSON.parse(e.datos_json || '{}') || {}; datos = corteLandingDatosTxt(e.nombre_hoja, d.nuevo || {}, e.entrega); } catch (_) {} }
        nombres[tel + '|' + p.hoja_cliente] = await corteLandingNombreClientes(token, p.hoja_cliente || p.cliente_nombre, datos, memo);
      }
      const cliente = nombres[tel + '|' + p.hoja_cliente];
      const r = await corteHojaFilaPieza(token, {
        cliente, diseno: p.diseno_nombre || p.producto, cantidad: Math.max(1, parseInt(p.cantidad, 10) || 1),
        fecha: p.hoja_fecha, ancho: p.producto === 'TRANS' ? +p.ancho_real : '', alto: p.producto === 'TRANS' ? +p.alto_real : '', producto: p.producto, aclaracion: p.aclaraciones || '',
      }, ocupadas);
      ocupadas.add(r.fila);
      // Fila nueva (no una que Emma tipeó a mano): en Venta_Insumos, la misma fila (IMPORTRANGE de columnas enteras) queda
      // "Pendiente de pago" (lo que busca la marca automática de pagado) y con el precio que se le cobra al cliente, como
      // hace Gaspar a mano con los precios especiales (la fórmula de COGS no conoce la escala de las fuentes ni los
      // precios nuevos). Si falla, la fila igual queda escrita: se avisa y no se reintenta (no se duplica nada).
      if (!r.vinculada && +p.precio > 0) {
        try { await corteHojaEscribir(token, CORTE_SHEET_ID, 'RAW', [{ range: `Venta_Insumos!I${r.fila}:J${r.fila}`, values: [['Pendiente de pago', Math.round(+p.precio * 100) / 100]] }]); }
        catch (err) { await corteLandingError(env, 'Venta_Insumos fila ' + r.fila + ' (pago/precio): ' + String((err && err.message) || err)); }
      }
      await env.DB.prepare("UPDATE corte_pedidos SET hoja_fila=?, hoja_cliente=?, updated_at=? WHERE id=? AND hoja_fila IS NULL").bind(r.fila, cliente, new Date().toISOString(), p.id).run();
      ok++;
    } catch (err) { await corteLandingError(env, 'pieza ' + p.id + ' (' + (p.hoja_cliente || p.cliente_nombre) + ' · ' + (p.diseno_nombre || p.producto) + '): ' + String((err && err.message) || err)); }
  }
  if (ok) { try { await kvSet(env, 'corte_landing_err_n', '0'); } catch (_) {} }
}
// Un error de escritura en la planilla: se guarda; al 3° seguido se avisa a Gaspar (1 vez cada 6 h).
async function corteLandingError(env, txt) {
  try { console.log('corteLanding: ' + txt); } catch (_) {}
  try {
    const n = (parseInt(await kvGet(env, 'corte_landing_err_n', '0'), 10) || 0) + 1;
    await kvSet(env, 'corte_landing_err_n', String(n)); await kvSet(env, 'corte_landing_err_ult', txt.slice(0, 500));
    const ult = parseInt(await kvGet(env, 'corte_landing_err_aviso', '0'), 10) || 0;
    if (n >= 3 && Date.now() - ult > 6 * 3600000) {
      await kvSet(env, 'corte_landing_err_aviso', String(Date.now()));
      await precotizNotifyGaspar(env, 'Corte (pedidos web): no puedo escribir en la planilla de Emma. Lo sigo intentando cada 5 min.\nÚltimo error: ' + txt.slice(0, 300), { tipo: 'corte_landing_error', prioridad: 'P2' });
    }
  } catch (_) {}
}
// Resumen del cierre (sábado 12 h): lo que entró por la web para esa tanda, con lo que necesita una mirada.
async function corteLandingResumenes(env, ahora) {
  const pend = (await env.DB.prepare("SELECT DISTINCT hoja_fecha FROM corte_landing_envios WHERE prueba=0 AND IFNULL(cierre_at,'')='' AND IFNULL(hoja_fecha,'')!='' LIMIT 10").all()).results || [];
  for (const { hoja_fecha: f } of pend) {
    const cierre = corteLandingCierreDe(f);
    if (!cierre || ahora < cierre) continue;
    const envs = (await env.DB.prepare(`SELECT ${CORTE_LANDING_COLS} FROM corte_landing_envios WHERE prueba=0 AND hoja_fecha=? ORDER BY id`).bind(f).all()).results || [];
    const piezas = (await env.DB.prepare("SELECT producto, estado, diseno_nombre, cantidad FROM corte_pedidos WHERE origen='landing' AND hoja_fecha=? AND estado NOT IN ('prueba','cancelado')").bind(f).all()).results || [];
    const dis = piezas.filter(p => p.producto === 'TRANS'), sinMedir = dis.filter(p => p.estado === 'pedido').length;
    const ins = piezas.filter(p => p.producto !== 'TRANS');
    const clientes = new Set(envs.map(e => e.telefono)).size;
    const est = envs.reduce((s, e) => s + (parseInt(e.estimado, 10) || 0), 0);
    const nuevos = envs.filter(e => +e.nuevo === 1);
    const dirDe = e => { try { return (JSON.parse(e.datos_json || '{}') || {}).dir || null; } catch (_) { return null; } };
    const dirNuevas = envs.filter(e => { const d = dirDe(e); return !!(d && d.calle); });
    const lunes = f.split('/').slice(0, 2).map(x => x.padStart(2, '0')).join('/');
    const l = ['Corte · pedidos web para el lunes ' + lunes + ' (cerró hoy a las 12)'];
    l.push(dis.length + ' diseño' + (dis.length === 1 ? '' : 's') + ' de ' + clientes + ' cliente' + (clientes === 1 ? '' : 's') + ' · estimado ' + corteLandingPesos(est));
    if (ins.length) { const tot = {}; ins.forEach(p => { const k = p.diseno_nombre || p.producto; tot[k] = (tot[k] || 0) + (parseInt(p.cantidad, 10) || 1); }); l.push('Insumos: ' + Object.entries(tot).map(([k, n]) => n + ' × ' + k).join(', ')); }
    l.push(sinMedir ? 'Emma: ' + (dis.length - sinMedir) + ' medidos, ' + sinMedir + ' por medir' : 'Emma ya midió todo');
    if (nuevos.length) l.push('Clientes nuevos: ' + nuevos.map(e => e.nombre_hoja + ' (…' + String(e.telefono).slice(-4) + ')').join(', '));
    if (dirNuevas.length) l.push('Envío a una dirección nueva (pasásela a logística): ' + dirNuevas.map(e => { const d = dirDe(e) || {}; return e.nombre_hoja + ': ' + [d.calle, d.localidad, d.provincia, d.cp ? 'CP ' + d.cp : ''].filter(Boolean).join(', '); }).join(' · '));
    // Se marca aunque el envío falle: es un resumen, no se reintenta cada 5 minutos.
    try { await precotizNotifyGaspar(env, l.join('\n'), { tipo: 'corte_landing_resumen', prioridad: 'P2', clave: 'corte_landing_resumen:' + f }); } catch (_) {}
    await env.DB.prepare("UPDATE corte_landing_envios SET cierre_at=? WHERE hoja_fecha=? AND IFNULL(cierre_at,'')=''").bind(new Date().toISOString(), f).run();
  }
}
// Le pone la tanda a las piezas web del lunes `fecha` (crea la tanda si hace falta), pasa a 'cortado' los diseños con
// matriz y los insumos, y aplica la entrega que eligió cada cliente a TODAS sus piezas de esa tanda (también a las que
// entran desde la planilla), con entrega_manual=1 para que la sincronización con la planilla no la pise.
async function corteLandingAsignarTanda(env, fecha) {
  if (!(await ensureCorteLandingSchema(env))) return { error: 'schema' };
  const f = corteFechaValida(fecha); if (!f) return { error: 'fecha' };
  const n = await env.DB.prepare("SELECT COUNT(*) AS n FROM corte_pedidos WHERE origen='landing' AND hoja_fecha=? AND estado NOT IN ('prueba','cancelado')").bind(f.txt).first();
  if (!n || !n.n) return { ok: true, asignadas: 0 };
  const td = await corteTandaDeFecha(env, f, false);
  if (!td.tanda) return { error: 'no pude crear/encontrar la tanda' };
  const tid = td.tanda.id, nowIso = new Date().toISOString();
  const a = await env.DB.prepare("UPDATE corte_pedidos SET tanda_id=?, updated_at=? WHERE origen='landing' AND hoja_fecha=? AND tanda_id IS NULL AND estado NOT IN ('prueba','cancelado')").bind(tid, nowIso, f.txt).run();
  const c = await env.DB.prepare("UPDATE corte_pedidos SET estado='cortado', updated_at=? WHERE origen='landing' AND hoja_fecha=? AND tanda_id=? AND ((producto='TRANS' AND estado='matriz_lista') OR (producto!='TRANS' AND estado='pedido'))").bind(nowIso, f.txt, tid).run();
  const envs = (await env.DB.prepare("SELECT telefono, entrega FROM corte_landing_envios WHERE prueba=0 AND hoja_fecha=? ORDER BY id").bind(f.txt).all()).results || [];
  const ent = {}; envs.forEach(e => { if (e.telefono && (e.entrega === 'envio' || e.entrega === 'retira')) ent[e.telefono] = e.entrega; }); // el último envío manda
  for (const [tel, en] of Object.entries(ent)) {
    try { await env.DB.prepare("UPDATE corte_pedidos SET entrega=?, entrega_manual=1, updated_at=? WHERE tanda_id=? AND telefono=? AND estado NOT IN ('despachado','entregado') AND IFNULL(producto,'')!='NEON'").bind(en, nowIso, tid, tel).run(); } catch (_) {}
  }
  const sm = await env.DB.prepare("SELECT COUNT(*) AS n FROM corte_pedidos WHERE origen='landing' AND hoja_fecha=? AND tanda_id=? AND producto='TRANS' AND estado='pedido'").bind(f.txt, tid).first();
  return { ok: true, tanda_id: tid, asignadas: (a.meta && a.meta.changes) || 0, a_cortado: (c.meta && c.meta.changes) || 0, sin_medir: (sm && sm.n) || 0 };
}
// La carga de la tanda completa (botón "Cargar tanda" y carga automática): primero las piezas web (para que la carga de
// la planilla las reconozca), después la planilla y la entrega.
async function corteCargarTandaCompleta(env, { fecha, dryRun = true, incluirSospechosas = false }) {
  let web = null;
  if (!dryRun) { try { web = await corteLandingAsignarTanda(env, fecha); } catch (e) { web = { error: String((e && e.message) || e) }; } }
  const r = await corteCargarTanda(env, { fecha, dryRun, incluirSospechosas });
  // Otra pasada después de la planilla: la entrega que eligió el cliente en la web vale también para lo que entró recién
  // desde la hoja (p. ej. un insumo que le tipearon a mano). Es idempotente.
  if (!dryRun && web && web.ok && web.tanda_id) { try { await corteLandingAsignarTanda(env, fecha); } catch (_) {} }
  if (web) r.web = web;
  if (r.ok && !dryRun && r.tanda_id) { try { r.sync_entrega = await corteSyncEntrega(env, { soloTandaId: r.tanda_id, notify: true }); } catch (_) {} }
  return r;
}
// Carga automática: sábado 21 h, domingo 21 h y lunes 7:30 (AR), la tanda del lunes. Idempotente (la carga solo suma lo
// nuevo); cada franja corre una sola vez. Avisa solo si entró algo o hay diseños web sin medir.
async function corteAutoCarga(env, ahora) {
  if ((await kvGet(env, 'corte_autocarga_on', '1')) !== '1') return;
  const ar = new Date(ahora - 3 * 3600000), dow = ar.getUTCDay(), hh = ar.getUTCHours(), mm = ar.getUTCMinutes();
  let franja = '';
  if ((dow === 6 || dow === 0) && hh === 21) franja = dow === 6 ? 'sab' : 'dom';
  else if (dow === 1 && ((hh === 7 && mm >= 30) || (hh === 8 && mm < 30))) franja = 'lun';
  if (!franja) return;
  const dias = dow === 6 ? 2 : (dow === 0 ? 1 : 0);
  const lun = new Date(Date.UTC(ar.getUTCFullYear(), ar.getUTCMonth(), ar.getUTCDate() + dias));
  const fecha = lun.getUTCDate() + '/' + (lun.getUTCMonth() + 1) + '/' + lun.getUTCFullYear();
  const clave = fecha + '|' + franja;
  if ((await kvGet(env, 'corte_autocarga_ult', '')) === clave) return;
  await kvSet(env, 'corte_autocarga_ult', clave);
  const r = await corteCargarTandaCompleta(env, { fecha, dryRun: false });
  try { await kvSet(env, 'corte_autocarga_res', JSON.stringify({ clave, at: new Date().toISOString(), nuevas: r.nuevas || 0, error: r.error || '', web: r.web || null }).slice(0, 2000)); } catch (_) {}
  // corteCargarTanda ya avisa lo que cargó desde la planilla; acá, lo de la web.
  const w = r.web || {};
  if (w.asignadas || w.sin_medir) {
    const t = 'Corte · tanda ' + fecha + ' (carga automática): ' + (w.asignadas ? w.asignadas + ' pieza' + (w.asignadas === 1 ? '' : 's') + ' web sumada' + (w.asignadas === 1 ? '' : 's') + (w.a_cortado ? ', ' + w.a_cortado + ' lista' + (w.a_cortado === 1 ? '' : 's') + ' para Neyen' : '') : 'sin piezas web nuevas') + (w.sin_medir ? '\n⚠ ' + w.sin_medir + ' diseño' + (w.sin_medir === 1 ? '' : 's') + ' web todavía sin medir (Emma)' : '');
    try { await precotizNotifyGaspar(env, t, { tipo: 'corte_tanda', prioridad: 'P3', clave: 'corte_autocarga:' + clave }); } catch (_) {}
  }
  if (r.error && !/no hay|sin piezas/i.test(r.error)) { try { await precotizNotifyGaspar(env, 'Corte · la carga automática de la tanda ' + fecha + ' falló: ' + r.error, { tipo: 'corte_tanda', prioridad: 'P2', clave: 'corte_autocarga_err:' + clave }); } catch (_) {} }
}
// ---- Endpoints públicos de la landing (sin sesión; antes del muro de /admin/) ----
//  GET  /corte/landing/config  → plazo, precios, insumos y video.
//  POST /corte/landing/cliente {telefono} → { conocido, tiene_direccion } (nada más: ni nombre ni dirección).
//  POST /corte/landing/foto    (el archivo en el cuerpo; image/* o PDF; máx 15 MB) → { key }.
//  POST /corte/landing/pedido  → crea el pedido (ver corteLandingPedido).
// Medición de la página del corte (aviso por WhatsApp del 16-oct: "avisame cuántos tocan el botón y van a la página").
// WhatsApp no informa los clics del botón, así que se cuenta desde la página: cada carga ('visita', IP hasheada) y cada
// teléfono que escriben ('telefono'): ahí se sabe QUÉ cliente de la lista entró. Nunca frena la página.
async function corteLandingVisita(env, request, tipo, tel) {
  try {
    await env.DB.prepare('CREATE TABLE IF NOT EXISTS corte_landing_visitas (id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT, tipo TEXT, ipk TEXT, tel TEXT, ua TEXT)').run();
    const ip = request.headers.get('CF-Connecting-IP') || '';
    const h = await crypto.subtle.digest('SHA-256', new TextEncoder().encode('corte:' + ip));
    const ipk = [...new Uint8Array(h)].slice(0, 6).map(b => b.toString(16).padStart(2, '0')).join('');
    const ua = String(request.headers.get('User-Agent') || '');
    const uaCorto = (/whatsapp/i.test(ua) ? 'wa ' : '') + (/android/i.test(ua) ? 'android' : /iphone|ipad/i.test(ua) ? 'ios' : /windows|macintosh/i.test(ua) ? 'pc' : 'otro');
    await env.DB.prepare('INSERT INTO corte_landing_visitas (ts, tipo, ipk, tel, ua) VALUES (?, ?, ?, ?, ?)').bind(new Date().toISOString(), tipo, ipk, tel || '', uaCorto).run();
  } catch (_) {}
}
// Números del aviso: enviados, respondieron, visitas a la página, clientes de la lista que pusieron su número, pedidos.
async function corteWebStats(env) {
  const kind = await kvGet(env, 'corte_web_bc_kind', '');
  if (!kind) return { ok: false, error: 'no hay aviso activo (kv corte_web_bc_kind)' };
  const desde = await kvGet(env, 'corte_web_bc_desde', '') || '2026-10-16T00:00:00Z';
  const q1 = async (sql, ...a) => { try { return await env.DB.prepare(sql).bind(...a).first(); } catch (_) { return null; } };
  const env_ = await q1("SELECT SUM(status = 'sent') AS enviados, SUM(status = 'failed') AS fallidos, SUM(status IN ('queued', 'sending')) AS en_cola, COUNT(*) AS total FROM wa_autoreply_log WHERE kind = ?", kind);
  const resp = await q1("SELECT COUNT(DISTINCT m.phone) AS n FROM wa_messages m JOIN wa_autoreply_log a ON a.phone = m.phone AND a.kind = ? AND a.status = 'sent' WHERE m.direction = 'inbound' AND m.ts >= a.sent_at AND m.msg_type NOT IN ('status', 'reaction')", kind);
  const vis = await q1("SELECT COUNT(*) AS visitas, COUNT(DISTINCT ipk) AS unicos FROM corte_landing_visitas WHERE tipo = 'visita' AND ts >= ?", desde);
  const tels = await q1("SELECT COUNT(DISTINCT v.tel) AS de_lista FROM corte_landing_visitas v JOIN wa_autoreply_log a ON substr(a.phone, -10) = substr(v.tel, -10) AND a.kind = ? WHERE v.tipo = 'telefono' AND v.ts >= ?", kind, desde);
  const telsTot = await q1("SELECT COUNT(DISTINCT tel) AS n FROM corte_landing_visitas WHERE tipo = 'telefono' AND ts >= ?", desde);
  let quienes = [];
  try { quienes = ((await env.DB.prepare("SELECT DISTINCT a.sender_name AS nombre FROM corte_landing_visitas v JOIN wa_autoreply_log a ON substr(a.phone, -10) = substr(v.tel, -10) AND a.kind = ? WHERE v.tipo = 'telefono' AND v.ts >= ? LIMIT 30").bind(kind, desde).all()).results || []).map(r => r.nombre).filter(Boolean); } catch (_) {}
  const ped = await q1("SELECT COUNT(*) AS n FROM corte_landing_envios WHERE IFNULL(prueba, 0) = 0 AND created_at >= ?", desde);
  return { ok: true, kind, desde, enviados: Number(env_ && env_.enviados) || 0, fallidos: Number(env_ && env_.fallidos) || 0, en_cola: Number(env_ && env_.en_cola) || 0,
    respondieron: Number(resp && resp.n) || 0, visitas: Number(vis && vis.visitas) || 0, visitantes: Number(vis && vis.unicos) || 0,
    pusieron_numero: Number(telsTot && telsTot.n) || 0, de_la_lista: Number(tels && tels.de_lista) || 0, quienes, pedidos: Number(ped && ped.n) || 0 };
}
function corteWebStatsTexto(st) {
  return `📊 Aviso del sitio del corte: enviados ${st.enviados}${st.fallidos ? ' (' + st.fallidos + ' no llegaron)' : ''}${st.en_cola ? ', ' + st.en_cola + ' en cola' : ''}. Respondieron ${st.respondieron}. Página: ${st.visitas} visitas (${st.visitantes} personas distintas). Pusieron su número ${st.pusieron_numero} (${st.de_la_lista} de la lista${st.quienes.length ? ': ' + st.quienes.slice(0, 12).join(', ') + (st.quienes.length > 12 ? '…' : '') : ''}). Pedidos por la página: ${st.pedidos}.`;
}
// Resúmenes automáticos a Gaspar en los horarios de kv corte_web_resumenes (JSON de ISO). Cada uno sale una vez.
async function processCorteWebResumen(env) {
  try {
    let horas = []; try { horas = JSON.parse(await kvGet(env, 'corte_web_resumenes', '[]')) || []; } catch (_) {}
    const now = Date.now();
    for (const h of horas) {
      const t = Date.parse(h); if (!t || now < t || now - t > 6 * 3600 * 1000) continue;
      const k = 'corte_web_resumen_ok:' + h;
      if ((await kvGet(env, k, '')) === '1') continue;
      await kvSet(env, k, '1');
      const st = await corteWebStats(env); if (!st.ok) return;
      const txt = corteWebStatsTexto(st);
      await avisoInterno(env, { para: 'gaspar', tipo: 'corte_web_resumen', prioridad: 'P2', clave: k, texto: txt,
        legacy: () => avisoLanzamientoSendLegacy(env, AVISO_SLUGS_FIJOS.gaspar, txt), legacyDest: AVISO_SLUGS_FIJOS.gaspar });
    }
  } catch (_) {}
}
async function corteLandingRoute(request, env, ctx, url, path) {
  if (!env.DB) return json({ error: 'db' }, 500);
  const on = (await kvGet(env, 'corte_landing_on', '1')) === '1';
  if (request.method === 'GET' && path === '/corte/landing/config') {
    if (ctx && ctx.waitUntil) ctx.waitUntil(corteLandingVisita(env, request, 'visita', ''));
    const pl = corteLandingPlazo(), pr = await corteLandingPrecios(env);
    return json({
      ok: true, on, plazo: { lunes: pl.lunesCorto, viernes: pl.viernesCorto, estado: pl.estado },
      precio_m2: pr.m2, insumos: pr.insumos.map(x => ({ codigo: x.codigo, nombre: x.nombre, detalle: x.detalle, precio: x.precio, escala: x.escala || null, colores: x.colores || null })),
      video: await kvGet(env, 'corte_landing_video', ''), whatsapp: '5491133708544',
    });
  }
  if (request.method !== 'POST') return json({ error: 'not_found' }, 404);
  if (!on) return json({ error: 'cerrado', motivo: 'Por ahora los pedidos se toman por WhatsApp.' }, 503);
  if (path === '/corte/landing/cliente') {
    const rl = await corteLandingLimite(env, request, 'cli', 40);
    if (!rl.ok) return json({ error: 'limite', motivo: 'Demasiados intentos. Probá de nuevo en un rato.' }, 429);
    let body; try { body = await request.json(); } catch { body = {}; }
    const tel = corteTel(body.telefono);
    if (!tel) return json({ error: 'telefono', motivo: 'No reconocemos ese número. Escribilo con el código de área, por ejemplo 11 2345 6789 o 351 123 4567.' }, 400);
    if (ctx && ctx.waitUntil) ctx.waitUntil(corteLandingVisita(env, request, 'telefono', tel));
    const c = await corteLandingCliente(env, tel);
    // Con un teléfono registrado se devuelve el nombre para autocompletar (lo mismo que ve cualquiera que tenga ese número en
    // WhatsApp). Al revés (nombre → teléfono) NO: la página es pública y expondría los números de los clientes.
    return json({ ok: true, conocido: c.conocido, tiene_direccion: c.tieneDireccion, nombre: c.conocido ? corteLandingNombreLindo(c.nombreHoja || c.nombre) : '', telefono: corteTelFmt(tel) });
  }
  if (path === '/corte/landing/foto') {
    const rl = await corteLandingLimite(env, request, 'foto', 80);
    if (!rl.ok) return json({ error: 'limite', motivo: 'Demasiadas fotos seguidas. Probá de nuevo en un rato.' }, 429);
    if (!env.MEDIA) return json({ error: 'r2' }, 500);
    const ct = String(request.headers.get('Content-Type') || '').split(';')[0].trim().toLowerCase();
    const ext = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/heic': 'heic', 'image/heif': 'heif', 'application/pdf': 'pdf' }[ct];
    if (!ext) return json({ error: 'tipo', motivo: 'Subí una imagen (JPG o PNG) o un PDF.' }, 415);
    const max = 15 * 1024 * 1024;
    if ((parseInt(request.headers.get('Content-Length') || '0', 10) || 0) > max) return json({ error: 'grande', motivo: 'El archivo pesa más de 15 MB.' }, 413);
    const buf = await request.arrayBuffer();
    if (!buf.byteLength) return json({ error: 'vacio', motivo: 'El archivo llegó vacío.' }, 400);
    if (buf.byteLength > max) return json({ error: 'grande', motivo: 'El archivo pesa más de 15 MB.' }, 413);
    const b = new Uint8Array(buf.slice(0, 12)), asc = String.fromCharCode(...b);
    const firmaOk = ext === 'jpg' ? (b[0] === 0xFF && b[1] === 0xD8) : ext === 'png' ? (b[0] === 0x89 && asc.slice(1, 4) === 'PNG') : ext === 'pdf' ? asc.startsWith('%PDF') : ext === 'webp' ? (asc.startsWith('RIFF') && asc.slice(8, 12) === 'WEBP') : asc.slice(4, 8) === 'ftyp';
    if (!firmaOk) return json({ error: 'tipo', motivo: 'El archivo no parece una imagen o un PDF.' }, 415);
    const key = CORTE_LANDING_PREFIX + new Date().toISOString().slice(0, 7) + '/' + crypto.randomUUID() + '.' + ext;
    try { await env.MEDIA.put(key, buf, { httpMetadata: { contentType: ct } }); } catch (_) { return json({ error: 'r2', motivo: 'No se pudo guardar el archivo. Probá de nuevo.' }, 500); }
    return json({ ok: true, key });
  }
  if (path === '/corte/landing/pedido') {
    const rl = await corteLandingLimite(env, request, 'ped', 12);
    if (!rl.ok) return json({ error: 'limite', motivo: 'Demasiados pedidos seguidos. Si necesitás ayuda, escribinos por WhatsApp.' }, 429);
    let body; try { body = await request.json(); } catch { body = {}; }
    // Modo prueba: solo con la sesión de Gaspar (las piezas quedan en estado 'prueba', fuera de todas las colas).
    let prueba = false;
    if (url.searchParams.get('prueba') === '1') {
      const s = await getSession(env, request);
      if (!s || (await getSessionRole(env, s.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
      prueba = true;
    }
    return json(...(await corteLandingPedido(env, body, { prueba, ipHash: rl.ipHash })));
  }
  return json({ error: 'not_found' }, 404);
}
// Crea el pedido de la landing. → [cuerpo, status] para json().
async function corteLandingPedido(env, body, { prueba = false, ipHash = '' } = {}) {
  if (!(await ensureCorteLandingSchema(env))) return [{ error: 'db', motivo: 'No pudimos guardar el pedido. Probá de nuevo en un momento.' }, 500];
  const err = (motivo, campo) => [{ error: 'datos', motivo, campo: campo || '' }, 400];
  if (String(body.hp || '').trim() || (+body.ms > 0 && +body.ms < 6000)) return [{ ok: true, lunes: corteLandingPlazo().lunesCorto, disenos: 0 }, 200]; // bot: se le dice que sí y no se guarda
  const tel = corteTel(body.telefono);
  if (!tel) return err('No reconocemos ese número de WhatsApp. Escribilo con el código de área, por ejemplo 11 2345 6789 o 351 123 4567.', 'telefono');
  const nombre = corteLandingNombrePropio(body.nombre);
  if (nombre.length < 3) return err('Escribí tu nombre y apellido.', 'nombre');
  const entrega = body.entrega === 'envio' ? 'envio' : (body.entrega === 'retira' ? 'retira' : '');
  if (!entrega) return err('Elegí si lo retirás en el taller o va por envío.', 'entrega');
  if (body.acepta !== true) return err('Confirmá que entendés cómo se calcula el precio final.', 'acepta');
  const pr = await corteLandingPrecios(env);
  // Diseños.
  const dIn = Array.isArray(body.disenos) ? body.disenos : [];
  if (dIn.length > 25) return err('Son muchos diseños para un solo pedido: mandalos en dos.');
  const disenos = [];
  for (let i = 0; i < dIn.length; i++) {
    const d = dIn[i] || {}, n = i + 1;
    const foto = String(d.foto_key || '');
    if (!foto.startsWith(CORTE_LANDING_PREFIX) || foto.includes('..') || foto.length > 120) return err('Falta la foto del diseño ' + n + '.', 'diseno' + n);
    const dn = corteLandingTxt(d.nombre, 60);
    if (!dn) return err('Ponele un nombre al diseño ' + n + '.', 'diseno' + n);
    const an = corteLandingCm(d.ancho), al = corteLandingCm(d.alto);
    if (!(an >= 1 && an <= 400 && al >= 1 && al <= 400)) return err('Revisá la medida del diseño ' + n + ' (ancho y alto en centímetros).', 'diseno' + n);
    const cant = Math.max(1, Math.min(10, parseInt(d.cantidad, 10) || 1)); // la planilla de Emma acepta 1 a 10
    disenos.push({ foto, nombre: dn, ancho: an, alto: al, cantidad: cant, aclaraciones: corteLandingTxt(d.aclaraciones, 300) });
  }
  // Insumos.
  const iIn = Array.isArray(body.insumos) ? body.insumos : [];
  const insumos = [];
  for (const it of iIn.slice(0, 10)) {
    const def = pr.insumos.find(x => x.codigo === String((it || {}).codigo || ''));
    const cant = Math.max(0, Math.min(50, parseInt((it || {}).cantidad, 10) || 0));
    if (!def || !cant) continue;
    const color = def.colores ? (def.colores.includes(String(it.color || '')) ? String(it.color) : def.colores[0]) : '';
    insumos.push({ codigo: def.codigo, cantidad: cant, color, precio: corteLandingPrecioUnit(def, cant), nombre: def.nombre + (color ? ' ' + color : '') });
  }
  if (!disenos.length && !insumos.length) return err('Sumá al menos un diseño.', 'disenos');
  // Las fotos tienen que existir (subidas por la propia landing).
  for (const d of disenos) { let h = null; try { h = await env.MEDIA.head(d.foto); } catch (_) {} if (!h) return err('Una de las fotos no se subió bien. Volvé a elegirla.'); }
  // Cliente.
  const cli = await corteLandingCliente(env, tel);
  const limpio = o => { const x = {}; ['dni', 'calle', 'localidad', 'provincia', 'cp', 'recibe'].forEach(k => { const v = corteLandingTxt((o || {})[k], k === 'calle' ? 120 : 60); if (v) x[k] = v; }); if (x.dni) x.dni = x.dni.replace(/\D/g, ''); if (x.cp) x.cp = x.cp.toUpperCase(); return x; };
  let nuevo = null, dir = null;
  if (!cli.conocido) {
    nuevo = limpio(body.nuevo);
    if (!/^\d{7,9}$/.test(nuevo.dni || '')) return err('Tu DNI (solo números) para registrarte como cliente.', 'dni');
    if (entrega === 'envio' && !(nuevo.calle && nuevo.localidad && nuevo.provincia && nuevo.cp)) return err('Completá la dirección de envío: calle y número, localidad, provincia y código postal.', 'direccion');
  } else if (entrega === 'envio') {
    const d = limpio(body.dir);
    if (d.calle) { if (!(d.localidad && d.provincia && d.cp)) return err('Completá la dirección nueva: calle y número, localidad, provincia y código postal.', 'direccion'); dir = d; }
    else if (!cli.tieneDireccion) return err('No tenemos tu dirección de envío: completala abajo.', 'direccion');
  }
  const pl = corteLandingPlazo();
  const nombreHoja = cli.conocido ? (cli.nombreHoja || nombre) : nombre;
  const estimado = Math.round(disenos.reduce((s, d) => s + (d.ancho / 100) * (d.alto / 100) * pr.m2 * d.cantidad, 0) + insumos.reduce((s, x) => s + x.precio * x.cantidad, 0));
  // Doble envío (doble toque, red lenta): mismo pedido del mismo teléfono en los últimos 30 min → se devuelve el anterior.
  const huella = (await sha256hex(JSON.stringify([tel, entrega, disenos.map(d => [d.foto, d.nombre, d.ancho, d.alto, d.cantidad]), insumos.map(x => [x.codigo, x.cantidad, x.color])]))).slice(0, 32);
  try {
    const prev = await env.DB.prepare("SELECT id, n_disenos, hoja_fecha FROM corte_landing_envios WHERE telefono=? AND huella=? AND created_at > ? ORDER BY id DESC LIMIT 1").bind(tel, huella, new Date(Date.now() - 30 * 60000).toISOString()).first();
    if (prev) return [{ ok: true, id: prev.id, repetido: true, lunes: pl.lunesCorto, estado: pl.estado, disenos: prev.n_disenos, insumos: insumos.length, estimado, telefono: corteTelFmt(tel) }, 200];
  } catch (_) {}
  const nowIso = new Date().toISOString();
  const datosJson = JSON.stringify({ nuevo: nuevo || undefined, dir: dir || undefined });
  let envioId = null;
  try {
    const r = await env.DB.prepare("INSERT INTO corte_landing_envios (created_at, telefono, nombre, nombre_hoja, nuevo, entrega, datos_json, insumos_json, n_disenos, estimado, hoja_fecha, plazo_estado, huella, ip_hash, prueba) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id")
      .bind(nowIso, tel, nombre, nombreHoja, cli.conocido ? 0 : 1, entrega, datosJson, JSON.stringify(insumos), disenos.length, estimado, pl.lunes, pl.estado, huella, ipHash, prueba ? 1 : 0).first();
    envioId = r && r.id;
  } catch (e) { return [{ error: 'db', motivo: 'No pudimos guardar el pedido. Probá de nuevo en un momento.' }, 500]; }
  // Ficha del cliente nuevo (las planillas, cuando se escribe su primera fila).
  let alumnoId = cli.alumnoId;
  if (!cli.conocido && !prueba) {
    try {
      const datos = corteLandingDatosTxt(nombre, nuevo, entrega);
      const a = await env.DB.prepare("INSERT INTO corte_alumnos (nombre, telefono, datos_envio, direccion, provincia, cp, dni, origen, activo, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, 'landing', 1, ?, ?) RETURNING id")
        .bind(nombre, tel, datos, nuevo.calle ? nuevo.calle + (nuevo.localidad ? ', ' + nuevo.localidad : '') : '', nuevo.provincia || '', nuevo.cp || '', nuevo.dni || '', nowIso, nowIso).first();
      alumnoId = a && a.id;
    } catch (_) {}
    if (corteTokens(nombre).length >= 2) { try { await env.DB.prepare("INSERT INTO corte_tel_override (nombre_norm, nombre, telefono, created_by, created_at) VALUES (?, ?, ?, 'landing', ?) ON CONFLICT(nombre_norm) DO NOTHING").bind(corteNormNombre(nombre), nombre, tel, nowIso).run(); } catch (_) {} }
  }
  // Piezas: diseños 'pedido' (Emma), insumos 'pedido' con precio (Emma no los ve). Sin tanda hasta la carga.
  const estado = prueba ? 'prueba' : 'pedido';
  const ins = (vals) => env.DB.prepare("INSERT INTO corte_pedidos (alumno_id, telefono, cliente_nombre, hoja_cliente, hoja_fecha, diseno_nombre, aclaraciones, foto_key, medida_declarada, cantidad, producto, precio, estado, estado_pago, entrega, entrega_manual, origen, tanda_id, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'pendiente', ?, 1, 'landing', NULL, ?, ?) RETURNING id").bind(...vals);
  const stmts = [
    ...disenos.map(d => ins([alumnoId || null, tel, nombreHoja, nombreHoja, pl.lunes, d.nombre, d.aclaraciones, d.foto, `ancho ${String(d.ancho).replace('.', ',')} × alto ${String(d.alto).replace('.', ',')} cm`, d.cantidad, 'TRANS', null, estado, entrega, nowIso, nowIso])),
    ...insumos.flatMap(x => { const partes = []; for (let q = x.cantidad; q > 0; q -= 10) partes.push(Math.min(10, q)); return partes.map(c => ins([alumnoId || null, tel, nombreHoja, nombreHoja, pl.lunes, x.nombre, x.color, null, '', c, x.codigo, x.precio * c, estado, entrega, nowIso, nowIso])); }),
  ];
  let ids = [];
  try { ids = (await env.DB.batch(stmts)).map(r => r.results && r.results[0] && r.results[0].id).filter(Boolean); }
  catch (e) {
    try { await env.DB.prepare("DELETE FROM corte_landing_envios WHERE id=?").bind(envioId).run(); } catch (_) {}
    return [{ error: 'db', motivo: 'No pudimos guardar el pedido. Probá de nuevo en un momento.' }, 500];
  }
  try { await env.DB.prepare("UPDATE corte_landing_envios SET piezas_ids=? WHERE id=?").bind(ids.join(','), envioId).run(); } catch (_) {}
  // Aviso al momento: solo el cliente nuevo (lo demás va en el resumen del sábado).
  if (!cli.conocido && !prueba) {
    // ¿Ya era cliente con otro número? (nombre igual a uno registrado). Solo para Gaspar: la página nunca muestra teléfonos.
    let otroNumero = '';
    try {
      const l = await corteLandingLtv(env);
      const m = l && l.ok ? l.rows.filter(r => r.tel && r.tel !== tel && corteMismaPersona(r.nombre, nombre)).slice(0, 2) : [];
      if (m.length) otroNumero = '\nOjo: el nombre coincide con ' + m.map(r => r.nombre + ' (…' + r.tel.slice(-4) + ')').join(' y ') + ', registrado con otro número. Si cambió de número, avisame y lo unifico.';
    } catch (_) {}
    const t = 'Corte · cliente nuevo por la web: ' + nombre + ' (…' + tel.slice(-4) + ')' + otroNumero + '\n' + (disenos.length ? disenos.length + ' diseño' + (disenos.length === 1 ? '' : 's') : '') + (insumos.length ? (disenos.length ? ' + ' : '') + insumos.length + ' insumo' + (insumos.length === 1 ? '' : 's') : '') + ' · ' + (entrega === 'envio' ? 'envío a ' + [nuevo.localidad, nuevo.provincia].filter(Boolean).join(', ') : 'retira') + ' · tanda del lunes ' + pl.lunesCorto + '\nLo sumo solo a LTV y a Clientes cuando Emma mida su primer diseño.';
    try { await precotizNotifyGaspar(env, t, { tipo: 'corte_landing_nuevo', prioridad: 'P2', clave: 'corte_landing_nuevo:' + envioId, refPhone: tel }); } catch (_) {}
  }
  return [{ ok: true, id: envioId, lunes: pl.lunesCorto, estado: pl.estado, disenos: disenos.length, insumos: insumos.length, estimado, telefono: corteTelFmt(tel) }, 200];
}
function corteEntregaCambiosTxt(cambios) {
  return 'Corte: actualicé la entrega desde la planilla de cortes:\n' + cambios.map(c => `· ${c.cliente} (${c.tanda}): ${c.de} → ${c.a}${c.ya_embalado ? ' ⚠ YA ESTABA EMBALADO, avisale a Neyen' : ''}`).join('\n');
}
// Sincroniza la ENTREGA de las piezas recientes (no despachadas) con la planilla de cortes, por la fecha de la hoja
// de cada pieza (hoja_fecha) y su nombre original (hoja_cliente). La planilla es la ÚNICA fuente: en el CRM no se
// cambia a mano. notify → avisa a Gaspar si cambió algo (sobre todo si ya estaba embalado).
async function corteSyncEntrega(env, { soloTandaId = 0, notify = false } = {}) {
  await ensureCorteHojaSchema(env);
  // entrega_manual=1 (el admin la cambió a mano): la planilla ya no la pisa. "Retiró" NO la pone: el estado 'entregado' ya
  // la deja afuera, y si se deshace la pieza tiene que volver a seguir la planilla. Si el esquema nuevo no está, la columna
  // no existe y no hay piezas manuales → sin filtro.
  const manualOk = await ensureCorteDespachoSchema(env);
  let rows = [];
  // Solo la tanda EN CURSO (piezas de los últimos 8 días): las anteriores ya salieron aunque sigan "embalado" (nadie
  // las marca despachadas) y tocarlas mandaría avisos falsos de "avisale a Neyen".
  try { rows = (await env.DB.prepare("SELECT id, cliente_nombre, hoja_cliente, hoja_fecha, entrega, estado FROM corte_pedidos WHERE IFNULL(producto,'')!='NEON' AND hoja_fecha IS NOT NULL AND hoja_fecha!='' AND estado NOT IN ('despachado','entregado')" + (manualOk ? " AND IFNULL(entrega_manual,0)=0" : "") + " AND " + (soloTandaId ? "tanda_id=?" : "created_at > ?")).bind(soloTandaId ? soloTandaId : new Date(Date.now() - 8 * 86400000).toISOString()).all()).results || []; } catch (_) {}
  if (!rows.length) return { ok: true, cambios: [], revisadas: 0 };
  const ent = await corteEntregaHoja(env);
  if (!ent.ok) return { error: ent.error };
  const cambios = []; const nowIso = new Date().toISOString(); const grupos = {};
  for (const p of rows) {
    const want = (ent.byFecha[p.hoja_fecha] || {})[corteNormNombre(p.hoja_cliente || p.cliente_nombre)];
    if (!want || (p.entrega || '') === want) continue;
    const gk = p.hoja_fecha + '|' + p.cliente_nombre;
    const g = (grupos[gk] = grupos[gk] || { tanda: p.hoja_fecha, cliente: p.cliente_nombre, de: p.entrega || 'sin definir', a: want, ids: [], ya_embalado: false });
    g.ids.push(p.id); if (p.estado === 'embalado') g.ya_embalado = true;
  }
  for (const g of Object.values(grupos)) {
    // Las condiciones del SELECT se repiten en el UPDATE: entre la lectura y acá pasan segundos (lectura de la planilla) y
    // en ese rato el admin pudo fijar la entrega a mano, Neyen marcar "Retiró" o logística despachar. Solo se informa lo
    // que de verdad cambió.
    try {
      const u = await env.DB.prepare("UPDATE corte_pedidos SET entrega=?, updated_at=? WHERE id IN (" + g.ids.map(() => '?').join(',') + ") AND estado NOT IN ('despachado','entregado')" + (manualOk ? " AND IFNULL(entrega_manual,0)=0" : "")).bind(g.a, nowIso, ...g.ids).run();
      const ch = (u && u.meta && u.meta.changes) || 0;
      if (ch) cambios.push({ tanda: g.tanda, cliente: g.cliente, de: g.de, a: g.a, piezas: ch, ya_embalado: g.ya_embalado });
    } catch (_) {}
  }
  if (notify && cambios.length) { try { await precotizNotifyGaspar(env, corteEntregaCambiosTxt(cambios), { tipo: 'corte_entrega', prioridad: 'P3' }); } catch (_) {} }
  return { ok: true, cambios, revisadas: rows.length };
}
// Cron: cada 60 min (8 a 21 hs AR) sincroniza la entrega y avisa a Gaspar si cambió algo.
async function processCorteEntregaSync(env) {
  try {
    if ((await kvGet(env, 'corte_entrega_sync_on', '1')) !== '1') return;
    const h = new Date(Date.now() - 3 * 3600 * 1000).getUTCHours(); if (h < 8 || h > 21) return;
    const nowL = new Date().toISOString(), stale = new Date(Date.now() - 60 * 60 * 1000).toISOString();
    let lk = null;
    try { lk = await env.DB.prepare("INSERT INTO kv_cache (k, v, updated_at) VALUES ('corte_entrega_sync_at', ?, ?) ON CONFLICT(k) DO UPDATE SET v=excluded.v, updated_at=excluded.updated_at WHERE kv_cache.updated_at < ? RETURNING k").bind(nowL, nowL, stale).first(); } catch (_) {}
    if (!lk) return; // ya corrió en la última hora
    await corteSyncEntrega(env, { notify: true });
  } catch (_) {}
}
// ===== LOGÍSTICA (usuario externo: Siempre a Tiempo) =====
// Cada lunes, con la tanda cargada, logística ve los paquetes que van por ENVÍO (cliente, teléfono, dirección y
// tamaño) para contactar a los clientes mientras Neyen embala, y el martes solo los carga en el camión.
// Paquete = todas las piezas de UN cliente en UNA tanda. Clave = teléfono, o "n:"+nombre si no tiene.
function corteClaveCliente(p) { return p.telefono ? String(p.telefono) : 'n:' + corteNormNombre(p.cliente_nombre); }
let _cortePaqSchemaOk = false;
async function ensureCortePaquetesSchema(env) {
  if (_cortePaqSchemaOk) return;
  try { await env.DB.prepare("CREATE TABLE IF NOT EXISTS corte_paquetes (tanda_id INTEGER NOT NULL, cliente_key TEXT NOT NULL, largo REAL, ancho REAL, alto REAL, peso REAL, bultos INTEGER, medido_por TEXT, medido_at TEXT, contactado INTEGER DEFAULT 0, contactado_at TEXT, contactado_por TEXT, cargado INTEGER DEFAULT 0, cargado_at TEXT, cargado_por TEXT, nota TEXT, nota_at TEXT, nota_por TEXT, PRIMARY KEY (tanda_id, cliente_key))").run(); _cortePaqSchemaOk = true; } catch (_) {}
}
// Medida de una pieza en cm: la real (ancho_real/alto_real) o la declarada ("60x44").
function corteMedidaPieza(p) {
  let a = Number(p.ancho_real) || 0, h = Number(p.alto_real) || 0;
  if (!(a > 0 && h > 0)) { const m = String(p.medida_declarada || '').match(/(\d+(?:[.,]\d+)?)\s*[x×*]\s*(\d+(?:[.,]\d+)?)/i); if (m) { a = parseFloat(m[1].replace(',', '.')); h = parseFloat(m[2].replace(',', '.')); } }
  return (a > 0 && h > 0) ? { a, h } : null;
}
// Paquete ESTIMADO a partir de las piezas (para el lunes temprano, antes de que Neyen embale y mida):
//  · largo/ancho = la pieza más grande + 6 cm de embalaje; alto = 0,8 cm por pieza (acrílico 3 mm + protección) + 4 cm.
//  · peso = acrílico 3 mm (1,19 g/cm³) + cartón/film; cada rollo de cable ~1,2 kg (+8 cm de alto), fuentes ~0,35 kg.
function corteEstimarPaquete(items) {
  let L = 0, W = 0, piezas = 0, kg = 0, cable = 0, fuentes = 0, otros = 0;
  for (const p of items) {
    const q = Math.max(1, parseInt(p.cantidad, 10) || 1);
    const m = corteMedidaPieza(p);
    if (m) {
      L = Math.max(L, Math.max(m.a, m.h)); W = Math.max(W, Math.min(m.a, m.h)); piezas += q;
      kg += (m.a * m.h * 0.3 * 1.19 / 1000) * q;
    } else {
      const pr = String(p.producto || '') + ' ' + String(p.diseno_nombre || '');
      if (/cable|rollo/i.test(pr)) { cable += q; kg += 1.2 * q; }
      else if (/fuen|fuet/i.test(pr)) { fuentes += q; kg += 0.35 * q; }
      else { otros += q; kg += 0.5 * q; }
    }
  }
  let largo = piezas ? L + 6 : 30, ancho = piezas ? W + 6 : 25, alto = piezas ? piezas * 0.8 + 4 : 0;
  alto += cable * 8 + Math.ceil(fuentes / 4) * 5 + otros * 5;
  if (!piezas) alto = Math.max(alto, 10);
  kg += 0.4 + (largo * ancho / 10000) * 0.6;
  return { largo: Math.round(largo), ancho: Math.round(ancho), alto: Math.round(alto), peso: Math.round(kg * 10) / 10, bultos: 1, piezas, cable, fuentes, pieza_mas_larga: Math.round(L) };
}
// ===== DESPACHO DEL CORTE (oct-2026): circuito cerrado lunes contactar / martes cargar =====
// Decisiones de Gaspar: NUNCA se despacha con deuda (en NINGUNA tanda del cliente); el lunes logística (Siempre a Tiempo)
// contacta a todos (también a los impagos) y cobra el envío desde SU WhatsApp; el martes carga al camión SOLO lo que tiene
// pedido pagado + envío pagado. Cargar = las piezas pasan a 'despachado' (antes nadie lo hacía: las tandas viejas quedaban
// 'embalado'). Columnas/tablas nuevas (migrations/045_corte_despacho.sql; acá también en caliente, idempotente):
//  · corte_pedidos: despachado_at, entregado_at, entregado_por, entrega_manual, pago_metodo, pago_manual_por, pago_manual_at, pago_nota
//  · corte_paquetes: numero (N° estable de la semana, único por tanda), contacto_estado ('' | escrito | no_contesta | listo),
//    contacto_at, intentos, envio_pagado(+_at/_por), despachado_at, aviso_at (freno de "Avisar a Neon"), aviso_nc_at (aviso único "no contesta ×3")
//  · logistica_log: historial de acciones de logística (no se pisa).
let _corteDespSchemaOk = false;
async function ensureCorteDespachoSchema(env) {
  if (_corteDespSchemaOk) return true;
  // Camino rápido (12-oct): si todo ya existe, UNA sola ida a la base. Antes cada isolate nuevo (pasa seguido) corría ~25
  // ALTER/CREATE en fila que fallaban por "ya existe": 5-10 s de espera en cada carga de logística/etiquetas.
  try {
    const rs = await env.DB.batch([
      env.DB.prepare('SELECT despachado_at, entregado_at, entregado_por, entrega_manual, pago_metodo, pago_manual_por, pago_manual_at, pago_nota FROM corte_pedidos LIMIT 0'),
      env.DB.prepare('SELECT numero, contacto_estado, contacto_at, intentos, envio_pagado, envio_pagado_at, envio_pagado_por, despachado_at, aviso_at, aviso_nc_at FROM corte_paquetes LIMIT 0'),
      env.DB.prepare('SELECT id, tanda_id, cliente_key, ts, accion, nota, operador, usuario FROM logistica_log LIMIT 0'),
      env.DB.prepare("SELECT COUNT(*) AS n FROM sqlite_master WHERE type='index' AND name IN ('uq_corte_paquetes_numero','idx_logistica_log_paq','idx_corte_pedidos_pago')"),
    ]);
    if (((rs[3] && rs[3].results && rs[3].results[0]) || {}).n === 3) { _corteDespSchemaOk = true; return true; }
  } catch (_) {} // falta algo → camino lento de abajo (crea lo que falte)
  await ensureCortePaquetesSchema(env);
  for (const c of ['despachado_at TEXT', 'entregado_at TEXT', 'entregado_por TEXT', 'entrega_manual INTEGER DEFAULT 0', 'pago_metodo TEXT', 'pago_manual_por TEXT', 'pago_manual_at TEXT', 'pago_nota TEXT']) {
    try { await env.DB.prepare('ALTER TABLE corte_pedidos ADD COLUMN ' + c).run(); } catch (_) {} // tira si ya existe
  }
  for (const c of ['numero INTEGER', 'contacto_estado TEXT', 'contacto_at TEXT', 'intentos INTEGER DEFAULT 0', 'envio_pagado INTEGER DEFAULT 0', 'envio_pagado_at TEXT', 'envio_pagado_por TEXT', 'despachado_at TEXT', 'aviso_at TEXT', 'aviso_nc_at TEXT']) {
    try { await env.DB.prepare('ALTER TABLE corte_paquetes ADD COLUMN ' + c).run(); } catch (_) {}
  }
  try { await env.DB.prepare('CREATE UNIQUE INDEX IF NOT EXISTS uq_corte_paquetes_numero ON corte_paquetes(tanda_id, numero) WHERE numero IS NOT NULL').run(); } catch (_) {}
  try { await env.DB.prepare('CREATE TABLE IF NOT EXISTS logistica_log (id INTEGER PRIMARY KEY AUTOINCREMENT, tanda_id INTEGER, cliente_key TEXT, ts TEXT, accion TEXT, nota TEXT, operador TEXT, usuario TEXT)').run(); } catch (_) {}
  try { await env.DB.prepare('ALTER TABLE logistica_log ADD COLUMN usuario TEXT').run(); } catch (_) {} // tablas creadas antes de la columna
  try { await env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_logistica_log_paq ON logistica_log(tanda_id, cliente_key)').run(); } catch (_) {}
  try { await env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_corte_pedidos_pago ON corte_pedidos(estado_pago)').run(); } catch (_) {}
  // Memoizar SOLO si todo existe de verdad (un ALTER que falló por un corte transitorio no deja el isolate sin la feature).
  try {
    await env.DB.prepare('SELECT despachado_at, entregado_at, entregado_por, entrega_manual, pago_metodo, pago_manual_por, pago_manual_at, pago_nota FROM corte_pedidos LIMIT 0').all();
    await env.DB.prepare('SELECT numero, contacto_estado, contacto_at, intentos, envio_pagado, envio_pagado_at, envio_pagado_por, despachado_at, aviso_at, aviso_nc_at FROM corte_paquetes LIMIT 0').all();
    await env.DB.prepare('SELECT id, tanda_id, cliente_key, ts, accion, nota, operador, usuario FROM logistica_log LIMIT 0').all();
    _corteDespSchemaOk = true;
  } catch (_) {}
  return _corteDespSchemaOk;
}
// DEUDA (regla única para logística, retiro y pago manual): pieza de alumno (no neón), con precio > 0, sin pagar
// (pendiente/cobrando/parcial) y ya producida (las 'pedido'/'matriz_lista' de la semana que viene todavía no se cobraron:
// no pueden frenar un despacho). Las piezas en $0 NO son deuda. Cuenta CUALQUIER tanda del mismo cliente.
// PAGABLE (pago manual, spec 5): lo mismo SIN el filtro de etapa → el admin también puede marcar pagado un adelanto de
// piezas que todavía no se cortaron (el diálogo las muestra por semana y se destildan las que no).
const CORTE_PAGABLE_SQL = "IFNULL(producto,'TRANS')!='NEON' AND lower(IFNULL(cliente_nombre,''))!='neon' AND precio>0 AND estado_pago IN ('pendiente','cobrando','parcial')";
const CORTE_DEUDA_SQL = CORTE_PAGABLE_SQL + " AND IFNULL(estado,'pedido') NOT IN ('pedido','matriz_lista')";
// Claves de cliente (corteClaveCliente: teléfono, o 'n:'+nombre si no tiene) con deuda. Además, cada deuda CON teléfono
// suma 't:'+nombre normalizado: el mismo cliente puede tener una tanda cargada sin teléfono (LTV caído o todavía no estaba)
// y otra con teléfono, y la deuda de una tiene que frenar a la otra (ver corteTieneDeuda). null = no se pudo leer (el que
// llama lo trata como deuda: nunca despachar a ciegas).
async function corteDeudaKeys(env) {
  try {
    const s = new Set();
    ((await env.DB.prepare('SELECT DISTINCT telefono, cliente_nombre FROM corte_pedidos WHERE ' + CORTE_DEUDA_SQL).all()).results || []).forEach(r => {
      s.add(corteClaveCliente(r));
      const nn = corteNormNombre(r.cliente_nombre);
      if (r.telefono && nn) s.add('t:' + nn);
    });
    return s;
  }
  catch (_) { return null; }
}
// ¿El cliente (clave + nombre/s) tiene deuda? Por su clave y también por la otra clave posible del mismo nombre: con
// teléfono, la deuda cargada SIN teléfono a su nombre ('n:'); sin teléfono, la de su nombre CON teléfono ('t:'). Un
// homónimo puede frenar de más (lado seguro: nunca despachar con deuda). deuda null (no se pudo leer) = deuda.
function corteTieneDeuda(deuda, key, nombres) {
  if (!deuda) return true;
  if (deuda.has(key)) return true;
  const pre = String(key || '').startsWith('n:') ? 't:' : 'n:';
  return (Array.isArray(nombres) ? nombres : [nombres]).some(n => { const nn = corteNormNombre(n); return !!nn && deuda.has(pre + nn); });
}
// Un cliente en un body {telefono?, nombre?}: por teléfono si viene; si no, por nombre normalizado y SIN teléfono (misma
// clave que corteClaveCliente). El nombre se filtra en JS (corteNormNombre no existe en SQL).
function corteClienteSel(body) {
  const tel = String((body && body.telefono) || '').replace(/\D/g, '');
  if (tel) return { tel, key: tel, where: 'telefono=?', binds: [tel], match: () => true };
  const norm = corteNormNombre(body && body.nombre);
  if (!norm) return null;
  return { tel: '', key: 'n:' + norm, where: "(telefono IS NULL OR telefono='')", binds: [], match: p => corteNormNombre(p.cliente_nombre) === norm };
}
// Fechas AR: 'YYYY-MM-DD' (para "mismo día") y 'dd/mm' de un ISO.
function corteArYmd(iso) { const t = Date.parse(iso || ''); return isNaN(t) ? '' : new Date(t - 3 * 3600 * 1000).toISOString().slice(0, 10); }
function corteDdMm(iso) { const t = Date.parse(iso || ''); if (isNaN(t)) return ''; const d = new Date(t - 3 * 3600 * 1000); return String(d.getUTCDate()).padStart(2, '0') + '/' + String(d.getUTCMonth() + 1).padStart(2, '0'); }
// Martes de despacho de una tanda: el primer martes desde la fecha de corte (fecha_corte es el lunes → el día siguiente;
// las tandas viejas con fecha domingo → +2). Devuelve la Date a las 12:00 UTC del día, o null si la fecha no es válida.
function corteMartesDate(fechaCorte) { const f = corteFechaValida(fechaCorte); if (!f) return null; return new Date(f.date.getTime() + ((2 - f.date.getUTCDay() + 7) % 7) * 86400000); }
