  const uso = pred => vig.filter(r => r.tipo === 'uso' && pred(String(r.accion || ''))).length;
  const frenos = vig.filter(r => (r.tipo === 'uso' && r.accion === 'freno:impago') || (r.tipo === 'bloqueo' && r.accion === 'celda:enviado')).length;
