  const pend = info.filter(x => x.fuente.trim() && !x.iaOk).sort((a, b) => (+a.p.despachado - +b.p.despachado) || ((a.p.numero || 1e9) - (b.p.numero || 1e9))).slice(0, LOGI_DIR_LOTE);
