// ===== Analytics: funnel pre-cotización (carteles) =====
// Mide por mes (cohorte por PRIMER inbound del año, hora AR): leads nuevos, cuántos
// mandaron foto, cuántos medidas, cuántos recibieron presupuesto — y la cohorte
// "revivible" (últimos 60 días sin presupuesto, desglosada por qué dato falta).
// UN solo scan de wa_messages por query (agregación condicional, sin LIKE por el
// límite de D1) — para uso on-demand/cron, nunca en polls. Detección de presupuesto
// = la misma de producción (processPresupuestoFollowups) + los markers de plantilla.
async function analyticsPrecotizFunnel(env, url) {
  const desde = (url.searchParams.get('desde') || '2026-01-01') + 'T03:00:00Z'; // 00:00 AR
  const hoyMs = Date.now();
  const revDesde = new Date(hoyMs - 60 * 86400000).toISOString();
  const revHasta = new Date(hoyMs - 3 * 86400000).toISOString(); // 3 días de gracia (en curso)
  // per_phone: flags por teléfono en un solo scan. GLOB de medidas = aproximación
  // (el regex real vive en JS); excluye imágenes porque la descripción IA appendeada
  // ('[imagen] ...') mete números. Nota: acotar por ts hace que un cliente viejo que
  // vuelve cuente como nuevo — error aceptado, mismo criterio del análisis de mayo.
  const perPhone = (extraWhere) => `
    WITH per_phone AS (
      SELECT phone,
        CASE WHEN MAX(CASE WHEN channel='ig' THEN 1 ELSE 0 END)=1 THEN 'ig' ELSE 'wa' END AS canal,
        MIN(CASE WHEN direction='inbound'  AND msg_type!='status' THEN ts END) AS first_in_ts,
        MIN(CASE WHEN direction='outbound' AND msg_type!='status' THEN ts END) AS first_out_ts,
        MAX(CASE WHEN direction='inbound'  AND msg_type!='status' THEN ts END) AS last_in_ts,
        MAX(CASE WHEN direction='outbound' AND msg_type!='status' THEN ts END) AS last_out_ts,
        MAX(CASE WHEN direction='inbound' AND msg_type='image' THEN 1 ELSE 0 END) AS has_img,
        MAX(CASE WHEN direction='inbound' AND msg_type IN ('text','audio') AND (
              lower(body) GLOB '*[0-9]x[0-9]*'  OR lower(body) GLOB '*[0-9] x [0-9]*'
           OR lower(body) GLOB '*[0-9]x [0-9]*' OR lower(body) GLOB '*[0-9] x[0-9]*'
           OR lower(body) GLOB '*[0-9] por [0-9]*'
           OR lower(body) GLOB '*[0-9]cm*'      OR lower(body) GLOB '*[0-9] cm*'
           OR lower(body) GLOB '*[0-9] mts*'    OR lower(body) GLOB '*[0-9] metro*'
        ) THEN 1 ELSE 0 END) AS has_med,
        MAX(CASE WHEN direction='outbound' AND IFNULL(status,'')!='failed' AND ${_SC_QUOTE_SQL} THEN 1 ELSE 0 END) AS has_quote
      FROM wa_messages
      WHERE ts >= ?1 AND phone IS NOT NULL AND phone != ''
        AND phone NOT IN ('5491144366573','5491133708544') AND phone NOT IN (SELECT phone FROM wa_internal_phones)
      GROUP BY phone
    ),
    leads AS (
      SELECT p.*, strftime('%Y-%m', datetime(first_in_ts,'-3 hours')) AS mes
      FROM per_phone p
      WHERE first_in_ts IS NOT NULL
        AND (first_out_ts IS NULL OR first_in_ts <= first_out_ts)  -- inbound-first (excluye broadcasts nuestros)
        AND p.phone NOT IN (SELECT phone FROM wa_chats_summary WHERE inbox='cursos')  -- solo carteles
        ${extraWhere || ''}
    )`;
  const qMensual = perPhone('') + `
    SELECT mes, COUNT(*) AS nuevos,
      SUM(canal='wa') AS wa, SUM(canal='ig') AS ig,
      SUM(has_img) AS con_foto, SUM(has_med) AS con_medidas,
      SUM(has_img*has_med) AS con_ambas,
      SUM(has_quote) AS cotizados,
      SUM(CASE WHEN has_quote=0 AND has_img=1 AND has_med=1 THEN 1 ELSE 0 END) AS listos_sin_cotizar,
      SUM(CASE WHEN has_quote=0 AND has_img=0 AND has_med=0 THEN 1 ELSE 0 END) AS sin_datos_sin_cotizar
    FROM leads GROUP BY mes ORDER BY mes`;
  const qRevival = perPhone(`AND p.first_in_ts >= '${revDesde}' AND p.first_in_ts <= '${revHasta}'
        AND p.phone NOT IN (SELECT phone FROM wa_unreachable_phones)`) + `
    SELECT canal, COUNT(*) AS total,
      SUM(CASE WHEN has_img=0 AND has_med=0 THEN 1 ELSE 0 END) AS sin_datos,
      SUM(CASE WHEN has_img=1 AND has_med=0 THEN 1 ELSE 0 END) AS solo_foto,
      SUM(CASE WHEN has_img=0 AND has_med=1 THEN 1 ELSE 0 END) AS solo_medidas,
      SUM(CASE WHEN has_img=1 AND has_med=1 THEN 1 ELSE 0 END) AS datos_completos,
      SUM(CASE WHEN last_out_ts IS NULL OR last_in_ts > last_out_ts THEN 1 ELSE 0 END) AS ultima_palabra_del_cliente
    FROM leads WHERE has_quote=0 GROUP BY canal`;
  const qBriefs = `
    SELECT strftime('%Y-%m', datetime(created_at,'-3 hours')) AS mes,
      COUNT(*) AS creados,
      SUM(CASE WHEN estado='enviado' THEN 1 ELSE 0 END) AS enviados,
      SUM(CASE WHEN lower(origen_lead)='ig' THEN 1 ELSE 0 END) AS ig
    FROM briefs WHERE created_at >= ?1 GROUP BY mes ORDER BY mes`;
  const out = { desde: desde, revival_ventana: { desde: revDesde, hasta: revHasta } };
  try { out.mensual = (await env.DB.prepare(qMensual).bind(desde).all()).results || []; }
  catch (e) { out.mensual_error = String(e && e.message || e); }
  try { out.revival = (await env.DB.prepare(qRevival).bind(desde).all()).results || []; }
  catch (e) { out.revival_error = String(e && e.message || e); }
  try { out.briefs = (await env.DB.prepare(qBriefs).bind(desde).all()).results || []; }
  catch (e) { out.briefs_error = String(e && e.message || e); }
  return json(out);
}

// Alarma "💰 Sin cotizar": leads que mandaron foto Y medidas pero NO recibieron
// presupuesto tras +20hs. DINÁMICA — cada corrida (1) reconcilia etiquetas viejas,
// (2) DESTILDA a los que Joaco ya cotizó (actuó → sale de la lista), y (3) con addPass
// escanea y etiqueta los nuevos que cruzaron las 20hs. Tag-once via tabla sin_cotizar:
// un lead destildado a mano NO se re-etiqueta (evita falsas oportunidades repetidas).
const SIN_COTIZAR_LABEL_NAME = '💰 Sin cotizar';
const SIN_COTIZAR_LABEL_COLOR = '#22c55e';
// Un saliente cuenta como PRESUPUESTO si es el texto del cotizador o CUALQUIER plantilla presupuesto_*
// (detallado, _img, _img2, _img3, corporea, _v2_img…). Antes se listaban los nombres EXACTOS y al pasar a
// presupuesto_detallado_img3 / presupuesto_corporea_v2_img dejó de matchear: la etiqueta "Sin cotizar" no
// se sacaba y encima se le PONÍA a leads ya cotizados por plantilla (29-sep). Genérico = no se rompe con _img4.
// substr (no LIKE) porque '_' es comodín en LIKE. col = columna del body ('body' o 'm.body').
const _quoteSql = (col) => `(substr(${col},1,26)='Te comparto el presupuesto' OR substr(${col},1,26)='Te comparto la información' OR substr(${col},1,24)='[plantilla: presupuesto_')`;
const _SC_QUOTE_SQL = _quoteSql('body');
async function syncSinCotizar(env, opts = {}) {
  try { await env.DB.prepare("CREATE TABLE IF NOT EXISTS sin_cotizar (phone TEXT PRIMARY KEY, name TEXT, canal TEXT, quotable_since TEXT, created_at TEXT, quoted_at TEXT, escalated_at TEXT)").run(); } catch (_) {}
  try { await env.DB.prepare("ALTER TABLE sin_cotizar ADD COLUMN escalated_at TEXT").run(); } catch (_) {}
  const labelId = await ensureLabelId(env, SIN_COTIZAR_LABEL_NAME, SIN_COTIZAR_LABEL_COLOR);
  const nowIso = new Date().toISOString();
  let added = 0, removed = 0;

  // (1) RECONCILIAR: importá a sin_cotizar cualquier teléfono ya etiquetado que no esté
  // registrado (ej. el one-shot inicial), para que el destildado dinámico lo alcance.
  if (labelId) {
    try {
      await env.DB.prepare(
        "INSERT OR IGNORE INTO sin_cotizar (phone, name, canal, quotable_since, created_at) " +
        "SELECT cl.phone, IFNULL(s.contact_name,''), 'wa', cl.created_at, cl.created_at " +
        "FROM contact_labels cl LEFT JOIN wa_chats_summary s ON s.phone = cl.phone WHERE cl.label_id = ?"
      ).bind(labelId).run();
    } catch (_) {}
  }

  // (2) DESTILDAR a los que YA tienen presupuesto (barato: solo mira los etiquetados).
  try {
    const tagged = (await env.DB.prepare("SELECT phone FROM sin_cotizar WHERE quoted_at IS NULL").all()).results || [];
    const phones = tagged.map(r => String(r.phone).replace(/[^0-9]/g, '')).filter(Boolean);
    if (phones.length) {
      const inList = phones.map(p => `'${p}'`).join(',');
      const quoted = (await env.DB.prepare(
        // ts <= now-3min: el 'failed' de una plantilla llega asíncrono por webhook; sin margen, un presupuesto que
        // nunca llegó destildaba y seteaba quoted_at (tag-once → no se re-etiquetaba nunca más).
        `SELECT DISTINCT phone FROM wa_messages WHERE phone IN (${inList}) AND direction='outbound' AND IFNULL(status,'')!='failed' AND ts <= strftime('%Y-%m-%dT%H:%M:%fZ','now','-3 minutes') AND ${_SC_QUOTE_SQL}`
      ).all()).results || [];
      for (const q of quoted) {
        try {
          if (labelId) await env.DB.prepare("DELETE FROM contact_labels WHERE phone = ? AND label_id = ?").bind(q.phone, labelId).run();
          await env.DB.prepare("UPDATE sin_cotizar SET quoted_at = ? WHERE phone = ?").bind(nowIso, q.phone).run();
          removed++;
        } catch (_) {}
      }
    }
  } catch (_) {}

  // (3) ETIQUETAR NUEVOS (solo con addPass — es el scan pesado de wa_messages).
  // foto+medidas, sin presupuesto, +20hs desde que juntó AMBOS datos, alcanzable,
  // no cursos, no interno, inbound-first, primer contacto <60d. Tag-once (OR IGNORE).
  if (opts.addPass) {
    const desde60d = new Date(Date.now() - 60 * 86400000).toISOString();
    const umbral20h = new Date(Date.now() - 20 * 3600000).toISOString();
    const sql = `
      WITH per_phone AS (
        SELECT phone,
          CASE WHEN MAX(CASE WHEN channel='ig' THEN 1 ELSE 0 END)=1 THEN 'ig' ELSE 'wa' END AS canal,
          MIN(CASE WHEN direction='inbound'  AND msg_type!='status' THEN ts END) AS first_in_ts,
          MIN(CASE WHEN direction='outbound' AND msg_type!='status' THEN ts END) AS first_out_ts,
          MAX(CASE WHEN direction='inbound'  AND msg_type!='status' THEN ts END) AS last_in_ts,
          MIN(CASE WHEN direction='inbound' AND msg_type='image' THEN ts END) AS first_img_ts,
          MIN(CASE WHEN direction='inbound' AND msg_type IN ('text','audio') AND (
                lower(body) GLOB '*[0-9]x[0-9]*'  OR lower(body) GLOB '*[0-9] x [0-9]*'
             OR lower(body) GLOB '*[0-9]x [0-9]*' OR lower(body) GLOB '*[0-9] x[0-9]*'
             OR lower(body) GLOB '*[0-9] por [0-9]*'
             OR lower(body) GLOB '*[0-9]cm*'      OR lower(body) GLOB '*[0-9] cm*'
             OR lower(body) GLOB '*[0-9] mts*'    OR lower(body) GLOB '*[0-9] metro*'
          ) THEN ts END) AS first_med_ts,
          MAX(CASE WHEN direction='outbound' AND IFNULL(status,'')!='failed' AND ${_SC_QUOTE_SQL} THEN 1 ELSE 0 END) AS has_quote
        FROM wa_messages
        WHERE ts >= ?1 AND phone IS NOT NULL AND phone != ''
          AND phone NOT IN ('5491144366573','5491133708544') AND phone NOT IN (SELECT phone FROM wa_internal_phones)
        GROUP BY phone
      )
      SELECT p.phone, p.canal, p.last_in_ts, max(p.first_img_ts, p.first_med_ts) AS quotable_since, s.contact_name
      FROM per_phone p LEFT JOIN wa_chats_summary s ON s.phone = p.phone
      WHERE p.first_in_ts IS NOT NULL AND p.first_in_ts >= ?1
        AND (p.first_out_ts IS NULL OR p.first_in_ts <= p.first_out_ts)
        AND IFNULL(s.inbox,'general') != 'cursos'
        AND p.has_quote = 0 AND p.first_img_ts IS NOT NULL AND p.first_med_ts IS NOT NULL
        AND max(p.first_img_ts, p.first_med_ts) <= ?2
        AND p.phone NOT IN (SELECT phone FROM wa_unreachable_phones)
      ORDER BY p.last_in_ts DESC`;
    let rows = [];
    try { rows = (await env.DB.prepare(sql).bind(desde60d, umbral20h).all()).results || []; } catch (_) {}
    for (const r of rows) {
      try {
        const res = await env.DB.prepare("INSERT OR IGNORE INTO sin_cotizar (phone, name, canal, quotable_since, created_at) VALUES (?, ?, ?, ?, ?)")
          .bind(r.phone, r.contact_name || '', r.canal || 'wa', r.quotable_since || nowIso, nowIso).run();
        if (res.meta && res.meta.changes) {
          if (labelId && !(await labelSuppressed(env, r.phone, labelId))) await env.DB.prepare("INSERT OR IGNORE INTO contact_labels (phone, label_id, created_at) VALUES (?, ?, ?)").bind(r.phone, labelId, nowIso).run();
          added++;
        }
      } catch (_) {}
    }
  }

  // (4) ESTADO actual — fuente de verdad = contact_labels con esta etiqueta.
  let lista = [];
  try {
    lista = (await env.DB.prepare(
      "SELECT cl.phone, cl.created_at, s.contact_name AS name FROM contact_labels cl LEFT JOIN wa_chats_summary s ON s.phone = cl.phone WHERE cl.label_id = ? ORDER BY cl.created_at DESC"
    ).bind(labelId).all()).results || [];
  } catch (_) {}
  return {
    label: SIN_COTIZAR_LABEL_NAME, label_id: labelId,
    count: lista.length, etiquetados_nuevos: added, destildados: removed,
    max_created_at: lista[0] ? lista[0].created_at : null,
    nombres: lista.slice(0, 6).map(r => (r.name && r.name.trim()) ? r.name.trim() : ('+' + r.phone)),
    rows: lista
  };
}

// Escalación + auto-limpieza: leads "sin cotizar" con +10 días etiquetados sin que Joaco
// haya cotizado. Los saca de la lista activa (ya están fríos) y le avisa a Gaspar en UN
// solo mensaje. Corre 1 vez/día desde el cron; lock diario atómico (kv_cache) evita doble.
async function escalarSinCotizarViejos(env) {
  const labelId = await ensureLabelId(env, SIN_COTIZAR_LABEL_NAME, SIN_COTIZAR_LABEL_COLOR);
  if (!labelId) return { escalados: 0 };
  const nowIso = new Date().toISOString();
  const hoy = nowIso.slice(0, 10);
  try {
    const lock = await env.DB.prepare("INSERT OR IGNORE INTO kv_cache (k, v, updated_at) VALUES (?, '1', datetime('now'))").bind('sin_cotizar_escal:' + hoy).run();
    if (!(lock.meta && lock.meta.changes)) return { escalados: 0, skipped: true };
  } catch (_) {}
  try { await env.DB.prepare("ALTER TABLE sin_cotizar ADD COLUMN escalated_at TEXT").run(); } catch (_) {}
  const umbral10d = new Date(Date.now() - 10 * 86400000).toISOString();
  let viejos = [];
  try {
    viejos = (await env.DB.prepare(
      "SELECT sc.phone, sc.name, sc.canal FROM sin_cotizar sc " +
      "JOIN contact_labels cl ON cl.phone = sc.phone AND cl.label_id = ? " +
      "WHERE sc.quoted_at IS NULL AND sc.escalated_at IS NULL AND sc.created_at <= ? ORDER BY sc.created_at ASC"
    ).bind(labelId, umbral10d).all()).results || [];
  } catch (_) {}
  if (!viejos.length) return { escalados: 0 };
  for (const v of viejos) {
    try {
      await env.DB.prepare("DELETE FROM contact_labels WHERE phone = ? AND label_id = ?").bind(v.phone, labelId).run();
      await env.DB.prepare("UPDATE sin_cotizar SET escalated_at = ? WHERE phone = ?").bind(nowIso, v.phone).run();
    } catch (_) {}
  }
  const lines = viejos.slice(0, 25).map(v => `- ${(v.name && v.name.trim()) ? v.name.trim() : ('+' + v.phone)}${v.canal === 'ig' ? ' (IG)' : ''}`);
  const extra = viejos.length > 25 ? `\n...y ${viejos.length - 25} mas` : '';
  const msg = `⚠️ ${viejos.length} pedido${viejos.length > 1 ? 's' : ''} sin cotizar hace +10 dias\nJoaco no les paso presupuesto, los saque de la lista activa (ya estan frios):\n${lines.join('\n')}${extra}`;
  try { await precotizNotifyGaspar(env, msg, { tipo: 'sin_cotizar', prioridad: 'P2' }); } catch (_) {}
  return { escalados: viejos.length };
}

// Segmento "Reflote 15 días": leads CUALIFICADOS de carteles (últimos 15 días) que
// engancharon (pidieron precio/presupuesto O mandaron foto O medidas) pero NO recibieron
// presupuesto y NO tienen los datos completos (no son de "sin cotizar"). Alcanzables,
// inbound-first, no cursos, no internos, y NO ya reflotados. Base del broadcast de rescate.
const REFLOTE_LABEL_NAME = '🔁 Reflote';
const REFLOTE_LABEL_COLOR = '#3b82f6';
async function computeRefloteSegment(env) {
  const labelId = await ensureLabelId(env, REFLOTE_LABEL_NAME, REFLOTE_LABEL_COLOR);
  const desde15d = new Date(Date.now() - 15 * 86400000).toISOString();
  const sql = `
    WITH per_phone AS (
      SELECT phone,
        CASE WHEN MAX(CASE WHEN channel='ig' THEN 1 ELSE 0 END)=1 THEN 'ig' ELSE 'wa' END AS canal,
        MIN(CASE WHEN direction='inbound' AND msg_type!='status' THEN ts END) AS first_in_ts,
        MIN(CASE WHEN direction='outbound' AND msg_type!='status' THEN ts END) AS first_out_ts,
        MAX(CASE WHEN direction='inbound' AND msg_type!='status' THEN ts END) AS last_in_ts,
        MAX(CASE WHEN direction='inbound' AND msg_type='image' THEN 1 ELSE 0 END) AS has_img,
        MAX(CASE WHEN direction='inbound' AND msg_type IN ('text','audio') AND (
              lower(body) GLOB '*[0-9]x[0-9]*' OR lower(body) GLOB '*[0-9] x [0-9]*'
           OR lower(body) GLOB '*[0-9]x [0-9]*' OR lower(body) GLOB '*[0-9] x[0-9]*'
           OR lower(body) GLOB '*[0-9] por [0-9]*'
           OR lower(body) GLOB '*[0-9]cm*' OR lower(body) GLOB '*[0-9] cm*'
           OR lower(body) GLOB '*[0-9] mts*' OR lower(body) GLOB '*[0-9] metro*'
        ) THEN 1 ELSE 0 END) AS has_med,
        MAX(CASE WHEN direction='inbound' AND msg_type IN ('text','audio') AND (
              lower(body) GLOB '*presupuesto*' OR lower(body) GLOB '*cotiz*'
           OR lower(body) GLOB '*precio*' OR lower(body) GLOB '*cuanto*'
           OR lower(body) GLOB '*cuánto*' OR lower(body) GLOB '*cuesta*' OR lower(body) GLOB '*presupuest*'
        ) THEN 1 ELSE 0 END) AS has_intent,
        MAX(CASE WHEN direction='outbound' AND IFNULL(status,'')!='failed' AND ${_SC_QUOTE_SQL} THEN 1 ELSE 0 END) AS has_quote
      FROM wa_messages
      WHERE ts >= ?1 AND phone IS NOT NULL AND phone != ''
        AND phone NOT IN ('5491144366573','5491133708544') AND phone NOT IN (SELECT phone FROM wa_internal_phones)
      GROUP BY phone
    )
    SELECT p.phone, p.canal, p.first_in_ts, p.last_in_ts, s.contact_name
    FROM per_phone p LEFT JOIN wa_chats_summary s ON s.phone = p.phone
    WHERE p.first_in_ts IS NOT NULL AND p.first_in_ts >= ?1
      AND (p.first_out_ts IS NULL OR p.first_in_ts <= p.first_out_ts)
      AND IFNULL(s.inbox,'general') != 'cursos'
      AND p.has_quote = 0
      AND (p.has_intent = 1 OR p.has_img = 1 OR p.has_med = 1)
      AND NOT (p.has_img = 1 AND p.has_med = 1)
      AND p.phone NOT IN (SELECT phone FROM wa_unreachable_phones)
      AND p.phone NOT IN (SELECT phone FROM contact_labels WHERE label_id = ${labelId || 0})
      -- Excluir los que el bot de precotización ya está trabajando o completó. El
      -- reflote detecta medidas por GLOB (débil: no reconoce "30 alto 80 largo"),
      -- pero el bot (LLM) ya sabe que tienen foto+medidas → no pedírselas de nuevo.
      AND p.phone NOT IN (SELECT phone FROM precotiz_pilot WHERE estado IN ('activo','completo','cotizado'))
    ORDER BY p.last_in_ts DESC`;
  let rows = [];
  try { rows = (await env.DB.prepare(sql).bind(desde15d).all()).results || []; } catch (e) { return { error: String(e && e.message || e), count: 0, rows: [] }; }
  const wa = rows.filter(r => r.canal === 'wa').length;
  return {
    count: rows.length, wa, ig: rows.length - wa, label_id: labelId,
    sample: rows.slice(0, 8).map(r => (r.contact_name && r.contact_name.trim()) ? r.contact_name.trim() : ('+' + r.phone)),
    rows
  };
}

// Broadcast fijo del reflote (reply_ai=1) — reusa el motor de goteo + rama IA de Fase 2.5.
const REFLOTE_POS_MSG = 'Dale! Pasanos una foto del diseño que quieras y las medidas y te armamos el presupuesto.';
const REFLOTE_BODY_PREVIEW = 'Holaa {{1}}! Te escribíamos de Neon Infinito por tu consulta del cartel. Seguís interesado? Pasanos una foto de referencia y las medidas y te armamos el presupuesto';
async function ensureRefloteBroadcast(env) {
  await ensureBroadcastsSchema(env);
  try {
    const row = await env.DB.prepare("SELECT id FROM wa_broadcasts WHERE template = 'reflote_presupuesto' ORDER BY id ASC LIMIT 1").first();
    if (row && row.id) {
      try { await env.DB.prepare("UPDATE wa_broadcasts SET status='running', reply_ai=1, reply_pos_msg=?, reply_neg_msg='', lang='es_AR', param_mode='nombre', body_preview=? WHERE id=?").bind(REFLOTE_POS_MSG, REFLOTE_BODY_PREVIEW, row.id).run(); } catch (_) {}
      return row.id;
    }
    const res = await env.DB.prepare(
      "INSERT INTO wa_broadcasts (name, template, lang, param_mode, body_preview, status, reply_ai, reply_pos_msg, reply_neg_msg, created_at, created_by) VALUES ('Reflote presupuesto (auto)', 'reflote_presupuesto', 'es_AR', 'nombre', ?, 'running', 1, ?, '', ?, 'sistema')"
    ).bind(REFLOTE_BODY_PREVIEW, REFLOTE_POS_MSG, new Date().toISOString()).run();
    return res.meta && res.meta.last_row_id;
  } catch (_) { return null; }
}
// Barrido del reflote: 1 vez/semana (lunes 9 AM AR desde el cron). Encola el segmento
// CUALIFICADO de WhatsApp en la cola de broadcast (kind bc_<id>) con due_at goteado a lo
// largo del día (~1 cada 2,5 min) y los etiqueta "🔁 Reflote" (no re-manda). El sender +
// la rama IA existentes hacen el resto SIN ocultar el chat (queda en la bandeja de Joaco).
// Gated por kv reflote_on='1'. Lock diario atómico contra doble corrida.
async function processRefloteSweep(env) {
  try {
    if (await isWaBillingBlocked(env)) return { skipped: 'billing' };
    const f = await env.DB.prepare("SELECT v FROM kv_cache WHERE k = 'reflote_on'").first();
    if (!f || f.v !== '1') return { skipped: 'off' };
    const nowIso = new Date().toISOString();
    const lock = await env.DB.prepare("INSERT OR IGNORE INTO kv_cache (k, v, updated_at) VALUES (?, '1', datetime('now'))").bind('reflote_sweep:' + nowIso.slice(0, 10)).run();
    if (!(lock.meta && lock.meta.changes)) return { skipped: 'ya corrio hoy' };
    const bid = await ensureRefloteBroadcast(env);
    if (!bid) return { error: 'sin broadcast id' };
    const seg = await computeRefloteSegment(env);
    const labelId = seg.label_id;
    const wa = (seg.rows || []).filter(r => r.canal === 'wa').slice(0, 500);  // solo WA (IG no recibe plantillas)
    const kind = 'bc_' + bid;
    const startMs = Date.now();
    const stepSec = 150;
    let enq = 0;
    for (let i = 0; i < wa.length; i++) {
      const r = wa[i];
      const due = new Date(startMs + i * stepSec * 1000).toISOString();
      try {
        const res = await env.DB.prepare(
          "INSERT OR IGNORE INTO wa_autoreply_log (phone, kind, sent_at, status, due_at, sender_name) VALUES (?, ?, '', 'queued', ?, ?)"
        ).bind(r.phone, kind, due, r.contact_name || '').run();
        if (res.meta && res.meta.changes) {
          if (labelId) { try { await env.DB.prepare("INSERT OR IGNORE INTO contact_labels (phone, label_id, created_at) VALUES (?, ?, ?)").bind(r.phone, labelId, nowIso).run(); } catch (_) {} }
          enq++;
        }
      } catch (_) {}
    }
    return { enqueued: enq, total_wa: wa.length, broadcast_id: bid };
  } catch (e) { return { error: String(e && e.message || e) }; }
}

// Prompt de montaje/mockup: monta el render de un cartel sobre la foto del local del
// cliente, en la zona que el diseñador marcó con un recuadro. Hiperrealista, con glow
// del neón, SIN el cable de 220v. Herramienta del diseñador (2 imágenes de entrada).
const GEMINI_MOCKUP_PROMPT = [
  'Sos especialista en fotomontajes hiperrealistas de carteles de neón LED. Recibís DOS imágenes:',
  '1) La PRIMERA es la foto del frente/lugar del cliente. Tiene un recuadro marcado (un rectángulo dibujado encima) que indica EXACTAMENTE dónde y de qué tamaño va el cartel.',
  '2) La SEGUNDA es el cartel de neón solo (el render).',
  '',
  'Montá el cartel de la segunda imagen sobre la primera, EXACTAMENTE en la zona del recuadro y con ese tamaño. Reglas:',
  '- Integración HIPERREALISTA: ajustá la perspectiva, el ángulo y la escala del cartel para que calce natural con la pared/superficie del recuadro.',
  '- El neón ILUMINA de verdad: agregá el glow/resplandor del neón sobre la pared y el entorno cercano, con reflejos, luz y sombras coherentes con la escena (hora del día, materiales).',
  '- ELIMINÁ por completo el recuadro/marca: no debe quedar ningún rastro del rectángulo dibujado.',
  '- NO dibujes el cable de alimentación a 220v, ni transformadores, ni cables visibles: queda feo. El cartel va limpio, sin cables.',
  '- El resto de la foto (el local, la pared, el entorno) queda IDÉNTICO a la original, sin cambios.',
  '- No agregues texto, marcas de agua ni elementos que no estén en las imágenes.',
  '',
  'Devolvé únicamente la foto final con el cartel montado, fotorrealista.'
].join('\n');

// Dado un brief de corpórea (tipo='corporea' con corporea_json), determina el caso
// visual A-E (según qué caras son translúcidas/opacas + iluminación) y arma el bloque
// de contexto puntual que se appendea al GEMINI_CORPOREA_RENDER_PROMPT.
function corporeaContexto(brief) {
  let p = {};
  try { p = JSON.parse(brief.corporea_json || '{}') || {}; } catch { p = {}; }
  const conLuz = p.con_luz !== false; // default: con luz
  const fTrans = String(p.frente_acabado || 'translucido').toLowerCase().startsWith('transl');
  const lTrans = String(p.lat_acabado || 'translucido').toLowerCase().startsWith('transl');
  const eTrans = String(p.esp_acabado || 'opaca').toLowerCase().startsWith('transl');
  const mat = (p.frente_material === 'acrilico') ? 'acrílico' : 'impreso';
  let caso, efecto;
  if (!conLuz) {
    caso = 'E'; efecto = 'apagada: letra 3D de color sólido, sin ningún brillo ni halo (todas las caras opacas).';
  } else if (fTrans && lTrans) {
    caso = 'A'; efecto = 'toda la letra brilla como un volumen de luz (frente y cantos transiluminados).';
  } else if (fTrans && !lTrans) {
    caso = 'B'; efecto = 'la cara frontal brilla pareja, los cantos/laterales son color sólido.';
  } else if (!fTrans && lTrans) {
    caso = 'C'; efecto = 'el frente es color sólido, los cantos/laterales brillan.';
  } else if (!fTrans && !lTrans && eTrans) {
    caso = 'D'; efecto = 'letra de color sólido con HALO retroiluminado en la pared detrás (efecto backlight).';
  } else {
    caso = 'E'; efecto = 'todas las caras opacas con luz = no escapa luz, se ve como una letra 3D de color sólido sin brillo.';
  }
  // "Replicar diseño": el frente NO es un color sólido sino GRÁFICA IMPRESA full
  // color que reproduce el diseño de la imagen de referencia (logos multicolor
  // como Google/marcas — no se representan con un color único).
  const fReplicar = /replic|dise[ñn]o/i.test(String(p.frente_color || ''));
  const colF = fReplicar
    ? ' — GRÁFICA IMPRESA FULL COLOR: el frente reproduce EXACTAMENTE el diseño/logo de la imagen de referencia (todos sus colores, formas y tipografía tal cual), NO es un color sólido'
    : (p.frente_color ? `, color ${p.frente_color}` : '');
  // "Replicar diseño" en LATERALES: los cantos NO son un color sólido único — cada canto
  // toma EL MISMO color que su letra/zona en el frente (siguiendo la gráfica del diseño de
  // referencia). Clave para logos/letras multicolor. Si el frente es gráfica full color, los
  // cantos continúan esos mismos colores letra por letra.
  const lReplicar = /replic|dise[ñn]o/i.test(String(p.lat_color || ''));
  // El texto cambia según si el FRENTE es gráfica full color o un color sólido: si el frente
  // es sólido, "replicar" en los cantos = ese mismo color sólido (no inventar multicolor).
  const colL = lReplicar
    ? (fReplicar
        ? ' — REPLICAN EL DISEÑO DEL FRENTE: cada canto lleva EXACTAMENTE el MISMO color que su letra/zona correspondiente en el frente (siguiendo la gráfica y los colores del diseño de referencia), NO un color sólido único ni blanco. Letra roja → sus cantos rojos; letra azul → sus cantos azules; etc.'
        : ' — cada canto lleva EXACTAMENTE el MISMO color que su letra/zona correspondiente en el frente (si el frente es un color sólido, los cantos son ese mismo color; NO blanco). Letra roja → cantos rojos; letra azul → cantos azules; etc.')
    : (p.lat_color ? `, color ${p.lat_color}` : '');
  const colE = p.esp_color ? `, color ${p.esp_color}` : '';
  const med = (p.ancho_cm && p.alto_cm) ? `${p.ancho_cm} × ${p.alto_cm} cm` : (brief.medidas_libre || 's/d');
  return [
    'CONTEXTO DE ESTA CORPÓREA (aplicá EXACTAMENTE este caso):',
    `- CASO ${caso}: ${efecto}`,
    `- Frente: ${fReplicar ? 'gráfica impresa' : mat}, ${fTrans ? 'translúcido (transilumina)' : 'opaco'}${colF}.`,
    `- Laterales: ${lTrans ? 'translúcidos (brillan)' : 'opacos'}${colL}.`,
    `- Espalda: ${eTrans ? 'translúcida (deja salir luz = halo)' : 'opaca'}${colE}.`,
    `- Iluminación: ${conLuz ? 'CON luz (LED encendido)' : 'SIN luz (apagada)'}.`,
    `- Medidas: ${med}.`
  ].join('\n');
}

// Modelo de generación de imágenes de Gemini (Nano Banana). Configurable por env
// por si cambia el nombre; default al actual.
function geminiImageModel(env) {
  // gemini-3-pro-image = mejor calidad (render que va al cliente).
  // Alternativas más rápidas/baratas: gemini-3.1-flash-image, gemini-2.5-flash-image.
  return env.GEMINI_IMAGE_MODEL || 'gemini-3-pro-image';
}

// ArrayBuffer → base64 en chunks (evita stack overflow con imágenes grandes).
function abToBase64(buf) {
  const bytes = new Uint8Array(buf);
  let binary = '';
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunk));
  }
  return btoa(binary);
}

// Precios de Gemini por 1M tokens (USD). En los modelos *-image, 'out' incluye los
// tokens de la imagen generada (el grueso del costo). Ajustables si Google cambia
// precios — la fuente de verdad sigue siendo la factura de Google.
const GEMINI_PRICES = {
  // Tarifas STANDARD (no batch) por 1M tokens, verificadas contra ai.google.dev/gemini-api/docs/pricing.
  // OJO: antes estaban las de batch (out 30/5 = mitad) → subestimaba ~2x el flash-image.
  // Validado 2026-08: julio corregido = $157.24 vs Google $156.32 (0.6%).
  'gemini-3.1-flash-image': { in: 0.50, out: 60 },  // img: $0.067/1K, $0.101/2K, $0.151/4K
  'gemini-2.5-flash-image': { in: 0.50, out: 60 },
  'gemini-3-pro-image':     { in: 2.00, out: 120 }, // img: $0.134/1K-2K, $0.24/4K
  'gemini-2.5-pro':         { in: 1.25, out: 10 },
  'gemini-2.5-flash':       { in: 0.30, out: 2.50 },
};
function geminiCost(model, usage) {
  if (!usage) return 0;
  const p = GEMINI_PRICES[model] || GEMINI_PRICES['gemini-2.5-flash-image'];
  const ti = usage.promptTokenCount || 0;
  const to = usage.candidatesTokenCount || Math.max(0, (usage.totalTokenCount || 0) - ti);
  return (ti * p.in + to * p.out) / 1e6;
}
// Registra un uso de Gemini (render | params) con su costo estimado en gemini_usage.
async function geminiTrackUsage(env, model, kind, usage, ref) {
  try {
    const ti = (usage && usage.promptTokenCount) || 0;
    const to = (usage && usage.candidatesTokenCount) || 0;
    await env.DB.prepare(
      "INSERT INTO gemini_usage (ts, model, kind, tokens_in, tokens_out, cost_usd, ref) VALUES (?, ?, ?, ?, ?, ?, ?)"
    ).bind(new Date().toISOString(), model || '', kind || 'render', ti, to, geminiCost(model, usage), String(ref || '')).run();
  } catch (_) {}
}

// Toma el boceto (bytes + mime) + medidas, llama a Gemini, devuelve { ok, base64, mime }
// con la imagen generada, o { error }.
// Achica una imagen base64 grande antes de mandarla a Gemini (que corta a los ~30s
// con inputs pesados). Solo toca imágenes > ~400KB. Si falla (ej. imagen > 100 MP,
// el máximo del binding Images), devuelve la original. fit scale-down limita ambos lados.
async function _shrinkB64ForGemini(env, b64, mime) {
  if (!env.IMAGES || !b64) return { data: b64, mime: mime || 'image/png' };
  try {
    const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
    if (bytes.byteLength < 400 * 1024) return { data: b64, mime: mime || 'image/png' };
    const res = await env.IMAGES.input(new Response(bytes).body).transform({ width: 1600, height: 1600, fit: 'scale-down' }).output({ format: 'image/jpeg', quality: 82 });
    const buf = await res.response().arrayBuffer();
    return { data: abToBase64(buf), mime: 'image/jpeg' };
  } catch (_) { return { data: b64, mime: mime || 'image/png' }; }
}
async function generarRenderConGemini(env, bocetoBuf, bocetoMime, extraTexto, opts = {}) {
  if (!env.GEMINI_API_KEY) return { error: 'GEMINI_API_KEY no configurada' };
  const model = opts.model || geminiImageModel(env);
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${env.GEMINI_API_KEY}`;
  // basePrompt permite usar otro prompt (ej. corpóreas) sin tocar el de carteles.
  const basePrompt = opts.basePrompt || GEMINI_RENDER_PROMPT;
  const promptText = basePrompt + (extraTexto ? `\n\n${extraTexto}` : '');
  const _main = await _shrinkB64ForGemini(env, opts.mainBase64 || abToBase64(bocetoBuf), bocetoMime || 'image/png');
  const reqParts = [
    { text: promptText },
    { inline_data: { mime_type: _main.mime, data: _main.data } }
  ];
  // Imágenes extra (ej: montaje = foto del local marcada + render del cartel). Van
  // después de la principal, en el orden que las referencia el prompt.
  if (Array.isArray(opts.extraImages)) {
    for (const im of opts.extraImages) {
      if (im && im.base64) { const _e = await _shrinkB64ForGemini(env, im.base64, im.mime || 'image/png'); reqParts.push({ inline_data: { mime_type: _e.mime, data: _e.data } }); }
    }
  }
  const genCfg = { responseModalities: ['IMAGE', 'TEXT'] };
  // aspectRatio (ej '16:9','3:2','21:9') fuerza la proporción de salida — clave para
  // que un cartel finito no salga cuadrado. Solo modelos de imagen que lo soportan.
  if (opts.aspectRatio) genCfg.imageConfig = { aspectRatio: opts.aspectRatio };
  const body = {
    contents: [{ parts: reqParts }],
    generationConfig: genCfg
  };
  // Reintento ante errores TRANSITORIOS de Gemini (503 deadline/overloaded, 500, 429):
  // el render es pesado y Google a veces satura o corta por deadline. Un reintento
  // resuelve la mayoría sin tirarle el error al usuario. Errores definitivos (400 prompt
  // inválido, etc.) no se reintentan.
  let resp = null, lastErr = 'Gemini no respondió';
  for (let intento = 0; intento < 2; intento++) {
    if (intento > 0) await new Promise(r => setTimeout(r, 2000));
    try {
      resp = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
    } catch (e) { lastErr = 'fetch a Gemini falló: ' + e.message; resp = null; continue; }
    if (resp.ok) break;
    let detail = '';
    try { detail = (await resp.json())?.error?.message || ''; } catch (e) {}
    lastErr = `Gemini HTTP ${resp.status}${detail ? ': ' + detail : ''}`;
    const transient = resp.status === 503 || resp.status === 500 || resp.status === 429 || /deadline|unavailable|overloaded|timeout|try again/i.test(detail);
    resp = null;
    if (!transient) break;
  }
  if (!resp || !resp.ok) return { error: lastErr };
  let data;
  try { data = await resp.json(); } catch (e) { return { error: 'respuesta de Gemini no es JSON' }; }
  const cand = data?.candidates?.[0];
  const parts = cand?.content?.parts || [];
  const imgPart = parts.find(p => p.inlineData || p.inline_data);
  const inline = imgPart?.inlineData || imgPart?.inline_data;
  if (!inline || !inline.data) {
    // No vino imagen. Motivos posibles: (a) rechazo por seguridad/copyright — finishReason
    // (IMAGE_SAFETY/PROHIBITED_CONTENT/RECITATION/SAFETY) o promptFeedback.blockReason: típico
    // con personajes de marca/Disney (ej. Dumbo); (b) el modelo "responde" con texto en vez de
    // generar. Capturamos el motivo real para que el error sea legible (antes salía opaco).
    const fr = cand?.finishReason || '';
    const block = data?.promptFeedback?.blockReason || '';
    const txt = parts.find(p => p.text)?.text || '';
    const bloqueado = /SAFETY|PROHIBITED|RECITATION|BLOCK|IMAGE_OTHER/i.test(String(fr) + ' ' + String(block));
    const motivo = bloqueado
      ? `Gemini bloqueó la generación (${block || fr}). Suele pasar con personajes de marca / copyright (ej. Disney). Simplificá el boceto para que no sea reconocible o sacale el nombre de la marca del título/notas.`
      : (txt ? txt.slice(0, 200) : `sin imagen en la respuesta (finishReason=${fr || '—'}${block ? ', block=' + block : ''})`);
    return { error: 'Gemini no devolvió imagen: ' + motivo };
  }
  // Registrar el costo de este render (tokens reales que devuelve Gemini).
  try { await geminiTrackUsage(env, model, 'render', data?.usageMetadata, opts.ref || ''); } catch (_) {}
  return { ok: true, base64: inline.data, mime: inline.mimeType || inline.mime_type || 'image/png', usage: data?.usageMetadata || null, model };
}

// Analiza la imagen + el texto del cliente y devuelve un JSON con ancho_cm,
// alto_cm, neon_mt, razonamiento y dif_vs_cliente. Usa gemini-2.5-flash con
// responseMimeType=application/json (modo estructurado) → mucho más confiable
// que parsear texto libre. Costo ~$0.001 por call (muy barato vs render).
async function estimarParametrosConGemini(env, imageBuf, imageMime, contextoCliente) {
  if (!env.GEMINI_API_KEY) return { error: 'GEMINI_API_KEY no configurada' };
  // Modelo de texto+vision. Antes era gemini-2.5-flash (más barato pero
  // poco preciso midiendo proporciones en imágenes: error típico ±15%).
  // Pro tiene visión mucho más fina, error esperable ±5%. Costo extra
  // ~$0.005 por brief (vs $0.001 con Flash), despreciable vs render.
  const model = env.GEMINI_PARAMS_MODEL || 'gemini-2.5-pro';
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${env.GEMINI_API_KEY}`;
  const body = {
    contents: [{
      parts: [
        { text: GEMINI_PARAMS_PROMPT(contextoCliente) },
        { inline_data: { mime_type: imageMime || 'image/png', data: abToBase64(imageBuf) } }
      ]
    }],
    generationConfig: {
      responseMimeType: 'application/json',
      temperature: 0.2
    }
  };
  let resp;
  try {
    resp = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  } catch (e) {
    return { error: 'fetch a Gemini Flash falló: ' + e.message };
  }
  if (!resp.ok) {
    let detail = '';
    try { detail = (await resp.json())?.error?.message || ''; } catch(e) {}
    return { error: `Gemini params HTTP ${resp.status}${detail ? ': ' + detail : ''}` };
  }
  let data;
  try { data = await resp.json(); } catch (e) { return { error: 'respuesta de params no es JSON wrapper' }; }
  const txt = data?.candidates?.[0]?.content?.parts?.[0]?.text || '';
  if (!txt) return { error: 'Gemini no devolvió texto con params' };
  let parsed;
  try { parsed = JSON.parse(txt); }
  catch (e) { return { error: 'JSON de params inválido: ' + txt.slice(0, 100) }; }
  try { await geminiTrackUsage(env, model, 'params', data?.usageMetadata, ''); } catch (_) {}
  return {
    ok: true,
    ancho_cm: Math.round(Number(parsed.ancho_cm) || 0),
    alto_cm: Math.round(Number(parsed.alto_cm) || 0),
    neon_mt: Math.round((Number(parsed.neon_mt) || 0) * 10) / 10,
    razonamiento: String(parsed.razonamiento || '').slice(0, 250),
    dif_vs_cliente: !!parsed.dif_vs_cliente
  };
}

// ===== Coexistence history import (event: 'history' de 360dialog) =====
// Procesa el formato 360dialog flat con TRES sub-payloads mutuamente exclusivos:
//   - data.messages[]: mensajes entrantes del cliente (live, ya recibimos via Meta-style también)
//   - data.message_echoes[]: mensajes que Joaco escribió desde el celular (outbound)
//   - data.history[].threads[].messages[]: backfill on-boarding (hasta 6 meses de historial)
//
// Todos los inserts son INSERT OR IGNORE — wamid UNIQUE evita duplicados.
// Para cada media (image/video/audio/document/sticker) hace downloadMedia → R2.
async function processCoexistenceHistory(env, data) {
  const businessPhone = String(env.WA_BUSINESS_PHONE || '5491133708544').replace(/\D/g, '');

  // Cache de nombres si hay state_sync o contacts.
  const nameByPhone = {};
  for (const c of (data?.contacts || [])) {
    const waId = String(c.wa_id || '').replace('+', '');
    const nm = c.profile?.name || c.profile?.full_name || '';
    if (waId && nm) nameByPhone[waId] = nm;
  }

  // Helper: extrae body + mediaUrl + flags según el tipo del mensaje.
  // Devuelve { msgType, body, mediaUrl, contextId, forwarded, isVoice }.
  const parseMsg = (m) => {
    let msgType = m.type || 'unknown';
    let body = '';
    let mediaUrl = '';
    let forwarded = 0;
    let isVoice = 0;

    if (m.text)         body = m.text.body || '';
    else if (m.image)   { body = m.image.caption || '';  mediaUrl = m.image.id || ''; }
    else if (m.video)   { body = m.video.caption || '';  mediaUrl = m.video.id || ''; }
    else if (m.audio)   { mediaUrl = m.audio.id || ''; isVoice = m.audio.voice ? 1 : 0; }
    else if (m.document){ body = m.document.filename || ''; mediaUrl = m.document.id || ''; }
    else if (m.sticker) { mediaUrl = m.sticker.id || ''; }
    else if (m.reaction) body = m.reaction.emoji || '';
    else if (m.location) body = `[ubicacion] ${m.location.latitude},${m.location.longitude}${m.location.name ? ' — ' + m.location.name : ''}`;
    else if (m.button)   body = m.button.text || m.button.payload || '';
    else if (m.interactive) body = m.interactive?.button_reply?.title || m.interactive?.list_reply?.title || '';
    else if (m.contacts && m.contacts.length) {
      const names = m.contacts.map(c => c.name?.formatted_name || c.name?.first_name || 'contacto').join(', ');
      const phones = m.contacts.map(c => c.phones?.[0]?.phone || c.phones?.[0]?.wa_id || '').filter(Boolean).join(', ');
      body = `[contacto] ${names}${phones ? ' — ' + phones : ''}`;
    }
    else if (m.order)   body = `[pedido] ${(m.order.product_items || []).map(p => p.product_retailer_id).join(', ')}`;
    // Coexistence history-specific:
    else if (m.type === 'media_placeholder') {
      // History trae 9417 de estos — placeholders de media que Meta no migró al onboarding.
      body = '[media histórica no disponible]';
    }
    else if (m.type === 'edit' && m.edit) {
      // History trae 373 edits — mantenemos el texto editado.
      msgType = 'edit';
      body = m.edit.message?.text?.body || '[mensaje editado]';
    }
    else if ((m.type === 'errors' || m.unsupported) && Array.isArray(m.errors) && m.errors.length) {
      const code = m.errors[0].code;
      const title = m.errors[0].title || '';
      if (code === 131051 || title === 'Message type unknown') {
        body = '✏️ El cliente editó un mensaje (Meta no comparte el contenido editado)';
      } else if (title.includes('unavailable')) {
        body = '[mensaje no disponible]';
      } else {
        body = `[no soportado: ${title || code || 'desconocido'}]`;
      }
    }

    // Flags adicionales
    let contextId = '';
    if (m.context?.id) contextId = m.context.id;
    else if (m.reaction?.message_id) contextId = m.reaction.message_id;
    if (m.context?.forwarded) forwarded = 1;
    if (m.edit?.original_message_id) contextId = m.edit.original_message_id;

    return { msgType, body, mediaUrl, contextId, forwarded, isVoice };
  };

  // Helper: inserta un mensaje en wa_messages, baja media a R2, atribuye ads.
  const insertMsg = async ({ wamid, ts, direction, phone, senderName, m }) => {
    let { msgType, body, mediaUrl, contextId } = parseMsg(m);

    // Bajar media a R2 (best-effort, con reintentos por el race del webhook).
    let r2Key = '';
    if (mediaUrl && env.MEDIA) {
      try { const dl = await downloadMediaWithRetry(env, mediaUrl); if (dl) r2Key = dl.key; } catch (_) {}
    }
    if (msgType === 'audio' && r2Key && env.AI) {
      // FIX: antes esto era un no-op (calculaba la transcripción y la tiraba).
      // Ahora la guardamos en body como '[audio] <texto>' igual que la rama live.
      try { const t = await transcribeAudio(env, r2Key); if (t) body = '[audio] ' + t; } catch (_) {}
    }

    try {
      await env.DB.prepare(
        `INSERT INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status)
         VALUES (?,?,?,?,?,?,?,?,?,?)
         ON CONFLICT(wamid) DO UPDATE SET
           direction = excluded.direction,
           phone = excluded.phone,
           msg_type = excluded.msg_type,
           body = excluded.body,
           media_url = excluded.media_url,
           context_id = excluded.context_id,
           ts = excluded.ts
         WHERE wa_messages.body IS NULL OR wa_messages.body = '' OR wa_messages.msg_type IN ('status','media_placeholder')`
      ).bind(ts, wamid, direction, phone, senderName, msgType, body, r2Key || mediaUrl, contextId, null).run();
    } catch (_) {}

    // Ad attribution (CTWA — referral) — mismo bloque que rama Meta-style.
    if (m.referral && direction === 'inbound') {
      try {
        const ref = m.referral;
        const exists = await env.DB.prepare('SELECT 1 FROM wa_ad_attributions WHERE wamid = ?').bind(wamid).first();
        if (!exists) {
          await env.DB.prepare(`INSERT INTO wa_ad_attributions
            (phone, wamid, ts, source_id, source_type, source_url, headline, body, media_type, image_url, video_url, thumbnail_url, ctwa_clid, created_at)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(
            phone, wamid, ts,
            String(ref.source_id || ''), String(ref.source_type || ''), String(ref.source_url || ''),
            String(ref.headline || ''), String(ref.body || ''), String(ref.media_type || ''),
            String(ref.image_url || ''), String(ref.video_url || ''), String(ref.thumbnail_url || ''),
            String(ref.ctwa_clid || ''), new Date().toISOString()
          ).run();
        }
      } catch (_) {}
    }
  };

  // === Branch 1: data.messages[] (live inbound del cliente) ===
  for (const m of (data?.messages || [])) {
    const wamid = m.id || ''; if (!wamid) continue;
    const fromNorm = String(m.from || '').replace(/\D/g, '');
    const direction = fromNorm === businessPhone ? 'outbound' : 'inbound';
    const phone = fromNorm;
    const senderName = direction === 'inbound' ? (nameByPhone[phone] || '') : '';
    const ts = m.timestamp ? new Date(parseInt(m.timestamp) * 1000).toISOString() : new Date().toISOString();
    await insertMsg({ wamid, ts, direction, phone, senderName, m });
  }

  // === Branch 2: data.message_echoes[] (Joaco escribió desde el celular) ===
  // ANTES SE IGNORABAN — 6.475 mensajes perdidos en 6 meses según auditoría.
  for (const echo of (data?.message_echoes || [])) {
    const wamid = echo.id || ''; if (!wamid) continue;
    const phone = String(echo.to || '').replace(/\D/g, ''); // destinatario = cliente
    const ts = echo.timestamp ? new Date(parseInt(echo.timestamp) * 1000).toISOString() : new Date().toISOString();
    await insertMsg({ wamid, ts, direction: 'outbound', phone, senderName: '', m: echo });
  }

  // === Branch 3: data.history[] (backfill on-boarding) ===
  // Cada history tiene threads, cada thread tiene messages. ANTES SE IGNORABA — 64.596 mensajes.
  for (const histEntry of (data?.history || [])) {
    for (const thread of (histEntry?.threads || [])) {
      const threadCtx = thread?.context || {};
      // Para identificar al cliente del thread (cuando from_me=true)
      const clientPhone = String(threadCtx.wa_id || '').replace('+', '');
      for (const m of (thread?.messages || [])) {
        const wamid = m.id || ''; if (!wamid) continue;
        // Direction barato y confiable: history_context.from_me
        const fromMe = m.history_context?.from_me === true;
        const direction = fromMe ? 'outbound' : 'inbound';
        const fromNorm = String(m.from || '').replace(/\D/g, '');
        const phone = fromMe ? clientPhone : (fromNorm || clientPhone);
        const senderName = direction === 'inbound' ? (nameByPhone[phone] || '') : '';
        const ts = m.timestamp ? new Date(parseInt(m.timestamp) * 1000).toISOString() : new Date().toISOString();
        await insertMsg({ wamid, ts, direction, phone, senderName, m });
      }
    }
  }
}

// ===== Template status update (webhook field message_template_status_update) =====
// Meta dispara este evento cuando un template cambia de status (PENDING → APPROVED|
// REJECTED|PAUSED|DISABLED). Reemplaza al polling cada 5 min de monitorTemplateStatus
// si el field está suscrito en el hub de 360dialog.
// [Etapa 1] También procesa el field 'template_category_update' (Meta recategoriza una plantilla: trae
// new_category y no trae event): guarda la categoría en el caché (la cadena de los avisos solo usa UTILITY) y, si
// es una plantilla de los avisos, avisoTplCategoriaCheck le avisa a Gaspar.
async function processTemplateStatusUpdate(env, value) {
  const name = value?.message_template_name || '';
  const lang = value?.message_template_language || '';
  const event = value?.event || ''; // APPROVED, REJECTED, PAUSED, etc.
  const reason = value?.reason || '';
  const newCat = String(value?.new_category || value?.category || '').toUpperCase();
  // Reflejar el estado al instante en el caché (los broadcasts esperan a que su plantilla esté APPROVED
  // ahí; si no, dependía del polling horario y arrancaban hasta ~1h tarde).
  if (name && ['APPROVED', 'REJECTED', 'PAUSED', 'DISABLED', 'PENDING'].includes(String(event).toUpperCase())) {
    try { await env.DB.prepare('INSERT INTO template_status_cache (name, status, updated_at) VALUES (?, ?, ?) ON CONFLICT(name) DO UPDATE SET status = excluded.status, updated_at = excluded.updated_at').bind(name, String(event).toUpperCase(), new Date().toISOString()).run(); } catch (_) {}
  }
  if (name && newCat && (await ensureTplCategoryCol(env))) {
    try { await env.DB.prepare('UPDATE template_status_cache SET category = ?, updated_at = ? WHERE name = ?').bind(newCat, new Date().toISOString(), name).run(); } catch (_) {}
  }
  if (name && (event || newCat)) {
    let st = String(event).toUpperCase(), cat = newCat;
    try { const c = await env.DB.prepare("SELECT status, COALESCE(category, '') AS category FROM template_status_cache WHERE name = ?").bind(name).first(); if (c) { st = st || c.status; cat = cat || String(c.category || '').toUpperCase(); } } catch (_) {}
    await avisoTplCategoriaCheck(env, name, st, cat);
  }
  if (!env.ADMIN_NOTIFY_PHONE || !name || !event) return;
  let icon = '📋';
  if (event === 'APPROVED') icon = '✅';
  else if (event === 'REJECTED' || event === 'DISABLED') icon = '❌';
  else if (event === 'PAUSED' || event === 'FLAGGED') icon = '⚠️';
  const text = `${icon} Plantilla "${name}" (${lang}): ${event}${reason ? `\nMotivo: ${reason}` : ''}`;
  try { await waSendText(env, env.ADMIN_NOTIFY_PHONE, text, { esAviso: true }); } catch (_) {}
}

// ===== Coexistence state sync (event: 'smb_app_state_sync' de 360dialog) =====
// 360dialog manda este evento al onboardear y cada vez que Joaco agrega/modifica/
// elimina un contacto en la app de WhatsApp Business del celular. Es la fuente de
// la verdad para nombres reales y permite poblar sender_name de mensajes inbound.
async function processCoexistenceStateSync(env, data) {
  const items = Array.isArray(data?.state_sync) ? data.state_sync : [];
  const now = new Date().toISOString();
  for (const item of items) {
    if (item.type !== 'contact') continue;
    const c = item.contact || {};
    const userId = String(c.user_id || '').trim();
    const phone = String(c.phone_number || '').replace(/\D/g, '');
    const fullName = String(c.full_name || '').trim();
    const firstName = String(c.first_name || '').trim();
    if (!userId || !phone) continue;
    const action = item.action || 'add';
    const version = parseInt(item.metadata?.version) || 1;
    try {
      await env.DB.prepare(
        `INSERT INTO wa_address_book (user_id, phone, full_name, first_name, action, version, first_seen_at, updated_at)
         VALUES (?,?,?,?,?,?,?,?)
         ON CONFLICT(user_id) DO UPDATE SET
           phone = excluded.phone,
           full_name = CASE WHEN excluded.full_name != '' THEN excluded.full_name ELSE wa_address_book.full_name END,
           first_name = CASE WHEN excluded.first_name != '' THEN excluded.first_name ELSE wa_address_book.first_name END,
           action = excluded.action,
           version = excluded.version,
           updated_at = excluded.updated_at`
      ).bind(userId, phone, fullName, firstName, action, version, now, now).run();

      // Bonus: backfill sender_name de mensajes inbound previos sin nombre.
      if (fullName) {
        await env.DB.prepare(
          "UPDATE wa_messages SET sender_name = ? WHERE phone = ? AND direction = 'inbound' AND (sender_name IS NULL OR sender_name = '')"
        ).bind(fullName, phone).run();
      }
    } catch (_) {}
  }
}

// ===== Image analysis (Vision via Workers AI) =====
async function analyzeImage(env, r2Key) {
  if (!env.AI || !env.MEDIA || !r2Key) return null;
  try {
    const obj = await env.MEDIA.get(r2Key);
    if (!obj) return null;
    const buf = await obj.arrayBuffer();
    const uint8 = new Uint8Array(buf);
    // Try uform-gen2 (image-to-text, simpler API)
    let result;
    try {
      result = await env.AI.run('@cf/unum/uform-gen2-qwen-500m', {
        image: [...uint8],
        prompt: 'Describí esta imagen en español en 1-2 oraciones cortas. Si tiene texto o palabras, transcibilas exactamente. Si es un diseño, logo o cartel, describí qué muestra.',
        max_tokens: 200
      });
    } catch (e1) {
      // Fallback: llama vision with array format
      try {
        result = await env.AI.run('@cf/meta/llama-3.2-11b-vision-instruct', {
          image: [...uint8],
          prompt: 'Describe this image in Spanish in 1-2 short sentences.',
          max_tokens: 200
        });
      } catch (e2) {
        console.error('both vision models failed:', e1.message, e2.message);
        return null;
      }
    }
    // Extract text from whatever format the model returns
    if (!result) return null;
    if (typeof result === 'string') return result;
    return result.description || result.response || result.text || result.output || JSON.stringify(result);
  } catch (e) {
    console.error('image analysis error:', e);
    return null;
  }
}

// ===== Comprobantes de pago — lanzamiento junio 2026 =====
// DESACTIVADO el 12/06 a pedido de Gaspar: el OCR de comprobantes y el reenvío
// a su WhatsApp personal eran solo para la noche del 11/06. Este interruptor
// apaga las tres piezas (OCR, reenvío en vivo y backfill). Para reactivar todo,
// poner PAGO_CAPTURA_ACTIVA = true.
const PAGO_CAPTURA_ACTIVA = true;   // re-apuntado 08/10/2026 para el lanzamiento de octubre
// Ventana del lanzamiento: desde 18:00 AR del 08/10 hasta fin del 13/10 AR (~5 días). Para cortar
// antes cuando cierre el lanzamiento: poner PAGO_CAPTURA_ACTIVA = false. AR = UTC-3.
const PAGO_LANZAMIENTO_START_UTC = '2026-10-08T21:00:00.000Z';
const PAGO_LANZAMIENTO_END_UTC   = '2026-10-14T03:00:00.000Z';
const PAGO_SENA_MIN = 30000;   // banda de la seña del acceso (~40.000 ARS)
const PAGO_SENA_MAX = 50000;
function isPagoLanzamientoWindow(tsIso) {
  if (!PAGO_CAPTURA_ACTIVA) return false;   // captura desactivada → no se OCR-ea ni reenvía nada
  const t = String(tsIso || '');
  return t >= PAGO_LANZAMIENTO_START_UTC && t < PAGO_LANZAMIENTO_END_UTC;
}
function _normTxt(s) { return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''); }

// ===== Reenvío automático de comprobantes al WhatsApp personal de Gaspar =====
// Pedido para el lanzamiento: que cada imagen/PDF que entre se le reenvíe a
// Gaspar a su personal, SOLO hoy (11/06) y mañana (12/06) AR. Idempotente vía la
// MISMA marca de kv_cache ('resent:<num>:<wamid>') que usó el reenvío manual, así
// no duplica con la "foto" inicial. Si el send falla (p.ej. ventana 24h cerrada)
// NO marca → un barrido posterior con /admin/wa/resend-media lo recupera.
const RESEND_GASPAR_PHONE   = '5491155604999';
const RESEND_GASPAR_END_UTC = '2026-06-13T03:00:00.000Z'; // fin del 12/06 AR (cubre todo el 12)
function isResendGasparWindow(tsIso) {
  // Sin límite inferior: alcanza con que sea anterior al cierre (todo lo que
  // entre de acá a fin de mañana). El hook ya está acotado a inbound media.
  return String(tsIso || '') < RESEND_GASPAR_END_UTC;
}
async function forwardProofToGaspar(env, m) {
  try {
    const target = RESEND_GASPAR_PHONE;
    const phone = String(m.phone || '');
    if (!phone || phone === target) return;        // no reenviarse a sí mismo
    const r2Key = m.r2Key;
    if (!r2Key) return;
    const ckey = 'resent:' + target + ':' + m.wamid;
    // idempotencia: si ya se reenvió, salir
    try { const seen = await env.DB.prepare("SELECT 1 AS x FROM kv_cache WHERE k = ?").bind(ckey).first(); if (seen) return; } catch (_) {}
    // datos del OCR (processPaymentProof ya escribió la fila, si pudo)
    let monto = 0, cuenta = '';
    try { const p = await env.DB.prepare("SELECT monto, cuenta FROM wa_pago_proof WHERE wamid = ?").bind(m.wamid).first(); if (p) { monto = p.monto || 0; cuenta = p.cuenta || ''; } } catch (_) {}
    let obj; try { obj = await env.MEDIA.get(r2Key); } catch (_) { return; }
    if (!obj) return;
    const buf = await obj.arrayBuffer();
    const mime = obj.httpMetadata?.contentType || (m.msgType === 'image' ? 'image/jpeg' : 'application/pdf');
    const baseName = (r2Key.split('/').pop() || '');
    const dotExt = baseName.includes('.') ? ('.' + baseName.split('.').pop()) : '';
    const ext = dotExt || (m.msgType === 'image' ? '.jpg' : (mime.includes('pdf') ? '.pdf' : ''));
    const fileName = m.msgType === 'document' ? ('comprobante_' + phone + ext) : (baseName || ('img' + ext));
    const mediaId = await uploadMediaToMeta(env, buf, mime, fileName);
    if (!mediaId) return;
    const fmtMonto = (n) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    const cuentaLabel = (c) => c === 'mp_gaspar' ? 'MP Gaspar' : c === 'bna_bruno' ? 'BNA Bruno' : (c === 'otra' ? 'otra cuenta' : (c || ''));
    const d = new Date(m.ts || Date.now());
    const art = new Date(d.getTime() - 3 * 3600 * 1000);
    const hhmm = String(art.getUTCHours()).padStart(2, '0') + ':' + String(art.getUTCMinutes()).padStart(2, '0');
    const quien = (m.senderName && String(m.senderName).trim()) ? String(m.senderName).trim() : phone;
    let cap = quien + ' · ' + phone + ' · ' + hhmm;
    if (monto && monto > 0) cap += '\n$' + fmtMonto(monto) + (cuenta ? (' · ' + cuentaLabel(cuenta)) : '');
    let res;
    if (m.msgType === 'image') res = await waSendImage(env, target, mediaId, cap);
    else res = await waSendDocument(env, target, mediaId, fileName, cap);
    if (res && res.ok) {
      try { await env.DB.prepare("INSERT OR REPLACE INTO kv_cache (k, v, updated_at) VALUES (?, ?, ?)").bind(ckey, '1', new Date().toISOString()).run(); } catch (_) {}
    }
  } catch (_) {}
}
// Red de seguridad del reenvío a Gaspar: corre en el cron y reintenta los inbound
// media (hoy+mañana) que aún no tienen la marca 'resent:' (los que el reenvío en
// vivo no logró mandar). LIMIT chico por tick — como corre cada minuto, drena
// cualquier backlog rápido sin recargar. Se apaga sola pasada la ventana + 3h.
async function processGasparResendBackfill(env) {
  try {
    if (!PAGO_CAPTURA_ACTIVA) return;               // reenvío de comprobantes desactivado (12/06)
    const endMs = new Date(RESEND_GASPAR_END_UTC).getTime() + 3 * 3600 * 1000;
    if (Date.now() > endMs) return;                 // ventana terminada → nada que hacer
    const target = RESEND_GASPAR_PHONE;
    const floor = '2026-06-11T23:00:00.000Z';       // desde las 20h AR del 11/06
    let rows;
    try {
      const rs = await env.DB.prepare(
        "SELECT m.wamid, m.phone, m.sender_name AS senderName, m.msg_type AS msgType, m.media_url AS r2Key, m.ts " +
        "FROM wa_messages m " +
        "LEFT JOIN kv_cache kc ON kc.k = ('resent:' || ? || ':' || m.wamid) " +
        "WHERE m.direction='inbound' AND m.msg_type IN ('image','document') " +
        "  AND m.ts >= ? AND m.ts < ? AND m.media_url IS NOT NULL AND m.media_url != '' " +
        "  AND kc.k IS NULL " +
        "ORDER BY m.id ASC LIMIT 5"
      ).bind(target, floor, RESEND_GASPAR_END_UTC).all();
      rows = rs.results || [];
    } catch (_) { return; }
    for (const r of rows) {
      await forwardProofToGaspar(env, { wamid: r.wamid, phone: r.phone, senderName: r.senderName, r2Key: r.r2Key, msgType: r.msgType, ts: r.ts });
      await new Promise(rr => setTimeout(rr, 300));
    }
  } catch (_) {}
}

// OCR potente del comprobante con Claude visión (imagen o PDF). Devuelve el JSON parseado o null.
// meta = { phone, by } → solo para registrar el gasto en copilot_usage (kind 'ocr').
async function analyzePaymentProof(env, r2Key, mimeHint, meta) {
  if (!env.ANTHROPIC_API_KEY || !env.MEDIA || !r2Key) return null;
  let obj; try { obj = await env.MEDIA.get(r2Key); } catch (_) { return null; }
  if (!obj) return null;
  let buf; try { buf = await obj.arrayBuffer(); } catch (_) { return null; }
  if (!buf || buf.byteLength < 64) return null;
  const mime = (String(obj.httpMetadata?.contentType || mimeHint || '').split(';')[0].trim().toLowerCase()) || 'image/jpeg';
  const isPdf = mime.includes('pdf');
  const b64 = abToBase64(buf);
  const block = isPdf
    ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 } }
    : { type: 'image', source: { type: 'base64', media_type: /(png|jpeg|webp|gif)/.test(mime) ? mime : 'image/jpeg', data: b64 } };
  const system = 'Sos un analista que lee comprobantes de pago/transferencia de Argentina (capturas o PDFs). Devolvé SOLO un JSON válido (sin markdown ni texto extra) con este formato exacto:\n' +
    '{"es_comprobante":true,"monto":0,"moneda":"ARS","cuenta":"mp_gaspar","titular_destino":"","banco":"","fecha":"","confianza":0.0}\n' +
    'Reglas:\n' +
    '- monto: numero sin simbolos ni puntos de miles (ej: 45000). 0 si no se ve.\n' +
    '- cuenta: a que cuenta ENTRO el dinero. Mercado Pago -> "mp_gaspar". Banco de la Nacion Argentina (BNA / Banco Nacion) -> "bna_bruno". Otra entidad -> "otra". No se distingue -> "desconocida".\n' +
    '- titular_destino: nombre del que RECIBE, tal cual figura. banco: la entidad destino.\n' +
    '- Si NO es un comprobante de pago, es_comprobante=false y el resto en 0/"".';
  let r;
  try {
    r = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({ model: 'claude-sonnet-4-5', max_tokens: 400, system, messages: [{ role: 'user', content: [block, { type: 'text', text: 'Analiza este comprobante y devolve el JSON.' }] }] })
    });
  } catch (_) { return null; }
  let j; try { j = await r.json(); } catch (_) { return null; }
  if (!r.ok) return null;
  await logAnthropicUsage(env, 'ocr', 'claude-sonnet-4-5', j, meta && meta.phone, (meta && meta.by) || '');
  let txt = String(j.content?.[0]?.text || '').trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  try { return JSON.parse(txt); } catch (_) { return { es_comprobante: false }; }
}

// ¿La conversación tiene la frase clave del lanzamiento? (caption del comprobante
// o algún inbound de texto de los últimos 30 min con "comunidad al infinito").
async function hasLaunchKeyPhrase(env, phone, caption) {
  if (_normTxt(caption).includes('comunidad al infinito')) return true;
  try {
    const since = new Date(Date.now() - 30 * 60 * 1000).toISOString();
    const rs = await env.DB.prepare("SELECT body FROM wa_messages WHERE phone = ? AND direction = 'inbound' AND ts >= ? ORDER BY ts DESC LIMIT 12").bind(phone, since).all();
    for (const r of (rs.results || [])) if (_normTxt(r.body).includes('comunidad al infinito')) return true;
  } catch (_) {}
  return false;
}

// ¿El monto es similar (±10%) a algún pago confirmado del lanzamiento?
async function isSimilarToLaunchAmount(env, monto) {
  if (!(monto > 0)) return false;
  try {
    const rs = await env.DB.prepare("SELECT DISTINCT monto FROM wa_pago_proof WHERE clasificacion = 'lanzamiento' AND monto > 0").all();
    for (const r of (rs.results || [])) { const a = +r.monto; if (a > 0 && Math.abs(monto - a) <= 0.10 * a) return true; }
  } catch (_) {}
  return false;
}

// Crea la etiqueta si no existe (con el nombre EXACTO en UTF-8 del worker — evita
// el problema de encoding de la ñ vía wrangler) y devuelve su id.
async function ensureLabelId(env, name, color) {
  try { await env.DB.prepare("INSERT OR IGNORE INTO labels (name, color, created_at) VALUES (?, ?, datetime('now'))").bind(name, color || '#888').run(); } catch (_) {}
  try { const r = await env.DB.prepare("SELECT id FROM labels WHERE name = ?").bind(name).first(); return r?.id || null; } catch (_) { return null; }
}

// Resuelve la cuenta destino por la INSTITUCIÓN (más confiable que el campo
// "cuenta" del OCR, que falla si el titular figura "Neon infinito" en vez de Gaspar).
function resolveCuenta(a) {
  const banco = _normTxt(a && a.banco);
  if (banco.includes('mercado pago') || banco.includes('mercadopago')) return 'mp_gaspar';
  if (banco.includes('nacion') || banco.includes('bna')) return 'bna_bruno';
  const c = (a && a.cuenta) || '';
  if (c === 'mp_gaspar' || c === 'bna_bruno') return c;
  return c || 'desconocida';
}

// Procesa un comprobante entrante: dedup por wamid, OCR, respalda en D1 y etiqueta.
// NO responde nada (eso lo hacen a mano). Corre en ctx.waitUntil (no bloquea el webhook).
async function processPaymentProof(env, m) {
  if (!m || !m.wamid || !m.phone) return;
  // Los comprobantes de CARTELES (contacto con "POR PAGAR") los maneja processCartelPagos
  // (saca "POR PAGAR" + pone "Cartel primer pago"). Acá SOLO procesamos los del lanzamiento.
  try { if (await hasPorPagarLabel(env, m.phone)) return; } catch (_) {}
  // Clientes del servicio de CORTE (alumnos o pedidos de corte): sus comprobantes los maneja el vigía de corte
  // (corteVigiaPago → corte_pago_check + caja). Antes se colaban como "Nuevo pago" del lanzamiento: el 12-oct
  // 3 cobros de corte ($7.700 a $18.375) se avisaron a Gaspar y Bruno como pagos del curso.
  try {
    const corte = await env.DB.prepare("SELECT (EXISTS (SELECT 1 FROM corte_alumnos WHERE telefono = ?1) OR EXISTS (SELECT 1 FROM corte_pedidos WHERE telefono = ?1)) AS v").bind(m.phone).first();
    if (corte && corte.v) return;
  } catch (_) {}
  // Clientes de CARTELES sin "POR PAGAR" (pagan el 50% restante, o la seña sin OC): tampoco son del lanzamiento. Antes
  // se avisaban a Gaspar y Bruno como "pago lanzamiento" y el chat se iba a cursos, sacándole el cliente al vendedor
  // (oct: …8469 de Facu, …8787, …1070, …1296). Salvo que el cliente nombre el lanzamiento ("comunidad al infinito").
  try {
    if (!(await hasLaunchKeyPhrase(env, m.phone, m.caption))) {
      const c = await env.DB.prepare(
        `SELECT (EXISTS (SELECT 1 FROM oc_enviadas o WHERE o.phone = ?1 AND o.ts_out >= strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-120 days'))
              OR EXISTS (SELECT 1 FROM pedidos p WHERE substr(replace(IFNULL(p.telefono, ''), ' ', ''), -10) = substr(?1, -10) AND p.fecha >= date('now', '-120 days'))
              OR EXISTS (SELECT 1 FROM briefs b WHERE b.cliente_wa_id = ?1 AND b.estado = 'enviado' AND b.enviado_at >= strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-120 days'))
              OR EXISTS (SELECT 1 FROM contact_labels cl JOIN labels l ON l.id = cl.label_id WHERE cl.phone = ?1 AND l.name IN ('Cartel primer pago', 'Cartel 2do pago', '📋 Para cotizar', '🔠 Corpóreo'))
              OR EXISTS (SELECT 1 FROM wa_chats_summary s WHERE s.phone = ?1 AND COALESCE(s.assigned_to, '') IN (${VENDEDORES_SECUNDARIOS.map(x => "'" + x + "'").join(', ')}))) AS v`
      ).bind(m.phone).first();
      if (c && c.v) return;
    }
  } catch (_) {}
  try {
    const res = await env.DB.prepare(
      "INSERT OR IGNORE INTO wa_pago_proof (wamid, phone, nombre, media_key, caption, ts, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)"
    ).bind(m.wamid, m.phone, m.senderName || '', m.r2Key || '', String(m.caption || '').slice(0, 500), m.ts || new Date().toISOString(), new Date().toISOString()).run();
    if (!res?.meta?.changes) return; // ya procesado
  } catch (_) { return; }
  const a = await analyzePaymentProof(env, m.r2Key, m.msgType === 'document' ? 'application/pdf' : '', { phone: m.phone, by: 'pago_lanzamiento' });
  const esPago = !!(a && a.es_comprobante);
  const monto = (a && +a.monto) || 0;
  const cuenta = resolveCuenta(a);
  let clasificacion = '', labelName = null;
  if (esPago) {
    // (los carteles / POR PAGAR ya se filtraron arriba → acá solo llegan pagos del lanzamiento)
    clasificacion = (monto >= PAGO_SENA_MIN && monto <= PAGO_SENA_MAX) ? 'sena' : 'full';  // seña ~40k vs completo
    labelName = 'pago lanzamiento';
  }
  try {
    await env.DB.prepare(
      "UPDATE wa_pago_proof SET is_payment=?, clasificacion=?, monto=?, moneda=?, cuenta=?, titular=?, banco=?, confianza=?, raw=? WHERE wamid=?"
    ).bind(esPago ? 1 : 0, clasificacion, monto, (a && a.moneda) || 'ARS', cuenta, (a && a.titular_destino) || '', (a && a.banco) || '', (a && +a.confianza) || 0, JSON.stringify(a || {}).slice(0, 1500), m.wamid).run();
  } catch (_) {}
  if (labelName) {
    const color = '#22c55e';  // pago lanzamiento = verde
    const lid = await ensureLabelId(env, labelName, color);
    if (lid) { try { await env.DB.prepare("INSERT OR IGNORE INTO contact_labels (phone, label_id, created_at) VALUES (?, ?, ?)").bind(m.phone, lid, new Date().toISOString()).run(); } catch (_) {} }
    // Revelar el chat a la bandeja de Abril (cursos) para que atienda al que pagó. Va ANTES del aviso
    // (antes iba después): así el dueño del chat que resuelve avisoInterno ya es Abril y no el de 'general'.
    try { await env.DB.prepare("INSERT INTO wa_chats_summary (phone, inbox, updated_at) VALUES (?, 'cursos', ?) ON CONFLICT(phone) DO UPDATE SET inbox = 'cursos', updated_at = excluded.updated_at WHERE wa_chats_summary.inbox IS NULL OR wa_chats_summary.inbox IN ('oculto','general','')").bind(m.phone, new Date().toISOString()).run(); } catch (_) {}
    // Aviso a Gaspar + Bruno por cada pago (+ el inicial "ya arrancaron" una sola vez).
    try { await avisoPagoLanzamiento(env, { nombre: m.senderName, phone: m.phone, monto, esSena: clasificacion === 'sena', wamid: m.wamid }); } catch (_) {}
  }
}

// ===================== AVISOS INTERNOS (plan de fondo, Etapa 1 — oct-2026) =====================
// Un solo camino para avisarle algo a alguien del equipo: avisoInterno. Hasta ahora cada flujo mandaba su
// propio texto libre a Gaspar (precotizNotifyGaspar, avisoLanzamientoSend, ADMIN_NOTIFY_PHONE…) sin dejar
// rastro: con la ventana de 24 h cerrada el texto rebotaba (131047) y nadie se enteraba. avisoInterno registra
// cada aviso en avisos_internos (mig 051), elige la vía (texto si la ventana está abierta, plantilla UTILITY si
// no, resumen para lo que puede esperar, cola en el silencio nocturno de los vendedores, tope por hora) y sigue
// la entrega con los statuses del webhook.
// Kill-switch kv aviso_interno_modo = off | dry | on (sin la fila: off, así un deploy sin migración no prende nada):
//   off → no registra nada; corre el envío de hoy (legacy) tal cual.
//   dry → corre el legacy PRIMERO y después registra qué habría hecho lo nuevo (decision) + el wamid del legacy
//         (su status de Meta dice si lo de hoy llegó, para comparar).
//   on  → lo nuevo elige la vía y manda; el legacy queda de red solo si lo nuevo revienta antes de mandar nada.
// Anti-loop: un aviso nunca genera otro aviso (todo sale con waSend {esAviso:true}); los statuses de los internos
// nunca pasan por la rama de clientes; el reintento es UNO, por plantilla, con reclamo atómico por fila.

// Normaliza un kill-switch a 'off' | 'dry' | 'on'. Acepta los alias viejos de la casa ('0', '1', 'live').
function kvModo(v, def = 'off') {
  const s = String(v == null ? '' : v).trim().toLowerCase();
  if (s === 'on' || s === '1' || s === 'live' || s === 'true') return 'on';
  if (s === 'dry') return 'dry';
  if (s === 'off' || s === '0' || s === 'false') return 'off';
  return def;
}
// Varios kv en UNA query por PK, con caché por isolate (ttl ms). Las claves que no existen quedan null y también
// se cachean (si no, cada aviso volvería a preguntar). Si la D1 falla devuelve lo que haya en caché (o null).
const _kvManyCache = new Map();
async function kvMany(env, keys, ttl = 60000) {
  const now = Date.now(), out = {}, faltan = [];
  for (const k of keys) { const c = _kvManyCache.get(k); if (c && now - c.at < ttl) out[k] = c.v; else faltan.push(k); }
  if (faltan.length) {
    try {
      const rs = await env.DB.prepare('SELECT k, v FROM kv_cache WHERE k IN (' + faltan.map(() => '?').join(',') + ')').bind(...faltan).all();
      const got = new Map((rs.results || []).map(r => [r.k, r.v]));
      for (const k of faltan) { const v = got.has(k) ? got.get(k) : null; _kvManyCache.set(k, { v, at: now }); out[k] = v; }
    } catch (_) { for (const k of faltan) { const c = _kvManyCache.get(k); out[k] = c ? c.v : null; } }
  }
  return out;
}
function kvManyOlvidar(keys) { for (const k of keys) _kvManyCache.delete(k); }

// Perillas de los avisos (todas en kv, se cambian sin deploy desde Admin → Avisos internos).
const AVISO_KV = ['aviso_interno_modo', 'aviso_interno_vendedores_on', 'aviso_interno_tope_hora', 'aviso_interno_tope_p1_hora',
  'aviso_interno_tope_global_hora', 'aviso_interno_tpl_chain', 'aviso_interno_gaspar_marketing_ok', 'aviso_interno_retry_on',
  'aviso_interno_flush_on', 'aviso_interno_silencio', 'aviso_interno_tope_filas_corrida', 'aviso_interno_tope_filas_dia',
  'resumen_horas', 'wa_send_paused'];
const AVISO_TPL_CHAIN_DEF = ['aviso_interno_crm', 'recordatorio_agenda'];
const AVISO_PRIOS = ['P1', 'P2', 'P3'];
// Tipos que no cuentan para el tope por hora (son pocos, programados, y si se frenan se pierde la info del día).
const AVISO_TIPOS_SIN_TOPE = ['resumen', 'reporte', 'test'];
async function avisoCfg(env) {
  const kv = await kvMany(env, AVISO_KV);
  const int = (k, d) => { const n = parseInt(kv[k], 10); return Number.isFinite(n) && n >= 0 ? n : d; };
  let chain = AVISO_TPL_CHAIN_DEF;
  try { const c = JSON.parse(kv.aviso_interno_tpl_chain || 'null'); if (Array.isArray(c) && c.length) chain = c.map(String).filter(Boolean); } catch (_) {}
  const sil = String(kv.aviso_interno_silencio || '22-8').split('-').map(x => parseInt(x, 10));
  const horas = String(kv.resumen_horas || '10,14,18').split(',').map(x => parseInt(x, 10)).filter(h => h >= 0 && h <= 23);
  const si = (k, d) => (kv[k] == null ? d : kv[k]) === '1';
  return {
    modo: kvModo(kv.aviso_interno_modo, 'off'),
    vendedoresOn: si('aviso_interno_vendedores_on', '0'),
    topeHora: int('aviso_interno_tope_hora', 12), topeP1: int('aviso_interno_tope_p1_hora', 30), topeGlobal: int('aviso_interno_tope_global_hora', 80),
    chain, gasparMkt: si('aviso_interno_gaspar_marketing_ok', '1'),
    retryOn: si('aviso_interno_retry_on', '1'), flushOn: si('aviso_interno_flush_on', '1'),
    silDesde: Number.isFinite(sil[0]) ? sil[0] : 22, silHasta: Number.isFinite(sil[1]) ? sil[1] : 8,
    resumenHoras: horas.length ? horas : [10, 14, 18],
    topeFilasCorrida: int('aviso_interno_tope_filas_corrida', 20000), topeFilasDia: int('aviso_interno_tope_filas_dia', 200000),
    pausado: kv.wa_send_paused === '1',
  };
}
function avisoHoraAR() { return new Date(Date.now() - 3 * 3600e3).getUTCHours(); }
function avisoFechaAR() { return new Date(Date.now() - 3 * 3600e3).toISOString().slice(0, 10); }
// ¿Es horario de silencio de los vendedores? ('22-8' cruza la medianoche; '13-15' no).
function avisoEnSilencio(cfg) {
  const h = avisoHoraAR(), a = cfg.silDesde, b = cfg.silHasta;
  if (a === b) return false;
  return a > b ? (h >= a || h < b) : (h >= a && h < b);
}
function _avHoraTxt(iso) { const d = new Date((Date.parse(iso) || Date.now()) - 3 * 3600e3); return String(d.getUTCHours()).padStart(2, '0') + ':' + String(d.getUTCMinutes()).padStart(2, '0'); }
// Parámetro de plantilla: Meta rechaza saltos de línea y 4+ espacios seguidos → una sola línea, recortada.
function unaLinea(s, max = 900) { const t = String(s || '').replace(/\s+/g, ' ').trim(); return t.length > max ? t.slice(0, max - 1) + '…' : t; }
// Prioridad por TIPO sin deploy (§3.7): kv aviso_tipo:<tipo> = 'P1' | 'P2' | 'P3' (vacío = la del código). Reemplaza
// la prioridad por defecto del aviso y la de los destinatarios que la heredaban; las copias con prioridad propia
// distinta (p. ej. la P3 a Gaspar de una falla) quedan como están. Así Gaspar mueve un tipo al resumen (P3) o lo
// sube a urgente sin tocar código. kvMany cachea 60 s (también el "no existe"): 0 queries en el caso normal.
const AVISO_TIPO_RE = /^[a-z0-9_]{1,40}$/;
// Tipos cuya prioridad no se pisa: el reporte (sinCola: su cron reintenta hasta que sale; como P3 iría al resumen
// sin salir, el cron lo volvería a pedir en cada tick de las 21 y el resumen de las 10 lo traería repetido), la
// prueba manual y el propio resumen.
const AVISO_TIPOS_PRIO_FIJA = ['reporte', 'test', 'resumen'];
async function avisoAplicarTipo(env, o) {
  try {
    if (o.sinCola || o.forzarOn || AVISO_TIPOS_PRIO_FIJA.includes(String(o.tipo || ''))) return o;
    const tipo = String(o.tipo || 'legacy');
    if (!AVISO_TIPO_RE.test(tipo)) return o;
    const k = 'aviso_tipo:' + tipo;
    const v = String((await kvMany(env, [k]))[k] || '').trim().toUpperCase();
    if (!AVISO_PRIOS.includes(v)) return o;
    const def = AVISO_PRIOS.includes(o.prioridad) ? o.prioridad : 'P2';
    const mapa = (it) => (it && typeof it === 'object' && it.prioridad === def) ? { ...it, prioridad: v } : it;
    return { ...o, prioridad: v, para: Array.isArray(o.para) ? o.para.map(mapa) : mapa(o.para) };
  } catch (_) { return o; }
}

// Medidor de filas leídas por corrida (freno de costo de D1, objeción [ALTA] del plan): cada query de los crons
// nuevos pasa por avQ con el medidor, que suma meta.rows_read. .all() siempre (también para RETURNING): .first()
// no trae meta.
function d1Medidor() { const m = { filas: 0, escritas: 0, add(r) { try { m.filas += Number((r && r.meta && r.meta.rows_read) || 0); m.escritas += Number((r && r.meta && r.meta.rows_written) || 0); } catch (_) {} } }; return m; }
async function avQ(env, sql, binds = [], med = null) {
  const r = await env.DB.prepare(sql).bind(...binds).all();
  if (med) med.add(r);
  return r.results || [];
}

// ----- Identidad (§3.2): las personas son agenda_phones.usuario -----
// gaspar, bruno, joaquin, facundo, agustina, abril, disenador, neyen, anibal. Es el mismo identificador para buscar
// el teléfono y para saber de quién es un chat, así que no hace falta mapa de alias (pedidos.comercial_id='joaco'
// es otro espacio de nombres y no se toca).
const INTERNOS_FIJOS = ['5491155604999', '5491155604996', '5491137593269'];   // Gaspar, Bruno, Joaco: la guardia de siempre
const AVISO_SLUGS_FIJOS = { gaspar: '5491155604999', bruno: '5491155604996', joaquin: '5491137593269' };
// Gaspar y Bruno reciben a toda hora. El resto (vendedores, Abril, diseño, producción) respeta
// aviso_interno_vendedores_on y el silencio nocturno (decisión de Gaspar 12-oct: 22 a 8 salvo plata confirmada).
const AVISO_SIN_SILENCIO = ['gaspar', 'bruno'];
function _avDig(p) { return String(p || '').replace(/\D/g, ''); }
// Dueño de un chat (slug de agenda_phones): cursos → Abril; corte/privado/precotiz/oculto → Gaspar; asignado a un
// vendedor secundario (Facu/Agus) → ese; el resto (general sin asignar o de Joaco) → joaquin. El motor de "sin
// responder" (Etapa 2) excluye 'oculto' en su propia consulta, así que acá puede caer en Gaspar sin molestar.
function duenoDeChat(inbox, asg) {
  const ib = String(inbox || ''), a = String(asg || '').toLowerCase();
  if (ib === 'cursos') return 'abril';
  if (ib === 'corte' || ib === 'privado' || ib === 'precotiz' || ib === 'oculto') return 'gaspar';
  if (a && VENDEDORES_SECUNDARIOS.includes(a)) return a;
  return 'joaquin';
}
async function duenoDeChatPhone(env, phone, med = null) {
  const ph = _avDig(phone);
  let r = null;
  try { r = (await avQ(env, 'SELECT inbox, assigned_to FROM wa_chats_summary WHERE phone = ?', [ph], med))[0] || null; } catch (_) {}
  const inbox = (r && r.inbox) || '', asg = (r && r.assigned_to) || '';
  return { slug: duenoDeChat(inbox, asg), inbox, asg };
}
// Teléfonos del equipo: wa_internal_phones ∪ agenda_phones ∪ ADMIN_NOTIFY_PHONE ∪ los 3 fijos. Caché 10 min por
// isolate. Si la query falla: solo los fijos y ok:false (fail-closed: el que llama decide no avisar fallas de
// clientes en ese lote antes que tratar a un interno como cliente). No se memoiza el fallo.
let _internosCache = null;
async function internosSet(env) {
  if (_internosCache && Date.now() - _internosCache.at < 10 * 60 * 1000) return _internosCache;
  const set = new Set(INTERNOS_FIJOS);
  const bySlug = new Map(Object.entries(AVISO_SLUGS_FIJOS));
  const slugByPhone = new Map(Object.entries(AVISO_SLUGS_FIJOS).map(([s, p]) => [p, s]));
  try {
    const rs = await env.DB.prepare("SELECT usuario AS slug, phone FROM agenda_phones UNION ALL SELECT '' AS slug, phone FROM wa_internal_phones").all();
    for (const r of (rs.results || [])) {
      const p = _avDig(r.phone); if (!p) continue;
      set.add(p);
      const sl = String(r.slug || '').toLowerCase();
      if (sl) { bySlug.set(sl, p); if (!slugByPhone.has(p) || !AVISO_SLUGS_FIJOS[slugByPhone.get(p)]) slugByPhone.set(p, sl); }
    }
    const adm = _avDig(env.ADMIN_NOTIFY_PHONE); if (adm) set.add(adm);
    _internosCache = { set, bySlug, slugByPhone, ok: true, at: Date.now() };
    return _internosCache;
  } catch (_) {
    // Con una lista anterior en caché (vencida) se usa esa, que es mejor que solo los fijos (p. ej. para que el poll
    // de notificaciones no le muestre a un vendedor el chat de Agus); ok sigue en false (fail-closed donde importa).
    if (_internosCache) return { ..._internosCache, ok: false };
    return { set, bySlug, slugByPhone, ok: false, at: Date.now() };
  }
}
async function esTelefonoInterno(env, phone) {
  const d = _avDig(phone);
  try { return (await internosSet(env)).set.has(d); } catch (_) { return INTERNOS_FIJOS.includes(d); }
}
// Usuario de la sesión del CRM → slug. 'Gaspar' es usuario compartido con Bruno: los avisos "al autor" de algo que
// mandó 'gaspar' van a los dos (avisoResolverPara).
function avisoAutorSlug(sessionUser) {
  const s = String(sessionUser || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  if (!s) return '';
  if (s === 'joaco' || s === 'joaquin') return 'joaquin';
  if (s === 'cursos' || s === 'abril') return 'abril';
  if (s === 'emma' || s === 'disenador') return 'disenador';
  if (s === 'nadia' || s === 'facu' || s === 'facundo') return 'facundo';   // Facu reemplazó a Nadia (mismo usuario)
  if (s === 'agus' || s === 'agustina') return 'agustina';
  if (VENDEDORES_SECUNDARIOS.includes(s)) return s;
  return ['gaspar', 'bruno', 'neyen', 'anibal'].includes(s) ? s : '';
}
// ¿La ventana de 24 h del interno está abierta? (le escribió al número del negocio hace < 23 h; idx phone+ts).
async function ventanaAbiertaInterno(env, phone, med = null) {
  const desde = new Date(Date.now() - 23 * 3600 * 1000).toISOString();
  const r = await avQ(env, "SELECT 1 AS x FROM wa_messages WHERE phone = ? AND direction = 'inbound' AND msg_type NOT IN ('status', 'reaction') AND ts > ? LIMIT 1", [_avDig(phone), desde], med);
  return r.length > 0;
}

// ----- Esquema (mig 051). Patrón de la casa (045): la migración se aplica ANTES del deploy y esto solo crea
// tablas y columnas si faltan (ALTER en try/catch) y verifica antes de memoizar. Los índices los crea la
// migración (nunca acá): si faltan se loguea, no se crean en caliente.
let _avisosSchemaOk = false, _tplCatColOk = false;
async function ensureAvisosSchema(env) {
  if (_avisosSchemaOk) return true;
  try {
    await env.DB.prepare(`CREATE TABLE IF NOT EXISTS avisos_internos (id INTEGER PRIMARY KEY AUTOINCREMENT, clave TEXT UNIQUE, dest TEXT NOT NULL, dest_slug TEXT NOT NULL DEFAULT '', tipo TEXT NOT NULL,
      prioridad TEXT NOT NULL DEFAULT 'P2' CHECK (prioridad IN ('P1','P2','P3')), texto TEXT NOT NULL, ref_phone TEXT NOT NULL DEFAULT '', media_keys TEXT NOT NULL DEFAULT '',
      via TEXT NOT NULL DEFAULT '', decision TEXT NOT NULL DEFAULT '', wamid TEXT, wamid_prev TEXT, status TEXT NOT NULL DEFAULT 'pendiente', error_code TEXT NOT NULL DEFAULT '',
      intentos INTEGER NOT NULL DEFAULT 0, digest_id INTEGER, created_at TEXT NOT NULL, sent_at TEXT, delivered_at TEXT, read_at TEXT, flushed_at TEXT, visto_at TEXT, visto_por TEXT, updated_at TEXT NOT NULL)`).run();
  } catch (_) {}
  try { await env.DB.prepare("CREATE TABLE IF NOT EXISTS wa_send_author (wamid TEXT PRIMARY KEY, autor TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', ts TEXT NOT NULL)").run(); } catch (_) {}
  await ensureTplCategoryCol(env);
  try {
    await env.DB.prepare('SELECT id, clave, dest, dest_slug, tipo, prioridad, texto, ref_phone, media_keys, via, decision, wamid, wamid_prev, status, error_code, intentos, digest_id, created_at, sent_at, delivered_at, read_at, flushed_at, visto_at, visto_por, updated_at FROM avisos_internos LIMIT 0').all();
    await env.DB.prepare('SELECT wamid, autor, phone, ts FROM wa_send_author LIMIT 0').all();
    _avisosSchemaOk = true;
  } catch (_) {}
  if (_avisosSchemaOk) {
    try {
      const ix = await env.DB.prepare("SELECT COUNT(*) AS n FROM sqlite_master WHERE type = 'index' AND name IN ('idx_avisos_wamid', 'idx_avisos_dest_created', 'idx_avisos_status_created', 'idx_avisos_created', 'idx_wa_send_author_ts')").first();
      if (!ix || ix.n < 5) console.warn('avisos_internos: faltan índices de la migración 051 (' + (ix ? ix.n : 0) + '/5) — aplicarla');
    } catch (_) {}
  }
  return _avisosSchemaOk;
}
// template_status_cache.category (mig 051): la cadena de plantillas de los avisos solo usa las UTILITY. La tabla la
// crea monitorTemplateStatus; si todavía no existe, se reintenta en la próxima llamada.
async function ensureTplCategoryCol(env) {
  if (_tplCatColOk) return true;
  // Primero se mira si ya está (lo normal después de la migración): así no se tira un ALTER fallido por isolate.
  try { await env.DB.prepare('SELECT category FROM template_status_cache LIMIT 0').all(); _tplCatColOk = true; return true; } catch (_) {}
  try { await env.DB.prepare("ALTER TABLE template_status_cache ADD COLUMN category TEXT NOT NULL DEFAULT ''").run(); } catch (_) {}
  try { await env.DB.prepare('SELECT category FROM template_status_cache LIMIT 0').all(); _tplCatColOk = true; } catch (_) {}
  return _tplCatColOk;
}

// ----- Elección de plantilla (ventana cerrada) -----
// Candidatas en orden: las de aviso_interno_tpl_chain que estén APPROVED y sean UTILITY (las UTILITY no tienen el
// tope por usuario de las MARKETING, 131049, que hoy le hace rebotar los avisos a Bruno). recordatorio_agenda se
// acepta con categoría VACÍA solo mientras monitorTemplateStatus no la complete: se creó con allow_category_change
// y si Meta la pasó a MARKETING queda afuera apenas la columna se llene. Para Gaspar, aviso_lanzamiento (MARKETING)
// como último recurso si aviso_interno_gaspar_marketing_ok='1'. 360dialog devuelve status en minúsculas → upper().
// Devuelve [{name, max}] (max = largo del parámetro: aviso_lanzamiento admite 300).
async function elegirPlantillaAviso(env, cfg, slug, med = null) {
  const names = [...new Set([...cfg.chain, 'aviso_lanzamiento'])];
  const ph = names.map(() => '?').join(',');
  let rows = [];
  try { rows = await avQ(env, `SELECT name, upper(status) AS status, upper(COALESCE(category, '')) AS category FROM template_status_cache WHERE name IN (${ph})`, names, med); }
  catch (_) { try { rows = await avQ(env, `SELECT name, upper(status) AS status, '' AS category FROM template_status_cache WHERE name IN (${ph})`, names, med); } catch (_) {} }
  const by = new Map(rows.map(r => [r.name, r]));
  // ¿La columna ya está poblada? (alguna de estas plantillas tiene categoría): desde ahí la excepción de la categoría
  // vacía de recordatorio_agenda deja de valer (objeción [BAJA] del plan): vacía = no sabemos = no se usa.
  const poblada = rows.some(r => r.category);
  const out = [];
  for (const n of cfg.chain) {
    const r = by.get(n);
    if (!r || r.status !== 'APPROVED') continue;
    if (r.category === 'UTILITY' || (n === 'recordatorio_agenda' && r.category === '' && !poblada)) out.push({ name: n, max: 900 });
  }
  if (slug === 'gaspar' && cfg.gasparMkt) { const r = by.get('aviso_lanzamiento'); if (r && r.status === 'APPROVED' && !out.some(x => x.name === 'aviso_lanzamiento')) out.push({ name: 'aviso_lanzamiento', max: 300 }); }
  return out;
}

// ----- Destinatarios -----
// `para`: un slug, un teléfono interno, {duenio: phone}, {autor: wamid, phone}, {slug}, cada uno con `prioridad`
// opcional, o un array de esas formas. Solo resuelve a teléfonos de internosSet: un cliente nunca recibe un aviso.
// Mismo teléfono dos veces → queda la prioridad más urgente. Sin dueño → gaspar.
//  - {autor}: el que mandó ese wamid desde el CRM (wa_send_author). 'gaspar' = usuario compartido → gaspar + bruno.
//    Sin autor (envío automático: FUP, bot) → al RESUMEN del dueño del chat (P3), no como push (objeción [MEDIA]).
//  - Mientras aviso_interno_vendedores_on no esté en '1', lo que iba a un vendedor/Abril/diseño/producción le llega
//    a Gaspar (como hoy, que todo le llega a él). Con o.sinRedireccion (prueba manual) no se redirige.
async function avisoResolverPara(env, para, prioDef, cfg, o = {}, med = null) {
  const I = await internosSet(env);
  const items = Array.isArray(para) ? para : [para];
  const out = new Map();
  const add = (slug, prio, phoneDirecto) => {
    slug = String(slug || '').toLowerCase();
    let phone = phoneDirecto || I.bySlug.get(slug) || '';
    if (!phone || !I.set.has(phone)) return;
    if (slug && !AVISO_SIN_SILENCIO.includes(slug) && !cfg.vendedoresOn && !o.sinRedireccion) { slug = 'gaspar'; phone = I.bySlug.get('gaspar') || AVISO_SLUGS_FIJOS.gaspar; }
    const p = AVISO_PRIOS.includes(prio) ? prio : 'P2';
    const prev = out.get(phone);
    if (!prev || p < prev.prioridad) out.set(phone, { phone, slug, prioridad: p });   // 'P1' < 'P2' < 'P3'
  };
  for (const it of items) {
    if (it == null || it === '') continue;
    const prio = (typeof it === 'object' && it.prioridad) || prioDef;
    if (typeof it === 'string') {
      const d = _avDig(it);
      if (/^[\d\s+()-]+$/.test(it) && d.length >= 10) add(I.slugByPhone.get(d) || '', prio, d);
      else add(it, prio);
      continue;
    }
    if (it.slug) { add(it.slug, prio); continue; }
    if (it.duenio) { const d = await duenoDeChatPhone(env, it.duenio, med); add(d.slug || 'gaspar', prio); continue; }
    if (Object.prototype.hasOwnProperty.call(it, 'autor')) {
      let autor = '';
      if (it.autor) { try { autor = ((await avQ(env, 'SELECT autor FROM wa_send_author WHERE wamid = ?', [String(it.autor)], med))[0] || {}).autor || ''; } catch (_) {} }
      if (autor === 'gaspar') { add('gaspar', prio); add('bruno', prio); }
      else if (autor && I.bySlug.has(autor)) add(autor, prio);
      else if (it.phone) { const d = await duenoDeChatPhone(env, it.phone, med); add(d.slug || 'gaspar', 'P3'); }
      else add('gaspar', 'P3');
    }
  }
  return [...out.values()];
}

// ----- Decisión de la vía (§3.7), en este orden -----
// 1) P3 → resumen. 2) vendedor en horario de silencio → cola hasta las 8 (también P1, salvo plata confirmada:
// o.plata). 3) tope por hora: P1 (aviso_interno_tope_p1_hora), P2 (aviso_interno_tope_hora) y global → 'tope'
// (sale agrupado: P1 cada 5 min, P2 cada 15). 4) envíos pausados (wa_send_paused) → 'pausado'. Devuelve null si
// hay que mandar ya (la vía de envío la elige avisoEnviar / avisoDecisionRuta).
const AVISO_DECISION_ENVIO_SQL = "(decision = 'texto' OR decision LIKE 'plantilla:%' OR decision LIKE 'tpl:%')";
async function avisoDecidirPrevio(env, cfg, t, o, med = null) {
  const d = await _avDecidirPrevio(env, cfg, t, o, med);
  // o.sinCola (el reporte diario): el que llama ya reintenta solo; si además quedara esperando (resumen, cola, tope o
  // pausado), lo mandaría también el resumen, la cola o el flush y saldría DOS veces (o una por tick). Queda
  // 'descartado' (se ve en el panel con la decisión).
  if (d && o.sinCola) return { decision: d.decision, status: 'descartado' };
  return d;
}
async function _avDecidirPrevio(env, cfg, t, o, med) {
  if (t.prioridad === 'P3') return { decision: 'resumen', status: 'digest' };
  if (!AVISO_SIN_SILENCIO.includes(t.slug) && avisoEnSilencio(cfg) && !(t.prioridad === 'P1' && o.plata)) return { decision: 'cola', status: 'cola' };
  if (!AVISO_TIPOS_SIN_TOPE.includes(o.tipo)) {
    const desde = new Date(Date.now() - 3600e3).toISOString();
    const r = (await avQ(env, `SELECT COUNT(*) AS n, SUM(CASE WHEN prioridad = 'P1' THEN 1 ELSE 0 END) AS p1 FROM avisos_internos WHERE dest = ? AND created_at >= ? AND ${AVISO_DECISION_ENVIO_SQL}`, [t.phone, desde], med))[0] || {};
    const n = r.n || 0, p1 = r.p1 || 0;
    if (t.prioridad === 'P1' ? p1 >= cfg.topeP1 : (n - p1) >= cfg.topeHora) return { decision: 'tope', status: 'tope' };
    const g = (await avQ(env, `SELECT COUNT(*) AS n FROM avisos_internos WHERE created_at >= ? AND ${AVISO_DECISION_ENVIO_SQL}`, [desde], med))[0] || {};
    if ((g.n || 0) >= cfg.topeGlobal) return { decision: 'tope', status: 'tope' };
  }
  if (cfg.pausado) return { decision: 'pausado', status: 'pausado' };
  return null;
}
// Qué vía usaría avisoEnviar, SIN mandar (para el registro en dry).
async function avisoDecisionRuta(env, cfg, t, o, med = null) {
  if (o.tpls && o.tpls.length) return 'tpl:' + o.tpls[0].name;
  if (await ventanaAbiertaInterno(env, t.phone, med)) return 'texto';
  const c = await elegirPlantillaAviso(env, cfg, t.slug, med);
  return c.length ? 'plantilla:' + c[0].name : 'perdido';
}

// Fotos de un aviso (R2) al interno, con la ventana abierta. Devuelve cuántas salieron.
async function avisoEnviarMedia(env, phone, keys, caption) {
  let n = 0;
  if (!env.MEDIA) return 0;
  for (let i = 0; i < keys.length && i < 10; i++) {
    try {
      const obj = await env.MEDIA.get(keys[i]);
      if (!obj) continue;
      const buf = await obj.arrayBuffer();
      const mime = (obj.httpMetadata && obj.httpMetadata.contentType) || 'image/jpeg';
      const mediaId = await uploadMediaToMeta(env, buf, mime, String(keys[i]).split('/').pop() || 'foto.jpg');
      if (!mediaId) continue;
      const r = await waSendImage(env, phone, mediaId, i === 0 && caption ? String(caption).slice(0, 1000) : undefined, { esAviso: true });
      if (r && r.ok) n++;
    } catch (_) {}
  }
  return n;
}
// Manda UN aviso (no mira silencio ni tope: eso lo decide el que llama). Orden: las plantillas explícitas del
// aviso (o.tpls, p. ej. el reporte diario) → ventana abierta: texto (+ fotos; con '🔴 Urgente' si es P1) → la
// cadena de plantillas UTILITY con el texto en una línea. Un rechazo síncrono pasa a la siguiente opción.
// Devuelve { ok, via, wamid, code, error, fotos }.
async function avisoEnviar(env, cfg, t, o, med = null) {
  const E = { esAviso: true };
  let last = null;
  for (const tp of (o.tpls || [])) {
    let r = null;
    try { r = await waSendTemplate(env, t.phone, tp.name, tp.lang || 'es_AR', tp.params || [], null, E); } catch (_) {}
    if (r && r.ok) return { ok: true, via: 'tpl:' + tp.name, wamid: r.id || null, fotos: 0 };
    if (r && r.error === 'wa_send_paused') return { ok: false, via: 'pausado', code: '', error: r.error };
    last = r;
  }
  let ventana = false;
  try { ventana = await ventanaAbiertaInterno(env, t.phone, med); } catch (_) {}
  if (ventana) {
    const txt = String(o.texto || '');
    const pre = (t.prioridad === 'P1' && !/^\s*🔴/.test(txt)) ? '🔴 Urgente\n' : '';
    let r = null;
    try { r = await waSendText(env, t.phone, (pre + txt).slice(0, 4000), E); } catch (_) {}
    if (r && r.ok) {
      const fotos = (o.mediaKeys && o.mediaKeys.length) ? await avisoEnviarMedia(env, t.phone, o.mediaKeys, o.mediaCaption) : 0;
      return { ok: true, via: 'texto', wamid: r.id || null, fotos };
    }
    if (r && r.error === 'wa_send_paused') return { ok: false, via: 'pausado', code: '', error: r.error };
    last = r;
  }
  for (const tp of await elegirPlantillaAviso(env, cfg, t.slug, med)) {
    let r = null;
    try { r = await waSendTemplate(env, t.phone, tp.name, 'es_AR', [unaLinea(o.texto, tp.max)], null, E); } catch (_) {}
    if (r && r.ok) return { ok: true, via: 'plantilla:' + tp.name, wamid: r.id || null, fotos: 0 };
    if (r && r.error === 'wa_send_paused') return { ok: false, via: 'pausado', code: '', error: r.error };
    last = r;
  }
  return { ok: false, via: 'perdido', code: String((last && last.code) || ''), error: (last && last.error) || 'sin vía disponible' };
}

// ----- avisoInterno: la ÚNICA función para avisarle algo a alguien del equipo -----
// o = { para, tipo, prioridad='P2', texto, clave=null, refPhone='', mediaKeys=[], mediaCaption='', tpl=null,
//       legacy=null, legacyDest='', plata=false, forzarOn=false, sinRedireccion=false }
//  · clave: dedup '<tipo>:<id natural>' → se le agrega ':'+slug por destinatario (UNIQUE en la tabla).
//  · legacy: () => Promise<resultado de waSend> — el envío de HOY. Puede devolver { ok, id, porDest:{phone:r} }
//    si manda a varios. legacyDest: a quién manda el legacy (para pegar su wamid a la fila correcta en dry).
//  · tpl: plantilla(s) explícitas {name, lang, params} que se prueban primero en 'on' (reporte diario).
//  · plata: plata confirmada → un P1 a un vendedor sale aunque sea de noche.
//  · forzarOn: prueba manual (/admin/avisos/test): camino 'on' aunque el modo sea off/dry.
//  · sinCola: el que llama reintenta por su cuenta (reporte diario) → si no sale, la fila queda 'descartado' y
//    nunca la levantan la cola, el flush ni el resumen (si no, saldría dos veces).
// La prioridad se puede pisar por tipo sin deploy (kv aviso_tipo:<tipo>, avisoAplicarTipo).
// Nunca tira: devuelve { ok, modo, legacy, filas, fotos }.
async function avisoInterno(env, o = {}) {
  let cfg = null;
  try { cfg = await avisoCfg(env); } catch (_) {}
  const modo = o.forzarOn ? 'on' : ((cfg && cfg.modo) || 'off');
  if (modo !== 'on') {
    // off/dry: el envío de hoy va PRIMERO y no depende de nada nuevo (ni de la tabla ni del kv): si lo nuevo
    // falla, lo de hoy ya salió igual.
    let lr = null;
    if (typeof o.legacy === 'function') { try { lr = await o.legacy(); } catch (_) {} }
    if (modo === 'dry' && cfg) {
      const med = d1Medidor();
      try { await avisoRegistrarDry(env, cfg, await avisoAplicarTipo(env, o), lr, med); } catch (_) {}
      await avisoMedirFuera(env, med);
    }
    return { ok: !!(lr && lr.ok), modo, legacy: lr, filas: [] };
  }
  const estado = { mandado: false };
  const med = d1Medidor();
  try {
    return await avisoInternoOn(env, cfg || (await avisoCfg(env)), o.forzarOn ? o : await avisoAplicarTipo(env, o), estado, med);
  } catch (e) {
    // Lo nuevo reventó (tabla sin migrar, D1 caída, sin destino interno): si todavía no salió nada, el envío de
    // hoy como red. Si algo ya salió, no se repite.
    if (!estado.mandado && typeof o.legacy === 'function') {
      let lr = null; try { lr = await o.legacy(); } catch (_) {}
      return { ok: !!(lr && lr.ok), modo, legacy: lr, filas: [], error: String((e && e.message) || e) };
    }
    return { ok: estado.mandado, modo, legacy: null, filas: [], error: String((e && e.message) || e) };
  } finally { await avisoMedirFuera(env, med); }
}
function _avTpls(o) { return o.tpl ? (Array.isArray(o.tpl) ? o.tpl : [o.tpl]).filter(t => t && t.name) : []; }
async function avisoInternoOn(env, cfg, o, estado, med = null) {
  if (!(await ensureAvisosSchema(env))) throw new Error('avisos_internos sin esquema');
  const prio = AVISO_PRIOS.includes(o.prioridad) ? o.prioridad : 'P2';
  const dests = await avisoResolverPara(env, o.para == null ? 'gaspar' : o.para, prio, cfg, o, med);
  if (!dests.length) throw new Error('sin destino interno');
  const oo = { ...o, tpls: _avTpls(o), mediaKeys: Array.isArray(o.mediaKeys) ? o.mediaKeys : [] };
  const texto = String(o.texto || '').slice(0, 4000);
  const res = { ok: false, modo: 'on', legacy: null, filas: [], fotos: 0 };
  for (const t of dests) {
    const now = new Date().toISOString();
    const clave = o.clave ? String(o.clave) + ':' + (t.slug || t.phone) : null;
    // El INSERT con la clave reclama el aviso: dos llamadas simultáneas con la misma clave → solo una sigue.
    const ins = await avQ(env, "INSERT INTO avisos_internos (clave, dest, dest_slug, tipo, prioridad, texto, ref_phone, media_keys, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'pendiente', ?, ?) ON CONFLICT(clave) DO NOTHING RETURNING id",
      [clave, t.phone, t.slug, String(o.tipo || 'legacy'), t.prioridad, texto, _avDig(o.refPhone), oo.mediaKeys.length ? JSON.stringify(oo.mediaKeys) : '', now, now], med);
    const id = ins[0] && ins[0].id;
    if (!id) { res.filas.push({ slug: t.slug, dup: true }); continue; }   // ya avisado (misma clave)
    const d = o.forzarOn ? null : await avisoDecidirPrevio(env, cfg, t, oo, med);
    if (d) {
      await avQ(env, 'UPDATE avisos_internos SET status = ?, decision = ?, updated_at = ? WHERE id = ?', [d.status, d.decision, now, id], med);
      res.filas.push({ id, slug: t.slug, decision: d.decision });
      continue;
    }
    const s = await avisoEnviar(env, cfg, t, { ...oo, texto }, med);
    if (s.ok) { estado.mandado = true; res.ok = true; res.fotos += s.fotos || 0; }
    const st = s.ok ? 'enviado' : (o.sinCola ? 'descartado' : (s.via === 'pausado' ? 'pausado' : 'perdido'));
    await avQ(env, 'UPDATE avisos_internos SET via = ?, decision = ?, wamid = ?, status = ?, error_code = ?, intentos = 1, sent_at = ?, updated_at = ? WHERE id = ?',
      [s.ok ? s.via : '', s.via, s.wamid || null, st, s.ok ? '' : String(s.code || s.error || '').slice(0, 120), s.ok ? now : null, now, id], med);
    res.filas.push({ id, slug: t.slug, via: s.via, ok: s.ok });
  }
  return res;
}
// dry: registra qué habría hecho lo nuevo (decision) y pega el wamid del envío de hoy a la fila de su destinatario
// (o a la primera, si no se sabe), así el status de Meta mide si lo de hoy llegó. Lo que el legacy mandó a alguien
// que lo nuevo no tiene (p. ej. hoy a Gaspar, mañana a Abril) queda en una fila aparte 'solo_legacy'.
async function avisoRegistrarDry(env, cfg, o, lr, med = null) {
  if (!(await ensureAvisosSchema(env))) return;
  const prio = AVISO_PRIOS.includes(o.prioridad) ? o.prioridad : 'P2';
  let dests = [];
  try { dests = await avisoResolverPara(env, o.para == null ? 'gaspar' : o.para, prio, cfg, o, med); } catch (_) {}
  const oo = { ...o, tpls: _avTpls(o) };
  const texto = String(o.texto || '').slice(0, 4000);
  const mk = Array.isArray(o.mediaKeys) && o.mediaKeys.length ? JSON.stringify(o.mediaKeys) : '';
  // Resultado del legacy por destinatario.
  const porDest = new Map();
  if (lr && lr.porDest) { for (const [p, r] of Object.entries(lr.porDest)) porDest.set(_avDig(p), r); }
  else if (lr && _avDig(o.legacyDest)) porDest.set(_avDig(o.legacyDest), lr);
  else if (lr && dests[0]) porDest.set(dests[0].phone, lr);
  const ins = async (t, decision, r) => {
    const now = new Date().toISOString();
    const clave = o.clave ? String(o.clave) + ':' + (decision === 'solo_legacy' ? 'legacy:' + t.phone : (t.slug || t.phone)) : null;
    const status = r ? (r.ok ? 'enviado' : 'fallido') : 'dry';
    await avQ(env, "INSERT INTO avisos_internos (clave, dest, dest_slug, tipo, prioridad, texto, ref_phone, media_keys, via, decision, wamid, status, error_code, intentos, sent_at, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT(clave) DO NOTHING",
      [clave, t.phone, t.slug || '', String(o.tipo || 'legacy'), t.prioridad || prio, texto, _avDig(o.refPhone), mk, r ? 'legacy' : '', decision, (r && r.ok && r.id) || null, status,
       r && !r.ok ? String(r.code || r.error || '').slice(0, 120) : '', r ? 1 : 0, r && r.ok ? now : null, now, now], med);
  };
  for (const t of dests) {
    let decision = 'perdido';
    try { const d = await avisoDecidirPrevio(env, cfg, t, oo, med); decision = d ? d.decision : await avisoDecisionRuta(env, cfg, t, oo, med); } catch (_) {}
    const r = porDest.get(t.phone) || null;
    porDest.delete(t.phone);
    await ins(t, decision, r);
  }
  if (porDest.size) {
    const I = await internosSet(env);
    for (const [p, r] of porDest) { if (r) await ins({ phone: p, slug: I.slugByPhone.get(p) || '', prioridad: prio }, 'solo_legacy', r); }
  }
}

// ----- Statuses de los envíos al equipo (los llama el webhook SOLO para destinatarios internos) -----
// Nunca llama a avisoInterno. sent/delivered/read avanzan el estado (nunca retroceden). failed: un aviso que salió
// como TEXTO (ventana que se cerró, 131047) se reintenta UNA vez por plantilla, con reclamo atómico por fila
// (intentos < 2 … RETURNING): Meta reentrega el webhook y no puede salir dos veces. Si el wamid no es de un aviso
// (listas, reporte, vigilado…) y es la primera vez que falla, queda como 'falla_interna' P3 para el resumen de
// Gaspar (antes, con la guardia de 3 números, esas fallas no se veían en ningún lado).
async function avisoInternoStatus(env, s = {}) {
  const med = d1Medidor();
  try { await _avisoInternoStatus(env, s, med); } finally { await avisoMedirFuera(env, med); }
}
async function _avisoInternoStatus(env, s, med) {
  let cfg = null;
  try { cfg = await avisoCfg(env); } catch (_) { return; }
  if (!cfg || cfg.modo === 'off' || !s.wamid) return;
  if (!(await ensureAvisosSchema(env))) return;
  const now = new Date().toISOString();
  const rows = await avQ(env, 'SELECT id, status, via, intentos, dest, dest_slug, texto FROM avisos_internos WHERE wamid = ?', [String(s.wamid)], med);
  if (!rows.length) {
    if (s.status !== 'failed' || !s.primeraVez) return;
    const I = await internosSet(env);
    const quien = I.slugByPhone.get(_avDig(s.phone)) || s.phone;
    const txt = 'Falló un envío a ' + quien + ': ' + (s.errMsg || 'sin detalle') + (s.prevBody ? ' · "' + unaLinea(s.prevBody, 100) + '"' : '');
    // wamid_prev (no wamid): así los statuses que lleguen después de ese mensaje no la confunden con un aviso.
    await avQ(env, "INSERT INTO avisos_internos (clave, dest, dest_slug, tipo, prioridad, texto, ref_phone, decision, status, error_code, wamid_prev, created_at, updated_at) VALUES (?, ?, 'gaspar', 'falla_interna', 'P3', ?, ?, 'resumen', ?, ?, ?, ?, ?) ON CONFLICT(clave) DO NOTHING",
      ['falla_interna:' + s.wamid, I.bySlug.get('gaspar') || AVISO_SLUGS_FIJOS.gaspar, txt, _avDig(s.phone), cfg.modo === 'on' ? 'digest' : 'dry', String(s.errCode || ''), String(s.wamid), now, now], med);
    return;
  }
  const ids = rows.map(r => r.id), ph = ids.map(() => '?').join(',');
  if (s.status === 'sent') {
    await avQ(env, `UPDATE avisos_internos SET status = CASE WHEN status IN ('sin_confirmar', 'pendiente') THEN 'enviado' ELSE status END, sent_at = COALESCE(sent_at, ?), updated_at = ? WHERE id IN (${ph})`, [now, now, ...ids], med);
  } else if (s.status === 'delivered') {
    await avQ(env, `UPDATE avisos_internos SET status = CASE WHEN status IN ('enviado', 'sin_confirmar', 'pendiente', 'reintentando') THEN 'entregado' ELSE status END, delivered_at = COALESCE(delivered_at, ?), updated_at = ? WHERE id IN (${ph})`, [now, now, ...ids], med);
  } else if (s.status === 'read') {
    await avQ(env, `UPDATE avisos_internos SET status = CASE WHEN status IN ('enviado', 'entregado', 'sin_confirmar', 'pendiente', 'reintentando') THEN 'leido' ELSE status END, delivered_at = COALESCE(delivered_at, ?), read_at = COALESCE(read_at, ?), updated_at = ? WHERE id IN (${ph})`, [now, now, now, ...ids], med);
  } else if (s.status === 'failed') {
    // Solo pasan a 'fallido' los estados "quietos". Los que están EN VUELO ('enviando': lo reclamó el flush o la cola;
    // 'reintentando': lo está mandando otra invocación) no se tocan: un 'failed' reentregado los devolvería a
    // 'fallido' y el flush o este mismo reintento los volverían a reclamar → el mismo aviso saldría dos veces.
    // 'perdido' tampoco (ya se sabe que no salió) ni lo entregado/leído (el 'failed' tardío no lo deshace).
    await avQ(env, `UPDATE avisos_internos SET status = 'fallido', error_code = ?, updated_at = ? WHERE id IN (${ph}) AND status IN ('pendiente', 'enviado', 'sin_confirmar', 'fallido')`, [String(s.errCode || s.errMsg || '').slice(0, 120), now, ...ids], med);
    // La falla_interna espuria (el status llegó antes de que se guardara el wamid del aviso) se descarta.
    try { await avQ(env, "UPDATE avisos_internos SET status = 'descartado', updated_at = ? WHERE clave = ?", [now, 'falla_interna:' + s.wamid], med); } catch (_) {}
    if (cfg.modo !== 'on' || !cfg.retryOn) return;
    for (const r of rows) {
      if (r.via !== 'texto') continue;   // solo el texto que rebotó por ventana; agrupados/flush/plantillas no se reintentan
      const c = await avQ(env, "UPDATE avisos_internos SET status = 'reintentando', intentos = intentos + 1, updated_at = ? WHERE id = ? AND intentos < 2 AND via = 'texto' AND status = 'fallido' RETURNING id", [now, r.id], med);
      if (!c.length) continue;   // ya reintentado (webhook reentregado) o agotado
      let ok = null, lastErr = '', pausa = false;
      for (const tp of await elegirPlantillaAviso(env, cfg, r.dest_slug, med)) {
        let x = null;
        try { x = await waSendTemplate(env, r.dest, tp.name, 'es_AR', [unaLinea(r.texto, tp.max)], null, { esAviso: true }); } catch (_) {}
        if (x && x.ok) { ok = { via: 'plantilla:' + tp.name, id: x.id || null }; break; }
        if (x && x.error === 'wa_send_paused') { pausa = true; break; }   // frenan todos los envíos: no tiene sentido probar la siguiente
        lastErr = String((x && (x.code || x.error)) || '');
      }
      if (ok) await avQ(env, 'UPDATE avisos_internos SET wamid_prev = wamid, wamid = ?, via = ?, status = ?, sent_at = ?, updated_at = ? WHERE id = ?', [ok.id, ok.via, 'enviado', now, now, r.id], med);
      // Envíos pausados (wa_send_paused): 'pausado', así lo manda la cola apenas se reanudan ("Avisos que estaban en pausa").
      else if (pausa) await avQ(env, "UPDATE avisos_internos SET status = 'pausado', error_code = 'wa_send_paused', updated_at = ? WHERE id = ?", [now, r.id], med);
      else await avQ(env, "UPDATE avisos_internos SET status = 'perdido', error_code = ?, updated_at = ? WHERE id = ?", [lastErr.slice(0, 120) || 'reintento sin plantilla', now, r.id], med);
    }
  }
}

// ----- Reconciliador (cron */5) -----
// Cubre la carrera en que el status de Meta llega ANTES de que se guarde el wamid del aviso (el webhook no encuentra
// la fila): mira el status que el webhook dejó en wa_messages (por wamid, índice único) en UNA consulta. También
// pasa a 'sin_confirmar' los 'pendiente' viejos (el worker se cortó entre el INSERT y el envío) y los 'enviando' o
// 'reintentando' que un cron, un flush o el reintento del webhook reclamó y no terminó (no se reenvían solos: si
// salieron, saldrían dos veces; quedan en el panel con "Reenviar", que no toma lo que está en vuelo).
async function avisoInternoReconciliar(env, med = null) {
  const now = new Date().toISOString();
  const hace = (min) => new Date(Date.now() - min * 60000).toISOString();
  await avQ(env, "UPDATE avisos_internos SET status = 'sin_confirmar', updated_at = ? WHERE status = 'pendiente' AND created_at >= ? AND created_at < ?", [now, hace(48 * 60), hace(15)], med);
  await avQ(env, "UPDATE avisos_internos SET status = 'sin_confirmar', updated_at = ? WHERE status IN ('enviando', 'reintentando') AND created_at >= ? AND updated_at < ?", [now, hace(72 * 60), hace(15)], med);
  // La cola, el tope y los pausados solo se levantan dentro de las 24 h (processAvisosCola): lo que quedó afuera pasa a
  // 'perdido' para que el panel diga la verdad (se puede reenviar a mano). Ventana de 24-72 h: por índice.
  await avQ(env, "UPDATE avisos_internos SET status = 'perdido', error_code = 'vencido en cola', updated_at = ? WHERE status IN ('cola', 'tope', 'pausado') AND created_at >= ? AND created_at < ?", [now, hace(72 * 60), hace(24 * 60)], med);
  const rs = await avQ(env,
    `SELECT a.id, a.wamid, m.status AS st FROM avisos_internos a JOIN wa_messages m ON m.wamid = a.wamid
     WHERE a.status IN ('enviado', 'sin_confirmar') AND a.created_at >= ? AND a.created_at < ? AND a.wamid IS NOT NULL
       AND m.status IN ('delivered', 'read', 'failed') LIMIT 100`, [hace(6 * 60), hace(5)], med);
  for (const r of rs) {
    const nuevo = r.st === 'read' ? 'leido' : r.st === 'delivered' ? 'entregado' : 'fallido';
    const col = r.st === 'read' ? ', read_at = COALESCE(read_at, ?), delivered_at = COALESCE(delivered_at, ?)' : r.st === 'delivered' ? ', delivered_at = COALESCE(delivered_at, ?)' : '';
    const extra = r.st === 'read' ? [now, now] : r.st === 'delivered' ? [now] : [];
    await avQ(env, `UPDATE avisos_internos SET status = ?${col}, updated_at = ? WHERE id = ? AND status IN ('enviado', 'sin_confirmar')`, [nuevo, ...extra, now, r.id], med);
    // Si falló y el status había llegado antes que el wamid, el webhook lo anotó como 'falla_interna' (no era un
    // aviso todavía): ya está en su fila, se descarta el duplicado (por clave, índice único).
    if (r.st === 'failed') await avQ(env, "UPDATE avisos_internos SET status = 'descartado', updated_at = ? WHERE clave = ? AND status IN ('digest', 'dry')", [now, 'falla_interna:' + r.wamid], med);
  }
}

// ----- Envío agrupado (cola de silencio, excedente del tope, pausados) -----
// Un solo mensaje por persona con todo lo reclamado. via 'grupo:<vía>' → el reintento por plantilla no lo toma
// (si no, cada fila del grupo mandaría su propia plantilla).
async function avisoEnviarAgrupado(env, cfg, dest, slug, rows, titulo, med = null) {
  if (!rows.length) return;
  const now = new Date().toISOString();
  const prio = rows.reduce((p, r) => (r.prioridad < p ? r.prioridad : p), 'P3');
  const texto = rows.length === 1 ? rows[0].texto
    : (titulo + ' (' + rows.length + '):\n' + rows.map(r => '• ' + _avHoraTxt(r.created_at) + ' ' + unaLinea(r.texto, 350)).join('\n'));
  const s = await avisoEnviar(env, cfg, { phone: dest, slug, prioridad: prio }, { texto: texto.slice(0, 4000), tipo: 'agrupado' }, med);
  const ids = rows.map(r => r.id), ph = ids.map(() => '?').join(',');
  // intentos = intentos AUTOMÁTICOS por fila (el envío y el único reintento): el agrupado es el primer envío de lo que
  // esperaba (cola, tope, pausado) → max(intentos, 1), nunca suma de más (la invariante "más de 2" es la del loop).
  if (s.ok) await avQ(env, `UPDATE avisos_internos SET status = 'enviado', via = ?, wamid = ?, intentos = max(intentos, 1), sent_at = COALESCE(sent_at, ?), updated_at = ? WHERE id IN (${ph})`, ['grupo:' + s.via, s.wamid || null, now, now, ...ids], med);
  else await avQ(env, `UPDATE avisos_internos SET status = ?, error_code = ?, updated_at = ? WHERE id IN (${ph})`, [s.via === 'pausado' ? 'pausado' : 'perdido', String(s.code || s.error || '').slice(0, 120), now, ...ids], med);
}
function _avAgruparPorDest(rows) {
  const m = new Map();
  for (const r of rows) { if (!m.has(r.dest)) m.set(r.dest, { slug: r.dest_slug || '', rows: [] }); m.get(r.dest).rows.push(r); }
  return m;
}
// Cron */5: libera la cola del silencio (fuera del horario de silencio), el excedente del tope (P1 cada 5 min, P2
// cada 15 min; ninguno pasa al día siguiente) y lo que quedó pausado por wa_send_paused cuando se reanuda. Cada
// grupo se RECLAMA con un UPDATE … RETURNING antes de mandar: el flush del webhook y el cron no pueden tomar las
// mismas filas.
async function processAvisosCola(env, cfg, t = {}, med = null) {
  if (!cfg || cfg.modo !== 'on') return;
  const now = new Date().toISOString(), desde = new Date(Date.now() - 24 * 3600e3).toISOString();
  const minute = Number.isFinite(t.minute) ? t.minute : new Date().getUTCMinutes();
  const lotes = [];
  // En el silencio nocturno, el excedente del tope que no es urgente de un vendedor (quedó en 'tope' antes de las
  // 22) no sale de noche: pasa a la cola de la mañana. Gaspar y Bruno reciben a toda hora.
  if (avisoEnSilencio(cfg)) {
    await avQ(env, `UPDATE avisos_internos SET status = 'cola', updated_at = ? WHERE status = 'tope' AND created_at >= ? AND prioridad != 'P1' AND dest_slug NOT IN (${AVISO_SIN_SILENCIO.map(() => '?').join(',')})`, [now, desde, ...AVISO_SIN_SILENCIO], med);
  } else lotes.push(["status = 'cola'", 'Avisos de anoche']);
  lotes.push([minute % 15 < 5 ? "status = 'tope'" : "status = 'tope' AND prioridad = 'P1'", 'Avisos agrupados']);
  if (!cfg.pausado) lotes.push(["status = 'pausado'", 'Avisos que estaban en pausa']);
  for (const [cond, titulo] of lotes) {
    const rows = await avQ(env, `UPDATE avisos_internos SET status = 'enviando', updated_at = ? WHERE id IN (SELECT id FROM avisos_internos WHERE ${cond} AND created_at >= ? ORDER BY id LIMIT 60) AND ${cond} RETURNING id, dest, dest_slug, prioridad, texto, created_at`, [now, desde], med);
    for (const [dest, g] of _avAgruparPorDest(rows)) {
      try { await avisoEnviarAgrupado(env, cfg, dest, g.slug, g.rows.sort((a, b) => a.id - b.id), titulo, med); }
      catch (_) { try { await avQ(env, `UPDATE avisos_internos SET status = 'perdido', updated_at = ? WHERE id IN (${g.rows.map(() => '?').join(',')}) AND status = 'enviando'`, [now, ...g.rows.map(r => r.id)], med); } catch (_) {} }
    }
  }
}
// Webhook de entrada: un interno le escribió al número del negocio → su ventana de 24 h está abierta. Se le manda
// en UN texto lo que no le llegó en las últimas 24 h (cola, tope, perdido, fallido, pausado) y las fotos de los
// avisos que salieron por plantilla (que no pueden llevar foto). Solo en 'on' y con aviso_interno_flush_on='1'.
async function avisoInternoFlush(env, phone) {
  const med = d1Medidor();
  try {
    const cfg = await avisoCfg(env);
    if (cfg.modo !== 'on' || !cfg.flushOn) return;
    if (!(await ensureAvisosSchema(env))) return;
    const dest = _avDig(phone);
    const now = new Date().toISOString(), desde = new Date(Date.now() - 24 * 3600e3).toISOString();
    // via != 'legacy': las fallas del envío de siempre registradas en modo prueba no se reenvían al prender.
    const rows = await avQ(env, "UPDATE avisos_internos SET status = 'enviando', updated_at = ? WHERE dest = ? AND created_at >= ? AND flushed_at IS NULL AND status IN ('cola', 'tope', 'perdido', 'fallido', 'pausado') AND via != 'legacy' RETURNING id, prioridad, texto, created_at", [now, dest, desde], med);
    if (rows.length) {
      rows.sort((a, b) => a.id - b.id);
      const texto = rows.length === 1 ? rows[0].texto : 'Avisos que no te llegaron (' + rows.length + '):\n' + rows.map(r => '• ' + _avHoraTxt(r.created_at) + ' ' + unaLinea(r.texto, 350)).join('\n');
      let r = null;
      try { r = await waSendText(env, dest, texto.slice(0, 4000), { esAviso: true }); } catch (_) {}
      const ids = rows.map(x => x.id), ph = ids.map(() => '?').join(',');
      // El flush NO suma a intentos (contador del envío automático y su único reintento): queda marcado por
      // flushed_at y via 'flush'. Si sumara, un aviso que rebotó, se reintentó y después salió por acá daría 3 y
      // la invariante "más de 2 intentos" (la del loop) saltaría sin que haya ningún loop.
      if (r && r.ok) await avQ(env, `UPDATE avisos_internos SET status = 'enviado', via = 'flush', wamid = ?, flushed_at = ?, sent_at = COALESCE(sent_at, ?), updated_at = ? WHERE id IN (${ph})`, [r.id || null, now, now, now, ...ids], med);
      // Envíos pausados (wa_send_paused): todo a 'pausado' SIN marcar flushed_at, así lo manda la cola apenas se
      // reanudan (lote "Avisos que estaban en pausa"). Antes quedaba 'perdido' y solo salía si la persona volvía a escribir.
      else if (r && r.error === 'wa_send_paused') await avQ(env, `UPDATE avisos_internos SET status = 'pausado', updated_at = ? WHERE id IN (${ph})`, [now, ...ids], med);
      else await avQ(env, `UPDATE avisos_internos SET status = 'perdido', updated_at = ? WHERE id IN (${ph})`, [now, ...ids], med);
    }
    // Fotos pendientes: avisos con media que salieron por plantilla. Reclamo por flushed_at (una sola vez).
    const conFotos = await avQ(env, "UPDATE avisos_internos SET flushed_at = ?, updated_at = ? WHERE dest = ? AND created_at >= ? AND flushed_at IS NULL AND media_keys != '' AND via LIKE 'plantilla:%' RETURNING id, texto, media_keys", [now, now, dest, desde], med);
    for (const a of conFotos) {
      let keys = []; try { keys = JSON.parse(a.media_keys) || []; } catch (_) {}
      if (keys.length) await avisoEnviarMedia(env, dest, keys, unaLinea(a.texto, 200));
    }
  } catch (_) {}
  finally { await avisoMedirFuera(env, med); }
}

// ----- Resumen programado (§2.5: uno solo, con secciones) -----
// Corre en el cron */5 entre :05 y :20 de cada hora de resumen_horas (10, 14, 18 AR), de lunes a sábado; el dedup
// es la clave 'resumen:<fecha>:<hora>:<slug>', así un tick que falla lo levanta el siguiente (objeción [MEDIA]).
// Un mensaje por persona por horario, como P2 'resumen' (sin tope). Secciones: los avisos P3 de esa persona
// (reclamados con UPDATE … RETURNING) + las que sumen otras etapas en RESUMEN_SECCIONES.
// Gancho para la Etapa 2: RESUMEN_SECCIONES.push({ nombre, slugs: async (env, slot) => [slug…],
// texto: async (env, slug, slot) => '' }) — p. ej. sinRespSeccionResumen ("sin responder").
const RESUMEN_SECCIONES = [];
async function processResumenes(env, cfg, t = {}, med = null) {
  if (!cfg || cfg.modo !== 'on') return;
  const hAR = Number.isFinite(t.hAR) ? t.hAR : avisoHoraAR();
  const dowAR = Number.isFinite(t.dowAR) ? t.dowAR : new Date(Date.now() - 3 * 3600e3).getUTCDay();
  const minute = Number.isFinite(t.minute) ? t.minute : new Date().getUTCMinutes();
  if (dowAR === 0 || !cfg.resumenHoras.includes(hAR) || minute < 5 || minute > 20) return;
  const fecha = avisoFechaAR(), slot = { fecha, hora: hAR };
  const now = new Date().toISOString(), desde = new Date(Date.now() - 3 * 24 * 3600e3).toISOString();
  const I = await internosSet(env);
  const dests = new Map();
  for (const r of await avQ(env, "SELECT dest, MAX(dest_slug) AS slug FROM avisos_internos WHERE status = 'digest' AND created_at >= ? GROUP BY dest", [desde], med)) dests.set(r.dest, r.slug || '');
  for (const sec of RESUMEN_SECCIONES) {
    try { for (const sl of (await sec.slugs(env, slot)) || []) { const p = I.bySlug.get(sl); if (p && !dests.has(p)) dests.set(p, sl); } } catch (_) {}
  }
  for (const [dest, slug] of dests) {
    try {
      const clave = 'resumen:' + fecha + ':' + hAR + ':' + (slug || dest);
      if ((await avQ(env, 'SELECT 1 AS x FROM avisos_internos WHERE clave = ?', [clave], med)).length) continue;   // ya salió este horario
      const items = await avQ(env, "UPDATE avisos_internos SET status = 'agrupado', updated_at = ? WHERE dest = ? AND status = 'digest' AND created_at >= ? RETURNING id, tipo, texto, created_at", [now, dest, desde], med);
      items.sort((a, b) => a.id - b.id);
      const partes = [];
      if (items.length) partes.push('Avisos (' + items.length + '):\n' + items.slice(0, 25).map(x => '• ' + _avHoraTxt(x.created_at) + ' ' + unaLinea(x.texto, 250)).join('\n') + (items.length > 25 ? '\n…y ' + (items.length - 25) + ' más (Admin → Avisos internos)' : ''));
      for (const sec of RESUMEN_SECCIONES) { try { const tx = await sec.texto(env, slug, slot); if (tx) partes.push(String(tx)); } catch (_) {} }
      if (!partes.length) continue;
      const texto = ('📋 Resumen de las ' + hAR + ' h\n\n' + partes.join('\n\n')).slice(0, 4000);
      const ins = await avQ(env, "INSERT INTO avisos_internos (clave, dest, dest_slug, tipo, prioridad, texto, status, created_at, updated_at) VALUES (?, ?, ?, 'resumen', 'P2', ?, 'pendiente', ?, ?) ON CONFLICT(clave) DO NOTHING RETURNING id", [clave, dest, slug, texto, now, now], med);
      const rid = ins[0] && ins[0].id;
      const ids = items.map(x => x.id), ph = ids.map(() => '?').join(',');
      if (!rid) {   // otro tick lo mandó justo: los P3 vuelven a esperar al próximo horario
        if (ids.length) await avQ(env, `UPDATE avisos_internos SET status = 'digest', updated_at = ? WHERE id IN (${ph})`, [now, ...ids], med);
        continue;
      }
      const s = await avisoEnviar(env, cfg, { phone: dest, slug, prioridad: 'P2' }, { texto, tipo: 'resumen' }, med);
      await avQ(env, 'UPDATE avisos_internos SET via = ?, decision = ?, wamid = ?, status = ?, error_code = ?, intentos = 1, sent_at = ?, updated_at = ? WHERE id = ?',
        [s.ok ? s.via : '', s.via, s.wamid || null, s.ok ? 'enviado' : (s.via === 'pausado' ? 'pausado' : 'perdido'), s.ok ? '' : String(s.code || s.error || '').slice(0, 120), s.ok ? now : null, now, rid], med);
      if (ids.length) await avQ(env, `UPDATE avisos_internos SET digest_id = ?, updated_at = ? WHERE id IN (${ph})`, [rid, now, ...ids], med);
    } catch (_) {}
  }
}

// ----- Autor de los envíos manuales del CRM -----
// wamid → slug de quien lo mandó (wa_send_author, mig 051). No se usa wa_messages.sender_name: en las plantillas
// guarda al vendedor COMERCIAL ('joaco' por defecto, resolveComercial) y la fila fantasma de status le puede ganar
// al INSERT por wamid. Si falla no importa: el aviso de esa falla va al resumen del dueño en vez de al autor.
// Los endpoints la llaman DESPUÉS de su INSERT en wa_messages y con ctx.waitUntil: esperarla antes le sumaba un viaje
// a la D1 a la carrera con la fila fantasma de status, también con los avisos en off.
async function registrarAutorEnvio(env, wamid, sessionUser, phone) {
  if (!wamid) return;
  const autor = avisoAutorSlug(sessionUser) || String(sessionUser || '').trim().toLowerCase().slice(0, 40);
  if (!autor) return;
  try { await env.DB.prepare('INSERT OR IGNORE INTO wa_send_author (wamid, autor, phone, ts) VALUES (?, ?, ?, ?)').bind(String(wamid), autor, _avDig(phone), new Date().toISOString()).run(); } catch (_) {}
}

// ----- Purga diaria (cron, 5 AR): avisos de +90 días y autores de +14 (los dos por índice de fecha) -----
async function purgarAvisos(env, med = null) {
  await avQ(env, 'DELETE FROM avisos_internos WHERE created_at < ?', [new Date(Date.now() - 90 * 24 * 3600e3).toISOString()], med);
  await avQ(env, 'DELETE FROM wa_send_author WHERE ts < ?', [new Date(Date.now() - 14 * 24 * 3600e3).toISOString()], med);
  // Contadores diarios de filas leídas fuera del cron (avisoMedirFuera) de +7 días: rango por PK de kv_cache, sin LIKE.
  const corte = new Date(Date.now() - 3 * 3600e3 - 7 * 24 * 3600e3).toISOString().slice(0, 10);
  await avQ(env, 'DELETE FROM kv_cache WHERE k >= ? AND k < ?', [AVISO_FILAS_FUERA_KV, AVISO_FILAS_FUERA_KV + corte], med);
}

// ----- Filas leídas FUERA del cron (objeción [ALTA] del plan + revisión) -----
// Lo que leen los avisos desde el webhook y los envíos (registro en dry, avisoInterno en 'on', statuses de internos,
// flush) no pasa por processAvisosTick: sin esto el freno de costo no veía una regresión ahí. Se acumula por isolate
// y se vuelca a kv avisos_filas_fuera:<fecha AR> cada 10 min o cada 2.000 filas (una escritura, suma en SQL). Lo que
// no se volcó cuando el isolate muere se pierde: es un contador aproximado, alcanza para ver una regresión de miles.
const AVISO_FILAS_FUERA_KV = 'avisos_filas_fuera:';
let _avFuera = { filas: 0, at: Date.now() };
async function avisoMedirFuera(env, med) {
  try {
    _avFuera.filas += (med && med.filas) || 0;
    if (_avFuera.filas < 2000 && Date.now() - _avFuera.at < 10 * 60000) return;
    const n = _avFuera.filas;
    _avFuera = { filas: 0, at: Date.now() };
    if (!n) return;
    await env.DB.prepare('INSERT INTO kv_cache (k, v, updated_at) VALUES (?, ?, ?) ON CONFLICT(k) DO UPDATE SET v = CAST(COALESCE(CAST(kv_cache.v AS INTEGER), 0) + CAST(excluded.v AS INTEGER) AS TEXT), updated_at = excluded.updated_at')
      .bind(AVISO_FILAS_FUERA_KV + avisoFechaAR(), String(n), new Date().toISOString()).run();
  } catch (_) {}
}

// ----- Freno de costo de D1 (objeción [ALTA] del plan) -----
// Suma las filas leídas de cada corrida en kv avisos_stats (por día AR). Si una corrida pasa
// aviso_interno_tope_filas_corrida (20k) o el día pasa aviso_interno_tope_filas_dia (200k), apaga los avisos
// (aviso_interno_modo='off': todo vuelve al envío de hoy) y le avisa a Gaspar UNA vez por día.
async function avisosFrenoCosto(env, cfg, med, job) {
  try {
    const fecha = avisoFechaAR(), now = new Date().toISOString();
    let st = {}; try { st = JSON.parse(await kvGet(env, 'avisos_stats', '{}')) || {}; } catch (_) {}
    if (st.fecha !== fecha) st = { fecha, filas: 0, escritas: 0, corridas: 0, max: 0 };
    st.filas += med.filas; st.escritas = (st.escritas || 0) + med.escritas; st.corridas++; st.max = Math.max(st.max || 0, med.filas);
    st.ultima = { at: now, job, filas: med.filas, escritas: med.escritas };
    // + lo que leyeron hoy fuera del cron (webhook, envíos; avisoMedirFuera): el tope del día es sobre el total.
    let fuera = 0;
    try { const r = await env.DB.prepare('SELECT v FROM kv_cache WHERE k = ?').bind(AVISO_FILAS_FUERA_KV + fecha).all(); med.add(r); fuera = parseInt(((r.results || [])[0] || {}).v, 10) || 0; } catch (_) {}
    st.fuera = fuera;
    await kvSet(env, 'avisos_stats', JSON.stringify(st));
    const total = st.filas + fuera;
    const motivo = med.filas > cfg.topeFilasCorrida ? `una corrida de ${job} leyó ${med.filas} filas (tope ${cfg.topeFilasCorrida})`
      : (total > cfg.topeFilasDia ? `hoy los avisos ya leyeron ${total} filas (cron ${st.filas} + webhook y envíos ${fuera}; tope ${cfg.topeFilasDia})` : '');
    if (!motivo) return;
    await kvSet(env, 'aviso_interno_modo', 'off');
    kvManyOlvidar(['aviso_interno_modo']);
    const claim = await env.DB.prepare("INSERT INTO kv_cache (k, v, updated_at) VALUES (?, '1', ?) ON CONFLICT(k) DO NOTHING").bind('avisos_freno:' + fecha, now).run();
    if (!claim || !claim.meta || !claim.meta.changes) return;
    const txt = '🔴 Avisos internos APAGADOS solos por el freno de costo de la D1: ' + motivo + '. Todo volvió al envío de siempre. Revisalo antes de prenderlos de nuevo (Admin → Avisos internos).';
    // El modo ya quedó en off → avisoInterno corre el legacy (plantilla con respaldo de texto, como los avisos de hoy).
    await avisoInterno(env, { para: 'gaspar', tipo: 'freno_costo', prioridad: 'P1', texto: txt, legacy: () => avisoLanzamientoSendLegacy(env, AVISO_SLUGS_FIJOS.gaspar, txt), legacyDest: AVISO_SLUGS_FIJOS.gaspar });
  } catch (_) {}
}
// Tick de los avisos (cron */5): reconciliador siempre que el modo no sea off; cola y resúmenes solo en 'on'; purga a
// las 5 AR. Corre todo en serie dentro de UNA medición (así el freno ve el costo real de la corrida) en vez de tres
// waitUntil sueltos.
async function processAvisosTick(env, t = {}) {
  const med = d1Medidor();
  // La purga corre en cualquier modo: wa_send_author se llena con cada envío manual aunque los avisos estén en off.
  if (t.hAR === 5 && Number.isFinite(t.minute) && t.minute < 5) { try { await purgarAvisos(env, med); } catch (_) {} }
  // El aviso de bloqueo por pago que un envío no mandó porque el que rebotó era un aviso, y su "volvió": en cualquier
  // modo (en off/dry es el mismo mensaje de hoy, a lo sumo 5 min después). 3 lecturas por PK.
  try { await avisoBloqueoPagoCron(env, med); } catch (_) {}
  let cfg = null;
  try { cfg = await avisoCfg(env); } catch (_) { return; }
  if (!cfg || cfg.modo === 'off') return;
  if (!(await ensureAvisosSchema(env))) return;
  try { await avisoInternoReconciliar(env, med); } catch (_) {}
  if (cfg.modo === 'on') {
    try { await processAvisosCola(env, cfg, t, med); } catch (_) {}
    try { await processResumenes(env, cfg, t, med); } catch (_) {}
  }
  await avisosFrenoCosto(env, cfg, med, 'avisos');
}

// ----- Plantillas internas: categoría y estado -----
// Si una plantilla que usan los avisos queda en otra categoría que UTILITY (Meta recategoriza) o en PAUSED/DISABLED/
// REJECTED, la cadena la saltea sola; esto le avisa a Gaspar (P1, una vez por categoría+estado).
const AVISO_TPL_INTERNAS_EXTRA = ['reporte_diario_ventas3', 'reporte_seguir2', 'aviso_cliente_vigilado'];
async function avisoTplCategoriaCheck(env, name, status, category) {
  try {
    const cfg = await avisoCfg(env);
    if (!new Set([...cfg.chain, ...AVISO_TPL_INTERNAS_EXTRA]).has(name)) return;
    const st = String(status || '').toUpperCase(), cat = String(category || '').toUpperCase();
    if (!(['PAUSED', 'DISABLED', 'REJECTED'].includes(st) || (cat && cat !== 'UTILITY'))) return;
    // Clave con la fecha AR: dedup de los eventos repetidos del mismo cambio (webhook + monitor horario), pero si la
    // plantilla vuelve a quedar PAUSED otro día (después de reaprobada) se avisa de nuevo.
    await avisoInterno(env, { para: 'gaspar', tipo: 'plantilla_interna', prioridad: 'P1', clave: 'tplcat:' + name + ':' + cat + st + ':' + avisoFechaAR(),
      texto: `⚠️ La plantilla interna "${name}" quedó ${st || '?'}${cat ? ' · ' + cat : ''}: los avisos ya no la usan (saltan a la siguiente de la cadena). Revisala en 360dialog.` });
  } catch (_) {}
}

// Envíos directos a ADMIN_NOTIFY / al personal de Gaspar que no tenían envoltorio (guardia del lanzamiento, ticket
// de corpóreo, follow-ups de presupuesto fallidos). opts: { tipo, prioridad, to (destino de hoy; por defecto
// ADMIN_NOTIFY_PHONE), mediaKeys, mediaCaption, legacy (si el envío de hoy es más que un texto), clave, refPhone }.
async function avisoAdmin(env, texto, opts = {}) {
  const to = opts.to !== undefined ? opts.to : env.ADMIN_NOTIFY_PHONE;
  const legacy = opts.legacy || (to ? () => waSendText(env, to, texto, { esAviso: true }) : null);
  return avisoInterno(env, {
    para: opts.para || 'gaspar', tipo: opts.tipo || 'admin', prioridad: opts.prioridad || 'P2', texto,
    clave: opts.clave || null, refPhone: opts.refPhone || '', mediaKeys: opts.mediaKeys || [], mediaCaption: opts.mediaCaption || '',
    legacy, legacyDest: to || '',
  });
}
// Prioridad de una falla de envío a un cliente: P1 solo si hay plata en juego (etiqueta POR PAGAR = OC sin pagar);
// si no, P2 (objeción [MEDIA]: el presupuesto de P1 no se puede ir en fallas de FUP que pueden esperar).
async function avisoPrioFalla(env, phone) {
  try { return (await hasPorPagarLabel(env, phone)) ? 'P1' : 'P2'; } catch (_) { return 'P2'; }
}

// ----- Endpoints /admin/avisos* (los llama el handler de /admin/ con la sesión ya validada) -----
// GET  /admin/avisos              → (admin) KPIs del período (?horas=24), config, plantillas, freno de costo y los últimos avisos.
// GET  /admin/avisos/mios?pend=1  → (cualquiera del equipo) sus P1 sin "Lo vi" de las últimas 48 h (banner del front).
//                                   Sin pend: todos los suyos de 48 h. Vacío salvo aviso_interno_modo='on'.
// POST /admin/avisos/visto        → {ids:[…]} "Lo vi" (lo suyo; admin, cualquiera).
// POST /admin/avisos/config       → (admin) perillas en kv: modo, vendedores_on, topes, cadena, silencio, resumen_horas,
//                                   retry_on, flush_on, gaspar_marketing_ok, topes de filas; sync_tpl:true = pasada de
//                                   monitorTemplateStatus ya (completa la categoría de las plantillas apenas se deploya).
// POST /admin/avisos/test         → (admin) {para, texto, prioridad} manda una prueba por el camino 'on' aunque el modo
//                                   sea off/dry (ventana cerrada → plantilla; abierta → texto).
// POST /admin/avisos/reenviar     → (admin) {id} vuelve a mandar ese aviso por la vía que corresponda ahora.
// Devuelve null si el path no es de acá.
async function avisosRoute(env, request, url, path, session, esAdmin) {
  if (path !== '/admin/avisos' && !path.startsWith('/admin/avisos/')) return null;
  if (!(await ensureAvisosSchema(env))) return json({ error: 'avisos_internos sin esquema (falta la migración 051)' }, 503);
  const now = new Date().toISOString();
  const I = await internosSet(env);
  const misDests = () => { const sl = avisoAutorSlug(session.user); return (sl === 'gaspar' ? ['gaspar', 'bruno'] : [sl]).map(s => I.bySlug.get(s)).filter(Boolean); };

  if (request.method === 'GET' && path === '/admin/avisos/mios') {
    const cfg = await avisoCfg(env);
    const dests = misDests();
    if (cfg.modo !== 'on' || !dests.length) return json({ ok: true, modo: cfg.modo, items: [] });
    const pend = url.searchParams.get('pend') === '1';
    const desde = new Date(Date.now() - 48 * 3600e3).toISOString();
    const items = await avQ(env, `SELECT id, tipo, prioridad, texto, ref_phone, dest_slug, status, created_at, visto_at FROM avisos_internos
      WHERE dest IN (${dests.map(() => '?').join(',')}) AND created_at >= ? AND status NOT IN ('dry', 'descartado')${pend ? " AND prioridad = 'P1' AND visto_at IS NULL AND tipo != 'resumen'" : ''}
      ORDER BY id DESC LIMIT ${pend ? 20 : 60}`, [...dests, desde]);
    return json({ ok: true, modo: cfg.modo, items });
  }
  if (request.method === 'POST' && path === '/admin/avisos/visto') {
    let b = {}; try { b = await request.json(); } catch (_) {}
    const ids = (Array.isArray(b.ids) ? b.ids : [b.id]).map(x => parseInt(x, 10)).filter(x => x > 0).slice(0, 100);
    if (!ids.length) return json({ error: 'faltan ids' }, 400);
    const binds = [now, String(session.user || '').slice(0, 40), now, ...ids];
    let extra = '';
    if (!esAdmin) { const d = misDests(); if (!d.length) return json({ error: 'forbidden' }, 403); extra = ` AND dest IN (${d.map(() => '?').join(',')})`; binds.push(...d); }
    const r = await env.DB.prepare(`UPDATE avisos_internos SET visto_at = ?, visto_por = ?, updated_at = ? WHERE id IN (${ids.map(() => '?').join(',')}) AND visto_at IS NULL${extra}`).bind(...binds).run();
    return json({ ok: true, marcados: (r && r.meta && r.meta.changes) || 0 });
  }

  if (!esAdmin) return json({ error: 'forbidden: admin only' }, 403);

  if (request.method === 'GET' && path === '/admin/avisos') {
    const cfg = await avisoCfg(env);
    const horas = Math.max(1, Math.min(24 * 14, parseInt(url.searchParams.get('horas') || '24', 10) || 24));
    const desde = new Date(Date.now() - horas * 3600e3).toISOString();
    const kpis = await avQ(env, 'SELECT prioridad, status, COUNT(*) AS n FROM avisos_internos WHERE created_at >= ? GROUP BY prioridad, status', [desde]);
    const porTipo = await avQ(env, 'SELECT tipo, dest_slug, decision, status, COUNT(*) AS n FROM avisos_internos WHERE created_at >= ? GROUP BY tipo, dest_slug, decision, status ORDER BY n DESC LIMIT 200', [desde]);
    const items = await avQ(env, `SELECT id, clave, dest_slug, tipo, prioridad, texto, ref_phone, via, decision, status, error_code, intentos, created_at, sent_at, delivered_at, read_at, visto_at, visto_por
      FROM avisos_internos WHERE created_at >= ? ORDER BY created_at DESC LIMIT 150`, [desde]);   // ORDER BY created_at (no id): usa idx_avisos_created; con id el planner recorre la tabla entera
    const tplNames = [...new Set([...cfg.chain, 'aviso_lanzamiento', ...AVISO_TPL_INTERNAS_EXTRA])];
    let plantillas = [];
    try { plantillas = await avQ(env, `SELECT name, status, COALESCE(category, '') AS category, updated_at FROM template_status_cache WHERE name IN (${tplNames.map(() => '?').join(',')})`, tplNames); }
    catch (_) { try { plantillas = await avQ(env, `SELECT name, status, '' AS category, updated_at FROM template_status_cache WHERE name IN (${tplNames.map(() => '?').join(',')})`, tplNames); } catch (_) {} }
    let stats = null; try { stats = JSON.parse(await kvGet(env, 'avisos_stats', 'null')); } catch (_) {}
    const usables = (await elegirPlantillaAviso(env, cfg, 'gaspar')).map(t => t.name);
    // Prioridades pisadas por tipo (kv aviso_tipo:<tipo>): rango por PK de kv_cache, sin LIKE.
    let tipos = {};
    try { for (const r of await avQ(env, "SELECT k, v FROM kv_cache WHERE k >= 'aviso_tipo:' AND k < 'aviso_tipo;'")) { if (r.v) tipos[String(r.k).slice(11)] = r.v; } } catch (_) {}
    // Invariantes de la verificación diaria del plan (tienen que dar 0): más de 2 intentos y destino que no es del
    // equipo (wa_internal_phones ∪ agenda_phones). Por rango de fecha (idx_avisos_created). intentos cuenta solo los
    // envíos AUTOMÁTICOS de la fila (el envío y su único reintento): el flush y el reenvío manual no suman, así que
    // "más de 2" es siempre un loop de verdad.
    let invariantes = null;
    try {
      invariantes = (await avQ(env, `SELECT SUM(CASE WHEN intentos > 2 THEN 1 ELSE 0 END) AS mas_de_2,
        SUM(CASE WHEN dest NOT IN (SELECT phone FROM agenda_phones UNION SELECT phone FROM wa_internal_phones) THEN 1 ELSE 0 END) AS dest_externo
        FROM avisos_internos WHERE created_at >= ?`, [desde]))[0] || null;
    } catch (_) {}
    return json({ ok: true, modo: cfg.modo, horas, config: cfg, kpis, por_tipo: porTipo, items, plantillas, plantillas_usables: usables, stats, tipos, invariantes });
  }
  if (request.method === 'POST' && path === '/admin/avisos/config') {
    let b = {}; try { b = await request.json(); } catch (_) {}
    const set = [];
    if (b.modo != null) { const m = String(b.modo); if (!['off', 'dry', 'on'].includes(m)) return json({ error: 'modo: off | dry | on' }, 400); set.push(['aviso_interno_modo', m]); }
    for (const [k, kvk] of [['vendedores_on', 'aviso_interno_vendedores_on'], ['gaspar_marketing_ok', 'aviso_interno_gaspar_marketing_ok'], ['retry_on', 'aviso_interno_retry_on'], ['flush_on', 'aviso_interno_flush_on']]) {
      if (typeof b[k] === 'boolean') set.push([kvk, b[k] ? '1' : '0']);
    }
    for (const [k, kvk, max] of [['tope_hora', 'aviso_interno_tope_hora', 500], ['tope_p1_hora', 'aviso_interno_tope_p1_hora', 500], ['tope_global_hora', 'aviso_interno_tope_global_hora', 5000],
      ['tope_filas_corrida', 'aviso_interno_tope_filas_corrida', 10000000], ['tope_filas_dia', 'aviso_interno_tope_filas_dia', 100000000]]) {
      if (b[k] == null) continue;
      const n = parseInt(b[k], 10);
      if (!(n >= 0 && n <= max)) return json({ error: k + ': número entre 0 y ' + max }, 400);
      set.push([kvk, String(n)]);
    }
    if (b.tpl_chain != null) {
      const arr = (Array.isArray(b.tpl_chain) ? b.tpl_chain : String(b.tpl_chain).split(',')).map(x => String(x).trim()).filter(Boolean);
      if (!arr.length || arr.length > 6 || !arr.every(x => /^[a-z0-9_]{1,80}$/.test(x))) return json({ error: 'tpl_chain: lista de nombres de plantilla (a-z, 0-9, _)' }, 400);
      set.push(['aviso_interno_tpl_chain', JSON.stringify(arr)]);
    }
    if (b.silencio != null) {
      const m = String(b.silencio).trim().match(/^(\d{1,2})-(\d{1,2})$/);
      if (!m || +m[1] > 23 || +m[2] > 23) return json({ error: 'silencio: "desde-hasta" en horas AR, p. ej. 22-8' }, 400);
      set.push(['aviso_interno_silencio', (+m[1]) + '-' + (+m[2])]);
    }
    if (b.resumen_horas != null) {
      const hs = [...new Set(String(b.resumen_horas).split(',').map(x => parseInt(x, 10)).filter(h => h >= 0 && h <= 23))].sort((x, y) => x - y);
      if (!hs.length) return json({ error: 'resumen_horas: horas AR separadas por coma, p. ej. 10,14,18' }, 400);
      set.push(['resumen_horas', hs.join(',')]);
    }
    // tipos: { <tipo>: 'P1' | 'P2' | 'P3' | '' } → kv aviso_tipo:<tipo> ('' vuelve a la prioridad del código).
    if (b.tipos != null) {
      if (typeof b.tipos !== 'object' || Array.isArray(b.tipos)) return json({ error: 'tipos: {tipo: "P1"|"P2"|"P3"|""}' }, 400);
      for (const [tp, pr] of Object.entries(b.tipos).slice(0, 40)) {
        const p = String(pr || '').toUpperCase();
        if (!AVISO_TIPO_RE.test(tp) || (p && !AVISO_PRIOS.includes(p))) return json({ error: 'tipos: ' + tp + ' → P1, P2, P3 o vacío' }, 400);
        if (p && AVISO_TIPOS_PRIO_FIJA.includes(tp)) return json({ error: 'tipos: la prioridad de "' + tp + '" no se puede cambiar' }, 400);
        set.push(['aviso_tipo:' + tp, p]);
      }
    }
    for (const [k, v] of set) await kvSet(env, k, v);
    kvManyOlvidar(AVISO_KV);
    kvManyOlvidar(set.map(x => x[0]).filter(k => k.startsWith('aviso_tipo:')));
    let sync = false;
    if (b.sync_tpl) { try { await monitorTemplateStatus(env); sync = true; } catch (_) {} }
    return json({ ok: true, cambiados: set.map(x => x[0]), sync, config: await avisoCfg(env) });
  }
  if (request.method === 'POST' && path === '/admin/avisos/test') {
    let b = {}; try { b = await request.json(); } catch (_) {}
    const para = String(b.para || 'gaspar').trim();
    const prio = AVISO_PRIOS.includes(b.prioridad) ? b.prioridad : 'P2';
    const texto = String(b.texto || ('Prueba de avisos internos del CRM · ' + _avHoraTxt(now) + ' h')).slice(0, 1500);
    const res = await avisoInterno(env, { para, tipo: 'test', prioridad: prio, texto, forzarOn: true, sinRedireccion: true });
    return json({ ok: !!(res && res.ok), res });
  }
  if (request.method === 'POST' && path === '/admin/avisos/reenviar') {
    let b = {}; try { b = await request.json(); } catch (_) {}
    const id = parseInt(b.id, 10);
    if (!(id > 0)) return json({ error: 'falta id' }, 400);
    // Reclamo atómico: si el cron, un flush o el reintento del webhook lo están mandando ('enviando', 'reintentando',
    // 'pendiente'), no se pisa (si se cortó a mitad, el reconciliador lo pasa a 'sin_confirmar' a los 15 min).
    const rows = await avQ(env, "UPDATE avisos_internos SET status = 'enviando', updated_at = ? WHERE id = ? AND status NOT IN ('enviando', 'pendiente', 'reintentando') RETURNING id, dest, dest_slug, prioridad, texto, media_keys", [now, id]);
    if (!rows.length) return json({ error: 'no existe o se está mandando ahora' }, 409);
    const a = rows[0];
    let keys = []; try { keys = a.media_keys ? (JSON.parse(a.media_keys) || []) : []; } catch (_) {}
    const s = await avisoEnviar(env, await avisoCfg(env), { phone: a.dest, slug: a.dest_slug, prioridad: a.prioridad }, { texto: a.texto, mediaKeys: keys, tipo: 'reenvio' });
    // El reenvío manual no suma a intentos (es el contador del envío automático y su reintento; ver el flush): queda
    // marcado por via 'reenvio:…' y wamid_prev.
    if (s.ok) await avQ(env, "UPDATE avisos_internos SET status = 'enviado', via = ?, wamid_prev = wamid, wamid = ?, sent_at = ?, error_code = '', updated_at = ? WHERE id = ?", ['reenvio:' + s.via, s.wamid || null, now, now, id]);
    else await avQ(env, 'UPDATE avisos_internos SET status = ?, error_code = ?, updated_at = ? WHERE id = ?', [s.via === 'pausado' ? 'pausado' : 'perdido', String(s.code || s.error || '').slice(0, 120), now, id]);
    return json({ ok: !!s.ok, via: s.via, error: s.ok ? undefined : (s.error || 'no salió') });
  }
  return json({ error: 'not found' }, 404);
}

// Manda un aviso del lanzamiento a un número interno: plantilla aviso_lanzamiento (porque
// Gaspar/Bruno casi siempre están FUERA de la ventana 24h) con fallback a texto libre.
// [Etapa 1] Es el envío "de hoy" (legacy) que envuelve avisoLanzamientoSend. Todo sale con esAviso.
async function avisoLanzamientoSendLegacy(env, ph, texto) {
  const E = { esAviso: true };
  const t = String(texto || '').replace(/\s+/g, ' ').trim().slice(0, 300);  // 1 línea (Meta rechaza \n / 4+ espacios en params)
  // Ventana de 24h abierta (escribió al número del negocio hace <23h) → texto libre primero: llega seguro
  // y no choca con el tope de plantillas de marketing por usuario de Meta (131049: a Bruno se le perdían
  // los avisos de pago del lanzamiento). Con la ventana cerrada, plantilla como antes.
  try {
    const desde = new Date(Date.now() - 23 * 3600 * 1000).toISOString();
    const inb = await env.DB.prepare("SELECT 1 AS x FROM wa_messages WHERE phone = ? AND direction = 'inbound' AND msg_type NOT IN ('status', 'reaction') AND ts > ? LIMIT 1").bind(String(ph || '').replace(/\D/g, ''), desde).first();
    if (inb) {
      const r0 = await waSendText(env, ph, '🚀 Lanzamiento Neon\n' + String(texto || '').trim().slice(0, 1500), E);
      if (r0 && r0.ok) return r0;
    }
  } catch (_) {}
  let r = null;
  // Ventana cerrada → plantilla de SERVICIO (UTILITY): no tiene el tope de marketing por usuario (131049).
  // aviso_interno_crm cuando Meta la apruebe; mientras tanto, a Bruno (al que la MARKETING le rebota) el
  // puente recordatorio_agenda (UTILITY ya aprobada, {{1}} libre). Si no, aviso_lanzamiento como antes.
  const tLargo = String(texto || '').replace(/\s+/g, ' ').trim().slice(0, 800);
  try {
    const ok = await env.DB.prepare("SELECT 1 AS x FROM template_status_cache WHERE name = 'aviso_interno_crm' AND upper(status) = 'APPROVED'").first();
    if (ok) r = await waSendTemplate(env, ph, 'aviso_interno_crm', 'es_AR', [tLargo], null, E);
    else if (String(ph || '').replace(/\D/g, '') === '5491155604996') r = await waSendTemplate(env, ph, 'recordatorio_agenda', 'es_AR', [tLargo], null, E);
  } catch (_) {}
  if (!r || !r.ok) { try { r = await waSendTemplate(env, ph, 'aviso_lanzamiento', 'es_AR', [t], null, E); } catch (_) {} }
  if (!r || !r.ok) { try { r = await waSendText(env, ph, '🚀 Lanzamiento Neon\n' + t, E); } catch (_) {} }
  return r;
}
// Envoltorio de avisoInterno: en off/dry corre avisoLanzamientoSendLegacy tal cual y devuelve SU resultado (los
// llamadores miran r.ok); en 'on' la vía la elige avisoInterno. opts: { tipo, prioridad, clave, refPhone, para }.
async function avisoLanzamientoSend(env, ph, texto, opts = {}) {
  const dest = String(ph || '').replace(/\D/g, '');
  const res = await avisoInterno(env, {
    para: opts.para || dest, tipo: opts.tipo || 'lanzamiento', prioridad: opts.prioridad || 'P2', texto,
    clave: opts.clave || null, refPhone: opts.refPhone || '', plata: !!opts.plata,
    legacy: () => avisoLanzamientoSendLegacy(env, ph, texto), legacyDest: dest,
  });
  return res && res.modo !== 'on' ? res.legacy : res;
}

// ===== Aviso de PLANTILLA FALLIDA (a Bruno + Gaspar) — pedido Bruno 3-sep =====
// Cuando falla una plantilla de VENTA/SEGUIMIENTO (las que Bruno/Joaco mandan a los leads: adhoc,
// presupuesto_*, cotizamos, aviso_presupuesto_listo, cambionro, etc.), avisar al toque a Bruno y a
// Gaspar para que la escriban a mano. Se EXCLUYEN las campañas masivas (broadcasts) que rebotan a
// montones y solo harían ruido. Anti-loop: destinatarios internos ya excluidos en el hook; el aviso
// va por plantilla aviso_lanzamiento (que ES campaña masiva → nunca se re-rutea) con fallback a texto.
function esCampanaMasiva(name) {
  const n = String(name || '').toLowerCase();
  if (/^(minisupernova|minicurso|lanzamiento|cupo_comunidad|seminario|sorteo|comunidad|pack_emprendedor|reporte_)/.test(n)) return true;
  if (n === 'aviso_lanzamiento' || n === 'aviso_arranque_equipo' || n === 'aviso_interno_crm') return true;
  return false;
}
// ¿El envío que falló fue de un broadcast del panel? = a ese teléfono le salió una fila 'bc_<id>' en las
// 24h anteriores (los broadcasts guardan el texto en vez del marcador [plantilla: x]).
async function esEnvioDeBroadcast(env, phone, tsIso) {
  try {
    const desde = new Date((Date.parse(tsIso) || Date.now()) - 24 * 3600 * 1000).toISOString();
    const r = await env.DB.prepare("SELECT 1 AS x FROM wa_autoreply_log WHERE phone = ? AND kind LIKE 'bc!_%' ESCAPE '!' AND sent_at >= ? LIMIT 1").bind(String(phone || ''), desde).first();
    return !!r;
  } catch (_) { return false; }
}
// [Etapa 1] wamid = el envío que falló (para avisarle a su AUTOR, wa_send_author). soloLegacy = el "cliente" es en
// realidad alguien del equipo fuera de la guardia vieja (solo pasa en off/dry): sale lo de hoy, sin registrar
// (esa falla ya la registra avisoInternoStatus como falla_interna).
async function notifyTplFail(env, { name, phone, reason, wamid, soloLegacy } = {}) {
  try {
    const ph = String(phone || '').replace(/\D/g, '');
    if (!ph || !name) return;
    const fecha = new Date(Date.now() - 3 * 3600 * 1000).toISOString().slice(0, 10);
    const dk = 'tplfail:' + name + ':' + ph + ':' + fecha;   // dedup por plantilla+phone+día
    try { const seen = await env.DB.prepare("SELECT 1 AS x FROM kv_cache WHERE k = ?").bind(dk).first(); if (seen) return; } catch (_) {}
    // Tope global de avisos por hora (evita flood si Meta falla en masa).
    const hourKey = 'tplfail_h:' + new Date().toISOString().slice(0, 13);
    let cnt = 0;
    try { const c = await env.DB.prepare("SELECT v FROM kv_cache WHERE k = ?").bind(hourKey).first(); cnt = c ? (parseInt(c.v, 10) || 0) : 0; } catch (_) {}
    if (cnt >= 15) return;
    // Marcar dedup + contador ANTES de enviar (evita doble por sync+async o concurrencia).
    const nowIso = new Date().toISOString();
    try { await env.DB.prepare("INSERT OR IGNORE INTO kv_cache (k, v, updated_at) VALUES (?, '1', ?)").bind(dk, nowIso).run(); } catch (_) {}
    try { await env.DB.prepare("INSERT INTO kv_cache (k, v, updated_at) VALUES (?, '1', ?) ON CONFLICT(k) DO UPDATE SET v = CAST(kv_cache.v AS INTEGER) + 1, updated_at = excluded.updated_at").bind(hourKey, nowIso).run(); } catch (_) {}
    const texto = 'Falló una plantilla a +' + ph + ': ' + (reason || 'no se pudo enviar') + '. Fijate de escribirle a mano.';
    // Lo de hoy: a Bruno + Gaspar con avisoLanzamientoSendLegacy (plantilla con texto de respaldo).
    const legacy = async () => {
      const porDest = {};
      for (const dest of ['5491155604996', '5491155604999']) {   // Bruno + Gaspar
        let r = null; try { r = await avisoLanzamientoSendLegacy(env, dest, texto); } catch (_) {}
        porDest[dest] = r;
      }
      return { ok: Object.values(porDest).some(x => x && x.ok), porDest };
    };
    if (soloLegacy) { await legacy(); return; }
    // Etapa 1: al AUTOR de la plantilla (si fue un envío automático, al resumen del dueño del chat), Bruno P2 y
    // copia P3 a Gaspar. P2, o P1 si el chat tiene plata en juego (objeción [MEDIA]).
    // try propio: si esto tirara, el envío de hoy (legacy) igual tiene que salir.
    let prio = 'P2';
    try { if ((await avisoCfg(env)).modo !== 'off') prio = await avisoPrioFalla(env, ph); } catch (_) {}
    await avisoInterno(env, {
      para: [{ autor: wamid || '', phone: ph, prioridad: prio }, { slug: 'bruno', prioridad: 'P2' }, { slug: 'gaspar', prioridad: 'P3' }],
      tipo: 'falla_plantilla', prioridad: prio, texto, clave: 'tplfail:' + name + ':' + ph + ':' + fecha, refPhone: ph, legacy,
    });
  } catch (_) {}
}

// Pin a la bandeja PRIVADA (pedido Bruno 3-sep): marca el chat para que ADEMÁS aparezca en la
// bandeja privada, SIN sacarlo de su bandeja actual (no toca inbox). Se llama cuando Bruno manda
// un mensaje/plantilla con su firma. El flag pin_privado lo incluye la lista de chats y el front
// lo suma a la vista privada. Un-pin: /admin/wa/private-toggle {on:false} lo limpia.
async function pinPrivadoBruno(env, phone) {
  const ph = String(phone || '').replace(/\D/g, '');
  if (!ph) return;
  try { await env.DB.prepare("UPDATE wa_chats_summary SET pin_privado = 1 WHERE phone = ?").bind(ph).run(); } catch (_) {}
}
// Auto-heal de la columna wa_chats_summary.pin_privado (una vez por isolate): así el SELECT de la
// lista de chats nunca rompe por 'no such column' si se deploya contra una D1 sin la migración.
let _pinPrivadoColOk = false;
async function ensurePinPrivadoCol(env) {
  if (_pinPrivadoColOk) return;
  try { await env.DB.prepare("ALTER TABLE wa_chats_summary ADD COLUMN pin_privado INTEGER DEFAULT 0").run(); } catch (_) {}
  _pinPrivadoColOk = true;
}

// Por cada pago del lanzamiento detectado: (1) el aviso inicial "ya arrancaron" una sola vez
// (marca kv SOLO si salió OK, así no se pierde si la plantilla aún no está aprobada), (2) el
// aviso del pago con nombre + teléfono + importe + si es seña. A Gaspar y Bruno.
// [Etapa 1] Los dos pasan por avisoInterno con lo de hoy como legacy. En 'on': el inicial se deduplica con la
// clave 'pago_inicial:<inicio de la ventana>' (en la Etapa 4 pasa a cfg.desde) y el pago va al dueño del chat
// (Abril en cursos) P1 + Bruno P2 + Gaspar P2, decisión de Gaspar del 12-oct. Es plata confirmada (OCR): el P1
// sale aunque sea de noche. wamid = el del comprobante (clave 'pago_ocr:'+wamid).
async function avisoPagoLanzamiento(env, { nombre, phone, monto, esSena, wamid }) {
  const fmt = (n) => '$' + String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  const who = (nombre && String(nombre).trim()) || phone;
  try {
    // La marca de siempre (kv lanzamiento_aviso_inicial, se borra a mano en cada lanzamiento) manda en los tres
    // modos: si ya está, no hay aviso inicial ni fila (en 'on' tampoco: si no, al prender los avisos a mitad de un
    // lanzamiento el "ya arrancaron" saldría de nuevo, porque la clave por ventana es nueva).
    const seen = await env.DB.prepare("SELECT 1 FROM kv_cache WHERE k = 'lanzamiento_aviso_inicial'").first();
    if (!seen) {
      const ini = 'Ya arrancaron a entrar pagos! 🎉';
      const marcar = async () => { try { await env.DB.prepare("INSERT OR IGNORE INTO kv_cache (k, v, updated_at) VALUES ('lanzamiento_aviso_inicial','1',?)").bind(new Date().toISOString()).run(); } catch (_) {} };
      const legacyIni = async () => {
        let anyOk = false; const porDest = {};
        for (const p of REPORTE_DIARIO_PHONES) { const r = await avisoLanzamientoSendLegacy(env, p, ini); porDest[p] = r; if (r && r.ok) anyOk = true; }
        if (anyOk) await marcar();
        return { ok: anyOk, porDest };
      };
      const r = await avisoInterno(env, { para: ['gaspar', 'bruno'], tipo: 'pago_inicial', prioridad: 'P2', texto: ini, clave: 'pago_inicial:' + PAGO_LANZAMIENTO_START_UTC, plata: true, legacy: legacyIni });
      // En 'on' la clave ya deduplica (y lo que no salió lo levantan el flush o el panel): se marca igual, así el
      // camino viejo nunca lo repite si se vuelve a off/dry.
      if (r && r.modo === 'on' && !r.error) await marcar();
    }
  } catch (_) {}
  const detalle = 'Nuevo pago 💰 ' + String(who).slice(0, 40) + ' · ' + phone + (monto > 0 ? (' · ' + fmt(monto)) : '') + (esSena ? ' (seña ~40k)' : '');
  try {
    const legacy = async () => {
      const porDest = {};
      for (const p of REPORTE_DIARIO_PHONES) { let r = null; try { r = await avisoLanzamientoSendLegacy(env, p, detalle); } catch (_) {} porDest[p] = r; }
      return { ok: Object.values(porDest).some(x => x && x.ok), porDest };
    };
    await avisoInterno(env, {
      para: [{ duenio: phone, prioridad: 'P1' }, { slug: 'bruno', prioridad: 'P2' }, { slug: 'gaspar', prioridad: 'P2' }],
      tipo: 'pago_ocr', prioridad: 'P1', texto: detalle, clave: wamid ? 'pago_ocr:' + wamid : null, refPhone: phone, plata: true, legacy,
    });
  } catch (_) {}
}

// ===== Transcripción de audio con Gemini (transcribe MUCHO mejor el español
// rioplatense que Whisper). Devuelve el texto o null. =====
async function transcribeAudioGemini(env, r2Key) {
  if (!env.GEMINI_API_KEY || !env.MEDIA || !r2Key) return null;
  try {
    const obj = await env.MEDIA.get(r2Key);
    if (!obj) return null;
    const buf = await obj.arrayBuffer();
    if (!buf || buf.byteLength < 64 || buf.byteLength > 20 * 1024 * 1024) return null; // vacío o >20MB
    let mime = String(obj.httpMetadata?.contentType || 'audio/ogg').split(';')[0].trim().toLowerCase();
    if (!/^audio\//.test(mime)) mime = 'audio/ogg';
    const model = env.GEMINI_AUDIO_MODEL || 'gemini-2.5-flash';
    const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${env.GEMINI_API_KEY}`;
    const prompt = 'Transcribí literalmente este audio de WhatsApp hablado en español rioplatense (Argentina). Es una conversación real sobre carteles de neón LED: medidas en centímetros, colores, diseños, logos, presupuestos, envíos, pagos. Devolvé SOLO el texto transcripto tal cual lo dice la persona, sin comillas, sin corchetes, sin aclaraciones ni traducción. Si el audio no tiene habla o no se entiende nada, devolvé exactamente una cadena vacía.';
    const body = {
      contents: [{ parts: [{ text: prompt }, { inline_data: { mime_type: mime, data: abToBase64(buf) } }] }],
      generationConfig: { temperature: 0 }
    };
    // timeout: la transcripción corre dentro del webhook; si Gemini se cuelga,
    // abortamos y el caller cae a Whisper (no bloqueamos el procesamiento del mensaje).
    const resp = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body), signal: AbortSignal.timeout(20000) });
    if (!resp.ok) return null;
    const data = await resp.json().catch(() => null);
    if (!data) return null;
    try { await geminiTrackUsage(env, model, 'transcribe', data?.usageMetadata, ''); } catch (_) {}
    const txt = (data?.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('').trim();
    return txt ? txt.replace(/^\[audio\]\s*/i, '').trim() : null;
  } catch (e) { console.error('gemini transcription error:', e); return null; }
}

// ===== Audio transcription. Gemini primero (mejor rioplatense); si no está
// configurado o falla, cae a Whisper (Workers AI). =====
async function transcribeAudio(env, r2Key) {
  if (!env.MEDIA || !r2Key) return null;
  if (env.GEMINI_API_KEY) {
    try { const g = await transcribeAudioGemini(env, r2Key); if (g) return g; } catch (_) {}
  }
  if (!env.AI) return null;
  try {
    const obj = await env.MEDIA.get(r2Key);
    if (!obj) return null;
    const bytes = await obj.arrayBuffer();
    const audioArr = [...new Uint8Array(bytes)];
    // Prompt contextual: ayuda al modelo a reconocer terminología específica
    // (carteles de neón, jerga rioplatense, productos, medidas, etc.) que
    // mejora notablemente la calidad de transcripción para Neon Infinito.
    const initialPrompt = 'Conversación en español rioplatense argentino sobre carteles de neón LED, presupuestos, medidas en centímetros, m², colores, pedidos, envíos, pagos, controladores, fuentes, transparente, negro, base, neón, dimmer, instalación, cliente.';
    let result;
    try {
      result = await env.AI.run('@cf/openai/whisper-large-v3-turbo', {
        audio: audioArr,
        language: 'es',
        task: 'transcribe',
        vad_filter: true,
        initial_prompt: initialPrompt
      });
    } catch (e1) {
      // Fallback al modelo base si el turbo falla
      try {
        result = await env.AI.run('@cf/openai/whisper-large-v3-turbo', {
          audio: audioArr,
          language: 'es'
        });
      } catch (e2) {
        result = await env.AI.run('@cf/openai/whisper', {
          audio: audioArr,
          language: 'es'
        });
      }
    }
    return result?.text || null;
  } catch (e) {
    console.error('transcription error:', e);
    return null;
  }
}

async function logWaEvent(env, { to, kind, ref, ok, messageId, error }) {
  try {
    await env.DB.prepare(
      'INSERT INTO wa_log (ts, to_number, kind, ref, ok, message_id, error) VALUES (?, ?, ?, ?, ?, ?, ?)'
    ).bind(new Date().toISOString(), to || '', kind || '', ref || '', ok ? 1 : 0, messageId || '', error || '').run();
  } catch (_) { /* tabla puede no existir aun en primera deploy */ }
}

// El admin puede entrar tipeando "gaspar"/"GASPAR" y el login guardaba lo tipeado, pero los controles "solo Gaspar"
// comparan exacto con 'Gaspar' → esas sesiones daban 403 (Funnel de Ads, costos, etc.). Se canoniza al leer la
// sesión (arregla las viejas) y al crearla.
function canonSessionUser(u) {
  const s = String(u || '');
  return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim() === 'gaspar' ? 'Gaspar' : s;
}

async function getSession(env, request) {
  const auth = request.headers.get('Authorization') || '';
  const m = auth.match(/^Bearer\s+(.+)$/i);
  if (!m) return null;
  const token = m[1].trim();
  const row = await env.DB.prepare(
    'SELECT user, expires_at FROM sessions WHERE token = ?'
  ).bind(token).first();
  if (!row) return null;
  if (new Date(row.expires_at) < new Date()) return null;
  return { token, user: canonSessionUser(row.user) };
}

// Mapea el slug del usuario (del nombre que manda el front) a los posibles ids
// en users_panel. Cubre alias históricos: Joaquín↔joaco y Abril↔cursos (el
// botón del selector dice "Abril" pero el usuario en la base es 'cursos').
function userLookupIds(slug) {
  if (slug === 'joaquin' || slug === 'joaco') return ['joaquin', 'joaco'];
  if (slug === 'abril' || slug === 'cursos') return ['abril', 'cursos'];
  if (String(slug || '').replace(/[\s._-]+/g, '') === 'sinfrontera') return ['sinfrontera']; // "Sin Frontera" (con espacio) → su id
  return [slug];
}

// Emma (diseñador) nunca ve de qué vendedor es un brief (Gaspar 17-oct): sin comercial_id, enviado_por ni la comisión (su
// proporción con el precio delata al vendedor). Se usa en todas las respuestas de /admin/briefs* para el rol 'disenador'.
function briefSinVendedor(b) { if (!b) return b; const o = { ...b }; delete o.comercial_id; delete o.enviado_por; delete o.comision_joaco; return o; }
// Pieza de corte para quien no es admin: sin el vendedor (ni el "vendió X" que traían las aclaraciones viejas).
function cortePiezaSinVendedor(r) { if (!r) return r; delete r.vendedor; if (r.aclaraciones) r.aclaraciones = String(r.aclaraciones).replace(/\s*·?\s*vendió [^·]*$/i, '').trim(); return r; }

// ===================== SIN FRONTERA (usuario externo) =====================
// Sin Frontera fabrica nuestros corpóreos y además nos compra neón. Tiene un usuario propio ('sinfrontera', lo crea Gaspar
// poniéndole contraseña) que ve SOLO dos cosas: (1) Producción: los corpóreos con ticket, sin precio ni datos del cliente, y
// les cambia el estado; (2) Mis pedidos: sus compras de neón (por sus números o vinculadas a mano) como las ve Gaspar pero
// sin lo interno. Se reconoce por el NOMBRE, como logística (getSessionRole cae a 'comercial' si falla la base): el muro de
// /admin/, la agenda y sesionInterna lo frenan fuera de /admin/sinfrontera/*. Vale "Sin Frontera", "sinfrontera", "sin-frontera".
function esUsuarioSinFrontera(userName) { return String(userName || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[\s._-]+/g, '') === 'sinfrontera'; }
// Estados del corpóreo que actualiza Sin Frontera (Gaspar, 15-oct). Se guardan en pedidos.prod_estado, la misma columna que la
// producción de neón (allá: pendiente / en_armado / terminado; un pedido es neón o corpóreo, nunca los dos). '' = por empezar.
const SF_ESTADOS = [['en_diseno', 'En diseño'], ['en_impresion', 'En impresión'], ['en_ensamble', 'En ensamble'], ['listo', 'Listo para entregar'], ['entregado', 'Entregado']];
// Campos del ticket que ven: los del formulario actual (TICKET_CORP_SECS del front). Lista CERRADA: los tickets del 21-sep
// tenían nombre, teléfono, mail y dirección del cliente, y eso no se muestra. Ningún campo del ticket tiene precio.
const SF_TICKET_CAMPOS = ['empresa', 'fecha_sena', 'fecha_compromiso', 'producto', 'tipo_producto', 'carteleria', 'precisa_instalacion', 'prioridad', 'medidas', 'descripcion_cliente', 'requiere_estructura', 'desc_diseno', 'impresora', 'colores', 'desc_impresion', 'salida_cables', 'lado_cables', 'tipo_luz', 'desc_ensamble'];
// Lo que ven de SUS pedidos: lo de la tabla de Pedidos menos lo interno (vendedor, quién cargó, comisión, anuncio y campaña,
// productor y su mano de obra, origen, espejo a la planilla, cajas, comprobantes).
const SF_PEDIDO_CAMPOS = ['id', 'numero', 'fecha', 'cartel', 'colores', 'alto', 'ancho', 'base', 'tipo', 'cantidad', 'dimer', 'precio', 'precio_dimmer', 'envio', 'aclaracion', 'estado_pedido', 'es_corporeo', 'producto', 'frente', 'laterales', 'espalda', 'iluminacion', 'bastidor', 'color_bastidor', 'instalacion', 'prod_estado', 'prod_terminado_at'];
let _sfSchemaOk = false;
async function ensureSinFronteraSchema(env) {
  if (_sfSchemaOk) return;
  await ensureProdSchema(env); // pedidos.prod_estado / prod_estado_at y pedido_prod_log (producción de neón, migración 053)
  await env.DB.prepare('CREATE TABLE IF NOT EXISTS sinfrontera_pedidos (pedido_id INTEGER PRIMARY KEY, por TEXT, at TEXT)').run();
  // Corpóreos que NO hace Sin Frontera (los fabrica otro o se cancelaron): Gaspar los saca de su tablero (16-oct, OMA pastilla).
  await env.DB.prepare('CREATE TABLE IF NOT EXISTS sinfrontera_excluidos (pedido_id INTEGER PRIMARY KEY, por TEXT, at TEXT)').run();
  _sfSchemaOk = true;
}
// Números con los que compra Sin Frontera (kv sinfrontera_tels, JSON): celular normalizado (549…) o @usuario de Instagram
// (los pedidos que entran por IG guardan el @ en telefono).
function sfNormTels(lista) {
  const out = [];
  for (const x of (Array.isArray(lista) ? lista : [])) {
    const s = String(x || '').trim();
    if (!s) continue;
    let t = '';
    if (/^@[\w.]{2,40}$/.test(s)) t = s.toLowerCase();
    else { const d = s.replace(/\D/g, ''); if (d.length >= 10 && d.length <= 15) t = normalizeArPhone(s) || d; }
    if (t && !out.includes(t)) out.push(t);
  }
  return out.slice(0, 20);
}
async function sfTels(env) { try { return sfNormTels(JSON.parse((await kvGet(env, 'sinfrontera_tels', '[]')) || '[]')); } catch (_) { return []; } }
// Filtro de SUS pedidos: por sus números (últimos 10 dígitos: matchea con o sin 54/9) o @usuario, más los vinculados a mano
// (sinfrontera_pedidos). Columnas calificadas con "pedidos." para pedidosConDiseno.
function sfPedidosWhere(tels) {
  const dig = [...new Set(tels.filter(t => !t.startsWith('@')).map(t => t.replace(/\D/g, '').slice(-10)).filter(t => t.length === 10))];
  const ig = tels.filter(t => t.startsWith('@'));
  const conds = ['pedidos.id IN (SELECT pedido_id FROM sinfrontera_pedidos)'], args = [];
  const tel = "replace(replace(replace(IFNULL(pedidos.telefono, ''), '+', ''), ' ', ''), '-', '')";
  if (dig.length) { conds.push(`(length(${tel}) BETWEEN 10 AND 13 AND ${tel} NOT GLOB '*[^0-9]*' AND substr(${tel}, -10) IN (${dig.map(() => '?').join(',')}))`); args.push(...dig); }
  if (ig.length) { conds.push(`lower(IFNULL(pedidos.telefono, '')) IN (${ig.map(() => '?').join(',')})`); args.push(...ig); }
  return { sql: '(' + conds.join(' OR ') + ')', args };
}
// Producción: un renglón por corpóreo con ticket (el último ticket de cada pedido). Del ticket, solo SF_TICKET_CAMPOS; del
// pedido, lo que hace falta para fabricar. NUNCA precio, pago, teléfono, vendedor ni la aclaración libre del pedido (ya va en
// el ticket como "Descripción del cliente"). Sin estado propio y el pedido ya figura Entregado → se muestra entregado.
async function sfProduccion(env, opts = {}) {
  let rows = [];
  try {
    rows = (await env.DB.prepare(
      `SELECT t.id AS tid, t.numero, t.pedido_id, t.data, t.photo_keys, t.created_at,
              p.fecha, p.cartel, p.alto, p.ancho, p.cantidad, p.producto, p.frente, p.laterales, p.espalda, p.iluminacion,
              p.bastidor, p.color_bastidor, p.instalacion, p.foto_diseno_key, IFNULL(p.prod_estado, '') AS prod_estado, p.prod_estado_at,
              IFNULL(p.estado_pedido, '') AS estado_pedido
         FROM corporeo_tickets t
         JOIN (SELECT pedido_id, MAX(id) AS mid FROM corporeo_tickets WHERE pedido_id IS NOT NULL GROUP BY pedido_id) u ON u.mid = t.id
         JOIN pedidos p ON p.id = t.pedido_id AND IFNULL(p.es_corporeo, 0) = 1
        WHERE p.id NOT IN (SELECT pedido_id FROM sinfrontera_excluidos)
        ORDER BY t.numero DESC, t.id DESC LIMIT 300`).all()).results || [];
  } catch (_) { return { ok: false, error: 'No se pudo leer la producción. Probá de nuevo en un momento.' }; }
  // Solo para Gaspar: los que sacó del tablero (para poder volver a sumarlos).
  let excluidos;
  if (opts.admin) {
    try {
      excluidos = ((await env.DB.prepare(
        `SELECT x.pedido_id, x.por, x.at, p.cartel, (SELECT MAX(numero) FROM corporeo_tickets t WHERE t.pedido_id = x.pedido_id) AS ticket
           FROM sinfrontera_excluidos x JOIN pedidos p ON p.id = x.pedido_id ORDER BY x.at DESC LIMIT 100`).all()).results || [])
        .map(r => ({ pedido_id: r.pedido_id, ticket: r.ticket, empresa: String(r.cartel || '').trim(), por: r.por || '', at: r.at || '' }));
    } catch (_) { excluidos = []; }
  }
  const hist = {};
  const ids = rows.map(r => r.pedido_id);
  for (let i = 0; i < ids.length; i += 90) {
    const lote = ids.slice(i, i + 90);
    try {
      const rs = (await env.DB.prepare(`SELECT pedido_id, a, por, ts FROM pedido_prod_log WHERE campo = 'estado' AND pedido_id IN (${lote.map(() => '?').join(',')}) ORDER BY ts DESC`).bind(...lote).all()).results || [];
      for (const r of rs) { const h = (hist[r.pedido_id] = hist[r.pedido_id] || []); if (h.length < 15) h.push({ estado: r.a, por: r.por || '', at: r.ts || '' }); }
    } catch (_) {}
  }
  const validos = new Set(SF_ESTADOS.map(e => e[0]));
  const tickets = rows.map(r => {
    let d = {}; try { d = JSON.parse(r.data || '{}') || {}; } catch (_) {}
    const campos = {};
    for (const k of SF_TICKET_CAMPOS) { const v = String(d[k] == null ? '' : d[k]).trim(); if (v && v !== '—') campos[k] = v.slice(0, 2000); }
    let fotos = 0; try { const a = JSON.parse(r.photo_keys || '[]'); fotos = Array.isArray(a) ? Math.min(a.length, 10) : 0; } catch (_) {}
    let estado = validos.has(r.prod_estado) ? r.prod_estado : '';
    if (!estado && /entregad/i.test(r.estado_pedido)) estado = 'entregado';
    return {
      pedido_id: r.pedido_id, ticket: r.numero, tid: r.tid, creado: r.created_at || '', fecha: r.fecha || '',
      empresa: campos.empresa || String(r.cartel || '').trim(), campos, fotos, diseno: !!String(r.foto_diseno_key || '').trim(),
      pedido: {
        medidas: (r.alto && r.ancho) ? `${r.alto} × ${r.ancho} cm` : '', cantidad: parseInt(r.cantidad, 10) || 1, producto: r.producto || '',
        frente: r.frente || '', laterales: r.laterales || '', fondo: r.espalda || '', iluminacion: r.iluminacion || '',
        bastidor: r.bastidor || '', color_bastidor: r.color_bastidor || '', instalacion: r.instalacion || '',
      },
      estado, estado_at: r.prod_estado_at || '', historial: hist[r.pedido_id] || [],
    };
  });
  return { ok: true, tickets, estados: SF_ESTADOS, ...(excluidos ? { excluidos } : {}) };
}
// Mis pedidos: SUS compras (sfPedidosWhere), con precio y pagos, el estado de producción del neón y cuántas fotos del cartel
// terminado hay (las sube el productor).
async function sfPedidos(env, opts = {}) {
  const tels = await sfTels(env);
  const w = sfPedidosWhere(tels);
  let rows = [];
  try { rows = await pedidosConDiseno(env, `WHERE ${w.sql} ORDER BY pedidos.fecha DESC, pedidos.numero DESC, pedidos.id DESC LIMIT 500`, w.args); }
  catch (_) { return { ok: false, error: 'No se pudieron leer los pedidos. Probá de nuevo en un momento.' }; }
  const fotos = {};
  const ids = rows.map(r => r.id);
  for (let i = 0; i < ids.length; i += 90) {
    const lote = ids.slice(i, i + 90);
    try { for (const r of ((await env.DB.prepare(`SELECT pedido_id, COUNT(*) AS n FROM pedido_prod_fotos WHERE pedido_id IN (${lote.map(() => '?').join(',')}) GROUP BY pedido_id`).bind(...lote).all()).results || [])) fotos[r.pedido_id] = Math.min(5, +r.n || 0); } catch (_) {}
  }
  const pedidos = rows.map(r => {
    const o = {};
    for (const k of SF_PEDIDO_CAMPOS) if (r[k] !== undefined) o[k] = r[k];
    o.diseno = !!String(r.diseno_key || '').trim();
    o.fotos_terminado = fotos[r.id] || 0;
    return o;
  });
  // Etapa del tablero de neón (sin "esperando pago": van en cuenta corriente).
  const neonIds = pedidos.filter(p => +p.es_corporeo !== 1).map(p => p.id);
  if (neonIds.length) {
    try {
      const et = {}; for (const r of neonEtapas(await neonTableroFilas(env, { ids: neonIds }), new Set(neonIds))) et[r.id] = r._etapa === 'pago' ? 'terminado' : r._etapa;
      for (const p of pedidos) if (et[p.id]) p.etapa = et[p.id];
    } catch (e) { console.log('sfPedidos etapa:', String((e && e.message) || e)); }
  }
  // Los neones que Gaspar les vende y anota en la planilla (Pedidos_Distris, Canal "Sin Frontera"). No están en la base.
  const pl = opts.planilla === false ? { pedidos: [] } : await sfPlanillaPedidos(env);
  // Pedido viejo que Gaspar vuelve a cargar en el CRM (ej. ribs #1000 del 16-oct, con la fecha original): se esconde su fila de la
  // planilla. Uno a uno por nombre (hay dos "baños") y con la misma fecha o el mismo precio; si no, no se toca.
  const nom = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '');
  const libres = pl.pedidos.slice(), repetidos = [];
  for (const p of pedidos) {
    if (+p.es_corporeo === 1 || !nom(p.cartel)) continue;
    const cands = libres.filter(x => nom(x.cartel) === nom(p.cartel));
    const f = String(p.fecha || '').slice(0, 10), pr = +p.precio || 0;
    const x = cands.find(c => c.fecha === f) || cands.find(c => Math.abs(c.precio - pr) < 1);
    if (x) { libres.splice(libres.indexOf(x), 1); repetidos.push({ id_planilla: x.numero, cartel: x.cartel, numero_crm: p.numero }); }
  }
  const todos = pedidos.concat(libres)
    .sort((a, b) => String(b.fecha || '').slice(0, 10).localeCompare(String(a.fecha || '').slice(0, 10)) || ((parseInt(b.numero, 10) || 0) - (parseInt(a.numero, 10) || 0)));
  return { ok: true, pedidos: todos, configurado: tels.length > 0, ...(pl.error ? { planilla_error: true } : {}), ...(opts.admin && repetidos.length ? { repetidos } : {}) };
}
// HISTÓRICO (Gaspar 16-oct: desde ahora todos sus neones se cargan en el CRM; "leer Pedidos_Distris es solo un backfill"):
// las filas de Pedidos_Distris (2026 v4) con Canal "Sin Frontera" (opción de Maping!A4). Solo ID, fecha, cartel, cantidad,
// colores, medidas, base, dimmer, envío, aclaración y precio. NUNCA pagos (tienen cuenta corriente en otro Excel), costos (P..X),
// Caja ni cálculos. id negativo correlativo; origen 'planilla'. Cache 2 min por isolate; si Google falla o tarda más de 6 s,
// la última lectura (hasta 1 día) y planilla_error.
const SF_PLANILLA_TTL = 2 * 60 * 1000;
let _sfPlanilla = null;
async function sfPlanillaPedidos(env) {
  const ahora = Date.now();
  if (_sfPlanilla && ahora - _sfPlanilla.at < SF_PLANILLA_TTL) return { pedidos: _sfPlanilla.pedidos };
  const viejo = () => (_sfPlanilla && ahora - _sfPlanilla.at < 24 * 3600 * 1000) ? _sfPlanilla.pedidos : [];
  let rows;
  try {
    const token = await sheetsAccessToken(env);
    if (!token) return { pedidos: viejo(), error: 'sin token' };
    const r = await fetch(`https://sheets.googleapis.com/v4/spreadsheets/${CORTE_SHEET_ID}/values/${encodeURIComponent('Pedidos_Distris!A3:O3000')}`, { headers: { Authorization: 'Bearer ' + token }, signal: AbortSignal.timeout(6000) });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) return { pedidos: viejo(), error: (j.error && j.error.message) || ('HTTP ' + r.status) };
    rows = j.values || [];
  } catch (e) { return { pedidos: viejo(), error: String((e && e.message) || e) }; }
  const canal = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z]/g, '');
  const txt = (v, n) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim().slice(0, n || 200);
  const iso = s => { const m = String(s || '').trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/); return m ? `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}` : ''; };
  const lista = [];
  rows.forEach(r => {
    if (canal(r[2]) !== 'sinfrontera' || !txt(r[3])) return;
    lista.push({
      id: -(lista.length + 1), origen: 'planilla', numero: txt(r[0], 20), fecha: iso(r[1]), cartel: txt(r[3]), cantidad: parseInt(r[4], 10) || 1,
      colores: txt(r[5]), alto: txt(r[6], 10), ancho: txt(r[7], 10), base: txt(r[9], 40), dimer: /^no$/i.test(txt(r[10])) ? '' : txt(r[10], 40),
      envio: txt(r[11]), aclaracion: txt(r[12], 600), precio: parseAmt(r[13]), precio_dimmer: parseAmt(r[14]),
      es_corporeo: 0, prod_estado: '', estado_pedido: '', diseno: false, fotos_terminado: 0,
    });
  });
  _sfPlanilla = { at: ahora, pedidos: lista };
  return { pedidos: lista };
}
// Archivos que pueden ver (R2): fotos del ticket VIGENTE de un corpóreo (?t=<id del ticket>&i=<n>), el diseño de un corpóreo en
// producción o de un pedido suyo (?p=<id>) y las fotos del cartel terminado de un pedido suyo (?p=<id>&f=<n>). Devuelve la key
// o '' si no le corresponde: nunca una key que venga del pedido de afuera.
async function sfArchivoKey(env, qs) {
  const t = parseInt(qs.get('t'), 10) || 0, i = parseInt(qs.get('i'), 10), p = parseInt(qs.get('p'), 10) || 0, fi = parseInt(qs.get('f'), 10);
  try {
    if (t) {
      if (!(i >= 0 && i < 10)) return '';
      const r = await env.DB.prepare(
        `SELECT t.photo_keys FROM corporeo_tickets t JOIN pedidos p ON p.id = t.pedido_id AND IFNULL(p.es_corporeo, 0) = 1
          WHERE t.id = ? AND t.id = (SELECT MAX(id) FROM corporeo_tickets WHERE pedido_id = t.pedido_id) AND p.id NOT IN (SELECT pedido_id FROM sinfrontera_excluidos)`).bind(t).first();
      let keys = []; try { keys = r ? JSON.parse(r.photo_keys || '[]') : []; } catch (_) {}
      const k = Array.isArray(keys) ? String(keys[i] || '') : '';
      return k.startsWith('corporeo-ticket/') ? k : '';
    }
    if (!p) return '';
    if (!(fi >= 0)) {
      // Corpóreo en producción (con ticket): el diseño original que cargó el vendedor.
      const c = await env.DB.prepare("SELECT foto_diseno_key AS k FROM pedidos WHERE id = ? AND IFNULL(es_corporeo, 0) = 1 AND EXISTS (SELECT 1 FROM corporeo_tickets WHERE pedido_id = pedidos.id) AND id NOT IN (SELECT pedido_id FROM sinfrontera_excluidos)").bind(p).first();
      if (c && String(c.k || '').trim()) return String(c.k).trim();
    }
    await ensureSinFronteraSchema(env);
    const w = sfPedidosWhere(await sfTels(env));
    const rows = await pedidosConDiseno(env, `WHERE pedidos.id = ? AND ${w.sql}`, [p, ...w.args]);
    if (!rows.length) return '';
    if (fi >= 0) {
      const f = await env.DB.prepare('SELECT r2_key FROM pedido_prod_fotos WHERE pedido_id = ? ORDER BY id LIMIT 1 OFFSET ?').bind(p, Math.min(fi, 20)).first();
      return f ? String(f.r2_key || '') : '';
    }
    return String(rows[0].diseno_key || '').trim();
  } catch (_) {}
  return '';
}
// Sirve un archivo de R2 (con ?w= para miniaturas, como /admin/media/; ?dl=1 lo baja con nombre). Cache PRIVADO: la URL lleva
// el token de la sesión.
// ===== Tablero de producción de NEÓN (Gaspar 16-oct-2026) =====
// 7 etapas que pidió Gaspar. La etapa se CALCULA con lo que cada uno ya marca en su pantalla: la pieza de corte (Emma la
// toma y hace la matriz, Aníbal corta, Neyen separa la base), el productor y su estado (su hoja), el 2do pago y la salida
// que marca Neyen o logística. No hay una columna "etapa" que mantener al día. Lo único manual es neon_piso: Gaspar ubica a
// mano un cartel que el sistema no puede ubicar solo (ej. neones viejos sin pieza de corte). Nunca plata en el tablero.
// Ver memoria kanban-neon-produccion.
const NEON_ETAPAS = [['confirmado', 'Confirmado'], ['diseno', 'En diseño y corte'], ['montando', 'Montando neón'], ['terminado', 'Terminado'], ['pago', 'Esperando pago'], ['enviar', 'Para enviar'], ['enviado', 'Enviado']];
const NEON_IDX = Object.fromEntries(NEON_ETAPAS.map(([k], i) => [k, i]));
const NEON_TABLERO_DESDE = '2026-09-01';
const NEON_ENVIADO_DIAS = 30;      // los enviados vuelven al tablero 30 días (la columna muestra 14; el resto en "Ver todos")
const NEON_DESPACHO_MODOS = { envio: 'Salió por envío', retira: 'Retiró en el taller', instalacion: 'Instalado', sinfrontera: 'Entregado a Sin Frontera' };
const NEON_VEND = { joaco: 'Joaco', joaquin: 'Joaco', facundo: 'Facu', agustina: 'Agus', debi: 'Debi', gaspar: 'Gaspar' };
let _neonTabOk = false;
async function ensureNeonTableroSchema(env) {
  if (_neonTabOk) return;
  try {
    await env.DB.prepare('SELECT diseno_inicio_at, diseno_inicio_por, cortado_at, separado_at FROM corte_pedidos LIMIT 0').all();
    await env.DB.prepare('SELECT recibido_at, recibido_por, despachado_at, despachado_por, despacho_modo, despacho_transporte, despacho_seguimiento, despacho_prev_estado, neon_piso, neon_piso_at, neon_piso_por, neon_piso_motivo FROM pedidos LIMIT 0').all();
    _neonTabOk = true; return;
  } catch (_) {}
  const alters = [
    ['corte_pedidos', ['diseno_inicio_at TEXT', 'diseno_inicio_por TEXT', 'cortado_at TEXT', 'separado_at TEXT']],
    ['pedidos', ['recibido_at TEXT', 'recibido_por TEXT', 'despachado_at TEXT', 'despachado_por TEXT', 'despacho_modo TEXT', 'despacho_transporte TEXT', 'despacho_seguimiento TEXT', 'despacho_prev_estado TEXT', 'neon_piso TEXT', 'neon_piso_at TEXT', 'neon_piso_por TEXT', 'neon_piso_motivo TEXT']],
  ];
  for (const [t, cols] of alters) for (const c of cols) { try { await env.DB.prepare('ALTER TABLE ' + t + ' ADD COLUMN ' + c).run(); } catch (_) {} }
  _neonTabOk = true;
}
// Fechas de corte para el recorrido (Aníbal y Neyen marcan en Corte; estas columnas solo guardan CUÁNDO, la primera vez).
async function neonCorteStamp(env, ids, campo, por) {
  const cond = { cortado_at: "estado IN ('cortado','embalado')", separado_at: "estado = 'embalado'", diseno_inicio_at: "estado = 'pedido'" }[campo];
  if (!cond || !ids || !ids.length) return;
  try {
    await ensureNeonTableroSchema(env);
    const now = new Date().toISOString(), ph = ids.map(() => '?').join(',');
    if (campo === 'diseno_inicio_at') await env.DB.prepare('UPDATE corte_pedidos SET diseno_inicio_at = COALESCE(diseno_inicio_at, ?), diseno_inicio_por = COALESCE(diseno_inicio_por, ?) WHERE id IN (' + ph + ") AND producto = 'NEON' AND " + cond).bind(now, String(por || ''), ...ids).run();
    else await env.DB.prepare('UPDATE corte_pedidos SET ' + campo + ' = COALESCE(' + campo + ', ?) WHERE id IN (' + ph + ") AND producto = 'NEON' AND " + cond).bind(now, ...ids).run();
  } catch (_) {}
}
// Mismo grupo que el PATCH de pedidos: N° + fecha + vendedor y, en los del CRM con teléfono, el mismo cliente. La clave lleva el
// teléfono del cliente: NUNCA sale del worker (al front va _gid, un id opaco).
function neonGrupoKey(r) { return [r.numero, r.fecha, String(r.comercial_id || 'joaco'), (r.origen === 'crm' && r.telefono) ? 'crm:' + r.telefono : ''].join('|'); }
// Líneas de servicio cargadas como cartel (ej. "instalacion led la magica", sin medidas): no son un cartel a producir. Las dos
// condiciones juntas: un neón real cargado sin medidas no se esconde.
function neonNoCartel(r) { return !(Number(r.alto) > 0 && Number(r.ancho) > 0) && /instalaci|colocaci|env[ií]o|flete|mano de obra/i.test(String(r.cartel || '')); }
// Pedidos de antes del tablero: su 'para enviar' puesto a mano en Pedidos cuenta como etapa (si está pagado). Los nuevos se ubican
// solo con las señales (el estado_pedido pasa a ser una salida).
const NEON_LEGACY_HASTA = '2026-10-17';
async function neonTableroFilas(env, opts = {}) {
  await ensureNeonTableroSchema(env);
  try { await ensureProdSchema(env); } catch (_) {}
  try { await ensureCorteNeonSchema(env); } catch (_) {}
  const sel = 'SELECT p.id, p.numero, p.fecha, p.cartel, p.colores, p.alto, p.ancho, p.cantidad, p.base, p.dimer, p.tipo, p.envio, p.aclaracion, p.telefono, p.comercial_id, p.cargado_por, p.origen, ' +
    'p.estado_pedido, p.estado_pago, p.pago_metodo, p.pagado AS _pag, p.cobro2_at, p.productor_id, p.productor, p.prod_estado, p.prod_estado_at, p.prod_asignado_at, p.prod_terminado_at, p.created_at, p.foto_diseno_key, ' +
    'p.recibido_at, p.recibido_por, p.despachado_at, p.despachado_por, p.despacho_modo, p.despacho_transporte, p.despacho_seguimiento, p.despacho_prev_estado, p.neon_piso, p.neon_piso_at, p.neon_piso_por, p.neon_piso_motivo, ' +
    'cp.id AS corte_id, cp.estado AS corte_estado, cp.foto_key AS corte_foto, cp.medida_declarada, cp.ancho_real, cp.alto_real, cp.disenado_at, cp.diseno_inicio_at, cp.diseno_inicio_por, cp.cortado_at, cp.separado_at, ' +
    '(SELECT COUNT(*) FROM pedido_prod_fotos f WHERE f.pedido_id = p.id) AS fotos_n, ' +
    // Total del pedido ENTERO (con los corpóreos del grupo): para saber si lo pagó todo con la seña.
    "(SELECT SUM(IFNULL(x.precio,0) + IFNULL(x.precio_dimmer,0)) FROM pedidos x WHERE x.numero = p.numero AND x.fecha = p.fecha AND IFNULL(x.comercial_id,'joaco') = IFNULL(p.comercial_id,'joaco') AND (IFNULL(p.origen,'') <> 'crm' OR IFNULL(p.telefono,'') = '' OR (x.origen = 'crm' AND x.telefono = p.telefono))) AS _tot, " +
    // Seña del pedido entero: los del CRM la repiten en cada fila (MAX); los importados del Excel la tienen repartida por fila (SUM si
    // cada fila cierra —pagado + restante = su precio— o si los montos difieren; si no, uno solo: del lado seguro, nunca "saldado" de más).
    "(SELECT CASE WHEN SUM(CASE WHEN IFNULL(x.origen,'') = 'crm' THEN 0 ELSE 1 END) = 0 THEN MAX(IFNULL(x.pagado,0)) WHEN MAX(ABS(IFNULL(x.pagado,0) + IFNULL(x.restante,0) - IFNULL(x.precio,0) - IFNULL(x.precio_dimmer,0))) <= 1 OR MIN(IFNULL(x.pagado,0)) <> MAX(IFNULL(x.pagado,0)) THEN SUM(IFNULL(x.pagado,0)) ELSE MAX(IFNULL(x.pagado,0)) END FROM pedidos x WHERE x.numero = p.numero AND x.fecha = p.fecha AND IFNULL(x.comercial_id,'joaco') = IFNULL(p.comercial_id,'joaco') AND (IFNULL(p.origen,'') <> 'crm' OR IFNULL(p.telefono,'') = '' OR (x.origen = 'crm' AND x.telefono = p.telefono))) AS _sena, " +
    "(SELECT MAX(x.cobro2) FROM pedidos x WHERE x.numero = p.numero AND x.fecha = p.fecha AND IFNULL(x.comercial_id,'joaco') = IFNULL(p.comercial_id,'joaco') AND (IFNULL(p.origen,'') <> 'crm' OR IFNULL(p.telefono,'') = '' OR (x.origen = 'crm' AND x.telefono = p.telefono))) AS _cob2, " +
    "(SELECT MAX(ts) FROM pedido_estado_log l WHERE l.pedido_id = p.id AND lower(l.a) LIKE 'para enviar%') AS env_log_at, " +
    "(SELECT l.por FROM pedido_estado_log l WHERE l.pedido_id = p.id AND lower(l.a) LIKE 'para enviar%' ORDER BY l.ts DESC LIMIT 1) AS env_log_por, " +
    "(SELECT MAX(ts) FROM pedido_estado_log l WHERE l.pedido_id = p.id AND lower(l.a) LIKE 'entregad%') AS ent_log_at " +
    'FROM pedidos p ' +
    'LEFT JOIN (SELECT pedido_id, MAX(id) AS cid FROM corte_pedidos WHERE pedido_id IS NOT NULL GROUP BY pedido_id) cx ON cx.pedido_id = p.id ' +
    'LEFT JOIN corte_pedidos cp ON cp.id = cx.cid ' +
    'WHERE IFNULL(p.es_corporeo, 0) = 0 AND ';
  let rows = [];
  if (opts.ids) {
    const ids = [...new Set(opts.ids.map(Number).filter(n => n > 0))];
    for (let i = 0; i < ids.length; i += 90) { const l = ids.slice(i, i + 90); rows.push(...((await env.DB.prepare(sel + 'p.id IN (' + l.map(() => '?').join(',') + ')').bind(...l).all()).results || [])); }
  } else {
    const hoy = Date.now();
    rows = (await env.DB.prepare(sel + "p.fecha >= ? AND NOT (lower(IFNULL(p.estado_pedido,'')) LIKE 'entregad%' AND ((IFNULL(p.despachado_at,'') <> '' AND p.despachado_at < ?) OR (IFNULL(p.despachado_at,'') = '' AND p.fecha < ?))) ORDER BY p.fecha DESC, p.id DESC LIMIT 800")
      .bind(NEON_TABLERO_DESDE, new Date(hoy - NEON_ENVIADO_DIAS * 86400000).toISOString(), new Date(hoy - 45 * 86400000).toISOString().slice(0, 10)).all()).results || [];
  }
  return rows.filter(r => !neonNoCartel(r));
}
// Etapa de cada cartel (y de paso el grupo y desde cuándo). Las de pedido entero (esperando pago, para enviar, enviado) miran a
// TODOS los carteles de neón del pedido: un pedido no se cobra ni se manda a medias. neonEtapas tiene que correr sobre el grupo
// COMPLETO (nunca sobre un cartel suelto).
function neonEtapas(rows, sfIds) {
  const grupos = {};
  for (const r of rows) { r._g = neonGrupoKey(r); (grupos[r._g] = grupos[r._g] || []).push(r); }
  for (const k in grupos) { const gid = 'g' + Math.min(...grupos[k].map(x => +x.id)); for (const x of grupos[k]) x._gid = gid; }
  const term = x => String(x.prod_estado || '') === 'terminado';
  // Producción lista: terminado por el productor, o Gaspar lo ubicó a mano en Terminado o más adelante (neones sin productor en el
  // sistema). Sin esto, una tarjeta ubicada en Esperando pago no pasaba nunca a Para enviar aunque registraran el 2do pago (#351).
  const listo = x => term(x) || (NEON_IDX[String(x.neon_piso || '')] ?? -1) >= NEON_IDX.terminado;
  // Gaspar 17-oct: Terminado = "terminado, falta traerlo al taller". Sale de ahí (a Esperando pago o Para enviar) cuando Neyen o
  // Gaspar marcan "Llegó al taller" (recibido_at), o si Gaspar lo ubicó a mano en Esperando pago o más adelante.
  const llego = x => !!String(x.recibido_at || '').trim() || (NEON_IDX[String(x.neon_piso || '')] ?? -1) >= NEON_IDX.pago;
  const maxF = (g, k) => g.map(x => x[k] || '').sort().pop() || '';
  // Quién escribió el último 'para enviar' del pedido (el log queda en UNA fila del grupo, no en cada cartel).
  const envPor = {};
  for (const k in grupos) { let b = null; for (const x of grupos[k]) if (x.env_log_at && (!b || String(x.env_log_at) > String(b.env_log_at))) b = x; envPor[k] = b ? String(b.env_log_por || '') : ''; }
  for (const r of rows) {
    const g = grupos[r._g], ep = String(r.estado_pedido || '').trim().toLowerCase(), pago = String(r.estado_pago || '').trim().toLowerCase();
    const ce = String(r.corte_estado || '');
    // Pagado: 2do pago, cuenta corriente (Sin Frontera) o la seña cubrió todo (cargados como '1er pago' con el total).
    // Gaspar 17-oct: "no se puede mandar algo que no está saldado". Saldado = lo cobrado (seña + 2do pago) cubre el total del pedido
    // ENTERO. El '2do pago' puesto a mano antes del modal (sin cobro2) cuenta como saldado: el restante de esos no es confiable.
    const cubre = Number(r._tot) > 0 && (Number(r._sena) || 0) + (Number(r._cob2) || 0) >= Number(r._tot) - 1;
    const sinCob2 = r._cob2 == null || r._cob2 === '';
    const pagado = pago === 'cuenta corriente' || !!(sfIds && sfIds.has(r.id))
      || (pago === '2do pago' && (cubre || (sinCob2 && String(r.fecha || '') < NEON_LEGACY_HASTA)))
      || (pago === '1er pago' && String(r.pago_metodo || '') !== 'pendiente' && cubre);
    let i;
    if (/^entregad/.test(ep)) i = 6;
    else if (g.every(x => listo(x) && llego(x))) i = pagado ? 5 : 4;
    else if (listo(r)) i = 3;   // terminado: falta traerlo al taller, o espera a otro cartel del pedido
    // Derivado pero la base todavía no está cortada (está en la cola de Emma o de Aníbal): sigue en En diseño y corte.
    else if (String(r.productor_id || '') && (String(r.prod_estado || '') === 'en_armado' || !r.corte_id || ['cortado', 'embalado', 'cobrado', 'despachado', 'entregado'].includes(ce))) i = 2;
    else if (['matriz_lista', 'cortado', 'embalado', 'cobrado', 'despachado', 'entregado'].includes(ce) || (ce === 'pedido' && String(r.corte_foto || '').trim())) i = 1;
    else i = 0;
    let motivo = '';
    if (i < 5 && pagado && /^para enviar/.test(ep) && String(r.fecha || '') < NEON_LEGACY_HASTA && envPor[r._g] !== 'tablero') { i = 5; motivo = 'estado'; }
    const piso = NEON_IDX[String(r.neon_piso || '')];
    if (piso != null && piso > i) { i = piso; motivo = 'piso'; }
    // Ubicado a mano en Para enviar sin saldar: queda en Esperando pago (nada sin saldar aparece listo para despachar).
    if (i === NEON_IDX.enviar && !pagado) i = NEON_IDX.pago;
    r._i = i; r._etapa = NEON_ETAPAS[i][0]; r._motivo = motivo; r._pagado = pagado;
    r._sf = !!(sfIds && sfIds.has(r.id)) || pago === 'cuenta corriente';
    r._grupo_n = g.length; r._grupo_term = g.filter(listo).length;
    r._desde = motivo === 'piso' ? r.neon_piso_at
      : i === 0 ? r.created_at
      : i === 1 ? r.created_at
      : i === 2 ? r.prod_asignado_at
      : i === 3 ? r.prod_terminado_at
      : i === 4 ? ([maxF(g, 'prod_terminado_at'), maxF(g, 'recibido_at')].sort().pop() || '')
      : i === 5 ? (motivo === 'estado' ? (r.cobro2_at || maxF(g, 'env_log_at') || '') : ([maxF(g, 'prod_terminado_at'), maxF(g, 'recibido_at'), r.cobro2_at || ''].sort().pop() || ''))
      : (r.despachado_at || maxF(g, 'ent_log_at') || '');
    r._desde = r._desde || (r.neon_piso ? (r.neon_piso_at || '') : '');
    // Sin fecha propia (los de antes del tablero): se cuenta, aproximado, desde la fecha del pedido.
    r._desde_aprox = (!r._desde && i >= 5) ? String(r.fecha || '') : '';
  }
  return rows;
}
// El grupo completo de un cartel, con sus etapas (despacho, ubicar y las fotos para logística).
async function neonGrupoDe(env, pid) {
  const base = (await neonTableroFilas(env, { ids: [pid] }))[0];
  if (!base) return { base: null, fr: [], serv: [], yo: null };
  const cand = (await env.DB.prepare("SELECT id, numero, fecha, comercial_id, origen, telefono, cartel, alto, ancho, estado_pedido, despachado_at FROM pedidos WHERE numero = ? AND fecha = ? AND IFNULL(comercial_id,'joaco') = ? AND IFNULL(es_corporeo,0) = 0").bind(base.numero, base.fecha, String(base.comercial_id || 'joaco')).all()).results || [];
  const k = neonGrupoKey(base);
  const fr = neonEtapas(await neonTableroFilas(env, { ids: cand.map(x => x.id) }), await neonSfIds(env)).filter(x => x._g === k);
  // Líneas de servicio del pedido (no son tarjetas): acompañan al pedido en el estado.
  const serv = cand.filter(x => neonGrupoKey(x) === k && neonNoCartel(x));
  return { base, fr, serv, yo: fr.find(x => x.id === pid) || null };
}
// Lo que viaja al front: lista CERRADA, sin precio, pagos, teléfono ni la clave del grupo. La dirección (texto de envío) solo para
// quien despacha (Gaspar, Neyen, logística) y para el vendedor del pedido.
function neonTarjeta(r, ctx) {
  const med = (Number(r.alto) > 0 && Number(r.ancho) > 0) ? Number(r.alto) + ' × ' + Number(r.ancho) + ' cm' : '';
  const com = String(r.comercial_id || 'joaco');
  const propio = ctx.rol === 'comercial' && com === ctx.com;
  const dir = ctx.rol === 'admin' || ctx.despacha || propio;
  const ce = String(r.corte_estado || ''), post = ['cobrado', 'despachado', 'entregado'];
  const salio = !!r.despachado_at && /^entregad/i.test(String(r.estado_pedido || ''));
  const o = {
    id: r.id, numero: r.numero, fecha: r.fecha, cartel: String(r.cartel || '').trim(), colores: r.colores || '', medida: med, alto: Number(r.alto) || 0, ancho: Number(r.ancho) || 0,
    cantidad: Math.max(1, parseInt(r.cantidad, 10) || 1), base: r.base || '', dimer: /^no$/i.test(String(r.dimer || '')) ? '' : (r.dimer || ''), tipo: r.tipo || '',
    etapa: r._etapa, motivo: r._motivo, desde: r._desde || '', desde_aprox: r._desde_aprox || '', sf: r._sf, grupo: r._gid, grupo_n: r._grupo_n, grupo_term: r._grupo_term,
    productor_id: r.productor_id || '', productor: String(r.productor || r.productor_id || '').trim(), prod_estado: r.prod_estado || '',
    corte_id: r.corte_id || null, corte_estado: ce, diseno: !!(String(r.corte_foto || '').trim() || String(r.foto_diseno_key || '').trim()), fotos: Math.min(12, +r.fotos_n || 0),
    // Fechas del recorrido: solo las que el estado actual sostiene (un deshacer en Corte no las borra).
    f: { creado: r.created_at || '', tomado: (ce === 'pedido' || ['matriz_lista', 'cortado', 'embalado', ...post].includes(ce)) ? (r.diseno_inicio_at || '') : '', tomado_por: r.diseno_inicio_por || '',
      matriz: ['matriz_lista', 'cortado', 'embalado', ...post].includes(ce) ? (r.disenado_at || '') : '',
      cortado: ['cortado', 'embalado', ...post].includes(ce) ? (r.cortado_at || '') : '', separado: ['embalado', ...post].includes(ce) ? (r.separado_at || '') : '',
      asignado: r.prod_asignado_at || '', prod: r.prod_estado_at || '', terminado: r.prod_terminado_at || '', recibido: r.recibido_at || '', despachado: salio ? r.despachado_at : '' },
    recibido_por: r.recibido_por || '', despacho: salio ? { modo: r.despacho_modo || '', transporte: r.despacho_transporte || '', seguimiento: r.despacho_seguimiento || '', por: r.despachado_por || '' } : null,
    mio: propio,
  };
  if (ctx.rol !== 'logistica') { o.vendedor = NEON_VEND[com] || com; o.aclaracion = String(r.aclaracion || '').trim().slice(0, 300); }
  if (dir) o.envio = String(r.envio || '').trim().slice(0, 400);
  if (ctx.rol === 'admin' && r.neon_piso) o.piso = { etapa: r.neon_piso, motivo: r.neon_piso_motivo || '', por: r.neon_piso_por || '', at: r.neon_piso_at || '' };
  return o;
}
// Quién es quién en el tablero. logística por nombre (es externo); el resto por su rol.
async function neonCtx(env, session) {
  const slug = String(session.user || '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  if (esUsuarioLogistica(session.user)) return { rol: 'logistica', slug, despacha: true, quien: 'Logística' };
  const rol = await getSessionRole(env, session.user);
  const ctx = { rol, slug, despacha: rol === 'admin' || (rol === 'produccion' && slug === 'neyen'), quien: String(session.user || '') };
  if (rol === 'comercial') ctx.com = await resolveComercial(env, { sessionUser: session.user });
  return ctx;
}
async function neonSfIds(env) {
  try { return new Set(((await env.DB.prepare('SELECT pedido_id FROM sinfrontera_pedidos').all()).results || []).map(r => r.pedido_id)); } catch (_) { return new Set(); }
}
async function neonTablero(env, ctx) {
  const rows = neonEtapas(await neonTableroFilas(env), await neonSfIds(env));
  let vis = rows, otros = null;
  if (ctx.rol === 'comercial') {
    vis = rows.filter(r => String(r.comercial_id || 'joaco') === ctx.com);
    otros = {}; for (const r of rows) if (String(r.comercial_id || 'joaco') !== ctx.com) otros[r._etapa] = (otros[r._etapa] || 0) + 1;
  } else if (ctx.rol === 'logistica') vis = rows.filter(r => r._i >= 5);
  const out = { ok: true, etapas: NEON_ETAPAS, carteles: vis.map(r => neonTarjeta(r, ctx)), rol: ctx.rol, yo: ctx.slug, despacha: ctx.despacha, desde: NEON_TABLERO_DESDE };
  if (otros) out.otros = otros;
  if (ctx.rol === 'admin') { try { out.productores = (await prodProductores(env)).filter(p => !p.baja).map(p => ({ id: p.id, nombre: p.nombre, activo: !!p.activo })); } catch (_) { out.productores = []; } }
  return out;
}
// Cuando el 2do pago completa un pedido terminado, el tablero lo pone "Para enviar" y la planilla tiene que decir lo mismo:
// pasa estado_pedido de 'En produccion' a 'para enviar' (todo el grupo, con espejo y pedido_estado_log por='tablero'). Solo
// para arriba y apagado hasta el OK de Gaspar (kv neon_estado_sync_on = '1').
async function neonSyncEstados(env) {
  if (String(await kvGet(env, 'neon_estado_sync_on', '0')) !== '1') return { off: true };
  const rows = neonEtapas(await neonTableroFilas(env), await neonSfIds(env));
  const vistos = new Set(); let n = 0;
  for (const r of rows) {
    if (r._etapa !== 'enviar' || r._motivo || vistos.has(r._g) || !/^en produc/i.test(String(r.estado_pedido || ''))) continue;
    vistos.add(r._g);
    let ids = rows.filter(x => x._g === r._g).map(x => x.id); const now = new Date().toISOString();
    try { const gq = await neonGrupoDe(env, r.id); ids = ids.concat((gq.serv || []).filter(x => /^en produc/i.test(String(x.estado_pedido || ''))).map(x => x.id)); } catch (_) {}
    try {
      const u = await env.DB.prepare("UPDATE pedidos SET estado_pedido = 'para enviar', mirror_dirty = 1, mirror_attempts = 0, mirror_error = NULL, updated_at = ? WHERE id IN (" + ids.map(() => '?').join(',') + ") AND lower(IFNULL(estado_pedido,'')) LIKE 'en produc%'").bind(now, ...ids).run();
      if ((u.meta && u.meta.changes) || 0) {
        n++;
        try { await env.DB.prepare('INSERT INTO pedido_estado_log (pedido_id, numero, fecha, comercial_id, telefono, de, a, por, ts) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)').bind(r.id, r.numero, r.fecha, r.comercial_id || 'joaco', r.telefono || '', r.estado_pedido || '', 'para enviar', 'tablero', now).run(); } catch (_) {}
      }
    } catch (_) {}
  }
  return { ok: true, n };
}
async function sfServirR2(env, key, url) {
  if (!env.MEDIA) return json({ error: 'R2 not configured' }, 500);
  const obj = await env.MEDIA.get(key);
  if (!obj) return json({ error: 'not found' }, 404);
  const ctype = obj.httpMetadata?.contentType || 'application/octet-stream';
  const hdr = { ...cors(), 'Content-Type': ctype, 'Cache-Control': 'private, max-age=86400' };
  if (url.searchParams.get('dl') === '1') hdr['Content-Disposition'] = 'attachment; filename="' + (key.split('/').pop() || 'archivo').replace(/[^\w.-]/g, '_') + '"';
  const w = parseInt(url.searchParams.get('w') || '0', 10);
  if (w >= 100 && w <= 2000 && env.IMAGES && /^image\/(jpe?g|png|webp)/i.test(ctype)) {
    try {
      const buf = await obj.arrayBuffer();
      if (buf.byteLength > 60000) {
        const res = await env.IMAGES.input(new Response(buf).body).transform({ width: w, fit: 'scale-down' }).output({ format: 'image/jpeg', quality: 76 });
        return new Response(await res.response().arrayBuffer(), { headers: { ...hdr, 'Content-Type': 'image/jpeg' } });
      }
      return new Response(buf, { headers: hdr });
    } catch (_) {
      try { const o2 = await env.MEDIA.get(key); if (o2) return new Response(o2.body, { headers: hdr }); } catch (_) {}
      return json({ error: 'media error' }, 500);
    }
  }
  return new Response(obj.body, { headers: hdr });
}
// Usuario EXTERNO de logística (Siempre a Tiempo). Fuera de /admin/logistica/* no puede leer NADA del CRM (chats,
// ventas, clientes, plata): lo frena el muro de /admin/ y la agenda. El front no es una barrera de seguridad.
function esUsuarioLogistica(userName) { return String(userName || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '') === 'logistica'; }
// Rol funcional del usuario de la sesión: admin | comercial | disenador | cursos | produccion | logistica.
// gaspar siempre admin; el resto se resuelve por su slug contra users_panel.
async function getSessionRole(env, userName) {
  const slug = String(userName || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  if (slug === 'gaspar') return 'admin';
  const ids = userLookupIds(slug);
  const ph = ids.map(() => '?').join(',');
  try {
    const u = await env.DB.prepare(`SELECT rol FROM users_panel WHERE id IN (${ph}) AND activo = 1 LIMIT 1`).bind(...ids).first();
    return (u && u.rol) ? u.rol : 'comercial';
  } catch (e) { return 'comercial'; }
}

// Rutas fuera de /admin/ que antes eran públicas (/cotizador/*, /report, /done, /debug/wa-quality): exigen
// sesión válida y NUNCA dejan pasar al usuario externo de logística. Con `roles`, además, solo esos roles.
// Devuelve { session, role } o { error } con la Response lista para devolver.
async function sesionInterna(env, request, roles) {
  const session = await getSession(env, request);
  if (!session) return { error: unauthorized() };
  const role = esUsuarioLogistica(session.user) ? 'logistica' : (esUsuarioSinFrontera(session.user) ? 'sinfrontera' : ((await productorDeSesion(env, session.user)) ? 'productor' : await getSessionRole(env, session.user)));
  if (role === 'logistica' || role === 'sinfrontera' || role === 'productor' || (roles && !roles.includes(role))) return { error: json({ error: 'forbidden' }, 403) };
  return { session, role };
}
// Quiénes usan el cotizador (COGS/params) y la vista Actividad: Gaspar, vendedores y diseño.
// Cursos (Abril), producción (Aníbal/Neyen) y logística no lo necesitan.
const ROLES_COTIZADOR = ['admin', 'comercial', 'disenador'];
// ¿El `user` que manda el front es el dueño de la sesión? Tolera tildes/mayúsculas y los alias (Joaquín↔joaco).
function esMismoUsuario(sessionUser, user) {
  const slug = (s) => String(s || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  return userLookupIds(slug(user)).includes(slug(sessionUser));
}

// Cláusula SQL de filtrado de bandeja según rol (para la lista de chats).
//   admin     → sin filtro (ve todo)
//   cursos    → solo bandeja 'cursos'
//   los demás → todo MENOS 'cursos' (Joaco no ve los de cursos)
function inboxClauseForRole(role) {
  // 'oculto' = chats de broadcast aún sin respuesta: no se ven en NINGUNA
  // bandeja (ni admin) hasta que el cliente responde y se revelan.
  if (role === 'admin') return "AND inbox != 'oculto'";
  if (role === 'cursos') return "AND inbox = 'cursos'";
  // 'precotiz' = lead en pre cotización automática (piloto): solo Gaspar (admin)
  // lo ve mientras está en relevamiento; vuelve a 'general' al completar los 3 datos.
  // 'privado' = bandeja admin-only de Gaspar (clientes especiales que asigna a mano):
  // solo admin lo ve, comercial/cursos NUNCA. Mismo patrón que precotiz.
  // 'corte' = bandeja del Servicio de Corte, admin-only de Gaspar (es un negocio suyo; ni Abril ni
  // comercial se meten). Mismo patrón que 'privado'. El bot de corte manda los chats acá.
  // Cadena de != en vez de NOT IN (...): mismo resultado, pero D1 cuenta el doble de filas
  // leídas con NOT IN sobre una lista (medido: 72k vs 39k por cada carga de la lista de Joaco).
  return "AND inbox != 'cursos' AND inbox != 'oculto' AND inbox != 'precotiz' AND inbox != 'privado' AND inbox != 'corte'";
}

// Control de acceso por chat: 'cursos' solo su bandeja; la bandeja 'privado' (admin-only de
// Gaspar) NO la tocan ni comercial ni cursos; admin ve/toca todo. La usan messages/send/send-media.
async function inboxAccessOk(env, role, phone, sessionUser) {
  if (role === 'admin') return true;
  // Los chats del EQUIPO con el número del negocio (avisos internos, listas, reportes) son solo de admin: si no,
  // Abril veía en 'cursos' los avisos de Bruno y Joaco en 'general' los de Agus (plan de fondo §8). internosSet
  // sale de caché (10 min).
  if (phone && (await esTelefonoInterno(env, phone))) return false;
  if (phone) {
    try {
      const r = await env.DB.prepare('SELECT inbox, assigned_to FROM wa_chats_summary WHERE phone = ?').bind(phone).first();
      const inbox = (r && r.inbox) || '';
      if (inbox === 'privado' || inbox === 'corte') return false; // privado y corte = SOLO admin (Gaspar)
      if (role === 'cursos') return inbox === 'cursos';  // cursos: solo su bandeja
      // comercial: scope por vendedor (igual que la lista). El secundario (Facundo) SOLO abre/
      // responde lo asignado a él; el principal (Joaco) todo lo NO asignado a un secundario.
      // Cierra el hueco de que dos vendedores atendieran el mismo chat (por búsqueda/API).
      if (role === 'comercial') {
        const _u = String(sessionUser || '').toLowerCase();
        const asg = (r && r.assigned_to) || '';
        if (VENDEDORES_SECUNDARIOS.includes(_u)) return asg === _u;
        return !VENDEDORES_SECUNDARIOS.includes(asg);
      }
      return true;                                       // otros roles: todo menos privado
    } catch (e) { return role !== 'cursos'; }
  }
  return role !== 'cursos';                              // sin phone puntual: cursos no, resto sí
}

// Invalida las variantes (por rol) del cache de chats-summary.
// Vendedores comerciales SECUNDARIOS: ven SOLO los chats asignados a ellos (assigned_to).
// El comercial "principal" (Joaco) ve todo lo NO asignado a un secundario. Es el reparto
// de chats entre vendedores (assigned_to en wa_chats_summary, mig 037). Sumar un 3er
// vendedor secundario = agregar su slug acá (y queda cubierto en la invalidación de cache).
const VENDEDORES_SECUNDARIOS = COMERCIALES_SECUNDARIOS.map(c => c.slug);
async function invalidateChatsSummaryCache(request) {
  try {
    const cache = caches.default;
    const base = new URL(request.url);
    base.pathname = '/admin/wa/chats-summary';
    const variants = ['?role=admin', '?role=comercial', '?role=disenador', '?role=cursos'];
    // El rol comercial se cachea POR USUARIO (reparto por vendedor): borrar cada variante.
    for (const u of ['joaco', 'joaquin', ...VENDEDORES_SECUNDARIOS]) variants.push('?role=comercial&u=' + u);
    for (const s of variants) { base.search = s; await cache.delete(new Request(base.toString(), { method: 'GET' })); }
  } catch (_) {}
}

// ===== Framework de venta (hogar operativo del agente IA) =====
// Vive en D1 (tabla sales_framework, versionada). Se auto-siembra desde
// FRAMEWORK_SEED (worker/knowledge/framework-venta.md) si la tabla está vacía.
// El agente lee la versión activa en runtime; el bucle de retroalimentación
// inserta versiones nuevas con aprobación humana. Source: seed|manual|synthesis.
async function ensureFrameworkSeeded(env) {
  try {
    const row = await env.DB.prepare('SELECT COUNT(*) AS n FROM sales_framework').first();
    if (row && row.n > 0) return;
    await env.DB.prepare(
      `INSERT INTO sales_framework (version, content, format, is_active, source, notes, created_by, created_at)
       VALUES (1, ?, 'md', 1, 'seed', 'Semilla inicial desde el repo', 'system', ?)`
    ).bind(FRAMEWORK_SEED, new Date().toISOString()).run();
    await deriveFrameworkSections(env, 1, FRAMEWORK_SEED);
  } catch (e) { try { console.error('sales_framework seed:', (e && e.message) || e); } catch (_) {} }
}

async function getActiveFramework(env) {
  await ensureFrameworkSeeded(env);
  return await env.DB.prepare(
    `SELECT version, content, format, source, notes, created_by, created_at
     FROM sales_framework WHERE is_active = 1 ORDER BY version DESC LIMIT 1`
  ).first();
}

// Parte el markdown del playbook en secciones (por encabezados # .. ######).
// Cada sección = { order_idx, level, heading, body }. Sirve para retrieval
// dirigido y feedback por sección (en vez de mandar el blob entero al modelo).
function parseMarkdownSections(md) {
  const lines = String(md || '').split(/\r?\n/);
  const sections = [];
  let cur = null;
  let order = 0;
  for (const line of lines) {
    const m = line.match(/^(#{1,6})\s+(.*)$/);
    if (m) {
      if (cur) sections.push(cur);
      cur = { order_idx: order++, level: m[1].length, heading: m[2].trim(), body: '' };
    } else if (cur) {
      cur.body += (cur.body ? '\n' : '') + line;
    }
  }
  if (cur) sections.push(cur);
  return sections.map(s => ({ order_idx: s.order_idx, level: s.level, heading: s.heading, body: s.body.trim() }));
}

// Deriva (regenera) las secciones de una versión del playbook en framework_sections.
async function deriveFrameworkSections(env, version, content) {
  try {
    const secs = parseMarkdownSections(content);
    await env.DB.prepare('DELETE FROM framework_sections WHERE version = ?').bind(version).run();
    const now = new Date().toISOString();
    for (const s of secs) {
      await env.DB.prepare(
        `INSERT INTO framework_sections (version, order_idx, level, heading, body, tags, created_at)
         VALUES (?, ?, ?, ?, ?, '', ?)`
      ).bind(version, s.order_idx, s.level, s.heading, s.body, now).run();
    }
  } catch (e) { try { console.error('deriveFrameworkSections:', (e && e.message) || e); } catch (_) {} }
}

// Asegura que existan las secciones de una versión (deriva on-demand si faltan).
async function ensureSectionsForVersion(env, version, content) {
  try {
    const row = await env.DB.prepare('SELECT COUNT(*) AS n FROM framework_sections WHERE version = ?').bind(version).first();
    if (row && row.n > 0) return;
    await deriveFrameworkSections(env, version, content);
  } catch (_) {}
}

// Distancia de Levenshtein (para edit_distance entre sugerencia y mensaje enviado).
function levenshtein(a, b) {
  a = String(a || ''); b = String(b || '');
  if (a === b) return 0;
  if (!a.length) return b.length;
  if (!b.length) return a.length;
  let v0 = new Array(b.length + 1), v1 = new Array(b.length + 1);
  for (let i = 0; i <= b.length; i++) v0[i] = i;
  for (let i = 0; i < a.length; i++) {
    v1[0] = i + 1;
    for (let j = 0; j < b.length; j++) {
      const cost = a[i] === b[j] ? 0 : 1;
      v1[j + 1] = Math.min(v1[j] + 1, v0[j + 1] + 1, v0[j] + cost);
    }
    const tmp = v0; v0 = v1; v1 = tmp;
  }
  return v0[b.length];
}

// ===== Copiloto: motor de respuestas sugeridas (Fase 2) =====
// Reglas duras del agente (separadas del playbook, que va cacheado aparte).
const SUGGEST_SYSTEM_RULES = `Sos parte del equipo de ventas de Neon Infinito (carteles de neón LED y cursos para aprender a fabricarlos, Argentina). Te paso una conversación real de WhatsApp con un cliente y el PLAYBOOK de ventas del negocio. Tu tarea: sugerir el PRÓXIMO mensaje para mandarle al cliente, listo para enviar.

REGLAS DURAS (no negociables):
1. PRIMERO clasificá la vertical del lead: "carteles" (quiere un cartel para su local/un regalo), "cursos" (quiere aprender / Neon Mastery), "supernova" (ya fabrica y quiere escalar ventas), o "ambiguo". Aplicá el criterio de esa vertical (ver playbook: 8A.0 router + PARTE A carteles + PARTE B cursos). NUNCA cruces criterios: no mandes render/medidas/seña a un lead de curso, ni testimonios de "facturá millones" a un dueño de local que solo quiere un cartel.
2. NUNCA inventes NI AFIRMES datos que no estén EXPLÍCITOS en el chat o el playbook: precios, plazos de entrega, garantías, datos de pago, condiciones, NI el estado de un pedido (ej. "ya está en producción", "esta semana lo armamos"), fechas de avance, ni qué se fabricó/qué base lleva. Si no lo sabés con certeza por el chat, NO lo afirmes: preguntá o decí que lo confirmás (ej. "dejame chequear cómo viene y te confirmo"), ponelo en "missing_info" y bajá la confianza. Para cotizar un cartel hace falta foto + medidas (alto y ancho) + interior/exterior — nunca tires un precio a ojo.
3. TONO — imitá EXACTAMENTE cómo escribe el equipo (mirá los mensajes de JOACO en el historial). Es WhatsApp argentino informal, NO formal:
   - SIN signos de apertura: NUNCA uses ¿ ni ¡. Escribí "como va?" o "que bueno!", nunca "¿cómo va?" ni "¡qué bueno!".
   - SIN punto final: no cierres las oraciones con ".".
   - Emojis al MÍNIMO: 0 o como mucho 1 en todo el mensaje, nunca varios.
   - Voseo, frases cortas, cercano, humano. Nada robótico ni corporativo. Si no sabés el nombre, arrancá con "Buenas".
4. Espejá el registro de ESA conversación (nivel de formalidad, largo de los mensajes, cómo saluda Joaco). Tu sugerencia tiene que sentirse escrita por la misma persona que venía respondiendo, no por un bot.
5. Si conviene un humano (B2B de varios locales, dudas fuertes de precio/financiación, una queja, o te falta info clave para responder bien), poné should_escalate=true con el motivo y hacé un draft prudente (sin comprometer nada).
6. FORMATO — mandá como un humano real por WhatsApp: NO un bloque largo, sino VARIOS mensajes CORTOS, uno por idea (típico: el saludo por un lado, la respuesta por otro, la pregunta que sigue por otro). Separá cada mensaje con un DOBLE salto de línea (una línea en blanco entre uno y otro). Entre 1 y 4 mensajes, cada uno corto. Si es un "sí/no" simple o una sola idea, puede ser 1 solo. El campo "draft" tiene que venir con esos dobles saltos de línea entre los mensajes.

Devolvé SOLO un objeto JSON (sin markdown, sin texto extra) con EXACTAMENTE este shape (draft = los mensajes separados por doble salto de línea):
{"vertical":"carteles|cursos|supernova|ambiguo","intent":"string corto","draft":"mensaje 1\\n\\nmensaje 2\\n\\nmensaje 3","confidence":0.0,"sources_used":["secciones del playbook usadas"],"missing_info":["datos que faltan y NO inventaste, ej: precio, plazo, garantía"],"should_escalate":false,"escalation_reason":""}`;

// Reglas del copiloto para CLIENTES DEL SERVICIO DE CORTE (alumnos). Se apoya en la base de conocimiento /
// playbook del corte (el mismo que usa el bot), no en el de ventas de carteles/cursos.
const SUGGEST_CORTE_RULES = `Sos parte del equipo de Neon Infinito y atendés a los ALUMNOS del SERVICIO DE CORTE: cortamos bases acrílicas transparentes para que armen sus carteles, y también les vendemos cable. Te paso una conversación real de WhatsApp con un alumno y la BASE DE CONOCIMIENTO / PLAYBOOK del servicio de corte. Tu tarea: sugerir el PRÓXIMO mensaje para mandarle, listo para enviar.

REGLAS DURAS (no negociables):
1. Respondé SOLO con lo que está EXPLÍCITO en el chat o en la base de conocimiento del corte. NUNCA inventes ni afirmes precios, plazos, medios de pago, condiciones, ni el estado de un pedido. Si no lo sabés con certeza, no lo afirmes: decí que lo chequeás y confirmás, ponelo en "missing_info" y bajá la confianza.
2. Es el SERVICIO DE CORTE, NO ventas de carteles ni cursos: no ofrezcas cotización de carteles, renders, seña, ni charla de escalar ventas. Si el alumno quiere un CARTEL completo (no un corte), o es algo de la comunidad/curso, un reclamo/postventa o algo random → poné should_escalate=true (lo toma una persona).
3. Situate en la DINÁMICA SEMANAL (los pedidos entran toda la semana, se corta el finde, se cobra el lunes) y en el contexto interno que te paso: si hay un COBRO PENDIENTE o un CORTE EN PROCESO, seguí esa directiva (no empujes un pedido nuevo cuando el foco es el pago; si pregunta por el estado, respondé lo que dice el contexto).
4. TONO — WhatsApp argentino informal: SIN signos de apertura (NUNCA ¿ ni ¡), sin punto final, emojis al mínimo (0 o 1), voseo, frases cortas, humano. Si no sabés el nombre, arrancá con "Buenas".
5. FORMATO — varios mensajes CORTOS (entre 1 y 4), uno por idea, separados por DOBLE salto de línea (una línea en blanco entre cada uno).

Devolvé SOLO un objeto JSON (sin markdown, sin texto extra) con este shape (draft = los mensajes separados por doble salto de línea):
{"vertical":"corte","intent":"string corto","draft":"mensaje 1\\n\\nmensaje 2","confidence":0.0,"sources_used":["parte del playbook del corte usada"],"missing_info":["datos que faltan y NO inventaste"],"should_escalate":false,"escalation_reason":""}`;

// Genera una respuesta sugerida para el último mensaje de un chat. NO la envía.
// opts.dry=true devuelve el contexto armado sin llamar a Claude (para test/inspección).
async function suggestReply(env, phone, opts = {}) {
 try {
  const ctx = await buildChatContext(env, phone, 40);
  if (!ctx) return { ok: false, error: 'sin mensajes para este phone' };

  // ¿Cliente del SERVICIO DE CORTE? (está en corte_alumnos o su chat está en la bandeja 'corte').
  // Si sí, el copiloto se apoya en la base de conocimiento / playbook del corte, NO en el de ventas.
  let esCorte = false;
  try { esCorte = !!(await env.DB.prepare("SELECT 1 AS x FROM corte_alumnos WHERE telefono=? LIMIT 1").bind(phone).first()); } catch (_) {}
  if (!esCorte) { try { const ci = await env.DB.prepare("SELECT inbox FROM wa_chats_summary WHERE phone=?").bind(phone).first(); if (ci && ci.inbox === 'corte') esCorte = true; } catch (_) {} }
  // 3ª señal: ya tiene un pedido de corte cargado (cubre cobranzas que atiende el vigía con el bot apagado,
  // y clientes fuera del seed de corte_alumnos).
  if (!esCorte) { try { esCorte = !!(await env.DB.prepare("SELECT 1 AS x FROM corte_pedidos WHERE telefono=? LIMIT 1").bind(phone).first()); } catch (_) {} }

  let conv = null, examples = [], frameworkText = '', frameworkVersion = null, system, userContent;

  if (esCorte) {
    // Base de conocimiento del corte = el system del bot (playbook operativo) + el conocimiento curado (kv corte_knowledge).
    let kb = CORTE_LLM_SYSTEM;
    try { const extra = String(await kvGet(env, 'corte_knowledge', '') || '').trim(); if (extra) kb += '\n\nCONOCIMIENTO ADICIONAL (curado):\n' + extra; } catch (_) {}
    frameworkText = kb; frameworkVersion = 'corte-kb';
    // Contexto operativo del alumno (cobro pendiente / corte en proceso), mismo criterio que el bot de corte.
    let estadoCtx = '';
    try {
      // Mismo estado real que el bot (corteCtxEstado): sin despachadas/entregadas, total solo en cobro, + despacho/retiro reciente.
      const act = await corteCtxEstado(env, phone);
      if (act.enCobro) estadoCtx = '[COBRO PENDIENTE (interno): a este alumno YA le mandamos el cobro de su corte de esta semana, total $' + Number(act.total).toLocaleString('es-AR') + ', y esperamos el pago/comprobante. El foco es el pago, no un pedido nuevo.]\n\n';
      else if (act.n) estadoCtx = '[CORTE EN PROCESO (interno): este alumno YA tiene un corte de esta semana tomado y en producción (' + act.n + ' diseño(s)). Su pedido YA está; si pregunta por el estado / cuándo lo recibe: si va por envío, el lunes lo contacta Siempre a Tiempo (la logística) para coordinar el envío y pasarle el costo, que se paga por adelantado, y el martes se despacha (envío 24-72hs); si retira, lo retira en el taller de Colegiales.]\n\n';
      estadoCtx += corteCtxSalidas(act);
    } catch (_) {}
    userContent = estadoCtx + ctx.fullText + '\n\nSugerí el PRÓXIMO mensaje para mandarle al alumno ahora. Devolvé SOLO el JSON.';
    system = [
      { type: 'text', text: SUGGEST_CORTE_RULES },
      { type: 'text', text: '## BASE DE CONOCIMIENTO / PLAYBOOK DEL SERVICIO DE CORTE\n\n' + kb + '\n\n(NOTA: las instrucciones de salida en formato JSON del bot automático que aparecen arriba NO aplican al copiloto — seguí el shape de las REGLAS DURAS.)', cache_control: { type: 'ephemeral' } }
    ];
  } else {
    conv = await env.DB.prepare(
      `SELECT vertical, product_type, customer_profile, objections, what_worked, next_action
       FROM wa_conversations WHERE phone = ?`
    ).bind(phone).first();

    // Ejemplos ganadores: qué cerró en ventas concretadas del mismo producto.
    try {
      const exr = conv?.product_type
        ? await env.DB.prepare(`SELECT what_worked FROM wa_conversations WHERE outcome='sold' AND what_worked != '' AND product_type = ? ORDER BY last_analyzed_at DESC LIMIT 3`).bind(conv.product_type).all()
        : await env.DB.prepare(`SELECT what_worked FROM wa_conversations WHERE outcome='sold' AND what_worked != '' ORDER BY last_analyzed_at DESC LIMIT 3`).all();
      examples = (exr.results || []).map(e => e.what_worked).filter(Boolean);
    } catch (_) {}

    const fw = await getActiveFramework(env);
    frameworkText = fw?.content || '';
    frameworkVersion = fw?.version || null;

    userContent = ctx.fullText + '\n\n';
    if (conv) {
      userContent += `## ANÁLISIS PREVIO DEL CLIENTE\n`;
      if (conv.vertical) userContent += `Vertical: ${conv.vertical}\n`;
      if (conv.customer_profile) userContent += `Perfil: ${conv.customer_profile}\n`;
      if (conv.objections) userContent += `Objeciones detectadas: ${conv.objections}\n`;
      if (conv.next_action) userContent += `Próxima acción (del análisis): ${conv.next_action}\n`;
      userContent += '\n';
    }
    if (examples.length) {
      userContent += `## QUÉ FUNCIONÓ EN VENTAS CERRADAS PARECIDAS (referencia, no copiar literal)\n`;
      examples.forEach((e, i) => { userContent += `${i + 1}. ${e}\n`; });
      userContent += '\n';
    }
    userContent += `Sugerí el PRÓXIMO mensaje para mandarle al cliente ahora. Devolvé SOLO el JSON.`;
  }

  if (opts.dry) {
    return { ok: true, dry: true, corte: esCorte, framework_version: frameworkVersion, framework_chars: frameworkText.length,
             examples: examples.length, has_analysis: !!conv, user_chars: userContent.length,
             user_preview: userContent.slice(0, 1400) };
  }
  if (!env.ANTHROPIC_API_KEY) return { ok: false, error: 'ANTHROPIC_API_KEY no configurada' };

  if (!esCorte) system = [
    { type: 'text', text: SUGGEST_SYSTEM_RULES },
    { type: 'text', text: '## PLAYBOOK DE VENTAS\n\n' + frameworkText, cache_control: { type: 'ephemeral' } }
  ];
  try {
    const r = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({ model: 'claude-sonnet-4-5', max_tokens: 1000, system, messages: [{ role: 'user', content: userContent }] })
    });
    const j = await r.json();
    if (!r.ok) return { ok: false, error: j.error?.message || ('HTTP ' + r.status), raw: j };
    const text = j.content?.[0]?.text || '';
    let parsed;
    try { parsed = JSON.parse(text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim()); }
    catch (e) { return { ok: false, error: 'JSON parse error', raw: text.slice(0, 1500) }; }

    const missing = Array.isArray(parsed.missing_info) ? parsed.missing_info : [];
    const sensitive = missing.some(m => /precio|plazo|garant|pago|cuota|tiempo|entrega|financ/i.test(String(m)));
    const conf = typeof parsed.confidence === 'number' ? parsed.confidence : 0.5;
    const lowConfidence = conf < 0.7 || sensitive || parsed.should_escalate === true;
    const ti = j.usage?.input_tokens || 0;
    const tcw = j.usage?.cache_creation_input_tokens || 0;
    const tcr = j.usage?.cache_read_input_tokens || 0;
    const to = j.usage?.output_tokens || 0;
    // Costo real (precios Sonnet jun 2026): input $3, cache write $3.75, cache read $0.30, output $15 /MTok.
    const cost = +(((ti * 3 + tcw * 3.75 + tcr * 0.30 + to * 15) / 1000000).toFixed(5));
    try {
      await env.DB.prepare(
        `INSERT INTO copilot_usage (phone, kind, model, tokens_in, tokens_out, cache_read, cache_creation, cost_usd, created_by, created_at)
         VALUES (?, 'suggest', 'claude-sonnet-4-5', ?, ?, ?, ?, ?, ?, ?)`
      ).bind(phone, ti, to, tcr, tcw, cost, opts.createdBy || '', new Date().toISOString()).run();
    } catch (_) {}
    return {
      ok: true,
      suggestion: {
        vertical: parsed.vertical || (conv?.vertical || ''),
        intent: parsed.intent || '',
        draft: String(parsed.draft || ''),
        confidence: conf,
        low_confidence: lowConfidence,
        sources_used: Array.isArray(parsed.sources_used) ? parsed.sources_used : [],
        missing_info: missing,
        should_escalate: parsed.should_escalate === true || sensitive,
        escalation_reason: parsed.escalation_reason || (sensitive ? 'falta info sensible (precio/plazo/garantía) — confirmá con humano' : '')
      },
      framework_version: frameworkVersion,
      model: 'claude-sonnet-4-5',
      tokens_in: ti, tokens_out: to, cache_read: tcr, cache_creation: tcw,
      cost_usd: cost
    };
  } catch (e) {
    return { ok: false, error: String((e && e.message) || e) };
  }
 } catch (outer) {
   return { ok: false, error: 'suggest: ' + String((outer && outer.message) || outer) };
 }
}

