// Precios Anthropic (USD por MTok) [input, output]. Cache write (5 min) = 1,25× input; cache read = 0,1× input.
// Modelo desconocido → precio Sonnet (mejor estimar algo que dejarlo en 0).
const ANTHROPIC_PRICES = { 'claude-opus-4-5': [5, 25], 'claude-sonnet-4-5': [3, 15], 'claude-haiku-4-5': [1, 5] };
function anthropicCostUsd(model, u) {
  const m = String(model || '');
  const [pin, pout] = ANTHROPIC_PRICES[Object.keys(ANTHROPIC_PRICES).find(k => m.startsWith(k)) || 'claude-sonnet-4-5'];
  const ti = (u && u.input_tokens) || 0, to = (u && u.output_tokens) || 0;
  const tcr = (u && u.cache_read_input_tokens) || 0, tcw = (u && u.cache_creation_input_tokens) || 0;
  return +(((ti * pin + tcw * pin * 1.25 + tcr * pin * 0.1 + to * pout) / 1000000).toFixed(6));
}

// Registra una llamada a Claude en copilot_usage para que /admin/costs muestre el gasto real.
// kind: precotiz | corte | ocr | clasificador (suggest y synthesis insertan por su cuenta). by = origen
// (bot, pago_cartel, broadcast_reply, dry-run...). j = la respuesta JSON de /v1/messages.
// Best-effort: nunca tira, no puede frenar a un bot.
async function logAnthropicUsage(env, kind, model, j, phone, by) {
  try {
    const u = j && j.usage;
    if (!u) return;
    await env.DB.prepare(
      'INSERT INTO copilot_usage (phone, kind, model, tokens_in, tokens_out, cache_read, cache_creation, cost_usd, created_by, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
    ).bind(phone ? String(phone) : null, kind, model, u.input_tokens || 0, u.output_tokens || 0, u.cache_read_input_tokens || 0, u.cache_creation_input_tokens || 0, anthropicCostUsd(model, u), by || '', new Date().toISOString()).run();
  } catch (_) {}
}

// Costo real de Anthropic del mes en curso: copilot_usage (copiloto, síntesis, bots de precotización
// y corte, OCR de comprobantes, clasificadores) + wa_chat_analyses. by_kind / by_source = desglose.
async function computeAnthropicMonthCost(env) {
  const ms = new Date(); ms.setUTCDate(1); ms.setUTCHours(0, 0, 0, 0); const m = ms.toISOString();
  const out = { total: 0, suggest: 0, synthesis: 0, analysis: 0, precotiz: 0, corte: 0, ocr: 0, clasificador: 0, calls: 0, since: m, by_kind: [], by_source: [] };
  const byKind = {};
  try {
    const rows = (await env.DB.prepare(
      `SELECT kind, created_by, COUNT(*) AS n, SUM(cost_usd) AS c, SUM(tokens_in) AS ti, SUM(tokens_out) AS tout, SUM(cache_read) AS tcr, SUM(cache_creation) AS tcw
       FROM copilot_usage WHERE created_at >= ? GROUP BY kind, created_by`
    ).bind(m).all()).results || [];
    for (const r of rows) {
      const k = r.kind || '?';
      const b = byKind[k] || (byKind[k] = { kind: k, calls: 0, cost_usd: 0, tokens_in: 0, tokens_out: 0, cache_read: 0, cache_creation: 0 });
      b.calls += r.n || 0; b.cost_usd += r.c || 0;
      b.tokens_in += r.ti || 0; b.tokens_out += r.tout || 0; b.cache_read += r.tcr || 0; b.cache_creation += r.tcw || 0;
      // En suggest/synthesis created_by es el usuario del CRM (o 'cron'); en el resto, el origen de la llamada.
      out.by_source.push({ kind: k, source: r.created_by || '', calls: r.n || 0, cost_usd: +((r.c || 0).toFixed(4)) });
    }
  } catch (_) {}
  try {
    const an = await env.DB.prepare(
      `SELECT COUNT(*) AS n, SUM(cost_usd_estimated) AS c, SUM(tokens_in) AS ti, SUM(tokens_out) AS tout FROM wa_chat_analyses WHERE analyzed_at >= ?`
    ).bind(m).first();
    if (an && an.n) byKind.analysis = { kind: 'analysis', calls: an.n, cost_usd: an.c || 0, tokens_in: an.ti || 0, tokens_out: an.tout || 0, cache_read: 0, cache_creation: 0 };
  } catch (_) {}
  out.by_kind = Object.values(byKind).map(b => ({ ...b, cost_usd: +b.cost_usd.toFixed(4) })).sort((a, b) => b.cost_usd - a.cost_usd);
  out.by_source.sort((a, b) => b.cost_usd - a.cost_usd);
  let total = 0;
  for (const b of out.by_kind) {
    total += b.cost_usd; out.calls += b.calls;
    if (['suggest', 'synthesis', 'analysis', 'precotiz', 'corte', 'ocr', 'clasificador'].includes(b.kind)) out[b.kind] = b.cost_usd;
  }
  out.total = +total.toFixed(4);
  return out;
}

async function getUsdArsRate(env) {
  try {
    const row = await env.DB.prepare(`SELECT v FROM kv_cache WHERE k = 'usd_ars_rate'`).first();
    const n = row ? parseFloat(row.v) : NaN;
    return (isFinite(n) && n > 0) ? n : null;
  } catch (_) { return null; }
}

// ===== Circuit breaker: bloqueo de pago de WhatsApp (error Meta 131042 / 360dialog) =====
// Cuando Meta rechaza la ENTREGA con "Business eligibility payment issue" (131042) o 360dialog
// rechaza el envío con "This number is blocked due to lack of payment on client side", es un
// problema de PAGO de la cuenta, no del destinatario. Desde la migración a la WABA 1374216464651634
// (25-jul-2026) las plantillas se pagan con el SALDO PREPAGO de 360dialog (Funds, recargas con la
// tarjeta), NO las cobra Meta directo a la Visa: el destrabe es cargar fondos en hub.360dialog.com.
// Pausamos los envíos automáticos para no quemar contactos ni spamear a Gaspar,
// y reanudamos solos cuando un envío vuelve a salir OK (o tras un cooldown).
const WA_BILLING_BLOCK_KEY = 'wa_billing_block';
const WA_BILLING_COOLDOWN_MS = 3 * 60 * 60 * 1000;   // tras el último bloqueo, reintenta a las 3h
const WA_BILLING_NOTIFY_MS = 12 * 60 * 60 * 1000;    // avisa como mucho 1 vez cada 12h

function isBillingBlockError(code, msg) {
  if (code === 131042 || code === '131042') return true;
  const m = String(msg || '').toLowerCase();
  // 'lack of payment': texto de 360dialog ("This number is blocked due to lack of payment on client side.").
  return m.includes('eligibility') || m.includes('lack of payment') || (m.includes('payment') && m.includes('issue'));
}

// Registro de un episodio de rechazo por pago en kv: wa_billing_block (asíncrono, 131042 en el status: además
// frena los envíos automáticos 3 h) o wa_pay_reject (síncrono, ver waSend: solo constancia). Los dos con la misma
// regla de aviso. Devuelve { notify, since, turno, count }:
//  · notify: corresponde avisar (compuerta de 12 h) Y el episodio quedó guardado. Sin el episodio guardado no hay
//    dedup (la clave saldría de un since nuevo en cada rebote: la cadena aviso → rebote → aviso con la D1
//    sobrecargada). Mejor no avisar: si el rebote quedó anotado, lo avisa el cron (avisoBloqueoPagoCron).
//  · turno: el turno de 12 h dentro del episodio. La clave del aviso es 'wa_bloqueo:'+since+':'+turno: con la clave
//    por episodio sola, en 'on' el recordatorio de las 12 h chocaba con la fila del primer aviso y no salía (y un
//    bloqueo nuevo que heredaba un episodio sin cerrar tampoco). Dos rebotes simultáneos del mismo turno siguen
//    dando una sola fila.
//  · opts.soloRegistrar: el envío que rebotó era un AVISO → se anota el rebote (updated_at) sin gastar el turno y
//    nunca devuelve notify: un aviso no genera otro aviso. Si ese rebote tocaba avisar (pasaron +12 h del último
//    aviso), lo manda el cron a los 5 min, así en off/dry Gaspar recibe el mismo mensaje que hoy, apenas después.
// Si falla la LECTURA no se sabe si había episodio: se registra igual (el breaker de wa_billing_block tiene que
// quedar armado) con un UPSERT que no pisa since ni last_notify_at del que hubiera, y no se avisa.
async function waEpisodioPago(env, key, errMsg, opts = {}) {
  const now = Date.now();
  const err = String(errMsg || '').slice(0, 300);
  let row = null, leido = false;
  try { row = await env.DB.prepare('SELECT v FROM kv_cache WHERE k=?').bind(key).first(); leido = true; } catch (_) {}
  if (!leido) {
    const nuevo = { since: now, updated_at: now, count: 1, last_error: err, last_notify_at: 0 };
    try {
      await env.DB.prepare("INSERT INTO kv_cache (k, v, updated_at) VALUES (?, ?, ?) ON CONFLICT(k) DO UPDATE SET v = json_set(kv_cache.v, '$.updated_at', ?, '$.last_error', ?, '$.count', COALESCE(json_extract(kv_cache.v, '$.count'), 0) + 1), updated_at = excluded.updated_at")
        .bind(key, JSON.stringify(nuevo), new Date().toISOString(), now, err).run();
    } catch (_) {}
    return { notify: false, since: null, turno: 0, count: 0 };
  }
  let prev = null;
  try { if (row) prev = JSON.parse(row.v); } catch (_) {}   // JSON roto = sin episodio (se reescribe entero)
  const lastNotify = (prev && prev.last_notify_at) || 0;
  const since = (prev && prev.since) || now;
  const shouldNotify = !opts.soloRegistrar && (now - lastNotify) > WA_BILLING_NOTIFY_MS;
  const obj = { since, updated_at: now, count: ((prev && prev.count) || 0) + 1, last_error: err, last_notify_at: shouldNotify ? now : lastNotify };
  let guardado = false;
  try { await env.DB.prepare('INSERT INTO kv_cache (k, v, updated_at) VALUES (?, ?, ?) ON CONFLICT(k) DO UPDATE SET v=excluded.v, updated_at=excluded.updated_at').bind(key, JSON.stringify(obj), new Date().toISOString()).run(); guardado = true; } catch (_) {}
  return { notify: shouldNotify && guardado, since, turno: Math.floor((now - since) / WA_BILLING_NOTIFY_MS), count: obj.count };
}
// opts.soloRegistrar: el status 'failed' era de un envío al EQUIPO (un aviso, una lista, el reporte): ver waEpisodioPago.
async function setWaBillingBlock(env, errMsg, opts = {}) {
  const ep = await waEpisodioPago(env, WA_BILLING_BLOCK_KEY, errMsg, opts);
  return { shouldNotify: ep.notify, count: ep.count, since: ep.since, turno: ep.turno };
}

// Registro del rechazo por pago SÍNCRONO (ver waSend). Separado de wa_billing_block a propósito: no
// frena nada, solo deja constancia (GET /admin/envios-reintentos) y dedup del aviso (1 cada 12h).
// Lo cierra la próxima plantilla que salga OK (clearWaPayReject; si la que sale es un aviso, waPayRejectCerrarPorAviso).
const WA_PAY_REJECT_KEY = 'wa_pay_reject';
// Marca "volvió" pendiente: el episodio lo cerró una plantilla que ERA un aviso, así que el "volvió" lo manda el cron.
const WA_PAY_REJECT_VOLVIO_KEY = 'wa_pay_reject_volvio';
// Devuelve { notify, since, turno } (ver waEpisodioPago). Con soloRegistrar (el envío que rebotó era un aviso) se
// anota el rebote sin gastar el turno de aviso y nunca devuelve notify.
async function noteWaPayReject(env, errMsg, opts = {}) {
  return waEpisodioPago(env, WA_PAY_REJECT_KEY, errMsg, opts);
}
async function clearWaPayReject(env) {
  try {
    const row = await env.DB.prepare('SELECT 1 AS x FROM kv_cache WHERE k=?').bind(WA_PAY_REJECT_KEY).first();
    if (!row) return false;
    await env.DB.prepare('DELETE FROM kv_cache WHERE k=?').bind(WA_PAY_REJECT_KEY).run();
    return true;
  } catch (_) { return false; }
}
// Una plantilla que ERA un aviso salió OK: el envío no puede mandar el "volvió" (un aviso no genera otro aviso), pero
// el episodio sí se cierra, como hoy, y el "volvió" lo manda el cron (marca wa_pay_reject_volvio). Así un bloqueo
// nuevo no hereda un episodio viejo sin cerrar. Si al episodio le falta su aviso de "bloqueado" (el rebote que
// tocaba avisar fue de un aviso y el cron todavía no pasó), queda abierto: el cron manda primero ese y el próximo
// envío OK lo cierra con su "volvió", el mismo par de mensajes que hoy. 1 lectura por PK por plantilla de aviso.
async function waPayRejectCerrarPorAviso(env) {
  try {
    const row = await env.DB.prepare('SELECT v FROM kv_cache WHERE k=?').bind(WA_PAY_REJECT_KEY).first();
    if (!row) return;
    let ep = null; try { ep = JSON.parse(row.v); } catch (_) {}
    if (ep && waEpisodioAvisoPendiente(ep, Date.now())) return;
    const avisado = !!(ep && (Number(ep.last_notify_at) || 0) >= (Number(ep.since) || 0) && Number(ep.last_notify_at) > 0);
    const del = await env.DB.prepare('DELETE FROM kv_cache WHERE k = ? AND v = ?').bind(WA_PAY_REJECT_KEY, row.v).run();
    // Solo si de ese episodio se avisó el "bloqueado" (si no, un "volvió" suelto no le dice nada a nadie).
    if (avisado && del && del.meta && del.meta.changes) {
      await env.DB.prepare('INSERT OR IGNORE INTO kv_cache (k, v, updated_at) VALUES (?, ?, ?)').bind(WA_PAY_REJECT_VOLVIO_KEY, String(Date.now()), new Date().toISOString()).run();
    }
  } catch (_) {}
}
// ¿El episodio tiene un rebote que tocaba avisar y no se avisó? (rebote de un aviso, soloRegistrar, a +12 h del
// último aviso). Mismo criterio que la compuerta de 12 h de un envío normal: no agrega recordatorios que hoy no salen.
function waEpisodioAvisoPendiente(ep, now) {
  const last = Number(ep && ep.last_notify_at) || 0, upd = Number(ep && ep.updated_at) || 0;
  return (upd - last) > WA_BILLING_NOTIFY_MS && (now - last) > WA_BILLING_NOTIFY_MS && (now - upd) < 24 * 3600e3;
}
// Textos de siempre del aviso de bloqueo por pago (el envío que rebota y el cron mandan exactamente lo mismo).
function waPagoTxt(key, errText) {
  if (key === WA_BILLING_BLOCK_KEY) return '🔴 WhatsApp BLOQUEADO por pago — Meta error 131042 (problema de pago de la cuenta de WhatsApp Business).\nLas plantillas se pagan con el SALDO de 360dialog: revisá fondos y licencia en hub.360dialog.com (Funds / Invoices). Si ahí está todo bien, escribile al soporte de 360dialog (ellos manejan la línea de crédito con Meta).\nPausé los envíos automáticos para no quemar contactos — se reanudan solos cuando vuelva a andar.';
  return '🔴 WhatsApp rechaza envíos por un problema de PAGO.\nError: ' + errText + '\nLas plantillas se pagan con el SALDO de 360dialog: cargá fondos en hub.360dialog.com → Funds (si el saldo está bien, fijate que la licencia del número esté paga en Invoices).\nLas campañas automáticas quedan en pausa sin quemar contactos y se reanudan solas cuando vuelva a salir una plantilla.';
}
async function avisoBloqueoPago(env, key, since, turno, errText) {
  const txt = waPagoTxt(key, errText);
  return avisoInterno(env, {
    para: ['gaspar', 'bruno'], tipo: 'wa_bloqueo_pago', prioridad: 'P1', texto: txt, clave: 'wa_bloqueo:' + since + ':' + turno,
    legacy: env.ADMIN_NOTIFY_PHONE ? () => waSendText(env, env.ADMIN_NOTIFY_PHONE, txt, { esAviso: true }) : null,
    legacyDest: env.ADMIN_NOTIFY_PHONE,
  });
}
async function avisoPagoVolvio(env) {
  const txt = 'WhatsApp volvió a mandar plantillas — las campañas automáticas se reanudan solas';
  return avisoInterno(env, {
    para: ['gaspar', 'bruno'], tipo: 'wa_bloqueo_pago_ok', prioridad: 'P2', texto: txt,
    legacy: env.ADMIN_NOTIFY_PHONE ? () => waSendText(env, env.ADMIN_NOTIFY_PHONE, txt, { esAviso: true }) : null,
    legacyDest: env.ADMIN_NOTIFY_PHONE,
  });
}
// Cron */5 (processAvisosTick, en CUALQUIER modo): manda el aviso de bloqueo que el envío no pudo mandar porque el
// que rebotó era un aviso (soloRegistrar), y el "volvió" de un episodio que cerró una plantilla de aviso. Así
// ningún aviso genera otro (lo genera el cron) y off/dry quedan como hoy, con hasta 5 min de demora. El turno se
// reclama con un UPDATE condicional sobre el valor leído (compare-and-swap): dos ticks no avisan dos veces y, si la
// D1 no guarda el turno, no se avisa. 3 lecturas por PK por tick.
async function avisoBloqueoPagoCron(env, med = null) {
  const rows = await avQ(env, 'SELECT k, v FROM kv_cache WHERE k IN (?, ?, ?)', [WA_PAY_REJECT_KEY, WA_BILLING_BLOCK_KEY, WA_PAY_REJECT_VOLVIO_KEY], med);
  const now = Date.now();
  for (const r of rows) {
    try {
      if (r.k === WA_PAY_REJECT_VOLVIO_KEY) {
        const del = await env.DB.prepare('DELETE FROM kv_cache WHERE k = ? AND v = ?').bind(r.k, r.v).run();
        if (med) med.add(del);
        if (del && del.meta && del.meta.changes) await avisoPagoVolvio(env);
        continue;
      }
      let ep = null; try { ep = JSON.parse(r.v); } catch (_) {}
      if (!ep || !waEpisodioAvisoPendiente(ep, now)) continue;
      const cas = await env.DB.prepare('UPDATE kv_cache SET v = ?, updated_at = ? WHERE k = ? AND v = ?').bind(JSON.stringify({ ...ep, last_notify_at: now }), new Date().toISOString(), r.k, r.v).run();
      if (med) med.add(cas);
      if (!cas || !cas.meta || !cas.meta.changes) continue;
      const since = Number(ep.since) || now;
      await avisoBloqueoPago(env, r.k, since, Math.floor((now - since) / WA_BILLING_NOTIFY_MS), ep.last_error || '');
    } catch (_) {}
  }
}

async function clearWaBillingBlock(env) {
  try {
    const row = await env.DB.prepare('SELECT v FROM kv_cache WHERE k=?').bind(WA_BILLING_BLOCK_KEY).first();
    if (!row) return false; // no estaba bloqueado
    await env.DB.prepare('DELETE FROM kv_cache WHERE k=?').bind(WA_BILLING_BLOCK_KEY).run();
    return true; // estaba bloqueado y se resolvió
  } catch (_) { return false; }
}

async function isWaBillingBlocked(env) {
  try {
    const row = await env.DB.prepare('SELECT v FROM kv_cache WHERE k=?').bind(WA_BILLING_BLOCK_KEY).first();
    if (!row) return false;
    const obj = JSON.parse(row.v);
    return (Date.now() - ((obj && obj.updated_at) || 0)) < WA_BILLING_COOLDOWN_MS;
  } catch (_) { return false; }
}

// ===== Plantillas "al toque" (creadas por vendedores) =====
// Guardrails: el vendedor no conoce las reglas de Meta, así que validamos el
// contenido ANTES de mandarlo a Meta. Si no cumple, ni se intenta crear.
// Devuelve un mensaje de error (string) si NO cumple, o null si está OK.
function validateAdhocTemplate(text) {
  const t = String(text || '').trim();
  if (t.length < 10) return 'El texto es muy corto (mínimo 10 caracteres).';
  if (t.length > 600) return 'El texto es muy largo (máximo 600 caracteres).';
  if (/https?:\/\/|www\.|wa\.me|t\.me|\b\S+\.(com|net|ar|org|io)\b/i.test(t)) return 'No se permiten links en la plantilla.';
  if (/[A-ZÁÉÍÓÚÑ]{5,}/.test(t)) return 'Evitá palabras en MAYÚSCULAS (Meta las rechaza).';
  if (/\d{7,}/.test(t)) return 'No incluyas números largos (teléfonos o códigos).';
  if (/(.)\1{6,}/.test(t)) return 'Hay caracteres repetidos de más.';
  return null;
}

// --- Dedup de plantillas adhoc (fix restricción Meta jul-2026) ---------------
// El feature "crear plantilla al toque" creaba una plantilla MARKETING NUEVA por
// cada mensaje fuera de ventana → ~155 plantillas casi todas MARKETING → patrón
// que Meta penaliza como spam (causó la inhabilitación de la cuenta). body_norm
// es el texto normalizado; sirve para detectar un texto ya usado y REUSAR la
// plantilla aprobada en vez de crear otra.
function adhocBodyNorm(text) {
  return String(text || '').trim().toLowerCase().replace(/\s+/g, ' ').slice(0, 600);
}

// Remitente que se guarda en el chat para una plantilla ad-hoc: solo si quien la escribió es un
// vendedor comercial (Joaco o un secundario); si no (Abril, admin) → ''. Sin consultar la base a
// propósito: getSessionRole/resolveComercial caen a 'comercial'/'joaco' si D1 falla, y le
// atribuirían a Joaco algo que mandó otra persona.
function adhocSenderSlug(user) {
  const k = String(user || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
  if (k === 'joaquin' || k === 'joaco') return 'joaco';
  return VENDEDORES_SECUNDARIOS.includes(k) ? k : '';
}
// Autor de una acción para el panel de rendimiento: slug del vendedor (joaco/facundo/agustina) o, si
// no es vendedor, el usuario en minúscula (gaspar, abril…). A diferencia de resolveComercial, NO cae
// al dueño del chat: registra quién lo hizo de verdad.
function autorSlug(user) {
  return adhocSenderSlug(user) || String(user || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
}

// Registra en el chat una plantilla ad-hoc ya enviada (reuso inmediato o envío del cron cuando Meta
// la aprueba). La escribió una persona → automated=0 (sin badge "automático"; el bot de precotización
// la cuenta como humano). Si el webhook de estado de Meta llegó antes y creó la fila 'status' vacía,
// el upsert la pisa con el texto; y como el trigger de la lista de chats es AFTER INSERT (no corre en
// el DO UPDATE), también se corrige la vista previa si quedó mostrando esa fila fantasma.
async function registrarPlantillaAdhocEnChat(env, { phone, wamid, texto, senderSlug }) {
  if (!wamid) return;
  try {
    await env.DB.prepare(
      `INSERT INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, status, context_id, automated)
       VALUES (?, ?, 'outbound', ?, ?, 'template', ?, 'sent', '', 0)
       ON CONFLICT(wamid) DO UPDATE SET body = excluded.body, msg_type = 'template', sender_name = excluded.sender_name, automated = 0
         WHERE wa_messages.body IS NULL OR wa_messages.body = '' OR wa_messages.msg_type = 'status'`
    ).bind(new Date().toISOString(), wamid, phone, senderSlug || '', String(texto || '')).run();
    // Solo si la vista previa es justo la fila de ESTE envío (no otra fantasma del mismo chat).
    await env.DB.prepare(
      "UPDATE wa_chats_summary SET last_body = ?, last_msg_type = 'template' WHERE phone = ? AND last_direction = 'outbound' AND last_msg_type = 'status' AND (last_body IS NULL OR last_body = '') AND last_ts = (SELECT ts FROM wa_messages WHERE wamid = ?)"
    ).bind(String(texto || '').slice(0, 300), phone, wamid).run();
  } catch (_) {}
}
let _adhocSchemaReady = false;
async function ensureAdhocSchema(env) {
  if (_adhocSchemaReady) return;
  try { await env.DB.prepare("ALTER TABLE wa_pending_template_send ADD COLUMN body_norm TEXT DEFAULT ''").run(); } catch (_) {}
  try { await env.DB.prepare("CREATE INDEX IF NOT EXISTS idx_pending_tpl_bodynorm ON wa_pending_template_send(body_norm, status)").run(); } catch (_) {}
  _adhocSchemaReady = true;
}

// Mapea el vendedor que creó la plantilla ad-hoc (created_by = nombre visible del user:
// Gaspar/Joaquín/Bruno/Abril/Facundo) a su teléfono, para avisarle A ÉL si su plantilla
// salió o falló — antes el aviso iba solo a env.ADMIN_NOTIFY_PHONE, que estaba SIN setear
// (por eso "no avisan"). Desconocidos (Abril/Facundo) -> Gaspar, así el aviso nunca es mudo.
function adhocNotifyPhone(createdBy) {
  const u = String(createdBy || '').trim().toLowerCase();
  if (u.startsWith('joaqu') || u === 'joaco') return '5491137593269';
  if (u.startsWith('bruno')) return '5491155604996';
  return '5491155604999'; // Gaspar (y fallback para Abril/Facundo/desconocido)
}

// Cron: manda las plantillas "al toque" apenas Meta las aprueba (el vendedor no
// espera en el chat). Reintenta si el envío falla; marca rejected/expired.
// Se llama SOLO en horario hábil AR para no escribir de madrugada.
async function processPendingTemplateSends(env) {
  if (await isWaBillingBlocked(env)) return;
  let pend;
  try {
    const rs = await env.DB.prepare(
      "SELECT template_name, phone, body_preview, created_at, created_by FROM wa_pending_template_send WHERE status = 'pending' ORDER BY created_at ASC LIMIT 20"
    ).all();
    pend = rs.results || [];
  } catch (_) { return; }
  if (!pend.length) return;
  // Estado actual de las plantillas (un solo fetch).
  const statusByName = {};
  try {
    const _wa = getWaClient(env);
    const sep = _wa.templatesUrl().includes('?') ? '&' : '?';
    // limit=500: hay ~320 plantillas (270 son adhoc_) y con limit=200 el cron NO veía las
    // que quedaban fuera de las primeras 200 -> plantillas que Meta YA aprobó nunca se
    // enviaban y expiraban en silencio (causa principal de "muchas no salen"). TODO: limpiar
    // plantillas adhoc viejas en Meta (crecen ~/día y Meta penaliza tener muchas MARKETING).
    const r = await fetch(`${_wa.templatesUrl()}${sep}limit=500&fields=name,status`, { headers: _wa.headers });
    const data = await r.json().catch(() => ({}));
    for (const t of (data.data || data.waba_templates || [])) statusByName[t.name] = String(t.status || '').toLowerCase();
  } catch (_) { return; }
  const now = Date.now();
  for (const row of pend) {
    const st = statusByName[row.template_name];
    if (st === 'approved') {
      // La plantilla la escribió un vendedor: se registra como mensaje de persona (automated=0, con su
      // remitente), igual que el reuso inmediato. Antes quedaba automated=1 → badge "automático" y el
      // bot de precotización no la contaba como humano.
      const senderSlug = adhocSenderSlug(row.created_by);
      const rt = await waSendTemplate(env, row.phone, row.template_name, 'es_AR', []);
      if (rt.ok) {
        await registrarPlantillaAdhocEnChat(env, { phone: row.phone, wamid: rt.id || '', texto: row.body_preview, senderSlug });
        try { await env.DB.prepare("UPDATE wa_pending_template_send SET status='sent', updated_at=? WHERE template_name=?").bind(new Date().toISOString(), row.template_name).run(); } catch (_) {}
        // [Etapa 1] avisoAdmin (legacy = el texto de siempre). Decisión 1 de §6: va al resumen (P3) con los avisos prendidos.
        if (env.ADMIN_NOTIFY_PHONE) { try { await avisoAdmin(env, `✅ Plantilla aprobada y enviada a ${row.phone}:\n"${(row.body_preview || '').slice(0, 120)}"`, { tipo: 'plantilla_enviada', prioridad: 'P3', refPhone: row.phone }); } catch (_) {} }
        await new Promise(rs => setTimeout(rs, 400));
      }
      // si el envío falla, queda 'pending' y reintenta el próximo tick
    } else if (st === 'rejected') {
      try { await env.DB.prepare("UPDATE wa_pending_template_send SET status='rejected', updated_at=? WHERE template_name=?").bind(new Date().toISOString(), row.template_name).run(); } catch (_) {}
      // Avisar AL VENDEDOR que la creó (antes solo a env.ADMIN_NOTIFY_PHONE, sin setear -> mudo).
      try { await waSendText(env, adhocNotifyPhone(row.created_by), `❌ Meta rechazó tu plantilla para reflotar a ${row.phone}:\n"${(row.body_preview || '').slice(0, 100)}"\nNO salió. Probá de nuevo con un texto más simple (sin links ni MAYÚSCULAS) o escribile a mano.`); } catch (_) {}
    } else if ((now - new Date(row.created_at).getTime()) > 24 * 60 * 60 * 1000) {
      try { await env.DB.prepare("UPDATE wa_pending_template_send SET status='expired', updated_at=? WHERE template_name=?").bind(new Date().toISOString(), row.template_name).run(); } catch (_) {}
      // Avisar AL VENDEDOR: Meta no la aprobó en 24h -> NO salió (antes expiraba en silencio).
      try { await waSendText(env, adhocNotifyPhone(row.created_by), `⌛ Meta no aprobó en 24h tu plantilla para reflotar a ${row.phone}:\n"${(row.body_preview || '').slice(0, 100)}"\nNO salió. Reintentá (a veces aprueba al 2º intento) o escribile a mano.`); } catch (_) {}
    }
  }
}

// ===== Limpieza de plantillas ad-hoc viejas =====
// Meta penaliza tener MUCHAS plantillas MARKETING (nos costó un ban en jul-2026 con ~155).
// Las adhoc de reflote son de UN SOLO USO: a los N días ya cumplieron. Esta limpieza borra de
// Meta las adhoc cuya última actividad (creación por el ts del nombre adhoc_<ms>, o el último
// envío registrado) es > N días, SALVO que tengan un envío pendiente. Mantiene el total bajo
// (equilibrio ~ ritmo_de_creación × N). Solo Cloud API (meta): DELETE .../message_templates?name=.
async function adhocCleanup(env, opts) {
  opts = opts || {};
  const days = parseInt(opts.days != null ? opts.days : await kvGet(env, 'adhoc_cleanup_days', '7'), 10) || 7;
  const dryRun = !!opts.dryRun;
  const _waT = getWaClient(env);
  const is360 = _waT.provider === '360dialog';
  if (_waT.provider !== 'meta' && !is360) return { ok: false, error: 'provider no soportado para cleanup', provider: _waT.provider };
  const sep = _waT.templatesUrl().includes('?') ? '&' : '?';
  const max = (opts.max != null && opts.max !== '') ? (parseInt(opts.max, 10) || 0) : Infinity;
  let all = [];
  try {
    const rr = await fetch(`${_waT.templatesUrl()}${sep}limit=500&fields=name,status`, { headers: _waT.headers });
    const dd = await rr.json().catch(() => ({}));
    all = (dd.data || dd.waba_templates || []);
  } catch (e) { return { ok: false, error: 'no se pudo listar plantillas: ' + ((e && e.message) || e) }; }
  const adhoc = all.filter(t => String(t.name || '').startsWith('adhoc_'));
  const cutoff = Date.now() - days * 86400000;
  // último envío + si hay pendientes, por template_name (para NO borrar algo en uso/por salir)
  const pend = {};
  try {
    const rs = await env.DB.prepare(
      "SELECT template_name, MAX(created_at) AS last_at, SUM(CASE WHEN status='pending' THEN 1 ELSE 0 END) AS n_pend FROM wa_pending_template_send WHERE template_name LIKE 'adhoc\\_%' ESCAPE '\\' GROUP BY template_name"
    ).all();
    for (const r of (rs.results || [])) pend[r.template_name] = { last: r.last_at ? new Date(r.last_at).getTime() : 0, pending: (r.n_pend || 0) > 0 };
  } catch (_) {}
  const toDelete = [];
  for (const t of adhoc) {
    const nm = t.name;
    const m = String(nm).match(/^adhoc_(\d+)/);
    const createdTs = m ? parseInt(m[1], 10) : 0;
    const info = pend[nm] || { last: 0, pending: false };
    if (info.pending) continue;                              // tiene un envío pendiente -> no tocar
    if (Math.max(createdTs, info.last) > cutoff) continue;   // creada/usada hace poco -> no tocar
    toDelete.push(nm);
  }
  if (dryRun) return { ok: true, dry_run: true, days, total_adhoc: adhoc.length, to_delete: toDelete.length, keep: adhoc.length - toDelete.length, sample: toDelete.slice(0, 8) };
  let deleted = 0, failed = 0; const errs = [];
  for (const nm of toDelete.slice(0, max)) {
    try {
      // 360dialog borra por nombre en el PATH; Meta (Cloud API) por ?name=.
      const durl = is360 ? `${_waT.templatesUrl()}/${encodeURIComponent(nm)}` : `${_waT.templatesUrl()}${sep}name=${encodeURIComponent(nm)}`;
      const dr = await fetch(durl, { method: 'DELETE', headers: _waT.headers });
      if (dr.ok) { deleted++; try { await env.DB.prepare("DELETE FROM wa_pending_template_send WHERE template_name = ?").bind(nm).run(); } catch (_) {} }
      else { failed++; if (errs.length < 3) errs.push(dr.status + ': ' + (await dr.text().catch(() => '')).slice(0, 140)); }
      await new Promise(rs => setTimeout(rs, 40));   // no martillar la API
    } catch (_) { failed++; }
  }
  return { ok: true, days, total_adhoc: adhoc.length, deleted, failed, remaining_adhoc: adhoc.length - deleted, errs };
}
// Corre la limpieza 1 vez por día (gate por fecha AR en kv). Llamada desde el cron.
async function maybeAdhocCleanup(env) {
  try {
    if ((await kvGet(env, 'adhoc_cleanup_on', '1')) !== '1') return;   // kill-switch
    const fechaAR = new Date(Date.now() - 3 * 3600 * 1000).toISOString().slice(0, 10);
    if ((await kvGet(env, 'adhoc_cleanup_last', '')) === fechaAR) return;
    await kvSet(env, 'adhoc_cleanup_last', fechaAR);   // marcar ANTES para no repetir aunque tarde/falle
    const res = await adhocCleanup(env, {});
    // [Etapa 1] avisoAdmin (legacy = el texto de siempre al personal de Gaspar). Decisión 1 de §6: al resumen (P3).
    if (res && res.deleted) { try { await avisoAdmin(env, `🧹 Limpieza plantillas ad-hoc: borré ${res.deleted} viejas, quedan ${res.remaining_adhoc}.`, { tipo: 'adhoc_limpieza', prioridad: 'P3', to: '5491155604999' }); } catch (_) {} }
  } catch (_) {}
}

// ===== Producción de NEÓN: productores, estados por cartel y mano de obra por tiempo (15-oct-2026) =====
// Gaspar (15-oct): cada productor tiene su usuario y ve SOLO sus carteles asignados, sin el precio de venta: lo que
// le corresponde, color, foto del diseño y aclaraciones; pone el estado de cada uno y al terminarlo sube sí o sí una
// foto de cada cartel. Gaspar asigna los carteles desde Pedidos / Producción y marca qué trabajos ya les pagó.
// Mano de obra desde kv 'mo_desde' (regla tiempo_v1): % del precio + $ por minuto de armado según los tiempos medidos
// (fijo + por tramo + por metro + por m²), × cantidad, con tope % del precio. Los pedidos anteriores: % del mes (pct_mes).
// Los VALORES viven SOLO en D1 (cotizador_params mo_*, se editan en Admin). Gaspar (15-oct): "esto NUNCA se puede
// mostrar, los productores solo tienen que saber su pago por producir" → nada de números en el código (el repo es
// público) ni en lo que ve un productor o un vendedor. El monto queda guardado en el pedido y se congela al pagarlo.
const MO_KEYS = ['mo_pct_precio', 'mo_valor_min', 'mo_min_fijo', 'mo_min_tramo', 'mo_min_metro', 'mo_min_m2', 'mo_tope_pct'];
const MO_DESDE_DEFAULT = '2026-10-15';
const PROD_ESTADOS = ['pendiente', 'en_armado', 'terminado'];
// null si falta algún parámetro (o falla D1): entonces NO se calcula ni se borra nada.
async function moConfig(env) {
  const p = { desde: MO_DESDE_DEFAULT };
  try {
    const rs = await env.DB.prepare(`SELECT key, value FROM cotizador_params WHERE key IN (${MO_KEYS.map(() => '?').join(',')})`).bind(...MO_KEYS).all();
    for (const r of (rs.results || [])) { const n = Number(r.value); if (isFinite(n) && n >= 0) p[r.key] = n; }
  } catch (_) { return null; }
  if (MO_KEYS.some(k => !(k in p))) return null;
  try { const d = await kvGet(env, 'mo_desde', null); if (d && /^\d{4}-\d{2}-\d{2}$/.test(String(d))) p.desde = String(d); } catch (_) {}
  return p;
}
// % de mano de obra que se usaba por mes (COGS): 13,5% hasta septiembre de 2026, 12% desde octubre.
function moPctMes(fecha) { return String(fecha || '') < '2026-10-01' ? 0.135 : 0.12; }
// Mano de obra de UNA fila de pedido (un cartel × cantidad). null si faltan datos para calcularla.
function calcManoObra(row, P) {
  const precio = +row.precio || 0;
  if (!(precio > 0)) return null;
  // Instalación, envío, flete… cargados como línea del pedido (sin medidas): no los produce nadie, no llevan mano de obra (Gaspar 17-oct).
  if (neonNoCartel(row)) return null;
  if (String(row.fecha || '') < P.desde) {
    const pct = moPctMes(row.fecha);
    return { monto: Math.round(pct * precio), regla: 'pct_mes', detalle: { pct } };
  }
  const cant = +row.cantidad > 0 ? +row.cantidad : 1;
  const t = +row.tramos || 0, m = (+row.cm_neon || 0) / 100, a = ((+row.alto || 0) * (+row.ancho || 0)) / 10000;
  if (!(t >= 1) || !(m > 0) || !(a > 0)) return null;
  const min = P.mo_min_fijo + P.mo_min_tramo * t + P.mo_min_metro * m + P.mo_min_m2 * a;
  const bruto = P.mo_pct_precio * precio + P.mo_valor_min * cant * min;
  const tope = P.mo_tope_pct * precio;
  const monto = Math.round(Math.min(bruto, tope));
  return { monto, regla: 'tiempo_v1', detalle: { min: Math.round(min), cant, en_tope: bruto > tope } };
}
// Recalcula y guarda la mano de obra de esos pedidos de neón (nunca la de un trabajo ya pagado al productor).
async function moActualizar(env, ids) {
  ids = (ids || []).map(Number).filter(n => n > 0);
  if (!ids.length) return 0;
  if (ids.length > 90) { let n = 0; for (let i = 0; i < ids.length; i += 90) n += await moActualizar(env, ids.slice(i, i + 90)); return n; }
  await ensureProdSchema(env);
  const P = await moConfig(env);
  if (!P) return 0;
  const rows = (await env.DB.prepare(`SELECT id, fecha, cartel, precio, cantidad, tramos, cm_neon, alto, ancho, es_corporeo, prod_pagado_at, mo_monto FROM pedidos WHERE id IN (${ids.map(() => '?').join(',')})`).bind(...ids).all()).results || [];
  const now = new Date().toISOString(), stmts = [];
  for (const r of rows) {
    if (+r.es_corporeo || r.prod_pagado_at) continue;
    const mo = calcManoObra(r, P);
    if (!mo) { if (r.mo_monto != null) stmts.push(env.DB.prepare("UPDATE pedidos SET mo_monto = NULL, mo_regla = '', mo_detalle = NULL, mo_at = ? WHERE id = ?").bind(now, r.id)); continue; }
    if (r.mo_monto != null && Math.round(+r.mo_monto) === mo.monto) continue;
    stmts.push(env.DB.prepare('UPDATE pedidos SET mo_monto = ?, mo_regla = ?, mo_detalle = ?, mo_at = ? WHERE id = ?').bind(mo.monto, mo.regla, JSON.stringify(mo.detalle), now, r.id));
  }
  if (stmts.length) await env.DB.batch(stmts);
  return stmts.length;
}
let _prodSchemaOk = false;
async function ensureProdSchema(env) {
  if (_prodSchemaOk) return true;
  let tiene = false;
  try { tiene = !!(await env.DB.prepare("SELECT 1 AS x FROM pragma_table_info('pedidos') WHERE name = 'mo_at'").first()); } catch (_) {}
  if (!tiene) {
    for (const col of ["productor_id TEXT DEFAULT ''", "prod_estado TEXT DEFAULT ''", 'prod_estado_at TEXT', 'prod_asignado_at TEXT', 'prod_terminado_at TEXT', 'prod_pagado_at TEXT', "prod_pagado_por TEXT DEFAULT ''", 'mo_monto REAL', "mo_regla TEXT DEFAULT ''", 'mo_detalle TEXT', 'mo_at TEXT']) {
      try { await env.DB.prepare(`ALTER TABLE pedidos ADD COLUMN ${col}`).run(); } catch (_) {}
    }
  }
  try {
    await env.DB.batch([
      env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_pedidos_productor ON pedidos (productor_id)'),
      env.DB.prepare('CREATE TABLE IF NOT EXISTS pedido_prod_fotos (id INTEGER PRIMARY KEY AUTOINCREMENT, pedido_id INTEGER NOT NULL, r2_key TEXT NOT NULL, subido_por TEXT, created_at TEXT)'),
      env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_pedido_prod_fotos_pedido ON pedido_prod_fotos (pedido_id)'),
      env.DB.prepare('CREATE TABLE IF NOT EXISTS pedido_prod_log (id INTEGER PRIMARY KEY AUTOINCREMENT, pedido_id INTEGER, campo TEXT, de TEXT, a TEXT, por TEXT, ts TEXT)'),
      env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_pedido_prod_log_pedido ON pedido_prod_log (pedido_id)')
    ]);
  } catch (_) { return false; }
  _prodSchemaOk = true;
  return true;
}
// Usuarios que NO pueden ser productores (ya existen con otro rol o son del equipo).
const PROD_RESERVADOS = ['gaspar', 'admin', 'administrador', 'joaco', 'joaquin', 'facundo', 'facu', 'agustina', 'agus', 'abril', 'cursos', 'disenador', 'emma', 'emmanuel', 'logistica', 'sinfrontera', 'anibal', 'neyen', 'nadia', 'debi', 'debora'];
function prodSlug(s) { return String(s || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''); }
// ¿La sesión es de un PRODUCTOR? {id, nombre, activo} o null. Mira users_panel con cualquier activo: un productor
// dado de baja con una sesión vieja NO puede caer al rol por defecto ('comercial') y ver ventas. Cache 60 s por isolate.
const _prodSesCache = new Map();
async function productorDeSesion(env, userName) {
  const slug = prodSlug(userName);
  if (!slug || slug === 'gaspar' || PROD_RESERVADOS.includes(slug)) return null;
  const c = _prodSesCache.get(slug);
  if (c && Date.now() - c.at < 60000) return c.p;
  let p = null;
  try {
    const u = await env.DB.prepare("SELECT id, nombre, activo FROM users_panel WHERE id = ? AND rol = 'productor' LIMIT 1").bind(slug).first();
    if (u) p = { id: String(u.id), nombre: String(u.nombre || u.id), activo: +u.activo === 1 };
  } catch (_) { return { error: true, activo: false, id: slug }; }   // no se pudo verificar: el muro cierra (503)
  _prodSesCache.set(slug, { p, at: Date.now() });
  return p;
}
async function prodLog(env, items) {
  if (!items.length) return;
  for (let i = 0; i < items.length; i += 50) { const lote = items.slice(i, i + 50); try { await env.DB.batch(lote.map(x => env.DB.prepare('INSERT INTO pedido_prod_log (pedido_id, campo, de, a, por, ts) VALUES (?,?,?,?,?,?)').bind(x.pedido_id, x.campo, String(x.de ?? ''), String(x.a ?? ''), String(x.por || ''), new Date().toISOString()))); } catch (_) {} }
}
// Fotos del cartel terminado que pide el estado 'terminado': una por cartel (cantidad), máximo 5.
function prodFotosRequeridas(row) { return Math.min(5, Math.max(1, Math.round(+row.cantidad || 1))); }
// Carteles de producción con lo que cada uno puede ver. paraProductor=true: SIN precio, teléfono, envío ni vendedor.
async function prodCarteles(env, whereSql, args, paraProductor) {
  await ensureProdSchema(env);
  try { await ensureCorteNeonSchema(env); } catch (_) {}
  const cols = paraProductor
    ? 'p.id, p.numero, p.fecha, p.cartel, p.colores, p.alto, p.ancho, p.cm_neon, p.tramos, p.cantidad, p.base, p.dimer, p.tipo, p.aclaracion, p.productor_id, p.prod_estado, p.prod_estado_at, p.prod_asignado_at, p.prod_terminado_at, p.prod_pagado_at, p.mo_monto'
    : 'p.id, p.numero, p.fecha, p.cartel, p.colores, p.alto, p.ancho, p.cm_neon, p.tramos, p.cantidad, p.base, p.dimer, p.tipo, p.aclaracion, p.precio, p.estado_pago, p.estado_pedido, p.comercial_id, p.cargado_por, p.productor, p.productor_id, p.prod_estado, p.prod_estado_at, p.prod_asignado_at, p.prod_terminado_at, p.prod_pagado_at, p.prod_pagado_por, p.mo_monto, p.mo_regla, p.mo_detalle';
  const rows = (await env.DB.prepare(
    `SELECT ${cols}, COALESCE(NULLIF(cp.foto_key, ''), NULLIF(p.foto_diseno_key, '')) AS diseno_key, cp.estado AS corte_estado
       FROM pedidos p
       LEFT JOIN (SELECT pedido_id, MAX(id) AS cid FROM corte_pedidos WHERE pedido_id IS NOT NULL GROUP BY pedido_id) cx ON cx.pedido_id = p.id
       LEFT JOIN corte_pedidos cp ON cp.id = cx.cid
      ${whereSql}`
  ).bind(...args).all()).results || [];
  if (rows.length) {
    const ids = rows.map(r => r.id);
    const fotos = {};
    for (let i = 0; i < ids.length; i += 90) {
      const sl = ids.slice(i, i + 90);
      const fs = (await env.DB.prepare(`SELECT id, pedido_id, r2_key, created_at FROM pedido_prod_fotos WHERE pedido_id IN (${sl.map(() => '?').join(',')}) ORDER BY id`).bind(...sl).all()).results || [];
      for (const f of fs) (fotos[f.pedido_id] = fotos[f.pedido_id] || []).push({ id: f.id, key: f.r2_key, at: f.created_at });
    }
    for (const r of rows) { r.fotos = fotos[r.id] || []; r.fotos_requeridas = prodFotosRequeridas(r); if (r.mo_detalle && typeof r.mo_detalle === 'string') { try { r.mo_detalle = JSON.parse(r.mo_detalle); } catch (_) {} } }
  }
  return rows;
}
// Productores = usuarios rol 'productor' + "extras" de otro rol que también arman carteles (kv 'prod_extra' =
// [{id, nombre}], ej. Aníbal, que ya tiene su usuario de corte). Un productor sin contraseña todavía (activo=0, sin
// hash) se puede ASIGNAR pero no puede entrar; dado de baja = activo=0 con contraseña puesta (baja=1, no se asigna).
async function prodExtras(env) {
  try { const v = JSON.parse((await kvGet(env, 'prod_extra', null)) || '[]'); return Array.isArray(v) ? v.filter(x => x && x.id).map(x => ({ id: prodSlug(x.id), nombre: String(x.nombre || x.id) })) : []; } catch (_) { return []; }
}
// prodCarteles para una lista de ids, en tandas de ≤90 (D1 acepta ~100 parámetros por consulta).
async function prodCartelesPorIds(env, ids, paraProductor) {
  const out = [];
  for (let i = 0; i < ids.length; i += 90) { const l = ids.slice(i, i + 90); out.push(...(await prodCarteles(env, `WHERE p.id IN (${l.map(() => '?').join(',')})`, l, !!paraProductor))); }
  return out;
}
async function prodProductores(env) {
  const rs = await env.DB.prepare("SELECT id, nombre, activo, CASE WHEN COALESCE(password_hash,'') <> '' THEN 1 ELSE 0 END AS tiene_pw FROM users_panel WHERE rol = 'productor' ORDER BY nombre").all();
  const lista = (rs.results || []).map(p => ({ ...p, baja: (!+p.activo && +p.tiene_pw) ? 1 : 0, extra: 0 }));
  for (const x of await prodExtras(env)) {
    if (lista.some(p => p.id === x.id)) continue;
    const u = await env.DB.prepare("SELECT activo, CASE WHEN COALESCE(password_hash,'') <> '' THEN 1 ELSE 0 END AS tiene_pw FROM users_panel WHERE id = ?").bind(x.id).first();
    if (u && +u.activo) lista.push({ id: x.id, nombre: x.nombre, activo: 1, tiene_pw: +u.tiene_pw, baja: 0, extra: 1 });
  }
  return lista.sort((a, b) => String(a.nombre).localeCompare(String(b.nombre)));
}
// Productor "extra" (otro rol) de esta sesión: usa los endpoints de producción para SUS carteles, sin el muro del rol productor.
async function prodExtraDeSesion(env, userName) {
  const slug = prodSlug(userName);
  const x = (await prodExtras(env)).find(e => e.id === slug);
  if (!x) return null;
  const u = await env.DB.prepare('SELECT activo FROM users_panel WHERE id = ?').bind(slug).first().catch(() => null);
  return (u && +u.activo) ? { id: x.id, nombre: x.nombre, activo: true, extra: true } : null;
}
// Cierra las sesiones abiertas de un usuario (al darlo de baja o cambiarle la contraseña).
async function cerrarSesionesDe(env, userId) {
  const ses = (await env.DB.prepare('SELECT token, user FROM sessions WHERE expires_at > ?').bind(new Date().toISOString()).all()).results || [];
  const del = ses.filter(s => prodSlug(s.user) === userId).map(s => s.token);
  if (del.length) await env.DB.batch(del.map(t => env.DB.prepare('DELETE FROM sessions WHERE token = ?').bind(t)));
  _prodSesCache.delete(userId);
  return del.length;
}

// ── Mano de obra y productor → 2026 v4 › Pedidos_Directo (columnas "MO" y "PRODUCTOR") ──
// Solo los pedidos de neón desde mo_desde ("en los nuevos pedidos que se vayan anotando de acá en adelante"). El Apps
// Script (acción directo_mo) ubica las columnas por su título en la fila 2 y escribe SOLO si la celda está vacía, tiene
// una fórmula (la del 12% arrastrada) o todavía tiene lo que había puesto el CRM: nunca pisa lo cargado a mano.
// kv 'pedido_mo:<id>' = JSON {mo, prod} del último valor aplicado ({err, at} si no se ubicó la fila: se reintenta en 1 h).
async function directoMoDisponible(env) {
  if (!env.APPS_SCRIPT_URL) return false;
  const now = Date.now();
  let st = null; try { st = JSON.parse((await kvGet(env, 'directo_mo_ping', null)) || 'null'); } catch (_) {}
  if (st && now - (Number(st.at) || 0) < (st.ok ? 6 * 3600e3 : 15 * 60e3)) return !!st.ok;
  let ok = false;
  try {
    const u = env.APPS_SCRIPT_URL + (env.APPS_SCRIPT_URL.indexOf('?') >= 0 ? '&' : '?') + 'action=directo_ping';
    const r = await fetch(u, { redirect: 'follow', signal: AbortSignal.timeout(20000) });
    const j = await r.json().catch(() => null);
    ok = !!(j && j.ok && j.directo === true && j.mo === true);
  } catch (_) {}
  await kvSet(env, 'directo_mo_ping', JSON.stringify({ ok, at: now }));
  return ok;
}
async function barrerMoDirecto(env) {
  if (!env.APPS_SCRIPT_URL) return { skipped: 'no url' };
  try {
    await ensureProdSchema(env);
    const P = (await moConfig(env)) || { desde: MO_DESDE_DEFAULT };
    // Los de antes de mo_desde (desde kv 'mo_excel_desde', hoy el 1-oct) también van, pero SOLO los que tienen productor
    // (Gaspar 16-oct: "si tienen productor asignado… solo en algunos pusiste pago de mano de obra"). Su MO es la de su regla
    // (el % del mes); lo que no produce nadie (ej. una instalación de tira LED) no se escribe.
    const exDesde = String((await kvGet(env, 'mo_excel_desde', null)) || '').trim();
    const desdeQ = (/^\d{4}-\d{2}-\d{2}$/.test(exDesde) && exDesde < P.desde) ? exDesde : P.desde;
    // Nombre del productor desde su id (no desde pedidos.productor, que es texto libre heredado).
    const nombres = {}; for (const p of await prodProductores(env)) nombres[p.id] = p.nombre;
    const rs = await env.DB.prepare(
      "SELECT p.id, p.numero, p.cartel, p.fecha, p.sheet_row, p.alto, p.ancho, p.cantidad, p.mo_monto, p.productor_id, k.v AS kv FROM pedidos p " +
      "LEFT JOIN kv_cache k ON k.k = 'pedido_mo:' || p.id " +
      "WHERE p.es_corporeo = 0 AND p.fecha >= ? AND p.sheet_row > 1 AND p.mirror_dirty = 0 ORDER BY p.id DESC LIMIT 600"
    ).bind(desdeQ).all();
    // kv por pedido: {mo, prod} = lo que el CRM DEJÓ en la planilla (sirve de 'prev' para no tomarlo como manual);
    // {env_mo, env_prod} = lo último enviado (detecta cambios); at = última verificación; err = no se ubicó la fila.
    const ahora = Date.now(), items = [], kvs = {};
    for (const p of (rs.results || [])) {
      const mo = p.mo_monto != null ? Math.round(+p.mo_monto) : '';
      const prod = p.productor_id ? String(nombres[p.productor_id] || '') : '';
      let k = null; try { k = p.kv ? JSON.parse(p.kv) : null; } catch (_) {}
      if (String(p.fecha || '') < P.desde && !prod && !k) continue;   // de antes de mo_desde: solo con productor (o si el CRM ya escribió)
      if (mo === '' && !prod && (!k || (String(k.mo ?? '') === '' && !k.prod))) continue;   // nada que escribir ni nada del CRM en la planilla
      const cambio = !k || String(k.env_mo ?? k.mo ?? '') !== String(mo) || String(k.env_prod ?? k.prod ?? '') !== prod;
      const vence = k && (ahora - (Number(k.at) || 0)) > (k.err ? 3600e3 : 24 * 3600e3);   // reverifica 1×/día (fórmulas arrastradas encima)
      if (!cambio && !vence) continue;
      kvs[p.id] = k || {};
      items.push({ id: p.id, row: p.sheet_row, numero: p.numero, cartel: p.cartel, alto: p.alto, ancho: p.ancho, cantidad: p.cantidad,
        mo, prev_mo: k && k.mo != null ? k.mo : '', productor: prod, prev_prod: k && k.prod ? k.prod : '' });
      if (items.length >= 60) break;
    }
    if (!items.length) return { sent: 0 };
    if (!(await directoMoDisponible(env))) return { skipped: 'el Apps Script todavía no tiene directo_mo', pendientes: items.length };
    const j = await appsScriptPost(env, { action: 'directo_mo', items });
    if (!(j && j.ok && Array.isArray(j.items))) {
      if (j && j.ok) await kvSet(env, 'directo_mo_ping', JSON.stringify({ ok: false, at: Date.now() }));
      return { error: (j && j.error) || 'respuesta inesperada del Apps Script' };
    }
    const porId = {}; for (const r of j.items) porId[r.id] = r;
    const res = { sent: items.length, escritos: 0, iguales: 0, manuales: [], errores: [] };
    // Lo que queda en la planilla de cada campo según lo que contestó el Apps Script.
    const queda = (estado, enviado, antes) => (estado === 'escrito' || estado === 'igual') ? enviado : (estado === 'borrado' || estado === '-') ? '' : antes;
    for (const x of items) {
      const r = porId[x.id], k = kvs[x.id] || {};
      if (r && r.ok) {
        await kvSet(env, 'pedido_mo:' + x.id, JSON.stringify({ mo: queda(r.mo, x.mo, k.mo ?? ''), prod: queda(r.prod, x.productor, k.prod || ''), env_mo: x.mo, env_prod: x.productor, at: Date.now() }));
        if (['escrito', 'borrado'].includes(r.mo) || ['escrito', 'borrado'].includes(r.prod)) res.escritos++; else res.iguales++;
        if (r.mo === 'manual' || r.prod === 'manual') res.manuales.push({ id: x.id, cartel: x.cartel, mo: r.mo === 'manual' ? r.mo_planilla : undefined, prod: r.prod === 'manual' ? r.prod_planilla : undefined });
      } else {
        // No se ubicó la fila: se conserva lo último que el CRM dejó (para no tomarlo como manual al reintentar en 1 h).
        await kvSet(env, 'pedido_mo:' + x.id, JSON.stringify({ mo: k.mo ?? '', prod: k.prod || '', env_mo: k.env_mo ?? '', env_prod: k.env_prod ?? '', err: (r && r.error) || 'sin respuesta', at: Date.now() }));
        res.errores.push({ id: x.id, cartel: x.cartel, error: (r && r.error) || 'sin respuesta' });
      }
    }
    return res;
  } catch (e) { return { error: String((e && e.message) || e) }; }
}

const handler = {
  async fetch(request, env, ctx) {
    // Envoltorio anti-crash: cualquier excepción NO atrapada del handler (típico
    // "D1_ERROR: D1 DB is overloaded") DEBE devolver una respuesta CON CORS. Sin
    // esto Cloudflare responde un 1101 crudo sin CORS -> el navegador lo ve como
    // "Failed to fetch" (rompía el login y disparaba la cascada de reintentos que
    // saturaba más a D1). Referenciamos handler._fetch explícito (no `this`) para
    // no depender de cómo el runtime bindea el método.
    // Vigía de logística: los pedidos de /admin/logistica/* se registran al terminar (tiempo, errores; logiVigiaFin).
    const lv = logiVigiaInicio(request);
    try {
      const res = await handler._fetch(request, env, ctx);
      if (lv) logiVigiaFin(lv, request, res, null, env, ctx);
      return res;
    } catch (e) {
      const res = fetchErrorResponse(e);
      if (lv) logiVigiaFin(lv, request, res, e, env, ctx);
      return res;
    }
  },
  async _fetch(request, env, ctx) {
    if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: cors() });
    const url = new URL(request.url);
    const path = url.pathname;

    // ----- Health -----
    if (request.method === 'GET' && path === '/health') return json({ ok: true });

    // ===== Meta Lead Ads Webhook (separado del de WhatsApp) =====
    // Se suscribe en la Meta App "agente neon nuevo" (866678322681866) al campo
    // `leadgen` de la Page que recibe los leads (100517509701851).
    // Secretos requeridos:
    //   LEADGEN_VERIFY_TOKEN     — string random; Meta lo verifica al suscribir
    //   META_PAGE_ACCESS_TOKEN   — token de la Page con permiso leads_retrieval
    if (request.method === 'GET' && path === '/webhook/leads') {
      const mode = url.searchParams.get('hub.mode');
      const token = url.searchParams.get('hub.verify_token');
      const challenge = url.searchParams.get('hub.challenge');
      if (mode === 'subscribe' && token === env.LEADGEN_VERIFY_TOKEN && challenge) {
        return new Response(challenge, { status: 200, headers: { 'Content-Type': 'text/plain' } });
      }
      return new Response('Forbidden', { status: 403 });
    }
    if (request.method === 'POST' && path === '/webhook/leads') {
      let body;
      try { body = await request.json(); } catch { return json({ ok: true }); }
      // Log raw payload para debug temporal (luego se puede sacar).
      try {
        await env.DB.prepare('INSERT INTO wa_webhook_log (ts, payload) VALUES (?, ?)').bind(
          new Date().toISOString(), 'LEADS: ' + JSON.stringify(body).slice(0, 4000)
        ).run();
      } catch (_) {}
      // Responder 200 inmediato a Meta. El procesamiento (fetch detalle + enviar
      // template) va en waitUntil para no bloquear la respuesta del webhook.
      ctx.waitUntil(processLeadgenWebhook(env, body));
      return json({ ok: true });
    }

    // ===== Instagram DM Webhook (inbox de IG → CRM) — FASE 1: SOLO RECIBIR =====
    // App de Meta "agente neon nuevo" (866678322681866), producto Instagram con
    // Instagram Business Login, suscripto al campo `messages`. SEPARADO del de
    // WhatsApp (/webhook) y del de leadgen (/webhook/leads) para NO tocar lo que ya
    // anda. Por ahora SOLO loguea el payload (confirmar que los DM llegan). No guarda
    // en el chat ni responde NADA — eso se suma después, gateado. No puede romper nada.
    // Secreto requerido: IG_VERIFY_TOKEN (string random; Meta lo verifica al suscribir).
    if (request.method === 'GET' && path === '/webhook/ig') {
      const mode = url.searchParams.get('hub.mode');
      const token = url.searchParams.get('hub.verify_token');
      const challenge = url.searchParams.get('hub.challenge');
      if (mode === 'subscribe' && env.IG_VERIFY_TOKEN && token === env.IG_VERIFY_TOKEN && challenge) {
        return new Response(challenge, { status: 200, headers: { 'Content-Type': 'text/plain' } });
      }
      return new Response('Forbidden', { status: 403 });
    }
    if (request.method === 'POST' && path === '/webhook/ig') {
      let body;
      try { body = await request.json(); } catch { return json({ ok: true }); }
      try {
        await env.DB.prepare('INSERT INTO wa_webhook_log (ts, payload) VALUES (?, ?)').bind(
          new Date().toISOString(), 'IG: ' + JSON.stringify(body).slice(0, 4000)
        ).run();
      } catch (_) {}
      // Fase 2a: si el flag 'ig_inbox_on' está prendido, parsear + clasificar + guardar
      // (read-only, sin responder nada). Si está apagado, solo queda el log de arriba.
      if (await igInboxOn(env)) ctx.waitUntil(processIgWebhook(env, body));
      return json({ ok: true });
    }

    // ===== Bridge desde Google Sheets (Apps Script onChange) =====
    // Workaround mientras App Review aprueba leads_retrieval. Meta sincroniza
    // leads a la sheet nativamente, y un Apps Script en la sheet nos manda
    // cada fila nueva acá. Auth via header X-Sheet-Secret.
    if (request.method === 'POST' && path === '/webhook/sheet-lead') {
      const incoming = request.headers.get('x-sheet-secret') || '';
      if (!env.SHEET_BRIDGE_SECRET || incoming !== env.SHEET_BRIDGE_SECRET) {
        return json({ error: 'forbidden' }, 403);
      }
      let body;
      try { body = await request.json(); } catch { return json({ ok: true }); }
      try {
        await env.DB.prepare('INSERT INTO wa_webhook_log (ts, payload) VALUES (?, ?)').bind(
          new Date().toISOString(), 'SHEET_LEAD: ' + JSON.stringify(body).slice(0, 4000)
        ).run();
      } catch (_) {}
      ctx.waitUntil(processSheetLead(env, body));
      return json({ ok: true });
    }

    // ===== Registro de la landing del minicurso gratuito =====
    // La landing manda cada registro (nombre + teléfono) acá, en paralelo a la
    // acción que ya escribe en el Google Sheet. Auth via header X-Sheet-Secret
    // (acepta el secret del bridge de leads o uno dedicado). El opener lo dispara
    // el cron a los 45 min (con guardia + horario), no acá.
    if (request.method === 'POST' && path === '/webhook/minicurso-lead') {
      const incoming = request.headers.get('x-sheet-secret') || '';
      const okSecret = (env.SHEET_BRIDGE_SECRET && incoming === env.SHEET_BRIDGE_SECRET) || (env.MINICURSO_WEBHOOK_SECRET && incoming === env.MINICURSO_WEBHOOK_SECRET);
      if (!okSecret) return json({ error: 'forbidden' }, 403);
      let body;
      try { body = await request.json(); } catch { return json({ ok: true }); }
      try { await env.DB.prepare('INSERT INTO wa_webhook_log (ts, payload) VALUES (?, ?)').bind(new Date().toISOString(), 'MINICURSO_LEAD: ' + JSON.stringify(body).slice(0, 2000)).run(); } catch (_) {}
      ctx.waitUntil(processMinicursoLead(env, body));
      return json({ ok: true });
    }

    // ===== Registro de leads de la landing del LANZAMIENTO (Fase Semilla) =====
    // MISMO formato que el minicurso ({firstName, phone} + header X-Sheet-Secret), pero
    // URL y flujo SEPARADOS. Los leads entran a lanzamiento_landing; el opener NO se manda
    // hasta que se configure la plantilla + se prenda el freno (ver processLanzamientoLanding).
    if (request.method === 'POST' && path === '/webhook/lanzamiento-lead') {
      const incoming = request.headers.get('x-sheet-secret') || '';
      const okSecret = (env.SHEET_BRIDGE_SECRET && incoming === env.SHEET_BRIDGE_SECRET) || (env.MINICURSO_WEBHOOK_SECRET && incoming === env.MINICURSO_WEBHOOK_SECRET);
      if (!okSecret) return json({ error: 'forbidden' }, 403);
      let body;
      try { body = await request.json(); } catch { return json({ ok: true }); }
      try { await env.DB.prepare('INSERT INTO wa_webhook_log (ts, payload) VALUES (?, ?)').bind(new Date().toISOString(), 'LANZAMIENTO_LEAD: ' + JSON.stringify(body).slice(0, 2000)).run(); } catch (_) {}
      ctx.waitUntil(processLanzamientoLead(env, body));
      return json({ ok: true });
    }

    // ===== Registro de leads del formulario B2B de REVENTA =====
    // Un App Script en el Sheet de reventa reenvía cada fila nueva acá (mismo
    // header de auth que el minicurso). El worker filtra cualificados y actúa.
    if (request.method === 'POST' && path === '/webhook/reventa-lead') {
      const incoming = request.headers.get('x-sheet-secret') || '';
      const okSecret = (env.SHEET_BRIDGE_SECRET && incoming === env.SHEET_BRIDGE_SECRET) || (env.MINICURSO_WEBHOOK_SECRET && incoming === env.MINICURSO_WEBHOOK_SECRET);
      if (!okSecret) return json({ error: 'forbidden' }, 403);
      let body;
      try { body = await request.json(); } catch { return json({ ok: true }); }
      try { await env.DB.prepare('INSERT INTO wa_webhook_log (ts, payload) VALUES (?, ?)').bind(new Date().toISOString(), 'REVENTA_LEAD: ' + JSON.stringify(body).slice(0, 2000)).run(); } catch (_) {}
      ctx.waitUntil(processReventaLead(env, body));
      return json({ ok: true });
    }

    // ----- WhatsApp Webhook (verificación + recepción de mensajes) -----
    if (request.method === 'GET' && path === '/webhook') {
      // Verificación del webhook: Meta envía hub.mode, hub.verify_token, hub.challenge
      const mode = url.searchParams.get('hub.mode');
      const token = url.searchParams.get('hub.verify_token');
      const challenge = url.searchParams.get('hub.challenge');
      if (mode === 'subscribe' && (token === WA_VERIFY_TOKEN || token === env.WA_VERIFY_TOKEN) && challenge) {
        return new Response(challenge, { status: 200, headers: { 'Content-Type': 'text/plain' } });
      }
      // For override_callback_uri verification, Meta may send without our token
      if (mode === 'subscribe' && challenge) {
        return new Response(challenge, { status: 200, headers: { 'Content-Type': 'text/plain' } });
      }
      return new Response('Forbidden', { status: 403 });
    }

    if (request.method === 'POST' && path === '/webhook') {
      // Meta envía notificaciones de mensajes entrantes y status updates
      let body;
      try { body = await request.json(); } catch { return json({ ok: true }); }
      // Log raw payload for debugging (temporary)
      try {
        await env.DB.prepare('INSERT INTO wa_webhook_log (ts, payload) VALUES (?, ?)').bind(new Date().toISOString(), JSON.stringify(body).slice(0, 4000)).run();
      } catch (_) {}
      // Siempre responder 200 rápido para que Meta no reintente
      const processWebhook = async () => {
        try {
          // Coexistence — formato no-Meta: { id, event, data } directo en la raíz.
          // 360dialog envía 'event: history' (mensajes históricos del onboarding)
          // y 'event: smb_app_state_sync' (contactos sincronizados) en este formato
          // a la partner-configured webhook URL.
          if (body?.event === 'history' && body?.data) {
            await processCoexistenceHistory(env, body.data);
            return;
          }
          if (body?.event === 'smb_app_state_sync' && body?.data) {
            await processCoexistenceStateSync(env, body.data);
            return;
          }

          const entries = body?.entry || [];
          for (const entry of entries) {
            const changes = entry?.changes || [];
            for (const change of changes) {
              // Field 'message_template_status_update' = cambio de status de una
              // plantilla (APPROVED/REJECTED/PAUSED/DISABLED). Notificamos al admin
              // y dejamos de pollear monitorTemplateStatus.
              // 'template_category_update' = Meta recategorizó una plantilla (p. ej. UTILITY → MARKETING): se guarda
              // la categoría (los avisos internos solo usan UTILITY) sin avisarle al admin por cada una.
              if (change?.field === 'message_template_status_update' || change?.field === 'template_category_update') {
                await processTemplateStatusUpdate(env, change.value || {});
                continue;
              }
              // Aceptamos: 'messages' (Meta estándar), 'smb_message_echoes'
              // (coexistence echoes), y 'history' (algunos history events vienen
              // en formato Meta-style con value.message_echoes adentro, además del
              // formato plano {event,data} que se maneja arriba).
              const allowedFields = new Set(['messages', 'smb_message_echoes', 'history']);
              if (!allowedFields.has(change?.field)) continue;
              const value = change?.value || {};
              const contacts = value?.contacts || [];
              const contactMap = {};
              for (const c of contacts) contactMap[c.wa_id] = c.profile?.name || '';
              // Coexistencia / Echoes: detectar mensajes SALIENTES (Joaco escribió
              // desde la app de WhatsApp Business) con MÚLTIPLES heurísticas porque
              // 360dialog puede no traer value.metadata.display_phone_number igual
              // que Meta direct.
              // 1) display_phone_number del metadata (Meta direct, ideal)
              // 2) env.WA_BUSINESS_PHONE (fallback hardcoded por wrangler secret)
              // 3) presencia de msg.to (Y from distinto del cliente) — heurística:
              //    los mensajes inbound del cliente NO traen msg.to, los echoes sí.
              const businessPhoneFromMeta = String(value?.metadata?.display_phone_number || '').replace(/\D/g, '');
              const businessPhoneFromEnv  = String(env.WA_BUSINESS_PHONE || '').replace(/\D/g, '');
              const businessPhones = new Set([businessPhoneFromMeta, businessPhoneFromEnv].filter(Boolean));

              // Log de diagnóstico: guardamos el primer message del primer batch
              // para inspeccionar el formato real de 360dialog. Truncado a 4KB.
              try {
                if (Array.isArray(value?.messages) && value.messages.length) {
                  const dbg = {
                    metadata: value.metadata,
                    sample_message_keys: Object.keys(value.messages[0]),
                    sample_message: value.messages[0],
                    business_phones_known: Array.from(businessPhones)
                  };
                  const dbgStr = JSON.stringify(dbg).slice(0, 4000);
                  await env.DB.prepare('INSERT INTO wa_webhook_log (ts, payload) VALUES (?, ?)').bind(new Date().toISOString(), 'WEBHOOK_DEBUG: ' + dbgStr).run();
                }
              } catch(_) {}

              // Mensajes (entrantes y salientes vía echoes)
              for (const msg of (value?.messages || [])) {
                const fromNorm = String(msg.from || '').replace(/\D/g, '');
                const toNorm   = String(msg.to   || '').replace(/\D/g, '');
                // Echo si: from coincide con un número de business conocido, O si
                // tiene msg.to definido (los mensajes entrantes del cliente NO lo traen).
                const isOutboundEcho =
                  (businessPhones.size > 0 && businessPhones.has(fromNorm)) ||
                  (!!toNorm && fromNorm !== toNorm);
                // En echoes el destinatario viene en msg.to o en contacts[0]?.wa_id
                const recipient = toNorm || String(contacts[0]?.wa_id || '').replace(/\D/g, '');
                const phone = isOutboundEcho ? recipient : (msg.from || '');
                const direction = isOutboundEcho ? 'outbound' : 'inbound';
                const wamid = msg.id || '';
                const senderName = isOutboundEcho ? '' : (contactMap[phone] || '');
                const msgType = msg.type || 'unknown';
                let msgBody = '';
                let mediaUrl = '';
                if (msg.text) msgBody = msg.text.body || '';
                else if (msg.button) msgBody = msg.button.text || msg.button.payload || '';
                else if (msg.interactive) msgBody = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';
                else if (msg.image) { msgBody = msg.image.caption || ''; mediaUrl = msg.image.id || ''; }
                else if (msg.video) { msgBody = msg.video.caption || ''; mediaUrl = msg.video.id || ''; }
                else if (msg.audio) { mediaUrl = msg.audio.id || ''; }
                else if (msg.document) { msgBody = msg.document.filename || ''; mediaUrl = msg.document.id || ''; }
                else if (msg.sticker) { mediaUrl = msg.sticker.id || ''; }
                else if (msg.reaction) { msgBody = msg.reaction.emoji || ''; }
                else if (msg.location) { msgBody = `[ubicacion] ${msg.location.latitude},${msg.location.longitude}${msg.location.name ? ' — ' + msg.location.name : ''}${msg.location.address ? ' (' + msg.location.address + ')' : ''}`; }
                else if (msg.contacts && msg.contacts.length) {
                  const cNames = msg.contacts.map(c => c.name?.formatted_name || c.name?.first_name || 'contacto').join(', ');
                  const cPhones = msg.contacts.map(c => c.phones?.[0]?.phone || '').filter(Boolean).join(', ');
                  msgBody = `[contacto] ${cNames}${cPhones ? ' — ' + cPhones : ''}`;
                }
                else if (msg.order) { msgBody = `[pedido] ${(msg.order.product_items || []).map(p => p.product_retailer_id).join(', ')}`; }
                else if (msg.unsupported) {
                  // Meta sends error details for unsupported messages.
                  // El código 131051 ("Message type unknown") corresponde casi siempre
                  // a un mensaje EDITADO por el cliente — Meta no expone la edición
                  // por Cloud API, solo te notifica que algo cambió.
                  const errTitle = msg.errors?.[0]?.title || '';
                  const errCode  = msg.errors?.[0]?.code;
                  const errDetails = msg.errors?.[0]?.details || msg.errors?.[0]?.message || '';
                  let classified;
                  if (errCode === 131051 || errTitle === 'Message type unknown') {
                    msgBody = '✏️ El cliente editó un mensaje (Meta no comparte el contenido editado)';
                    classified = 'edited';
                  } else if (errTitle.includes('unavailable')) {
                    msgBody = '[mensaje no disponible]';
                    classified = 'unavailable';
                  } else {
                    msgBody = `[no soportado: ${errTitle || 'desconocido'}]`;
                    classified = 'other';
                  }
                  // Guardamos el payload crudo del mensaje para diagnosticar por qué
                  // Meta no comparte el contenido. La tabla tiene índice por ts/phone.
                  // No bloqueamos el flujo principal si esto falla.
                  try {
                    const rawPayload = JSON.stringify(msg).slice(0, 8000);
                    await env.DB.prepare(
                      'INSERT INTO wa_webhook_debug (ts, inserted_at, wamid, phone, sender_name, error_code, error_title, error_details, msg_type, classified_as, raw_payload) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
                    ).bind(
                      msg.timestamp ? new Date(parseInt(msg.timestamp) * 1000).toISOString() : new Date().toISOString(),
                      new Date().toISOString(),
                      msg.id || '',
                      phone || '',
                      senderName || '',
                      errCode || null,
                      errTitle,
                      typeof errDetails === 'string' ? errDetails : JSON.stringify(errDetails),
                      msg.type || 'unsupported',
                      classified,
                      rawPayload
                    ).run();
                  } catch (_) { /* ignore */ }
                }
                const contextId = msg.context?.id || msg.reaction?.message_id || '';
                const ts = msg.timestamp ? new Date(parseInt(msg.timestamp) * 1000).toISOString() : new Date().toISOString();
                // Download media to R2 if present (con reintentos: el webhook
                // suele llegar antes de que el media esté listo en Meta).
                let r2Key = '';
                if (mediaUrl && env.MEDIA) {
                  try {
                    const dl = await downloadMediaWithRetry(env, mediaUrl);
                    if (dl) r2Key = dl.key;
                  } catch (_) {}
                }
                // Transcribe audio messages
                if (msgType === 'audio' && r2Key && env.AI) {
                  try {
                    const transcript = await transcribeAudio(env, r2Key);
                    if (transcript) msgBody = '[audio] ' + transcript;
                  } catch (_) {}
                }
                // Analyze image messages
                if (msgType === 'image' && r2Key && env.AI) {
                  try {
                    const description = await analyzeImage(env, r2Key);
                    if (description) msgBody = (msgBody ? msgBody + ' | ' : '') + '[imagen] ' + description;
                  } catch (imgErr) {
                    try { await env.DB.prepare('INSERT INTO wa_webhook_log (ts, payload) VALUES (?, ?)').bind(new Date().toISOString(), 'IMG_ERR: ' + (imgErr?.message || String(imgErr))).run(); } catch(_){}
                  }
                }
                try {
                  // Upsert: si ya existe (p.ej. placeholder de status webhook con body vacío),
                  // completamos body/tipo/media. No pisamos status si ya viene 'sent/delivered/read'.
                  await env.DB.prepare(
                    `INSERT INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status)
                     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                     ON CONFLICT(wamid) DO UPDATE SET
                       direction = excluded.direction,
                       phone = excluded.phone,
                       msg_type = excluded.msg_type,
                       body = excluded.body,
                       media_url = excluded.media_url,
                       context_id = excluded.context_id,
                       ts = excluded.ts
                     WHERE wa_messages.body IS NULL OR wa_messages.body = '' OR wa_messages.msg_type = 'status'`
                  ).bind(ts, wamid, direction, phone, senderName, msgType, msgBody, r2Key || mediaUrl, contextId, null).run();
                } catch (_) {}

                // ===== Auto-recovery de unreachable =====
                // Si este contacto estaba marcado como unreachable y ahora nos
                // escribe, significa que NO está muerto. Lo desmarcamos para que
                // los flows automáticos vuelvan a considerarlo.
                if (direction === 'inbound' && phone) {
                  // Guía de Producción: ocultar YA, antes de cualquier otro hook, para cerrar la
                  // ventana de carrera que exponía el chat como 'general' en la libreta durante el
                  // flood del evento (ensuciaba la bandeja del admin ~5s por lote por el cache).
                  try { await guiaProduccionHideFast(env, phone, msgBody); } catch (_) {}
                  try { await removeUnreachable(env, phone); } catch (_) {}
                }
                // ===== Auto-respuesta del minicurso (regalos) =====
                // Solo inbound de texto reciente (últimos 10 min) que pida la
                // guía + cotizador. Mensaje libre (ventana 24h). Una vez por
                // contacto y deriva el chat a la bandeja de cursos (Abril).
                if (direction === 'inbound' && matchMinicursoTrigger(msgBody)) {
                  const reciente = (Date.now() - new Date(ts).getTime()) < 10 * 60 * 1000;
                  if (reciente) {
                    try { await maybeAutoReplyMinicurso(env, phone, senderName); } catch (_) {}
                  }
                }
                // ===== Campaña de cursos: si este inbound responde a un broadcast
                // oculto, IA evalúa, manda el evento si es positiva, y revela el
                // chat a Abril. (No hace nada si el chat no es de la campaña.) =====
                if (direction === 'inbound') {
                  try { await revealCursosCampaign(env, phone, msgBody); } catch (_) {}
                }
                // Broadcast custom con respuesta-IA activada: marcar para branch X/Y (Fase 2.5).
                // Las REACCIONES (emoji) NO cuentan como respuesta: no ramifican (si no, un like
                // podía disparar la rama positiva y mandar el checkout a alguien que solo reaccionó).
                if (direction === 'inbound') {
                  try { if (msgType !== 'reaction') await maybeBranchBroadcastReply(env, phone); } catch (_) {}
                }
                // ===== wa.me "Neón Mastery": ruteo directo a bandeja de cursos =====
                // Gente que entra por el link de wa.me del grupo de precalentamiento
                // del prelanzamiento manda el texto prearmado "Hola quiero acceder a
                // Neón Mastery". Los pasamos SOLO a la bandeja de Abril (cursos), sin
                // responder nada (pedido explícito): el equipo los atiende a mano.
                if (direction === 'inbound' && _normTxt(msgBody).includes('acceder a neon mastery')) {
                  try {
                    await env.DB.prepare(
                      "INSERT INTO wa_chats_summary (phone, inbox, updated_at) VALUES (?, 'cursos', ?) ON CONFLICT(phone) DO UPDATE SET inbox = 'cursos'"
                    ).bind(phone, ts).run();
                  } catch (_) {}
                }
                // ===== Minicurso: si este inbound responde al gate de feedback,
                // la IA evalúa y le manda el link de regalos si es positiva. =====
                if (direction === 'inbound') {
                  try { await maybeSendMinicursoGift(env, phone, msgBody, ts); } catch (_) {}
                }
                // ===== Cliente vigilado por Gaspar (botón 🔔): cada mensaje le llega a su personal =====
                // Las reacciones (👍) no cuentan como respuesta. En segundo plano para no frenar el webhook.
                if (direction === 'inbound' && msgType !== 'status' && msgType !== 'reaction') {
                  const _cv = avisarClienteVigilado(env, { wamid, phone, senderName, msgType, body: msgBody, r2Key, ts });
                  if (typeof ctx !== 'undefined' && ctx && ctx.waitUntil) ctx.waitUntil(_cv); else await _cv;
                }
                // ===== Avisos internos (Etapa 1): alguien del equipo le escribió al número del negocio =====
                // Su ventana de 24 h se acaba de abrir → se le manda en un texto lo que no le llegó (cola nocturna, tope,
                // perdidos, fallidos). En segundo plano; no hace nada salvo aviso_interno_modo='on' (adentro).
                if (direction === 'inbound' && msgType !== 'status' && msgType !== 'reaction') {
                  try {
                    if (await esTelefonoInterno(env, phone)) {
                      const _fl = avisoInternoFlush(env, phone);
                      if (typeof ctx !== 'undefined' && ctx && ctx.waitUntil) ctx.waitUntil(_fl); else await _fl;
                    }
                  } catch (_) {}
                }
                // ===== Lanzamiento junio: capturar comprobantes de pago =====
                // En la ventana (11-15/06), todo inbound con imagen/PDF se OCRea,
                // se clasifica, se etiqueta y se respalda en D1 (NO se responde nada).
                if (direction === 'inbound' && (msgType === 'image' || msgType === 'document') && r2Key && isPagoLanzamientoWindow(ts)) {
                  // 1) OCR + clasificación + backup en D1. 2) reenvío a Gaspar
                  // (solo hoy/mañana). El reenvío corre SIEMPRE tras el intento de
                  // OCR (aunque el OCR falle) para no perder ningún comprobante; el
                  // caption incluye monto/cuenta si el OCR alcanzó a leerlos.
                  const _pp = (async () => {
                    try { await processPaymentProof(env, { wamid, phone, senderName, r2Key, msgType, caption: msgBody, ts }); } catch (_) {}
                    if (isResendGasparWindow(ts)) { try { await forwardProofToGaspar(env, { wamid, phone, senderName, r2Key, msgType, ts }); } catch (_) {} }
                  })();
                  if (typeof ctx !== 'undefined' && ctx && ctx.waitUntil) ctx.waitUntil(_pp); else await _pp;
                }

                // ===== Ad Attribution (referral) =====
                // Cuando un cliente clickea un ad de Meta (Click-to-WhatsApp) y manda
                // mensaje, Meta inyecta un objeto `referral` con info del ad de origen.
                // Lo guardamos en wa_ad_attributions para trazabilidad y dashboard.
                const ref = msg.referral;
                if (ref && ref.source_id) {
                  try {
                    await env.DB.prepare(`CREATE TABLE IF NOT EXISTS wa_ad_attributions (
                      id INTEGER PRIMARY KEY AUTOINCREMENT,
                      phone TEXT NOT NULL,
                      wamid TEXT,
                      ts TEXT NOT NULL,
                      source_id TEXT,
                      source_type TEXT,
                      source_url TEXT,
                      headline TEXT,
                      body TEXT,
                      media_type TEXT,
                      image_url TEXT,
                      video_url TEXT,
                      thumbnail_url TEXT,
                      ctwa_clid TEXT,
                      ad_name TEXT,
                      ad_set_name TEXT,
                      campaign_name TEXT,
                      created_at TEXT NOT NULL
                    )`).run();
                    await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_wa_ad_attr_phone ON wa_ad_attributions(phone)`).run();
                    await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_wa_ad_attr_source ON wa_ad_attributions(source_id)`).run();
                    const nowIso = new Date().toISOString();
                    // Dedup: 360dialog/Meta reentregan webhooks (at-least-once). Sin este guard el
                    // mismo wamid se insertaba 2-3x e inflaba cualquier conteo por filas (~20%).
                    // Mismo patrón que las otras dos ramas de atribución (IG y Meta-style).
                    const _dupAttr = wamid ? await env.DB.prepare('SELECT 1 FROM wa_ad_attributions WHERE wamid = ?').bind(wamid).first() : null;
                    if (!_dupAttr) {
                    await env.DB.prepare(`INSERT INTO wa_ad_attributions
                      (phone, wamid, ts, source_id, source_type, source_url, headline, body, media_type, image_url, video_url, thumbnail_url, ctwa_clid, created_at)
                      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    `).bind(
                      phone,
                      wamid,
                      ts,
                      String(ref.source_id || ''),
                      String(ref.source_type || ''),
                      String(ref.source_url || ''),
                      String(ref.headline || ''),
                      String(ref.body || ''),
                      String(ref.media_type || ''),
                      String(ref.image_url || ''),
                      String(ref.video_url || ''),
                      String(ref.thumbnail_url || ''),
                      String(ref.ctwa_clid || ''),
                      nowIso
                    ).run();
                    }
                  } catch (e) {
                    try { await env.DB.prepare('INSERT INTO wa_webhook_log (ts, payload) VALUES (?, ?)').bind(new Date().toISOString(), 'AD_ATTR_ERR: ' + (e?.message || String(e))).run(); } catch(_) {}
                  }
                  // Trazabilidad del ad -> bandeja: carteles a Joaquin (general), cursos a Abril.
                  // Solo si el chat no tiene bandeja asignada o esta 'oculto' (no pisa asignaciones manuales).
                  try {
                    const _vert = await adVerticalForSource(env, ref.source_id, String(ref.headline || ''), String(ref.body || ''));
                    // Si es lead de cursos y el flujo automatico esta activo, el flujo
                    // maneja la bandeja (oculto durante el opener). No ruteamos aca.
                    // Tampoco ruteamos si es el trigger de la Guía de Producción: esa automatización
                    // ya ocultó el chat (guiaProduccionHideFast) y este INSERT lo pisaría de vuelta a
                    // 'general'/'cursos' (su WHERE incluye inbox='oculto') → volvería a ensuciar la bandeja.
                    const _esGuiaTrigger = _normTxt(msgBody).includes('quiero guia de produccion');
                    if (!_esGuiaTrigger && !(_vert === 'cursos' && await cursosFlowOn(env))) {
                      await env.DB.prepare("INSERT INTO wa_chats_summary (phone, inbox, updated_at) VALUES (?, ?, ?) ON CONFLICT(phone) DO UPDATE SET inbox = excluded.inbox, updated_at = excluded.updated_at WHERE wa_chats_summary.inbox IS NULL OR wa_chats_summary.inbox = 'oculto'").bind(phone, _vert === 'cursos' ? 'cursos' : 'general', ts).run();
                    }
                    // Corpóreo (ads Corporeas 1/2): etiqueta para atención manual (bot de neón excluido).
                    if (_vert === 'corporeo') await corporeoTag(env, phone, true);
                  } catch (_) {}
                }

                // Auto-labeling: deshabilitado por pedido del usuario (el matching
                // por keywords genera demasiados falsos positivos). El código
                // queda en applyAutoLabels() por si se quiere reactivar.
                // ===== Flujo de cursos por ads (Fase 3): arranque / transiciones =====
                if (direction === 'inbound') {
                  try { await cursosFlowOnInbound(env, phone, msgBody, ts); } catch (_) {}
                  // Landing del minicurso: respuesta al opener -> branch por IA / follow-up.
                  try { await minicursoLandingOnInbound(env, phone, ts); } catch (_) {}
                  // Landing del lanzamiento: walink → link (oculto); respuesta posterior → revelar.
                  // Las REACCIONES (emoji) NO cuentan como respuesta: no des-ocultan el chat
                  // (si no, un like al recordatorio del sorteo llenaba la bandeja de basura).
                  try { if (msgType !== 'reaction') await eventoRecordatorioOnInbound(env, phone); } catch (_) {}
                  // MiniSupernova ANTES que seminario: para el solapamiento alumno∩seminario (el
                  // seminario ya pasó, 29/08), cuando responde gana el reveal a 'cursos' (Abril,
                  // campaña activa) y NO el de seminario a 'privado' (que Abril no ve). El candado
                  // WHERE inbox='oculto' hace que el que corre 2do sea no-op.
                  // Respuesta al aviso del sitio del corte → vuelve a su bandeja o a 'corte' (ANTES que MiniSupernova).
                  try { if (msgType !== 'reaction') await corteWebOnInbound(env, phone); } catch (_) {}
                  try { await miniSupernovaOnInbound(env, phone); } catch (_) {}
                  try { await seminarioOnInbound(env, phone); } catch (_) {}
                  try { await lanzamientoLandingOnInbound(env, phone, msgBody); } catch (_) {}
                  // Reparto de leads de carteles a Facundo APENAS entra el lead (pedido Gaspar 3-sep):
                  // funciona igual que para Joaco, con su cuota/hash. Corre en CADA inbound EN VIVO (antes
                  // solo lo hacía el captador de precotización ~1 min tarde y Joaco los agarraba primero →
                  // Facu se quedaba con casi nada). Idempotente, determinístico, respeta anti-pisón, excluye
                  // cursos(inbox)/reventa/minicurso/cliente/corte. Facu SÍ recibe corpóreos. Va ANTES de la
                  // auto-respuesta de corpóreo para que el saludo ya sepa a quién quedó asignado (Facu/Joaco).
                  try { await maybeRepartirANadia(env, phone); } catch (_) {}
                  // Auto-respuesta a leads de corpóreo (mensaje del ad Corporeas): saluda (Facu/Joaco según
                  // asignación) + pide foto+medidas+int/ext.
                  try { await corporeoAskOnInbound(env, phone, msgBody); } catch (_) {}
                  // Auto-respuesta "Guía de Producción" (evento ON LED): mensaje pre-armado → intro + PDF + link.
                  try { await guiaProduccionOnInbound(env, phone, msgBody); } catch (_) {}
                  // CAPI: un lead B2B que responde = señal de calidad -> "QualifiedLead" a Meta.
                  try { await maybeCapiQualifiedLead(env, phone); } catch (_) {}
                  // Guía de Producción — re-ocultar como ÚLTIMA acción: si el lead está en otra campaña
                  // de cursos (MiniSupernova/lanzamiento), sus hooks de reveal recién corridos movieron el
                  // chat oculto → 'cursos'. El trigger de la guía gana: vuelve a 'oculto' (hasta el jueves).
                  // El guard protege a los que un humano ya atiende y a privado/corte.
                  try { await guiaProduccionHideFast(env, phone, msgBody); } catch (_) {}
                }
              }

              // Coexistence: smb_message_echoes — mensajes que Joaco escribió
              // desde la app de WhatsApp Business del celular. 360dialog los manda
              // en `value.message_echoes[]` (NO en value.messages), con field:
              // 'smb_message_echoes'. Por eso antes los ignorábamos silenciosamente.
              // Estructura del echo:
              //   { from: businessNumber, to: clientNumber, id, timestamp, type, text|image|...}
              for (const echo of (value?.message_echoes || [])) {
                const wamid = echo.id || '';
                if (!wamid) continue;
                const phone = String(echo.to || '').replace(/\D/g, ''); // destinatario = cliente
                const ts = echo.timestamp ? new Date(parseInt(echo.timestamp) * 1000).toISOString() : new Date().toISOString();
                const msgType = echo.type || 'unknown';
                let msgBody = '';
                let mediaUrl = '';
                if (echo.text) msgBody = echo.text.body || '';
                else if (echo.image) { msgBody = echo.image.caption || ''; mediaUrl = echo.image.id || ''; }
                else if (echo.video) { msgBody = echo.video.caption || ''; mediaUrl = echo.video.id || ''; }
                else if (echo.audio) { mediaUrl = echo.audio.id || ''; }
                else if (echo.document) { msgBody = echo.document.filename || ''; mediaUrl = echo.document.id || ''; }
                else if (echo.sticker) { mediaUrl = echo.sticker.id || ''; }
                else if (echo.reaction) { msgBody = echo.reaction.emoji || ''; }
                else if (echo.location) { msgBody = `[ubicacion] ${echo.location.latitude},${echo.location.longitude}${echo.location.name ? ' — ' + echo.location.name : ''}`; }
                const contextId = echo.context?.id || echo.reaction?.message_id || '';
                // Bajar media a R2 si tiene id (algunos echoes traen el media id).
                let r2Key = '';
                if (mediaUrl && env.MEDIA) {
                  try { const dl = await downloadMediaWithRetry(env, mediaUrl); if (dl) r2Key = dl.key; } catch (_) {}
                }
                if (msgType === 'audio' && r2Key && env.AI) {
                  try { const t = await transcribeAudio(env, r2Key); if (t) msgBody = '[audio] ' + t; } catch (_) {}
                }
                if (msgType === 'image' && r2Key && env.AI) {
                  try { const desc = await analyzeImage(env, r2Key); if (desc) msgBody = (msgBody ? msgBody + ' | ' : '') + '[imagen] ' + desc; } catch (_) {}
                }
                try {
                  // Upsert. Si el wamid ya existe como placeholder de status (body
                  // vacío, msg_type='status'), lo completamos con el body real del echo.
                  await env.DB.prepare(
                    `INSERT INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status)
                     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                     ON CONFLICT(wamid) DO UPDATE SET
                       direction = excluded.direction,
                       phone = excluded.phone,
                       msg_type = excluded.msg_type,
                       body = excluded.body,
                       media_url = excluded.media_url,
                       context_id = excluded.context_id,
                       ts = excluded.ts
                     WHERE wa_messages.body IS NULL OR wa_messages.body = '' OR wa_messages.msg_type = 'status'`
                  ).bind(ts, wamid, 'outbound', phone, '', msgType, msgBody, r2Key || mediaUrl, contextId, null).run();
                } catch (_) {}
              }

              // Status updates (sent, delivered, read) para mensajes salientes
              // [Etapa 1] Internos (el equipo): una sola lectura por lote, de caché (internosSet, 10 min). El modo de
              // los avisos (kv cacheado 60 s) solo se pide si en el lote hay un 'failed', que es lo único que lo usa:
              // pedirlo en cada lote de sent/delivered/read (~5 mil statuses por día) refrescaba la caché a cada
              // minuto y era la mayor parte de lo que leían los avisos en la D1, también en off.
              let _int = null, _avModo = 'off';
              if ((value?.statuses || []).length) {
                try { _int = await internosSet(env); } catch (_) {}
                if (value.statuses.some(s => s && s.status === 'failed')) { try { _avModo = (await avisoCfg(env)).modo; } catch (_) {} }
              }
              for (const st of (value?.statuses || [])) {
                const wamid = st.id || '';
                const status = st.status || ''; // sent | delivered | read | failed
                const phone = st.recipient_id || '';
                const ts = st.timestamp ? new Date(parseInt(st.timestamp) * 1000).toISOString() : new Date().toISOString();
                if (!wamid) continue;
                try {
                  // Leer status previo antes de actualizar — para no notificar dos veces el mismo failed
                  let prevStatus = null;
                  let prevBody = '';
                  let prevCampana = false; // plantilla de una campaña automática (broadcast, etc.)
                  try {
                    const row = await env.DB.prepare('SELECT status, body, msg_type, automated FROM wa_messages WHERE wamid = ?').bind(wamid).first();
                    prevStatus = row?.status || null;
                    prevBody = row?.body || '';
                    prevCampana = row?.msg_type === 'template' && Number(row?.automated) === 1;
                  } catch (_) {}
                  // Intentar actualizar status de un mensaje saliente existente
                  const updated = await env.DB.prepare(
                    'UPDATE wa_messages SET status = ? WHERE wamid = ?'
                  ).bind(status, wamid).run();
                  // Si no existe (mensaje enviado antes del webhook), insertar
                  if (!updated?.meta?.changes) {
                    await env.DB.prepare(
                      'INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
                    ).bind(ts, wamid, 'outbound', phone, '', 'status', '', '', '', status).run();
                  }
                  // Auto-mark conversation as read when an outbound message is sent
                  // (means someone replied from WA Web/phone)
                  if (status === 'sent' && phone) {
                    try {
                      await env.DB.prepare(
                        'INSERT INTO wa_read_cursor (phone, last_read_ts, updated_at) VALUES (?, ?, ?) ON CONFLICT(phone) DO UPDATE SET last_read_ts = excluded.last_read_ts, updated_at = excluded.updated_at'
                      ).bind(phone, ts, ts).run();
                    } catch (_) {}
                  }
                  // Si un envío vuelve a salir OK y había bloqueo de pago activo,
                  // levantarlo (se reanudan los flujos automáticos) y avisar.
                  // (Vale para CUALQUIER destinatario, también internos: el corte de internos va más abajo.)
                  if (status === 'sent' || status === 'delivered') {
                    try {
                      if (await clearWaBillingBlock(env)) {
                        const _txt = 'WhatsApp volvió a andar — reanudo los envíos automáticos';
                        await avisoInterno(env, {
                          para: ['gaspar', 'bruno'], tipo: 'wa_bloqueo_pago_ok', prioridad: 'P2', texto: _txt,
                          legacy: env.ADMIN_NOTIFY_PHONE ? () => waSendText(env, env.ADMIN_NOTIFY_PHONE, _txt, { esAviso: true }) : null,
                          legacyDest: env.ADMIN_NOTIFY_PHONE,
                        });
                      }
                    } catch (_) {}
                  }
                  const errs = Array.isArray(st.errors) ? st.errors : [];
                  const errCode = errs.length ? errs[0].code : null;
                  // Evitar el duplicado feo "X: X" cuando title === message.
                  const errMsg = errs.length
                    ? (errs[0].title || 'error') + (errs[0].message && errs[0].message !== errs[0].title ? ': ' + errs[0].message : '')
                    : 'sin detalle';
                  // ¿El destinatario es del equipo? GUARDIA anti-loop: si el envío que falló era un aviso a un interno
                  // (su ventana de 24h cerrada → rebota 131047), NO se genera otro aviso de cliente, porque ese también
                  // fallaría → recursión infinita (bug histórico que saturó la D1). Se compara por dígitos.
                  // En off/dry la rama de clientes usa la guardia de SIEMPRE (los 3 números fijos), así hacia afuera todo
                  // sigue igual (hoy una falla a Agus/Facu/Abril le llega a Gaspar como "Falló envío WA"); en 'on', todo
                  // internosSet, y si esa lectura falló (fail-closed) en este lote no se avisan fallas de clientes.
                  const _dig = String(phone).replace(/\D/g, '');
                  const _esInterno = _int ? _int.set.has(_dig) : INTERNOS_FIJOS.includes(_dig);
                  const _guardia = _avModo === 'on' ? (_esInterno || !_int || !_int.ok) : INTERNOS_FIJOS.includes(_dig);
                  // Notificar al admin si el envío FALLA (primera vez que llega como failed)
                  if (status === 'failed' && prevStatus !== 'failed') {
                    if (isBillingBlockError(errCode, errMsg)) {
                      // Bloqueo de cuenta por pago: pausar envíos automáticos + avisar 1 vez por turno de 12 h. El
                      // bloqueo se registra para CUALQUIER destinatario (también internos: el breaker se arma igual).
                      // Si el que rebotó era un envío al equipo (un aviso, una lista, el reporte), soloRegistrar: el
                      // status de un aviso no puede generar otro aviso (si el aviso de bloqueo también rebota, sería
                      // la cadena aviso → rebote → aviso). Ese rebote lo avisa el cron (avisoBloqueoPagoCron) a los
                      // 5 min, mismo texto y destino que hoy. Sin el episodio guardado tampoco se avisa (waEpisodioPago).
                      const { shouldNotify, since, turno } = await setWaBillingBlock(env, errMsg, { soloRegistrar: _esInterno });
                      if (shouldNotify) {
                        try { await avisoBloqueoPago(env, WA_BILLING_BLOCK_KEY, since, turno, errMsg); } catch (_) {}
                      }
                    } else if (!_guardia) {
                      // Fallo puntual hacia un CLIENTE (no interno, no billing). Los fallos hacia CLIENTES sí se avisan.
                      const _m = prevBody && prevBody.match(/\[plantilla:\s*([^\]\s]+)/);
                      const _tpl = _m ? _m[1] : null;
                      if (_tpl && !esCampanaMasiva(_tpl)) {
                        // Plantilla de venta/seguimiento (Bruno/Joaco) falló → aviso CONFIABLE a Bruno + Gaspar
                        // (plantilla + fallback), deduplicado, con tope por hora. Pedido de Bruno (3-sep).
                        // [Etapa 1] + wamid → en 'on' le llega al autor (wa_send_author).
                        try { await notifyTplFail(env, { name: _tpl, phone, reason: describeSendFailure({ code: errCode, error: errMsg }), wamid, soloLegacy: _esInterno }); } catch (_) {}
                      } else if (env.ADMIN_NOTIFY_PHONE && !(prevCampana && await esEnvioDeBroadcast(env, phone, ts))) {
                        // Texto libre o plantilla 1 a 1 → aviso a Gaspar por texto (como antes). Solo las de
                        // un BROADCAST del panel (guardan el texto, no el marcador) ya no avisan una por una:
                        // rebotan a montones y solo hacían ruido. Las de venta (lead B2B, revendedores) siguen.
                        const preview = prevBody ? prevBody.slice(0, 100) + (prevBody.length > 100 ? '…' : '') : '';
                        const summary = `⚠ Falló envío WA a ${phone}\nError: ${errMsg}` + (preview ? `\nMensaje: "${preview}"` : '');
                        if (_esInterno) {
                          // Alguien del equipo fuera de la guardia vieja (solo en off/dry): lo de hoy, sin registrar
                          // como falla de cliente (la registra avisoInternoStatus como falla_interna).
                          try { await waSendText(env, env.ADMIN_NOTIFY_PHONE, summary, { esAviso: true }); } catch (_) {}
                        } else {
                          // [Etapa 1] Al AUTOR del envío (wa_send_author; sin autor = envío automático → resumen del
                          // dueño del chat) + copia P3 a Gaspar. P2, o P1 si el chat tiene plata en juego.
                          try {
                            const _prio = _avModo === 'off' ? 'P2' : await avisoPrioFalla(env, phone);
                            await avisoInterno(env, {
                              para: [{ autor: wamid, phone, prioridad: _prio }, { slug: 'gaspar', prioridad: 'P3' }],
                              tipo: 'falla_envio', prioridad: _prio, texto: summary, clave: 'falla:' + wamid, refPhone: phone,
                              legacy: () => waSendText(env, env.ADMIN_NOTIFY_PHONE, summary, { esAviso: true }),
                              legacyDest: env.ADMIN_NOTIFY_PHONE,
                            });
                          } catch (_) {}
                        }
                      }
                    }
                  }
                  // [Etapa 1] Status de un envío al EQUIPO → seguimiento del aviso (entregado / leído / falló + 1
                  // reintento por plantilla). Va DESPUÉS de lo del bloqueo por pago (que vale para todos) y nunca llama
                  // a avisoInterno ni pasa por la rama de clientes.
                  if (_esInterno) {
                    try { await avisoInternoStatus(env, { wamid, status, phone, errCode, errMsg, prevBody, primeraVez: prevStatus !== status }); } catch (_) {}
                  }
                } catch (_) {}
              }
            }
          }
        } catch (e) { console.error('webhook processing error:', e); }
      };
      // Procesar en background, responder inmediato
      if (typeof ctx !== 'undefined') ctx.waitUntil(processWebhook());
      else await processWebhook();
      return json({ ok: true });
    }

    // ----- Tracking público -----
    if (request.method === 'POST' && path === '/event') {
      let body;
      try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
      const { user, action, itemId, itemKind, undo } = body || {};
      if (!user || !action || !itemId) return json({ error: 'missing fields' }, 400);
      const ts = new Date().toISOString();
      await env.DB.prepare(
        'INSERT INTO events (user, action, item_id, item_kind, undo, ts) VALUES (?, ?, ?, ?, ?, ?)'
      ).bind(user, action, itemId, itemKind || '', undo ? 1 : 0, ts).run();
      return noContent();
    }

    // ----- Done marks (persistente, reemplaza localStorage) -----
    // Cada uno lee/escribe SOLO sus marcas: sesión válida (no logística) y `user` = dueño de la sesión.
    if (path === '/done' && ['GET', 'POST', 'DELETE'].includes(request.method)) {
      const si = await sesionInterna(env, request);
      if (si.error) return si.error;
      let doneUser = url.searchParams.get('user');
      if (request.method !== 'GET') {
        try { doneUser = ((await request.clone().json()) || {}).user; } catch { return json({ error: 'invalid json' }, 400); }
      }
      if (doneUser && !esMismoUsuario(si.session.user, doneUser)) return json({ error: 'forbidden' }, 403);
    }
    if (request.method === 'GET' && path === '/done') {
      const user = url.searchParams.get('user');
      if (!user) return json({ error: 'missing user' }, 400);
      const rs = await env.DB.prepare('SELECT item_id, ts FROM done_marks WHERE user = ?').bind(user).all();
      const marks = {};
      for (const r of (rs.results || [])) marks[r.item_id] = r.ts;
      return json({ marks });
    }

    if (request.method === 'POST' && path === '/done') {
      let body;
      try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
      const { user, itemId } = body || {};
      if (!user || !itemId) return json({ error: 'missing fields' }, 400);
      const ts = new Date().toISOString();
      await env.DB.prepare(
        'INSERT OR REPLACE INTO done_marks (user, item_id, ts) VALUES (?, ?, ?)'
      ).bind(user, itemId, ts).run();
      return json({ ts });
    }

    if (request.method === 'DELETE' && path === '/done') {
      let body;
      try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
      const { user, itemId } = body || {};
      if (!user || !itemId) return json({ error: 'missing fields' }, 400);
      await env.DB.prepare('DELETE FROM done_marks WHERE user = ? AND item_id = ?').bind(user, itemId).run();
      return noContent();
    }

    // ----- Auth -----
    if (request.method === 'POST' && path === '/auth/login') {
      let body;
      try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
      const { user, password } = body || {};
      if (!user) return json({ error: 'missing fields' }, 400);
      const userSlug = String(user).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
      // Alias del slug → ids posibles en users_panel (Joaquín↔joaco, Abril↔cursos).
      const lookupIds = userLookupIds(userSlug);
      const placeholders = lookupIds.map(() => '?').join(',');
      const panelUser = await env.DB.prepare(
        `SELECT id, rol, password_hash FROM users_panel WHERE id IN (${placeholders}) AND activo = 1 LIMIT 1`
      ).bind(...lookupIds).first();

      const isAdminUser = userSlug === 'gaspar' || (panelUser && panelUser.rol === 'admin');
      // Freno de fuerza bruta (oct-2026, pensado para el usuario externo de logística): 8 intentos SEGUIDOS para ese usuario
      // → 15 min bloqueado (contados desde el 8°); se resetea al acertar, y si pasan 15 min sin intentos el contador vuelve a
      // empezar (antes, vencido el bloqueo, un solo error volvía a bloquear otros 15 min). El intento se RESERVA de forma
      // atómica ANTES de comparar la contraseña (un solo statement): requests en paralelo ya no pasan todas con el mismo
      // contador. Clave por el id real del usuario (los alias comparten contador; coincide con el borrado al cambiar la
      // contraseña de logística). Solo usuarios con contraseña propia (hash): el login legacy sin contraseña no cambia y al
      // admin no se lo bloquea (nadie puede dejar a Gaspar afuera tirando contraseñas).
      const failKey = 'login_fail:' + String((panelUser && panelUser.id) || userSlug).trim();
      const conFreno = !!(panelUser && panelUser.password_hash && !isAdminUser);

      if (isAdminUser) {
        // Gaspar: contraseña en env.ADMIN_PASSWORD.
        if (!password) return json({ error: 'missing fields' }, 400);
        if (!env.ADMIN_PASSWORD) return json({ error: 'server not configured' }, 500);
        if (password !== env.ADMIN_PASSWORD) {
          await new Promise(r => setTimeout(r, 250));
          return unauthorized('credenciales inválidas');
        }
      } else if (panelUser && panelUser.password_hash) {
        // Comercial / diseñador con password: validar hash SHA-256.
        if (!password) return json({ error: 'missing fields' }, 400);
        if (conFreno) {
          // v = {n, at}: n = intentos de la racha, at = último intento contado. Vencida la ventana → racha nueva (n=1). Con
          // n>=8 ya no se cuenta ni se corre `at` (el bloqueo dura 15 min desde el 8°): n=9 = bloqueado.
          const ahora = new Date().toISOString();
          let nInt = 0;
          try {
            const rf = await env.DB.prepare("INSERT INTO kv_cache (k, v, updated_at) VALUES (?, json_object('n', 1, 'at', ?), ?) ON CONFLICT(k) DO UPDATE SET v = CASE WHEN json_valid(kv_cache.v) = 0 OR IFNULL(json_extract(kv_cache.v, '$.at'), '') < ? THEN json_object('n', 1, 'at', ?) WHEN IFNULL(json_extract(kv_cache.v, '$.n'), 0) >= 8 THEN json_object('n', 9, 'at', json_extract(kv_cache.v, '$.at')) ELSE json_object('n', IFNULL(json_extract(kv_cache.v, '$.n'), 0) + 1, 'at', ?) END, updated_at = excluded.updated_at RETURNING v").bind(failKey, ahora, ahora, isoHace(15 * 60 * 1000), ahora, ahora).first();
            const f = rf ? JSON.parse(rf.v) : null; nInt = (f && +f.n) || 0;
          } catch (_) {} // si el freno falla, no deja a nadie afuera (como antes)
          if (nInt > 8) return json({ error: 'Demasiados intentos. Probá de nuevo en 15 minutos.' }, 429);
        }
        const inputHash = await sha256hex(password);
        if (inputHash !== panelUser.password_hash) {
          await new Promise(r => setTimeout(r, 250));
          return unauthorized('credenciales inválidas');
        }
        if (conFreno) { try { await env.DB.prepare('DELETE FROM kv_cache WHERE k = ?').bind(failKey).run(); } catch (_) {} }
      } else if (panelUser) {
        // Usuario existe pero sin password configurada → entra sin password (legacy).
      } else {
        // Usuario desconocido.
        await new Promise(r => setTimeout(r, 250));
        return unauthorized('usuario desconocido');
      }
      const token = randomToken();
      const now = new Date();
      // Usuarios externos (logística, Sin Frontera): sesión de 7 días (el resto, 30).
      const sesDias = ((panelUser && ['logistica', 'sinfrontera'].includes(panelUser.rol)) || esUsuarioLogistica(user) || esUsuarioSinFrontera(user)) ? LOGISTICA_SESSION_DAYS : SESSION_DAYS;
      const expires = new Date(now.getTime() + sesDias * 86400000);
      const userSes = canonSessionUser(user);
      await env.DB.prepare(
        'INSERT INTO sessions (token, user, expires_at, created_at) VALUES (?, ?, ?, ?)'
      ).bind(token, userSes, expires.toISOString(), now.toISOString()).run();
      // rol: el front lo usa para los usuarios de rol dinámico (productores de neón → solo su pantalla).
      return json({ token, user: userSes, expiresAt: expires.toISOString(), rol: isAdminUser ? 'admin' : String((panelUser && panelUser.rol) || '') });
    }

    if (request.method === 'POST' && path === '/auth/logout') {
      const session = await getSession(env, request);
      if (session) await env.DB.prepare('DELETE FROM sessions WHERE token = ?').bind(session.token).run();
      return noContent();
    }

    if (request.method === 'GET' && path === '/auth/me') {
      const session = await getSession(env, request);
      if (!session) return unauthorized();
      const _pzMe = await productorDeSesion(env, session.user);
      if (_pzMe && _pzMe.error) return json({ error: 'reintentá' }, 503);
      if (_pzMe && !_pzMe.activo) return unauthorized();
      return json({ user: session.user, rol: _pzMe ? 'productor' : await getSessionRole(env, session.user) });
    }

    // ===== Agenda del equipo (calendario interno) =====
    if (path === '/admin/agenda' || path.startsWith('/admin/agenda/')) {
      return await agendaRoute(env, request, url, path);
    }

    // POST /auth/switch { user } — cambiar de usuario SIN contraseña. SOLO el admin (Gaspar): se
    // autentica con SU token y el backend le emite un token de sesión del usuario destino, así ve la
    // vista scopeada de esa persona (impersonación). Ningún otro rol puede usarlo.
    if (request.method === 'POST' && path === '/auth/switch') {
      const session = await getSession(env, request);
      if (!session) return unauthorized();
      if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden: admin only' }, 403);
      let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
      const target = String(body?.user || '').trim();
      if (!target) return json({ error: 'missing user' }, 400);
      const tslug = target.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
      // El destino debe existir y estar activo (o ser el propio admin).
      let okTarget = tslug === 'gaspar', tRol = '';
      if (!okTarget) {
        const ids = userLookupIds(tslug); const ph = ids.map(() => '?').join(',');
        try { const tr = await env.DB.prepare(`SELECT rol FROM users_panel WHERE id IN (${ph}) AND activo = 1 LIMIT 1`).bind(...ids).first(); okTarget = !!tr; tRol = (tr && tr.rol) || ''; } catch (_) {}
      }
      if (!okTarget) return json({ error: 'usuario desconocido' }, 404);
      const token = randomToken();
      const now = new Date();
      const expires = new Date(now.getTime() + ((tRol === 'logistica' || tRol === 'sinfrontera' || esUsuarioLogistica(target) || esUsuarioSinFrontera(target)) ? LOGISTICA_SESSION_DAYS : SESSION_DAYS) * 86400000);
      const targetSes = canonSessionUser(target);
      await env.DB.prepare('INSERT INTO sessions (token, user, expires_at, created_at) VALUES (?, ?, ?, ?)').bind(token, targetSes, expires.toISOString(), now.toISOString()).run();
      return json({ token, user: targetSes, expiresAt: expires.toISOString(), rol: tslug === 'gaspar' ? 'admin' : tRol });
    }

    // ----- Reportes (vista Actividad del front; antes público) -----
    if (request.method === 'GET' && path === '/report') {
      const si = await sesionInterna(env, request, ROLES_COTIZADOR);
      if (si.error) return si.error;
      return reportHandler(env, url, false);
    }

    // DEBUG temporal — probar rutas de calidad/estado del número en 360dialog
    // (quality_rating + messaging_limit_tier). Los paths estándar dan "Not found",
    // acá probamos varias para encontrar la correcta del WABA nuevo. Solo admin.
    if (request.method === 'GET' && path === '/debug/wa-quality') {
      const si = await sesionInterna(env, request, ['admin']);
      if (si.error) return si.error;
      const wa = getWaClient(env);
      const out = { provider: wa.provider, base: wa.base || null, phone_id_env: env.WA_PHONE_NUMBER_ID || null, waba_id_env: env.WA_BUSINESS_ACCOUNT_ID || null };
      const tryPath = async (label, u) => {
        try {
          const r = await fetch(u, { headers: wa.headers });
          const t = await r.text();
          out[label] = { status: r.status, body: t.slice(0, 500) };
        } catch (e) { out[label] = { error: String(e && e.message || e) }; }
      };
      await tryPath('a_health_status', `${wa.base}/v1/health_status`);
      await tryPath('b_waba_config', `${wa.base}/v1/configs/whatsapp_business_account`);
      await tryPath('c_phone_by_id', `${wa.base}/${env.WA_PHONE_NUMBER_ID}?fields=quality_rating,messaging_limit_tier,display_phone_number,verified_name,throughput,health_status`);
      await tryPath('d_waba_phones', `${wa.base}/${env.WA_BUSINESS_ACCOUNT_ID}/phone_numbers?fields=quality_rating,messaging_limit_tier,display_phone_number`);
      await tryPath('e_settings', `${wa.base}/v1/settings`);
      return json(out);
    }

    // DEBUG público temporal — reprocesar imágenes pendientes (media_url con id raw).
    if (request.method === 'POST' && path === '/debug/media-reprocess') {
      // Trae media images con media_url numérico (no wa/...) y las baja a R2.
      // Solo media reciente (<3h): reintentar media viejo/expirado dispara el
      // bloqueo 429 de 360dialog ("too many wrong media_id requests") que tumba
      // también la descarga de los media nuevos y válidos.
      const cutoff = new Date(Date.now() - 3 * 60 * 60 * 1000).toISOString();
      const rs = await env.DB.prepare(
        "SELECT id, media_url FROM wa_messages WHERE msg_type IN ('image','video','audio','document','sticker') AND media_url GLOB '[0-9]*' AND length(media_url) > 8 AND ts >= ? ORDER BY ts DESC LIMIT 60"
      ).bind(cutoff).all();
      const pending = rs.results || [];
      let ok = 0, fail = 0;
      const errors = [];
      for (const row of pending) {
        try {
          const result = await downloadMedia(env, row.media_url);
          if (result) {
            await env.DB.prepare('UPDATE wa_messages SET media_url = ? WHERE id = ?').bind(result.key, row.id).run();
            ok++;
          } else {
            fail++;
            errors.push({ id: row.id, media: row.media_url, reason: 'null' });
          }
        } catch (e) { fail++; errors.push({ id: row.id, err: e.message }); }
      }
      return json({ ok, fail, total: pending.length, errors: errors.slice(0, 10) });
    }

    // DEBUG temporal — reprocesar UN media específico (id puntual).
    if (request.method === 'GET' && /^\/debug\/media\/\d+$/.test(path)) {
      const mediaId = path.split('/').pop();
      try {
        const result = await downloadMedia(env, mediaId);
        if (!result) return json({ ok: false, mediaId });
        // Actualizar wa_messages si hay rows con ese mediaId raw.
        await env.DB.prepare('UPDATE wa_messages SET media_url = ? WHERE media_url = ?').bind(result.key, mediaId).run();
        return json({ ok: true, mediaId, ...result });
      } catch (e) {
        return json({ ok: false, error: e.message, mediaId });
      }
    }

    // DEBUG temporal — diagnóstico DETALLADO de descarga de media: expone el
    // status HTTP y el cuerpo de error de cada paso (downloadMedia falla silencioso).
    if (request.method === 'GET' && /^\/debug\/media-info\/\d+$/.test(path)) {
      const mediaId = path.split('/').pop();
      const out = { mediaId };
      try {
        const wa = getWaClient(env);
        out.provider = wa.provider;
        out.base = wa.base || null;
        out.hasKey = !!(wa.headers && (wa.headers['D360-API-KEY'] || wa.headers['Authorization']));
        const step1Url = wa.mediaUrl(mediaId);
        out.step1_url = step1Url;
        const meta = await fetch(step1Url, { headers: wa.headers });
        out.step1_status = meta.status;
        const step1Text = await meta.text();
        let info = {};
        try { info = JSON.parse(step1Text); } catch (_) { out.step1_body = step1Text.slice(0, 500); }
        if (info && info.url) {
          out.media_url_host = (String(info.url).match(/^https?:\/\/([^\/]+)/) || [])[1] || '';
          out.mime = info.mime_type || null;
          let downloadUrl = info.url;
          if (wa.provider === '360dialog' && /lookaside\.fbsbx\.com/.test(downloadUrl)) {
            downloadUrl = downloadUrl.replace('https://lookaside.fbsbx.com', wa.base);
          }
          out.step2_host = (String(downloadUrl).match(/^https?:\/\/([^\/]+)/) || [])[1] || '';
          out.step2_proxied = downloadUrl !== info.url;
          const file = await fetch(downloadUrl, { headers: wa.headers });
          out.step2_status = file.status;
          if (!file.ok) out.step2_body = (await file.text()).slice(0, 500);
          else out.step2_bytes = (await file.arrayBuffer()).byteLength;
        } else {
          out.step1_info = info;
        }
      } catch (e) { out.error = e.message; }
      return json(out);
    }

    // ----- Cotizador params (lectura para quien cotiza; antes público) -----
    if (request.method === 'GET' && path === '/cotizador/params') {
      const si = await sesionInterna(env, request, ROLES_COTIZADOR);
      if (si.error) return si.error;
      const rs = await env.DB.prepare('SELECT key, value FROM cotizador_params').all();
      const params = {};
      // Los parámetros de mano de obra (mo_*) son solo de Gaspar: a vendedores y diseño no les llegan.
      for (const r of (rs.results || [])) { if (si.role !== 'admin' && String(r.key).startsWith('mo_')) continue; params[r.key] = r.value; }
      return json({ params });
    }

    // ----- COGS del Excel 2026v4 (proxy al Apps Script) -----
    // El front no puede leer el Apps Script directo (CORS lo bloquea), así que
    // el worker hace de proxy server-to-server. Devuelve los costos reales del
    // mes actual leídos de la hoja COGS, para que el cotizador nuevo cotice con
    // datos vivos. Cache D1 (TTL 20 min) salvo ?fresh=1 que fuerza relectura.
    // Antes era público: ahora solo quien cotiza (sesión válida, nunca logística). El sueldo fijo de
    // Joaco (joaquin_fijo*) lo ven solo el admin y Joaco (su panel "Tu sueldo"); ?fresh=1 solo el admin.
    if (request.method === 'GET' && path === '/cotizador/cogs') {
      const si = await sesionInterna(env, request, ROLES_COTIZADOR);
      if (si.error) return si.error;
      const veSueldoJoaco = si.role === 'admin' || canonWorker(si.session.user) === 'joaco';
      const sinSueldo = (d) => {
        if (veSueldoJoaco || !d || !d.cogs) return d;
        const { joaquin_fijo_by_month, joaquin_fijo, ...cogs } = d.cogs;
        return { ...d, cogs };
      };
      const scriptUrl = env.APPS_SCRIPT_URL;
      if (!scriptUrl) return json({ error: 'APPS_SCRIPT_URL no configurada en el worker' }, 500);
      const fresh = url.searchParams.get('fresh') === '1' && si.role === 'admin';
      const TTL_MS = 20 * 60 * 1000;
      // 1) Cache en kv_cache (key 'cogs_excel').
      if (!fresh) {
        try {
          const cached = await env.DB.prepare(
            "SELECT v, updated_at FROM kv_cache WHERE k = 'cogs_excel'"
          ).first();
          if (cached && cached.v && cached.updated_at) {
            const age = Date.now() - Date.parse(cached.updated_at);
            if (age >= 0 && age < TTL_MS) {
              return json(sinSueldo({ ...JSON.parse(cached.v), cached: true, age_ms: age }));
            }
          }
        } catch (_) { /* cache miss o JSON inválido → seguimos al fetch */ }
      }
      // 2) Fetch al Apps Script (server-to-server, sin CORS).
      let data;
      try {
        const r = await fetch(scriptUrl + '?action=cogs', { redirect: 'follow' });
        data = await r.json();
      } catch (e) {
        // Si falla la red, devolvemos el cache aunque esté vencido.
        try {
          const stale = await env.DB.prepare("SELECT v FROM kv_cache WHERE k = 'cogs_excel'").first();
          if (stale && stale.v) return json(sinSueldo({ ...JSON.parse(stale.v), cached: true, stale: true }));
        } catch (_) {}
        return json({ error: 'no pude leer COGS del Apps Script: ' + (e.message || e) }, 502);
      }
      // 3) Guardar en cache solo si vino bien.
      if (data && data.ok) {
        try {
          await env.DB.prepare(
            "INSERT INTO kv_cache (k, v, updated_at) VALUES ('cogs_excel', ?, ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v, updated_at = excluded.updated_at"
          ).bind(JSON.stringify(data), new Date().toISOString()).run();
        } catch (_) { /* si falla el cache no es fatal */ }
      }
      return json(sinSueldo(data));
    }

    // ----- Portal Revendedores (publico, cuentas propias, aislado del CRM) -----
    if (path === '/revendedores' || path === '/revendedores/') {
      return new Response(REVENDEDOR_HTML, {
        headers: { 'content-type': 'text/html; charset=utf-8', 'x-robots-tag': 'noindex, nofollow', 'cache-control': 'no-store' }
      });
    }
    if (path.startsWith('/revendedor/')) {
      try {
      await ensureRevSchema(env);

      if (request.method === 'POST' && path === '/revendedor/signup') {
        let body; try { body = await request.json(); } catch (_) { return json({ error: 'JSON invalido' }, 400); }
        const nombre = String(body.nombre || '').trim();
        const email = String(body.email || '').trim().toLowerCase();
        const whatsapp = normalizeArPhone(body.whatsapp) || String(body.whatsapp || '').trim();
        const password = String(body.password || '');
        if (!nombre || !email || !whatsapp || !password) return json({ error: 'Faltan datos.' }, 400);
        if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return json({ error: 'Email invalido.' }, 400);
        if (password.length < 6) return json({ error: 'La contrasena necesita al menos 6 caracteres.' }, 400);
        const dup = await env.DB.prepare('SELECT id FROM revendedores WHERE email = ?').bind(email).first();
        if (dup) return json({ error: 'Ya existe una cuenta con ese email. Proba entrar.' }, 409);
        const { hash, salt } = await revHashPassword(password);
        const now = new Date().toISOString();
        const ins = await env.DB.prepare(
          'INSERT INTO revendedores (nombre, email, whatsapp, pass_hash, pass_salt, created_at) VALUES (?, ?, ?, ?, ?, ?)'
        ).bind(nombre, email, whatsapp, hash, salt, now).run();
        let id = ins.meta && ins.meta.last_row_id;
        if (!id) { const row = await env.DB.prepare('SELECT id FROM revendedores WHERE email = ?').bind(email).first(); id = row && row.id; }
        const tk = randomToken();
        const exp = new Date(Date.now() + 90 * 24 * 3600 * 1000).toISOString();
        await env.DB.prepare('INSERT INTO revendedor_sesiones (token, revendedor_id, expires_at, created_at) VALUES (?, ?, ?, ?)').bind(tk, id, exp, now).run();
        return json({ ok: true, token: tk, revendedor: { id, nombre, email } });
      }

      if (request.method === 'POST' && path === '/revendedor/login') {
        let body; try { body = await request.json(); } catch (_) { return json({ error: 'JSON invalido' }, 400); }
        const email = String(body.email || '').trim().toLowerCase();
        const password = String(body.password || '');
        if (!email || !password) return json({ error: 'Faltan datos.' }, 400);
        const u = await env.DB.prepare('SELECT id, nombre, email, pass_hash, pass_salt FROM revendedores WHERE email = ?').bind(email).first();
        if (!u) return json({ error: 'Email o contrasena incorrectos.' }, 401);
        const { hash } = await revHashPassword(password, u.pass_salt);
        if (hash !== u.pass_hash) return json({ error: 'Email o contrasena incorrectos.' }, 401);
        const tk = randomToken();
        const now = new Date().toISOString();
        const exp = new Date(Date.now() + 90 * 24 * 3600 * 1000).toISOString();
        await env.DB.prepare('INSERT INTO revendedor_sesiones (token, revendedor_id, expires_at, created_at) VALUES (?, ?, ?, ?)').bind(tk, u.id, exp, now).run();
        return json({ ok: true, token: tk, revendedor: { id: u.id, nombre: u.nombre, email: u.email } });
      }

      // De aca en adelante requiere sesion de revendedor.
      const sess = await getRevSession(env, request);
      if (!sess) return unauthorized();

      if (request.method === 'GET' && path === '/revendedor/me') {
        return json({ id: sess.id, nombre: sess.nombre, email: sess.email });
      }
      if (request.method === 'POST' && path === '/revendedor/logout') {
        await env.DB.prepare('DELETE FROM revendedor_sesiones WHERE token = ?').bind(sess.token).run();
        return json({ ok: true });
      }
      if (request.method === 'POST' && path === '/revendedor/cotizar') {
        let body; try { body = await request.json(); } catch (_) { return json({ error: 'JSON invalido' }, 400); }
        const ancho = +body.ancho || 0, alto = +body.alto || 0, neon = +body.neon || 0;
        const tramos = +body.tramos || 1;
        const tipo = String(body.tipo || 'INT').toUpperCase() === 'EXT' ? 'EXT' : 'INT';
        const nombre = String(body.nombre || '').slice(0, 80).trim();
        const entrega = String(body.entrega || 'envio').toLowerCase() === 'retiro' ? 'retiro' : 'envio';
        if (ancho <= 0 || alto <= 0 || neon <= 0) return json({ error: 'Carga ancho, alto y metros de neon.' }, 400);
        if (ancho > 2000 || alto > 2000 || neon > 200) return json({ error: 'Medidas fuera de rango.' }, 400);
        const p = await revPriceParams(env);
        let { transFinal, negroFinal } = revCalcPrecio({ ancho, alto, neon, tramos, tipo }, p);
        // El envio YA esta incluido en el precio. Si el revendedor elige RETIRO en taller,
        // se descuenta el envio segun tamano (m2 del sheet = ancho*alto/100): <=25 $10k, <=50 $20k, resto $35k.
        const m2Sheet = (ancho * alto) / 100;
        const envioCost = m2Sheet <= 25 ? 10000 : m2Sheet <= 50 ? 20000 : 35000;
        if (entrega === 'retiro') { transFinal = Math.max(0, transFinal - envioCost); negroFinal = Math.max(0, negroFinal - envioCost); }
        const trans = revNumbers(transFinal), negro = revNumbers(negroFinal);
        const now = new Date().toISOString();
        try {
          await env.DB.prepare(
            'INSERT INTO revendedor_cotizaciones (revendedor_id, nombre, ancho, alto, neon, tramos, tipo, sugerido, costo, reventa_min, reventa_max, created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)'
          ).bind(sess.id, nombre, ancho, alto, neon, tramos, tipo, trans.sugerido, trans.costo, trans.reventaMin, trans.reventaMax, now).run();
        } catch (_) {}
        return json({ ok: true, trans, negro, entrega, envioCost });
      }
      if (request.method === 'GET' && path === '/revendedor/historial') {
        const rs = await env.DB.prepare(
          'SELECT id, nombre, ancho, alto, neon, tramos, tipo, sugerido, costo, reventa_min, reventa_max, created_at FROM revendedor_cotizaciones WHERE revendedor_id = ? ORDER BY id DESC LIMIT 40'
        ).bind(sess.id).all();
        return json({ ok: true, items: rs.results || [] });
      }
      return json({ error: 'not found' }, 404);
      } catch (e) {
        console.error('rev_error', (e && (e.stack || e.message)) || e);
        return json({ error: 'Hubo un error, proba de nuevo.' }, 500);
      }
    }

    // ----- Admin (requiere Bearer) -----
    // Media SALIENTE de IG (ig/out_): PÚBLICA sin auth. Instagram descarga la URL (sin token)
    // para reenviarla al cliente; con el gate de auth recibía 401 y fallaba ("Upload failed").
    // Son archivos que NOSOTROS mandamos (imágenes/audios salientes, no sensibles) y con nombre
    // aleatorio inadivinable. El resto de /admin/media/ sigue protegido por el gate de abajo.
    if (request.method === 'GET' && path.startsWith('/admin/media/')) {
      const _k = decodeURIComponent(path.slice('/admin/media/'.length));
      if (_k.startsWith('ig/out_') && env.MEDIA) {
        const _obj = await env.MEDIA.get(_k);
        if (_obj) return new Response(_obj.body, { headers: { ...cors(), 'Content-Type': _obj.httpMetadata?.contentType || 'application/octet-stream', 'Cache-Control': 'public, max-age=31536000, immutable' } });
      }
    }

    // ===== OAuth de Google Drive (una sola vez, "como Gaspar") =====
    // El callback lo llama Google SIN token de sesión, por eso van ANTES del muro de /admin/.
    // Seguridad: /start (admin) genera un `state` de un solo uso guardado en kv; /callback lo exige.
    if (request.method === 'GET' && path === '/admin/corte/oauth/start') {
      // Gate manual por token (el muro está más abajo). Solo Gaspar.
      const qTok = url.searchParams.get('token') || '';
      let okAdmin = false;
      try { const row = await env.DB.prepare('SELECT user, expires_at FROM sessions WHERE token = ?').bind(qTok).first(); if (row && new Date(row.expires_at) >= new Date() && String(row.user || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '') === 'gaspar') okAdmin = true; } catch (_) {}
      if (!okAdmin) return unauthorized();
      if (!env.GOOGLE_OAUTH_CLIENT_ID || !env.GOOGLE_OAUTH_CLIENT_SECRET) return new Response('Falta configurar GOOGLE_OAUTH_CLIENT_ID / GOOGLE_OAUTH_CLIENT_SECRET (secrets del worker) antes de autorizar.', { status: 400, headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
      const state = crypto.randomUUID().replace(/-/g, '') + crypto.randomUUID().replace(/-/g, '');
      await kvSet(env, 'drive_oauth_state', state);
      const redirectUri = url.origin + '/admin/corte/oauth/callback';
      const auth = 'https://accounts.google.com/o/oauth2/v2/auth?' +
        'client_id=' + encodeURIComponent(env.GOOGLE_OAUTH_CLIENT_ID) +
        '&redirect_uri=' + encodeURIComponent(redirectUri) +
        '&response_type=code' +
        '&scope=' + encodeURIComponent('https://www.googleapis.com/auth/drive') +
        '&access_type=offline&prompt=consent&include_granted_scopes=true' +
        '&state=' + encodeURIComponent(state);
      return new Response(null, { status: 302, headers: { Location: auth } });
    }
    if (request.method === 'GET' && path === '/admin/corte/oauth/callback') {
      const okHtml = (msg) => new Response('<!doctype html><meta charset=utf-8><body style="font-family:system-ui;max-width:640px;margin:60px auto;padding:0 20px;line-height:1.5"><h2>Neon Infinito · Drive</h2><p>' + msg + '</p></body>', { status: 200, headers: { 'Content-Type': 'text/html; charset=utf-8' } });
      const errHtml = (msg) => new Response('<!doctype html><meta charset=utf-8><body style="font-family:system-ui;max-width:640px;margin:60px auto;padding:0 20px;line-height:1.5"><h2>Neon Infinito · Drive</h2><p style="color:#b00">' + msg + '</p></body>', { status: 400, headers: { 'Content-Type': 'text/html; charset=utf-8' } });
      const code = url.searchParams.get('code') || '';
      const state = url.searchParams.get('state') || '';
      const gErr = url.searchParams.get('error') || '';
      if (gErr) return errHtml('Google devolvió un error: ' + gErr + '. Volvé a intentar desde el link de autorización.');
      if (!code) return errHtml('Falta el código de autorización.');
      const savedState = await kvGet(env, 'drive_oauth_state', '');
      if (!state || !savedState || state !== savedState) return errHtml('El link de autorización expiró o no es válido. Pedile a Claude un link nuevo.');
      const redirectUri = url.origin + '/admin/corte/oauth/callback';
      try {
        const r = await fetch('https://oauth2.googleapis.com/token', { method: 'POST', headers: { 'content-type': 'application/x-www-form-urlencoded' }, body: 'grant_type=authorization_code&code=' + encodeURIComponent(code) + '&client_id=' + encodeURIComponent(env.GOOGLE_OAUTH_CLIENT_ID) + '&client_secret=' + encodeURIComponent(env.GOOGLE_OAUTH_CLIENT_SECRET) + '&redirect_uri=' + encodeURIComponent(redirectUri) });
        const j = await r.json().catch(() => ({}));
        if (!r.ok || !j.refresh_token) return errHtml('No se pudo obtener el permiso permanente (refresh_token). Detalle: ' + ((j.error_description || j.error) || ('HTTP ' + r.status)) + '. Asegurate de haber aceptado con tu cuenta y volvé a intentar.');
        await kvSet(env, 'drive_refresh_token', j.refresh_token);
        await env.DB.prepare("DELETE FROM kv_cache WHERE k='drive_oauth_state'").run().catch(() => {});
        await env.DB.prepare("DELETE FROM kv_cache WHERE k='drive_token'").run().catch(() => {});
        return okHtml('Listo. El software ya quedó autorizado para guardar los archivos de corte en tu Drive. Podés cerrar esta pestaña.');
      } catch (e) { return errHtml('Error al canjear el código: ' + String((e && e.message) || e)); }
    }

    // ===== Páginas públicas (home + privacidad) =====
    // Requeridas por Google para publicar la app OAuth a producción (deben vivir en el
    // dominio autorizado). Describen el software y el uso del acceso a Google Drive.
    if (request.method === 'GET' && (path === '/' || path === '/inicio')) {
      const html = '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Neon Infinito · Software</title>'
        + '<style>body{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;max-width:720px;margin:0 auto;padding:48px 24px;line-height:1.6;color:#111}h1{margin-bottom:4px}h2{margin-top:32px}.muted{color:#666}a{color:#1a56db}</style></head><body>'
        + '<h1>Neon Infinito · Software interno</h1>'
        + '<p class="muted">Herramienta de gestión interna de Neon Infinito (carteles de neón LED y servicio de corte de acrílicos, Argentina).</p>'
        + '<h2>Qué es</h2><p>Es el sistema privado que Neon Infinito usa para tomar y organizar los pedidos del servicio de corte, coordinar el trabajo del equipo de producción y respaldar los archivos de diseño de cada tanda.</p>'
        + '<h2>Uso de Google Drive</h2><p>El software guarda una copia de respaldo de los archivos de diseño y de las placas cortadas en carpetas de Google Drive de la propia cuenta de Neon Infinito. Solo escribe esos archivos de trabajo; no accede a otros datos personales ni los comparte con terceros.</p>'
        + '<h2>Contacto</h2><p>neoninfinitok@gmail.com</p>'
        + '<p class="muted"><a href="/privacy">Política de privacidad</a></p>'
        + '</body></html>';
      return new Response(html, { status: 200, headers: { ...cors(), 'Content-Type': 'text/html; charset=utf-8' } });
    }
    if (request.method === 'GET' && (path === '/privacy' || path === '/privacidad')) {
      const html = '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Política de privacidad · Neon Infinito</title>'
        + '<style>body{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;max-width:720px;margin:0 auto;padding:48px 24px;line-height:1.6;color:#111}h1{margin-bottom:4px}h2{margin-top:28px}.muted{color:#666}a{color:#1a56db}</style></head><body>'
        + '<h1>Política de privacidad</h1><p class="muted">Neon Infinito · Software interno — última actualización: septiembre 2026</p>'
        + '<p>Esta aplicación es una herramienta interna de Neon Infinito para gestionar el servicio de corte de acrílicos y respaldar sus archivos de trabajo. La usa el propio equipo de Neon Infinito; no está destinada al público general.</p>'
        + '<h2>Datos de Google que utilizamos</h2><p>Cuando autorizás el acceso, la aplicación usa el permiso de Google Drive (<code>drive</code>) con un único fin: crear y guardar los archivos de diseño y de placas cortadas de cada tanda en carpetas de Google Drive de la propia cuenta de Neon Infinito. La aplicación no lee ni recopila tu correo, tus contactos ni otros archivos ajenos a esa función.</p>'
        + '<h2>Cómo usamos y protegemos los datos</h2><p>Los archivos se almacenan en la cuenta de Google de Neon Infinito y en la infraestructura del propio software (Cloudflare). Se usan exclusivamente para la operación interna del servicio de corte. No vendemos, alquilamos ni compartimos los datos de Google del usuario con terceros, y no los usamos para publicidad. El acceso a Google Drive se limita al mínimo necesario para respaldar los archivos de trabajo.</p>'
        + '<h2>Uso limitado (Google API Services)</h2><p>El uso de la información recibida de las APIs de Google por parte de esta aplicación se ajusta a la <a href="https://developers.google.com/terms/api-services-user-data-policy" rel="noopener">Política de datos de usuario de los servicios de las API de Google</a>, incluidos los requisitos de Uso limitado.</p>'
        + '<h2>Cómo revocar el acceso</h2><p>Podés revocar el permiso en cualquier momento desde <a href="https://myaccount.google.com/permissions" rel="noopener">la configuración de tu Cuenta de Google</a>.</p>'
        + '<h2>Contacto</h2><p>Ante cualquier consulta: neoninfinitok@gmail.com</p>'
        + '</body></html>';
      return new Response(html, { status: 200, headers: { ...cors(), 'Content-Type': 'text/html; charset=utf-8' } });
    }

    // Pedidos de corte por la web (landing pública neoninfinitosoftware.com/corte/): sin sesión, con sus propios topes.
    if (path.startsWith('/corte/landing/')) return await corteLandingRoute(request, env, ctx, url, path);

    if (path.startsWith('/admin/')) {
      // Allow token via query param for resources loaded by <img>, <audio>, etc.
      let session = await getSession(env, request);
      if (!session && url.searchParams.get('token')) {
        const qToken = url.searchParams.get('token');
        const row = await env.DB.prepare('SELECT user, expires_at FROM sessions WHERE token = ?').bind(qToken).first();
        if (row && new Date(row.expires_at) >= new Date()) session = { token: qToken, user: row.user };
      }
      if (!session) return unauthorized();
      // Logística (usuario externo): SOLO sus endpoints. Todo lo demás del CRM → 403 aunque tenga sesión válida.
      if (esUsuarioLogistica(session.user) && !path.startsWith('/admin/logistica/') && !path.startsWith('/admin/neon/')) return json({ error: 'forbidden' }, 403);
      // Sin Frontera (usuario externo): SOLO /admin/sinfrontera/* (corpóreos en producción sin precio y sus propios pedidos).
      if (esUsuarioSinFrontera(session.user) && !path.startsWith('/admin/sinfrontera/')) return json({ error: 'forbidden' }, 403);
      // Productores de neón (usuario propio): SOLO /admin/prod/* (sus carteles). Dado de baja → afuera aunque tenga sesión.
      { const _pz = await productorDeSesion(env, session.user); if (_pz) { if (_pz.error) return json({ error: 'No se pudo verificar el usuario. Probá de nuevo en un momento.' }, 503); if (!_pz.activo) return unauthorized(); if (!path.startsWith('/admin/prod/')) return json({ error: 'forbidden' }, 403); } }

      // Registro de actividad por usuario (para el aviso de arranque del equipo): estampa
      // last_active SOLO para los vendedores/diseñador vigilados, throttled a 5 min, sin bloquear
      // la respuesta (waitUntil). Es la señal real de "arrancó a trabajar" (mejor que el login).
      try {
        const _cw = canonWorker(session.user);
        // Solo cuenta como actividad si NO es un request automático. El front manda
        // X-NI-Human='1' cuando hubo interacción humana real hace <5min y '0' en los polls
        // (main-thread + poll-worker de 5s). Así NO se estampan "arranques" fantasma de las
        // 4 AM (celu dormido con la app abierta). Un request sin el header (frontend viejo
        // cacheado) se sigue contando hasta que el cliente actualice (bump de sw).
        if (_cw && request.headers.get('X-NI-Human') !== '0') {
          const _nowA = new Date().toISOString();
          const _thrA = new Date(Date.now() - 5 * 60 * 1000).toISOString();
          // Estampa last_active y, SOLO cuando pasó el throttle (>5 min o primera del día),
          // agrega una marca al historial user_activity_log. Ese historial permite calcular
          // horas trabajadas y pausas >1h en el reporte diario. La lectura extra es barata (4 vigilados).
          ctx.waitUntil((async () => {
            try {
              const _r = await env.DB.prepare("SELECT last_active FROM user_activity WHERE user = ?").bind(_cw).first();
              if (!_r || !_r.last_active || _r.last_active < _thrA) {
                await env.DB.prepare("INSERT INTO user_activity (user, last_active) VALUES (?, ?) ON CONFLICT(user) DO UPDATE SET last_active = excluded.last_active").bind(_cw, _nowA).run();
                await env.DB.prepare("INSERT INTO user_activity_log (user, ts) VALUES (?, ?)").bind(_cw, _nowA).run();
              }
            } catch (_) {}
          })());
        }
      } catch (_) {}

      // Defensa en profundidad: endpoints con datos sensibles (P&L, márgenes,
      // actividad global) requieren que la sesión sea del admin (Gaspar), no
      // cualquier token válido de bajo privilegio.
      const sessionUserKey = String(session.user || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
      const isAdminSession = sessionUserKey === 'gaspar';
      const ADMIN_ONLY_PATHS = ['/admin/business-panel', '/admin/activity'];
      if (ADMIN_ONLY_PATHS.includes(path) && !isAdminSession) {
        return json({ error: 'forbidden: admin only' }, 403);
      }

      if (request.method === 'GET' && path === '/admin/activity') {
        return reportHandler(env, url, true);
      }

      // ----- Framework de venta (sales_framework) -----
      // Lectura: cualquier sesión válida (ver el playbook). Escritura: solo admin.
      if (request.method === 'GET' && path === '/admin/framework') {
        const fw = await getActiveFramework(env);
        if (fw && url.searchParams.get('sections')) {
          await ensureSectionsForVersion(env, fw.version, fw.content);
          const rs = await env.DB.prepare(
            'SELECT order_idx, level, heading, body, tags FROM framework_sections WHERE version = ? ORDER BY order_idx'
          ).bind(fw.version).all();
          return json({ ok: true, framework: fw, sections: (rs.results || []) });
        }
        return json({ ok: true, framework: fw || null });
      }
      if (request.method === 'GET' && path === '/admin/framework/versions') {
        await ensureFrameworkSeeded(env);
        const rs = await env.DB.prepare(
          `SELECT id, version, is_active, source, notes, created_by, created_at
           FROM sales_framework ORDER BY version DESC`
        ).all();
        return json({ ok: true, versions: (rs.results || []) });
      }
      if (request.method === 'POST' && path === '/admin/framework') {
        if (!isAdminSession) return json({ error: 'forbidden: admin only' }, 403);
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const content = String(body?.content || '').trim();
        if (!content) return json({ error: 'missing content' }, 400);
        const notes = String(body?.notes || '');
        const source = ['manual', 'synthesis'].includes(body?.source) ? body.source : 'manual';
        await ensureFrameworkSeeded(env);
        const maxRow = await env.DB.prepare('SELECT MAX(version) AS v FROM sales_framework').first();
        const nextV = (maxRow?.v || 0) + 1;
        await env.DB.prepare('UPDATE sales_framework SET is_active = 0 WHERE is_active = 1').run();
        await env.DB.prepare(
          `INSERT INTO sales_framework (version, content, format, is_active, source, notes, created_by, created_at)
           VALUES (?, ?, 'md', 1, ?, ?, ?, ?)`
        ).bind(nextV, content, source, notes, session.user, new Date().toISOString()).run();
        await deriveFrameworkSections(env, nextV, content);
        return json({ ok: true, version: nextV });
      }
      if (request.method === 'POST' && path === '/admin/framework/activate') {
        if (!isAdminSession) return json({ error: 'forbidden: admin only' }, 403);
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const v = parseInt(body?.version, 10);
        if (!v) return json({ error: 'missing version' }, 400);
        const exists = await env.DB.prepare('SELECT 1 FROM sales_framework WHERE version = ?').bind(v).first();
        if (!exists) return json({ error: 'version not found' }, 404);
        await env.DB.prepare('UPDATE sales_framework SET is_active = 0 WHERE is_active = 1').run();
        await env.DB.prepare('UPDATE sales_framework SET is_active = 1 WHERE version = ?').bind(v).run();
        return json({ ok: true, active: v });
      }

      // ===== Fase 2C: mejoras al playbook (síntesis + aprobación humana) =====
      // Listar propuestas (por defecto las pendientes de revisar).
      if (request.method === 'GET' && path === '/admin/framework/improvements') {
        if (!isAdminSession) return json({ error: 'forbidden: admin only' }, 403);
        await ensureImprovementsSchema(env);
        const status = url.searchParams.get('status') || 'pending';
        const rs = status === 'all'
          ? await env.DB.prepare(`SELECT * FROM framework_improvements ORDER BY (status='pending') DESC, created_at DESC LIMIT 50`).all()
          : await env.DB.prepare(`SELECT * FROM framework_improvements WHERE status = ? ORDER BY created_at DESC LIMIT 50`).bind(status).all();
        const pend = await env.DB.prepare(`SELECT COUNT(*) AS n FROM framework_improvements WHERE status='pending'`).first();
        // Última corrida de síntesis (para mostrar "cuándo / cuánto costó").
        let lastRun = null;
        try { lastRun = await env.DB.prepare(`SELECT created_at, cost_usd, created_by FROM copilot_usage WHERE kind='synthesis' ORDER BY created_at DESC LIMIT 1`).first(); } catch (_) {}
        return json({ ok: true, improvements: (rs.results || []), pending_count: pend?.n || 0, last_run: lastRun });
      }
      // Disparar la síntesis a mano (botón "Generar mejoras ahora"). force salta el gate.
      if (request.method === 'POST' && path === '/admin/framework/improvements/generate') {
        if (!isAdminSession) return json({ error: 'forbidden: admin only' }, 403);
        let body = {};
        try { body = await request.json(); } catch (_) {}
        const res = await synthesizeFrameworkImprovements(env, { force: body?.force !== false, createdBy: session.user });
        if (!res.ok) return json({ error: res.error || 'failed', raw: res.raw }, res.error === 'ANTHROPIC_API_KEY no configurada' ? 503 : 500);
        return json(res);
      }
      // Aprobar una propuesta: aplica el cambio (versión nueva del playbook) y la marca approved.
      if (request.method === 'POST' && path === '/admin/framework/improvements/approve') {
        if (!isAdminSession) return json({ error: 'forbidden: admin only' }, 403);
        await ensureImprovementsSchema(env);
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const id = parseInt(body?.id, 10);
        if (!id) return json({ error: 'missing id' }, 400);
        const imp = await env.DB.prepare(`SELECT * FROM framework_improvements WHERE id = ?`).bind(id).first();
        if (!imp) return json({ error: 'propuesta no encontrada' }, 404);
        if (imp.status !== 'pending') return json({ error: 'ya fue revisada (' + imp.status + ')' }, 409);
        // Propuesta del SERVICIO DE CORTE → se suma a la base de conocimiento del corte (kv corte_knowledge),
        // no al playbook de ventas.
        if (imp.vertical === 'corte') {
          const line = (body?.edited_content != null && String(body.edited_content).trim()) ? String(body.edited_content).trim() : String(imp.proposed_content || '').trim();
          if (!line) return json({ error: 'la propuesta está vacía' }, 400);
          let kb = ''; try { kb = String(await kvGet(env, 'corte_knowledge', '') || ''); } catch (_) {}
          const norm = s => String(s || '').replace(/^[-•\s]+/, '').trim().toLowerCase();
          // Ya está (igual o casi igual): se da por resuelta y sale de la lista (antes respondía 409 y la propuesta quedaba
          // trabada: el botón "no hacía nada").
          if (kb.split('\n').some(l => norm(l) === norm(line) || corteKbParecido(l, line))) {
            await env.DB.prepare(`UPDATE framework_improvements SET status='approved', reviewed_by=?, reviewed_at=?, review_note=? WHERE id = ?`).bind(session.user, new Date().toISOString(), 'ya estaba en el conocimiento', id).run();
            return json({ ok: true, corte: true, ya_estaba: true });
          }
          try { await kvSet(env, 'corte_knowledge', (kb ? kb + '\n' : '') + '- ' + line.replace(/^[-•\s]+/, '')); } catch (_) {}
          await env.DB.prepare(`UPDATE framework_improvements SET status='approved', reviewed_by=?, reviewed_at=? WHERE id = ?`).bind(session.user, new Date().toISOString(), id).run();
          return json({ ok: true, corte: true });
        }
        const applied = await applyImprovementToFramework(env, imp, session.user, body?.edited_content);
        if (!applied.ok) return json({ error: applied.error }, 400);
        await env.DB.prepare(
          `UPDATE framework_improvements SET status='approved', applied_version=?, reviewed_by=?, reviewed_at=? WHERE id = ?`
        ).bind(applied.version, session.user, new Date().toISOString(), id).run();
        return json({ ok: true, applied_version: applied.version });
      }
      // Rechazar una propuesta (con motivo opcional, que es señal para la próxima síntesis).
      if (request.method === 'POST' && path === '/admin/framework/improvements/reject') {
        if (!isAdminSession) return json({ error: 'forbidden: admin only' }, 403);
        await ensureImprovementsSchema(env);
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const id = parseInt(body?.id, 10);
        if (!id) return json({ error: 'missing id' }, 400);
        const upd = await env.DB.prepare(
          `UPDATE framework_improvements SET status='rejected', reviewed_by=?, reviewed_at=?, review_note=? WHERE id = ? AND status='pending'`
        ).bind(session.user, new Date().toISOString(), String(body?.note || '').slice(0, 1000), id).run();
        if (!upd.meta?.changes) return json({ error: 'propuesta no encontrada o ya revisada' }, 404);
        return json({ ok: true });
      }

      // ----- Feedback de respuestas sugeridas (substrato del bucle de auto-mejora) -----
      // Loguea enviada/editada/ignorada + edit_distance (Levenshtein) + versión del
      // playbook + datos del hilo. El outcome se completa después al cerrar el hilo.
      if (request.method === 'POST' && path === '/admin/suggestion-feedback') {
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const phone = String(body?.phone || '').replace(/\D/g, '');
        if (!phone) return json({ error: 'missing phone' }, 400);
        const suggested = String(body?.suggested_text || '');
        const finalTxt = String(body?.final_text || '');
        const action = ['sent', 'edited', 'ignored'].includes(body?.action) ? body.action : '';
        const ed = (suggested && finalTxt) ? levenshtein(suggested, finalTxt)
                 : (body?.edit_distance != null ? parseInt(body.edit_distance, 10) : null);
        await env.DB.prepare(
          `INSERT INTO suggestion_feedback
             (phone, suggested_text, final_text, action, edit_distance, confidence, framework_version, vertical, objection, outcome, model_used, created_by, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, '', ?, ?, ?)`
        ).bind(
          phone, suggested, finalTxt, action, ed,
          (body?.confidence != null ? +body.confidence : null),
          (body?.framework_version != null ? parseInt(body.framework_version, 10) : null),
          String(body?.vertical || ''), String(body?.objection || ''),
          String(body?.model_used || ''), session.user, new Date().toISOString()
        ).run();
        return json({ ok: true, edit_distance: ed });
      }

      // ----- Copiloto: respuesta sugerida (NO la envía; la muestra para revisar) -----
      if (request.method === 'POST' && path === '/admin/wa/suggest-reply') {
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const num = String(body?.phone || '').replace(/\D/g, '');
        if (!num) return json({ error: 'missing phone' }, 400);
        const res = await suggestReply(env, num, { dry: !!body?.dry, createdBy: session.user });
        if (!res.ok) return json({ error: res.error || 'failed', raw: res.raw }, res.error === 'ANTHROPIC_API_KEY no configurada' ? 503 : 500);
        return json(res);
      }

      // POST /admin/corporeo/ticket → genera un ticket de producción de corpóreo (los datos que
      // pide Sin Frontera), lo numera + guarda en corporeo_tickets, y manda el detalle por WhatsApp
      // al número personal de Gaspar. El front compone el cuerpo (body); acá se numera + envía.
      if (request.method === 'POST' && path === '/admin/corporeo/ticket') {
        let tb; try { tb = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const detalle = String((tb && tb.body) || '').trim();
        if (!detalle) return json({ error: 'ticket vacío' }, 400);
        const cliente = String((tb && tb.cliente) || '').trim();
        // Vínculo con el pedido corpóreo que lo originó (flujo "todo desde el pedido"): permite
        // luego el botón "Ver ticket" en la tabla de Pedidos. fields = campos estructurados en JSON
        // (para re-render/edición); si no vienen, no rompe (queda solo el detalle de texto).
        const pedidoId = parseInt((tb && tb.pedido_id), 10) || null;
        let fieldsJson = null;
        try { if (tb && tb.fields && typeof tb.fields === 'object') fieldsJson = JSON.stringify(tb.fields); } catch (_) {}
        try { await env.DB.prepare('CREATE TABLE IF NOT EXISTS corporeo_tickets (id INTEGER PRIMARY KEY AUTOINCREMENT, numero INTEGER, cliente TEXT, detalle TEXT, created_by TEXT, created_at TEXT)').run(); } catch (_) {}
        try { await env.DB.prepare('ALTER TABLE corporeo_tickets ADD COLUMN pedido_id INTEGER').run(); } catch (_) {}
        try { await env.DB.prepare('ALTER TABLE corporeo_tickets ADD COLUMN data TEXT').run(); } catch (_) {}
        try { await env.DB.prepare('ALTER TABLE corporeo_tickets ADD COLUMN photo_keys TEXT').run(); } catch (_) {}
        // Si ese pedido ya tenía ticket, reusar su número (re-generar / actualizar) en vez de crear otro.
        let numero = null;
        if (pedidoId) {
          try { const prev = await env.DB.prepare('SELECT numero FROM corporeo_tickets WHERE pedido_id=? ORDER BY id DESC LIMIT 1').bind(pedidoId).first(); if (prev && prev.numero) numero = Math.floor(Number(prev.numero)); } catch (_) {}
        }
        if (!numero) {
          const mx = await env.DB.prepare('SELECT MAX(numero) AS m FROM corporeo_tickets').first();
          numero = ((mx && mx.m) ? Math.floor(Number(mx.m)) : 0) + 1;
        }
        const now = new Date().toISOString();
        // RETURNING id para saber la fila y poder guardar las fotos en R2 (reenvío futuro).
        let rowId = null;
        try { const ins = await env.DB.prepare('INSERT INTO corporeo_tickets (numero, cliente, detalle, created_by, created_at, pedido_id, data) VALUES (?,?,?,?,?,?,?) RETURNING id').bind(numero, cliente, detalle, session.user, now, pedidoId, fieldsJson).first(); rowId = ins && ins.id; } catch (_) {}
        const fecha = now.slice(8, 10) + '/' + now.slice(5, 7) + '/' + now.slice(0, 4);
        const to = '5491155604999'; // número personal de Gaspar (pedido explícito)
        const txt = `🎫 TICKET DE PRODUCCIÓN CORPÓREO #${numero}\n${fecha}${cliente ? ' · ' + cliente : ''} · cargó ${session.user}\n\n${detalle}`;
        // Fotos del ticket (base64 desde el front, ya downscaleadas): se decodifican y se GUARDAN en R2
        // (corporeo-ticket/<rowId>/<i>.jpg) ANTES de mandar nada, para poder reenviar el ticket completo si el 1er
        // envío falla por la ventana de 24h de WhatsApp y para que el aviso interno (Etapa 1) las tenga como
        // mediaKeys. Hacia Gaspar sale lo mismo y en el mismo orden que antes: el texto y después las fotos (caption
        // en la 1ª, tope 10).
        const photoKeys = [], fotos = [];
        const photos = Array.isArray(tb.photos) ? tb.photos.slice(0, 10) : [];
        for (let pi = 0; pi < photos.length; pi++) {
          try {
            const b64 = String((photos[pi] && photos[pi].data) || '').trim();
            if (!b64) continue;
            const mime = String((photos[pi] && photos[pi].mime) || 'image/jpeg');
            const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
            if (rowId != null && env.MEDIA) {
              try { const key = `corporeo-ticket/${rowId}/${pi}.jpg`; await env.MEDIA.put(key, bytes, { httpMetadata: { contentType: mime } }); photoKeys.push(key); } catch (_) {}
            }
            fotos.push({ bytes, mime });
          } catch (_) {}
        }
        if (rowId != null && photoKeys.length) { try { await env.DB.prepare('UPDATE corporeo_tickets SET photo_keys=? WHERE id=?').bind(JSON.stringify(photoKeys), rowId).run(); } catch (_) {} }
        const capFotos = `🎫 Fotos ticket #${numero}${cliente ? ' · ' + cliente : ''}`;
        let photos_sent = 0;
        // Lo de hoy (legacy): texto a Gaspar y cada foto subida a WhatsApp desde los bytes.
        const legacy = async () => {
          let r = null;
          try { r = await waSendText(env, to, txt, { esAviso: true }); } catch (_) {}
          if (fotos.length) {
            const _waT = getWaClient(env);
            for (let pi = 0; pi < fotos.length; pi++) {
              try {
                const fd = new FormData();
                fd.append('messaging_product', 'whatsapp');
                fd.append('file', new Blob([fotos[pi].bytes.buffer], { type: fotos[pi].mime }), 'ticket.jpg');
                fd.append('type', fotos[pi].mime);
                const upR = await fetch(_waT.mediaUploadUrl(), { method: 'POST', headers: _waT.headers, body: fd });
                const upJ = await upR.json().catch(() => ({}));
                if (upR.ok && upJ.id) {
                  const sr = await waSendImage(env, to, upJ.id, pi === 0 ? capFotos : undefined, { esAviso: true });
                  if (sr && sr.ok) photos_sent++;
                }
              } catch (_) {}
            }
          }
          return r;
        };
        const av = await avisoAdmin(env, txt, { tipo: 'ticket_corporeo', prioridad: 'P1', to, mediaKeys: photoKeys, mediaCaption: capFotos, legacy });
        const sent = !!(av && av.ok);
        if (av && av.modo === 'on') photos_sent = av.fotos || 0;
        return json({ ok: true, numero, sent, photos_sent });
      }

      // POST /admin/corporeo/ticket/resend { id? , pedido_id? } → reenvía por WhatsApp un ticket ya
      // guardado (texto + fotos desde R2) al número personal de Gaspar. Para cuando el 1er envío
      // falló por la ventana de 24h de WhatsApp y después se reabre.
      if (request.method === 'POST' && path === '/admin/corporeo/ticket/resend') {
        let rb; try { rb = await request.json(); } catch { rb = {}; }
        const rid = parseInt(rb && rb.id, 10) || 0;
        const rpid = parseInt(rb && rb.pedido_id, 10) || 0;
        if (!rid && !rpid) return json({ error: 'falta id o pedido_id' }, 400);
        let tk = null;
        try {
          if (rid) tk = await env.DB.prepare('SELECT id, numero, cliente, detalle, created_by, created_at, photo_keys FROM corporeo_tickets WHERE id=?').bind(rid).first();
          else tk = await env.DB.prepare('SELECT id, numero, cliente, detalle, created_by, created_at, photo_keys FROM corporeo_tickets WHERE pedido_id=? ORDER BY id DESC LIMIT 1').bind(rpid).first();
        } catch (_) {}
        if (!tk) return json({ error: 'ticket no encontrado' }, 404);
        const ca = String(tk.created_at || '');
        const fecha = ca.length >= 10 ? (ca.slice(8, 10) + '/' + ca.slice(5, 7) + '/' + ca.slice(0, 4)) : '';
        const to = '5491155604999';
        const txt = `🎫 TICKET DE PRODUCCIÓN CORPÓREO #${tk.numero} (reenvío)\n${fecha}${tk.cliente ? ' · ' + tk.cliente : ''}${tk.created_by ? ' · cargó ' + tk.created_by : ''}\n\n${tk.detalle}`;
        let sent = false, err = '';
        let photos_sent = 0, keys = [];
        try { if (tk.photo_keys) keys = JSON.parse(tk.photo_keys) || []; } catch (_) {}
        if (!Array.isArray(keys)) keys = [];
        const capFotos = `🎫 Fotos ticket #${tk.numero}${tk.cliente ? ' · ' + tk.cliente : ''}`;
        // Lo de hoy (legacy): texto + las fotos guardadas en R2. [Etapa 1] pasa por avisoAdmin (P1, con las fotos como mediaKeys).
        const legacy = async () => {
          let r = null;
          try { r = await waSendText(env, to, txt, { esAviso: true }); if (!(r && r.ok)) err = JSON.stringify(r || {}).slice(0, 300); } catch (e) { err = String((e && e.message) || e); }
          if (keys.length && env.MEDIA) {
            const _waT = getWaClient(env);
            for (let pi = 0; pi < keys.length && pi < 10; pi++) {
              try {
                const obj = await env.MEDIA.get(keys[pi]);
                if (!obj) continue;
                const ab = await obj.arrayBuffer();
                const mime = (obj.httpMetadata && obj.httpMetadata.contentType) || 'image/jpeg';
                const fd = new FormData();
                fd.append('messaging_product', 'whatsapp');
                fd.append('file', new Blob([ab], { type: mime }), 'ticket.jpg');
                fd.append('type', mime);
                const upR = await fetch(_waT.mediaUploadUrl(), { method: 'POST', headers: _waT.headers, body: fd });
                const upJ = await upR.json().catch(() => ({}));
                if (upR.ok && upJ.id) { const sr = await waSendImage(env, to, upJ.id, pi === 0 ? capFotos : undefined, { esAviso: true }); if (sr && sr.ok) photos_sent++; }
              } catch (_) {}
            }
          }
          return r;
        };
        const av = await avisoAdmin(env, txt, { tipo: 'ticket_corporeo', prioridad: 'P1', to, mediaKeys: keys.slice(0, 10), mediaCaption: capFotos, legacy });
        sent = !!(av && av.ok);
        if (av && av.modo === 'on') { photos_sent = av.fotos || 0; if (!sent) err = String(av.error || 'no salió (ver Admin → Avisos internos)'); }
        return json({ ok: true, sent, numero: tk.numero, photos_sent, photos_stored: keys.length, error: err || undefined });
      }

      // GET /admin/corporeo/tickets → ids de pedidos que YA tienen ticket (para pintar el botón
      // "Ver ticket #N" vs "Armar ticket" en la tabla de Pedidos). Devuelve el último por pedido.
      if (request.method === 'GET' && path === '/admin/corporeo/tickets') {
        let rows = [];
        try {
          const r = await env.DB.prepare('SELECT pedido_id, MAX(numero) AS numero FROM corporeo_tickets WHERE pedido_id IS NOT NULL GROUP BY pedido_id').all();
          rows = (r && r.results) ? r.results : [];
        } catch (_) { rows = []; }
        return json({ ok: true, tickets: rows });
      }

      // GET /admin/corporeo/tickets/all → lista COMPLETA de tickets de producción (panel "Ver tickets").
      // Trae para cada uno: producto + medidas (del JSON `data`) y la 1ª foto (R2 key, para la miniatura).
      if (request.method === 'GET' && path === '/admin/corporeo/tickets/all') {
        let rows = [];
        try {
          const r = await env.DB.prepare('SELECT id, numero, cliente, pedido_id, detalle, data, created_by, created_at, photo_keys FROM corporeo_tickets ORDER BY numero DESC, id DESC').all();
          rows = (r && r.results) ? r.results : [];
        } catch (_) { rows = []; }
        const clean = v => { v = String(v == null ? '' : v).replace(/\s+/g, ' ').trim(); return (!v || v === '—') ? '' : v; };
        const tickets = rows.map(t => {
          let keys = []; try { keys = t.photo_keys ? JSON.parse(t.photo_keys) : []; if (!Array.isArray(keys)) keys = []; } catch (_) { keys = []; }
          let f = {}; try { f = t.data ? JSON.parse(t.data) : {}; } catch (_) { f = {}; }
          const producto = clean(f.tipo_producto) || clean(f.producto);
          const medidas = clean(f.medidas);
          return { id: t.id, numero: t.numero, cliente: t.cliente, pedido_id: t.pedido_id, detalle: t.detalle, producto, medidas, foto: keys[0] || null, fotos: keys.length, created_by: t.created_by, created_at: t.created_at };
        });
        return json({ ok: true, tickets });
      }

      // GET /admin/corporeo/ticket?pedido_id=N → el último ticket de ese pedido (para "Ver ticket").
      if (request.method === 'GET' && path === '/admin/corporeo/ticket') {
        const pid = parseInt(url.searchParams.get('pedido_id'), 10) || 0;
        if (!pid) return json({ error: 'missing pedido_id' }, 400);
        let t = null;
        try { t = await env.DB.prepare('SELECT numero, cliente, detalle, data, created_by, created_at FROM corporeo_tickets WHERE pedido_id=? ORDER BY id DESC LIMIT 1').bind(pid).first(); } catch (_) {}
        if (!t) return json({ ok: true, ticket: null });
        let fields = null; try { if (t.data) fields = JSON.parse(t.data); } catch (_) {}
        return json({ ok: true, ticket: { numero: t.numero, cliente: t.cliente, detalle: t.detalle, fields, created_by: t.created_by, created_at: t.created_at } });
      }

      // ----- Proformas (beta): listar / abrir / guardar. Admin + Joaco + Facundo (Gaspar 17-oct: "habilitale esta función a
      // joaco" / "habilitale también a facundo"). Cada vendedor ve y edita SOLO las suyas (created_by); el admin, todas.
      if (path === '/admin/proformas' || /^\/admin\/proformas\/\d+$/.test(path)) {
        const pfAdmin = (await getSessionRole(env, session.user)) === 'admin';
        if (!pfAdmin && !['joaco', 'facu'].includes(canonWorker(session.user))) return json({ error: 'forbidden' }, 403);
        const pfEsMia = (r) => pfAdmin || (!!r && canonWorker(r.created_by) === canonWorker(session.user));
        if (!(await ensureProformasSchema(env))) return json({ error: 'no se pudo preparar la tabla de proformas' }, 500);
        const pfId = path === '/admin/proformas' ? 0 : parseInt(path.split('/').pop(), 10);
        if (request.method === 'GET' && !pfId) {
          const rs = await env.DB.prepare('SELECT id, numero, cliente, telefono, total, created_by, created_at, updated_at FROM proformas ORDER BY updated_at DESC, id DESC LIMIT ?').bind(pfAdmin ? 40 : 400).all();
          return json({ ok: true, proformas: (rs.results || []).filter(pfEsMia).slice(0, 40) });
        }
        if (request.method === 'GET' && pfId) {
          const r = await env.DB.prepare('SELECT * FROM proformas WHERE id = ?').bind(pfId).first();
          if (!r || !pfEsMia(r)) return json({ error: 'no existe' }, 404);
          let data = null; try { data = JSON.parse(r.data_json || 'null'); } catch (_) {}
          return json({ ok: true, proforma: { id: r.id, numero: r.numero, data, created_by: r.created_by, created_at: r.created_at, updated_at: r.updated_at } });
        }
        if (request.method === 'POST' && !pfId) {
          let body; try { body = await request.json(); } catch { body = {}; }
          const data = (body && typeof body.data === 'object' && body.data) ? body.data : null;
          if (!data) return json({ error: 'faltan los datos de la proforma' }, 400);
          const dataJson = JSON.stringify(data);
          if (dataJson.length > 200000) return json({ error: 'la proforma es demasiado grande' }, 413);
          const cliente = String(data.cliente || '').slice(0, 200);
          const tel = String(data.telefono || '').replace(/\D/g, '').slice(0, 20);
          const total = (Array.isArray(data.items) ? data.items : []).reduce((a, it) => a + (Number(it.cantidad) || 0) * (Number(it.precio) || 0), 0);
          const now = new Date().toISOString();
          const id = parseInt(body.id, 10) || 0;
          if (id) {
            if (!pfEsMia(await env.DB.prepare('SELECT created_by FROM proformas WHERE id = ?').bind(id).first())) return json({ error: 'esa proforma ya no existe' }, 404);
            const r = await env.DB.prepare('UPDATE proformas SET cliente=?, telefono=?, total=?, data_json=?, updated_at=? WHERE id=? RETURNING id, numero').bind(cliente, tel, total, dataJson, now, id).first();
            if (!r) return json({ error: 'esa proforma ya no existe' }, 404);
            return json({ ok: true, id: r.id, numero: r.numero });
          }
          for (let intento = 0; intento < 3; intento++) {
            try {
              const r = await env.DB.prepare('INSERT INTO proformas (numero, cliente, telefono, total, data_json, created_by, created_at, updated_at) SELECT COALESCE(MAX(numero), 0) + 1, ?, ?, ?, ?, ?, ?, ? FROM proformas RETURNING id, numero')
                .bind(cliente, tel, total, dataJson, String(session.user || ''), now, now).first();
              if (r) return json({ ok: true, id: r.id, numero: r.numero });
            } catch (e) { if (!/UNIQUE/i.test(String(e && e.message))) return json({ error: String((e && e.message) || e) }, 500); }
          }
          return json({ error: 'no se pudo numerar la proforma, probá de nuevo' }, 500);
        }
        return json({ error: 'método no soportado' }, 405);
      }

      // ----- Clientes vigilados (botón 🔔 del chat, solo admin) -----
      // GET → {ok, vigilados:[{phone, nombre, desde, by}]}. POST {phone, on, nombre?}: on=true prende el
      // reenvío de cada mensaje del cliente al WhatsApp personal de Gaspar (avisarClienteVigilado), on=false lo apaga.
      if (path === '/admin/vigilar') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'solo admin' }, 403);
        if (request.method === 'GET') {
          const rs = await env.DB.prepare("SELECT k, v FROM kv_cache WHERE k LIKE 'vigilar:%'").all();
          const vigilados = (rs.results || []).map(r => { let c = {}; try { c = JSON.parse(r.v) || {}; } catch (_) {} return { phone: String(r.k).slice(8), nombre: c.nombre || '', desde: c.desde || '', by: c.by || '' }; });
          return json({ ok: true, vigilados });
        }
        if (request.method === 'POST') {
          const body = await request.json().catch(() => ({}));
          const phone = String(body.phone || '').replace(/\D/g, '');
          if (phone.length < 8 || phone.length > 15) return json({ error: 'teléfono inválido' }, 400);
          if (phone === VIGILAR_DESTINO) return json({ error: 'ese es tu número personal' }, 400);
          if (!body.on) {
            await env.DB.prepare("DELETE FROM kv_cache WHERE k = ?").bind('vigilar:' + phone).run();
            return json({ ok: true, on: false });
          }
          let nombre = String(body.nombre || '').trim().slice(0, 80);
          if (!nombre) {
            try { const r = await env.DB.prepare("SELECT sender_name FROM wa_messages WHERE phone = ? AND direction = 'inbound' AND sender_name IS NOT NULL AND sender_name != '' ORDER BY ts DESC LIMIT 1").bind(phone).first(); nombre = String(r?.sender_name || '').trim().slice(0, 80); } catch (_) {}
          }
          await kvSet(env, 'vigilar:' + phone, JSON.stringify({ nombre: nombre || phone, desde: new Date().toISOString(), by: String(session.user || '') }));
          return json({ ok: true, on: true, nombre: nombre || phone });
        }
        return json({ error: 'método no soportado' }, 405);
      }

      // ----- Regulador de consultas (Facu/Agus eligen cuántos leads quieren por día) -----
      // GET: el vendedor secundario recibe SOLO lo suyo; Gaspar recibe {secundarios:[...]}.
      // POST {dia:'hoy'|'manana', cuota} (vendedor: mañana siempre, hoy solo antes de las 12:00 AR, 0..max).
      // POST admin {slug, dia, cuota} fija sin corte y bloquea ese día para el vendedor; {slug, dia, reset:true}
      // vuelve a la cuota por defecto. Joaco y el resto → 403 (Joaco sigue como viene).
      if (path === '/admin/reparto/cuota') {
        const role = await getSessionRole(env, session.user);
        const me = String(session.user || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
        const esAdm = role === 'admin';
        let miSec = null;
        if (!esAdm && role === 'comercial' && VENDEDORES_SECUNDARIOS.includes(me)) {
          // La sesión dura 30 días: confirmar que siga activo como comercial (mismo criterio que chat-import).
          let u = null;
          try { u = await env.DB.prepare("SELECT 1 AS ok FROM users_panel WHERE id = ? AND activo = 1 AND rol = 'comercial'").bind(me).first(); }
          catch (_) { return json({ error: 'base ocupada, probá en un ratito' }, 503); }
          if (u) miSec = COMERCIALES_SECUNDARIOS.find(c => c.slug === me) || null;
        }
        if (!esAdm && !miSec) return json({ error: 'solo para Facu, Agus y Gaspar' }, 403);
        if (request.method === 'GET') {
          if (esAdm) return json({ ok: true, secundarios: await Promise.all(COMERCIALES_SECUNDARIOS.map(c => estadoCuotaVendedor(env, c))) });
          return json({ ok: true, ...(await estadoCuotaVendedor(env, miSec)) });
        }
        if (request.method === 'POST') {
          let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
          const c = esAdm ? COMERCIALES_SECUNDARIOS.find(x => x.slug === String(body?.slug || '').toLowerCase()) : miSec;
          if (!c) return json({ error: 'vendedor inválido' }, 400);
          const f = fechasAR();
          const dia = String(body?.dia || '');
          const fecha = dia === 'hoy' ? f.hoy : dia === 'manana' ? f.manana : '';
          if (!fecha) return json({ error: "dia tiene que ser 'hoy' o 'manana'" }, 400);
          // El front manda además la FECHA que tiene en pantalla: si pasó la medianoche desde que la cargó,
          // 'mañana' ya es otro día → no guardamos y le devolvemos el estado fresco para que elija de nuevo.
          const fCli = String(body?.fecha || '');
          if (fCli && fCli !== fecha) {
            const fresco = esAdm ? { secundarios: await Promise.all(COMERCIALES_SECUNDARIOS.map(x => estadoCuotaVendedor(env, x))) } : await estadoCuotaVendedor(env, c);
            return json({ error: 'Cambió el día desde que abriste la pantalla: te recargué los datos, elegí de nuevo.', ...fresco }, 409);
          }
          const kCuota = 'cuota_dia:' + c.slug + ':' + fecha, kMeta = 'cuota_dia_meta:' + c.slug + ':' + fecha;
          const actual = await cuotaDelDia(env, c, fecha);
          if (esAdm && body?.reset) {
            try { await env.DB.prepare('DELETE FROM kv_cache WHERE k IN (?, ?)').bind(kCuota, kMeta).run(); }
            catch (_) { return json({ error: 'no se pudo guardar, probá de nuevo' }, 503); }
            return json({ ok: true, secundarios: await Promise.all(COMERCIALES_SECUNDARIOS.map(x => estadoCuotaVendedor(env, x))) });
          }
          // Solo enteros (número o string de dígitos): Number(null/''/false) daría 0 y cortaría el reparto.
          const raw = body?.cuota;
          const n = (typeof raw === 'number' || (typeof raw === 'string' && /^\d+$/.test(raw.trim()))) ? Number(raw) : NaN;
          const max = esAdm ? 100 : (c.maxCuota || 30);
          if (!Number.isInteger(n) || n < 0 || n > max) return json({ error: `la cantidad tiene que ser un número entre 0 y ${max}` }, 400);
          if (!esAdm) {
            if (dia === 'hoy' && f.hAR >= 12) return json({ error: 'Después de las 12 la cantidad de hoy ya no se cambia. Podés elegir la de mañana.' }, 409);
            if (actual.origen === 'admin') return json({ error: 'Gaspar fijó tu cantidad para ese día. Hablalo con él si la querés cambiar.' }, 409);
          }
          const cambio = actual.cuota !== n || (esAdm ? actual.origen !== 'admin' : actual.origen === 'default');
          if (cambio) {
            // Cuota y meta en UN batch (transaccional en D1) y sin tragar errores: si falla, 503 y no se avisa.
            const nowIso = new Date().toISOString();
            const up = "INSERT INTO kv_cache (k, v, updated_at) VALUES (?, ?, ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v, updated_at = excluded.updated_at";
            try {
              await env.DB.batch([
                env.DB.prepare(up).bind(kCuota, String(n), nowIso),
                env.DB.prepare(up).bind(kMeta, JSON.stringify({ by: String(session.user || ''), at: nowIso, lock: esAdm ? 1 : 0 }), nowIso),
              ]);
            } catch (_) { return json({ error: 'no se pudo guardar, probá de nuevo' }, 503); }
            // Aviso a Gaspar cuando el VENDEDOR cambia su cantidad (no cuando la cambia él): 1 cada 30 min
            // por vendedor y día (salvo si la pone en 0: eso se avisa siempre), texto libre en segundo plano
            // (si la ventana de 24 h de Gaspar está cerrada no llega; la card de Admin lo muestra igual).
            if (!esAdm && actual.cuota !== n) {
              const kAv = 'cuota_aviso:' + c.slug + ':' + fecha;
              const ult = parseInt(await kvGet(env, kAv, '0'), 10) || 0;
              if (n === 0 || Date.now() - ult > 30 * 60 * 1000) {
                await kvSet(env, kAv, String(Date.now()));
                const fd = fecha.slice(8, 10) + '/' + fecha.slice(5, 7);
                ctx.waitUntil(precotizNotifyGaspar(env, `${c.nombre} eligió ${n} consulta${n === 1 ? '' : 's'} para ${dia === 'hoy' ? 'hoy' : 'mañana'} (${fd}). Antes: ${actual.cuota}.`,
                  // Decisión 1 de §6: las cuotas van al resumen (P3), salvo cuando eligen 0 (P2: alguien deja de recibir).
                  { tipo: 'cuotas', prioridad: n === 0 ? 'P2' : 'P3' }).catch(() => {}));
              }
            }
          }
          if (esAdm) return json({ ok: true, secundarios: await Promise.all(COMERCIALES_SECUNDARIOS.map(x => estadoCuotaVendedor(env, x))) });
          return json({ ok: true, ...(await estadoCuotaVendedor(env, c)) });
        }
        return json({ error: 'método no soportado' }, 405);
      }

      // ----- Piloto de pre cotización (solo Gaspar): estado, control, dry-run, aprobar -----
      if (path.startsWith('/admin/precotiz')) {
        // Frenar/reanudar el bot en un chat (freeze/frozen) lo puede usar cualquier usuario del
        // CRM (Joaco/comercial), no solo Gaspar. El resto del piloto sigue siendo solo-admin.
        const _precotizAnyUser = (path === '/admin/precotiz/freeze' || path === '/admin/precotiz/frozen');
        // El GET del estado del piloto lo puede leer también el comercial (Joaco/Facu): lo usa el
        // chat para mostrar el cartel de "Freno precotización" y el estado de datos. Las acciones
        // (approve/discard/on-off/cap) siguen siendo solo-admin.
        let _precotizComercialGet = false;
        if (!isAdminSession && request.method === 'GET' && path === '/admin/precotiz') {
          try { _precotizComercialGet = (await getSessionRole(env, session.user)) === 'comercial'; } catch (_) {}
        }
        if (!isAdminSession && !_precotizAnyUser && !_precotizComercialGet) return json({ error: 'forbidden: admin only' }, 403);

        // GET /admin/precotiz → on/off + modo + leads del piloto
        if (request.method === 'GET' && path === '/admin/precotiz') {
          const on = (await kvGet(env, 'precotiz_on', '0')) === '1';
          const modo = await kvGet(env, 'precotiz_modo', 'draft');
          const cap = parseInt(await kvGet(env, 'precotiz_cap', String(PRECOTIZ_CAP)), 10) || PRECOTIZ_CAP;
          const sample = parseInt(await kvGet(env, 'precotiz_sample', '20'), 10) || 20;
          let leads = [];
          try { const rs = await env.DB.prepare('SELECT * FROM precotiz_pilot ORDER BY updated_at DESC').all(); leads = rs.results || []; } catch (_) {}
          let frozen = [];
          // El rango sobre k (';' es el carácter siguiente a ':') usa la PK; el LIKE solo escaneaba todo kv_cache.
          try { const fr = await env.DB.prepare("SELECT substr(k, 17) AS phone FROM kv_cache WHERE k >= 'precotiz_frozen:' AND k < 'precotiz_frozen;' AND k LIKE 'precotiz_frozen:%' AND v = '1'").all(); frozen = (fr.results || []).map(r => r.phone); } catch (_) {}
          // Reparto a los vendedores SECUNDARIOS: cuota diaria por cada uno + cuántos se le asignaron
          // hoy (día AR) + su teléfono de aviso. secundarios[] alimenta la UI; nadia_* quedan por
          // compatibilidad (= el primer secundario, Facu).
          const secundarios = [];
          for (const c of COMERCIALES_SECUNDARIOS) {
            const cu = parseInt(await kvGet(env, c.cuotaKv, '0'), 10) || 0;
            let hoy = 0;
            try { const nr = await env.DB.prepare("SELECT COUNT(*) AS n FROM wa_chats_summary WHERE assigned_to = ? AND assigned_at >= (date('now','-3 hours') || 'T03:00:00Z') AND NOT EXISTS (SELECT 1 FROM chat_assign_log l WHERE l.phone = wa_chats_summary.phone AND l.via IN ('import', 'no_neon', 'no_neon_auto') AND l.ts = wa_chats_summary.assigned_at)").bind(c.slug).first(); hoy = (nr && nr.n) || 0; } catch (_) {}   // sin los traídos a mano
            const ph = await kvGet(env, c.phoneKv, '');
            // cuota = la POR DEFECTO (alimenta el input); cuota_hoy = la que de verdad corta hoy (regulador).
            const ef = await cuotaDelDia(env, c, fechasAR().hoy);
            secundarios.push({ slug: c.slug, nombre: c.nombre, cuota: cu, cuota_hoy: ef.cuota, origen_hoy: ef.origen, hoy, phone: ph });
          }
          const _facu = secundarios.find(x => x.slug === 'facundo') || { cuota: 0, hoy: 0, phone: '' };
          return json({ ok: true, on, modo, cap, sample, count: leads.length, leads, frozen, secundarios, nadia_cuota: _facu.cuota, nadia_hoy: _facu.hoy, nadia_phone: _facu.phone });
        }

        // GET /admin/precotiz/evaluaciones → veredictos de la IA (por qué entró/no entró cada lead).
        // ?phone=549... filtra por lead | ?resultado=rechazo|error_ia|entro | ?limit=N (máx 300)
        if (request.method === 'GET' && path === '/admin/precotiz/evaluaciones') {
          const u = new URL(request.url);
          const qPhone = (u.searchParams.get('phone') || '').replace(/\D/g, '');
          const qRes = u.searchParams.get('resultado') || '';
          const lim = Math.min(parseInt(u.searchParams.get('limit') || '50', 10) || 50, 300);
          let sql = "SELECT phone, resultado, motivo, es_carteles, frenar, tiene_foto, tiene_medidas, tiene_intext, ts FROM precotiz_eval_log";
          const conds = [], binds = [];
          if (qPhone) { conds.push('phone = ?'); binds.push(qPhone); }
          if (qRes) { conds.push('resultado = ?'); binds.push(qRes); }
          if (conds.length) sql += ' WHERE ' + conds.join(' AND ');
          sql += ' ORDER BY ts DESC LIMIT ?'; binds.push(lim);
          let rows = [];
          try { const rs = await env.DB.prepare(sql).bind(...binds).all(); rows = rs.results || []; } catch (_) {}
          return json({ ok: true, count: rows.length, evaluaciones: rows });
        }

        // POST /admin/precotiz/freeze → { phone, on } FRENO DE MANO manual por chat (el bot no vuelve a hablar ahí)
        if (request.method === 'POST' && path === '/admin/precotiz/freeze') {
          let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
          const num = String(body?.phone || '').replace(/\D/g, '');
          if (!num) return json({ error: 'missing phone' }, 400);
          const on = body?.on !== false; // default true (frenar)
          await kvSet(env, 'precotiz_frozen:' + num, on ? '1' : '0');
          await botFrenadoTag(env, num, on);
          return json({ ok: true, phone: num, frozen: on });
        }

        // GET /admin/precotiz/frozen → teléfonos con el bot frenado a mano
        if (request.method === 'GET' && path === '/admin/precotiz/frozen') {
          let phones = [];
          try { const rs = await env.DB.prepare("SELECT substr(k, 17) AS phone FROM kv_cache WHERE k >= 'precotiz_frozen:' AND k < 'precotiz_frozen;' AND k LIKE 'precotiz_frozen:%' AND v = '1'").all(); phones = (rs.results || []).map(r => r.phone); } catch (_) {}
          return json({ ok: true, frozen: phones });
        }

        // POST /admin/precotiz/control → { on?, modo? } prender/apagar + draft|auto
        if (request.method === 'POST' && path === '/admin/precotiz/control') {
          let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
          if (typeof body?.on === 'boolean') await kvSet(env, 'precotiz_on', body.on ? '1' : '0');
          if (body?.modo === 'auto' || body?.modo === 'draft') await kvSet(env, 'precotiz_modo', body.modo);
          // Reparto: cuota diaria (0 = nada) + teléfono de aviso, por vendedor secundario.
          // Genérico: body.reparto = { slug: { cuota?, phone? } }. Legacy: nadia_cuota/nadia_phone = Facu.
          if (body?.reparto && typeof body.reparto === 'object') {
            for (const c of COMERCIALES_SECUNDARIOS) {
              const rr = body.reparto[c.slug]; if (!rr || typeof rr !== 'object') continue;
              if (rr.cuota !== undefined) { const q = Math.max(0, parseInt(rr.cuota, 10) || 0); await kvSet(env, c.cuotaKv, String(q)); }
              if (rr.phone !== undefined) { await kvSet(env, c.phoneKv, String(rr.phone || '').replace(/\D/g, '')); }
            }
          }
          if (body?.nadia_cuota !== undefined) { const q = Math.max(0, parseInt(body.nadia_cuota, 10) || 0); await kvSet(env, 'nadia_cuota_diaria', String(q)); }
          if (body?.nadia_phone !== undefined) { await kvSet(env, 'nadia_phone', String(body.nadia_phone || '').replace(/\D/g, '')); }
          return json({ ok: true, on: (await kvGet(env, 'precotiz_on', '0')) === '1', modo: await kvGet(env, 'precotiz_modo', 'draft'), nadia_cuota: parseInt(await kvGet(env, 'nadia_cuota_diaria', '0'), 10) || 0, nadia_phone: await kvGet(env, 'nadia_phone', '') });
        }

        // POST /admin/precotiz/corporeo-backfill → etiqueta a los leads que YA entraron por ads mapeados
        // a vertical 'corporeo' (wa_ad_verticals) y los saca del bot de precotización si cayeron.
        // Idempotente; se re-corre al agregar ads corpóreos nuevos al mapa.
        if (request.method === 'POST' && path === '/admin/precotiz/corporeo-backfill') {
          let n = 0, escal = 0;
          try {
            const rs = await env.DB.prepare(
              "SELECT DISTINCT a.phone AS phone FROM wa_ad_attributions a JOIN wa_ad_verticals v ON v.ad_id = a.source_id WHERE v.vertical = 'corporeo' AND a.phone IS NOT NULL AND a.phone != ''"
            ).all();
            for (const r of (rs.results || [])) {
              const ph = r.phone;
              await corporeoTag(env, ph, true); n++;
              try {
                const inb = await env.DB.prepare("SELECT 1 AS x FROM precotiz_pilot WHERE phone = ? AND estado IN ('activo','completo') LIMIT 1").bind(ph).first();
                if (inb) {
                  await env.DB.prepare("UPDATE precotiz_pilot SET estado='escalado', escalado_motivo='corporeo', updated_at=? WHERE phone=? AND estado IN ('activo','completo')").bind(new Date().toISOString(), ph).run();
                  await precotizTag(env, ph, false);
                  await paraCotizarTag(env, ph, false);
                  escal++;
                }
              } catch (_) {}
            }
          } catch (e) { return json({ error: String(e?.message || e) }, 500); }
          return json({ ok: true, etiquetados: n, sacados_del_bot: escal });
        }

        // POST /admin/precotiz/dry-run → { phone } qué decidiría el motor, SIN enviar
        if (request.method === 'POST' && path === '/admin/precotiz/dry-run') {
          let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
          const num = String(body?.phone || '').replace(/\D/g, '');
          // { text } = conversación de PRUEBA (líneas "ts CLIENTE: ..." / "ts JOACO: ...") para testear el
          // prompt sin un chat real. Nunca manda nada; también devuelve qué harían el candado de medidas
          // y la espera de la pregunta de techo/fecha.
          const testText = String(body?.text || '').trim();
          if (!num && !testText) return json({ error: 'missing phone o text' }, 400);
          let fullText, imgs = [];
          if (testText) {
            fullText = `## CONVERSACIÓN\nCliente: prueba\n${body.header ? String(body.header) + '\n' : 'ORIGEN: sin atribución registrada\n'}\n${testText}`;
          } else {
            const ctx = await buildChatContext(env, num, 40);
            if (!ctx) return json({ error: 'sin mensajes para ese phone' }, 404);
            fullText = ctx.fullText;
            imgs = await precotizImageBlocks(env, num);
          }
          const fw = await getActiveFramework(env);
          let _guardado = '';
          if (num) { try { const _p = await env.DB.prepare("SELECT producto FROM precotiz_pilot WHERE phone = ?").bind(num).first(); _guardado = (_p && _p.producto) || ''; } catch (_) {} }
          const esCorp = await precotizEsCorporeo(env, num, fullText, _guardado);
          const out = await precotizLlm(env, (esCorp ? PRECOTIZ_CORP_NOTE : '') + fullText, fw?.content || '', imgs, { phone: num || 'prueba', by: 'dry-run' });
          const esCorpTurno = precotizCorpTurno(esCorp, out.data);
          if (out.data && esCorpTurno) precotizAjusteCorporeo(out.data);
          const _msgs = precotizMsgs(out.data);
          return json({ ok: out.ok, phone: num || null, es_corporeo: esCorpTurno, result: out.data || null, candado: out.data ? (precotizMedidaInventada(_msgs, fullText) || null) : null, espera_pregunta: out.data ? precotizFaltaPregunta(out.data, _msgs) : null, error: out.error || null, status: out.status || null, raw: out.raw || null });
        }

        // POST /admin/precotiz/approve → { phone, mensajes? } envía los mensajitos (editados o del borrador)
        if (request.method === 'POST' && path === '/admin/precotiz/approve') {
          let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
          const num = String(body?.phone || '').replace(/\D/g, '');
          if (!num) return json({ error: 'missing phone' }, 400);
          const lead = await precotizGet(env, num);
          if (!lead) return json({ error: 'lead no encontrado' }, 404);
          let msgs = Array.isArray(body?.mensajes) ? body.mensajes : null;
          if (!msgs && lead.pending_draft) { try { msgs = JSON.parse(lead.pending_draft); } catch (_) { msgs = null; } }
          msgs = (msgs || []).filter(m => typeof m === 'string' && m.trim()).slice(0, 5);
          if (!msgs.length) return json({ error: 'no hay mensajes para enviar' }, 400);
          for (const m of msgs) { await precotizSend(env, num, m); await new Promise(r => setTimeout(r, 900)); }
          const nowIso = new Date().toISOString();
          let lastInTs = '';
          try { const li = await env.DB.prepare("SELECT MAX(ts) AS t FROM wa_messages WHERE phone = ? AND direction = 'inbound' AND msg_type != 'status'").bind(num).first(); lastInTs = li?.t || ''; } catch (_) {}
          try { await env.DB.prepare("UPDATE precotiz_pilot SET pending_draft = '', draft_ts = '', msgs_bot = msgs_bot + 1, last_processed_ts = ?, updated_at = ? WHERE phone = ?").bind(lastInTs || nowIso, nowIso, num).run(); } catch (_) {}
          return json({ ok: true, sent: msgs.length });
        }

        // POST /admin/precotiz/discard → { phone } descarta el borrador sin enviar
        if (request.method === 'POST' && path === '/admin/precotiz/discard') {
          let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
          const num = String(body?.phone || '').replace(/\D/g, '');
          if (!num) return json({ error: 'missing phone' }, 400);
          const nowIso = new Date().toISOString();
          let lastInTs = '';
          try { const li = await env.DB.prepare("SELECT MAX(ts) AS t FROM wa_messages WHERE phone = ? AND direction = 'inbound' AND msg_type != 'status'").bind(num).first(); lastInTs = li?.t || ''; } catch (_) {}
          try { await env.DB.prepare("UPDATE precotiz_pilot SET pending_draft = '', draft_ts = '', last_processed_ts = ?, updated_at = ? WHERE phone = ?").bind(lastInTs || nowIso, nowIso, num).run(); } catch (_) {}
          return json({ ok: true });
        }

        return json({ error: 'not found' }, 404);
      }

      // GET /admin/minicurso-landing → estado + leads del flujo de la landing del minicurso
      if (request.method === 'GET' && path === '/admin/minicurso-landing') {
        const on = (await kvGet(env, 'minicurso_landing_on', '0')) === '1';
        let leads = [];
        try { const rs = await env.DB.prepare('SELECT * FROM minicurso_landing ORDER BY updated_at DESC LIMIT 300').all(); leads = rs.results || []; } catch (_) {}
        const by_stage = {};
        for (const l of leads) by_stage[l.stage] = (by_stage[l.stage] || 0) + 1;
        return json({ ok: true, on, count: leads.length, by_stage, leads });
      }
      // POST /admin/minicurso-landing/control → { on? } prender/apagar (kill-switch)
      if (request.method === 'POST' && path === '/admin/minicurso-landing/control') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        if (typeof body?.on === 'boolean') await kvSet(env, 'minicurso_landing_on', body.on ? '1' : '0');
        return json({ ok: true, on: (await kvGet(env, 'minicurso_landing_on', '0')) === '1' });
      }
      // POST /admin/minicurso-landing/test → { phone, nombre, now? } registra un lead
      // de prueba. Con now:true el opener sale en el próximo tick (probar sin esperar 45min).
      if (request.method === 'POST' && path === '/admin/minicurso-landing/test') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const num = normalizeArPhone(String(body?.phone || '')) || '';
        if (!num) return json({ error: 'missing/invalid phone' }, 400);
        const nombre = (String(body?.nombre || body?.firstName || '').trim().split(/\s+/)[0]) || '';
        const now = new Date().toISOString();
        const due = body?.now ? now : new Date(Date.now() + MINICURSO_LANDING_DELAY_MS).toISOString();
        try {
          await env.DB.prepare(
            "INSERT INTO minicurso_landing (phone, nombre, stage, registered_at, opener_due_at, source, updated_at, created_at) VALUES (?, ?, 'registered', ?, ?, 'test', ?, ?) ON CONFLICT(phone) DO UPDATE SET stage='registered', nombre=excluded.nombre, opener_due_at=excluded.opener_due_at, opener_sent_at=NULL, reply_due=NULL, followup_sent_at=NULL, followup_due_at=NULL, guard_reason='', vio_clase2=0, updated_at=excluded.updated_at"
          ).bind(num, nombre, now, due, now, now).run();
        } catch (e) { return json({ error: String(e?.message || e) }, 500); }
        return json({ ok: true, phone: num, nombre, opener_due_at: due });
      }

      // GET /admin/reventa → estado + leads del flujo de reventa B2B
      if (request.method === 'GET' && path === '/admin/reventa') {
        const on = (await kvGet(env, 'reventa_on', '0')) === '1';
        let leads = [];
        try { const rs = await env.DB.prepare('SELECT * FROM reventa_leads ORDER BY created_at DESC LIMIT 300').all(); leads = rs.results || []; } catch (_) {}
        const cual = leads.filter(l => l.cualificado).length;
        return json({ ok: true, on, count: leads.length, cualificados: cual, no_cualificados: leads.length - cual, leads });
      }
      // POST /admin/reventa/control → { on? } (kill-switch)
      if (request.method === 'POST' && path === '/admin/reventa/control') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        if (typeof body?.on === 'boolean') await kvSet(env, 'reventa_on', body.on ? '1' : '0');
        return json({ ok: true, on: (await kvGet(env, 'reventa_on', '0')) === '1' });
      }
      // POST /admin/reventa/test → simula un lead { phone, nombre, p1, p2, p3, id? }
      if (request.method === 'POST' && path === '/admin/reventa/test') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const row = { id: body.id || ('test-' + String(body.phone || '').replace(/\D/g, '')), phone: body.phone || '', full_name: body.nombre || '', 'tenes experiencia en venta de productos': body.p1 || '', 'tenes clientes para venderles': body.p2 || '', 'te dedicas a alguno de estos rubros': body.p3 || '' };
        await processReventaLead(env, { row_data: row });
        const lead = await env.DB.prepare('SELECT lead_id, phone, nombre, cualificado, template_status FROM reventa_leads WHERE lead_id = ?').bind(row.id).first();
        return json({ ok: true, lead });
      }

      // POST /admin/capi/test → { phone?, leadId?, event? } manda un evento de prueba a la CAPI de Meta
      if (request.method === 'POST' && path === '/admin/capi/test') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const out = await sendCapiEvent(env, { leadId: body.leadId || '', phone: body.phone || '', email: body.email || '', eventName: body.event || 'Lead', ref: 'admin-test' });
        return json(out);
      }

      // ----- Copiloto: contador de gasto IA (solo Gaspar) -----
      // ----- Gasto de Gemini: renders + estimación de medidas (solo Gaspar) -----
      // Diagnóstico: prueba un modelo de imagen de Gemini directo y devuelve status/tiempo/error REAL.
      if (request.method === 'GET' && path === '/admin/gemini/test') {
        if (!isAdminSession) return json({ error: 'forbidden: admin only' }, 403);
        if (!env.GEMINI_API_KEY) return json({ error: 'sin GEMINI_API_KEY' }, 500);
        const model = url.searchParams.get('model') || geminiImageModel(env);
        const _stream = url.searchParams.get('stream') === '1';
        const gurl = `https://generativelanguage.googleapis.com/v1beta/models/${model}:${_stream ? 'streamGenerateContent?alt=sse&' : 'generateContent?'}key=${env.GEMINI_API_KEY}`;
        // Con ?render_key=<r2key> replica la CARGA real del render (prompt de render + imagen);
        // sin él, un test liviano de solo texto.
        let _parts = [{ text: 'Genera una imagen simple de un cartel de neon que diga TEST sobre fondo negro.' }];
        let _inBytes = 0, _outBytes = 0, _rzErr = null;
        const _rk = url.searchParams.get('render_key') || '';
        const _rw = parseInt(url.searchParams.get('resize') || '0', 10);
        if (_rk && env.MEDIA) {
          try {
            const _o = await env.MEDIA.get(_rk);
            if (_o) {
              let _b = await _o.arrayBuffer(); let _m = _o.httpMetadata?.contentType || 'image/png'; _inBytes = _b.byteLength;
              if (_rw > 0 && env.IMAGES) {
                try { const _res = await env.IMAGES.input(new Response(_b).body).transform({ width: _rw }).output({ format: 'image/jpeg', quality: 82 }); _b = await _res.response().arrayBuffer(); _m = 'image/jpeg'; } catch (e) { _rzErr = String((e && e.message) || e); }
              }
              _outBytes = _b.byteLength;
              _parts = [{ text: GEMINI_RENDER_PROMPT }, { inline_data: { mime_type: _m, data: abToBase64(_b) } }];
            }
          } catch (_) {}
        }
        const gbody = { contents: [{ parts: _parts }], generationConfig: { responseModalities: ['IMAGE', 'TEXT'] } };
        const t0 = Date.now();
        let resp, raw = '';
        try { resp = await fetch(gurl, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(gbody) }); raw = await resp.text(); }
        catch (e) { return json({ model, stream: _stream, fetch_error: String((e && e.message) || e), ms: Date.now() - t0 }); }
        const ms = Date.now() - t0;
        let hasImg = false, gErr = null;
        if (_stream) {
          for (const line of raw.split('\n')) { if (line.startsWith('data:')) { try { const ev = JSON.parse(line.slice(5).trim()); if ((ev?.candidates?.[0]?.content?.parts || []).find(p => p.inlineData || p.inline_data)) hasImg = true; if (ev?.error) gErr = ev.error; } catch (_) {} } }
        } else {
          let parsed = null; try { parsed = JSON.parse(raw); } catch (_) {}
          hasImg = !!(parsed?.candidates?.[0]?.content?.parts || []).find(p => p.inlineData || p.inline_data);
          gErr = parsed?.error || null;
        }
        return json({ model, stream: _stream, in_bytes: _inBytes, out_bytes: _outBytes, rz_err: _rzErr, status: resp.status, ok: resp.ok, ms, has_image: hasImg, gemini_error: gErr, raw_snippet: hasImg ? '(imagen ok)' : raw.slice(0, 300) });
      }
      if (request.method === 'GET' && path === '/admin/gemini/usage') {
        if (!isAdminSession) return json({ error: 'forbidden: admin only' }, 403);
        const ms = new Date(); ms.setUTCDate(1); ms.setUTCHours(0, 0, 0, 0); const m = ms.toISOString();
        const ds = new Date(); ds.setUTCHours(0, 0, 0, 0); const d = ds.toISOString();
        const agg = async (where, ...b) => {
          const r = await env.DB.prepare(`SELECT COUNT(*) AS n, ROUND(SUM(cost_usd), 4) AS cost FROM gemini_usage WHERE 1=1 ${where}`).bind(...b).first();
          return { n: r?.n || 0, cost: r?.cost || 0 };
        };
        const today = await agg(' AND ts >= ?', d);
        const month = await agg(' AND ts >= ?', m);
        const monthRender = await agg(" AND kind='render' AND ts >= ?", m);
        const total = await agg('');
        const byModel = (await env.DB.prepare("SELECT model, kind, COUNT(*) AS n, ROUND(SUM(cost_usd), 4) AS cost FROM gemini_usage WHERE ts >= ? GROUP BY model, kind ORDER BY cost DESC").bind(m).all()).results || [];
        const avgRender = monthRender.n ? +(monthRender.cost / monthRender.n).toFixed(4) : 0;
        return json({
          ok: true,
          today: { count: today.n, cost_usd: today.cost },
          month: { count: month.n, cost_usd: month.cost, renders: monthRender.n, avg_render_usd: avgRender },
          total: { count: total.n, cost_usd: total.cost },
          by_model: byModel
        });
      }

      // ----- Copiloto: contador de gasto IA (solo Gaspar) -----
      if (request.method === 'GET' && path === '/admin/copilot/usage') {
        if (!isAdminSession) return json({ error: 'forbidden: admin only' }, 403);
        const ms = new Date(); ms.setUTCDate(1); ms.setUTCHours(0, 0, 0, 0); const m = ms.toISOString();
        const ds = new Date(); ds.setUTCHours(0, 0, 0, 0); const d = ds.toISOString();
        const usage = async (cond, ...b) => await env.DB.prepare(
          `SELECT COUNT(*) AS n, ROUND(SUM(cost_usd), 4) AS cost FROM copilot_usage WHERE kind = 'suggest'${cond}`
        ).bind(...b).first();
        const fb = async (cond, ...b) => {
          const rows = (await env.DB.prepare(
            `SELECT action, COUNT(*) AS n FROM suggestion_feedback${cond} GROUP BY action`
          ).bind(...b).all()).results || [];
          const o = { sent: 0, edited: 0, ignored: 0 };
          rows.forEach(r => { if (o[r.action] != null) o[r.action] = r.n; });
          return o;
        };
        const uD = await usage(' AND created_at >= ?', d);
        const uM = await usage(' AND created_at >= ?', m);
        const uT = await usage('');
        const fM = await fb(' WHERE created_at >= ?', m);
        const fT = await fb('');
        const edT = await env.DB.prepare(`SELECT ROUND(AVG(edit_distance), 1) AS a FROM suggestion_feedback WHERE action = 'edited' AND edit_distance IS NOT NULL`).first();
        return json({
          ok: true,
          today: { count: uD?.n || 0, cost_usd: uD?.cost || 0 },
          month: { count: uM?.n || 0, cost_usd: uM?.cost || 0, generated: uM?.n || 0, sent: fM.sent, edited: fM.edited, ignored: fM.ignored },
          total: { count: uT?.n || 0, cost_usd: uT?.cost || 0, generated: uT?.n || 0, sent: fT.sent, edited: fT.edited, ignored: fT.ignored, avg_edit_distance: edT?.a || 0 }
        });
      }

      // ----- Panel de costos del sitio -----
      if (request.method === 'GET' && path === '/admin/costs') {
        if (!isAdminSession) return json({ error: 'forbidden: admin only' }, 403);
        await ensureCostsSchema(env);
        const services = (await env.DB.prepare('SELECT * FROM site_services WHERE active = 1 ORDER BY sort_order, id').all()).results || [];
        const anth = await computeAnthropicMonthCost(env);
        const rate = await getUsdArsRate(env);
        const ms = new Date(); ms.setUTCDate(1); ms.setUTCHours(0, 0, 0, 0); const m = ms.toISOString();
        let waOut = 0, waConv = 0;
        try { waOut = (await env.DB.prepare(`SELECT COUNT(*) AS n FROM wa_messages WHERE direction='outbound' AND ts >= ?`).bind(m).first())?.n || 0; } catch (_) {}
        try { waConv = (await env.DB.prepare(`SELECT COUNT(DISTINCT phone) AS n FROM wa_messages WHERE direction='outbound' AND ts >= ?`).bind(m).first())?.n || 0; } catch (_) {}
        const toUsd = (amt, cur) => {
          if (!amt) return 0;
          if (cur === 'ARS') return rate ? +(amt / rate).toFixed(2) : null; // null = falta el tipo de cambio
          if (cur === 'EUR') return +(amt * 1.08).toFixed(2);
          return amt; // USD
        };
        let infraUsd = 0, adsUsd = 0, infraIncomplete = false, adsIncomplete = false;
        const enriched = services.map(s => {
          let usd;
          if (s.cost_type === 'auto' && s.auto_key === 'anthropic') usd = anth.total;
          else if (s.cost_type === 'free') usd = 0;
          else usd = toUsd(s.cost_amount, s.cost_currency);
          const row = { ...s, monthly_usd: usd };
          if (s.cost_type === 'auto' && s.auto_key === 'anthropic') row.anthropic = anth;
          if (s.category === 'ads') { if (usd == null) adsIncomplete = true; else adsUsd += usd; }
          else { if (usd == null) infraIncomplete = true; else infraUsd += usd; }
          return row;
        });
        return json({
          ok: true,
          services: enriched,
          anthropic: anth,
          fx_usd_ars: rate,
          totals: { infra_usd: +infraUsd.toFixed(2), ads_usd: +adsUsd.toFixed(2), infra_incomplete: infraIncomplete, ads_incomplete: adsIncomplete },
          usage: { wa_outbound_msgs: waOut, wa_conversations: waConv },
          provider: {
            wa_provider: env.WA_PROVIDER || 'meta',
            has_d360_key: !!env.D360_API_KEY,
            has_wa_token: !!env.WA_TOKEN,
            has_anthropic_key: !!env.ANTHROPIC_API_KEY,
            wa_billing_blocked: await isWaBillingBlocked(env)
          }
        });
      }
      // Inventario de automatizaciones de WhatsApp (Fase 1: read-only). Lista
      // TODAS las automatizaciones (broadcasts, disparadores por mensaje, crons)
      // con su estado real y stats en vivo derivadas de la base. Solo admin.
      if (request.method === 'GET' && path === '/admin/automations') {
        if (!isAdminSession) return json({ error: 'forbidden: admin only' }, 403);
        // Stats de colas/broadcasts en una sola query (kind x status).
        const qRows = (await env.DB.prepare("SELECT kind, status, COUNT(*) AS n FROM wa_autoreply_log GROUP BY kind, status").all()).results || [];
        const byKind = {};
        for (const r of qRows) { (byKind[r.kind] = byKind[r.kind] || {})[r.status] = r.n; }
        // Stats de campañas (respondieron / positivas) por campaña.
        const camp = {};
        try {
          const cr = (await env.DB.prepare("SELECT campaign, COUNT(*) AS total, SUM(CASE WHEN responded_at IS NOT NULL THEN 1 ELSE 0 END) AS responded, SUM(CASE WHEN sentiment='positiva' THEN 1 ELSE 0 END) AS positiva FROM wa_cursos_campaign GROUP BY campaign").all()).results || [];
          for (const r of cr) camp[r.campaign] = r;
        } catch (_) {}
        let cursosInbox = 0;
        try { cursosInbox = (await env.DB.prepare("SELECT COUNT(*) AS n FROM wa_chats_summary WHERE inbox='cursos'").first())?.n || 0; } catch (_) {}
        const billingBlocked = await isWaBillingBlocked(env);
        // Stats del flujo Lead Ads B2B -> auto-WhatsApp (tabla wa_leads).
        let leadsTotal = 0, leadsSent = 0;
        try {
          const lr = await env.DB.prepare("SELECT COUNT(*) AS total, SUM(CASE WHEN template_status='sent' THEN 1 ELSE 0 END) AS sent FROM wa_leads").first();
          leadsTotal = lr?.total || 0; leadsSent = lr?.sent || 0;
        } catch (_) {}
        let cfOn = false, cfTotal = 0, cfActivos = 0;
        try { cfOn = (await env.DB.prepare("SELECT v FROM kv_cache WHERE k='cursos_flow_on'").first())?.v === '1'; } catch (_) {}
        try { const cr = await env.DB.prepare("SELECT COUNT(*) AS total, SUM(CASE WHEN stage NOT IN ('done','stopped') THEN 1 ELSE 0 END) AS activos FROM wa_cursos_flow").first(); cfTotal = cr?.total || 0; cfActivos = cr?.activos || 0; } catch (_) {}
        // Estado de un broadcast segun su cola: en curso si quedan encolados,
        // completado si ya mando algo, inactivo si nunca tuvo data.
        const bcState = (k) => (byKind[k]?.queued ? 'en_curso' : (byKind[k]?.sent ? 'completado' : 'inactivo'));
        const automations = [
          { id:'cupo_broadcast', group:'Broadcasts', name:'Cupo Comunidad (1 cupo)', desc:'Plantilla cupo_comunidad_junio a leads del form de junio, con goteo.', trigger:'Manual / encolado', state: bcState('cupo_broadcast'), stats: byKind.cupo_broadcast || {} },
          { id:'junio_broadcast', group:'Broadcasts', name:'Lanzamiento Junio', desc:'Plantilla lanzamiento_junio_2026 a leads del 9-10 jun, con goteo.', trigger:'Manual / encolado', state: bcState('junio_broadcast'), stats: byKind.junio_broadcast || {} },
          { id:'cursos_broadcast', group:'Broadcasts', name:'Cursos Mayo', desc:'Plantilla cursos_clases_vivo_mayo, con goteo.', trigger:'Manual / encolado', state: bcState('cursos_broadcast'), stats: byKind.cursos_broadcast || {} },
          { id:'neon_mastery', group:'Disparadores por mensaje', name:'Ruteo "Neon Mastery"', desc:'Quien escribe "acceder a Neon Mastery" pasa a la bandeja de Abril (cursos). No responde nada.', trigger:'Texto contiene "acceder a neon mastery"', state:'active', stats:{} },
          { id:'minicurso', group:'Disparadores por mensaje', name:'Auto-reply Minicurso', desc:'Quien pide cotizador + guia + curso recibe el link del minicurso (1 vez por contacto).', trigger:'Texto: cotizador + guia + curso', state: billingBlocked ? 'pausado' : 'active', stats:{ enviados: byKind.minicurso?.sent || 0, en_cola: byKind.minicurso?.queued || 0 } },
          { id:'cursos_reveal', group:'Disparadores por mensaje', name:'Respuesta a campana de cursos', desc:'Si un lead de campana responde, la IA evalua, manda el evento si es positiva y revela el chat a Abril.', trigger:'Inbound de lead de campana', state:'active', stats:{ respondieron: (camp.junio?.responded||0)+(camp.mayo?.responded||0), positivas: (camp.junio?.positiva||0)+(camp.mayo?.positiva||0) } },
          { id:'presupuesto_fu', group:'Seguimientos automaticos', name:'Follow-up de presupuesto', desc:'23h despues de cotizar sin respuesta, manda un seguimiento (gratis, dentro de la ventana de 24h).', trigger:'Cron horario 8-20 AR', state: billingBlocked ? 'pausado' : 'active', stats:{} },
          { id:'minicurso_fu', group:'Seguimientos automaticos', name:'Follow-up de minicurso', desc:'4-24h sin respuesta tras el minicurso, manda un recordatorio.', trigger:'Cron horario 8-20 AR', state: billingBlocked ? 'pausado' : 'active', stats:{} },
          { id:'cursos_fu', group:'Seguimientos automaticos', name:'Follow-up de cursos (Mayo)', desc:'2do mensaje a no-respondedores. DESACTIVADO (mandaba al cohorte equivocado).', trigger:'Cron horario', state:'disabled', stats:{} },
          { id:'pago_ocr', group:'Otras', name:'OCR de comprobantes de pago', desc:'En ventana de lanzamiento, OCRea imagenes/PDF, clasifica y respalda. No responde al cliente.', trigger:'Inbound con imagen/PDF', state: PAGO_CAPTURA_ACTIVA ? 'active' : 'disabled', stats:{} },
          { id:'copilot', group:'Otras', name:'Analisis IA de chats (Copilot)', desc:'Analiza chats nuevos con Claude (hasta 5/h): sentimiento, objeciones, proxima accion.', trigger:'Cron horario', state: env.ANTHROPIC_API_KEY ? 'active' : 'inactivo', stats:{} },
          { id:'lead_b2b', group:'Leads / Ads', name:'Lead Ads B2B -> auto-WhatsApp', desc:'Cuando entra un lead del form B2B de Meta Ads, le manda la plantilla lead_b2b_followup en menos de 30s.', trigger:'Webhook de Meta (leadgen)', state: env.META_PAGE_ACCESS_TOKEN ? 'active' : 'disabled', stats:{ leads: leadsTotal, enviados: leadsSent, fallidos: Math.max(0, leadsTotal - leadsSent) } },
          { id:'cursos_flow', group:'Disparadores por mensaje', name:'Flujo de cursos (ads)', desc:'Lead de ad de cursos -> opener automatico (visible para Abril desde el inicio) -> branch por IA (manda el minicurso si responde) -> nutrir (msg +23h) + nudge a las 3hs.', trigger:'Inbound de lead de ad de cursos', state: cfOn ? 'active' : 'disabled', stats:{ en_curso: cfActivos, total: cfTotal } },
        ];
        // Broadcasts custom creados desde el panel (Fase 2): se suman arriba.
        try {
          const bcs = (await env.DB.prepare("SELECT id, name, template, status FROM wa_broadcasts ORDER BY id DESC").all()).results || [];
          for (const b of bcs) {
            const st = byKind['bc_' + b.id] || {};
            const state = b.status === 'paused' ? 'pausado' : (st.queued ? 'en_curso' : (st.sent ? 'completado' : 'inactivo'));
            automations.unshift({ id: 'bc_' + b.id, group: 'Broadcasts', name: b.name || ('Broadcast #' + b.id), desc: 'Plantilla ' + b.template + ' - creado desde el panel (CSV).', trigger: 'CSV / manual', state, stats: st });
          }
        } catch (_) {}
        return json({ ok:true, billing_blocked: billingBlocked, cursos_inbox: cursosInbox, automations });
      }
      // Crear un broadcast custom desde el panel (Fase 2): CSV de contactos +
      // plantilla elegida + goteo. dryRun=true valida sin encolar (preview seguro).
      if (request.method === 'POST' && path === '/admin/broadcasts') {
        if (!isAdminSession) return json({ error: 'forbidden: admin only' }, 403);
        await ensureBroadcastsSchema(env);
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const template = (body?.template || '').trim();
        if (!template) return json({ error: 'falta la plantilla' }, 400);
        const lang = (body?.lang || 'es').trim();
        const paramMode = body?.param_mode === 'none' ? 'none' : 'nombre';
        const bodyPreview = (body?.body_preview || '').slice(0, 2000);
        const name = (body?.name || '').slice(0, 120);
        const intervalSec = Math.max(5, Math.min(3600, parseInt(body?.intervalSec, 10) || 32));
        const rawContacts = Array.isArray(body?.contacts) ? body.contacts : [];
        // Flujo fusionado (Fase 2.5): respuesta IA (X/Y texto libre) + follow-up (Z plantilla). Opcional.
        const replyAi = body?.reply_ai ? 1 : 0;
        const replyPos = (body?.reply_pos_msg || '').slice(0, 2000);
        const replyNeg = (body?.reply_neg_msg || '').slice(0, 2000);
        let followupHours = parseFloat(body?.followup_hours);
        if (!followupHours || isNaN(followupHours) || followupHours <= 0) followupHours = null;
        const followupTemplate = (body?.followup_template || '').trim();
        const followupLang = (body?.followup_lang || 'es').trim();
        const followupParamMode = body?.followup_param_mode === 'none' ? 'none' : 'nombre';
        const followupPreview = (body?.followup_preview || '').slice(0, 2000);
        // Normalizar telefonos + dedupe; descartar invalidos.
        const seen = new Set();
        const valid = [];
        let invalid = 0;
        for (const c of rawContacts) {
          const ph = normalizeArPhone(c && (c.phone != null ? c.phone : c.tel));
          if (!ph) { invalid++; continue; }
          if (seen.has(ph)) continue;
          seen.add(ph);
          valid.push({ phone: ph, nombre: String((c && c.nombre) || '').slice(0, 80) });
        }
        if (!valid.length) return json({ error: 'no hay contactos validos en el CSV', invalid }, 400);
        let startMs = Date.parse(body?.startTs || '');
        if (!startMs || isNaN(startMs)) startMs = Date.now();
        const durationMin = Math.round((valid.length * intervalSec) / 60);
        if (body?.dryRun) {
          return json({ ok: true, dryRun: true, valid: valid.length, invalid, interval_sec: intervalSec, start: new Date(startMs).toISOString(), duration_min: durationMin, sample: valid.slice(0, 5) });
        }
        const ins = await env.DB.prepare(
          "INSERT INTO wa_broadcasts (name, template, lang, param_mode, body_preview, status, total, created_at, created_by, reply_ai, reply_pos_msg, reply_neg_msg, followup_hours, followup_template, followup_lang, followup_param_mode, followup_preview) VALUES (?, ?, ?, ?, ?, 'running', ?, ?, 'admin', ?, ?, ?, ?, ?, ?, ?, ?)"
        ).bind(name, template, lang, paramMode, bodyPreview, valid.length, new Date().toISOString(), replyAi, replyPos, replyNeg, followupHours, (followupHours ? followupTemplate : null), followupLang, followupParamMode, followupPreview).run();
        const id = ins?.meta?.last_row_id;
        if (!id) return json({ error: 'no se pudo crear el broadcast' }, 500);
        const kind = 'bc_' + id;
        const stmts = [];
        for (let i = 0; i < valid.length; i++) {
          const dueAt = new Date(startMs + i * intervalSec * 1000).toISOString();
          stmts.push(env.DB.prepare("INSERT OR IGNORE INTO wa_autoreply_log (phone, kind, sent_at, status, due_at, sender_name) VALUES (?, ?, '', 'queued', ?, ?)").bind(valid[i].phone, kind, dueAt, valid[i].nombre));
        }
        for (let j = 0; j < stmts.length; j += 100) { try { await env.DB.batch(stmts.slice(j, j + 100)); } catch (_) {} }
        return json({ ok: true, id, kind, enqueued: valid.length, invalid, interval_sec: intervalSec, start: new Date(startMs).toISOString(), duration_min: durationMin });
      }
      if (request.method === 'POST' && path === '/admin/costs') {
        if (!isAdminSession) return json({ error: 'forbidden: admin only' }, 403);
        await ensureCostsSchema(env);
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const action = body?.action || 'upsert';
        const now = new Date().toISOString();
        if (action === 'resume_wa') {
          // Reanudar manualmente los envíos (tras cargar saldo en 360dialog).
          const was = await clearWaBillingBlock(env);
          return json({ ok: true, was_blocked: was });
        }
        if (action === 'set_rate') {
          const rt = parseFloat(body?.usd_ars);
          if (!isFinite(rt) || rt <= 0) return json({ error: 'tipo de cambio inválido' }, 400);
          await env.DB.prepare(`INSERT INTO kv_cache (k, v, updated_at) VALUES ('usd_ars_rate', ?, ?) ON CONFLICT(k) DO UPDATE SET v=excluded.v, updated_at=excluded.updated_at`).bind(String(rt), now).run();
          return json({ ok: true, usd_ars: rt });
        }
        if (action === 'delete') {
          const id = parseInt(body?.id, 10);
          if (!id) return json({ error: 'missing id' }, 400);
          await env.DB.prepare('UPDATE site_services SET active=0, updated_at=? WHERE id=?').bind(now, id).run();
          return json({ ok: true });
        }
        const sv = body?.service || {};
        const f = {
          name: String(sv.name || '').slice(0, 200),
          category: ['ia', 'infra', 'mensajeria', 'almacenamiento', 'ads', 'otro'].includes(sv.category) ? sv.category : 'otro',
          provider: String(sv.provider || '').slice(0, 100),
          usage: String(sv.usage || '').slice(0, 1000),
          credential_location: String(sv.credential_location || '').slice(0, 500),
          cost_type: ['fixed', 'usage', 'free'].includes(sv.cost_type) ? sv.cost_type : 'fixed', // 'auto' no se setea a mano
          cost_amount: (isFinite(parseFloat(sv.cost_amount)) ? parseFloat(sv.cost_amount) : 0),
          cost_currency: ['USD', 'ARS', 'EUR'].includes(sv.cost_currency) ? sv.cost_currency : 'USD',
          billing_url: String(sv.billing_url || '').slice(0, 500),
          notes: String(sv.notes || '').slice(0, 1000),
          sort_order: (isFinite(parseInt(sv.sort_order, 10)) ? parseInt(sv.sort_order, 10) : 100)
        };
        const id = parseInt(sv.id, 10);
        if (id) {
          // Editar: no tocar auto_key (un servicio 'auto' sigue siendo auto). Solo
          // actualiza cost_type si el original NO era auto.
          const orig = await env.DB.prepare('SELECT cost_type, auto_key FROM site_services WHERE id=?').bind(id).first();
          const keepAuto = orig && orig.cost_type === 'auto';
          await env.DB.prepare(
            `UPDATE site_services SET name=?, category=?, provider=?, usage=?, credential_location=?, cost_type=?, cost_amount=?, cost_currency=?, billing_url=?, notes=?, sort_order=?, updated_at=? WHERE id=?`
          ).bind(f.name, f.category, f.provider, f.usage, f.credential_location, keepAuto ? 'auto' : f.cost_type, f.cost_amount, f.cost_currency, f.billing_url, f.notes, f.sort_order, now, id).run();
          return json({ ok: true, id });
        }
        if (!f.name) return json({ error: 'falta el nombre del servicio' }, 400);
        const res = await env.DB.prepare(
          `INSERT INTO site_services (sort_order, name, category, provider, usage, credential_location, cost_type, cost_amount, cost_currency, auto_key, billing_url, notes, active, created_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, '', ?, ?, 1, ?, ?)`
        ).bind(f.sort_order, f.name, f.category, f.provider, f.usage, f.credential_location, f.cost_type, f.cost_amount, f.cost_currency, f.billing_url, f.notes, now, now).run();
        return json({ ok: true, id: res.meta?.last_row_id });
      }

      if (request.method === 'POST' && path === '/admin/wa/send') {
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { to, body: text, reply_to } = body || {};
        if (!to || !text) return json({ error: 'missing fields (to, body)' }, 400);
        const num = normalizeArPhone(to);
        // Rol 'cursos' (Abril) solo puede escribir a chats de su bandeja.
        {
          const _role = await getSessionRole(env, session.user);
          if (!(await inboxAccessOk(env, _role, num || String(to).replace(/\D/g, ''), session.user))) {
            return json({ error: 'forbidden: chat fuera de tu bandeja' }, 403);
          }
        }
        // Chequeo de ventana 24h OPT-IN (check_window): el texto libre fuera de ventana rebota
        // ASYNC con 131047 (Meta lo acepta y lo falla por webhook → no se atrapa en el return).
        // Si el caller lo pide (ej. presupuesto), avisamos 409 window_closed ANTES de mandar,
        // para que el front caiga a la plantilla aprobada en vez de perder el mensaje.
        if (body.check_window && num) {
          const since24 = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
          const inb = await env.DB.prepare("SELECT 1 FROM wa_messages WHERE phone = ? AND direction = 'inbound' AND ts > ? LIMIT 1").bind(num, since24).first();
          if (!inb) return json({ error: 'Re-engagement message', window_closed: true }, 409);
        }
        // Si reply_to viene, incluimos context.message_id para que WA lo muestre como cita.
        const payload = { messaging_product: 'whatsapp', to: num || to, type: 'text', text: { body: String(text) } };
        if (reply_to) payload.context = { message_id: reply_to };
        const r = await waSend(env, payload);
        await logWaEvent(env, { to, kind: 'text', ref: reply_to || '', ok: r.ok, messageId: r.id, error: r.error });
        if (!r.ok) return json({ error: r.error, raw: r.raw }, r.status || 500);
        // sender_name = quién lo escribió (panel de rendimiento): slug del vendedor (joaco/facundo/
        // agustina) o el usuario en minúscula (gaspar, abril…). En salientes no se muestra ni toca el
        // nombre del contacto (el trigger de la lista solo lee sender_name de los inbound).
        const _autor = autorSlug(session.user);
        try {
          await env.DB.prepare(
            'INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
          ).bind(new Date().toISOString(), r.id || '', 'outbound', num || to, _autor, 'text', String(text), '', reply_to || '', 'sent').run();
        } catch (_) {}
        // Autor real del envío (avisos internos: si después falla, le llega a quien lo mandó). DESPUÉS del INSERT y en
        // segundo plano: antes del INSERT agrandaba la carrera con la fila fantasma de status (el chat mostraba "sin
        // texto registrado"); el autor solo se usa cuando llega un 'failed', segundos después. Nunca tira.
        ctx.waitUntil(registrarAutorEnvio(env, r.id, session.user, num || String(to).replace(/\D/g, '')));
        // Auto-etiquetar ALUMNO (id 26): si Abril manda el mensaje de ALTA al programa (el de
        // "LEE BIEN A CONCIENCIA..." o el link a la plataforma alinfinito.app.clientclub.net),
        // el contacto ya compró el curso -> con la etiqueta se le cortan los automáticos de
        // cursos (ver esAlumnoCursos). Disparadores validados: los 71 alumnos ya etiquetados
        // recibieron uno de estos, sin falsos positivos.
        try {
          if (/LEE BIEN A CONCIENCIA ESTE MENSAJE|alinfinito\.app\.clientclub\.net/i.test(String(text))) {
            await env.DB.prepare("INSERT OR IGNORE INTO contact_labels (phone, label_id, created_at) VALUES (?, 26, ?)").bind(num || to, new Date().toISOString()).run();
            await enqueueComunidadPromo(env, num || to);   // drip Pack Emprendedor a los 14 días
          }
        } catch (_) {}
        // Pin privado (pedido Bruno 3-sep): texto libre con su firma → el chat ADEMÁS a la privada.
        // Solo si la sesión es admin (Bruno/Gaspar) → evita falsos pin de Joaco/Abril al nombrar a Bruno.
        if (isAdminSession && /\bbruno\b/i.test(String(text))) { try { await pinPrivadoBruno(env, num || String(to).replace(/\D/g, '')); } catch (_) {} }
        // "El que trabaja el lead se queda con él" (Gaspar 4-sep): si lo manda un vendedor comercial,
        // el chat se le asigna a él (Joaco/Facu), así el lead no queda con el vendedor equivocado.
        try { await reasignarAlQueTrabaja(env, num || String(to).replace(/\D/g, ''), session.user); } catch (_) {}
        return json({ id: r.id });
      }

      if (request.method === 'POST' && path === '/admin/wa/template') {
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { to, name, lang, params, header_image_key } = body || {};
        if (!to || !name) return json({ error: 'missing fields (to, name)' }, 400);
        const num = normalizeArPhone(to);
        // Si viene header_image_key (r2 key del render), lo subimos a Meta y lo mandamos
        // en el header de la plantilla (para media templates tipo presupuesto_detallado_img).
        let headerMediaId = null;
        if (header_image_key) { try { headerMediaId = await getPromoMediaId(env, header_image_key); } catch (_) {} }
        const r = await waSendTemplate(env, to, name, lang || 'es', Array.isArray(params) ? params : [], headerMediaId);
        await logWaEvent(env, { to, kind: 'template:' + name, ref: '', ok: r.ok, messageId: r.id, error: r.error });
        if (!r.ok) return json({ error: r.error, raw: r.raw }, r.status || 500);
        // Guardar en wa_messages para que aparezca en el chat
        try {
          // Valores unidos por ", " (legible; tplMarkerToText del front los separa). Si ALGUNO trae ", " adentro
          // (el Frente de corpóreos: "frente full color, reproduciendo tu diseño, opaco") ese split corría los
          // campos en el chat → en ese caso van como JSON (["…","…"]), que el front lee sin ambigüedad.
          const _tplVals = Array.isArray(params) ? params.map(p => String(p)) : [];
          const previewBody = `[plantilla: ${name}]` + (_tplVals.length
            ? ' ' + (_tplVals.some(v => v.includes(', ')) ? JSON.stringify(_tplVals) : _tplVals.join(', '))
            : '');
          // Trazabilidad: marcamos el vendedor que la envió (presupuesto por plantilla / ventana cerrada).
          const senderSlug = await resolveComercial(env, { sessionUser: session.user, phone: num || String(to).replace(/\D/g, '') });
          // Si la plantilla se mandó CON el render en el header (header_image_key resuelto a un
          // media_id), la guardamos como IMAGEN con el render como media_url → así el chat MUESTRA
          // la foto (igual que un presupuesto dentro de la ventana), no solo el rótulo "plantilla
          // enviada". El body sigue siendo el marcador → tplMarkerToText reconstruye el texto de pie.
          const sentWithImg = !!(header_image_key && headerMediaId);
          await env.DB.prepare(
            'INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
          ).bind(new Date().toISOString(), r.id || '', 'outbound', num || to, senderSlug, sentWithImg ? 'image' : 'template', previewBody, sentWithImg ? header_image_key : '', '', 'sent').run();
        } catch (_) {}
        // Autor real (avisos internos): después del INSERT y en segundo plano (ver /admin/wa/send).
        ctx.waitUntil(registrarAutorEnvio(env, r.id, session.user, num || String(to).replace(/\D/g, '')));
        // "El que trabaja el lead se queda con él" (Gaspar 4-sep): el presupuesto/plantilla que manda
        // un vendedor comercial le asigna el chat a él (caso Bre: lo cotizó Joaco, quedaba en Facu).
        try { await reasignarAlQueTrabaja(env, num || String(to).replace(/\D/g, ''), session.user); } catch (_) {}
        return json({ id: r.id });
      }

      // ===== FULL-TEXT SEARCH del chat WA =====
      // Busca en body de mensajes, sender_name y phone. Devuelve:
      // - contacts: lista de phones que tienen mensajes que matchean
      // - messages: mensajes individuales que matchean con preview
      if (request.method === 'GET' && path === '/admin/wa/search') {
        const q = (url.searchParams.get('q') || '').trim();
        if (q.length < 2) return json({ contacts: [], messages: [] });
        // SQLite LIKE es case-insensitive para ASCII por default con NOCASE,
        // pero acá normalizamos a lowercase para consistencia.
        const qLower = q.toLowerCase();
        const like = '%' + qLower + '%';
        // Scope por rol/vendedor: el secundario (Facundo) SOLO busca en SUS chats; el principal
        // (Joaco) en todo lo NO asignado a un secundario; cursos su bandeja; admin todo. Cierra
        // el hueco de encontrar (y responder) chats ajenos por la búsqueda.
        const _srole = await getSessionRole(env, session.user);
        let scopeClause = '';
        if (_srole !== 'admin') {
          if (_srole === 'cursos') {
            scopeClause = " AND wa_messages.phone IN (SELECT phone FROM wa_chats_summary WHERE inbox='cursos')";
          } else {
            const _su = String(session.user || '').toLowerCase();
            const _asg = VENDEDORES_SECUNDARIOS.includes(_su) ? `assigned_to = '${_su}'` : `assigned_to NOT IN (${VENDEDORES_SECUNDARIOS.map(s => `'${s}'`).join(',')})`;
            scopeClause = ` AND wa_messages.phone IN (SELECT phone FROM wa_chats_summary WHERE inbox NOT IN ('cursos','oculto','precotiz','privado','corte') AND ${_asg})`;
          }
        }

        // Contactos: phones únicos cuyos mensajes contienen el query.
        // También matchea si el query es parte del phone (para buscar por número).
        const contactsQ = await env.DB.prepare(
          `SELECT phone, COUNT(*) AS hits, MAX(ts) AS last_match_ts,
                  MAX(CASE WHEN LOWER(sender_name) != '' THEN sender_name END) AS contact_name
           FROM wa_messages
           WHERE (LOWER(body) LIKE ?
              OR LOWER(sender_name) LIKE ?
              OR phone LIKE ?)${scopeClause}
           GROUP BY phone
           ORDER BY last_match_ts DESC
           LIMIT 50`
        ).bind(like, like, like).all();

        // Mensajes individuales: top 50 mensajes recientes que matchean.
        const messagesQ = await env.DB.prepare(
          `SELECT ts, phone, sender_name, direction, msg_type, body, wamid
           FROM wa_messages
           WHERE LOWER(body) LIKE ?${scopeClause}
           ORDER BY ts DESC
           LIMIT 50`
        ).bind(like).all();

        // Chats del equipo: solo admin (mismo criterio que la lista de chats y inboxAccessOk).
        let _contacts = contactsQ.results || [], _messages = messagesQ.results || [];
        if (_srole !== 'admin') {
          try {
            const _I = await internosSet(env);
            const _fuera = (p) => _I.set.has(String(p || '').replace(/\D/g, ''));
            _contacts = _contacts.filter(c => !_fuera(c.phone)); _messages = _messages.filter(m => !_fuera(m.phone));
          } catch (_) {}
        }
        return json({
          q,
          contacts: _contacts,
          messages: _messages
        });
      }

      // (Endpoint /admin/wa/phone-info v1 removido — la versión que ramifica por
      //  provider y unifica con phone-status vive más abajo en este mismo archivo.)

      // ===== BULK IMPORT de historial de WA (scrape via whatsapp-web.js) =====
      // El script scrape-wa-history.js corre en la PC del usuario y manda
      // batches de mensajes acá. Inserta con OR IGNORE para dedup por wamid.
      if (request.method === 'POST' && path === '/admin/wa/import-bulk') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { phone, messages, contactName } = body || {};
        if (!phone || !Array.isArray(messages)) return json({ error: 'missing phone or messages[]' }, 400);
        const num = normalizeArPhone(phone) || phone;
        let inserted = 0, duplicates = 0, skipped = 0, errors = 0, mediaBackfilled = 0;
        for (const m of messages) {
          try {
            // Normalizar
            const ts = m.ts || new Date().toISOString();
            const wamid = m.wamid || ('scraped_' + num + '_' + new Date(ts).getTime() + '_' + Math.random().toString(36).slice(2, 8));
            const direction = m.direction === 'outbound' ? 'outbound' : 'inbound';
            const msgType = m.msg_type || m.type || 'text';
            const bodyText = String(m.body || '');
            const mediaUrl = m.media_url || '';
            const contextId = m.context_id || '';
            const senderName = direction === 'inbound' ? (contactName || m.sender_name || '') : '';
            if (!bodyText && !mediaUrl) { skipped++; continue; }
            const r = await env.DB.prepare(
              'INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
            ).bind(ts, wamid, direction, num, senderName, msgType, bodyText, mediaUrl, contextId, 'imported').run();
            if (r.meta && r.meta.changes > 0) {
              inserted++;
            } else {
              duplicates++;
              // Backfill media_url si el mensaje ya existía con media_url vacío
              // y este import trae uno nuevo (ej: catch-up que ahora baja media).
              if (mediaUrl) {
                const u = await env.DB.prepare(
                  "UPDATE wa_messages SET media_url = ? WHERE wamid = ? AND (media_url IS NULL OR media_url = '')"
                ).bind(mediaUrl, wamid).run();
                if (u.meta && u.meta.changes > 0) mediaBackfilled++;
              }
            }
          } catch (e) {
            errors++;
          }
        }
        return json({ ok: true, inserted, duplicates, skipped, errors, mediaBackfilled, total: messages.length });
      }

      // ===== MEDIA UPLOAD desde scraper (sube blob a R2, devuelve key) =====
      // El scraper baja la media de WA Web (msg.downloadMedia → base64),
      // la convierte a binario y la sube acá multipart. Devuelve el R2 key
      // que el scraper guarda en media_url al hacer import-bulk.
      // Key determinístico = wa/scrape_<wamid_sanitized> → si se intenta subir
      // el mismo wamid 2 veces, sobrescribe (idempotente).
      if (request.method === 'POST' && path === '/admin/wa/media/upload') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        if (!env.MEDIA) return json({ error: 'R2 not configured' }, 500);
        const ct = request.headers.get('Content-Type') || '';
        if (!ct.includes('multipart/form-data')) return json({ error: 'expected multipart/form-data' }, 400);
        const fd = await request.formData();
        const file = fd.get('file');
        const wamid = String(fd.get('wamid') || '').trim();
        const msgType = String(fd.get('type') || 'document').trim();
        if (!file) return json({ error: 'missing file' }, 400);
        if (!wamid) return json({ error: 'missing wamid' }, 400);
        const fileMime = file.type || '';
        const fileName = file.name || '';
        const ext = fileName.includes('.') ? '.' + fileName.split('.').pop().toLowerCase().slice(0, 5)
                  : msgType === 'audio' ? '.ogg'
                  : msgType === 'image' ? '.jpg'
                  : msgType === 'video' ? '.mp4'
                  : msgType === 'sticker' ? '.webp'
                  : '';
        // Key determinístico por wamid (sanitizado).
        const sanitized = wamid.replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 120);
        const r2Key = `wa/scrape_${sanitized}${ext}`;
        const buf = await file.arrayBuffer();
        const defaultMime = msgType === 'audio' ? 'audio/ogg; codecs=opus'
                          : msgType === 'image' ? 'image/jpeg'
                          : msgType === 'video' ? 'video/mp4'
                          : msgType === 'sticker' ? 'image/webp'
                          : 'application/octet-stream';
        const mime = fileMime || defaultMime;
        try {
          await env.MEDIA.put(r2Key, buf, { httpMetadata: { contentType: mime } });
          return json({ ok: true, key: r2Key, bytes: buf.byteLength });
        } catch (e) {
          return json({ error: 'r2 put failed: ' + e.message }, 500);
        }
      }

      // Lista de wamids que YA tienen media_url en DB.
      if (request.method === 'GET' && path === '/admin/wa/media/wamids') {
        try {
          const rs = await env.DB.prepare(
            "SELECT wamid FROM wa_messages WHERE media_url IS NOT NULL AND media_url != ''"
          ).all();
          const wamids = (rs.results || []).map(r => r.wamid).filter(Boolean);
          return json({ wamids });
        } catch (e) { return json({ wamids: [], error: e.message }, 500); }
      }

      // Lista de TODOS los wamids en DB (con o sin media). El scraper la baja
      // al arrancar para saber qué mensajes ya están conocidos y skipear el
      // download de media (costoso) cuando es un duplicado. Solo para mensajes
      // NUEVOS se baja la media. ~16k strings ≈ 800 KB total.
      if (request.method === 'GET' && path === '/admin/wa/wamids') {
        try {
          const rs = await env.DB.prepare('SELECT wamid FROM wa_messages WHERE wamid IS NOT NULL AND wamid != ""').all();
          const wamids = (rs.results || []).map(r => r.wamid).filter(Boolean);
          return json({ wamids, count: wamids.length });
        } catch (e) { return json({ wamids: [], error: e.message }, 500); }
      }

      // ===== WA CONTACTS (nombres de contacto sincronizados desde WhatsApp) =====
      // Tabla wa_contacts: phone → name. La fuente es el scraper que lee los
      // nombres tal como Joaco los tiene guardados en la agenda del 6573.
      // El frontend mergea esto contra los mensajes para mostrar el nombre real.
      if (request.method === 'POST' && path === '/admin/wa/contacts/import-bulk') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { contacts } = body || {};
        if (!Array.isArray(contacts)) return json({ error: 'missing contacts[]' }, 400);
        await env.DB.prepare("CREATE TABLE IF NOT EXISTS wa_contacts (phone TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL)").run();
        const now = new Date().toISOString();
        let upserted = 0, skipped = 0;
        for (const c of (contacts || [])) {
          const rawPhone = c?.phone || '';
          const num = normalizeArPhone(rawPhone) || String(rawPhone).replace(/\D/g, '');
          const name = String(c?.name || '').trim();
          if (!num || !name) { skipped++; continue; }
          try {
            await env.DB.prepare(
              'INSERT INTO wa_contacts (phone, name, updated_at) VALUES (?, ?, ?) ON CONFLICT(phone) DO UPDATE SET name = excluded.name, updated_at = excluded.updated_at'
            ).bind(num, name, now).run();
            upserted++;
          } catch (_) { skipped++; }
        }
        return json({ ok: true, upserted, skipped, total: contacts.length });
      }

      if (request.method === 'GET' && path === '/admin/wa/contacts') {
        try {
          // ?v=: mismo esquema de versión que /admin/contact-labels (triggers trg_ver_wa_contacts_*).
          const ver = await kvGet(env, 'ver:wa_contacts', null);
          if (ver && url.searchParams.get('v') === ver) return json({ unchanged: true, ver });
          await env.DB.prepare("CREATE TABLE IF NOT EXISTS wa_contacts (phone TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL)").run();
          const rs = await env.DB.prepare('SELECT phone, name, username, pic_url FROM wa_contacts').all();
          return json({ contacts: rs.results || [], ver });
        } catch (e) { return json({ contacts: [] }); }
      }

      // Rellena la foto de perfil de los contactos de IG que todavía no la tienen
      // (los resueltos antes de agregar la foto). One-shot, idempotente: igResolveName
      // ya saltea los que tienen foto fresca. Útil además para refrescar antes de que venzan.
      if (request.method === 'POST' && path === '/admin/ig/backfill-pics') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        if (!(await igGetToken(env))) return json({ error: 'no IG token' }, 400);
        let contactos = 0, media = 0;
        try {
          // 1) Contactos de IG sin nombre/@usuario/foto -> re-resolver. Incluye los "echo-only"
          //    (a los que solo les escribimos y no están en wa_contacts) vía LEFT JOIN.
          const rs = await env.DB.prepare("SELECT s.phone AS phone FROM wa_chats_summary s LEFT JOIN wa_contacts c ON c.phone=s.phone WHERE s.channel='ig' AND (c.name IS NULL OR c.name='' OR c.username IS NULL OR c.username='' OR c.pic_url IS NULL OR c.pic_url='')").all();
          for (const row of (rs.results || [])) { contactos++; await igResolveName(env, row.phone); }
          // 2) Mensajes de IG con media todavía en URL cruda (lookaside) -> bajar a R2.
          const ms = await env.DB.prepare("SELECT id, wamid, media_url, msg_type FROM wa_messages WHERE channel='ig' AND media_url LIKE 'http%' LIMIT 100").all();
          for (const row of (ms.results || [])) {
            const k = await downloadIgMedia(env, row.media_url, row.wamid, row.msg_type);
            if (k) { await env.DB.prepare('UPDATE wa_messages SET media_url=? WHERE id=?').bind(k, row.id).run(); media++; }
          }
          return json({ ok: true, contactos, media });
        } catch (e) { return json({ error: String(e), contactos, media }, 500); }
      }

      // Re-procesa los webhooks de IG ya logueados a través de processIgWebhook (idempotente:
      // INSERT OR IGNORE por mid). Sirve para recuperar HISTÓRICO: los mensajes ENVIADOS (echoes)
      // que antes descartábamos, y re-etiquetar los anuncios (ig_post) que quedaron como
      // "imagen no disponible". Esos placeholders se borran primero para que el replay los recree bien.
      if (request.method === 'POST' && path === '/admin/ig/replay-logs') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        let replayed = 0, deleted = 0;
        try {
          const del = await env.DB.prepare("DELETE FROM wa_messages WHERE channel='ig' AND body='🖼️ imagen no disponible'").run();
          deleted = del.meta?.changes || 0;
          const rs = await env.DB.prepare("SELECT payload FROM wa_webhook_log WHERE payload LIKE 'IG: {%' ORDER BY ts DESC LIMIT 600").all();
          for (const row of (rs.results || [])) {
            try {
              const raw = String(row.payload || '');
              const obj = JSON.parse(raw.slice(raw.indexOf('{')));
              await processIgWebhook(env, obj);
              replayed++;
            } catch (_) {}
          }
          return json({ ok: true, deleted, replayed });
        } catch (e) { return json({ error: String(e), deleted, replayed }, 500); }
      }

      // POST /admin/reporte-diario/test → arma el reporte diario y lo devuelve; con {send:true} lo manda por WA a Gaspar+hermano.
      if (request.method === 'POST' && path === '/admin/reporte-diario/test') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        let body = {}; try { body = await request.json(); } catch (_) {}
        const d = await buildReporteDiario(env);
        const preview = formatReporteDiario(d);
        if (body && body.send) { for (const ph of REPORTE_DIARIO_PHONES) { try { await waSendText(env, ph, preview); } catch (_) {} } }
        return json({ ok: true, data: d, preview, sent: !!(body && body.send) });
      }

      // ===== Avisos internos (plan de fondo, Etapa 1): /admin/avisos* → avisosRoute (ahí está el detalle) =====
      // /mios y /visto son para cualquiera del equipo (banner de P1 sin ver); el resto, solo admin.
      {
        const _avResp = await avisosRoute(env, request, url, path, session, isAdminSession);
        if (_avResp) return _avResp;
      }

      // POST /admin/envios-pausa → freno GLOBAL de envíos de WhatsApp (kv wa_send_paused).
      // {on:true} frena TODO envío saliente (usar cuando Meta restringe la cuenta);
      // {on:false} lo reanuda y todos los flujos siguen solos. Sin body: devuelve el estado.
      // (Ojo: NO usar el prefijo /admin/wa/ acá — ese lo intercepta otro bloque de rutas.)
      if (request.method === 'POST' && path === '/admin/envios-pausa') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        let body = {}; try { body = await request.json(); } catch (_) {}
        if (typeof body.on === 'boolean') await kvSet(env, 'wa_send_paused', body.on ? '1' : '0');
        return json({ ok: true, paused: (await kvGet(env, 'wa_send_paused', '0')) === '1' });
      }

      // GET /admin/envios-reintentos → estado de los reintentos acotados de campañas (ver
      // campaignSendFail): pausa/racha de cada flujo, bloqueo de pago, y por flujo cuántas filas en
      // espera / perdidas + los últimos errores REALES. POST {kind, reanudar:true} → levanta la
      // pausa de ese flujo (después de arreglar la causa, sin esperar el backoff).
      if (path === '/admin/envios-reintentos') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        const KINDS = ['comunidad_promo', 'lanzamiento_opener', 'minisupernova', 'pp-followup-tpl'];
        await ensureSendRetryTable(env);
        // + los broadcasts del panel ('bc_<id>') que tengan reintentos o pausa registrados.
        try { for (const r of ((await env.DB.prepare("SELECT DISTINCT kind FROM wa_send_retry WHERE kind LIKE 'bc!_%' ESCAPE '!'").all()).results || [])) if (!KINDS.includes(r.kind)) KINDS.push(r.kind); } catch (_) {}
        try { for (const r of ((await env.DB.prepare("SELECT substr(k, 11) AS kind FROM kv_cache WHERE k LIKE 'cmpgn!_brk:bc!_%' ESCAPE '!'").all()).results || [])) if (r.kind && !KINDS.includes(r.kind)) KINDS.push(r.kind); } catch (_) {}
        if (request.method === 'POST') {
          let body = {}; try { body = await request.json(); } catch (_) {}
          if (body.reanudar && (KINDS.includes(body.kind) || /^bc_\d+$/.test(String(body.kind || '')))) {
            // Broadcast: al pausar se corrió su cola lo que duraba la pausa → volverla a correr lo que falta.
            if (/^bc_\d+$/.test(body.kind)) {
              try {
                const st = await campaignState(env, body.kind);
                const resta = st.until ? Math.round((st.until - Date.now()) / 1000) : 0;
                if (resta > 0) await env.DB.prepare("UPDATE wa_autoreply_log SET due_at = strftime('%Y-%m-%dT%H:%M:%fZ', due_at, '-' || ? || ' seconds') WHERE kind = ? AND status = 'queued'").bind(resta, body.kind).run();
              } catch (_) {}
            }
            try { await env.DB.prepare('DELETE FROM kv_cache WHERE k = ?').bind('cmpgn_brk:' + body.kind).run(); } catch (_) {}
          }
        }
        const nowIso = new Date().toISOString();
        const flujos = {};
        for (const k of KINDS) {
          const st = await campaignState(env, k);
          let resumen = [], ultimos = [];
          try { resumen = (await env.DB.prepare("SELECT final, last_class, COUNT(*) AS n, SUM(CASE WHEN next_at > ? THEN 1 ELSE 0 END) AS en_espera FROM wa_send_retry WHERE kind = ? GROUP BY final, last_class").bind(nowIso, k).all()).results || []; } catch (_) {}
          try { ultimos = (await env.DB.prepare("SELECT phone, ref, attempts, final, next_at, last_class, last_error, updated_at FROM wa_send_retry WHERE kind = ? ORDER BY updated_at DESC LIMIT 10").bind(k).all()).results || []; } catch (_) {}
          flujos[k] = { pausado: campaignPaused(st), pausa_hasta: st.until ? new Date(st.until).toISOString() : null, racha_fallos: st.streak || 0, pausas_seguidas: st.trips || 0, motivo: st.reason || '', resumen, ultimos };
        }
        let billing = null, payReject = null;
        try { const row = await env.DB.prepare('SELECT v FROM kv_cache WHERE k = ?').bind(WA_BILLING_BLOCK_KEY).first(); if (row) billing = JSON.parse(row.v); } catch (_) {}
        try { const row = await env.DB.prepare('SELECT v FROM kv_cache WHERE k = ?').bind(WA_PAY_REJECT_KEY).first(); if (row) payReject = JSON.parse(row.v); } catch (_) {}
        return json({ ok: true, tope_intentos: CAMPAIGN_RETRY_CAP, bloqueo_pago_activo: await isWaBillingBlocked(env), bloqueo_pago_131042: billing, rechazo_pago_al_enviar: payReject, flujos });
      }

      // Recordatorio del evento (Fase Semilla): control del goteo + preview de números.
      // GET → estado + cuántos anotados/mandados/pendientes/en-ventana. POST {on, fase, pertick} → configura.
      //   on: bool (prende/apaga) · fase: 'ventana' (solo texto libre a los de 24h) | 'todos' (suma plantilla)
      //   pertick: 1..20 mensajes por corrida del cron de 1 min (~pertick*60/h).
      if (path === '/admin/evento-recordatorio') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        if (request.method === 'POST') {
          let body = {}; try { body = await request.json(); } catch (_) {}
          if (typeof body.on === 'boolean') await kvSet(env, 'evento_recordatorio_on', body.on ? '1' : '0');
          if (body.fase === 'ventana' || body.fase === 'todos') await kvSet(env, 'evento_recordatorio_fase', body.fase);
          if (body.pertick != null) await kvSet(env, 'evento_recordatorio_pertick', String(Math.max(1, Math.min(20, parseInt(body.pertick, 10) || 4))));
        }
        const on = (await kvGet(env, 'evento_recordatorio_on', '0')) === '1';
        const fase = String(await kvGet(env, 'evento_recordatorio_fase', 'ventana') || 'ventana');
        const perTick = parseInt(await kvGet(env, 'evento_recordatorio_pertick', '4'), 10) || 4;
        const cutoff = new Date(Date.now() - 24 * 3600 * 1000).toISOString();
        let total = 0, mandados = 0, enVentana = 0;
        try { total = (await env.DB.prepare("SELECT COUNT(*) AS n FROM lanzamiento_landing").first())?.n || 0; } catch (_) {}
        try { mandados = (await env.DB.prepare("SELECT COUNT(*) AS n FROM wa_autoreply_log WHERE kind='evento_record' AND status='sent'").first())?.n || 0; } catch (_) {}
        try { enVentana = (await env.DB.prepare("SELECT COUNT(*) AS n FROM lanzamiento_landing ll WHERE NOT EXISTS (SELECT 1 FROM wa_autoreply_log a WHERE a.phone=ll.phone AND a.kind='evento_record') AND EXISTS (SELECT 1 FROM wa_messages m WHERE m.phone=ll.phone AND m.direction='inbound' AND m.ts > ?)").bind(cutoff).first())?.n || 0; } catch (_) {}
        const hAR = new Date(Date.now() - 3 * 3600 * 1000).getUTCHours();
        const hFin = Math.max(10, Math.min(24, parseInt(await kvGet(env, 'evento_recordatorio_hora_fin', '21'), 10) || 21));
        return json({
          ok: true, on, fase, perTick,
          total_anotados: total, ya_mandados: mandados, pendientes: total - mandados, pendientes_en_ventana: enVentana,
          variante_mensaje: _eventoVarianteHoy(Date.now()) ? 'HOY 19hs' : 'mañana 19hs',
          horario_ok: (hAR >= 9 && hAR < hFin), hora_fin_ar: hFin, deadline: EVENTO_RECORDATORIO_DEADLINE,
          wa_send_paused: (await kvGet(env, 'wa_send_paused', '0')) === '1', ritmo_por_hora: perTick * 60
        });
      }

      // Panel de control de la campaña MiniSupernova (difusión a alumnos). GET = métricas;
      // POST {on:bool, pertick:int} = prender/apagar + ritmo por tick. Tope diario fijo 50.
      if (path === '/admin/minisupernova') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        try { await env.DB.prepare("CREATE TABLE IF NOT EXISTS minisupernova (phone TEXT PRIMARY KEY, nombre TEXT, grupo TEXT, status TEXT DEFAULT 'pending', sent_at TEXT, claimed_at TEXT, replied_at TEXT)").run(); } catch (_) {}
        if (request.method === 'POST') {
          let body = {}; try { body = await request.json(); } catch (_) {}
          if (typeof body.on === 'boolean') await kvSet(env, 'minisupernova_on', body.on ? '1' : '0');
          if (body.pertick != null) await kvSet(env, 'minisupernova_pertick', String(Math.max(1, Math.min(10, parseInt(body.pertick, 10) || 3))));
          if (body.cap != null) await kvSet(env, 'minisupernova_cap', String(Math.max(1, Math.min(200, parseInt(body.cap, 10) || MINISUPER_CAP_DIARIO))));
        }
        const on = (await kvGet(env, 'minisupernova_on', '0')) === '1';
        const perTick = parseInt(await kvGet(env, 'minisupernova_pertick', '3'), 10) || 3;
        const capDiario = Math.max(1, Math.min(200, parseInt(await kvGet(env, 'minisupernova_cap', String(MINISUPER_CAP_DIARIO)), 10) || MINISUPER_CAP_DIARIO));
        let total = 0, enviados = 0, pend = 0, resp = 0, hoy = 0, fallidos = 0, porGrupo = [];
        try { total = (await env.DB.prepare("SELECT COUNT(*) AS n FROM minisupernova").first())?.n || 0; } catch (_) {}
        try { fallidos = (await env.DB.prepare("SELECT COUNT(*) AS n FROM minisupernova WHERE status='failed'").first())?.n || 0; } catch (_) {}
        try { enviados = (await env.DB.prepare("SELECT COUNT(*) AS n FROM minisupernova WHERE status='sent'").first())?.n || 0; } catch (_) {}
        try { pend = (await env.DB.prepare("SELECT COUNT(*) AS n FROM minisupernova WHERE status='pending'").first())?.n || 0; } catch (_) {}
        try { resp = (await env.DB.prepare("SELECT COUNT(*) AS n FROM minisupernova WHERE replied_at IS NOT NULL").first())?.n || 0; } catch (_) {}
        try { hoy = (await env.DB.prepare("SELECT COUNT(*) AS n FROM minisupernova WHERE status='sent' AND sent_at >= " + REPORTE_DIA_DESDE).first())?.n || 0; } catch (_) {}
        try { porGrupo = (await env.DB.prepare("SELECT grupo, COUNT(*) AS n, SUM(CASE WHEN status='sent' THEN 1 ELSE 0 END) AS sent FROM minisupernova GROUP BY grupo ORDER BY CAST(grupo AS INTEGER)").all()).results || []; } catch (_) {}
        let tplN = 'unknown', tplG = 'unknown';
        try { const t = await env.DB.prepare("SELECT status FROM template_status_cache WHERE name = ?").bind(MINISUPER_TPL).first(); tplN = (t && t.status) || 'unknown'; } catch (_) {}
        try { const t = await env.DB.prepare("SELECT status FROM template_status_cache WHERE name = ?").bind(MINISUPER_TPL_GRL).first(); tplG = (t && t.status) || 'unknown'; } catch (_) {}
        let sinNombre = 0;
        try { sinNombre = (await env.DB.prepare("SELECT COUNT(*) AS n FROM minisupernova WHERE nombre IS NULL OR nombre = ''").first())?.n || 0; } catch (_) {}
        const hAR = new Date(Date.now() - 3 * 3600 * 1000).getUTCHours();
        return json({
          ok: true, on, perTick, cap_diario: capDiario,
          total, enviados, pendientes: pend, fallidos, respondieron: resp, enviados_hoy: hoy, sin_nombre: sinNombre,
          por_grupo: porGrupo,
          plantilla_nombre: MINISUPER_TPL, plantilla_nombre_status: tplN,
          plantilla_generica: MINISUPER_TPL_GRL, plantilla_generica_status: tplG,
          listo_para_enviar: (tplN.toUpperCase?.() === 'APPROVED' && tplG.toUpperCase?.() === 'APPROVED'),
          horario_ok: (hAR >= 9 && hAR < 21), hora_ar: hAR,
          wa_send_paused: (await kvGet(env, 'wa_send_paused', '0')) === '1',
          dias_estimados: pend > 0 ? Math.ceil(pend / capDiario) : 0
        });
      }

      // Lista "para llamar" de Agus. POST {} = PREVIEW (no manda nada). POST {send:true} = la manda YA (o sigue
      // desde la parte que faltó); si ya salió hoy NO la reenvía, salvo {send:true, again:true}. Solo Gaspar.
      if (request.method === 'POST' && path === '/admin/lista-agus-test') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        const _b = (await request.json().catch(() => null)) || {};
        const _send = _b.send === true;
        return json(await maybeListaAgus(env, { force: _send, dry: !_send, again: _send && _b.again === true }));
      }
      // Lista de OC sin pagar por vendedor. POST {} = PREVIEW (no manda nada). {send:true[, vendedor, again]} = la manda
      // YA (aunque el kill-switch lista_oc_on esté apagado). Solo Gaspar.
      if (request.method === 'POST' && path === '/admin/lista-oc-test') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        const _b = (await request.json().catch(() => null)) || {};
        const _send = _b.send === true;
        const _v = LISTA_OC_VEND.some(v => v.slug === _b.vendedor) ? _b.vendedor : undefined;
        return json(await maybeListaOC(env, { force: _send, dry: !_send, again: _send && _b.again === true, vendedor: _v }));
      }
      // Forzar el aviso "leads para llamar" AHORA (para probarlo fuera del cron de las 9 AR).
      // Resetea el dedup del día y ejecuta la función real (plantilla + fallback a texto).
      if (request.method === 'POST' && path === '/admin/reporte-llamar-test') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        await kvSet(env, 'reporte_llamar_sent', '');
        await maybeReporteLlamar(env);
        return json({ ok: true, forced: true });
      }

      // Recuperar FUPs perdidos: presupuestos recientes SIN seguimiento efectivo (sin FUP
      // 'sent', sin respuesta del cliente, sin cierre). GET = dry-run (lista sin mandar).
      // POST {ejecutar:true, dias?, limit?} = re-manda el FUP por plantilla seguimiento_presupuesto
      // (sale fuera de ventana), con goteo (delay) y respetando wa_send_paused.
      if (path === '/admin/recuperar-fups') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        let body = {}; if (request.method === 'POST') { try { body = await request.json(); } catch (_) {} }
        const dias = Math.max(1, Math.min(14, parseInt(body.dias, 10) || 7));
        const desde = new Date(Date.now() - dias * 24 * 3600 * 1000).toISOString();
        // Solo presupuestos cuyo FUP1 YA venció (>23h): los de hoy los agarra el cron normal.
        const venc = new Date(Date.now() - 23 * 3600 * 1000).toISOString();
        const pfx1 = PRESUPUESTO_PREFIXES_TEXT[0].substring(0, 26);
        const pfx2 = PRESUPUESTO_PREFIXES_TEXT[1].substring(0, 26);
        const fupLike = ALL_FOLLOWUP_PREFIXES_TEXT.map(() => "f.body LIKE ? ESCAPE '\\'").join(' OR ');
        const fupParams = ALL_FOLLOWUP_PREFIXES_TEXT.map(pref => pref.replace(/([%_\\])/g, '\\$1') + '%');
        const cierreLike = FUP_CIERRE_MARKERS.map(() => "lower(c.body) LIKE ?").join(' OR ');
        const cierreParams = FUP_CIERRE_MARKERS.map(k => '%' + k.toLowerCase() + '%');
        const sql =
          "WITH presup AS (SELECT phone, MAX(ts) AS pts FROM wa_messages " +
          "  WHERE direction='outbound' AND ts >= ? AND (substr(body,1,26)=? OR substr(body,1,26)=?) " +
          "    AND length(phone) BETWEEN 10 AND 14 GROUP BY phone) " +
          "SELECT pr.phone, pr.pts, " +
          "  (SELECT x.sender_name FROM wa_messages x WHERE x.phone=pr.phone AND x.direction='outbound' AND x.ts=pr.pts LIMIT 1) AS nombre, " +
          "  (SELECT x.body FROM wa_messages x WHERE x.phone=pr.phone AND x.direction='outbound' AND x.ts=pr.pts LIMIT 1) AS body " +
          "FROM presup pr " +
          "WHERE NOT EXISTS (SELECT 1 FROM wa_messages f WHERE f.phone=pr.phone AND f.direction='outbound' AND f.automated=1 AND IFNULL(f.status,'')!='failed' AND f.ts > pr.pts AND (" + fupLike + ")) " +
          "  AND NOT EXISTS (SELECT 1 FROM wa_messages i WHERE i.phone=pr.phone AND i.direction='inbound' AND i.msg_type!='status' AND i.ts > pr.pts) " +
          "  AND NOT EXISTS (SELECT 1 FROM wa_messages c WHERE c.phone=pr.phone AND c.direction='outbound' AND (" + cierreLike + ")) " +
          "  AND pr.phone NOT IN (SELECT phone FROM wa_unreachable_phones) " +
          "  AND pr.pts < ? " +
          "ORDER BY pr.pts DESC LIMIT 250";
        let rows = [];
        try { rows = (await env.DB.prepare(sql).bind(desde, pfx1, pfx2, ...fupParams, ...cierreParams, venc).all()).results || []; } catch (e) { return json({ error: 'query: ' + e.message }, 500); }
        const leads = rows.map(r => ({ phone: r.phone, nombre: (r.nombre || '').split(/\s+/)[0] || '', fecha: (r.pts || '').slice(0, 10), monto: extractPresupuestoAmount(r.body) }));
        if (request.method === 'POST' && body.ejecutar === true) {
          const limit = Math.max(1, Math.min(250, parseInt(body.limit, 10) || 50));
          let ok = 0, fail = 0;
          for (const lead of leads.slice(0, limit)) {
            if ((await kvGet(env, 'wa_send_paused', '0')) === '1') break;
            const firstName = capitalizeName(lead.nombre) || 'amigo/a';
            let rt = null;
            try { rt = await waSendTemplate(env, lead.phone, 'seguimiento_presupuesto', 'es_AR', [firstName]); } catch (_) {}
            if (rt && rt.ok) {
              ok++;
              try { await env.DB.prepare("INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, status, context_id, automated) VALUES (?, ?, 'outbound', ?, '', 'template', '[plantilla: seguimiento_presupuesto]', 'sent', '', 1)").bind(new Date().toISOString(), rt.id || ('fu-recover:' + lead.phone), lead.phone).run(); } catch (_) {}
            } else { fail++; }
            await new Promise(rs => setTimeout(rs, 500));
          }
          return json({ ok: true, ejecutado: true, enviados: ok, fallidos: fail, pendientes_restantes: leads.length - ok });
        }
        return json({ ok: true, dry_run: true, dias, total: leads.length, leads: leads.slice(0, 80) });
      }

      // Backfill de los mensajes automáticos de ManyChat (welcome) que Instagram nos mandó
      // como echo VACÍO (solo el mid, sin texto) y por eso nunca se guardaron -> las convos
      // de IG arrancaban "cortadas". Recorre los logs crudos en orden cronológico: el PRIMER
      // echo vacío de cada chat = welcome (texto fijo IG_MANYCHAT_WELCOME); los siguientes ->
      // marcador genérico. SOLO toca chats donde el lead respondió (>=1 inbound) para no
      // llenar la bandeja con seguidores que recibieron el welcome y nunca contestaron.
      // Idempotente: INSERT OR IGNORE por mid. El trigger no ensucia el orden (ts viejo).
      if (request.method === 'POST' && path === '/admin/ig/backfill-manychat') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        const out = { postbacks: 0, welcomes: 0, marcadores: 0, corregidos: 0, regalos: 0, skipped: 0 };
        try {
          // ===== PASO 1: postbacks históricos ("Quiero el regalo 🎁") -> inbound =====
          // Instagram manda el toque de botón como postback, no como message, así que nunca se
          // guardó. Lo reponemos como inbound para que se vea la interacción y el chat cuente
          // como "respondió" (además así el PASO 2 incluye a esos chats).
          const pbRs = await env.DB.prepare(
            "SELECT ts, payload FROM wa_webhook_log WHERE payload LIKE 'IG:%' AND payload LIKE '%postback%' ORDER BY ts ASC"
          ).all();
          const pbIns = env.DB.prepare("INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status, channel) VALUES (?, ?, 'inbound', ?, '', 'text', ?, '', '', '', 'ig')");
          const pbStmts = [];
          for (const row of (pbRs.results || [])) {
            let obj; try { const raw = String(row.payload || ''); obj = JSON.parse(raw.slice(raw.indexOf('{'))); } catch (_) { continue; }
            for (const entry of (obj?.entry || [])) {
              for (const m of (entry?.messaging || [])) {
                const pb = m?.postback; if (!pb || m?.message) continue;
                const cust = m?.sender?.id; if (!cust) continue;
                const mid = pb.mid || ('ig-pb-' + cust + '-' + (m.timestamp || ''));
                const ts = m.timestamp ? new Date(m.timestamp).toISOString() : String(row.ts);
                const title = String(pb.title || '').replace(/\s+/g, ' ').trim();
                out.postbacks++;
                pbStmts.push(pbIns.bind(ts, mid, cust, '👆 Tocó el botón: ' + (title || '(botón)')));
              }
            }
          }
          for (let i = 0; i < pbStmts.length; i += 50) { await env.DB.batch(pbStmts.slice(i, i + 50)); }

          // ===== PASO 2: welcomes/marcadores de los echo vacíos (chats con interacción) =====
          // conInbound ahora incluye los postbacks recién insertados (Luciana y cía. ya cuentan).
          const conInbound = new Set();
          const ib = await env.DB.prepare("SELECT DISTINCT phone FROM wa_messages WHERE channel='ig' AND direction='inbound'").all();
          for (const r of (ib.results || [])) conInbound.add(String(r.phone));
          const yaWelcome = new Set();
          const ex = await env.DB.prepare("SELECT DISTINCT phone FROM wa_messages WHERE channel='ig' AND body LIKE 'Buenas! Te mandamos mensajito%'").all();
          for (const r of (ex.results || [])) yaWelcome.add(String(r.phone));
          const rs = await env.DB.prepare(
            "SELECT ts, payload FROM wa_webhook_log WHERE payload LIKE 'IG:%' AND payload LIKE '%is_echo%' AND payload NOT LIKE '%\"text\"%' AND payload NOT LIKE '%attachments%' ORDER BY ts ASC"
          ).all();
          const insSql = env.DB.prepare("INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status, channel) VALUES (?, ?, 'outbound', ?, '', 'text', ?, '', '', '', 'ig')");
          const stmts = [];
          for (const row of (rs.results || [])) {
            let obj; try { const raw = String(row.payload || ''); obj = JSON.parse(raw.slice(raw.indexOf('{'))); } catch (_) { continue; }
            for (const entry of (obj?.entry || [])) {
              for (const m of (entry?.messaging || [])) {
                const msg = m?.message;
                if (!msg || !msg.is_echo) continue;
                if (msg.text || (Array.isArray(msg.attachments) && msg.attachments.length)) continue;
                const custId = m?.recipient?.id;
                if (!custId) continue;
                if (!conInbound.has(String(custId))) { out.skipped++; continue; }
                const mid = msg.mid || ('ig-' + custId + '-' + (m.timestamp || ''));
                const ts = m.timestamp ? new Date(m.timestamp).toISOString() : String(row.ts);
                if (!yaWelcome.has(String(custId))) {
                  yaWelcome.add(String(custId)); out.welcomes++;
                  stmts.push(insSql.bind(ts, mid, custId, IG_MANYCHAT_WELCOME));
                } else {
                  out.marcadores++;
                  stmts.push(insSql.bind(ts, mid, custId, '🤖 Mensaje automático (ManyChat)'));
                }
              }
            }
          }
          for (let i = 0; i < stmts.length; i += 50) { await env.DB.batch(stmts.slice(i, i + 50)); }

          // ===== PASO 3: corregir el PRIMER saliente de cada chat que quedó como marcador =====
          // Los chats procesados antes del welcome real (ventana entre deploys) tienen su welcome
          // como marcador genérico. El 1er saliente de un chat de IG siempre es el welcome, así
          // que lo pisamos con el texto real. Idempotente (si ya es welcome, no matchea).
          const upd = await env.DB.prepare(
            "UPDATE wa_messages SET body = ? WHERE id IN (SELECT id FROM (SELECT id, ROW_NUMBER() OVER (PARTITION BY phone ORDER BY ts ASC, id ASC) rn FROM wa_messages WHERE channel='ig' AND direction='outbound') WHERE rn = 1) AND body = '🤖 Mensaje automático (ManyChat)'"
          ).bind(IG_MANYCHAT_WELCOME).run();
          out.corregidos = (upd.meta && upd.meta.changes) || 0;

          // ===== PASO 4: reponer la respuesta al regalo (2º saliente tras "Quiero el regalo") =====
          // El echo vacío que sigue al toque del botón es la respuesta con la formación gratuita.
          // Heurística: el 2º saliente del chat, si quedó genérico y el chat tiene ese postback.
          const updR = await env.DB.prepare(
            "UPDATE wa_messages SET body = ? WHERE id IN (SELECT id FROM (SELECT id, ROW_NUMBER() OVER (PARTITION BY phone ORDER BY ts ASC, id ASC) rn FROM wa_messages WHERE channel='ig' AND direction='outbound') WHERE rn = 2) AND body = '🤖 Mensaje automático (ManyChat)' AND phone IN (SELECT phone FROM wa_messages WHERE channel='ig' AND direction='inbound' AND body LIKE '%Quiero el regalo%')"
          ).bind(IG_MANYCHAT_REGALO).run();
          out.regalos = (updR.meta && updR.meta.changes) || 0;

          return json({ ok: true, ...out });
        } catch (e) { return json({ error: String(e && e.message || e), ...out }, 500); }
      }

      // Backfill: manda a la bandeja de Abril (cursos) los chats de IG que recibieron el
      // opener/contenido de cursos pero quedaron en 'general' (leads de cursos que entran por
      // IG, históricamente mal ruteados por clasificarse por el texto de su respuesta).
      // Idempotente y seguro: solo promueve general/oculto -> cursos (no pisa asignación manual).
      if (request.method === 'POST' && path === '/admin/ig/reclasify-cursos') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        try {
          const r = await env.DB.prepare(
            "UPDATE wa_chats_summary SET inbox='cursos', updated_at = ? WHERE channel='ig' AND inbox IN ('general','oculto') AND phone IN (SELECT DISTINCT phone FROM wa_messages WHERE channel='ig' AND (body LIKE '%neoninfinito.com%' OR body LIKE '%mastery%' OR body LIKE '%minicurso%' OR body LIKE '%curso gratuito%' OR body LIKE '%comunidad al infinito%' OR body LIKE '%supernova%'))"
          ).bind(new Date().toISOString()).run();
          return json({ ok: true, updated: r.meta && r.meta.changes });
        } catch (e) { return json({ error: String(e && e.message || e) }, 500); }
      }

      // Sincroniza el mapa de anuncios de IG (media_id -> ad_id/campaña) desde Meta Ads.
      // Devuelve el diagnóstico (sirve para ver si el token tiene permiso ads_read).
      if (request.method === 'POST' && path === '/admin/ig/sync-ad-map') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        const res = await syncIgAdMap(env);
        return json(res, res.ok ? 200 : 502);
      }

      // Sincroniza/backfillea el mapa de campañas de Meta para leads de CTWA (WhatsApp). Resuelve
      // los ad_id de wa_ad_attributions -> nombre de campaña/ad y rellena las columnas (venían NULL).
      // Forzable a mano para backfillear el histórico (procesa hasta `limit` ad_ids por corrida,
      // default 80; correr varias veces hasta que resolved/seen den 0).
      if (request.method === 'POST' && path === '/admin/meta/sync-ad-map') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        let _b = {}; try { _b = await request.json(); } catch (_) {}
        const res = await syncMetaAdMap(env, { limit: _b && _b.limit });
        return json(res, res.ok ? 200 : 502);
      }

      // Enviar un DM de IG (texto). Lo dispara el chat cuando el contacto es de Instagram.
      // Valida la ventana de 24h ANTES de mandar (IG no permite texto libre fuera de ella;
      // a diferencia de WhatsApp, IG no tiene plantillas para reabrir). El que envía es una
      // persona desde el chat: nada automático.
      if (request.method === 'POST' && path === '/admin/ig/send') {
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { to, text } = body || {};
        if (!to || !text) return json({ error: 'missing fields (to, text)' }, 400);
        const igId = String(to);
        // Rol 'cursos' (Abril) solo puede escribir a chats de su bandeja.
        {
          const _role = await getSessionRole(env, session.user);
          if (!(await inboxAccessOk(env, _role, igId, session.user))) {
            return json({ error: 'forbidden: chat fuera de tu bandeja' }, 403);
          }
        }
        // Ventana de 24h: tomamos el último mensaje ENTRANTE de IG de este contacto.
        let lastTs = 0;
        try {
          const lastIn = await env.DB.prepare("SELECT MAX(ts) AS ts FROM wa_messages WHERE phone=? AND direction='inbound' AND channel='ig'").bind(igId).first();
          lastTs = lastIn && lastIn.ts ? new Date(lastIn.ts).getTime() : 0;
        } catch (_) {}
        if (!(lastTs && (Date.now() - lastTs) < 24 * 3600 * 1000)) {
          return json({ error: 'Ventana de 24 h cerrada: el cliente no escribió en las últimas 24 h. Instagram no permite mandar fuera de la ventana.', window_closed: true }, 409);
        }
        const r = await igSend(env, igId, text);
        await logWaEvent(env, { to: igId, kind: 'ig-text', ref: '', ok: r.ok, messageId: r.id, error: r.error });
        if (!r.ok) return json({ error: r.error, raw: r.raw }, 500);
        try {
          // sender_name = quién lo escribió (igual que /admin/wa/send). Upsert: si el eco del webhook llegó antes y
          // creó la fila sin autor, se lo completa (con INSERT OR IGNORE se perdía 1 de cada 9).
          await env.DB.prepare(
            "INSERT INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status, channel) VALUES (?, ?, 'outbound', ?, ?, 'text', ?, '', '', 'sent', 'ig') ON CONFLICT(wamid) DO UPDATE SET sender_name = excluded.sender_name WHERE IFNULL(wa_messages.sender_name, '') = ''"
          ).bind(new Date().toISOString(), r.id || ('ig-txt-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6)), igId, autorSlug(session.user), String(text)).run();
          // Aseguramos que el resumen quede marcado como IG (el trigger no toca channel).
          await env.DB.prepare("UPDATE wa_chats_summary SET channel='ig' WHERE phone=?").bind(igId).run();
        } catch (_) {}
        return json({ id: r.id });
      }

      // Enviar una FOTO por IG. Sube a R2, arma la URL publica (/admin/media/, sin
      // auth) y la manda por la Graph API. Caption (si hay) va como texto aparte.
      if (request.method === 'POST' && path === '/admin/ig/send-media') {
        const ctIg = request.headers.get('Content-Type') || '';
        if (!ctIg.includes('multipart/form-data')) return json({ error: 'expected multipart/form-data' }, 400);
        if (!env.MEDIA) return json({ error: 'R2 not configured' }, 500);
        const fd = await request.formData();
        const igId = String(fd.get('to') || '');
        const caption = fd.get('caption') || '';
        const file = fd.get('file');
        if (!igId || !file) return json({ error: 'missing to or file' }, 400);
        { const _role = await getSessionRole(env, session.user); if (!(await inboxAccessOk(env, _role, igId, session.user))) return json({ error: 'forbidden: chat fuera de tu bandeja' }, 403); }
        const fileMime = (file.type || '').split(';')[0].trim();
        const isImg = fileMime.startsWith('image/');
        const isAud = fileMime.startsWith('audio/');
        if (!isImg && !isAud) return json({ error: 'Por IG solo se pueden mandar imagenes o audios por ahora' }, 400);
        let lastTs = 0;
        try { const lastIn = await env.DB.prepare("SELECT MAX(ts) AS ts FROM wa_messages WHERE phone=? AND direction='inbound' AND channel='ig'").bind(igId).first(); lastTs = lastIn && lastIn.ts ? new Date(lastIn.ts).getTime() : 0; } catch (_) {}
        if (!(lastTs && (Date.now() - lastTs) < 24 * 3600 * 1000)) return json({ error: 'Ventana de 24 h cerrada: el cliente no escribio en las ultimas 24 h. Instagram no permite mandar fuera de la ventana.', window_closed: true }, 409);
        const fileName = file.name || ((isAud ? 'aud_' : 'img_') + Date.now());
        const ext = fileName.includes('.') ? '.' + fileName.split('.').pop() : (isAud ? '.m4a' : '.jpg');
        const r2Key = `ig/out_${Date.now()}_${Math.random().toString(36).slice(2, 7)}${ext}`;
        await env.MEDIA.put(r2Key, await file.arrayBuffer(), { httpMetadata: { contentType: fileMime } });
        const mediaUrl = new URL(request.url).origin + '/admin/media/' + r2Key;
        const r = isAud ? await igSendAudio(env, igId, mediaUrl) : await igSendImage(env, igId, mediaUrl);
        await logWaEvent(env, { to: igId, kind: isAud ? 'ig-audio' : 'ig-image', ref: r2Key, ok: r.ok, messageId: r.id, error: r.error });
        if (!r.ok) return json({ error: r.error, raw: r.raw }, 500);
        const ts = new Date().toISOString();
        const mtype = isAud ? 'audio' : 'image';
        try {
          await env.DB.prepare("INSERT INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status, channel) VALUES (?, ?, 'outbound', ?, ?, ?, '', ?, '', 'sent', 'ig') ON CONFLICT(wamid) DO UPDATE SET sender_name = excluded.sender_name WHERE IFNULL(wa_messages.sender_name, '') = ''").bind(ts, r.id || ('ig-med-' + Date.now()), igId, autorSlug(session.user), mtype, r2Key).run();
          await env.DB.prepare("UPDATE wa_chats_summary SET channel='ig' WHERE phone=?").bind(igId).run();
        } catch (_) {}
        if (caption && String(caption).trim()) {
          const rc = await igSend(env, igId, String(caption));
          if (rc && rc.ok) { try { await env.DB.prepare("INSERT INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status, channel) VALUES (?, ?, 'outbound', ?, ?, 'text', ?, '', '', 'sent', 'ig') ON CONFLICT(wamid) DO UPDATE SET sender_name = excluded.sender_name WHERE IFNULL(wa_messages.sender_name, '') = ''").bind(new Date().toISOString(), rc.id || ('ig-cap-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6)), igId, autorSlug(session.user), String(caption)).run(); } catch (_) {} }
        }
        return json({ id: r.id, r2Key, media_url: r2Key });
      }

      // ===== Enviar presupuesto de un brief por DM de Instagram =====
      // body: { brief_id, to (=IGSID), caption }. Espejo de /admin/wa/send-brief-presupuesto
      // pero por IG: manda el render como IMAGEN + el presupuesto como TEXTO aparte (IG no
      // lleva caption en el attachment). Respeta la ventana de 24 h de IG (SIN plantilla de
      // rescate, a diferencia de WhatsApp). El render (briefs/<id>/render-...) se COPIA a una
      // key ig/out_ porque la ruta pública sin-auth solo sirve esas (IG baja la imagen sin token).
      if (request.method === 'POST' && path === '/admin/ig/send-brief-presupuesto') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { brief_id, to, caption } = body || {};
        if (!to || !caption) return json({ error: 'missing to or caption' }, 400);
        if (!env.MEDIA) return json({ error: 'R2 not configured' }, 500);
        const igId = String(to).replace(/\D/g, '');
        if (igId.length < 15) return json({ error: 'IGSID invalido' }, 400);
        { const _role = await getSessionRole(env, session.user); if (!(await inboxAccessOk(env, _role, igId, session.user))) return json({ error: 'forbidden: chat fuera de tu bandeja' }, 403); }
        // Ventana de 24 h de IG (el cliente escribió en las últimas 24 h). Sin rescate por plantilla.
        let lastTs = 0;
        try { const lastIn = await env.DB.prepare("SELECT MAX(ts) AS ts FROM wa_messages WHERE phone=? AND direction='inbound' AND channel='ig'").bind(igId).first(); lastTs = lastIn && lastIn.ts ? new Date(lastIn.ts).getTime() : 0; } catch (_) {}
        if (!(lastTs && (Date.now() - lastTs) < 24 * 3600 * 1000)) return json({ error: 'Ventana de 24 h de Instagram cerrada: el cliente no escribio en las ultimas 24 h.', window_closed: true }, 409);
        // Render más reciente del brief.
        let renderKey = null;
        if (brief_id) {
          try { const row = await env.DB.prepare("SELECT r2_key FROM brief_imagenes WHERE brief_id=? AND tipo='render' ORDER BY created_at DESC, id DESC LIMIT 1").bind(brief_id).first(); if (row && row.r2_key) renderKey = row.r2_key; } catch (_) {}
        }
        const senderSlug = await resolveComercial(env, { sessionUser: session.user, phone: igId });
        const saveIg = async (wamid, mtype, bodyTxt, mediaKey) => {
          try {
            await env.DB.prepare(
              "INSERT INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status, channel) VALUES (?, ?, 'outbound', ?, ?, ?, ?, ?, '', 'sent', 'ig') ON CONFLICT(wamid) DO UPDATE SET sender_name = excluded.sender_name WHERE IFNULL(wa_messages.sender_name, '') = ''"
            ).bind(new Date().toISOString(), wamid || ('ig-brief-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6)), igId, senderSlug, mtype, bodyTxt, mediaKey || '').run();
          } catch (_) {}
        };
        // 1) Render como imagen: copiar el blob a una key pública ig/out_ y mandarlo por IG.
        let usedImage = false;
        if (renderKey) {
          try {
            const obj = await env.MEDIA.get(renderKey);
            if (obj) {
              const ct = obj.httpMetadata?.contentType || 'image/jpeg';
              const igKey = `ig/out_render_${Date.now()}_${Math.random().toString(36).slice(2, 7)}.jpg`;
              await env.MEDIA.put(igKey, await obj.arrayBuffer(), { httpMetadata: { contentType: ct } });
              const mediaUrl = new URL(request.url).origin + '/admin/media/' + igKey;
              const ri = await igSendImage(env, igId, mediaUrl);
              await logWaEvent(env, { to: igId, kind: 'ig-image', ref: 'brief:' + (brief_id || ''), ok: ri.ok, messageId: ri.id, error: ri.error });
              if (!ri.ok) return json({ error: ri.error || 'ig image send failed', raw: ri.raw }, 500);
              usedImage = true;
              await saveIg(ri.id, 'image', '', igKey);
            }
          } catch (e) { return json({ error: 'ig image error: ' + String(e && e.message || e) }, 500); }
        }
        // 2) Presupuesto como texto (mensaje aparte).
        const rt = await igSend(env, igId, String(caption));
        await logWaEvent(env, { to: igId, kind: 'ig-text', ref: 'brief:' + (brief_id || ''), ok: rt.ok, messageId: rt.id, error: rt.error });
        if (!rt.ok) return json({ error: rt.error || 'ig text send failed', raw: rt.raw, image_sent: usedImage }, 500);
        await saveIg(rt.id, 'text', String(caption), '');
        try { await env.DB.prepare("UPDATE wa_chats_summary SET channel='ig' WHERE phone=?").bind(igId).run(); } catch (_) {}
        return json({ id: rt.id, hasImage: usedImage });
      }

      // ===== WA LABELS BULK IMPORT (desde el scraper) =====
      // Body: { labels: [{name, color}], assignments: [{phone, labelName}], replaceAll?: bool }
      // Si replaceAll=true → borra TODAS las assignments antes de insertar (sync limpio).
      // Las labels se hacen upsert (mantiene id existente si ya está, actualiza color).
      if (request.method === 'POST' && path === '/admin/wa/labels/import-bulk') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { labels, assignments, replaceAll } = body || {};
        await env.DB.prepare('CREATE TABLE IF NOT EXISTS labels (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, color TEXT NOT NULL, created_at TEXT NOT NULL)').run();
        await env.DB.prepare('CREATE TABLE IF NOT EXISTS contact_labels (phone TEXT NOT NULL, label_id INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (phone, label_id))').run();
        const now = new Date().toISOString();
        const nameToId = new Map();
        let labelsCreated = 0, labelsUpdated = 0, assignmentsCreated = 0, assignmentsSkipped = 0;

        // 1) Upsert labels
        if (Array.isArray(labels)) {
          for (const l of labels) {
            const name = String(l?.name || '').trim();
            const color = String(l?.color || '#42a5f5').trim();
            if (!name) continue;
            try {
              const existing = await env.DB.prepare('SELECT id FROM labels WHERE name = ?').bind(name).first();
              if (existing) {
                await env.DB.prepare('UPDATE labels SET color = ? WHERE id = ?').bind(color, existing.id).run();
                nameToId.set(name, existing.id);
                labelsUpdated++;
              } else {
                await env.DB.prepare('INSERT INTO labels (name, color, created_at) VALUES (?, ?, ?)').bind(name, color, now).run();
                const row = await env.DB.prepare('SELECT id FROM labels WHERE name = ?').bind(name).first();
                if (row) nameToId.set(name, row.id);
                labelsCreated++;
              }
            } catch (_) {}
          }
        }

        // 2) Si replaceAll → limpiar assignments existentes para sync limpio
        if (replaceAll === true) {
          await env.DB.prepare('DELETE FROM contact_labels').run();
        }

        // 3) Upsert assignments
        if (Array.isArray(assignments)) {
          for (const a of assignments) {
            const rawPhone = a?.phone || '';
            const phone = normalizeArPhone(rawPhone) || String(rawPhone).replace(/\D/g, '');
            const labelName = String(a?.labelName || '').trim();
            if (!phone || !labelName) { assignmentsSkipped++; continue; }
            let lid = nameToId.get(labelName);
            if (!lid) {
              const row = await env.DB.prepare('SELECT id FROM labels WHERE name = ?').bind(labelName).first();
              if (row) { lid = row.id; nameToId.set(labelName, lid); }
            }
            if (!lid) { assignmentsSkipped++; continue; }
            try {
              await env.DB.prepare(
                'INSERT OR IGNORE INTO contact_labels (phone, label_id, created_at) VALUES (?, ?, ?)'
              ).bind(phone, lid, now).run();
              assignmentsCreated++;
            } catch (_) { assignmentsSkipped++; }
          }
        }
        return json({ ok: true, labelsCreated, labelsUpdated, assignmentsCreated, assignmentsSkipped });
      }

      // ===== BUSINESS PANEL (solo Gaspar) =====
      // Lee el Sheet "2025 V4" (PnL + 6 hojas detalle), parsea y devuelve JSON.
      // Cachea 1h en D1 para no tirar del Sheet en cada visita.
      if (request.method === 'GET' && path === '/admin/business-panel') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        const force = url.searchParams.get('force') === '1';
        // Cache check
        await env.DB.prepare('CREATE TABLE IF NOT EXISTS panel_cache (k TEXT PRIMARY KEY, v TEXT NOT NULL, updated_at TEXT NOT NULL)').run();
        if (!force) {
          const cached = await env.DB.prepare('SELECT v, updated_at FROM panel_cache WHERE k = ?').bind('business_panel_v2_noneon').first();
          if (cached) {
            const age = Date.now() - new Date(cached.updated_at).getTime();
            if (age < 60 * 60 * 1000) {
              return json({ ...JSON.parse(cached.v), _cached: true, _cache_age_s: Math.floor(age / 1000) });
            }
          }
        }
        // Fetch all 7 sheets in parallel via public gviz CSV.
        const SID = '1PLG-vosgVtvhYYaBLi5Rh-LM6f2A_BvG3i6-a7NpNCE';
        const fetchSheet = async (name, range) => {
          const u = `https://docs.google.com/spreadsheets/d/${SID}/gviz/tq?tqx=out:csv&sheet=${encodeURIComponent(name)}${range ? '&range=' + range : ''}`;
          const r = await fetch(u);
          if (!r.ok) return '';
          return await r.text();
        };
        const [pnlCsv, dirCsv, disCsv, insCsv, curCsv] = await Promise.all([
          fetchSheet('PnL', 'A1:Q15'),
          fetchSheet('Pedidos_Directo'),
          fetchSheet('Pedidos_Distris'),
          fetchSheet('Venta_Insumos'),
          fetchSheet('CURSOS'),
        ]);
        const data = parsePanelData({ pnlCsv, dirCsv, disCsv, insCsv, curCsv });
        const payload = JSON.stringify({ ts: new Date().toISOString(), ...data });
        try {
          await env.DB.prepare('INSERT OR REPLACE INTO panel_cache (k, v, updated_at) VALUES (?, ?, ?)')
            .bind('business_panel_v2_noneon', payload, new Date().toISOString()).run();
        } catch (_) {}
        return new Response(payload, { headers: cors({ 'Content-Type': 'application/json' }) });
      }

      if (request.method === 'POST' && path === '/admin/wa/followups') {
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const items = Array.isArray(body?.items) ? body.items : null;
        if (!items) return json({ error: 'missing items[]' }, 400);
        const result = await runFollowups(env, items);
        return json(result);
      }

      // ===== CHATS SUMMARY: una fila por phone con último mensaje + unread =====
      // ===== Ad Attribution: contexto del ad que originó el primer contacto =====
      // GET /admin/wa/ad-attribution?phone=549XXXXXXXXXX → último ad referral
      // POST /admin/wa/ad-attributions/list → lista resumida agregada por source_id
      if (request.method === 'GET' && path === '/admin/wa/ad-attribution') {
        const phone = url.searchParams.get('phone') || '';
        if (!phone) return json({ error: 'missing phone' }, 400);
        try {
          const row = await env.DB.prepare(
            'SELECT * FROM wa_ad_attributions WHERE phone = ? ORDER BY ts DESC LIMIT 1'
          ).bind(phone).first();
          // Atribución "dura" (con ad_id de Meta) para que el modal de Cargar pedido guarde el
          // source_id y trace bien en el funnel. MISMA regla que traceAdForPedido (último touch
          // CON source_id no vacío — el más reciente puede ser un referral sin ad_id). ad_label =
          // label de vertical ya resuelto server-side (adLabelFromSource) para no duplicar lógica
          // en el front; queda '' para ads de cursos (que no se atribuyen a carteles).
          let source_id = '', ad_label = '';
          try {
            const src = await env.DB.prepare("SELECT source_id, headline FROM wa_ad_attributions WHERE phone=? AND COALESCE(source_id,'')!='' ORDER BY ts DESC LIMIT 1").bind(phone).first();
            if (src && src.source_id) { source_id = String(src.source_id); ad_label = adLabelFromSource(source_id, src.headline); }
          } catch (_) {}
          return json({ attribution: row || null, source_id, ad_label });
        } catch (e) {
          return json({ attribution: null, error: e.message });
        }
      }
      if (request.method === 'GET' && path === '/admin/wa/ad-attributions/summary') {
        // Para dashboard futuro: agregado por source_id con counts.
        try {
          const rs = await env.DB.prepare(`
            SELECT source_id, source_type, headline,
                   COUNT(*) AS leads,
                   COUNT(DISTINCT phone) AS unique_contacts,
                   MIN(ts) AS first_lead_ts,
                   MAX(ts) AS last_lead_ts
            FROM wa_ad_attributions
            GROUP BY source_id
            ORDER BY last_lead_ts DESC
          `).all();
          return json({ ads: rs.results || [] });
        } catch (e) {
          return json({ ads: [], error: e.message });
        }
      }

      // Reemplaza el patrón anterior de pedir limit=5000 mensajes para armar la
      // lista de chats. Devuelve 1 fila por phone con: last_ts, last_body,
      // last_direction, last_msg_type, contact_name (último sender_name inbound
      // no vacío), unread (count inbound > last_read_ts).
      // Mucho más liviano y escala con la cantidad de chats, no de mensajes.
      if (request.method === 'GET' && path === '/admin/wa/chats-summary') {
        // === Lista de chats: lee de la libreta resumen wa_chats_summary ===
        // La libreta tiene 1 fila por chat (último msg + no leídos + nombre),
        // mantenida al día por el trigger trg_wa_chats_summary_ins. Leerla es
        // ~unas cientos de filas (vs ~440k de la query vieja con ROW_NUMBER).
        // RED DE SEGURIDAD: si la libreta está vacía (no migrada) o falla, se
        // usa la query vieja (CHATS_SUMMARY_FALLBACK_SQL) — así nunca se rompe.
        // Cache corto (5s) en Workers Cache API; mark-read invalida la cache.
        // Rol del usuario → qué bandeja ve. Cache POR ROL (cada rol ve una
        // lista distinta: Abril solo 'cursos', Joaco todo menos 'cursos',
        // Gaspar todo). Sin esto, el cache mezclaría las listas entre usuarios.
        const role = await getSessionRole(env, session.user);
        // Slug normalizado del usuario (para el reparto por vendedor: Nadia ve solo lo suyo).
        const uslug = String(session.user || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
        const esSecundario = role === 'comercial' && VENDEDORES_SECUNDARIOS.includes(uslug);
        const cache = caches.default;
        const cacheUrl = new URL(request.url);
        // El rol comercial se cachea POR USUARIO (Joaco y Nadia ven listas distintas).
        cacheUrl.search = '?role=' + encodeURIComponent(role) + (role === 'comercial' ? '&u=' + encodeURIComponent(uslug) : '');
        const cacheKey = new Request(cacheUrl.toString(), { method: 'GET' });
        const cached = await cache.match(cacheKey);
        if (cached) return cached;
        await ensurePinPrivadoCol(env);   // garantiza la columna pin_privado antes del SELECT (auto-heal)
        const inboxClause = inboxClauseForRole(role);
        // Reparto por vendedor (solo comercial): el secundario (Nadia) ve SOLO lo asignado a
        // él; el principal (Joaco) ve todo lo NO asignado a un secundario. uslug se interpola
        // solo cuando es un secundario conocido (lista fija VENDEDORES_SECUNDARIOS) -> seguro.
        let assignClause = '';
        if (role === 'comercial') {
          assignClause = esSecundario
            ? ` AND assigned_to = '${uslug}'`
            : ` AND assigned_to NOT IN (${VENDEDORES_SECUNDARIOS.map(s => `'${s}'`).join(',')})`;
        }
        let chats = null;
        try {
          const rs = await env.DB.prepare(
            `SELECT phone, last_ts, last_body, last_direction, last_msg_type, contact_name, unread, inbox, channel, assigned_to, pin_privado
             FROM wa_chats_summary
             WHERE last_ts != '' AND NOT (channel = 'ig' AND has_inbound = 0) ${inboxClause}${assignClause}
             ORDER BY last_ts DESC`
          ).all();
          chats = rs.results || [];
          // Si la libreta está vacía (ej. base sin migrar), caer al fallback.
          if (!chats.length) chats = null;
        } catch (e) { chats = null; }
        // Fallback a la query vieja (red de seguridad). No tiene info de bandeja ni asignación:
        // para 'cursos' y para vendedores SECUNDARIOS (Nadia) devolvemos vacío (no se puede
        // saber cuáles son suyos sin la libreta); admin/Joaco reciben la lista completa.
        if (chats === null) {
          if (role === 'cursos' || esSecundario) {
            chats = [];
          } else {
            try {
              const fb = await env.DB.prepare(CHATS_SUMMARY_FALLBACK_SQL).all();
              chats = fb.results || [];
            } catch (e) {
              return json({ chats: [], error: e.message }, 500);
            }
          }
        }
        // Los chats del EQUIPO con el número del negocio (avisos internos, listas, reportes) no se le muestran a nadie
        // que no sea admin: cada aviso sube ese chat al tope de una bandeja operativa (Bruno en 'cursos', Agus y
        // Joaco en 'general'). Filtro en memoria contra internosSet (caché 10 min): no le suma filas leídas a la query.
        if (role !== 'admin' && chats && chats.length) {
          try { const _I = await internosSet(env); chats = chats.filter(c => !_I.set.has(String(c.phone || '').replace(/\D/g, ''))); } catch (_) {}
        }
        const response = json({ chats });
        response.headers.set('Cache-Control', 'public, max-age=5');
        ctx.waitUntil(cache.put(cacheKey, response.clone()));
        return response;
      }

      // Análisis individual de un chat con Claude. model=sonnet|opus.
      // GET para que sea fácil disparar desde browser/curl, idempotente por phone
      // (cada llamada UPDATE el snapshot vigente + INSERT histórico).
      if (request.method === 'POST' && path === '/admin/wa/analyze-chat') {
        let payload;
        try { payload = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { phone, model } = payload || {};
        if (!phone) return json({ error: 'missing phone' }, 400);
        const res = await analyzeChatWithClaude(env, phone, model === 'opus' ? 'opus' : 'sonnet');
        return json(res, res.ok ? 200 : 500);
      }

      // Batch análisis para cron diario. Toma N chats que tengan actividad
      // posterior al last_analyzed_at (o que nunca se analizaron) y los corre.
      // Limit default 10 por llamada (~30 seg). Se puede llamar varias veces
      // para procesar más. Excluye phones internos del equipo (Joaco, Gaspar, Bruno)
      // listados en wa_internal_phones para no analizar chats internos como si
      // fueran clientes (los msgs de Joaco en su número del negocio NO son
      // conversaciones de venta).
      if (request.method === 'POST' && path === '/admin/wa/analyze-pending') {
        const limit = Math.min(parseInt(url.searchParams.get('limit') || '10'), 50);
        const minMsgs = parseInt(url.searchParams.get('min_msgs') || '3'); // chats con menos de 3 msgs los skipeamos por default
        const stats = { processed: 0, succeeded: 0, failed: 0, total_cost_usd: 0, results: [] };
        try {
          // Estrategia: phones que tienen msgs nuevos desde el último análisis.
          // Subquery saca last_msg_ts por phone, y comparamos contra last_analyzed_at
          // de wa_conversations. Si nunca se analizó o si hay msgs nuevos, entra.
          // EXCLUDE: phones en wa_internal_phones (equipo, no clientes).
          const rs = await env.DB.prepare(
            `WITH chat_stats AS (
               SELECT phone, MAX(ts) AS last_ts, COUNT(*) AS n_msgs
               FROM wa_messages WHERE msg_type != 'reaction'
                 AND phone NOT IN (SELECT phone FROM wa_internal_phones)
               GROUP BY phone
               HAVING n_msgs >= ?
             )
             SELECT cs.phone FROM chat_stats cs
             LEFT JOIN wa_conversations c ON c.phone = cs.phone
             WHERE c.last_analyzed_at IS NULL OR c.last_analyzed_at < cs.last_ts
                OR c.analysis_version < ?
             ORDER BY cs.last_ts DESC
             LIMIT ?`
          ).bind(minMsgs, ANALYSIS_PROMPT_VERSION, limit).all();
          const phones = (rs.results || []).map(r => r.phone);
          // Ejecutamos los N análisis EN PARALELO con Promise.all. Cada análisis
          // es ~3 seg I/O bound (espera respuesta de Anthropic), así que con
          // limit=15 el wall time queda ~5-8 seg en vez de 45-60 seg en serie.
          // Workers tiene CPU time limit (30s free/5min paid) pero el await fetch
          // no consume CPU, así que esto es safe.
          const results = await Promise.all(phones.map(async (phone) => {
            try {
              const r = await analyzeChatWithClaude(env, phone, 'sonnet');
              return { phone, ok: r.ok, cost: r.cost_usd || 0, error: r.error };
            } catch (e) {
              return { phone, ok: false, error: e.message };
            }
          }));
          for (const r of results) {
            stats.processed++;
            if (r.ok) {
              stats.succeeded++;
              stats.total_cost_usd += r.cost || 0;
            } else {
              stats.failed++;
            }
            stats.results.push({ phone: r.phone, ok: r.ok, error: r.error });
          }
          return json({ ok: true, stats });
        } catch (e) {
          return json({ error: e.message, stats }, 500);
        }
      }

      // Agregados pre-calculados para el dashboard de insights IA.
      // Devuelve resumen, distribución por ad, por vertical, top objeciones,
      // top "qué funcionó" y costo total acumulado del análisis.
      // Filtro opcional ?product_type=cartel_personalizado|curso|... para
      // segmentar por vertical (los ciclos de venta son completamente distintos).
      if (request.method === 'GET' && path === '/admin/wa/insights') {
        try {
          const productFilter = url.searchParams.get('product_type') || '';
          const where = productFilter
            ? `WHERE outcome != '' AND product_type = '${productFilter.replace(/'/g, "''")}'`
            : `WHERE outcome != ''`;
          const whereLabels = productFilter
            ? `WHERE product_type = '${productFilter.replace(/'/g, "''")}'`
            : ``;
          const results = { filter: productFilter };
          // Resumen general — outcomes y costo
          const summary = await env.DB.prepare(
            `SELECT
              COUNT(*) AS total,
              SUM(CASE WHEN outcome = 'sold' THEN 1 ELSE 0 END) AS sold,
              SUM(CASE WHEN outcome = 'lost' THEN 1 ELSE 0 END) AS lost,
              SUM(CASE WHEN outcome = 'abandoned_by_client' THEN 1 ELSE 0 END) AS abandoned,
              SUM(CASE WHEN outcome = 'in_progress' THEN 1 ELSE 0 END) AS in_progress,
              SUM(CASE WHEN outcome = 'spam' THEN 1 ELSE 0 END) AS spam
            FROM wa_conversations ${where}`
          ).first();
          results.summary = summary || {};
          const costRow = await env.DB.prepare(
            `SELECT ROUND(SUM(cost_usd_estimated), 2) AS total_cost FROM wa_chat_analyses WHERE error = ''`
          ).first();
          results.total_cost_usd = costRow?.total_cost || 0;
          // Por ad — solo ads que tengan al menos 1 análisis. Aplica filtro de producto si está activo.
          const adWhere = productFilter
            ? `WHERE ad_name != '' AND product_type = '${productFilter.replace(/'/g, "''")}'`
            : `WHERE ad_name != ''`;
          results.by_ad = (await env.DB.prepare(
            `SELECT ad_name, campaign_name,
              COUNT(*) AS total,
              SUM(CASE WHEN outcome = 'sold' THEN 1 ELSE 0 END) AS sold,
              SUM(CASE WHEN outcome = 'lost' THEN 1 ELSE 0 END) AS lost,
              SUM(CASE WHEN outcome = 'abandoned_by_client' THEN 1 ELSE 0 END) AS abandoned,
              SUM(CASE WHEN outcome = 'in_progress' THEN 1 ELSE 0 END) AS in_progress
            FROM wa_conversations
            ${adWhere}
            GROUP BY ad_name, campaign_name
            ORDER BY total DESC LIMIT 30`
          ).all()).results || [];
          // Por vertical (vertical del CLIENTE: particular/local/franquicia/etc — distinto a product_type)
          const vertWhere = productFilter
            ? `WHERE vertical != '' AND product_type = '${productFilter.replace(/'/g, "''")}'`
            : `WHERE vertical != ''`;
          results.by_vertical = (await env.DB.prepare(
            `SELECT vertical,
              COUNT(*) AS total,
              SUM(CASE WHEN outcome = 'sold' THEN 1 ELSE 0 END) AS sold,
              SUM(CASE WHEN outcome = 'lost' THEN 1 ELSE 0 END) AS lost,
              SUM(CASE WHEN outcome = 'abandoned_by_client' THEN 1 ELSE 0 END) AS abandoned,
              SUM(CASE WHEN outcome = 'in_progress' THEN 1 ELSE 0 END) AS in_progress
            FROM wa_conversations
            ${vertWhere}
            GROUP BY vertical
            ORDER BY total DESC`
          ).all()).results || [];
          // Por product type
          results.by_product = (await env.DB.prepare(
            `SELECT product_type,
              COUNT(*) AS total,
              SUM(CASE WHEN outcome = 'sold' THEN 1 ELSE 0 END) AS sold
            FROM wa_conversations
            WHERE product_type != ''
            GROUP BY product_type
            ORDER BY total DESC`
          ).all()).results || [];
          // Sentiment
          results.by_sentiment = (await env.DB.prepare(
            `SELECT sentiment_final, COUNT(*) AS n FROM wa_conversations
             WHERE sentiment_final != '' GROUP BY sentiment_final ORDER BY n DESC`
          ).all()).results || [];
          // Top objeciones (parseamos los JSON arrays a flat list)
          const objWhere = productFilter
            ? `WHERE objections != '' AND objections != '[]' AND product_type = '${productFilter.replace(/'/g, "''")}'`
            : `WHERE objections != '' AND objections != '[]'`;
          const objRows = (await env.DB.prepare(
            `SELECT objections FROM wa_conversations ${objWhere}`
          ).all()).results || [];
          const objCounts = {};
          for (const r of objRows) {
            try {
              const arr = JSON.parse(r.objections);
              if (Array.isArray(arr)) for (const o of arr) {
                const key = String(o).trim().toLowerCase();
                if (key) objCounts[key] = (objCounts[key] || 0) + 1;
              }
            } catch (_) {}
          }
          results.top_objections = Object.entries(objCounts)
            .sort((a, b) => b[1] - a[1]).slice(0, 20)
            .map(([k, v]) => ({ objection: k, count: v }));
          // Top intent signals (mismo filtro de producto)
          const intWhere = productFilter
            ? `WHERE intent_signals != '' AND intent_signals != '[]' AND product_type = '${productFilter.replace(/'/g, "''")}'`
            : `WHERE intent_signals != '' AND intent_signals != '[]'`;
          const intRows = (await env.DB.prepare(
            `SELECT intent_signals FROM wa_conversations ${intWhere}`
          ).all()).results || [];
          const intCounts = {};
          for (const r of intRows) {
            try {
              const arr = JSON.parse(r.intent_signals);
              if (Array.isArray(arr)) for (const o of arr) {
                const key = String(o).trim().toLowerCase();
                if (key) intCounts[key] = (intCounts[key] || 0) + 1;
              }
            } catch (_) {}
          }
          results.top_intents = Object.entries(intCounts)
            .sort((a, b) => b[1] - a[1]).slice(0, 20)
            .map(([k, v]) => ({ intent: k, count: v }));
          // Costos por modelo
          results.by_model = (await env.DB.prepare(
            `SELECT model_used, COUNT(*) AS calls, ROUND(SUM(cost_usd_estimated), 2) AS cost
             FROM wa_chat_analyses WHERE error = ''
             GROUP BY model_used ORDER BY cost DESC`
          ).all()).results || [];
          return json(results);
        } catch (e) {
          return json({ error: e.message }, 500);
        }
      }

      // Listado/resumen de conversaciones ya analizadas. Filtros básicos para
      // explorar insights desde el dashboard sin tener que hacer SQL.
      if (request.method === 'GET' && path === '/admin/wa/conversations') {
        const limit = Math.min(parseInt(url.searchParams.get('limit') || '50'), 500);
        const outcome = url.searchParams.get('outcome') || '';
        const productType = url.searchParams.get('product_type') || '';
        const adName = url.searchParams.get('ad_name') || '';
        let sql = `SELECT phone, first_msg_ts, last_msg_ts, total_msgs, ad_name, campaign_name,
                          outcome, outcome_reason, product_type, product_details, vertical,
                          sentiment_final, confidence, last_analyzed_at, last_model_used
                   FROM wa_conversations WHERE 1=1`;
        const params = [];
        if (outcome) { sql += ' AND outcome = ?'; params.push(outcome); }
        if (productType) { sql += ' AND product_type = ?'; params.push(productType); }
        if (adName) { sql += ' AND ad_name = ?'; params.push(adName); }
        sql += ' ORDER BY last_msg_ts DESC LIMIT ?';
        params.push(limit);
        try {
          const rs = await env.DB.prepare(sql).bind(...params).all();
          return json({ conversations: rs.results || [] });
        } catch (e) {
          return json({ conversations: [], error: e.message }, 500);
        }
      }

      // Backfill de transcripción de audios históricos. Toma N audios con media
      // en R2 pero sin transcripción (body vacío o solo placeholder '[audio]')
      // y los procesa via Workers AI whisper-large-v3-turbo. Workers tiene
      // límite de ~30s por request, por eso default limit=15 (cada audio tarda
      // 1-3 seg). Idempotente: si se vuelve a llamar, sigue donde dejó.
      if (request.method === 'POST' && path === '/admin/wa/transcribe-backfill') {
        const limit = Math.min(parseInt(url.searchParams.get('limit') || '15'), 50);
        const stats = { processed: 0, transcribed: 0, failed: 0, no_media: 0 };
        try {
          const rs = await env.DB.prepare(
            `SELECT id, media_url FROM wa_messages
             WHERE msg_type='audio'
               AND media_url LIKE 'wa/%'
               AND (body = '' OR body = '[audio]' OR body IS NULL OR length(body) < 10)
             ORDER BY ts DESC
             LIMIT ?`
          ).bind(limit).all();
          const rows = rs.results || [];
          for (const r of rows) {
            stats.processed++;
            try {
              const transcript = await transcribeAudio(env, r.media_url);
              if (transcript && transcript.trim().length > 0) {
                await env.DB.prepare('UPDATE wa_messages SET body = ? WHERE id = ?').bind(
                  '[audio] ' + transcript, r.id
                ).run();
                stats.transcribed++;
              } else {
                stats.no_media++;
              }
            } catch (e) {
              stats.failed++;
            }
          }
          // Cuántos quedan pendientes para que el caller decida si seguir.
          const remaining = await env.DB.prepare(
            `SELECT COUNT(*) AS n FROM wa_messages
             WHERE msg_type='audio' AND media_url LIKE 'wa/%'
             AND (body = '' OR body = '[audio]' OR body IS NULL OR length(body) < 10)`
          ).first();
          return json({ ok: true, stats, remaining: remaining?.n || 0 });
        } catch (e) {
          return json({ error: e.message, stats }, 500);
        }
      }

      // Listado de leads procesados desde Meta Lead Ads + status del template.
      // Útil para monitorear el flujo en tiempo real y debug.
      if (request.method === 'GET' && path === '/admin/wa/leads') {
        const limit = Math.min(parseInt(url.searchParams.get('limit') || '50'), 500);
        const status = url.searchParams.get('status') || ''; // pending|sent|failed|skipped
        let sql = 'SELECT id, leadgen_id, ts, received_at, page_id, form_id, ad_id, phone, first_name, full_name, email, vertical, template_status, template_sent_at, template_error, wamid, process_error FROM wa_leads';
        const params = [];
        if (status) { sql += ' WHERE template_status = ?'; params.push(status); }
        sql += ' ORDER BY ts DESC LIMIT ?';
        params.push(limit);
        try {
          const rs = await env.DB.prepare(sql).bind(...params).all();
          return json({ leads: rs.results || [] });
        } catch (e) {
          return json({ leads: [], error: e.message }, 500);
        }
      }

      // Reintentar enviar template para un lead que falló. Útil cuando el template
      // estaba pendiente de aprobación al momento del lead, o falló la API.
      if (request.method === 'POST' && path.startsWith('/admin/wa/leads/') && path.endsWith('/retry')) {
        const leadgenId = path.slice('/admin/wa/leads/'.length, -('/retry'.length));
        try {
          const row = await env.DB.prepare('SELECT * FROM wa_leads WHERE leadgen_id = ?').bind(leadgenId).first();
          if (!row) return json({ error: 'lead not found' }, 404);
          if (!row.phone) return json({ error: 'lead has no valid phone' }, 400);
          const tplResult = await waSendTemplate(env, row.phone, 'lead_b2b_followup', 'es_AR', [
            row.first_name || 'amigo/a'
          ]);
          if (tplResult?.ok) {
            const wamid = tplResult.id || '';
            await env.DB.prepare(
              'UPDATE wa_leads SET template_status = ?, template_sent_at = ?, wamid = ?, template_error = ? WHERE leadgen_id = ?'
            ).bind('sent', new Date().toISOString(), wamid, '', leadgenId).run();
            return json({ ok: true, wamid });
          } else {
            await env.DB.prepare(
              'UPDATE wa_leads SET template_status = ?, template_error = ? WHERE leadgen_id = ?'
            ).bind('failed', JSON.stringify(tplResult).slice(0, 500), leadgenId).run();
            return json({ ok: false, error: tplResult }, 500);
          }
        } catch (e) {
          return json({ error: e.message }, 500);
        }
      }

      // Diagnóstico: log de mensajes inbound que Meta marca como unsupported.
      // Captura el JSON crudo + error.title/code/details para entender por qué
      // tantos mensajes llegan sin contenido (sospecha: msgs eliminados rápido).
      if (request.method === 'GET' && path === '/admin/wa/debug-unavailable') {
        const limit = Math.min(parseInt(url.searchParams.get('limit') || '50'), 200);
        try {
          const rs = await env.DB.prepare(
            'SELECT id, ts, inserted_at, wamid, phone, sender_name, error_code, error_title, error_details, msg_type, classified_as, raw_payload FROM wa_webhook_debug ORDER BY ts DESC LIMIT ?'
          ).bind(limit).all();
          return json({ rows: rs.results || [] });
        } catch (e) {
          return json({ rows: [], error: e.message }, 500);
        }
      }

      // Bandeja PRIVADA (admin-only): asignar/sacar un chat a la bandeja 'privado' de Gaspar.
      // Solo admin la ve (inboxClauseForRole + inboxAccessOk gatean 'privado'). on=true → privado;
      // on=false → 'general' (vuelve a la bandeja normal). Invalida el cache para que se refleje ya.
      if (request.method === 'POST' && path === '/admin/wa/private-toggle') {
        if (!isAdminSession) return json({ error: 'forbidden: admin only' }, 403);
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const raw = String(body?.to || body?.phone || '');
        const num = normalizeArPhone(raw) || raw.replace(/\D/g, '');
        if (!num) return json({ error: 'teléfono inválido' }, 400);
        const on = body?.on !== false; // default true
        try {
          if (on) {
            // Mover a la bandeja privada (movimiento manual del admin): sale de su bandeja actual.
            await env.DB.prepare(
              "INSERT INTO wa_chats_summary (phone, inbox, pin_privado, updated_at) VALUES (?, 'privado', 0, ?) ON CONFLICT(phone) DO UPDATE SET inbox = 'privado', pin_privado = 0, updated_at = excluded.updated_at"
            ).bind(num, new Date().toISOString()).run();
          } else {
            // Sacar de la privada / des-pinnear. Solo volvemos a 'general' si estaba en 'privado'; si es
            // un chat auto-pinneado (Bruno) que vive en OTRA bandeja (cursos/corte/precotiz), conservamos
            // su bandeja y solo le sacamos el pin (no lo relocalizamos ni lo filtramos mal).
            await env.DB.prepare(
              "UPDATE wa_chats_summary SET pin_privado = 0, inbox = CASE WHEN inbox = 'privado' THEN 'general' ELSE inbox END, updated_at = ? WHERE phone = ?"
            ).bind(new Date().toISOString(), num).run();
          }
        } catch (e) { return json({ error: 'no se pudo actualizar' }, 500); }
        try { await invalidateChatsSummaryCache(request); } catch (_) {}
        return json({ ok: true, phone: num, inbox: on ? 'privado' : 'general' });
      }

      // Consultar mensajes de WhatsApp guardados (para análisis)
      if (request.method === 'GET' && path === '/admin/wa/messages') {
        const phone = url.searchParams.get('phone') || '';
        const _role = await getSessionRole(env, session.user);
        const from = url.searchParams.get('from') || '';
        const to = url.searchParams.get('to') || '';
        const dir = url.searchParams.get('direction') || '';
        const limit = Math.min(parseInt(url.searchParams.get('limit') || '500'), 5000);
        let where = '1=1';
        const params = [];
        if (phone) {
          // Consulta de un chat puntual. Rol 'cursos' solo accede a su bandeja.
          if (_role !== 'admin' && !(await inboxAccessOk(env, _role, phone.replace(/\D/g, ''), session.user))) {
            return json({ error: 'forbidden: chat fuera de tu bandeja', messages: [] }, 403);
          }
          where += ' AND phone = ?'; params.push(phone);
        } else {
          // Consulta global (polling de inbound, follow-ups, etc.): filtramos por
          // bandeja según rol para que Joaco NUNCA reciba ni procese nada de
          // cursos (ni notificaciones en segundo plano), y Abril solo lo suyo.
          //   admin    → sin filtro
          //   cursos   → solo chats de la bandeja cursos
          //   comercial→ todo MENOS cursos
          // Los filtros van como (NOT) EXISTS correlacionados contra la PK de wa_chats_summary, NO
          // como "phone (NOT) IN (SELECT phone FROM wa_chats_summary WHERE ...)": el IN materializa
          // la lista entera de la bandeja (8k-17k filas) en CADA poll, aunque la ventana de mensajes
          // sea de segundos. Con EXISTS se lee la ventana por idx_wa_messages_ts + 1 lookup por
          // mensaje (~17k -> ~70 filas por poll). Mismo resultado (verificado contra prod).
          // "phone IS NOT NULL" conserva la semántica del NOT IN (un phone NULL quedaba afuera).
          const _cs = (cond) => `EXISTS (SELECT 1 FROM wa_chats_summary s WHERE s.phone = wa_messages.phone AND ${cond})`;
          where += ' AND phone IS NOT NULL';
          if (_role === 'cursos') {
            where += ` AND ${_cs("s.inbox = 'cursos'")}`;
          } else if (_role === 'admin') {
            where += ` AND NOT ${_cs("s.inbox = 'oculto'")}`;
          } else {
            // comercial: excluir cursos/oculto/precotiz/privado/corte (igual que inboxClauseForRole).
            where += ` AND NOT ${_cs("s.inbox IN ('cursos','oculto','precotiz','privado','corte')")}`;
            // Scope por vendedor (espeja /admin/wa/chats-summary): el secundario (Facundo) SOLO
            // ve/pollea lo asignado a él; el principal (Joaco) todo lo NO asignado a un secundario.
            // Así el poll de notificaciones no se filtra entre vendedores. _uslug se interpola solo
            // si está en la whitelist fija VENDEDORES_SECUNDARIOS -> sin riesgo de inyección.
            const _uslug = String(session.user || '').toLowerCase();
            if (VENDEDORES_SECUNDARIOS.includes(_uslug)) {
              where += ` AND ${_cs(`s.assigned_to = '${_uslug}'`)}`;
            } else {
              where += ` AND NOT ${_cs(`s.assigned_to IN (${VENDEDORES_SECUNDARIOS.map(s => `'${s}'`).join(',')})`)}`;
            }
          }
        }
        if (from) { where += ' AND ts >= ?'; params.push(from); }
        if (to) { where += ' AND ts <= ?'; params.push(to); }
        if (dir === 'inbound' || dir === 'outbound') { where += ' AND direction = ?'; params.push(dir); }
        // quoted_meta: preview del mensaje CITADO (cuando este mensaje es una respuesta a otro).
        // Lo resolvemos acá con un self-lookup por context_id para que el chat muestre "a cuál
        // le responde" AUNQUE el mensaje citado no esté en la ventana cargada (chats largos).
        // Formato: direction ⏹ msg_type ⏹ sender_name ⏹ body(120) — separador char(31), que
        // nunca aparece en texto. El front lo parsea.
        const rs = await env.DB.prepare(
          `SELECT id, ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status, automated,
             (SELECT p.direction || char(31) || p.msg_type || char(31) || COALESCE(p.sender_name,'') || char(31) || substr(COALESCE(p.body,''),1,120)
                FROM wa_messages p WHERE p.wamid = wa_messages.context_id AND p.phone = wa_messages.phone AND wa_messages.context_id != '' LIMIT 1) AS quoted_meta
           FROM wa_messages WHERE ${where} ORDER BY ts DESC LIMIT ?`
        ).bind(...params, limit).all();
        let _msgs = rs.results || [];
        // Consulta global de alguien que no es admin: afuera los chats del EQUIPO con el número del negocio (avisos,
        // listas, reportes; mismo criterio que la lista de chats, la búsqueda e inboxAccessOk). Si no, el poll de
        // notificaciones (poll-worker.js, cada 5 s) le hacía sonar y le mostraba a Joaco lo que Agus le escribe al número
        // del negocio (su chat está en 'general' sin asignar) y a Abril lo de Bruno ('cursos'). En memoria contra
        // internosSet (caché 10 min): la query sigue por idx_wa_messages_ts, sin filas leídas de más.
        if (!phone && _role !== 'admin' && _msgs.length) {
          try { const _I = await internosSet(env); _msgs = _msgs.filter(m => !_I.set.has(String(m.phone || '').replace(/\D/g, ''))); } catch (_) {}
        }
        // Las burbujas "sin texto registrado" muestran lo que salió (aviso interno o registro de envíos).
        // (También en el poll global: solo consulta si llegó alguna burbuja vacía, que es raro.)
        if (_msgs.length) { try { _msgs = await waRellenarSalientes(env, _msgs); } catch (_) {} }
        return json({ messages: _msgs });
      }

      // Read cursors: qué conversaciones fueron leídas y cuándo
      if (request.method === 'GET' && path === '/admin/wa/read-cursors') {
        try {
          const rs = await env.DB.prepare('SELECT phone, last_read_ts FROM wa_read_cursor').all();
          const cursors = {};
          for (const r of (rs.results || [])) cursors[r.phone] = r.last_read_ts;
          return json({ cursors });
        } catch (_) {
          return json({ cursors: {} });
        }
      }

      // Preview de los leads del Sheet de cursos (solo admin). No manda nada;
      // devuelve conteos + muestra para revisar antes del envío masivo.
      if (request.method === 'GET' && path === '/admin/wa/cursos-leads') {
        const role = await getSessionRole(env, session.user);
        if (role !== 'admin') return json({ error: 'forbidden' }, 403);
        let data;
        try { data = await fetchCursosLeads(env); }
        catch (e) { return json({ error: 'no pude leer el sheet: ' + e.message }, 502); }
        const validos = data.leads.filter(l => l.valido);
        const invalidos = data.leads.filter(l => !l.valido);
        // Cuántos ya recibieron el broadcast (dedup).
        let yaEnviados = 0;
        try {
          const phones = validos.map(l => l.tel);
          if (phones.length) {
            // chunk para no pasar 999 binds
            for (let i = 0; i < phones.length; i += 400) {
              const chunk = phones.slice(i, i + 400);
              const ph = chunk.map(() => '?').join(',');
              const r2 = await env.DB.prepare(`SELECT COUNT(*) AS n FROM wa_autoreply_log WHERE kind='cursos_broadcast' AND status='sent' AND phone IN (${ph})`).bind(...chunk).first();
              yaEnviados += (r2?.n || 0);
            }
          }
        } catch (_) {}
        return json({
          total_filas: data.total,
          validos: validos.length,
          invalidos: invalidos.length,
          ya_enviados: yaEnviados,
          pendientes: validos.length - yaEnviados,
          muestra: data.leads.slice(0, 8),
          invalidos_muestra: invalidos.slice(0, 5)
        });
      }

      // Programar goteo del broadcast — encola N leads en la cola con due_at
      // distribuido entre startTs y endTs. El cron processCursosBroadcastQueue
      // los procesa cuando vencen. NO manda nada al toque.
      // Body: { count, startTs (ISO), endTs (ISO), dryRun? }
      // Excluye automáticamente: ya enviados (cursos_broadcast 'sent'),
      // unreachable phones, y leads sin tel válido.
      if (request.method === 'POST' && path === '/admin/wa/cursos-broadcast-schedule') {
        const role = await getSessionRole(env, session.user);
        if (role !== 'admin') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const count = Math.min(Math.max(parseInt(body?.count || '0', 10) || 0, 1), 500);
        const startTs = body?.startTs ? new Date(body.startTs) : new Date();
        const endTs = body?.endTs ? new Date(body.endTs) : new Date(Date.now() + 4 * 60 * 60 * 1000);
        const dryRun = !!body?.dryRun;
        if (isNaN(startTs.getTime()) || isNaN(endTs.getTime()) || endTs <= startTs) {
          return json({ error: 'startTs/endTs inválidos' }, 400);
        }
        let data;
        try { data = await fetchCursosLeads(env); } catch (e) { return json({ error: 'no pude leer el sheet: ' + e.message }, 502); }
        const validos = data.leads.filter(l => l.valido);
        // Excluir ya enviados, en cola y unreachable.
        const yaSet = new Set();
        try {
          const rs = await env.DB.prepare("SELECT phone FROM wa_autoreply_log WHERE kind = 'cursos_broadcast'").all();
          for (const r of (rs.results || [])) yaSet.add(r.phone);
        } catch (_) {}
        const unreachSet = new Set();
        try {
          const rs = await env.DB.prepare("SELECT phone FROM wa_unreachable_phones").all();
          for (const r of (rs.results || [])) unreachSet.add(r.phone);
        } catch (_) {}
        const pendientes = validos.filter(l => !yaSet.has(l.tel) && !unreachSet.has(l.tel)).slice(0, count);
        if (!pendientes.length) return json({ scheduled: 0, available: validos.length - yaSet.size, reason: 'no quedan leads pendientes' });
        // Distribuir due_at uniformemente entre startTs y endTs.
        const totalMs = endTs.getTime() - startTs.getTime();
        const step = pendientes.length > 1 ? totalMs / (pendientes.length - 1) : 0;
        const planned = pendientes.map((l, i) => ({
          tel: l.tel,
          nombre: l.nombre || '',
          due_at: new Date(startTs.getTime() + Math.round(i * step)).toISOString()
        }));
        if (dryRun) {
          return json({
            dryRun: true,
            scheduled: planned.length,
            window: { startTs: startTs.toISOString(), endTs: endTs.toISOString(), step_seconds: Math.round(step / 1000) },
            primeros: planned.slice(0, 5),
            ultimos: planned.slice(-5)
          });
        }
        // Insertar en wa_autoreply_log con kind='cursos_broadcast' y status='queued'.
        let scheduled = 0;
        const nowIso = new Date().toISOString();
        for (const p of planned) {
          try {
            const r = await env.DB.prepare(
              "INSERT OR IGNORE INTO wa_autoreply_log (phone, kind, sent_at, status, due_at, sender_name) VALUES (?, 'cursos_broadcast', '', 'queued', ?, ?)"
            ).bind(p.tel, p.due_at, p.nombre).run();
            if (r?.meta?.changes) scheduled++;
          } catch (_) {}
        }
        return json({
          ok: true,
          scheduled,
          requested: planned.length,
          window: { startTs: startTs.toISOString(), endTs: endTs.toISOString(), step_seconds: Math.round(step / 1000) },
          primeros: planned.slice(0, 3),
          ultimos: planned.slice(-3),
          nota: 'El cron procesa cada minuto. El primer envío sale aprox a las ' + startTs.toISOString() + '.'
        });
      }

      // Schedule del broadcast de JUNIO 2026 (lanzamiento). Igual que el de cursos
      // pero lee fetchJunioLeads (filtrado 9 y 10 jun 2026) y encola kind='junio_broadcast'.
      if (request.method === 'POST' && path === '/admin/wa/junio-broadcast-schedule') {
        const role = await getSessionRole(env, session.user);
        if (role !== 'admin') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const count = Math.min(Math.max(parseInt(body?.count || '0', 10) || 0, 1), 1000);
        const startTs = body?.startTs ? new Date(body.startTs) : new Date();
        const endTs = body?.endTs ? new Date(body.endTs) : new Date(Date.now() + 4 * 60 * 60 * 1000);
        const dryRun = !!body?.dryRun;
        if (isNaN(startTs.getTime()) || isNaN(endTs.getTime()) || endTs <= startTs) {
          return json({ error: 'startTs/endTs inválidos' }, 400);
        }
        let data;
        try { data = await fetchJunioLeads(env); } catch (e) { return json({ error: 'no pude leer el sheet: ' + e.message }, 502); }
        const validos = data.leads.filter(l => l.valido);
        const yaSet = new Set();
        try {
          const rs = await env.DB.prepare("SELECT phone FROM wa_autoreply_log WHERE kind = 'junio_broadcast'").all();
          for (const r of (rs.results || [])) yaSet.add(r.phone);
        } catch (_) {}
        const unreachSet = new Set();
        try {
          const rs = await env.DB.prepare("SELECT phone FROM wa_unreachable_phones").all();
          for (const r of (rs.results || [])) unreachSet.add(r.phone);
        } catch (_) {}
        const pendientes = validos.filter(l => !yaSet.has(l.tel) && !unreachSet.has(l.tel)).slice(0, count);
        if (!pendientes.length) return json({ scheduled: 0, available: validos.length - yaSet.size, reason: 'no quedan leads pendientes' });
        const totalMs = endTs.getTime() - startTs.getTime();
        const step = pendientes.length > 1 ? totalMs / (pendientes.length - 1) : 0;
        const planned = pendientes.map((l, i) => ({
          tel: l.tel, nombre: l.nombre || '',
          due_at: new Date(startTs.getTime() + Math.round(i * step)).toISOString()
        }));
        if (dryRun) {
          return json({ dryRun: true, scheduled: planned.length, total_validos: validos.length, ya_encolados: yaSet.size,
            window: { startTs: startTs.toISOString(), endTs: endTs.toISOString(), step_seconds: Math.round(step / 1000) },
            primeros: planned.slice(0, 5), ultimos: planned.slice(-5) });
        }
        let scheduled = 0;
        for (const p of planned) {
          try {
            const r = await env.DB.prepare(
              "INSERT OR IGNORE INTO wa_autoreply_log (phone, kind, sent_at, status, due_at, sender_name) VALUES (?, 'junio_broadcast', '', 'queued', ?, ?)"
            ).bind(p.tel, p.due_at, p.nombre).run();
            if (r?.meta?.changes) scheduled++;
          } catch (_) {}
        }
        return json({ ok: true, scheduled, requested: planned.length,
          window: { startTs: startTs.toISOString(), endTs: endTs.toISOString(), step_seconds: Math.round(step / 1000) },
          primeros: planned.slice(0, 3), ultimos: planned.slice(-3) });
      }

      // Envío masivo de la plantilla de cursos a los leads del Sheet (solo admin).
      // Body: { limit?: number (default 10, máx 200), dryRun?: bool }.
      // Manda la plantilla cursos_clases_vivo_mayo con {{1}}=primer nombre, guarda
      // el outbound en el CRM y deriva cada chat a la bandeja de Abril. Dedup
      // atómico por wa_autoreply_log kind='cursos_broadcast' (no manda 2 veces).
      if (request.method === 'POST' && path === '/admin/wa/cursos-broadcast') {
        const role = await getSessionRole(env, session.user);
        if (role !== 'admin') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const limit = Math.min(Math.max(parseInt(body?.limit || '10', 10) || 10, 1), 200);
        const dryRun = !!body?.dryRun;
        let data;
        try { data = await fetchCursosLeads(env); } catch (e) { return json({ error: 'no pude leer el sheet: ' + e.message }, 502); }
        const validos = data.leads.filter(l => l.valido);
        // Excluir los que ya recibieron (status sent o en curso).
        const yaSet = new Set();
        try {
          const rs = await env.DB.prepare("SELECT phone FROM wa_autoreply_log WHERE kind = 'cursos_broadcast'").all();
          for (const r of (rs.results || [])) yaSet.add(r.phone);
        } catch (_) {}
        const pendientes = validos.filter(l => !yaSet.has(l.tel)).slice(0, limit);
        if (dryRun) {
          return json({ dryRun: true, a_enviar: pendientes.length, muestra: pendientes.map(l => ({ nombre: l.nombre, tel: l.tel })) });
        }
        const result = { enviados: 0, fallidos: 0, errores: [] };
        // id de la etiqueta 'form 6 y 7 de mayo' (para distinguir la campaña).
        let formLabelId = 24;
        try { const lr = await env.DB.prepare("SELECT id FROM labels WHERE name = 'form 6 y 7 de mayo'").first(); if (lr?.id) formLabelId = lr.id; } catch (_) {}
        for (const lead of pendientes) {
          // Reserva atómica (evita doble envío).
          let reserva;
          try {
            reserva = await env.DB.prepare(
              "INSERT OR IGNORE INTO wa_autoreply_log (phone, kind, sent_at, status, due_at, sender_name) VALUES (?, 'cursos_broadcast', '', 'sending', ?, ?)"
            ).bind(lead.tel, new Date().toISOString(), lead.nombre || '').run();
          } catch (_) { continue; }
          if (!reserva?.meta?.changes) continue; // ya reservado
          const primerNombre = capitalizeName((lead.nombre || '').split(/\s+/)[0]) || 'amigo/a';
          const tpl = await waSendTemplate(env, lead.tel, 'cursos_clases_vivo_mayo', 'es_AR', [primerNombre]);
          if (tpl?.ok) {
            result.enviados++;
            const wamid = tpl.id || '';
            const ts = new Date().toISOString();
            try { await env.DB.prepare("UPDATE wa_autoreply_log SET status = 'sent', sent_at = ? WHERE phone = ? AND kind = 'cursos_broadcast'").bind(ts, lead.tel).run(); } catch (_) {}
            const previewBody = `holaa ${primerNombre}! Cómo andás?\nSoy Abril, de Neon Infinito. Me dijeron los chicos que participaste de las clases en vivo que hicieron el 6 y 7 de mayo, puede ser?`;
            if (wamid) {
              try {
                await env.DB.prepare(
                  `INSERT INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, status, context_id, automated)
                   VALUES (?, ?, 'outbound', ?, '', 'template', ?, 'sent', '', 1)
                   ON CONFLICT(wamid) DO UPDATE SET body = excluded.body, msg_type = 'template', automated = 1
                     WHERE wa_messages.body IS NULL OR wa_messages.body = '' OR wa_messages.msg_type = 'status'`
                ).bind(ts, wamid, lead.tel, previewBody).run();
              } catch (_) {}
            }
            // OCULTAR del front (inbox='oculto') hasta que el cliente responda.
            try {
              await env.DB.prepare("INSERT INTO wa_chats_summary (phone, inbox, updated_at) VALUES (?, 'oculto', ?) ON CONFLICT(phone) DO UPDATE SET inbox = 'oculto'").bind(lead.tel, ts).run();
            } catch (_) {}
            // Registrar en la campaña (estado: enviado template 1, esperando respuesta).
            try {
              await env.DB.prepare("INSERT INTO wa_cursos_campaign (phone, nombre, sent_1_at, updated_at) VALUES (?, ?, ?, ?) ON CONFLICT(phone) DO UPDATE SET sent_1_at = excluded.sent_1_at, updated_at = excluded.updated_at").bind(lead.tel, lead.nombre || '', ts, ts).run();
            } catch (_) {}
            // Etiquetar con 'form 6 y 7 de mayo'.
            try { await env.DB.prepare("INSERT OR IGNORE INTO contact_labels (phone, label_id, created_at) VALUES (?, ?, ?)").bind(lead.tel, formLabelId, ts).run(); } catch (_) {}
          } else {
            result.fallidos++;
            if (result.errores.length < 8) result.errores.push({ tel: lead.tel, err: String(tpl?.error || JSON.stringify(tpl || {})).slice(0, 140) });
            // Liberar reserva para permitir reintento.
            try { await env.DB.prepare("DELETE FROM wa_autoreply_log WHERE phone = ? AND kind = 'cursos_broadcast'").bind(lead.tel).run(); } catch (_) {}
          }
        }
        return json(result);
      }

      // Derivar un chat a una bandeja (solo admin). inbox: 'cursos' | 'general'.
      // Marca el chat como de la bandeja Cursos (lo ve Abril, se oculta de Joaco)
      // o lo devuelve a la bandeja general.
      if (request.method === 'POST' && path === '/admin/wa/chat-inbox') {
        const role = await getSessionRole(env, session.user);
        // Admin y comercial (Joaco): mueven chats en cualquier dirección.
        // Cursos (Abril): SOLO puede SACAR de su bandeja (cursos → general) un
        // chat mal derivado; no puede meter chats (no ve los de general).
        if (role !== 'admin' && role !== 'comercial' && role !== 'cursos') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const phone = String(body?.phone || '').replace(/\D/g, '');
        const inbox = body?.inbox;
        if (!phone || !['cursos', 'general'].includes(inbox)) {
          return json({ error: 'phone (dígitos) e inbox (cursos|general) requeridos' }, 400);
        }
        if (role === 'cursos') {
          if (inbox !== 'general') return json({ error: 'forbidden: solo podés sacar chats de Cursos' }, 403);
          if (!(await inboxAccessOk(env, 'cursos', phone))) return json({ error: 'forbidden: ese chat no está en tu bandeja' }, 403);
        }
        // La bandeja 'privado' (admin-only de Gaspar) no la toca nadie más: si el chat YA está
        // en privado, solo admin lo puede sacar. (Meterlo a privado ya está bloqueado: arriba
        // solo se aceptan 'cursos'|'general'.) Se cambia con /admin/wa/private-toggle (admin).
        if (role !== 'admin') {
          try { const cur = await env.DB.prepare("SELECT inbox FROM wa_chats_summary WHERE phone = ?").bind(phone).first(); if (cur && cur.inbox === 'privado') return json({ error: 'forbidden' }, 403); } catch (_) {}
        }
        // Upsert: el chat ya suele existir en la libreta (tiene mensajes). Si no,
        // lo creamos con la bandeja seteada (aparecerá cuando tenga mensajes).
        await env.DB.prepare(
          `INSERT INTO wa_chats_summary (phone, inbox, updated_at) VALUES (?, ?, ?)
           ON CONFLICT(phone) DO UPDATE SET inbox = excluded.inbox`
        ).bind(phone, inbox, new Date().toISOString()).run();
        // Handoff manual del servicio de corte: si Gaspar manda un chat de corte a la bandeja de Abril
        // (cursos), marcamos la conversación 'handoff_abril' para que el bot de corte NO lo reclame. Si lo
        // saca de vuelta a 'general', limpiamos el handoff (el bot lo puede volver a atender). Si el chat no
        // es de corte (sin fila en corte_conversaciones), estos UPDATE no tocan nada.
        try {
          const _ts = new Date().toISOString();
          if (inbox === 'cursos') await env.DB.prepare("UPDATE corte_conversaciones SET estado='handoff_abril', updated_at=? WHERE phone=?").bind(_ts, phone).run();
          else if (inbox === 'general') await env.DB.prepare("UPDATE corte_conversaciones SET estado='nuevo', updated_at=? WHERE phone=? AND estado='handoff_abril'").bind(_ts, phone).run();
        } catch (_) {}
        ctx.waitUntil(invalidateChatsSummaryCache(request));
        return json({ ok: true, phone, inbox });
      }

      // POST /admin/wa/chat-assign → asignar un chat a un vendedor (solo Gaspar/admin).
      // body { phone, assigned_to: 'nadia'|'joaco'|'' }. '' = sin asignar (vuelve a la
      // bandeja de Joaco). El secundario (Nadia) ve SOLO lo asignado a él (filtro en
      // /admin/wa/chats-summary). assigned_at alimenta el reporte diario (chats/día).
      if (request.method === 'POST' && path === '/admin/wa/chat-assign') {
        const role = await getSessionRole(env, session.user);
        if (role !== 'admin') return json({ error: 'forbidden: solo admin asigna' }, 403);
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const phone = String(body?.phone || '').replace(/\D/g, '');
        const to = String(body?.assigned_to || '').trim().toLowerCase();
        if (!phone) return json({ error: 'phone requerido' }, 400);
        const validos = ['', 'joaco', ...VENDEDORES_SECUNDARIOS];
        if (!validos.includes(to)) return json({ error: 'assigned_to inválido' }, 400);
        const now = new Date().toISOString();
        let _prevAsg = ''; try { const _p = await env.DB.prepare("SELECT assigned_to FROM wa_chats_summary WHERE phone = ?").bind(phone).first(); _prevAsg = String((_p && _p.assigned_to) || ''); } catch (_) {}
        await env.DB.prepare(
          `INSERT INTO wa_chats_summary (phone, assigned_to, assigned_at, updated_at) VALUES (?, ?, ?, ?)
           ON CONFLICT(phone) DO UPDATE SET assigned_to = excluded.assigned_to, assigned_at = excluded.assigned_at`
        ).bind(phone, to, to ? now : '', now).run();
        if (_prevAsg !== to) await logAsignacion(env, phone, _prevAsg, to, 'manual', session.user, now);
        // El brief/comisión sigue al lead: al reasignar, movemos el comercial_id de los briefs de
        // este chat al vendedor asignado (secundario -> él; sin asignar / Joaco -> 'joaco').
        try { const _bc = VENDEDORES_SECUNDARIOS.includes(to) ? to : 'joaco'; await env.DB.prepare("UPDATE briefs SET comercial_id = ? WHERE cliente_wa_id = ?").bind(_bc, phone).run(); } catch (_) {}
        ctx.waitUntil(invalidateChatsSummaryCache(request));
        return json({ ok: true, phone, assigned_to: to });
      }

      // POST /admin/wa/chat-derivar {phone} — "No es neón" (Gaspar 17-oct): la vendedora de solo neón (o Gaspar) saca de su
      // bandeja un lead de corpóreo u otra cosa y va al sorteo parejo del resto (repartirDevuelto). Solo chats de la bandeja
      // general asignados a una de solo neón; si ya tiene pedido cargado no se mueve (lo resuelve Gaspar).
      if (request.method === 'POST' && path === '/admin/wa/chat-derivar') {
        const role = await getSessionRole(env, session.user);
        const meSlug = String(session.user || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
        const body = (await request.json().catch(() => null)) || {};
        const ph = String(body.phone || '').replace(/\D/g, '');
        if (!ph) return json({ error: 'Falta el teléfono.' }, 400);
        let row = null;
        try { row = await env.DB.prepare("SELECT assigned_to, inbox FROM wa_chats_summary WHERE phone = ?").bind(ph).first(); } catch (_) { return json({ error: 'No pude leer el chat. Probá de nuevo.' }, 503); }
        const desde = String((row && row.assigned_to) || '');
        const c = COMERCIALES_SECUNDARIOS.find(x => x.soloNeon && x.slug === desde);
        if (!(role === 'admin' || (role === 'comercial' && c && meSlug === c.slug))) return json({ error: 'Ese chat no está en tu bandeja.' }, 403);
        if (!c) return json({ error: 'Ese chat no es de una vendedora de solo neón.' }, 409);
        if ((String(row.inbox || '') || 'general') !== 'general') return json({ error: 'Ese chat no está en la bandeja de carteles.' }, 409);
        try { if (await env.DB.prepare('SELECT 1 AS x FROM pedidos WHERE telefono = ? LIMIT 1').bind(ph).first()) return json({ error: 'Ya tiene un pedido cargado: hablalo con Gaspar.' }, 409); } catch (_) {}
        const r = await repartirDevuelto(env, ph, { via: 'no_neon', byUser: session.user, desde });
        if (!r.ok) return json({ error: r.error }, 409);
        await invalidateChatsSummaryCache(request);
        return json({ ok: true, phone: ph, a: r.nombre });
      }

      // POST /admin/vendedores/password {slug, password} → SOLO admin: pone la contraseña de una vendedora secundaria y la ACTIVA
      // (nace inactiva: sin contraseña no entra ni recibe reparto). Cambiarla cierra sus sesiones abiertas.
      if (request.method === 'POST' && path === '/admin/vendedores/password') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const c = COMERCIALES_SECUNDARIOS.find(x => x.slug === String(body.slug || '').toLowerCase().trim());
        if (!c) return json({ error: 'vendedora desconocida' }, 400);
        const pw = String(body.password || '');
        if (pw.length < 8) return json({ error: 'la contraseña tiene que tener al menos 8 caracteres' }, 400);
        const hash = await sha256hex(pw);
        try {
          await env.DB.prepare("INSERT INTO users_panel (id, nombre, rol, activo, password_hash, created_at) VALUES (?, ?, 'comercial', 1, ?, ?) ON CONFLICT(id) DO UPDATE SET password_hash = excluded.password_hash, activo = 1 WHERE users_panel.rol = 'comercial'").bind(c.slug, c.nombre, hash, new Date().toISOString()).run();
          const u = await env.DB.prepare("SELECT rol, activo FROM users_panel WHERE id = ?").bind(c.slug).first();
          if (!u || u.rol !== 'comercial' || +u.activo !== 1) return json({ error: 'ese usuario existe con otro rol' }, 409);
          const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
          const ses = (await env.DB.prepare('SELECT token, user FROM sessions WHERE expires_at > ?').bind(new Date().toISOString()).all()).results || [];
          const del = ses.filter(s => norm(s.user) === c.slug).map(s => s.token);
          if (del.length) await env.DB.batch(del.map(t => env.DB.prepare('DELETE FROM sessions WHERE token = ?').bind(t)));
          try { await env.DB.prepare('DELETE FROM kv_cache WHERE k = ?').bind('login_fail:' + c.slug).run(); } catch (_) {}
        } catch (e) { return json({ error: String((e && e.message) || e) }, 500); }
        return json({ ok: true, usuario: c.slug, nombre: c.nombre });
      }
      // GET /admin/vendedores → estado de las vendedoras secundarias (para la card de Admin): si tienen contraseña y están activas.
      if (request.method === 'GET' && path === '/admin/vendedores') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        const out = [];
        for (const c of COMERCIALES_SECUNDARIOS) {
          let u = null; try { u = await env.DB.prepare("SELECT activo, CASE WHEN IFNULL(password_hash, '') NOT IN ('', 'REDACTADO') THEN 1 ELSE 0 END AS pw FROM users_panel WHERE id = ?").bind(c.slug).first(); } catch (_) {}
          out.push({ slug: c.slug, nombre: c.nombre, soloNeon: !!c.soloNeon, existe: !!u, activo: !!(u && +u.activo === 1), contrasena: !!(u && +u.pw === 1) });
        }
        return json({ ok: true, vendedores: out });
      }

      // POST /admin/wa/chat-import {phone, dry?} — "Traer de Joaco" (pedido de Gaspar, 1-oct): una vendedora
      // habilitada (hoy solo Agus) se trae a SU bandeja un chat que está en la de Joaco. Pasa el chat + la comisión
      // de sus presupuestos (briefs.comercial_id), igual que chat-assign. SOLO desde la bandeja de Joaco (inbox
      // 'general', assigned_to '' o 'joaco'): nunca de Facu ni de cursos/privado/corte/precotiz/oculto; no IG, no
      // internos, no chats inexistentes (UPDATE condicional, no crea filas), no leads que el bot todavía releva
      // (cambiaría de "Joaco" a "Agus" a mitad de la charla) ni clientes que ya arrancaron el cierre/pago con Joaco
      // (mismo criterio que la lista "para llamar"). Todo en UN batch (transacción) + registro en chat_assign_log
      // (via='import', ts = assigned_at) → NO consume la cuota del reparto ni cuenta en "chats asignados hoy".
      // Errores genéricos para la vendedora (no revela en qué bandeja está un chat ajeno); detalle solo al admin.
      // dry:true = valida sin cambiar nada. Admin puede hacerlo en nombre de una importadora con {para:'agustina'}.
      // Review 1-oct: sin búsqueda "a ojo" por sufijo con área (traía el chat de OTRA persona de otra área).
      if (request.method === 'POST' && path === '/admin/wa/chat-import') {
        const IMPORTADORAS = ['agustina'];   // Debi NO (Gaspar 17-oct: 'que no pueda traer de joaco')
        const role = await getSessionRole(env, session.user);
        const esAdm = role === 'admin';
        const meSlug = String(session.user || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
        const body = (await request.json().catch(() => null)) || {};
        const para = esAdm ? String(body.para || '').toLowerCase().trim() : (role === 'comercial' ? meSlug : '');
        if (!IMPORTADORAS.includes(para)) return json({ error: 'No tenés habilitado traer chats de la bandeja de Joaco.' }, 403);
        // La importadora tiene que seguir activa (una sesión dura 30 días y sobrevive a una baja).
        try {
          if (!(await env.DB.prepare("SELECT 1 AS x FROM users_panel WHERE id = ? AND activo = 1 AND rol = 'comercial'").bind(para).first())) return json({ error: 'Usuario no habilitado.' }, 403);
        } catch (_) { return json({ error: 'No pude validar el usuario. Probá de nuevo.' }, 503); }
        const dry = body.dry === true;
        const dig = String(body.phone || '').replace(/\D/g, '');
        if (dig.length < 8) return json({ error: 'Poné el teléfono completo, con código de área.' }, 400);
        const sel = "SELECT phone, inbox, assigned_to, channel, last_ts, contact_name FROM wa_chats_summary WHERE phone = ?";
        // Resolver SIN adivinar: (1) dígitos tal cual; (2) variantes argentinas EXACTAS: 549 + área + número
        // (sacando 00/54/9/0 y el "15" después de un área de 2-4 dígitos); (3) solo si tipeó 8-9 dígitos (sin área):
        // por los últimos 8 entre los chats que SÍ se pueden traer, y siempre pidiendo confirmación (needs_confirm).
        let row = await env.DB.prepare(sel).bind(dig).first();
        if (!row) {
          let d = dig;
          if (d.startsWith('00')) d = d.slice(2);
          if (d.startsWith('54')) d = d.slice(2);
          if (d.length === 11 && d.startsWith('9')) d = d.slice(1);
          if (d.startsWith('0')) d = d.slice(1);
          const vars = new Set();
          if (d.length === 10) vars.add('549' + d);
          if (d.length === 12) for (const a of [2, 3, 4]) if (d.substr(a, 2) === '15') vars.add('549' + d.slice(0, a) + d.slice(a + 2));
          for (const v of vars) { if (v === dig) continue; row = await env.DB.prepare(sel).bind(v).first(); if (row) break; }
        }
        if (!row && dig.length <= 9) {
          const cands = (await env.DB.prepare(
            "SELECT phone, contact_name FROM wa_chats_summary WHERE substr(phone, -8) = ? AND phone LIKE '549%' AND length(phone) = 13 AND IFNULL(last_ts, '') != '' " +
            "AND COALESCE(NULLIF(inbox, ''), 'general') = 'general' AND IFNULL(assigned_to, '') IN ('', 'joaco') AND phone NOT IN (SELECT phone FROM wa_internal_phones) LIMIT 5"
          ).bind(dig.slice(-8)).all()).results || [];
          if (cands.length) return json({ ok: false, needs_confirm: true, candidatos: cands.map(c => ({ phone: c.phone, nombre: c.contact_name || '' })) }, 409);
        }
        if (!row || !String(row.last_ts || '')) return json({ error: 'No encontré ningún chat con ese número. Revisá que tenga el código de área.' }, 404);
        const ph = String(row.phone);
        const nombre = row.contact_name || '';
        const asg = String(row.assigned_to || '');
        const inbox = String(row.inbox || '') || 'general';
        const no = (detalle) => json({ error: esAdm ? detalle : 'Ese chat no está en la bandeja de Joaco.' }, 409);
        if (String(row.channel || '') === 'ig' || ph.length >= 15) return json({ error: 'Ese contacto es de Instagram, no se puede traer por teléfono.' }, 400);
        try { if (await env.DB.prepare('SELECT 1 AS x FROM wa_internal_phones WHERE phone = ?').bind(ph).first()) return no('Es un número interno del equipo.'); } catch (_) {}
        if (inbox !== 'general') return no('Está en la bandeja "' + inbox + '".');
        if (asg === para) return json({ ok: true, ya_era_tuyo: true, phone: ph, nombre, last_ts: row.last_ts || '' });
        if (asg !== '' && asg !== 'joaco') return no('Está asignado a ' + asg + '.');
        try { if (await env.DB.prepare("SELECT 1 AS x FROM precotiz_pilot WHERE phone = ? AND estado = 'activo' LIMIT 1").bind(ph).first()) return json({ error: 'El bot todavía le está pidiendo los datos a este lead. Traelo cuando termine.' }, 409); } catch (_) {}
        // Vendedora de solo neón: nunca un lead de corpóreo.
        if ((COMERCIALES_SECUNDARIOS.find(c => c.slug === para) || {}).soloNeon && (await leadEsCorporeo(env, ph, ''))) return json({ error: 'Ese cliente es de corpóreo: lo atiende otro vendedor.' }, 409);
        try {
          const cierre = FUP_CIERRE_MARKERS.map(() => 'lower(body) LIKE ?').join(' OR ');
          const yaCierre = await env.DB.prepare("SELECT 1 AS x FROM wa_messages WHERE phone = ? AND direction = 'outbound' AND (" + cierre + ") LIMIT 1").bind(ph, ...FUP_CIERRE_MARKERS.map(k => '%' + k.toLowerCase() + '%')).first();
          const yaPedido = yaCierre ? null : await env.DB.prepare('SELECT 1 AS x FROM pedidos WHERE telefono = ? LIMIT 1').bind(ph).first();
          if (yaCierre || yaPedido) return json({ error: 'Ese cliente ya arrancó el cierre o el pago con Joaco, se queda con él.' }, 409);
        } catch (_) { return json({ error: 'No pude chequear el chat. Probá de nuevo.' }, 503); }
        if (dry) return json({ ok: true, dry: true, phone: ph, nombre, de: 'joaco', a: para });
        const now = new Date().toISOString();
        // Las sentencias que dependen de la reasignación solo aplican si el UPDATE condicional de verdad movió el chat
        // (guarda: assigned_to = para AND assigned_at = now). Todo en el mismo batch → o se aplica todo o nada.
        const guard = ' AND EXISTS (SELECT 1 FROM wa_chats_summary WHERE phone = ? AND assigned_to = ? AND assigned_at = ?)';
        let res;
        try {
          res = await env.DB.batch([
            env.DB.prepare("UPDATE wa_chats_summary SET assigned_to = ?, assigned_at = ? WHERE phone = ? AND COALESCE(NULLIF(inbox, ''), 'general') = 'general' AND IFNULL(assigned_to, '') IN ('', 'joaco')").bind(para, now, ph),
            env.DB.prepare('UPDATE briefs SET comercial_id = ? WHERE cliente_wa_id = ?' + guard).bind(para, ph, ph, para, now),   // la comisión sigue al lead (OK de Gaspar)
            env.DB.prepare('DELETE FROM archived_chats WHERE phone = ?' + guard).bind(ph, ph, para, now),                       // archivado es global: si Joaco lo archivó, a Agus le quedaba invisible
            env.DB.prepare("INSERT INTO chat_assign_log (phone, from_asg, to_asg, via, by_user, ts) SELECT ?, 'joaco', ?, 'import', ?, ? WHERE EXISTS (SELECT 1 FROM wa_chats_summary WHERE phone = ? AND assigned_to = ? AND assigned_at = ?)").bind(ph, para, String(session.user || ''), now, ph, para, now),
          ]);
        } catch (_) { return json({ error: 'No se pudo traer el chat (la base no respondió). Probá de nuevo.' }, 503); }
        if (!res || !res[0] || !res[0].meta || !res[0].meta.changes) return json({ error: 'El chat cambió de bandeja recién. Probá de nuevo.' }, 409);
        await invalidateChatsSummaryCache(request);   // con await: el front recarga la lista apenas recibe el ok
        return json({ ok: true, phone: ph, nombre, last_ts: row.last_ts || '', de: 'joaco', a: para });
      }

      // Bulk: derivar varios chats a una bandeja de una (solo admin).
      if (request.method === 'POST' && path === '/admin/wa/chat-inbox-bulk') {
        const role = await getSessionRole(env, session.user);
        if (role !== 'admin') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const inbox = body?.inbox;
        const phones = Array.isArray(body?.phones) ? body.phones : [];
        if (!['cursos', 'general'].includes(inbox) || !phones.length) {
          return json({ error: 'inbox (cursos|general) y phones[] requeridos' }, 400);
        }
        const now = new Date().toISOString();
        const stmts = phones
          .map(p => String(p || '').replace(/\D/g, ''))
          .filter(p => p.length >= 8)
          .map(p => env.DB.prepare(
            `INSERT INTO wa_chats_summary (phone, inbox, updated_at) VALUES (?, ?, ?)
             ON CONFLICT(phone) DO UPDATE SET inbox = excluded.inbox`
          ).bind(p, inbox, now));
        if (stmts.length) await env.DB.batch(stmts);
        ctx.waitUntil(invalidateChatsSummaryCache(request));
        return json({ ok: true, updated: stmts.length, inbox });
      }

      // Marcar conversación como leída
      if (request.method === 'POST' && path === '/admin/wa/mark-read') {
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { phone, ts } = body || {};
        if (!phone || !ts) return json({ error: 'missing phone or ts' }, 400);
        // Invalidar cache del chats-summary: el unread count del chat marcado
        // cambia a 0 y el badge tiene que refrescar al instante (no esperar 4s).
        ctx.waitUntil(invalidateChatsSummaryCache(request));
        try {
          await env.DB.prepare(
            'INSERT INTO wa_read_cursor (phone, last_read_ts, updated_at) VALUES (?, ?, ?) ON CONFLICT(phone) DO UPDATE SET last_read_ts = excluded.last_read_ts, updated_at = excluded.updated_at'
          ).bind(phone, ts, new Date().toISOString()).run();
          // Resetear el contador de no leídos en la libreta resumen (el trigger
          // solo suma; el reset a 0 lo hacemos acá al marcar el chat como leído).
          try { await env.DB.prepare('UPDATE wa_chats_summary SET unread = 0 WHERE phone = ?').bind(phone).run(); } catch (_) {}
        } catch (e) {
          try {
            await env.DB.prepare('CREATE TABLE IF NOT EXISTS wa_read_cursor (phone TEXT PRIMARY KEY, last_read_ts TEXT NOT NULL, updated_at TEXT NOT NULL)').run();
            await env.DB.prepare(
              'INSERT OR REPLACE INTO wa_read_cursor (phone, last_read_ts, updated_at) VALUES (?, ?, ?)'
            ).bind(phone, ts, new Date().toISOString()).run();
          } catch (_) {}
        }

        // Marcar el último inbound como leído en WhatsApp (doble tilde azul al cliente).
        // Solo lo hacemos para el ÚLTIMO mensaje inbound del contacto — Meta automáticamente
        // marca todos los anteriores como leídos también.
        try {
          const lastInbound = await env.DB.prepare(
            "SELECT wamid FROM wa_messages WHERE phone = ? AND direction = 'inbound' AND wamid != '' AND ts <= ? ORDER BY ts DESC LIMIT 1"
          ).bind(phone, ts).first();
          if (lastInbound?.wamid && lastInbound.wamid.startsWith('wamid.')) {
            await waSend(env, {
              messaging_product: 'whatsapp',
              status: 'read',
              message_id: lastInbound.wamid,
              // Bonus: typing indicator para mostrar que estamos por contestar.
              typing_indicator: { type: 'text' }
            });
          }
        } catch (e) { /* mark-read en WA es best-effort, no rompe el flow del cursor */ }

        return json({ ok: true });
      }

      // ===== Enviar media (foto/audio) por WhatsApp =====
      // ===== Stickers favoritos =====
      // Gaspar se manda sus stickers al numero desde su WhatsApp personal -> entran como
      // inbound (WebP cacheado en R2). Los marca como favoritos y los reusa desde un picker.
      if (request.method === 'GET' && path === '/admin/wa/sticker-favs') {
        try {
          await env.DB.prepare("CREATE TABLE IF NOT EXISTS sticker_favs (r2_key TEXT PRIMARY KEY, added_at TEXT NOT NULL)").run();
          const rs = await env.DB.prepare("SELECT r2_key, added_at FROM sticker_favs ORDER BY added_at DESC").all();
          return json({ stickers: rs.results || [] });
        } catch (e) { return json({ stickers: [] }); }
      }
      if (request.method === 'POST' && path === '/admin/wa/sticker-fav') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { r2_key, remove } = body || {};
        if (!r2_key || !String(r2_key).startsWith('wa/')) return json({ error: 'r2_key invalido' }, 400);
        try {
          await env.DB.prepare("CREATE TABLE IF NOT EXISTS sticker_favs (r2_key TEXT PRIMARY KEY, added_at TEXT NOT NULL)").run();
          if (remove) await env.DB.prepare("DELETE FROM sticker_favs WHERE r2_key = ?").bind(r2_key).run();
          else await env.DB.prepare("INSERT OR IGNORE INTO sticker_favs (r2_key, added_at) VALUES (?, ?)").bind(r2_key, new Date().toISOString()).run();
          return json({ ok: true });
        } catch (e) { return json({ error: String(e) }, 500); }
      }
      // Mandar un sticker favorito: lo saca de R2, lo sube a WhatsApp y lo manda como type=sticker.
      if (request.method === 'POST' && path === '/admin/wa/send-sticker') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { to, r2_key } = body || {};
        if (!to || !r2_key) return json({ error: 'missing to or r2_key' }, 400);
        const num = normalizeArPhone(to);
        if (!num) return json({ error: 'numero invalido' }, 400);
        { const _role = await getSessionRole(env, session.user); if (!(await inboxAccessOk(env, _role, num, session.user))) return json({ error: 'forbidden: chat fuera de tu bandeja' }, 403); }
        if (!env.MEDIA) return json({ error: 'R2 not configured' }, 500);
        const obj = await env.MEDIA.get(r2_key);
        if (!obj) return json({ error: 'sticker no encontrado' }, 404);
        const mediaId = await uploadMediaToMeta(env, await obj.arrayBuffer(), 'image/webp', 'sticker.webp');
        if (!mediaId) return json({ error: 'no se pudo subir el sticker a WhatsApp' }, 502);
        const r = await waSend(env, { messaging_product: 'whatsapp', to: num, type: 'sticker', sticker: { id: mediaId } });
        await logWaEvent(env, { to: num, kind: 'sticker', ref: r2_key, ok: r.ok, messageId: r.id, error: r.error });
        if (!r.ok) return json({ error: r.error, raw: r.raw }, r.status || 500);
        try { await env.DB.prepare("INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status) VALUES (?, ?, 'outbound', ?, '', 'sticker', '', ?, '', 'sent')").bind(new Date().toISOString(), r.id || '', num, r2_key).run(); } catch (_) {}
        return json({ id: r.id });
      }

      if (request.method === 'POST' && path === '/admin/wa/send-media') {
        const ct = request.headers.get('Content-Type') || '';
        if (!ct.includes('multipart/form-data')) return json({ error: 'expected multipart/form-data' }, 400);
        const fd = await request.formData();
        const to = fd.get('to');
        // Rol 'cursos' (Abril) solo puede mandar media a chats de su bandeja.
        {
          const _role = await getSessionRole(env, session.user);
          if (!(await inboxAccessOk(env, _role, String(to || '').replace(/\D/g, ''), session.user))) {
            return json({ error: 'forbidden: chat fuera de tu bandeja' }, 403);
          }
        }
        let type = fd.get('type'); // image | audio | document | video (default detectado del mime)
        const caption = fd.get('caption') || '';
        const replyTo = fd.get('reply_to') || '';
        const file = fd.get('file');
        if (!to || !file) return json({ error: 'missing to or file' }, 400);
        const num = normalizeArPhone(to);
        if (!num) return json({ error: 'numero invalido' }, 400);
        const fileMime = file.type || '';
        // Auto-detect type si no vino especificado o si vino "auto"
        if (!type || type === 'auto') {
          if (fileMime.startsWith('image/')) type = 'image';
          else if (fileMime.startsWith('audio/')) type = 'audio';
          else if (fileMime.startsWith('video/')) type = 'video';
          else type = 'document';
        }
        // 1. Upload to R2
        const fileName = file.name || ('file_' + Date.now());
        const ext = fileName.includes('.') ? '.' + fileName.split('.').pop() : '';
        const r2Key = `wa/out_${Date.now()}_${Math.random().toString(36).slice(2, 7)}${ext}`;
        const buf = await file.arrayBuffer();
        const defaultMime = type === 'audio' ? 'audio/ogg; codecs=opus'
                          : type === 'image' ? 'image/jpeg'
                          : type === 'video' ? 'video/mp4'
                          : 'application/octet-stream';
        const mime = fileMime || defaultMime;
        const cleanMime = mime.split(';')[0].trim();
        await env.MEDIA.put(r2Key, buf, { httpMetadata: { contentType: cleanMime } });
        // Presupuesto del cotizador (render en memoria) con la ventana de 24h CERRADA: Meta acepta
        // el envío libre y lo rechaza async (131047) → la foto nunca llega y salía texto pelado.
        // Cortamos ANTES y devolvemos la key R2 del render recién subido para que el front lo mande
        // como plantilla aprobada CON foto (presupuesto_detallado_img). Solo para el flujo de
        // presupuesto (form 'presupuesto'=1); NO toca el adjuntar-imagen normal del chat.
        if (type === 'image' && String(fd.get('presupuesto') || '') === '1') {
          try {
            const _since24 = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
            const _inb = await env.DB.prepare("SELECT 1 FROM wa_messages WHERE phone = ? AND direction = 'inbound' AND ts > ? LIMIT 1").bind(num, _since24).first();
            if (!_inb) return json({ error: 'Re-engagement message', window_closed: true, has_render: true, render_key: r2Key }, 409);
          } catch (_) {}
        }
        // 2. Upload media a WhatsApp (Meta o 360dialog) para obtener el media id.
        // Subimos con el mime LIMPIO (360dialog rechaza el param "; codecs=opus").
        // La NOTA DE VOZ no depende del mime del upload, sino del flag voice:true
        // en el send (ver abajo) + que el archivo sea ogg/opus (lo es: OggS+OpusHead).
        const _wa1 = getWaClient(env);
        const uploadFd = new FormData();
        uploadFd.append('messaging_product', 'whatsapp');
        uploadFd.append('file', new Blob([buf], { type: cleanMime }), fileName);
        uploadFd.append('type', cleanMime);
        const uploadR = await fetch(_wa1.mediaUploadUrl(), { method: 'POST', headers: _wa1.headers, body: uploadFd });
        const uploadData = await uploadR.json().catch(() => ({}));
        if (!uploadR.ok || !uploadData.id) {
          // Log de diagnóstico: mime recibido + respuesta cruda del provider.
          try { await env.DB.prepare('INSERT INTO wa_webhook_log (ts, payload) VALUES (?, ?)').bind(new Date().toISOString(), `AUDIO_FAIL type=${type} mimeRecibido=${mime} clean=${cleanMime} status=${uploadR.status} resp=${JSON.stringify(uploadData).slice(0, 600)}`).run(); } catch (_) {}
          return json({ error: 'media upload failed', detail: (uploadData?.error?.message || uploadData?.error || JSON.stringify(uploadData) || '').toString().slice(0, 200) }, 500);
        }
        const mediaId = uploadData.id;
        // 3. Send via WA API
        let payload;
        if (type === 'image') {
          payload = { messaging_product: 'whatsapp', to: num, type: 'image', image: { id: mediaId, caption: caption || undefined } };
        } else if (type === 'audio') {
          // voice:true → 360dialog/WhatsApp lo renderiza como NOTA DE VOZ (PTT,
          // con ondita), NO como archivo adjunto. Requiere que el archivo sea
          // ogg/opus (lo es). Sin este flag llega como audio-archivo (que es lo
          // que pasaba). Feature beta de la Cloud API, sin allowlisting.
          // Doc: docs.360dialog.com/docs/messaging/media/voice-message-beta-program
          payload = { messaging_product: 'whatsapp', to: num, type: 'audio', audio: { id: mediaId, voice: true } };
        } else if (type === 'video') {
          payload = { messaging_product: 'whatsapp', to: num, type: 'video', video: { id: mediaId, caption: caption || undefined } };
        } else { // document
          payload = { messaging_product: 'whatsapp', to: num, type: 'document', document: { id: mediaId, caption: caption || undefined, filename: fileName } };
        }
        if (replyTo) payload.context = { message_id: replyTo };
        const r = await waSend(env, payload);
        await logWaEvent(env, { to: num, kind: type, ref: '', ok: r.ok, messageId: r.id, error: r.error });
        if (!r.ok) return json({ error: r.error }, r.status || 500);
        // Autor real (avisos internos), en segundo plano: no demora el guardado (acá es UPSERT, la fila fantasma no le gana).
        ctx.waitUntil(registrarAutorEnvio(env, r.id, session.user, num));
        // 4. Save in wa_messages
        let body = caption || '';
        if (type === 'image') body = body || '[imagen]';
        else if (type === 'video') body = body || '[video]';
        else if (type === 'document') body = body || ('[documento] ' + fileName);
        else if (type === 'audio') {
          try {
            const transcript = await transcribeAudio(env, r2Key);
            if (transcript) body = '[audio] ' + transcript;
            else body = '[audio]';
          } catch (_) { body = '[audio]'; }
        }
        try {
          // UPSERT (NO "INSERT OR IGNORE"): el webhook de status ('sent') puede
          // crear un placeholder msg_type='status' con este wamid ANTES de que
          // termine el upload del audio/imagen (es lento: R2 + Cloud API). Con
          // INSERT OR IGNORE el placeholder ganaba y la data real (media_url,
          // tipo, body) se perdía → el media no se veía en otras PCs y quien lo
          // mandó lo re-enviaba (de ahí el "se manda dos veces"). Con ON CONFLICT
          // pisamos el placeholder con la data real, sin tocar el status ya
          // avanzado (delivered/read).
          await env.DB.prepare(
            `INSERT INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
             ON CONFLICT(wamid) DO UPDATE SET
               msg_type = excluded.msg_type,
               body = excluded.body,
               media_url = excluded.media_url,
               context_id = excluded.context_id
             WHERE wa_messages.msg_type = 'status' OR wa_messages.media_url IS NULL OR wa_messages.media_url = ''`
          ).bind(new Date().toISOString(), r.id || '', 'outbound', num, autorSlug(session.user), type, body, r2Key, replyTo || '', 'sent').run(); // sender_name = quién lo mandó (panel de rendimiento)
        } catch (_) {}
        return json({ id: r.id, r2Key, type });
      }

      // ===== Enviar presupuesto de un brief: render (foto) + presupuesto de caption =====
      // body: { brief_id, to, caption }
      // Manda el render del brief como IMAGEN con el texto del presupuesto de
      // pie de foto, en un solo mensaje (como pidió Gaspar). Si el brief no
      // tiene render, manda solo el texto. Si el caption supera el límite de
      // WhatsApp (1024 chars), manda la imagen sin caption + el texto aparte.
      if (request.method === 'POST' && path === '/admin/wa/send-brief-presupuesto') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { brief_id, to, caption } = body || {};
        if (!to || !caption) return json({ error: 'missing to or caption' }, 400);
        const num = normalizeArPhone(to);
        if (!num) return json({ error: 'numero invalido' }, 400);

        // Buscar el render más reciente del brief (ANTES del check de ventana: si la
        // ventana está cerrada, le avisamos al front si HAY render para que mande la
        // plantilla CON imagen (presupuesto_detallado_img) en vez de la de solo texto).
        let renderKey = null;
        if (brief_id) {
          try {
            const row = await env.DB.prepare(
              "SELECT r2_key FROM brief_imagenes WHERE brief_id = ? AND tipo = 'render' ORDER BY created_at DESC, id DESC LIMIT 1"
            ).bind(brief_id).first();
            if (row && row.r2_key) renderKey = row.r2_key;
          } catch (_) {}
        }

        // ¿Ventana de 24h abierta? (el cliente escribió en las últimas 24h). Si NO,
        // no intentamos el envío libre (imagen/texto): Meta lo acepta y después lo
        // rechaza async con 131047 ("Re-engagement message"). Avisamos al front
        // (window_closed + has_render) para que mande la plantilla aprobada
        // (con imagen si hay render), que SÍ se puede fuera de ventana.
        try {
          const since24 = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
          const inb = await env.DB.prepare(
            "SELECT 1 FROM wa_messages WHERE phone = ? AND direction = 'inbound' AND ts > ? LIMIT 1"
          ).bind(num, since24).first();
          // render_key para la plantilla con foto: el del brief si lo hay; si no, la key R2
          // del blob que ACABAMOS de subir (el cotizador manda el render en memoria, sin brief).
          if (!inb) { const rk = renderKey || ''; return json({ error: 'Re-engagement message', window_closed: true, has_render: !!rk, render_key: rk }, 409); }
        } catch (_) {}

        const CAPTION_MAX = 1024;
        const nowIso = () => new Date().toISOString();
        // Trazabilidad: marcamos QUIÉN mandó el presupuesto (el vendedor logueado: 'joaco'/'nadia')
        // en sender_name del mensaje saliente, para poder rastrear después de qué vendedor salió.
        const senderSlug = await resolveComercial(env, { sessionUser: session.user, phone: num });
        const saveMsg = async (wamid, type, bodyTxt, mediaKey) => {
          try {
            await env.DB.prepare(
              'INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
            ).bind(nowIso(), wamid || '', 'outbound', num, senderSlug, type, bodyTxt, mediaKey || '', '', 'sent').run();
          } catch (_) {}
        };

        let usedImage = false, splitText = false, mainId = '';

        if (renderKey) {
          const obj = await env.MEDIA.get(renderKey);
          if (obj) {
            const buf = await obj.arrayBuffer();
            const mime = obj.httpMetadata?.contentType || 'image/jpeg';
            const fileName = renderKey.split('/').pop() || 'render.jpg';
            const _wa = getWaClient(env);
            const fd = new FormData();
            fd.append('messaging_product', 'whatsapp');
            fd.append('file', new Blob([buf], { type: mime }), fileName);
            fd.append('type', mime);
            const upR = await fetch(_wa.mediaUploadUrl(), { method: 'POST', headers: _wa.headers, body: fd });
            const upJ = await upR.json().catch(() => ({}));
            if (upR.ok && upJ.id) {
              usedImage = true;
              const fits = String(caption).length <= CAPTION_MAX;
              const imgCaption = fits ? caption : '';
              const r = await waSend(env, { messaging_product: 'whatsapp', to: num, type: 'image', image: { id: upJ.id, caption: imgCaption || undefined } });
              await logWaEvent(env, { to: num, kind: 'image', ref: 'brief:' + (brief_id || ''), ok: r.ok, messageId: r.id, error: r.error });
              if (!r.ok) return json({ error: r.error || 'image send failed' }, r.status || 500);
              mainId = r.id || '';
              await saveMsg(r.id, 'image', imgCaption || '[imagen]', renderKey);
              // Caption no entraba → mandar el texto como segundo mensaje.
              if (!fits) {
                splitText = true;
                const rt = await waSendText(env, num, caption);
                await saveMsg(rt.id, 'text', caption, '');
              }
            }
          }
        }

        // Sin render (o el upload falló): mandar solo texto.
        if (!usedImage) {
          const rt = await waSendText(env, num, caption);
          await logWaEvent(env, { to: num, kind: 'text', ref: 'brief:' + (brief_id || ''), ok: rt.ok, messageId: rt.id, error: rt.error });
          if (!rt.ok) return json({ error: rt.error || 'text send failed' }, rt.status || 500);
          mainId = rt.id || '';
          await saveMsg(rt.id, 'text', caption, '');
        }

        return json({ id: mainId, hasImage: usedImage, splitText });
      }

      // ===== Forward (reenviar) un mensaje a uno o varios contactos =====
      // body: { wamid: "...", to_phones: ["549...", "549..."] }
      if (request.method === 'POST' && path === '/admin/wa/forward') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        // Acepta wamids[] (varios mensajes, estilo WhatsApp) o wamid (uno solo, compat).
        const wamids = Array.isArray(body?.wamids) ? body.wamids : (body?.wamid ? [body.wamid] : []);
        const to_phones = Array.isArray(body?.to_phones) ? body.to_phones : [];
        if (!wamids.length || !to_phones.length) return json({ error: 'missing wamids or to_phones' }, 400);
        // Tope anti-spam: a Gaspar le bloquearon el número una vez por mandar de más.
        if (to_phones.length > 30) return json({ error: 'demasiados destinatarios (máx 30 por seguridad de WhatsApp)' }, 400);
        const results = { sent: 0, failed: 0, errors: [] };
        // Helper: subir un blob existente en R2 a Meta y devolver media id
        const uploadFromR2ToMeta = async (r2Key) => {
          const obj = await env.MEDIA.get(r2Key);
          if (!obj) return null;
          const buf = await obj.arrayBuffer();
          const mime = obj.httpMetadata?.contentType || 'application/octet-stream';
          const fileName = r2Key.split('/').pop() || 'file';
          const _waRe = getWaClient(env);
          const fd = new FormData();
          fd.append('messaging_product', 'whatsapp');
          fd.append('file', new Blob([buf], { type: mime }), fileName);
          fd.append('type', mime);
          const upR = await fetch(_waRe.mediaUploadUrl(), {
            method: 'POST',
            headers: _waRe.headers,
            body: fd
          });
          const upJ = await upR.json().catch(() => ({}));
          return upR.ok && upJ.id ? { id: upJ.id, mime, fileName } : null;
        };
        // Sub-helper para limpiar el body cuando es 'image' con descripción inyectada
        const cleanBody = (bd, type) => {
          if (!bd) return '';
          if (type === 'audio' && bd.startsWith('[audio] ')) return ''; // la transcripción no se reenvía
          if (type === 'image') {
            const idx = bd.indexOf('[imagen]');
            if (idx >= 0) return bd.slice(0, idx).trim();
          }
          if (type === 'video') {
            const idx = bd.indexOf('[video]');
            if (idx >= 0) return bd.slice(0, idx).trim();
          }
          if (type === 'document') {
            const idx = bd.indexOf('[documento]');
            if (idx >= 0) return bd.slice(0, idx).trim();
          }
          return bd;
        };
        // Pre-fetch de los mensajes + subir su media UNA sola vez (se reusa el media_id para
        // todos los destinatarios → más rápido y menos carga en la API). Orden = el de wamids.
        const items = [];
        for (const w of wamids) {
          const original = await env.DB.prepare('SELECT msg_type, body, media_url FROM wa_messages WHERE wamid = ? LIMIT 1').bind(w).first();
          if (!original) continue;
          let up = null;
          if (original.msg_type !== 'text' && original.media_url && !/^https?:/i.test(original.media_url)) {
            up = await uploadFromR2ToMeta(original.media_url);
          }
          items.push({ original, up });
        }
        if (!items.length) return json({ error: 'ningún mensaje original encontrado' }, 404);
        results.recipients = to_phones.length;
        results.messages = items.length;
        for (const rawPhone of to_phones) {
          const num = normalizeArPhone(rawPhone);
          if (!num) { results.failed++; results.errors.push({ phone: rawPhone, error: 'numero invalido' }); continue; }
          for (const it of items) {
            const original = it.original;
            try {
              let res;
              if (original.msg_type === 'text' || !original.media_url) {
                res = await waSendText(env, num, original.body || '');
              } else if (!it.up) {
                results.failed++; results.errors.push({ phone: num, error: 'no se pudo subir media a Meta' }); continue;
              } else {
                const caption = cleanBody(original.body, original.msg_type);
                let payload;
                if (original.msg_type === 'image') payload = { messaging_product: 'whatsapp', to: num, type: 'image', image: { id: it.up.id, caption: caption || undefined } };
                else if (original.msg_type === 'video') payload = { messaging_product: 'whatsapp', to: num, type: 'video', video: { id: it.up.id, caption: caption || undefined } };
                else if (original.msg_type === 'audio') payload = { messaging_product: 'whatsapp', to: num, type: 'audio', audio: { id: it.up.id, voice: true } };
                else if (original.msg_type === 'sticker') payload = { messaging_product: 'whatsapp', to: num, type: 'sticker', sticker: { id: it.up.id } };
                else payload = { messaging_product: 'whatsapp', to: num, type: 'document', document: { id: it.up.id, caption: caption || undefined, filename: it.up.fileName } };
                res = await waSend(env, payload);
              }
              if (res.ok) {
                results.sent++;
                try {
                  await env.DB.prepare(
                    'INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
                  ).bind(new Date().toISOString(), res.id || '', 'outbound', num, autorSlug(session.user), original.msg_type, original.body || '', original.media_url || '', '', 'sent').run();
                } catch (_) {}
              } else {
                results.failed++;
                results.errors.push({ phone: num, error: res.error || 'send failed' });
              }
            } catch (e) {
              results.failed++;
              results.errors.push({ phone: rawPhone, error: e.message });
            }
          }
        }
        return json(results);
      }

      // ===== Reaccionar a un mensaje (emoji) =====
      // body: { phone, wamid, emoji }   — emoji vacío = quitar la reacción
      if (request.method === 'POST' && path === '/admin/wa/react') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { phone, wamid, emoji } = body || {};
        if (!phone || !wamid) return json({ error: 'missing phone or wamid' }, 400);
        const num = normalizeArPhone(phone);
        if (!num) return json({ error: 'numero invalido' }, 400);
        const payload = {
          messaging_product: 'whatsapp',
          recipient_type: 'individual',
          to: num,
          type: 'reaction',
          reaction: { message_id: wamid, emoji: emoji || '' }
        };
        const r = await waSend(env, payload);
        await logWaEvent(env, { to: num, kind: 'reaction', ref: wamid, ok: r.ok, messageId: r.id, error: r.error });
        if (!r.ok) return json({ error: r.error }, r.status || 500);
        try {
          await env.DB.prepare(
            'INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
          ).bind(new Date().toISOString(), r.id || '', 'outbound', num, '', 'reaction', emoji || '', '', wamid, 'sent').run();
        } catch (_) {}
        return json({ ok: true, id: r.id });
      }

      // ===== Quick Replies CRUD =====
      if (request.method === 'GET' && path === '/admin/quick-replies') {
        try {
          const rs = await env.DB.prepare('SELECT id, shortcut, body, media_r2_key, vertical FROM quick_replies ORDER BY shortcut').all();
          return json({ replies: rs.results || [] });
        } catch (e) { return json({ replies: [] }); }
      }
      if (request.method === 'POST' && path === '/admin/quick-replies') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { shortcut, body: text, media_r2_key, vertical } = body || {};
        if (!shortcut || (!text && !media_r2_key)) return json({ error: 'missing shortcut, body or media' }, 400);
        const sc = shortcut.toLowerCase().replace(/\s+/g, '_');
        const vert = (vertical === 'cursos') ? 'cursos' : 'carteles';
        await env.DB.prepare('INSERT OR REPLACE INTO quick_replies (shortcut, body, media_r2_key, vertical, created_at) VALUES (?, ?, ?, ?, ?)')
          .bind(sc, text || '', media_r2_key || null, vert, new Date().toISOString()).run();
        return json({ ok: true });
      }
      if (request.method === 'DELETE' && path.startsWith('/admin/quick-replies/')) {
        const id = path.split('/').pop();
        // Borrar también la imagen de R2 si tenía
        try {
          const row = await env.DB.prepare('SELECT media_r2_key FROM quick_replies WHERE id = ?').bind(id).first();
          if (row?.media_r2_key) await env.MEDIA.delete(row.media_r2_key);
        } catch (_) {}
        await env.DB.prepare('DELETE FROM quick_replies WHERE id = ?').bind(id).run();
        return json({ ok: true });
      }
      // Subir imagen para usar en quick replies. Devuelve la R2 key.
      if (request.method === 'POST' && path === '/admin/quick-replies/upload') {
        try {
          const fd = await request.formData();
          const file = fd.get('file');
          if (!file || typeof file === 'string') return json({ error: 'missing file' }, 400);
          const ext = file.name ? '.' + file.name.split('.').pop() : '.jpg';
          const r2Key = `qr/${Date.now()}_${Math.random().toString(36).slice(2, 8)}${ext}`;
          const buf = await file.arrayBuffer();
          const mime = file.type || 'image/jpeg';
          await env.MEDIA.put(r2Key, buf, { httpMetadata: { contentType: mime } });
          return json({ ok: true, r2_key: r2Key });
        } catch (e) { return json({ error: e.message }, 500); }
      }
      // Enviar quick reply: el server resuelve si tiene imagen, la sube a Meta
      // (desde R2) y manda imagen+caption en una sola llamada. Sin imagen → texto.
      if (request.method === 'POST' && path === '/admin/wa/send-quick-reply') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { phone, qr_id } = body || {};
        if (!phone || !qr_id) return json({ error: 'missing phone or qr_id' }, 400);
        const qr = await env.DB.prepare('SELECT shortcut, body, media_r2_key FROM quick_replies WHERE id = ?').bind(qr_id).first();
        if (!qr) return json({ error: 'qr not found' }, 404);
        const num = normalizeArPhone(phone);
        if (!num) return json({ error: 'numero invalido' }, 400);
        // Sin imagen: texto plano por waSendText.
        if (!qr.media_r2_key) {
          const r = await waSendText(env, phone, qr.body);
          if (!r.ok) return json({ error: r.error || 'send failed' }, r.status || 500);
          try {
            await env.DB.prepare(
              'INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
            ).bind(new Date().toISOString(), r.id || '', 'outbound', num, '', 'text', qr.body, '', '', 'sent').run();
          } catch (_) {}
          ctx.waitUntil(registrarAutorEnvio(env, r.id, session.user, num));   // autor real (avisos internos), después del INSERT
          return json({ ok: true, type: 'text', id: r.id });
        }
        // Con imagen: descargar de R2 → upload a Meta → send con caption.
        const obj = await env.MEDIA.get(qr.media_r2_key);
        if (!obj) return json({ error: 'media missing in R2' }, 500);
        const buf = await obj.arrayBuffer();
        const mime = obj.httpMetadata?.contentType || 'image/jpeg';
        const ext = qr.media_r2_key.split('.').pop() || 'jpg';
        const _waQr = getWaClient(env);
        const fd = new FormData();
        fd.append('messaging_product', 'whatsapp');
        fd.append('file', new Blob([buf], { type: mime }), 'qr.' + ext);
        fd.append('type', mime);
        const upR = await fetch(_waQr.mediaUploadUrl(), {
          method: 'POST',
          headers: _waQr.headers,
          body: fd
        });
        const upJ = await upR.json().catch(() => ({}));
        if (!upR.ok || !upJ.id) return json({ error: 'media upload failed', detail: upJ?.error?.message || '' }, 500);
        const r = await waSend(env, {
          messaging_product: 'whatsapp', to: num, type: 'image',
          image: { id: upJ.id, caption: qr.body || undefined }
        });
        if (!r.ok) return json({ error: r.error }, r.status || 500);
        try {
          await env.DB.prepare(
            'INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
          ).bind(new Date().toISOString(), r.id || '', 'outbound', num, '', 'image', qr.body || '[imagen]', qr.media_r2_key, '', 'sent').run();
        } catch (_) {}
        ctx.waitUntil(registrarAutorEnvio(env, r.id, session.user, num));   // autor real (avisos internos), después del INSERT
        return json({ ok: true, type: 'image', id: r.id });
      }

      // ===== Labels CRUD =====
      if (request.method === 'GET' && path === '/admin/labels') {
        try {
          await env.DB.prepare('CREATE TABLE IF NOT EXISTS labels (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, color TEXT NOT NULL, created_at TEXT NOT NULL)').run();
          await env.DB.prepare('CREATE TABLE IF NOT EXISTS contact_labels (phone TEXT NOT NULL, label_id INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (phone, label_id))').run();
          const rs = await env.DB.prepare('SELECT id, name, color FROM labels ORDER BY name').all();
          return json({ labels: rs.results || [] });
        } catch (e) { return json({ labels: [] }); }
      }
      if (request.method === 'POST' && path === '/admin/labels') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const name = String((body || {}).name || '').trim();
        const color = String((body || {}).color || '').trim();
        if (!name || !color) return json({ error: 'Falta el nombre o el color de la etiqueta' }, 400);
        await env.DB.prepare('CREATE TABLE IF NOT EXISTS labels (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, color TEXT NOT NULL, created_at TEXT NOT NULL)').run();
        // ON CONFLICT DO UPDATE (no OR REPLACE): no cambia el id de una etiqueta existente.
        // OR REPLACE borraba+reinsertaba -> id nuevo -> dejaba huerfanas las contact_labels.
        await env.DB.prepare('INSERT INTO labels (name, color, created_at) VALUES (?, ?, ?) ON CONFLICT(name) DO UPDATE SET color = excluded.color').bind(name, color, new Date().toISOString()).run();
        const row = await env.DB.prepare('SELECT id, name, color FROM labels WHERE name = ?').bind(name).first();
        return json({ ok: true, id: row && row.id, label: row });
      }
      if (request.method === 'DELETE' && path.startsWith('/admin/labels/')) {
        const id = path.split('/').pop();
        await env.DB.prepare('DELETE FROM contact_labels WHERE label_id = ?').bind(id).run();
        await env.DB.prepare('DELETE FROM labels WHERE id = ?').bind(id).run();
        return json({ ok: true });
      }

      // ===== Contact Labels =====
      if (request.method === 'GET' && path === '/admin/contact-labels') {
        try {
          // ?v=<versión que ya tiene el front>: si la tabla no cambió desde entonces (versión que
          // suben los triggers trg_ver_contact_labels_*), respondemos {unchanged:true} sin re-leer
          // las ~9k filas. La versión se lee ANTES que los datos: si entra una escritura en el medio,
          // el front recibe datos más nuevos que la versión y simplemente re-pide en el próximo poll.
          const ver = await kvGet(env, 'ver:contact_labels', null);
          if (ver && url.searchParams.get('v') === ver) return json({ unchanged: true, ver });
          await env.DB.prepare('CREATE TABLE IF NOT EXISTS contact_labels (phone TEXT NOT NULL, label_id INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (phone, label_id))').run();
          const rs = await env.DB.prepare('SELECT phone, label_id FROM contact_labels').all();
          // Group by phone
          const map = {};
          for (const r of (rs.results || [])) {
            if (!map[r.phone]) map[r.phone] = [];
            map[r.phone].push(r.label_id);
          }
          return json({ contactLabels: map, ver });
        } catch (e) { return json({ contactLabels: {} }); }
      }
      if (request.method === 'POST' && path === '/admin/contact-labels') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { phone, label_id } = body || {};
        if (!phone || !label_id) return json({ error: 'missing phone or label_id' }, 400);
        await env.DB.prepare('CREATE TABLE IF NOT EXISTS contact_labels (phone TEXT NOT NULL, label_id INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (phone, label_id))').run();
        await env.DB.prepare('INSERT OR IGNORE INTO contact_labels (phone, label_id, created_at) VALUES (?, ?, ?)').bind(phone, label_id, new Date().toISOString()).run();
        // Drip Pack Emprendedor: si la etiqueta es Alumno (26), encolar la promo a 14 días.
        if (Number(label_id) === 26) { try { await enqueueComunidadPromo(env, phone); } catch (_) {} }
        // Si la reponen a mano, dejar de suprimirla (limpia el override).
        try { await env.DB.prepare('DELETE FROM label_overrides WHERE phone = ? AND label_id = ?').bind(phone, label_id).run(); } catch (_) {}
        return json({ ok: true });
      }
      if (request.method === 'DELETE' && path === '/admin/contact-labels') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { phone, label_id } = body || {};
        if (!phone || !label_id) return json({ error: 'missing phone or label_id' }, 400);
        await env.DB.prepare('DELETE FROM contact_labels WHERE phone = ? AND label_id = ?').bind(phone, label_id).run();
        // Quitada A MANO → registrar el override para que los reconciliadores no la repongan.
        try {
          await env.DB.prepare('CREATE TABLE IF NOT EXISTS label_overrides (phone TEXT NOT NULL, label_id INTEGER NOT NULL, removed_at TEXT NOT NULL, PRIMARY KEY (phone, label_id))').run();
          await env.DB.prepare('INSERT OR REPLACE INTO label_overrides (phone, label_id, removed_at) VALUES (?, ?, ?)').bind(phone, label_id, new Date().toISOString()).run();
        } catch (_) {}
        return json({ ok: true });
      }

      // ===== Notas por contacto =====
      if (request.method === 'GET' && path === '/admin/contact-notes') {
        try {
          await env.DB.prepare("CREATE TABLE IF NOT EXISTS contact_notes (phone TEXT PRIMARY KEY, note TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL)").run();
          const phone = url.searchParams.get('phone') || '';
          if (phone) {
            const row = await env.DB.prepare('SELECT phone, note, updated_at FROM contact_notes WHERE phone = ?').bind(phone).first();
            return json({ note: row || null });
          }
          // Sin filtro: devolver todas las que tienen contenido (para preload masivo)
          const rs = await env.DB.prepare("SELECT phone, note, updated_at FROM contact_notes WHERE note != ''").all();
          return json({ notes: rs.results || [] });
        } catch (e) { return json({ error: e.message }, 500); }
      }
      if (request.method === 'PUT' && path === '/admin/contact-notes') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { phone, note } = body || {};
        if (!phone) return json({ error: 'missing phone' }, 400);
        await env.DB.prepare("CREATE TABLE IF NOT EXISTS contact_notes (phone TEXT PRIMARY KEY, note TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL)").run();
        const now = new Date().toISOString();
        await env.DB.prepare(
          'INSERT INTO contact_notes (phone, note, updated_at) VALUES (?, ?, ?) ON CONFLICT(phone) DO UPDATE SET note = excluded.note, updated_at = excluded.updated_at'
        ).bind(phone, String(note || ''), now).run();
        return json({ ok: true, updated_at: now });
      }
      if (request.method === 'DELETE' && path === '/admin/contact-notes') {
        const phone = url.searchParams.get('phone') || '';
        if (!phone) return json({ error: 'missing phone' }, 400);
        await env.DB.prepare('DELETE FROM contact_notes WHERE phone = ?').bind(phone).run();
        return json({ ok: true });
      }

      // ===== Marcar conversación como NO leída =====
      // Marca el chat como NO leído para TODO el equipo (estado compartido, sincronizado en todos los
      // dispositivos — pedido Gaspar 4-sep). Antes solo borraba el read_cursor, pero la lista de chats
      // se muestra desde la COLUMNA wa_chats_summary.unread (que el trigger sube y mark-read pone en 0),
      // así que otros usuarios seguían viéndolo como leído. Ahora también sube esa columna a >=1.
      if (request.method === 'POST' && path === '/admin/wa/mark-unread') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { phone } = body || {};
        if (!phone) return json({ error: 'missing phone' }, 400);
        // Invalidar la cache del chats-summary para que el resto del equipo lo vea YA (no en 4s).
        ctx.waitUntil(invalidateChatsSummaryCache(request));
        try { await env.DB.prepare('DELETE FROM wa_read_cursor WHERE phone = ?').bind(phone).run(); } catch (_) {}
        try { await env.DB.prepare('UPDATE wa_chats_summary SET unread = MAX(unread, 1) WHERE phone = ?').bind(phone).run(); } catch (_) {}
        return json({ ok: true });
      }

      // ===== Backfill de auto-labels =====
      // Procesa todos los inbound del rango y aplica las reglas de auto-labeling.
      // Útil cuando se modifican las keywords o para inicializar después de
      // cargar las labels nuevas. Idempotente.
      if (request.method === 'POST' && path === '/admin/wa/auto-label-backfill') {
        let body; try { body = await request.json(); } catch { body = {}; }
        const days = Math.max(1, Math.min(365, parseInt(body?.days || '90')));
        const since = new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString();
        try {
          const rs = await env.DB.prepare(
            "SELECT phone, body FROM wa_messages WHERE direction = 'inbound' AND body IS NOT NULL AND body != '' AND ts >= ? LIMIT 5000"
          ).bind(since).all();
          const rows = rs.results || [];
          let processed = 0;
          for (const r of rows) {
            await applyAutoLabels(env, r.phone, r.body);
            processed++;
          }
          return json({ ok: true, processed, since });
        } catch (e) { return json({ error: e.message }, 500); }
      }

      // ===== Archivar / desarchivar chats =====
      if (request.method === 'GET' && path === '/admin/wa/archived') {
        try {
          await env.DB.prepare('CREATE TABLE IF NOT EXISTS archived_chats (phone TEXT PRIMARY KEY, archived_at TEXT NOT NULL)').run();
          const rs = await env.DB.prepare('SELECT phone, archived_at FROM archived_chats').all();
          return json({ phones: (rs.results || []).map(r => r.phone) });
        } catch (e) { return json({ error: e.message }, 500); }
      }
      if (request.method === 'POST' && path === '/admin/wa/archive') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { phone } = body || {};
        if (!phone) return json({ error: 'missing phone' }, 400);
        await env.DB.prepare('CREATE TABLE IF NOT EXISTS archived_chats (phone TEXT PRIMARY KEY, archived_at TEXT NOT NULL)').run();
        await env.DB.prepare('INSERT OR REPLACE INTO archived_chats (phone, archived_at) VALUES (?, ?)').bind(phone, new Date().toISOString()).run();
        return json({ ok: true });
      }
      if (request.method === 'DELETE' && path === '/admin/wa/archive') {
        const phone = url.searchParams.get('phone') || '';
        if (!phone) return json({ error: 'missing phone' }, 400);
        await env.DB.prepare('DELETE FROM archived_chats WHERE phone = ?').bind(phone).run();
        return json({ ok: true });
      }

      // ===== Bulk messaging =====
      if (request.method === 'POST' && path === '/admin/wa/send-bulk') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { label_ids, message, template_name, template_lang } = body || {};
        if ((!label_ids || !label_ids.length) && !body.phones) return json({ error: 'missing label_ids or phones' }, 400);
        if (!message && !template_name) return json({ error: 'missing message or template_name' }, 400);
        // phones acepta dos formatos:
        //   1) ["54911...", "54922..."]  (sin params, mismo mensaje a todos)
        //   2) [{phone: "54911...", params: ["Juan"]}, ...]  (params por destinatario para template)
        let recipients = [];
        if (label_ids && label_ids.length) {
          const placeholders = label_ids.map(() => '?').join(',');
          const rs = await env.DB.prepare(`SELECT DISTINCT phone FROM contact_labels WHERE label_id IN (${placeholders})`).bind(...label_ids).all();
          recipients = (rs.results || []).map(r => ({ phone: r.phone, params: [] }));
        } else if (Array.isArray(body.phones)) {
          recipients = body.phones.map(p => typeof p === 'string' ? { phone: p, params: [] } : { phone: p.phone, params: p.params || [] });
        }
        if (!recipients.length) return json({ error: 'no contacts' }, 400);
        const results = { sent: 0, failed: 0, errors: [] };
        for (const it of recipients) {
          const ph = it.phone;
          try {
            let r;
            if (template_name) {
              r = await waSendTemplate(env, ph, template_name, template_lang || 'es', it.params || []);
            } else {
              r = await waSendText(env, ph, message);
            }
            if (r.ok) {
              results.sent++;
              try {
                await env.DB.prepare(
                  'INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
                ).bind(new Date().toISOString(), r.id || '', 'outbound', ph, '', 'text', message || `[template:${template_name}]`, '', '', 'sent').run();
              } catch (_) {}
            } else {
              results.failed++;
              results.errors.push({ phone: ph, error: r.error });
            }
            await logWaEvent(env, { to: ph, kind: 'bulk', ref: '', ok: r.ok, messageId: r.id, error: r.error });
          } catch (e) {
            results.failed++;
            results.errors.push({ phone: ph, error: e.message });
          }
        }
        return json(results);
      }

      // ===== Templates: crear y listar =====
      if (request.method === 'POST' && path === '/admin/wa/template-create') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { name, category, language, body_text, example_params } = body || {};
        if (!name || !category || !language || !body_text) return json({ error: 'missing fields' }, 400);
        const _waT = getWaClient(env);
        if (_waT.provider === 'meta' && (!env.WA_BUSINESS_ACCOUNT_ID || !env.WA_TOKEN)) return json({ error: 'WA not configured (meta)' }, 500);
        const components = [{ type: 'BODY', text: body_text }];
        if (Array.isArray(example_params) && example_params.length) {
          components[0].example = { body_text: [example_params] };
        }
        // Header de imagen opcional (media template): el example lleva una URL pública de
        // muestra (Meta la usa solo para aprobar; el header real se pasa al enviar). Va
        // PRIMERO en components (Meta exige HEADER antes que BODY).
        if (body.header_image_url && /^https?:\/\//i.test(String(body.header_image_url))) {
          components.unshift({ type: 'HEADER', format: 'IMAGE', example: { header_handle: [String(body.header_image_url)] } });
        }
        // Botón URL opcional (ej. "Ver portal"). URL estática (sin variable) → no
        // requiere params al enviar; el botón se manda solo con la plantilla.
        if (body.button_url && /^https?:\/\//i.test(String(body.button_url))) {
          components.push({ type: 'BUTTONS', buttons: [{ type: 'URL', text: String(body.button_text || 'Ver más').slice(0, 25), url: String(body.button_url) }] });
        }
        const r = await fetch(_waT.templatesUrl(), {
          method: 'POST',
          headers: { ..._waT.headers, 'Content-Type': 'application/json' },
          body: JSON.stringify({ name, category, language, components, ...(body.allow_category_change === true ? { allow_category_change: true } : {}) })
        });
        const data = await r.json().catch(() => ({}));
        if (!r.ok) return json({ error: data?.error?.message || 'create failed', raw: data }, r.status || 500);
        return json({ ok: true, id: data.id, status: data.status, category: data.category, provider: _waT.provider });
      }

      // Estado de aprobacion de plantillas (para pollear si Meta aprobo una recien creada).
      if (request.method === 'GET' && path === '/admin/wa/template-status') {
        const _waT = getWaClient(env);
        const sep = _waT.templatesUrl().includes('?') ? '&' : '?';
        const rr = await fetch(`${_waT.templatesUrl()}${sep}limit=500&fields=name,status`, { headers: _waT.headers });
        const dd = await rr.json().catch(() => ({}));
        const arr = (dd.data || dd.waba_templates || []);
        const nm = url.searchParams.get('name');
        if (nm) { const t = arr.find(x => x.name === nm); return json({ name: nm, status: t ? String(t.status).toLowerCase() : 'not_found' }); }
        return json({ templates: arr.map(x => ({ name: x.name, status: String(x.status || '').toLowerCase() })) });
      }

      // Limpieza de plantillas ad-hoc viejas (baja el nº total -> menos riesgo de ban de Meta).
      // POST {dry_run:true} para SOLO contar; {dry_run:false, days:N} para borrar. Solo admin.
      if (request.method === 'POST' && path === '/admin/wa/adhoc-cleanup') {
        const _role = await getSessionRole(env, session.user);
        if (_role !== 'admin') return json({ error: 'forbidden' }, 403);
        let _b = {}; try { _b = await request.json(); } catch (_) {}
        const res = await adhocCleanup(env, { days: _b.days, dryRun: !!_b.dry_run, max: _b.max });
        return json(res);
      }

      // ===== Crear plantilla "al toque" + mandarla sola cuando Meta la apruebe =====
      // Para vendedores (Joaco/Abril): crean una plantilla a medida para ESTE chat
      // sin esperar la aprobación en pantalla. Guardrails de contenido + tope diario
      // + nombre auto (categoría siempre MARKETING). El cron processPendingTemplateSends
      // la manda apenas Meta la aprueba.
      if (request.method === 'POST' && path === '/admin/wa/template-create-send') {
        const role = await getSessionRole(env, session.user);
        if (!['admin', 'comercial', 'cursos'].includes(role)) return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const num = normalizeArPhone(String(body?.to || ''));
        if (!num) return json({ error: 'teléfono inválido' }, 400);
        if (!(await inboxAccessOk(env, role, num, session.user))) return json({ error: 'forbidden: chat fuera de tu bandeja' }, 403);
        const text = String(body?.body_text || '').trim();
        const vErr = validateAdhocTemplate(text);
        if (vErr) return json({ error: vErr }, 400);
        // Pin privado (pedido Bruno 3-sep): si el mensaje lleva su firma, el chat ADEMÁS aparece en la
        // bandeja privada (sin salir de su bandeja). Acá cubre reuso Y creación nueva (ambos tienen text).
        // Solo si la sesión es admin (Bruno/Gaspar comparten el user admin) → evita que Joaco/Abril
        // pinneen de más al nombrar a Bruno.
        if (isAdminSession && /\bbruno\b/i.test(text)) { try { await pinPrivadoBruno(env, num); } catch (_) {} }
        // "El que trabaja el lead se queda con él" (Gaspar 4-sep): si el que compone es un vendedor
        // comercial, el chat se le asigna a él (cubre reuso Y creación de la adhoc).
        try { await reasignarAlQueTrabaja(env, num, session.user); } catch (_) {}
        const hasButton = !!(body.button_url && /^https?:\/\//i.test(String(body.button_url)));
        const bodyNorm = adhocBodyNorm(text) + (hasButton ? 'btn:' + String(body.button_url) : '');
        await ensureAdhocSchema(env);
        // 1) REUSO: si ya existe una plantilla adhoc APROBADA (status 'sent') con este
        //    mismo texto, la reusamos y la mandamos ya — NO creamos una nueva. Así las
        //    plantillas dejan de multiplicarse (lo que gatilló la restricción jul-2026).
        try {
          const hit = await env.DB.prepare(
            "SELECT template_name, body_preview FROM wa_pending_template_send WHERE body_norm = ? AND status = 'sent' ORDER BY updated_at DESC LIMIT 1"
          ).bind(bodyNorm).first();
          if (hit && hit.template_name) {
            // Remitente calculado ANTES de mandar: así el registro sale pegado al envío y casi nunca
            // pierde la carrera con el webhook de estado de Meta.
            const senderSlug = adhocSenderSlug(session.user);
            const rs = await waSendTemplate(env, num, hit.template_name, 'es_AR', []);
            if (rs.ok) {
              // Registrar el envío en el chat (caso Agus→Pau 7-oct): antes el reuso salía y se cobraba
              // pero no dejaba fila → el vendedor no lo veía, solo quedaba la fila 'status' vacía que crea
              // el webhook de Meta.
              const shown = (hit.body_preview && hit.body_preview.length < 300) ? hit.body_preview : text;
              await registrarPlantillaAdhocEnChat(env, { phone: num, wamid: rs.id, texto: shown, senderSlug });
              await logWaEvent(env, { to: num, kind: 'template:' + hit.template_name, ref: '', ok: true, messageId: rs.id });
              return json({ ok: true, template_name: hit.template_name, status: 'sent', reused: true });
            }
            await logWaEvent(env, { to: num, kind: 'template:' + hit.template_name, ref: '', ok: false, messageId: rs.id, error: rs.error });
            // Solo tiene sentido crear una plantilla nueva si ESTA ya no existe o está pausada en Meta
            // (y se marca para no volver a elegirla). Cualquier otro fallo (bloqueo por pago, kill-switch,
            // red, límite) se devuelve al vendedor SIN crear nada: antes creaba una MARKETING nueva idéntica
            // en cada intento, justo lo que infla la cuenta (restricción jul-2026).
            const tplGone = [132001, 132015, 132016].includes(Number(rs.code)) || /template/i.test(String(rs.error || ''));
            if (!tplGone) return json({ error: 'No se pudo mandar la plantilla: ' + describeSendFailure(rs) }, 502);
            try { await env.DB.prepare("UPDATE wa_pending_template_send SET status = 'gone', updated_at = ? WHERE template_name = ?").bind(new Date().toISOString(), hit.template_name).run(); } catch (_) {}
          }
        } catch (_) {}
        // 2) Freno de creación: kv 'adhoc_send_enabled' = '0' → no se crean plantillas
        //    nuevas (solo reuso). Backstop para no volver a inflar la cuenta si Meta aprieta.
        if ((await kvGet(env, 'adhoc_send_enabled', '1')) === '0') {
          return json({ error: 'La creación de plantillas nuevas está pausada. Podés reusar una ya aprobada o esperar a que el cliente responda (ventana de 24h).' }, 409);
        }
        // Tope diario de plantillas NUEVAS por usuario (los reusos NO cuentan).
        const dayStart = new Date(); dayStart.setUTCHours(0, 0, 0, 0);
        try {
          const c = await env.DB.prepare("SELECT COUNT(*) AS n FROM wa_pending_template_send WHERE created_by = ? AND created_at >= ?").bind(session.user, dayStart.toISOString()).first();
          const _adhocCap = parseInt(await kvGet(env, 'adhoc_template_daily_cap', '30'), 10) || 30;
          if (c && c.n >= _adhocCap) return json({ error: 'Llegaste al máximo de ' + _adhocCap + ' plantillas nuevas por día.' }, 429);
        } catch (_) {}
        const tplName = 'adhoc_' + Date.now();
        const _waT = getWaClient(env);
        const _components = [{ type: 'BODY', text }];
        if (hasButton) {
          _components.push({ type: 'BUTTONS', buttons: [{ type: 'URL', text: String(body.button_text || 'Ver más').slice(0, 25), url: String(body.button_url) }] });
        }
        // Categoría MARKETING directa: en la práctica Meta recategoriza estos follow-ups de
        // venta a MARKETING casi siempre (son promocionales), así que se crean ya en MARKETING
        // para evitar la corrección/discrepancia. allow_category_change=true: si alguna es
        // genuinamente utility, Meta la reclasifica sin rechazarla. El VOLUMEN (la causa real
        // del baneo jul-2026) lo controla el REUSO de arriba, NO la categoría.
        const r = await fetch(_waT.templatesUrl(), {
          method: 'POST', headers: { ..._waT.headers, 'Content-Type': 'application/json' },
          body: JSON.stringify({ name: tplName, category: 'MARKETING', allow_category_change: true, language: 'es_AR', components: _components })
        });
        const data = await r.json().catch(() => ({}));
        if (!r.ok) return json({ error: data?.error?.message || 'Meta rechazó la creación de la plantilla', raw: data }, r.status || 500);
        try {
          await env.DB.prepare(
            "INSERT OR REPLACE INTO wa_pending_template_send (template_name, phone, body_preview, body_norm, created_by, created_at, status, updated_at) VALUES (?, ?, ?, ?, ?, ?, 'pending', ?)"
          ).bind(tplName, num, text.slice(0, 300), bodyNorm, session.user, new Date().toISOString(), new Date().toISOString()).run();
        } catch (_) {}
        return json({ ok: true, template_name: tplName, status: data.status || 'pending' });
      }
      // ===== Promo assets (imágenes para campañas como follow-up de copa) =====
      // POST /admin/wa/promo-asset/upload?key=copa-mundial-junio
      //   Body: imagen binaria (image/jpeg, image/png, image/webp).
      //   Header opcional: Content-Type (default image/jpeg).
      // Guarda en R2 con key 'promo/<key>.<ext>'. Invalida el cache de media_id
      // (próxima vez que el cron lo necesite, re-uploadea a Meta).
      //
      // GET /admin/wa/promo-asset?key=...  → devuelve metadata + URL del worker
      //   para previsualizar (admin-only via /admin/media path).
      if (request.method === 'POST' && path === '/admin/wa/promo-asset/upload') {
        const role = await getSessionRole(env, session.user);
        if (role !== 'admin') return json({ error: 'forbidden' }, 403);
        const key = (url.searchParams.get('key') || '').trim();
        if (!key || !/^[a-z0-9-]+$/i.test(key)) return json({ error: 'key inválido (solo a-z 0-9 -)' }, 400);
        if (!env.MEDIA) return json({ error: 'R2 no configurado' }, 500);
        const ct = request.headers.get('content-type') || 'image/jpeg';
        const cleanMime = String(ct).split(';')[0].trim();
        const ext = cleanMime.includes('png') ? '.png'
                  : cleanMime.includes('webp') ? '.webp'
                  : '.jpg';
        const r2Key = `promo/${key}${ext}`;
        let buf;
        try { buf = await request.arrayBuffer(); } catch (e) { return json({ error: 'no pude leer el body: ' + e.message }, 400); }
        if (!buf || buf.byteLength < 100) return json({ error: 'imagen vacía o demasiado chica' }, 400);
        if (buf.byteLength > 5 * 1024 * 1024) return json({ error: 'imagen >5MB (Meta no acepta)' }, 400);
        try {
          await env.MEDIA.put(r2Key, buf, { httpMetadata: { contentType: cleanMime } });
        } catch (e) { return json({ error: 'r2 put failed: ' + e.message }, 500); }
        // Invalidar cache del media_id para esta key (próxima invocación
        // re-uploadea a Meta con la imagen nueva).
        try { await env.DB.prepare('DELETE FROM kv_cache WHERE k = ?').bind('promo_media:' + r2Key).run(); } catch (_) {}
        return json({ ok: true, key, r2_key: r2Key, size: buf.byteLength, mime: cleanMime });
      }

      // ===== Unreachable phones — listar / agregar / borrar =====
      // GET  /admin/wa/unreachable          → { phones: [...] }
      // POST /admin/wa/unreachable          { phone, reason? } → marcar manual
      // DELETE /admin/wa/unreachable?phone= → desmarcar manual
      if (request.method === 'GET' && path === '/admin/wa/unreachable') {
        try {
          const limit = Math.min(parseInt(url.searchParams.get('limit') || '500', 10) || 500, 2000);
          const rs = await env.DB.prepare(
            'SELECT phone, marked_at, reason, last_error, last_template, fail_count, updated_at FROM wa_unreachable_phones ORDER BY updated_at DESC LIMIT ?'
          ).bind(limit).all();
          return json({ phones: rs.results || [] });
        } catch (e) { return json({ error: e.message }, 500); }
      }
      if (request.method === 'POST' && path === '/admin/wa/unreachable') {
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { phone, reason } = body || {};
        if (!phone) return json({ error: 'missing phone' }, 400);
        await markUnreachable(env, phone, reason || 'manual', '(marcado manual)', '');
        return json({ ok: true, phone: normalizeArPhone(phone) });
      }
      if (request.method === 'DELETE' && path === '/admin/wa/unreachable') {
        const phone = url.searchParams.get('phone');
        if (!phone) return json({ error: 'missing phone' }, 400);
        await removeUnreachable(env, phone);
        return json({ ok: true, phone: normalizeArPhone(phone) });
      }
      // DELETE template — útil para recrear cuando se carga mal (encoding, typos).
      // Meta y 360dialog NO permiten editar un template aprobado, hay que borrar y recrear.
      // En Meta: DELETE /{waba_id}/message_templates?name=...
      // En 360dialog: DELETE /v1/configs/templates/{templatename}
      if (request.method === 'DELETE' && path === '/admin/wa/template-delete') {
        const name = url.searchParams.get('name');
        if (!name) return json({ error: 'missing name' }, 400);
        const _waD = getWaClient(env);
        if (_waD.provider === 'meta' && (!env.WA_BUSINESS_ACCOUNT_ID || !env.WA_TOKEN)) return json({ error: 'WA not configured (meta)' }, 500);
        const delUrl = _waD.provider === '360dialog'
          ? `${_waD.templatesUrl()}/${encodeURIComponent(name)}`
          : `${_waD.templatesUrl()}?name=${encodeURIComponent(name)}`;
        const r = await fetch(delUrl, { method: 'DELETE', headers: _waD.headers });
        const data = await r.json().catch(() => ({}));
        if (!r.ok) return json({ error: data?.error?.message || 'delete failed', raw: data }, r.status || 500);
        return json({ ok: true, deleted: name, provider: _waD.provider });
      }
      // set-pin y register son operaciones del flujo ON_PREMISE de Meta direct,
      // ya no aplican con 360dialog Cloud API hosted (lo gestiona el provider).
      // Si alguien las llama post-migración, devolvemos 501 con guía.
      // One-off: reenvía a un número TODAS las imágenes/PDF inbound desde un
      // timestamp. Usado en el lanzamiento junio para que Gaspar reciba en su
      // WhatsApp personal todos los comprobantes que entraron. Gaspar-only.
      // Robusto: timeout por item (un upload colgado NO cuelga toda la request),
      // budget total (corta y devuelve last_id para continuar) e idempotencia
      // (marca cada envío en kv_cache para que reintentos no dupliquen).
      // Paginado por id estable. Body: { since, to, limit?, after_id?, delay_ms? }.
      if (request.method === 'POST' && path === '/admin/wa/resend-media') {
        if (!session || session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const since = String(body?.since || '').trim();
        const to = String(body?.to || '').trim();
        const afterId = parseInt(body?.after_id || '0', 10) || 0;
        const limit = Math.min(Math.max(parseInt(body?.limit || '8', 10) || 8, 1), 50);
        const delayMs = Math.min(Math.max(parseInt(body?.delay_ms || '250', 10) || 250, 0), 3000);
        const itemTimeoutMs = Math.min(Math.max(parseInt(body?.item_timeout_ms || '15000', 10) || 15000, 3000), 45000);
        const maxReqMs = Math.min(Math.max(parseInt(body?.max_req_ms || '45000', 10) || 45000, 5000), 110000);
        if (!since || !to) return json({ error: 'missing since or to' }, 400);
        const num = normalizeArPhone(to);
        if (!num) return json({ error: 'numero destino invalido' }, 400);
        let rows;
        try {
          const rs = await env.DB.prepare(
            "SELECT m.id, m.wamid, m.phone, m.sender_name, m.msg_type, m.media_url, m.ts, " +
            "       p.monto AS p_monto, p.cuenta AS p_cuenta, p.clasificacion AS p_clase " +
            "FROM wa_messages m " +
            "LEFT JOIN wa_pago_proof p ON p.wamid = m.wamid " +
            "WHERE m.direction='inbound' AND m.msg_type IN ('image','document') " +
            "  AND m.ts >= ? AND m.id > ? AND m.media_url IS NOT NULL AND m.media_url != '' " +
            "ORDER BY m.id ASC LIMIT ?"
          ).bind(since, afterId, limit).all();
          rows = rs.results || [];
        } catch (e) { return json({ error: 'query failed: ' + e.message }, 500); }

        const fmtMonto = (n) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
        const cuentaLabel = (c) => c === 'mp_gaspar' ? 'MP Gaspar' : c === 'bna_bruno' ? 'BNA Bruno' : (c === 'otra' ? 'otra cuenta' : (c || 'cuenta?'));
        const withTimeout = (p, ms, label) => Promise.race([
          Promise.resolve(p),
          new Promise((_, rej) => setTimeout(() => rej(new Error('timeout ' + label)), ms))
        ]);
        const startMs = Date.now();
        let sent = 0, failed = 0, skipped = 0, lastId = afterId, truncated = false; const errors = [];
        for (const r of rows) {
          if (Date.now() - startMs > maxReqMs) { truncated = true; break; }
          lastId = r.id;
          const ckey = 'resent:' + num + ':' + r.wamid;
          // idempotencia: si ya lo reenviamos a este número, saltar
          try {
            const seen = await env.DB.prepare("SELECT 1 AS x FROM kv_cache WHERE k = ?").bind(ckey).first();
            if (seen) { skipped++; continue; }
          } catch (_) {}
          try {
            const obj = await withTimeout(env.MEDIA.get(r.media_url), itemTimeoutMs, 'r2');
            if (!obj) { failed++; errors.push({ id: r.id, phone: r.phone, error: 'no en R2' }); continue; }
            const buf = await withTimeout(obj.arrayBuffer(), itemTimeoutMs, 'r2-read');
            const mime = obj.httpMetadata?.contentType || (r.msg_type === 'image' ? 'image/jpeg' : 'application/pdf');
            const baseName = (r.media_url.split('/').pop() || '');
            const dotExt = baseName.includes('.') ? ('.' + baseName.split('.').pop()) : '';
            const ext = dotExt || (r.msg_type === 'image' ? '.jpg' : (mime.includes('pdf') ? '.pdf' : ''));
            const fileName = r.msg_type === 'document' ? ('comprobante_' + r.phone + ext) : (baseName || ('img' + ext));
            const mediaId = await withTimeout(uploadMediaToMeta(env, buf, mime, fileName), itemTimeoutMs, 'upload');
            if (!mediaId) { failed++; errors.push({ id: r.id, phone: r.phone, error: 'upload a Meta fallo' }); continue; }
            // ART hh:mm (UTC-3)
            const d = new Date(r.ts);
            const art = new Date(d.getTime() - 3 * 3600 * 1000);
            const hhmm = String(art.getUTCHours()).padStart(2, '0') + ':' + String(art.getUTCMinutes()).padStart(2, '0');
            const quien = (r.sender_name && r.sender_name.trim()) ? r.sender_name.trim() : r.phone;
            let cap = quien + ' · ' + r.phone + ' · ' + hhmm;
            if (r.p_monto && r.p_monto > 0) cap += '\n$' + fmtMonto(r.p_monto) + ' · ' + cuentaLabel(r.p_cuenta);
            let res;
            if (r.msg_type === 'image') res = await withTimeout(waSendImage(env, num, mediaId, cap), itemTimeoutMs, 'send');
            else res = await withTimeout(waSendDocument(env, num, mediaId, fileName, cap), itemTimeoutMs, 'send');
            if (res && res.ok) {
              sent++;
              try { await env.DB.prepare("INSERT OR REPLACE INTO kv_cache (k, v, updated_at) VALUES (?, ?, ?)").bind(ckey, '1', new Date().toISOString()).run(); } catch (_) {}
            } else { failed++; errors.push({ id: r.id, phone: r.phone, error: (res && res.error) || 'send fallo', code: res && res.code }); }
          } catch (e) { failed++; errors.push({ id: r.id, phone: r.phone, error: String(e && e.message || e) }); }
          if (delayMs) await new Promise(rr => setTimeout(rr, delayMs));
        }
        return json({ ok: true, batch: rows.length, sent, failed, skipped, last_id: lastId, truncated, done: !truncated && rows.length < limit, errors: errors.slice(0, 30) });
      }
      if (request.method === 'POST' && path === '/admin/wa/set-pin') {
        if ((env.WA_PROVIDER || 'meta') !== 'meta') {
          return json({ error: '2FA PIN se gestiona desde el dashboard de 360dialog Hub', provider: env.WA_PROVIDER }, 501);
        }
        if (!session || session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { pin } = body || {};
        if (!pin || !/^\d{6}$/.test(String(pin))) return json({ error: 'pin debe ser 6 dígitos numéricos' }, 400);
        const v = env.WA_API_VERSION || 'v25.0';
        const r = await fetch(`https://graph.facebook.com/${v}/${env.WA_PHONE_NUMBER_ID}`, {
          method: 'POST',
          headers: { 'Authorization': `Bearer ${env.WA_TOKEN}`, 'Content-Type': 'application/json' },
          body: JSON.stringify({ pin: String(pin) })
        });
        const data = await r.json().catch(() => ({}));
        if (!r.ok) return json({ error: data?.error?.message || 'set-pin failed', code: data?.error?.code, raw: data }, r.status || 500);
        return json({ ok: true, raw: data });
      }
      if (request.method === 'POST' && path === '/admin/wa/register') {
        if ((env.WA_PROVIDER || 'meta') !== 'meta') {
          return json({ error: 'register no aplica con 360dialog (Cloud API hosted)', provider: env.WA_PROVIDER }, 501);
        }
        if (!session || session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const { pin } = body || {};
        if (!pin) return json({ error: 'missing pin' }, 400);
        const v = env.WA_API_VERSION || 'v25.0';
        const r = await fetch(`https://graph.facebook.com/${v}/${env.WA_PHONE_NUMBER_ID}/register`, {
          method: 'POST',
          headers: { 'Authorization': `Bearer ${env.WA_TOKEN}`, 'Content-Type': 'application/json' },
          body: JSON.stringify({ messaging_product: 'whatsapp', pin: String(pin) })
        });
        const data = await r.json().catch(() => ({}));
        if (!r.ok) return json({ error: data?.error?.message || 'register failed', code: data?.error?.code, raw: data }, r.status || 500);
        return json({ ok: true, raw: data });
      }
      // Datos crudos del phone number — ramifica por provider.
      // Meta: GET /{phone_id}?fields=...
      // 360dialog: GET /v1/configs/whatsapp_business_account (devuelve TODO).
      if (request.method === 'GET' && path === '/admin/wa/phone-info') {
        if (!session || session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        const _waP = getWaClient(env);
        if (_waP.provider === '360dialog') {
          const r = await fetch(`${_waP.base}/v1/configs/whatsapp_business_account`, { headers: _waP.headers });
          const data = await r.json().catch(() => ({}));
          if (!r.ok) return json({ error: data?.error || 'failed', raw: data }, r.status || 500);
          return json({ provider: '360dialog', ...data });
        }
        if (!env.WA_PHONE_NUMBER_ID || !env.WA_TOKEN) return json({ error: 'WA not configured (meta)' }, 500);
        const v = env.WA_API_VERSION || 'v25.0';
        const r = await fetch(`https://graph.facebook.com/${v}/${env.WA_PHONE_NUMBER_ID}?fields=verified_name,code_verification_status,display_phone_number,quality_rating,platform_type,certificate,messaging_limit_tier,health_status`, {
          headers: { 'Authorization': `Bearer ${env.WA_TOKEN}` }
        });
        const data = await r.json().catch(() => ({}));
        if (!r.ok) return json({ error: data?.error?.message || 'failed', raw: data }, r.status || 500);
        return json({ provider: 'meta', ...data });
      }
      // Health status del número (quality + tier + can_send_message).
      if (request.method === 'GET' && path === '/admin/wa/phone-status') {
        if (!session || session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        const _waS = getWaClient(env);
        if (_waS.provider === '360dialog') {
          const r = await fetch(`${_waS.base}/v1/health_status`, { headers: _waS.headers });
          const data = await r.json().catch(() => ({}));
          if (!r.ok) return json({ error: data?.error || 'health fetch failed', raw: data }, r.status || 500);
          return json({ provider: '360dialog', ...data });
        }
        if (!env.WA_BUSINESS_ACCOUNT_ID || !env.WA_TOKEN) return json({ error: 'WA not configured (meta)' }, 500);
        const v = env.WA_API_VERSION || 'v25.0';
        const fields = 'id,display_phone_number,quality_rating,messaging_limit_tier,verified_name,status,name_status,throughput,health_status';
        const r = await fetch(`https://graph.facebook.com/${v}/${env.WA_BUSINESS_ACCOUNT_ID}/phone_numbers?fields=${fields}`, {
          headers: { 'Authorization': `Bearer ${env.WA_TOKEN}` }
        });
        const data = await r.json().catch(() => ({}));
        if (!r.ok) return json({ error: data?.error?.message || 'fetch failed', raw: data }, r.status || 500);
        return json({ provider: 'meta', phones: data.data || [] });
      }
      if (request.method === 'GET' && path === '/admin/wa/templates') {
        const _waL = getWaClient(env);
        if (_waL.provider === 'meta' && (!env.WA_BUSINESS_ACCOUNT_ID || !env.WA_TOKEN)) return json({ error: 'WA not configured (meta)' }, 500);
        // 360dialog pagina de a 100 (ignora limit>100) → hay que recorrer las páginas
        // con offset. Con 100+ plantillas adhoc_ (de un solo uso) que llenan el listado,
        // sin paginar las plantillas reutilizables nuevas quedaban fuera del corte de 100.
        const _allTpls = [];
        try {
          for (let _off = 0; _off < 3000; _off += 100) {   // tope de seguridad: 3000 plantillas
            const _sep = _waL.templatesUrl().includes('?') ? '&' : '?';
            const _r = await fetch(`${_waL.templatesUrl()}${_sep}limit=100&offset=${_off}&fields=name,status,category,language,components`, { headers: _waL.headers });
            const _d = await _r.json().catch(() => ({}));
            if (!_r.ok) { if (_off === 0) return json({ error: _d?.error?.message || 'list failed' }, _r.status || 500); break; }
            const _batch = _d.data || _d.waba_templates || [];
            _allTpls.push(..._batch);
            if (_batch.length < 100) break;   // última página
          }
        } catch (e) { return json({ error: String((e && e.message) || e) }, 500); }
        return json({ templates: _allTpls, provider: _waL.provider });
      }

      // Servir medios desde R2
      if (request.method === 'GET' && path.startsWith('/admin/media/')) {
        const key = decodeURIComponent(path.slice('/admin/media/'.length));
        if (!env.MEDIA) return json({ error: 'R2 not configured' }, 500);
        const obj = await env.MEDIA.get(key);
        if (!obj) return json({ error: 'not found' }, 404);
        // wa/ y briefs/ son content-addressed (la key nunca cambia de contenido) →
        // cache inmutable de 1 año, así no se re-bajan las fotos en cada primera
        // apertura del día (antes era 24h y se vencía cada noche). promo/ puede
        // re-subirse con la misma key → cache corto de 24h.
        // pedidos/ (foto del diseño final): key única por subida, nunca se pisa → también inmutable.
        const immutableMedia = key.startsWith('wa/') || key.startsWith('briefs/') || key.startsWith('ig/') || key.startsWith('pedidos/') || key.startsWith('corte/landing/');
        const cacheCtl = immutableMedia ? 'public, max-age=31536000, immutable' : 'public, max-age=86400';
        const ctype = obj.httpMetadata?.contentType || 'application/octet-stream';
        // Compresión al vuelo para el panel de cotización (?w=<ancho>): las capturas y
        // fotos de referencia que sube Joaco pesan y el panel de Emma junta muchas → se
        // traba. Con ?w se redimensionan+recomprimen. Los RENDER de IA se piden SIN ?w,
        // así se sirven en calidad full. Cache con la key+query, no re-transforma.
        const w = parseInt(url.searchParams.get('w') || '0', 10);
        if (w >= 200 && w <= 2000 && env.IMAGES && /^image\/(jpe?g|png|webp)/i.test(ctype)) {
          try {
            const buf = await obj.arrayBuffer();
            if (buf.byteLength > 60000) { // no vale la pena tocar las ya livianas
              const res = await env.IMAGES.input(new Response(buf).body).transform({ width: w, fit: 'scale-down' }).output({ format: 'image/jpeg', quality: 76 });
              const outBuf = await res.response().arrayBuffer();
              return new Response(outBuf, { headers: { ...cors(), 'Content-Type': 'image/jpeg', 'Cache-Control': cacheCtl } });
            }
            return new Response(buf, { headers: { ...cors(), 'Content-Type': ctype, 'Cache-Control': cacheCtl } });
          } catch (_) {
            // el resize falló tras consumir el body → re-get para servir el original
            try { const o2 = await env.MEDIA.get(key); if (o2) return new Response(o2.body, { headers: { ...cors(), 'Content-Type': ctype, 'Cache-Control': cacheCtl } }); } catch (_) {}
            return json({ error: 'media error' }, 500);
          }
        }
        return new Response(obj.body, {
          headers: {
            ...cors(),
            'Content-Type': ctype,
            'Cache-Control': cacheCtl
          }
        });
      }

      // ===== Scheduled Messages CRUD =====
      if (request.method === 'POST' && path === '/admin/wa/schedule') {
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const items = Array.isArray(body?.messages) ? body.messages : [body];
        const created = [];
        for (const it of items) {
          const { phone, body: text, scheduled_at, template, params, lang } = it || {};
          // Acepta texto libre Y/O plantilla. La plantilla se usa al enviar si la
          // ventana de 24h está cerrada (que es lo normal al día siguiente). Al menos
          // uno de los dos es obligatorio.
          if (!phone || !scheduled_at || (!text && !template)) { created.push({ error: 'missing phone, scheduled_at, or (body|template)' }); continue; }
          const num = normalizeArPhone(phone);
          if (!num) { created.push({ error: 'numero invalido', phone }); continue; }
          const now = new Date().toISOString();
          const rs = await env.DB.prepare(
            'INSERT INTO scheduled_messages (phone, body, scheduled_at, status, created_at, template, template_params, lang) VALUES (?, ?, ?, ?, ?, ?, ?, ?)'
          ).bind(num, text || '', scheduled_at, 'pending', now, template || null, params ? JSON.stringify(params) : null, lang || 'es_AR').run();
          created.push({ id: rs.meta?.last_row_id, phone: num, scheduled_at });
        }
        return json({ created });
      }

      if (request.method === 'GET' && path === '/admin/wa/schedule') {
        const status = url.searchParams.get('status') || 'pending';
        const rs = await env.DB.prepare(
          'SELECT id, phone, body, scheduled_at, status, created_at, sent_at, error FROM scheduled_messages WHERE status = ? ORDER BY scheduled_at ASC LIMIT 200'
        ).bind(status).all();
        return json({ messages: rs.results || [] });
      }

      if (request.method === 'DELETE' && path.startsWith('/admin/wa/schedule/')) {
        const id = path.split('/').pop();
        await env.DB.prepare('UPDATE scheduled_messages SET status = ? WHERE id = ? AND status = ?').bind('cancelled', id, 'pending').run();
        return json({ ok: true });
      }

      if (request.method === 'PUT' && path === '/admin/cotizador/params') {
        // Solo Gaspar: definen precios y la mano de obra de los productores (antes solo lo frenaba el front).
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const params = body && body.params;
        if (!params || typeof params !== 'object') return json({ error: 'missing params' }, 400);
        const now = new Date().toISOString();
        const stmts = [];
        for (const [k, v] of Object.entries(params)) {
          if (typeof v !== 'number' || isNaN(v)) continue;
          stmts.push(env.DB.prepare(
            'INSERT INTO cotizador_params (key, value, updated_at) VALUES (?, ?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at'
          ).bind(k, v, now));
        }
        if (stmts.length) await env.DB.batch(stmts);
        return noContent();
      }

      // ============================================================
      // Pedidos (migración del Excel de Ventas a D1 — fuente de verdad)
      // ============================================================

      // GET /admin/pedidos → todas las filas de la tabla pedidos.
      if (request.method === 'GET' && path === '/admin/pedidos') {
        await ensurePedidosSchema(env);
        // Cada vendedor comercial ve SOLO sus pedidos (Joaco los suyos, Nadia los
        // suyos); admin (Gaspar) ve todo. comercial_id existe con DEFAULT 'joaco',
        // así que todo el histórico queda de Joaco (su número no se mueve).
        const _pedRole = await getSessionRole(env, session.user);
        let _pedWhere = '';
        const _pedArgs = [];
        if (_pedRole === 'comercial') {
          const _pedComercial = await resolveComercial(env, { sessionUser: session.user });
          _pedWhere = " WHERE IFNULL(pedidos.comercial_id,'joaco') = ?";
          _pedArgs.push(_pedComercial);
        }
        _pedWhere += ' ORDER BY pedidos.fecha DESC, pedidos.numero DESC, pedidos.id DESC';
        // + diseno_key / corte_estado / corte_id de la pieza de corte (foto del diseño final).
        // Fotos del cartel terminado para todos (el vendedor se las puede mandar al cliente); la mano de obra y el pago
        // al productor solo para Gaspar (pedidosConDiseno los saca si no es interno).
        const _pedRows = await pedidosConDiseno(env, _pedWhere, _pedArgs, { interno: _pedRole === 'admin', fotos: true });
        if (_pedRole === 'comercial') for (const _r of _pedRows) delete _r.asistido_por; // marca interna de Gaspar
        if (_pedRole === 'disenador') for (const _r of _pedRows) { delete _r.comercial_id; delete _r.cargado_por; delete _r.asistido_por; }   // Emma: sin el vendedor
        return json({ pedidos: _pedRows });
      }

      // DELETE /admin/pedidos/{id} → borra UNA fila de pedido (ej: un duplicado como
      // Dr Alvarez). Si vino del Excel (tiene sheet_row) deja un tombstone en
      // pedidos_deleted para que importNewPedidosFromVentas NO la vuelva a traer.
      // Las creadas en el CRM (sin sheet_row) se borran directo. Solo Gaspar.
      if (request.method === 'DELETE' && /^\/admin\/pedidos\/\d+$/.test(path)) {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        const pid = parseInt(path.split('/').pop(), 10);
        try {
          const prow = await env.DB.prepare('SELECT id, sheet_row FROM pedidos WHERE id = ?').bind(pid).first();
          if (!prow) return json({ error: 'pedido no encontrado' }, 404);
          if (prow.sheet_row != null) {
            try { await env.DB.prepare('CREATE TABLE IF NOT EXISTS pedidos_deleted (sheet_row INTEGER PRIMARY KEY, deleted_at TEXT)').run(); } catch (_) {}
            try { await env.DB.prepare('INSERT OR IGNORE INTO pedidos_deleted (sheet_row, deleted_at) VALUES (?, ?)').bind(Number(prow.sheet_row), new Date().toISOString()).run(); } catch (_) {}
          }
          // Pieza de corte del cartel (matriz de Emma): si todavía no se cortó, se va con el pedido. Si ya
          // está cortada/separada queda (es una pieza física), marcada para que nadie la pierda de vista.
          // Todo en UN batch (atómico): el barredor del cron no puede re-crear la pieza en el medio.
          let _corteOk = false;
          try { await ensureCorteNeonSchema(env); _corteOk = _corteNeonSchemaOk; } catch (_) {}
          const _delStmts = [env.DB.prepare('DELETE FROM pedidos WHERE id = ?').bind(pid)];
          if (_corteOk) {
            _delStmts.push(env.DB.prepare("DELETE FROM corte_pedidos WHERE pedido_id = ? AND estado IN ('pedido','matriz_lista')").bind(pid));
            _delStmts.push(env.DB.prepare("UPDATE corte_pedidos SET aclaraciones = '⚠ PEDIDO BORRADO · ' || IFNULL(aclaraciones,''), updated_at = ? WHERE pedido_id = ? AND IFNULL(aclaraciones,'') NOT LIKE '⚠ PEDIDO BORRADO%'").bind(new Date().toISOString(), pid));
          }
          await env.DB.batch(_delStmts);
          return json({ ok: true, deleted: pid });
        } catch (e) { return json({ error: String(e && e.message || e) }, 500); }
      }

      // POST /admin/pedidos/backfill → importa (idempotente) los pedidos del Excel
      // de Ventas hoja "2026" a D1. Borra solo lo previamente importado (origen=
      // 'backfill') y reinserta; preserva los creados en el CRM (origen='crm').
      if (request.method === 'POST' && path === '/admin/pedidos/backfill') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        await ensurePedidosSchema(env);
        // Re-importar borra y re-crea las filas 'backfill' con ids NUEVOS: si alguna ya tiene pieza de corte
        // (foto del diseño subida desde el drawer), esa pieza quedaría huérfana → no se permite.
        try {
          await ensureCorteNeonSchema(env);
          const _ref = await env.DB.prepare("SELECT COUNT(*) AS n FROM corte_pedidos c JOIN pedidos p ON p.id = c.pedido_id WHERE p.origen = 'backfill'").first();
          if (_ref && _ref.n > 0) return json({ error: `hay ${_ref.n} pieza(s) de corte vinculadas a pedidos del backfill; re-importar las dejaría huérfanas` }, 409);
        } catch (_) {}
        const rows = await fetchVentas2026Rows();
        if (!rows) return json({ error: 'no se pudo leer el Excel de Ventas (export de la hoja 2026)' }, 502);
        if (rows.length < 2) return json({ error: 'el Excel de Ventas vino vacío' }, 502);
        const now = new Date().toISOString();
        let skipped = 0;
        const stmts = [env.DB.prepare("DELETE FROM pedidos WHERE origen = 'backfill'")];
        for (let i = 1; i < rows.length; i++) {
          const c = rows[i];
          if (!c || !String(c[2] || '').trim()) { skipped++; continue; }  // necesita cartel
          const fecha = pedidoFecha(c[0]);
          if (!fecha) { skipped++; continue; }                            // necesita fecha válida
          stmts.push(env.DB.prepare(
            `INSERT INTO pedidos (numero, fecha, cartel, colores, alto, ancho, cm_neon, base, cantidad, precio, dimer, precio_dimmer, envio, aclaracion, productor, plataforma, estado_pago, pagado, restante, estado_pedido, ad, sheet_row, origen, created_at, updated_at)
             VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?, 'backfill', ?, ?)`
          ).bind(
            pedidoNum(c[1]), fecha, String(c[2] || '').trim(), String(c[3] || '').trim(),
            pedidoNum(c[4]), pedidoNum(c[5]), pedidoNum(c[6]), String(c[7] || '').trim(),
            pedidoNum(c[8]) || 1, pedidoNum(c[9]), String(c[10] || '').trim(), pedidoNum(c[11]),
            String(c[12] || '').trim(), String(c[13] || '').trim(), String(c[14] || '').trim(), String(c[15] || '').trim(),
            String(c[16] || '').trim(), pedidoNum(c[17]), pedidoNum(c[18]), String(c[19] || '').trim(),
            String(c[20] || '').trim(), i + 1, now, now
          ));
        }
        const inserted = stmts.length - 1;
        const CHUNK = 50;
        for (let j = 0; j < stmts.length; j += CHUNK) {
          await env.DB.batch(stmts.slice(j, j + CHUNK));
        }
        return json({ ok: true, inserted, skipped, total_rows: rows.length });
      }

      // ===== Foto del DISEÑO FINAL de un cartel (→ matriz a diseñar de Emma en el corte) =====
      // La key nueva es única por subida (pedidos/diseno/<AAAAMM>/<ts>-<rand>.<ext>), nunca se pisa: por eso
      // se puede cachear como inmutable y "cambiar foto" siempre muestra la nueva. Solo vendedores y admin.
      const _disenoKeyNueva = (ct) => {
        const ext = (String(ct || '').split('/')[1] || 'jpg').replace(/[^a-z0-9]/gi, '').slice(0, 8) || 'jpg';
        const ym = new Date(Date.now() - 3 * 3600 * 1000).toISOString().slice(0, 7).replace('-', '');
        return `pedidos/diseno/${ym}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
      };
      // PUT /admin/pedidos/diseno-foto (body = imagen cruda) → sube la foto a R2 y devuelve {key}. NO toca D1:
      // se llama ANTES de crear el pedido (todavía no hay id); la key viaja en el payload de POST /admin/pedidos.
      if (request.method === 'PUT' && path === '/admin/pedidos/diseno-foto') {
        if (!['admin', 'comercial'].includes(await getSessionRole(env, session.user))) return json({ error: 'forbidden' }, 403);
        if (!env.MEDIA) return json({ error: 'R2 not configured' }, 500);
        let ct = (request.headers.get('content-type') || '').split(';')[0].trim().toLowerCase();
        if (!ct.startsWith('image/')) ct = 'image/jpeg';
        const _cl = parseInt(request.headers.get('content-length') || '0', 10) || 0;
        if (_cl > 10 * 1024 * 1024) return json({ error: 'la foto pesa más de 10MB' }, 413); // antes de leerla a memoria
        const buf = await request.arrayBuffer().catch(() => null);
        if (!buf || buf.byteLength === 0) return json({ error: 'la foto llegó vacía' }, 400);
        if (buf.byteLength > 10 * 1024 * 1024) return json({ error: 'la foto pesa más de 10MB' }, 413);
        const key = _disenoKeyNueva(ct);
        try { await env.MEDIA.put(key, buf, { httpMetadata: { contentType: ct } }); }
        catch (e) { return json({ error: 'no se pudo guardar la foto: ' + String((e && e.message) || e) }, 500); }
        return json({ ok: true, key });
      }
      // POST /admin/pedidos/diseno-foto/copiar {from} → usa como diseño final una imagen que YA está en R2
      // (lo que se le mandó al cliente por el chat, o un render del brief). Se COPIA, no se referencia: si
      // después se borra la imagen del brief, la foto del diseño del pedido sigue existiendo.
      if (request.method === 'POST' && path === '/admin/pedidos/diseno-foto/copiar') {
        if (!['admin', 'comercial'].includes(await getSessionRole(env, session.user))) return json({ error: 'forbidden' }, 403);
        if (!env.MEDIA) return json({ error: 'R2 not configured' }, 500);
        let body; try { body = await request.json(); } catch { body = {}; }
        const from = String(body.from || '');
        if (!/^(wa|ig|briefs|precotiz)\/[\w\-./]+$/.test(from) || from.indexOf('..') >= 0) return json({ error: 'imagen de origen inválida' }, 400);
        const obj = await env.MEDIA.get(from);
        if (!obj) return json({ error: 'esa imagen ya no existe' }, 404);
        if ((obj.size || 0) > 15 * 1024 * 1024) return json({ error: 'esa imagen pesa demasiado' }, 413);
        let ct = String((obj.httpMetadata && obj.httpMetadata.contentType) || '').toLowerCase();
        if (!/^image\//.test(ct)) {
          // Un video/audio/PDF del chat NO es un diseño. Sin content-type (o genérico) se acepta: las
          // sugerencias ya vienen solo de mensajes de tipo imagen.
          if ((ct && ct !== 'application/octet-stream') || /\.(mp4|mov|3gp|webm|ogg|opus|mp3|m4a|pdf|docx?|xlsx?)$/i.test(from)) return json({ error: 'eso no es una imagen' }, 400);
          const _ext = (from.match(/\.(jpe?g|png|webp|gif)$/i) || [])[1];
          ct = _ext ? 'image/' + _ext.toLowerCase().replace('jpg', 'jpeg') : 'image/jpeg';
        }
        const key = _disenoKeyNueva(ct);
        try { await env.MEDIA.put(key, await obj.arrayBuffer(), { httpMetadata: { contentType: ct } }); }
        catch (e) { return json({ error: 'no se pudo copiar la foto: ' + String((e && e.message) || e) }, 500); }
        return json({ ok: true, key });
      }
      // GET /admin/pedidos/diseno-sugerencias?phone= → últimas imágenes que se le MANDARON a ese cliente por el
      // chat (lo que vio y aprobó; las más nuevas primero) + los últimos renders de sus briefs. El vendedor
      // elige una y la confirma como "diseño aprobado". Solo keys de R2 (las que no se pudieron bajar se omiten).
      if (request.method === 'GET' && path === '/admin/pedidos/diseno-sugerencias') {
        const _sr = await getSessionRole(env, session.user);
        if (!['admin', 'comercial'].includes(_sr)) return json({ error: 'forbidden' }, 403);
        const raw = String(url.searchParams.get('phone') || '').trim();
        const dig = raw.replace(/\D/g, '');
        let phone = '';
        if (/^@|[a-z_.]/i.test(raw)) phone = await igsidDeUsuario(env, raw); // IG guardado con @usuario → IGSID
        else if (dig.length >= 15) phone = dig;                              // IGSID
        else if (dig.length >= 8) phone = await telefonoDelChat(env, dig);   // WPP: sin 549 / con 0 o 15; extranjeros tal cual
        // Mismo control que el chat: un vendedor no ve imágenes de chats de otro ni de las bandejas de Gaspar.
        if (!phone || !(await inboxAccessOk(env, _sr, phone, session.user))) return json({ ok: true, fotos: [] });
        const fotos = [], seen = new Set();
        const push = (k, ts, origen) => { k = String(k || ''); if (!k || seen.has(k) || !/^(wa|ig|briefs|precotiz)\//.test(k)) return; seen.add(k); fotos.push({ key: k, ts: ts || '', origen }); };
        try {
          const rs = await env.DB.prepare("SELECT media_url, ts FROM wa_messages WHERE phone = ? AND direction = 'outbound' AND msg_type = 'image' AND COALESCE(media_url,'') != '' ORDER BY ts DESC LIMIT 8").bind(phone).all();
          for (const m of (rs.results || [])) push(m.media_url, m.ts, 'chat');
        } catch (_) {}
        try {
          const rs = await env.DB.prepare("SELECT bi.r2_key, bi.created_at FROM brief_imagenes bi JOIN briefs b ON b.id = bi.brief_id WHERE b.cliente_wa_id = ? AND bi.tipo IN ('render','render-ia') ORDER BY bi.created_at DESC LIMIT 4").bind(phone).all();
          for (const m of (rs.results || [])) push(m.r2_key, m.created_at, 'render');
        } catch (_) {}
        // Solo las que siguen existiendo en R2 (un render regenerado/borrado del brief deja la key colgada en el chat).
        const vivas = [];
        await Promise.all(fotos.map(async (f, i) => { try { if (await env.MEDIA.head(f.key)) vivas[i] = f; } catch (_) {} }));
        const out = vivas.filter(Boolean);
        // Nombre del brief de cada render (briefs/<id>/...): el front lo usa para sugerirle a CADA cartel su
        // propio diseño cuando el pedido tiene varios (si no, todos sugerían la misma imagen).
        const bids = [...new Set(out.map(f => (f.key.match(/^briefs\/(\d+)\//) || [])[1]).filter(Boolean))];
        if (bids.length) {
          try {
            const rs = await env.DB.prepare(`SELECT id, diseno, cliente_nombre FROM briefs WHERE id IN (${bids.map(() => '?').join(',')})`).bind(...bids.map(Number)).all();
            const nom = {}; for (const b of (rs.results || [])) nom[b.id] = { diseno: b.diseno || '', cliente: b.cliente_nombre || '' };
            for (const f of out) { const id = (f.key.match(/^briefs\/(\d+)\//) || [])[1]; if (id && nom[id]) { f.brief_diseno = nom[id].diseno; f.brief_cliente = nom[id].cliente; } }
          } catch (_) {}
        }
        return json({ ok: true, fotos: out });
      }
      // ===== COMPROBANTE DE PAGO del pedido (oct-2026) =====
      // PUT /admin/pedidos/comprobante[?ocr=1] (body = foto o PDF crudo, ≤12MB) → lo sube a R2 y devuelve {key,tipo}
      // (con ocr=1 también es_comprobante, monto y caja sugerida). NO toca D1: se sube ANTES de crear el pedido
      // o de registrar el 2do pago; la key viaja en ese POST.
      if (request.method === 'PUT' && path === '/admin/pedidos/comprobante') {
        if (!['admin', 'comercial'].includes(await getSessionRole(env, session.user))) return json({ error: 'forbidden' }, 403);
        if (!env.MEDIA) return json({ error: 'R2 not configured' }, 500);
        const _cl = parseInt(request.headers.get('content-length') || '0', 10) || 0;
        if (_cl > 12 * 1024 * 1024) return json({ error: 'el archivo pesa más de 12MB' }, 413);
        const buf = await request.arrayBuffer().catch(() => null);
        if (!buf || buf.byteLength < 64) return json({ error: 'el archivo llegó vacío' }, 400);
        if (buf.byteLength > 12 * 1024 * 1024) return json({ error: 'el archivo pesa más de 12MB' }, 413);
        // El tipo sale de la FIRMA del archivo, no del header: una imagen con content-type equivocado hace que el
        // OCR la rechace. HEIC (fotos crudas de iPhone) no lo lee el OCR → se pide una captura.
        const _b = new Uint8Array(buf.slice(0, 16));
        const _asc = (i, n) => String.fromCharCode(..._b.slice(i, i + n));
        let ct = '', ext = '';
        if (_b[0] === 0xFF && _b[1] === 0xD8 && _b[2] === 0xFF) { ct = 'image/jpeg'; ext = 'jpg'; }
        else if (_b[0] === 0x89 && _asc(1, 3) === 'PNG') { ct = 'image/png'; ext = 'png'; }
        else if (_asc(0, 4) === '%PDF') { ct = 'application/pdf'; ext = 'pdf'; }
        else if (_asc(0, 4) === 'RIFF' && _asc(8, 4) === 'WEBP') { ct = 'image/webp'; ext = 'webp'; }
        if (!ct) return json({ error: 'tiene que ser una foto (JPG/PNG/WEBP) o un PDF. Si es una foto del iPhone, mandá una captura de pantalla' }, 400);
        const _ym = new Date(Date.now() - 3 * 3600 * 1000).toISOString().slice(0, 7).replace('-', '');
        const key = `pedidos/comprobante/${_ym}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
        try { await env.MEDIA.put(key, buf, { httpMetadata: { contentType: ct } }); }
        catch (e) { return json({ error: 'no se pudo guardar el comprobante: ' + String((e && e.message) || e) }, 500); }
        const out = { ok: true, key, tipo: ct === 'application/pdf' ? 'pdf' : 'image' };
        if (url.searchParams.get('ocr') === '1') {
          const o = await ocrComprobantePedido(env, { cacheId: 'key:' + key, phone: '', key, mimeHint: ct, by: 'pedido_comprobante' });
          if (o) Object.assign(out, { es_comprobante: o.es_comprobante, monto: o.monto, caja: o.caja });
        }
        return json(out);
      }
      // GET /admin/pedidos/comprobante-sugerencias?phone=<tel|IGSID|@usuario>&ocr=1 → las últimas fotos/PDF que MANDÓ
      // el cliente (posibles comprobantes, antes o después de la OC: no se filtra por la OC), con el OCR cacheado
      // (monto + caja sugerida) y si ya se usaron como comprobante de otro pedido. Mismo control de bandeja que el
      // chat. ocr=1 analiza hasta 3 archivos sin cache (cada uno = 1 llamada a Sonnet; después quedan guardados).
      if (request.method === 'GET' && path === '/admin/pedidos/comprobante-sugerencias') {
        const _sr = await getSessionRole(env, session.user);
        if (!['admin', 'comercial'].includes(_sr)) return json({ error: 'forbidden' }, 403);
        await ensurePedidosSchema(env);
        const raw = String(url.searchParams.get('phone') || '').trim();
        const dig = raw.replace(/\D/g, '');
        let phone = '';
        if (/^@|[a-z_.]/i.test(raw)) phone = await igsidDeUsuario(env, raw);
        else if (dig.length >= 15) phone = dig;
        else if (dig.length >= 8) phone = await telefonoDelChat(env, dig);
        if (!phone || !(await inboxAccessOk(env, _sr, phone, session.user))) return json({ ok: true, phone: phone || '', oc_ts: null, items: [] });
        let msgs = [];
        try {
          msgs = (await env.DB.prepare("SELECT wamid, ts, msg_type, body, media_url FROM wa_messages WHERE phone = ? AND direction = 'inbound' AND msg_type IN ('image','document') AND (media_url LIKE 'wa/%' OR media_url LIKE 'ig/%') AND ts >= ? ORDER BY ts DESC LIMIT 12").bind(phone, isoHace(45 * 86400 * 1000)).all()).results || [];
        } catch (_) {}
        // Tipo según R2: solo imagen o PDF (audios, videos y docx no son comprobantes). Las que ya no están en R2 se omiten.
        const cand = [];
        await Promise.all(msgs.map(async (m, i) => {
          if (!esKeyComprobantePedido(m.media_url)) return;
          let ctt = '';
          try { const h = await env.MEDIA.head(m.media_url); if (!h) return; ctt = String((h.httpMetadata && h.httpMetadata.contentType) || '').toLowerCase(); } catch (_) { return; }
          let tipo = '';
          if (/pdf/.test(ctt) || /\.pdf$/i.test(m.media_url)) tipo = 'pdf';
          else if (/^image\//.test(ctt) || /\.(jpe?g|png|webp|gif)$/i.test(m.media_url)) tipo = 'image';
          if (!tipo) return;
          cand[i] = { key: m.media_url, wamid: m.wamid || '', ts: m.ts || '', tipo, nombre: m.msg_type === 'document' ? String(m.body || '').slice(0, 80) : '', mime: tipo === 'pdf' ? 'application/pdf' : (ctt || 'image/jpeg') };
        }));
        const items = cand.filter(Boolean).slice(0, 8);
        await ensurePagoOcr(env);
        const wids = items.map(x => x.wamid).filter(Boolean);
        const cache = {}, ocHint = {};
        if (wids.length) {
          const ph = wids.map(() => '?').join(',');
          try { for (const r of ((await env.DB.prepare(`SELECT * FROM pago_ocr WHERE wamid IN (${ph})`).bind(...wids).all()).results || [])) cache[r.wamid] = pagoOcrFila(r); } catch (_) {}
          // El vigilador de la OC (processCartelPagos) ya marcó cuáles fueron comprobante: se analizan primero.
          try { for (const r of ((await env.DB.prepare(`SELECT wamid, es_comprobante FROM oc_pago_check WHERE wamid IN (${ph})`).bind(...wids).all()).results || [])) ocHint[r.wamid] = r.es_comprobante; } catch (_) {}
        }
        if (url.searchParams.get('ocr') === '1') {
          const pend = items.filter(x => x.wamid && !cache[x.wamid]).sort((a, b) => (ocHint[b.wamid] ? 1 : 0) - (ocHint[a.wamid] ? 1 : 0)).slice(0, 3);
          await Promise.all(pend.map(async x => { const o = await ocrComprobantePedido(env, { cacheId: x.wamid, phone, key: x.key, mimeHint: x.mime, by: 'pedido_comprobante' }); if (o) cache[x.wamid] = o; }));
        }
        // ¿Ese archivo ya es comprobante (1er o 2do pago) de algún pedido? El front avisa para no usarlo dos veces.
        const keys = items.map(x => x.key);
        const usado = {};
        if (keys.length) {
          const pk = keys.map(() => '?').join(',');
          try {
            const rs = (await env.DB.prepare(`SELECT id, numero, cartel, comprobante_key, comprobante2_key FROM pedidos WHERE comprobante_key IN (${pk}) OR comprobante2_key IN (${pk})`).bind(...keys, ...keys).all()).results || [];
            for (const r of rs) for (const k of [r.comprobante_key, r.comprobante2_key]) {
              if (!k || !keys.includes(k)) continue;
              const l = (usado[k] = usado[k] || []);
              if (!l.some(u => u.numero === r.numero)) l.push({ id: r.id, numero: r.numero, cartel: r.cartel || '' });
            }
          } catch (_) {}
        }
        let ocTs = null;
        try { const o = await env.DB.prepare('SELECT MAX(ts_out) AS t FROM oc_enviadas WHERE phone = ?').bind(phone).first(); ocTs = (o && o.t) || null; } catch (_) {}
        const outItems = items.map(x => {
          const o = cache[x.wamid] || null;
          return {
            key: x.key, wamid: x.wamid, ts: x.ts, tipo: x.tipo, nombre: x.nombre,
            es_comprobante: o ? o.es_comprobante : (ocHint[x.wamid] ? true : null),
            monto: o ? o.monto : null, caja: o ? o.caja : '', titular: o ? o.titular : '', banco: o ? o.banco : '',
            usado_en: usado[x.key] || [], sugerido: false
          };
        });
        // Sugerido: el comprobante confirmado por OCR más nuevo que no se usó en otro pedido (mejor si llegó después
        // de la OC); si no hay ninguno confirmado, el más nuevo todavía sin analizar. Nunca uno que el OCR descartó.
        const libres = outItems.filter(x => !x.usado_en.length && x.es_comprobante !== false);
        const s = libres.find(x => x.es_comprobante === true && ocTs && x.ts >= ocTs) || libres.find(x => x.es_comprobante === true) || libres.find(x => x.es_comprobante == null);
        if (s) s.sugerido = true;
        return json({ ok: true, phone, oc_ts: ocTs, items: outItems });
      }
      // POST /admin/pedidos/:id/diseno-foto {key} → asigna o cambia la foto del diseño final de un cartel ya
      // cargado (drawer: "la subo después", o pedidos viejos). Si el cartel no tiene pieza de corte, la crea.
      // Si Emma ya hizo la matriz (matriz_lista) vuelve a su cola para revisarla; si ya se cortó, se avisa.
      if (request.method === 'POST' && /^\/admin\/pedidos\/\d+\/diseno-foto$/.test(path)) {
        const _r = await getSessionRole(env, session.user);
        if (!['admin', 'comercial'].includes(_r)) return json({ error: 'forbidden' }, 403);
        await ensurePedidosSchema(env); await ensureCorteNeonSchema(env);
        const pid = parseInt(path.split('/')[3], 10);
        let body; try { body = await request.json(); } catch { body = {}; }
        const key = String(body.key || '');
        if (!esKeyDisenoPedido(key)) return json({ error: 'foto inválida' }, 400);
        const p = await env.DB.prepare('SELECT * FROM pedidos WHERE id = ?').bind(pid).first();
        if (!p) return json({ error: 'pedido no encontrado' }, 404);
        if (_r === 'comercial') {
          const mio = await resolveComercial(env, { sessionUser: session.user });
          if (String(p.comercial_id || 'joaco') !== mio) return json({ error: 'ese pedido es de otro vendedor' }, 403);
        }
        const nowIso = new Date().toISOString();
        // CORPÓREO: no va al corte (Emma no tiene nada que ver): la foto queda en el pedido y se suma sola a las
        // fotos del ticket de producción cuando se arma. Si el ticket YA estaba armado, se avisa (no se reenvía).
        if (Number(p.es_corporeo) === 1) {
          // Sin tocar updated_at: el espejo al Excel reclama/guarda cada fila con "WHERE updated_at = <el que leyó>";
          // cambiarlo a mitad de un push perdía el sheet_row y duplicaba la fila en Pedidos_Corporeo. La foto no se espeja.
          await env.DB.prepare('UPDATE pedidos SET foto_diseno_key = ? WHERE id = ?').bind(key, pid).run();
          let avisoC = '';
          try { const t = await env.DB.prepare('SELECT numero FROM corporeo_tickets WHERE pedido_id = ? ORDER BY id DESC LIMIT 1').bind(pid).first(); if (t && t.numero) avisoC = `Este corpóreo ya tiene el ticket #${t.numero} armado: la foto quedó en el pedido pero no se agregó a ese ticket.`; } catch (_) {}
          return json({ ok: true, aviso: avisoC, pedidos: await pedidosConDiseno(env, 'WHERE pedidos.id = ?', [pid], { interno: _r === 'admin', fotos: true }) });
        }
        const pieza = await env.DB.prepare('SELECT id, estado FROM corte_pedidos WHERE pedido_id = ? ORDER BY id DESC LIMIT 1').bind(pid).first();
        let aviso = '';
        // Pedido ANTERIOR al circuito de corte de neón (CORTE_NEON_DESDE, lo mismo que usa el barredor): esos carteles se
        // hicieron por fuera del sistema → la foto queda en el pedido y NO se crea pieza en la cola de Emma (caso Peuma 2
        // #379, 6-oct: subieron la foto de un pedido del 25/9 YA cortado y le apareció "por diseñar"). Si de verdad falta
        // hacerlo, el front pregunta y reenvía con a_corte:true. Sin tocar updated_at (mismo motivo que el corpóreo, arriba).
        if (!pieza && String(p.created_at || '') < CORTE_NEON_DESDE && body.a_corte !== true) {
          await env.DB.prepare('UPDATE pedidos SET foto_diseno_key = ? WHERE id = ?').bind(key, pid).run();
          return json({ ok: true, pregunta_corte: true, aviso: 'Foto guardada en el pedido (pedido anterior al circuito de corte: no se mandó a la cola de Emma).', pedidos: await pedidosConDiseno(env, 'WHERE pedidos.id = ?', [pid], { interno: _r === 'admin', fotos: true }) });
        }
        if (!pieza) {
          const t = await corteTandaActual(env);
          const vend = corteVendedorNombre(p.comercial_id) || p.cargado_por || '';
          await stmtInsertCortePieza(env, '?', pid, p.numero, cortePiezaDesdeCartel(p, p.numero, vend), key, vend, t ? t.id : null, nowIso).run();
          // Si otra subida simultánea la creó primero (el INSERT OR IGNORE no hizo nada), gana la última foto.
          await env.DB.prepare("UPDATE corte_pedidos SET foto_key = ?, updated_at = ? WHERE pedido_id = ? AND estado = 'pedido'").bind(key, nowIso, pid).run();
        } else if (pieza.estado === 'pedido') {
          await env.DB.prepare('UPDATE corte_pedidos SET foto_key = ?, updated_at = ? WHERE id = ?').bind(key, nowIso, pieza.id).run();
        } else if (pieza.estado === 'matriz_lista') {
          await env.DB.prepare("UPDATE corte_pedidos SET foto_key = ?, estado = 'pedido', aclaraciones = CASE WHEN IFNULL(aclaraciones,'') LIKE '⚠ FOTO CAMBIADA%' THEN aclaraciones ELSE '⚠ FOTO CAMBIADA, revisar la matriz · ' || IFNULL(aclaraciones,'') END, updated_at = ? WHERE id = ?").bind(key, nowIso, pieza.id).run();
          aviso = 'Emma ya había hecho la matriz: volvió a su cola para que la revise con la foto nueva.';
        } else {
          await env.DB.prepare('UPDATE corte_pedidos SET foto_key = ?, updated_at = ? WHERE id = ?').bind(key, nowIso, pieza.id).run();
          aviso = 'Esta pieza ya está cortada: avisales a Emma y a Aníbal del cambio de diseño.';
        }
        return json({ ok: true, aviso, pedidos: await pedidosConDiseno(env, 'WHERE pedidos.id = ?', [pid], { interno: _r === 'admin', fotos: true }) });
      }

      // POST /admin/pedidos → crea un pedido (1+ carteles que comparten número).
      // numero = max+1 (server-side); fecha = hoy si no viene; estado_pedido fijo
      // 'En produccion'; pagado/restante a nivel pedido (restante = total − pagado)
      // replicados en cada fila. origen='crm' (lo distingue del backfill del Excel).
      if (request.method === 'POST' && path === '/admin/pedidos') {
        // Solo vendedores y admin cargan ventas (diseño/producción/cursos no: con un POST armado a mano
        // creaban pedidos + piezas para Emma y los espejaban al Excel).
        if (!['admin', 'comercial'].includes(await getSessionRole(env, session.user))) return json({ error: 'forbidden' }, 403);
        await ensurePedidosSchema(env);
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const carteles = Array.isArray(body.carteles) ? body.carteles.filter(c => c && String(c.cartel || '').trim()) : [];
        if (!carteles.length) return json({ error: 'falta al menos un cartel con nombre' }, 400);
        const now = new Date().toISOString();
        const fecha = (body.fecha && /^\d{4}-\d{2}-\d{2}$/.test(body.fecha)) ? body.fecha : now.slice(0, 10);
        // El número viene del front (auto-sugerido pero editable por Joaco, porque
        // el numbering del Excel es inconsistente). Si no viene, fallback a max+1.
        const bodyNum = Math.floor(Number(body.numero));
        let numero;
        if (Number.isFinite(bodyNum) && bodyNum > 0) {
          numero = bodyNum;
        } else {
          const mx = await env.DB.prepare('SELECT MAX(numero) AS m FROM pedidos').first();
          numero = (mx && mx.m ? Math.floor(Number(mx.m)) : 0) + 1;
        }
        const num = (v) => (v == null || v === '') ? null : (isNaN(Number(v)) ? null : Number(v));
        const total = carteles.reduce((s, c) => s + (num(c.precio) || 0) + (num(c.precio_dimmer) || 0), 0);
        // Sin Frontera compra en CUENTA CORRIENTE (Gaspar 16-oct: "tenemos una cuenta corriente que está en otro Excel"): con
        // Cliente: Sin Frontera (solo admin) el alta va sin seña, caja ni comprobante, estado_pago 'Cuenta corriente' y restante 0
        // (la deuda se lleva aparte: no entra a "por cobrar" ni cierra la OC del chat).
        const esCuentaSF = !!body.cliente_sf && String(body.estado_pago || '') === 'Cuenta corriente' && (await getSessionRole(env, session.user)) === 'admin';
        // SIN PAGO (solo admin, Gaspar 16-oct: "un cliente frecuente que me paga en unos días pero quiero cargarlo igual"):
        // sin seña, caja ni comprobante; queda '1er pago' con $0 (la hoja 2026 solo acepta 1er/2do pago) y cobrar_el =
        // el día que tiene que cobrarlo → recordatorio por plantilla a Gaspar hasta que se registre el pago
        // (processCobrosPendientes). NO cierra la OC del chat (sigue sin pagar). El pago se registra con el modal de
        // pago (POST /admin/pedidos/:id/segundo-pago, que en un pedido sin seña lo toma como el 1er cobro).
        const esSinPago = !esCuentaSF && String(body.pago_metodo || '').toLowerCase() === 'pendiente' && (await getSessionRole(env, session.user)) === 'admin';
        let cobrarEl = '';
        if (esSinPago) {
          const hoyAR = new Date(Date.now() - 3 * 3600 * 1000).toISOString().slice(0, 10);
          const pedido = String(body.cobrar_el || '').trim();
          let def = Date.parse(hoyAR + 'T12:00:00Z') + 3 * 86400000;
          if (new Date(def).getUTCDay() === 0) def += 86400000;   // domingo → lunes
          cobrarEl = (/^\d{4}-\d{2}-\d{2}$/.test(pedido) && !isNaN(Date.parse(pedido + 'T12:00:00Z')) && pedido >= hoyAR) ? pedido : new Date(def).toISOString().slice(0, 10);
        }
        const pagado = (esCuentaSF || esSinPago) ? 0 : num(body.pagado);
        const restante = esCuentaSF ? 0 : (pagado != null ? Math.max(0, total - pagado) : total);
        const plataforma = body.plataforma === 'IG' ? 'IG' : 'WPP';
        let estadoPago = esCuentaSF ? 'Cuenta corriente' : (esSinPago ? '1er pago' : String(body.estado_pago || '1er pago'));
        if (!esCuentaSF && /^cuenta corriente$/i.test(estadoPago.trim())) estadoPago = '1er pago';
        if (estadoPago === '2do pago' && !(pagado != null && pagado >= total - 1)) estadoPago = '1er pago';   // '2do pago' = pagó todo
        // PAGO (oct-2026): comprobante + caja OBLIGATORIOS. Se exigen solo si el front es el nuevo (pago_v ≥ 2): un
        // vendedor con la PWA vieja en caché no manda estos campos y no se le frena la venta (regla de la casa).
        // Efectivo ⇔ caja 'Efectivo' y sin comprobante (el importe es `pagado`).
        const pagoV = Number(body.pago_v) || 0;
        let pagoMetodo = String(body.pago_metodo || '').toLowerCase() === 'efectivo' ? 'efectivo' : (body.pago_metodo ? 'transferencia' : '');
        let caja = cajaCanon(body.caja);
        if (pagoMetodo === 'efectivo') caja = 'Efectivo';
        else if (caja === 'Efectivo') pagoMetodo = 'efectivo';
        let compKey = (pagoMetodo !== 'efectivo' && esKeyComprobantePedido(body.comprobante_key)) ? String(body.comprobante_key) : '';
        if (esCuentaSF) { caja = ''; compKey = ''; pagoMetodo = ''; }
        if (esSinPago) { caja = ''; compKey = ''; pagoMetodo = 'pendiente'; }
        const compWamid = compKey ? String(body.comprobante_wamid || '').slice(0, 200) : '';
        if (pagoV >= 2 && !esCuentaSF && !esSinPago) {
          if (!caja) return json({ error: 'Falta a qué caja pagó', campo: 'caja' }, 400);
          if (!(pagado > 0)) return json({ error: 'Falta el importe pagado', campo: 'pagado' }, 400);
          if (!pagoMetodo) pagoMetodo = 'transferencia';
          if (pagoMetodo !== 'efectivo') {
            if (!compKey) return json({ error: 'Falta el comprobante de pago', campo: 'comprobante' }, 400);
            let _existe = null; try { _existe = env.MEDIA ? await env.MEDIA.head(compKey) : true; } catch (_) { _existe = true; }
            if (!_existe) return json({ error: 'No encuentro ese comprobante: subilo de nuevo', campo: 'comprobante' }, 400);
          }
        }
        const ad = String(body.ad || '');
        // source_id = ad_id EXACTO de Meta que el modal capturó de la atribución (opcional). Se
        // guarda directo en el INSERT así el pedido nace trazado y el funnel lo clasifica al toque
        // (sin esperar a la red de seguridad). Vacío → NULL (no ''), para que el backfill —que
        // filtra source_id IS NULL— siga alcanzando a los pedidos sin atribución del front.
        const sourceId = String(body.source_id || '').trim();
        // Contacto del cliente: en WPP es el teléfono (solo dígitos). En IG es el @usuario / id
        // de Instagram → NO stripeamos no-dígitos ahí (si no, un @usuario quedaría vacío).
        // WPP: en el formato del chat (un "1164791648" tipeado a mano no matcheaba el chat 5491164791648 →
        // la venta se atribuía a Joaco aunque el chat fuera de Agustina, ej. #391; tampoco trazaba el ad).
        const telefono = plataforma === 'IG'
          ? String(body.telefono || '').trim().slice(0, 120)
          : await telefonoDelChat(env, body.telefono);
        // Vendedor de la venta: el usuario logueado que la carga (o el vendedor del chat). En IG el campo
        // telefono suele ser el @usuario (sin dígitos): para buscar a quién está asignado el chat se usa el
        // IGSID que manda el modal (ig_id) — si no, un admin cargando el IG de un cliente de Facu/Agus
        // se lo atribuía a Joaco.
        // Sin ig_id (pedido IG cargado a mano con @usuario): se resuelve el @usuario al IGSID.
        const igId = String(body.ig_id || '').replace(/\D/g, '') || (plataforma === 'IG' ? await igsidDeUsuario(env, telefono) : '');
        // Lo que carga Gaspar (admin) es venta SUYA, sin comisión para nadie (Gaspar 14-oct: "si se cargan desde admin
        // los cargué yo… no va la comisión a Joaquín, a mí tampoco porque soy el dueño"), salvo que elija un vendedor.
        const _vendElegido = funnelVendedor(String(body.comercial_id || ''));
        const _vendAlta = ['joaco', ...VENDEDORES_SECUNDARIOS];
        const comercialId = (sessionUserKey === 'gaspar' && !_vendAlta.includes(_vendElegido))
          ? 'gaspar'
          : await resolveComercial(env, { bodyComercial: body.comercial_id, sessionUser: session.user, phone: (plataforma === 'IG' && igId) ? igId : telefono });
        // Usuario literal que cargó el pedido (para ver si lo cargó Facu/Joaco/Gaspar). Si Gaspar la cargó a nombre de un
        // vendedor, va el vendedor: la col C del Excel (comisiones) sale de cargado_por ("se corrige el cargado_por").
        const cargadoPor = (sessionUserKey === 'gaspar' && _vendAlta.includes(_vendElegido))
          ? (({ joaco: 'Joaquín', facundo: 'Facundo', agustina: 'Agustina' })[_vendElegido] || (COMERCIALES_SECUNDARIOS.find(c => c.slug === _vendElegido) || {}).nombre || _vendElegido)
          : String(session.user || '');
        // Tramos / cm de neón que falten (o vengan en 0/negativos) en un cartel de neón: se completan desde su
        // brief. Best-effort: si no hay brief claro el pedido se carga igual (nunca se frena una venta acá).
        for (const c of carteles) {
          if (c.es_corporeo === 1 || c.es_corporeo === true || c.es_corporeo === '1') continue;
          if (!(Number(c.tramos) >= 1)) c.tramos = null;
          if (c.tramos != null && Number(c.cm_neon) > 0) continue;
          const fb = await briefNeonDeCartel(env, plataforma === 'WPP' ? telefono : '', c);
          if (!fb) continue;
          if (c.tramos == null && fb.tramos >= 1) c.tramos = fb.tramos;
          if (!(Number(c.cm_neon) > 0) && fb.cm_neon) c.cm_neon = fb.cm_neon;
        }
        // Piezas de NEÓN PROPIO para el corte: cada cartel de neón nace también como pieza 'NEON' en
        // corte_pedidos (matriz a diseñar por Emma), con la foto del diseño final y su medida.
        try { await ensureCorteNeonSchema(env); } catch (_) {}
        const _tanda = await corteTandaActual(env);
        const _tandaId = _tanda ? _tanda.id : null;
        const _vendedor = corteVendedorNombre(comercialId) || cargadoPor || ''; // el que VENDIÓ (no el que cargó)
        const _esCorpC = (c) => (c.es_corporeo === 1 || c.es_corporeo === true || c.es_corporeo === '1') ? 1 : 0;
        // foto_key null = "la subo después" (la pieza nace "esperando foto").
        const _insCortePieza = (c, pedidoIdSql, pedidoIdArg) => stmtInsertCortePieza(
          env, pedidoIdSql, pedidoIdArg, numero, cortePiezaDesdeCartel(c, numero, _vendedor),
          esKeyDisenoPedido(c.foto_key) ? String(c.foto_key) : null, _vendedor, _tandaId, now);
        const pedidoStmts = carteles.map(c => {
          // Un ítem es corpóreo (letra 3D) si el front lo marca. TODOS se espejan (mirror_dirty=1):
          // los corpóreos van al Sheet 2026 v4 (Pedidos_Corporeo) y el neón al Excel de Ventas de
          // siempre — el ruteo por es_corporeo lo hace processPedidosMirror.
          const esCorp = _esCorpC(c);
          const mirrorDirty = 1;
          return env.DB.prepare(
          `INSERT INTO pedidos (numero, fecha, cartel, colores, alto, ancho, cm_neon, base, cantidad, precio, dimer, precio_dimmer, envio, aclaracion, tramos, tipo, productor, plataforma, estado_pago, pagado, restante, estado_pedido, ad, telefono, comercial_id, cargado_por, sheet_row, origen, mirror_dirty, es_corporeo, producto, frente, laterales, espalda, iluminacion, bastidor, color_bastidor, instalacion, created_at, updated_at, source_id, foto_diseno_key, caja, pago_metodo, comprobante_key, comprobante_wamid, cobrar_el)
           VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?, '', ?, ?, ?, ?, 'En produccion', ?, ?, ?, ?, NULL, 'crm', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
        ).bind(
          numero, fecha, String(c.cartel || '').trim(), String(c.colores || '').trim(),
          num(c.alto), num(c.ancho), num(c.cm_neon), String(c.base || '').trim(),
          num(c.cantidad) || 1, num(c.precio), String(c.dimer || 'NO').trim(), num(c.precio_dimmer),
          String(c.envio || '').trim(), String(c.aclaracion || '').trim(), num(c.tramos), String(c.tipo || '').trim(),
          plataforma, estadoPago, pagado, restante, ad, telefono, comercialId, cargadoPor,
          mirrorDirty, esCorp, String(c.producto || '').trim(),
          String(c.frente || '').trim(), String(c.laterales || '').trim(), String(c.espalda || '').trim(),
          String(c.iluminacion || '').trim(), String(c.bastidor || '').trim(), String(c.color_bastidor || '').trim(), String(c.instalacion || '').trim(),
          now, now, (sourceId || null),
          // Corpóreo: su foto del diseño queda en el pedido (key, o '' = "la subo después"). Neón: NULL (va a su pieza de corte).
          esCorp ? (esKeyDisenoPedido(c.foto_key) ? String(c.foto_key) : '') : null,
          // Pago a nivel PEDIDO (se repite en cada cartel, como pagado/estado_pago). La caja va a la col Z (syncCajaPedidos).
          caja || null, pagoMetodo || null, compKey || null, compWamid || null, cobrarEl || null
        );
        });
        // Batch: cada INSERT de cartel de neón va seguido del INSERT de su pieza de corte, vinculada por
        // last_insert_rowid() (mismo batch = misma transacción). NO se vincula por número: el N° se repite
        // entre vendedores y fechas. Si el batch con piezas falla, la VENTA NO SE BLOQUEA: se reintenta
        // solo con los carteles y las piezas se crean después una por una; si eso también falla, las
        // levanta el barredor del cron (ensureCortePiezasNeonPendientes).
        const stmts = [];
        carteles.forEach((c, i) => { stmts.push(pedidoStmts[i]); if (!_esCorpC(c)) stmts.push(_insCortePieza(c, 'last_insert_rowid()', null)); });
        if (stmts.length === pedidoStmts.length) {
          await env.DB.batch(pedidoStmts);
        } else {
          try { await env.DB.batch(stmts); }
          catch (_eCorte) {
            // ¿El batch se escribió igual y solo falló la respuesta (corte de red / reset)? D1 no reintenta
            // escrituras: si los carteles YA están, NO re-insertar (duplicaría la venta y el espejo al Excel).
            const _yaEstan = async () => ((await env.DB.prepare("SELECT id FROM pedidos WHERE numero = ? AND origen = 'crm' AND created_at = ? ORDER BY id").bind(numero, now).all()).results || []);
            let nuevos = [];
            try { nuevos = await _yaEstan(); } catch (_) {}
            if (!nuevos.length) { await env.DB.batch(pedidoStmts); try { nuevos = await _yaEstan(); } catch (_) {} }
            // Piezas que falten (INSERT OR IGNORE + índice único por pedido_id: no duplica si ya estaban).
            for (let i = 0; i < carteles.length && i < nuevos.length; i++) {
              if (_esCorpC(carteles[i])) continue;
              try { await _insCortePieza(carteles[i], '?', nuevos[i].id).run(); } catch (_) {}
            }
          }
        }
        // SOLO las filas recién creadas (mismo número + created_at de este alta): el N° se repite entre
        // vendedores, y antes la respuesta (y el trazado de ad de abajo) arrastraba pedidos de otro.
        const rs = { results: await pedidosConDiseno(env, 'WHERE pedidos.numero = ? AND pedidos.origen = ? AND pedidos.created_at = ? ORDER BY pedidos.id', [numero, 'crm', now], { interno: (await getSessionRole(env, session.user)) === 'admin', fotos: true }) };
        // Mano de obra del productor (por tiempo desde mo_desde): queda guardada en cada cartel de neón.
        try { await moActualizar(env, (rs.results || []).map(r => r.id)); } catch (_) {}
        // Cliente Sin Frontera (solo Gaspar): queda vinculado en el MISMO alta (antes era un segundo POST del front que podía
        // fallar suelto). Lo ven en su "Mis pedidos". Desde 16-oct todos sus neones se cargan acá (Pedidos_Distris = histórico).
        let sfVinculado = false;
        if (body.cliente_sf && (rs.results || []).length && (await getSessionRole(env, session.user)) === 'admin') {
          try {
            await ensureSinFronteraSchema(env);
            await env.DB.batch(rs.results.map(r => env.DB.prepare('INSERT OR IGNORE INTO sinfrontera_pedidos (pedido_id, por, at) VALUES (?, ?, ?)').bind(r.id, String(session.user || ''), now)));
            sfVinculado = true;
          } catch (_) {}
        }
        // Red de seguridad: si el pedido quedó SIN ad (no se trazó en el front, o se cargó a mano),
        // intentar trazarlo server-side ya mismo. WPP por teléfono; IG por IGSID vía la OC del chat
        // (traceAdForPedido resuelve el phone del cliente aunque telefono venga como @usuario/vacío).
        // Best-effort: si falla, el cron lo agarra igual en el próximo minuto.
        try {
          for (const row of (rs.results || [])) {
            const adTxt = String(row.ad || '').trim();
            const hasSource = String(row.source_id || '').trim() !== '';
            // Ya trazado (ad + source_id) → listo, no tocar.
            if (adTxt && hasSource) continue;
            // Con ad de texto pero SIN source_id: solo re-trazamos el label genérico que arma el
            // front ("IG ad: ..."/"FB ad: ..."), que trae el nombre del ad pero DESCARTA el ad_id
            // → sin source_id el funnel no lo puede clasificar. Los labels cargados a mano
            // (directo/frecuente/referido/link bio) se respetan y NO se tocan.
            const adl = adTxt.toLowerCase();
            const esGenericoAd = adl.indexOf('ig ad') === 0 || adl.indexOf('fb ad') === 0;
            if (adTxt && !esGenericoAd) continue;
            const t = await traceAdForPedido(env, row);
            if (t.ad) {
              await env.DB.prepare("UPDATE pedidos SET ad=?, source_id=?, source_campaign=?, telefono=CASE WHEN COALESCE(telefono,'')='' THEN ? ELSE telefono END, mirror_dirty=1 WHERE id=?").bind(t.ad, t.source_id || '', t.source_campaign || '', t.telefono, row.id).run();
              row.ad = t.ad;
            }
          }
        } catch (_) {}
        // OC de ese cliente → pagada (saca POR PAGAR, pone "Cartel primer pago", oc_enviadas.pagado_at). Ver ocCerrarPorPedido.
        if (!esCuentaSF && !esSinPago) await ocCerrarPorPedido(env, [telefono, igId], estadoPago);
        return json({ ok: true, numero, pedidos: rs.results || [], ...(body.cliente_sf ? { sf_vinculado: sfVinculado } : {}) });
      }

      // PATCH /admin/pedidos/:id → edita un pedido. Dos alcances:
      //  - Campos del CARTEL (solo esta fila, por id): cartel, base, dimer, precio, ad,
      //    envio, aclaracion.
      //  - Campos del PEDIDO (todas las filas del numero+fecha): estado_pedido,
      //    estado_pago, productor, pagado.
      // Si cambia el precio (cartel) o el pagado (pedido), recalcula el restante del
      // pedido = (Σ precio + Σ precio_dimmer) − pagado. Todo marca mirror_dirty.
      if (request.method === 'PATCH' && /^\/admin\/pedidos\/\d+$/.test(path)) {
        const _pr = await getSessionRole(env, session.user);
        if (!['admin', 'comercial'].includes(_pr)) return json({ error: 'forbidden' }, 403);
        await ensurePedidosSchema(env);
        const id = parseInt(path.split('/').pop(), 10);
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const ref = await env.DB.prepare("SELECT numero, fecha, IFNULL(comercial_id,'joaco') AS com, origen, IFNULL(telefono,'') AS tel FROM pedidos WHERE id = ?").bind(id).first();
        if (!ref) return json({ error: 'pedido no encontrado' }, 404);
        // Un vendedor solo edita SUS pedidos (mismo criterio que la lista que ve).
        if (_pr === 'comercial' && ref.com !== await resolveComercial(env, { sessionUser: session.user })) return json({ error: 'ese pedido es de otro vendedor' }, 403);
        // Neón del tablero (desde NEON_TABLERO_DESDE): el estado lo mueve el tablero de producción (Gaspar 16-oct: "bloqueá que los
        // vendedores cambien el estado de los neones"); solo Gaspar lo cambia a mano. Antes de escribir nada (no deja medio
        // guardado). Mismo valor que el actual (pantalla vieja que manda todo): se ignora sin error. Los neones de antes del
        // tablero siguen como antes (si no, nadie los podría cerrar).
        if (('estado_pedido' in body) && _pr !== 'admin' && String(ref.fecha || '') >= NEON_TABLERO_DESDE) {
          let _gq = "numero = ? AND fecha = ? AND IFNULL(comercial_id,'joaco') = ?"; const _ga = [ref.numero, ref.fecha, ref.com];
          if (ref.origen === 'crm' && ref.tel) { _gq += " AND origen = 'crm' AND IFNULL(telefono,'') = ?"; _ga.push(ref.tel); }
          const _neo = await env.DB.prepare('SELECT COUNT(*) AS n, MAX(IFNULL(estado_pedido,\'\')) AS e FROM pedidos WHERE ' + _gq + ' AND IFNULL(es_corporeo,0) = 0').bind(..._ga).first();
          if (_neo && Number(_neo.n) > 0) {
            if (_normTxt(String(body.estado_pedido || '')).trim() !== _normTxt(String(_neo.e || '')).trim()) return json({ error: 'El estado de los pedidos de neón lo mueve el tablero de Producción neón. Si hay que corregirlo, pedíselo a Gaspar.', campo: 'estado_pedido' }, 403);
            delete body.estado_pedido;
          }
        }
        const now = new Date().toISOString();
        let touched = false, precioChanged = false;

        // 0) Caja / comprobante del 1er pago (corrección desde el drawer, o completar un pedido cargado con la PWA vieja).
        //    Se validan ANTES de escribir nada (un 400 a mitad de camino dejaba el resto a medias) y sobre el estado
        //    FINAL: transferencia ⇒ con comprobante (salvo admin, que corrige históricos); efectivo ⇒ sin comprobante.
        //    No van al Apps Script (no marcan mirror_dirty ni updated_at): la caja la lleva syncCajaPedidos a la col Z.
        const pSets = [], pArgs = [];
        if ('caja' in body || 'comprobante_key' in body) {
          const cur = (await env.DB.prepare("SELECT IFNULL(caja,'') AS caja, IFNULL(comprobante_key,'') AS ck FROM pedidos WHERE id = ?").bind(id).first()) || { caja: '', ck: '' };
          const cj = ('caja' in body) ? cajaCanon(body.caja) : cajaCanon(cur.caja);
          if (('caja' in body) && body.caja && !cj) return json({ error: 'caja inválida', campo: 'caja' }, 400);
          let ck = ('comprobante_key' in body) ? (esKeyComprobantePedido(body.comprobante_key) ? String(body.comprobante_key) : '') : String(cur.ck || '');
          if (('comprobante_key' in body) && body.comprobante_key && !ck) return json({ error: 'comprobante inválido', campo: 'comprobante' }, 400);
          let cw = ('comprobante_key' in body) ? (ck ? String(body.comprobante_wamid || '').slice(0, 200) : '') : null;   // null = no tocar
          if (cj === 'Efectivo') { ck = ''; cw = ''; }
          else if (cj && !ck && _pr !== 'admin') return json({ error: 'Falta el comprobante de pago', campo: 'comprobante' }, 400);
          if (ck && ck !== cur.ck) {
            let _existe = null; try { _existe = env.MEDIA ? await env.MEDIA.head(ck) : true; } catch (_) { _existe = true; }
            if (!_existe) return json({ error: 'No encuentro ese comprobante: subilo de nuevo', campo: 'comprobante' }, 400);
          }
          pSets.push('caja = ?', 'pago_metodo = ?', 'comprobante_key = ?', 'caja_sync_attempts = 0', 'caja_sync_err = NULL');
          pArgs.push(cj || null, cj ? (cj === 'Efectivo' ? 'efectivo' : 'transferencia') : null, ck || null);
          if (cw !== null || !ck) { pSets.push('comprobante_wamid = ?'); pArgs.push(cw || null); }
        }

        // 1) Campos del CARTEL → UPDATE solo esta fila (por id).
        const cSets = [], cArgs = [];
        if ('cartel' in body)     { cSets.push('cartel = ?');     cArgs.push(String(body.cartel || '').trim()); }
        if ('base' in body)       { cSets.push('base = ?');       cArgs.push(String(body.base || '').trim()); }
        if ('dimer' in body)      { cSets.push('dimer = ?');      cArgs.push(String(body.dimer || '').trim()); }
        if ('ad' in body)         { cSets.push('ad = ?');         cArgs.push(String(body.ad || '').trim()); }
        if ('envio' in body)      { cSets.push('envio = ?');      cArgs.push(String(body.envio || '').trim()); }
        if ('aclaracion' in body) { cSets.push('aclaracion = ?'); cArgs.push(String(body.aclaracion || '').trim()); }
        if ('precio' in body) {
          const pv = (body.precio === '' || body.precio == null) ? null : (isNaN(Number(body.precio)) ? null : Number(body.precio));
          cSets.push('precio = ?'); cArgs.push(pv); precioChanged = true;
        }
        // Medidas + specs (cartel/corpóreo), editables desde el drawer. Números → null si vacío/NaN.
        const _numOrNull = (v) => (v === '' || v == null || isNaN(Number(v))) ? null : Number(v);
        if ('alto' in body)           { cSets.push('alto = ?');           cArgs.push(_numOrNull(body.alto)); }
        if ('ancho' in body)          { cSets.push('ancho = ?');          cArgs.push(_numOrNull(body.ancho)); }
        if ('cm_neon' in body)        { cSets.push('cm_neon = ?');        cArgs.push(_numOrNull(body.cm_neon)); }
        // Tramos (para la mano de obra): solo enteros positivos; vacío/0/negativo → NULL (ej. el -39 del #952).
        if ('tramos' in body)         { const t = _numOrNull(body.tramos); cSets.push('tramos = ?'); cArgs.push(t != null && t >= 1 ? Math.round(t) : null); }
        if ('cantidad' in body)       { cSets.push('cantidad = ?');       cArgs.push(_numOrNull(body.cantidad)); }
        if ('colores' in body)        { cSets.push('colores = ?');        cArgs.push(String(body.colores || '').trim()); }
        if ('producto' in body)       { cSets.push('producto = ?');       cArgs.push(String(body.producto || '').trim()); }
        if ('frente' in body)         { cSets.push('frente = ?');         cArgs.push(String(body.frente || '').trim()); }
        if ('laterales' in body)      { cSets.push('laterales = ?');      cArgs.push(String(body.laterales || '').trim()); }
        if ('espalda' in body)        { cSets.push('espalda = ?');        cArgs.push(String(body.espalda || '').trim()); }
        if ('iluminacion' in body)    { cSets.push('iluminacion = ?');    cArgs.push(String(body.iluminacion || '').trim()); }
        if ('bastidor' in body)       { cSets.push('bastidor = ?');       cArgs.push(String(body.bastidor || '').trim()); }
        if ('color_bastidor' in body) { cSets.push('color_bastidor = ?'); cArgs.push(String(body.color_bastidor || '').trim()); }
        if ('instalacion' in body)    { cSets.push('instalacion = ?');    cArgs.push(String(body.instalacion || '').trim()); }
        if (cSets.length) {
          cSets.push('mirror_dirty = 1', 'mirror_attempts = 0', 'mirror_error = NULL', 'updated_at = ?');
          cArgs.push(now, id);
          await env.DB.prepare(`UPDATE pedidos SET ${cSets.join(', ')} WHERE id = ?`).bind(...cArgs).run();
          touched = true;
          // Si cambió algo que ve Emma (nombre/medida/cantidad/colores/base/aclaración), re-sincronizar
          // la pieza de corte de este cartel — solo si todavía no la diseñó (estado 'pedido').
          if (['cartel', 'alto', 'ancho', 'cantidad', 'colores', 'base', 'aclaracion', 'cm_neon'].some(k => k in body)) {
            await syncCortePiezaDesdePedido(env, id);
          }
          // Cambió algo que entra en la mano de obra → recalcularla (no si ya se le pagó al productor).
          if (['precio', 'cantidad', 'alto', 'ancho', 'cm_neon', 'tramos'].some(k => k in body)) { try { await moActualizar(env, [id]); } catch (_) {} }
        }

        // 2) Campos del PEDIDO → UPDATE todas las filas del numero+fecha DEL MISMO VENDEDOR. Recalcula el
        //    restante si cambió el precio (ya aplicado arriba) o el pagado. El N° se repite entre vendedores
        //    (ej. #378 del 22-09: 2 carteles de Joaco + 1 de Agustina): sin el vendedor en el grupo, el pagado
        //    de uno pisaba el de los pedidos del otro y lo espejaba corrupto al Excel.
        let _grp = "numero = ? AND fecha = ? AND IFNULL(comercial_id,'joaco') = ?";
        const _grpArgs = [ref.numero, ref.fecha, ref.com];
        // Pedidos del CRM: además el MISMO CLIENTE (un alta guarda el mismo teléfono en todos sus carteles).
        // El N° de la OC se tipea a mano y se repite dentro de un mismo vendedor (#362, #376, #382): sin esto,
        // marcar 'Entregado' el de un cliente se lo marcaba al otro (y su pieza sin diseñar salía de la cola
        // de Emma). Las filas del Excel/backfill no: ahí el teléfono suele estar solo en la primera fila.
        if (ref.origen === 'crm' && ref.tel) { _grp += " AND origen = 'crm' AND IFNULL(telefono,'') = ?"; _grpArgs.push(ref.tel); }
        // Volver de '2do pago' a otro estado borra el 2do pago registrado (cobro2/caja2/comprobante2) y el saldo vuelve.
        // El paso a '2do pago' lo hace POST /admin/pedidos/:id/segundo-pago (modal con comprobante/importe); el front nuevo
        // no lo manda por acá, el viejo en caché sí (queda como antes: estado sin cobro2).
        // Con un 2do pago REGISTRADO (cobro2) solo se revierte con pago2_revert:true (el front lo manda tras confirmar):
        // un drawer viejo/desactualizado manda estado_pago siempre, con el valor que tenía al abrirse, y borraba el cobro.
        // El '2do pago' solo se registra con el modal (comprobante, caja e importe: POST /segundo-pago). Una app vieja en caché lo mandaba
        // por acá y el pedido quedaba "pagado" sin cobro (Gaspar 17-oct: no se manda nada sin saldar).
        if (('estado_pago' in body) && String(body.estado_pago || '') === '2do pago') {
          const _e2 = await env.DB.prepare(`SELECT IFNULL(estado_pago,'') e FROM pedidos WHERE ${_grp} LIMIT 1`).bind(..._grpArgs).first();
          if (_e2 && _e2.e !== '2do pago') return json({ error: 'El 2do pago se registra con el botón "Registrar 2do pago" (comprobante y caja). Si no lo ves, recargá la app.', campo: 'estado_pago' }, 409);
        }
        if (('estado_pago' in body) && /^cuenta corriente$/i.test(String(body.estado_pago || '').trim()) && _pr !== 'admin') return json({ error: 'La cuenta corriente la pone Gaspar' }, 403);
        let pago2Revert = false, estadoPagoIgnorado = false;
        if (('estado_pago' in body) && String(body.estado_pago || '') !== '2do pago') {
          const _ep = await env.DB.prepare(`SELECT IFNULL(estado_pago,'') e, cobro2 FROM pedidos WHERE ${_grp} LIMIT 1`).bind(..._grpArgs).first();
          if (_ep && _ep.cobro2 != null) { if (body.pago2_revert === true) pago2Revert = true; else estadoPagoIgnorado = true; }
          else pago2Revert = !!_ep && _ep.e === '2do pago';
        }
        const oSets = [], oArgs = [];
        if ('estado_pedido' in body) { oSets.push('estado_pedido = ?'); oArgs.push(String(body.estado_pedido || '')); }
        if (('estado_pago' in body) && !estadoPagoIgnorado) { oSets.push('estado_pago = ?'); oArgs.push(String(body.estado_pago || '')); }
        // Texto libre del productor (corpóreos / pedidos viejos): nunca pisa el nombre de un cartel asignado desde Producción.
        if ('productor' in body)     { oSets.push("productor = CASE WHEN COALESCE(productor_id,'') <> '' THEN productor ELSE ? END"); oArgs.push(String(body.productor || '')); }
        // Pedido "⏳ Sin pago": posponer el cobro (cobrar_el = otra fecha) o dejar de recordarlo (''). Solo admin, todo el
        // pedido. No va al Excel (sin mirror_dirty ni updated_at).
        if ('cobrar_el' in body) {
          if (_pr !== 'admin') return json({ error: 'forbidden: solo Gaspar maneja los cobros pendientes' }, 403);
          const ce = String(body.cobrar_el || '').trim();
          const hoyCe = new Date(Date.now() - 3 * 3600 * 1000).toISOString().slice(0, 10);
          if (ce && !(/^\d{4}-\d{2}-\d{2}$/.test(ce) && !isNaN(Date.parse(ce + 'T12:00:00Z')) && ce >= hoyCe)) return json({ error: 'Fecha de cobro inválida (tiene que ser hoy o más adelante)', campo: 'cobrar_el' }, 400);
          await env.DB.prepare(`UPDATE pedidos SET cobrar_el = ? WHERE ${_grp}`).bind(ce || null, ..._grpArgs).run();
          touched = true;
        }
        // El cobro de un pedido cargado sin pago se registra con "Registrar pago" (caja, comprobante, OC): tipeando
        // Pagado quedaría sin caja ni comprobante y la OC en POR PAGAR.
        if (('pagado' in body) && Number(body.pagado) > 0) {
          const _pp = await env.DB.prepare(`SELECT MAX(IFNULL(pago_metodo,'')) AS pm, MAX(IFNULL(pagado,0)) AS pg FROM pedidos WHERE ${_grp}`).bind(..._grpArgs).first();
          if (_pp && _pp.pm === 'pendiente' && !(Number(_pp.pg) > 0)) return json({ error: 'Este pedido se cargó sin pago: registrá el cobro con "Registrar pago" (así queda la caja y el comprobante)', campo: 'pagado' }, 409);
        }
        const pagadoInBody = ('pagado' in body);
        if (pagadoInBody || precioChanged || pago2Revert) {
          const cur = await env.DB.prepare(`SELECT pagado, cobro2 FROM pedidos WHERE ${_grp} LIMIT 1`).bind(..._grpArgs).first();
          const _sf = await env.DB.prepare(`SELECT CASE WHEN SUM(CASE WHEN IFNULL(origen,'') = 'crm' THEN 0 ELSE 1 END) > 0 AND (MAX(ABS(IFNULL(pagado,0) + IFNULL(restante,0) - IFNULL(precio,0) - IFNULL(precio_dimmer,0))) <= 1 OR MIN(IFNULL(pagado,0)) <> MAX(IFNULL(pagado,0))) THEN 1 ELSE 0 END AS por_fila, SUM(IFNULL(pagado,0)) AS suma FROM pedidos WHERE ${_grp}`).bind(..._grpArgs).first();
          const senaPorFila = !pagadoInBody && _sf && Number(_sf.por_fila) === 1;   // importado del Excel: la seña va repartida por fila
          let pagado;
          if (pagadoInBody) { pagado = (body.pagado === '' || body.pagado == null) ? null : Number(body.pagado); }
          else if (senaPorFila) { pagado = Number(_sf.suma) || 0; }
          else { pagado = (cur && cur.pagado != null) ? Number(cur.pagado) : null; }
          const cobro2 = pago2Revert ? 0 : ((cur && Number(cur.cobro2) > 0) ? Number(cur.cobro2) : 0);
          const tot = await env.DB.prepare(`SELECT COALESCE(SUM(precio),0) + COALESCE(SUM(precio_dimmer),0) AS t FROM pedidos WHERE ${_grp}`).bind(..._grpArgs).first();
          const total = tot ? Number(tot.t) : 0;
          const restante = Math.max(0, total - (pagado != null ? pagado : 0) - cobro2);
          if (senaPorFila) { /* la seña y el saldo de cada fila quedan como estaban (repetir el saldo del pedido en cada fila lo suma N veces) */ }
          else { oSets.push('pagado = ?', 'restante = ?'); oArgs.push(pagado, restante); }
          if (pago2Revert) oSets.push('cobro2 = NULL', 'caja2 = NULL', 'pago2_metodo = NULL', 'comprobante2_key = NULL', 'comprobante2_wamid = NULL', 'cobro2_at = NULL');
        }
        if (pSets.length) {
          await env.DB.prepare(`UPDATE pedidos SET ${pSets.join(', ')} WHERE ${_grp}`).bind(...pArgs, ..._grpArgs).run();
          touched = true;
        }
        let _estPrev = null;
        if ('estado_pedido' in body) { try { const _e = await env.DB.prepare(`SELECT IFNULL(estado_pedido, '') e FROM pedidos WHERE ${_grp} LIMIT 1`).bind(..._grpArgs).first(); _estPrev = _e ? _e.e : ''; } catch (_) {} }
        if (oSets.length) {
          oSets.push('mirror_dirty = 1', 'mirror_attempts = 0', 'mirror_error = NULL', 'updated_at = ?');
          oArgs.push(now, ..._grpArgs);
          await env.DB.prepare(`UPDATE pedidos SET ${oSets.join(', ')} WHERE ${_grp}`).bind(...oArgs).run();
          touched = true;
        }
        // Historial de estados (mig. 049): los estados de producción no se mantenían y no quedaba quién ni cuándo los
        // cambió; con esto el panel puede volver a contarlos cuando haya datos confiables.
        if (_estPrev != null && _estPrev !== String(body.estado_pedido || '')) {
          try { await env.DB.prepare("INSERT INTO pedido_estado_log (pedido_id, numero, fecha, comercial_id, telefono, de, a, por, ts) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)").bind(id, ref.numero, ref.fecha, ref.com, ref.tel, _estPrev, String(body.estado_pedido || ''), String(session.user || ''), now).run(); } catch (_) {}
        }
        // "La cerró el equipo" (solo Gaspar): todo el pedido; no va al Excel (no marca mirror_dirty).
        if ('asistido_por' in body) {
          if (sessionUserKey !== 'gaspar') return json({ error: 'forbidden: solo Gaspar marca ventas del equipo' }, 403);
          const _as = String(body.asistido_por || '').trim().toLowerCase();
          if (!['', 'bruno', 'equipo'].includes(_as)) return json({ error: 'asistido_por inválido' }, 400);
          await env.DB.prepare(`UPDATE pedidos SET asistido_por = ? WHERE ${_grp}`).bind(_as, ..._grpArgs).run();
          try { await env.DB.prepare("DELETE FROM kv_cache WHERE k LIKE 'kpi_mes:%' OR k LIKE 'kpi_sem:%'").run(); } catch (_) {} // que se vea ya en el panel
          touched = true;
        }

        if (!touched && estadoPagoIgnorado) return json({ error: 'Ese pedido ya tiene registrado el 2do pago. Recargá la app para volverlo a 1er pago.' }, 409);
        if (!touched) return json({ error: 'nada para actualizar' }, 400);
        const rs2 = { results: await pedidosConDiseno(env, 'WHERE ' + _grp.replace(/\b(numero|fecha|comercial_id|origen|telefono)\b/g, 'pedidos.$1') + ' ORDER BY pedidos.id', _grpArgs, { interno: _pr === 'admin', fotos: true }) };
        return json({ ok: true, numero: ref.numero, pedidos: rs2.results || [] });
      }

      // POST /admin/pedidos/:id/segundo-pago → registra el 2do pago (el saldo) de TODO el pedido (mismo grupo que el PATCH).
      // Body { pago_metodo:'transferencia'|'efectivo', caja, importe, comprobante_key, comprobante_wamid }.
      // Transferencia exige comprobante; efectivo ⇒ caja 'Efectivo' + importe. No toca `pagado` (COBRO 1 en la planilla;
      // COBRO 2 allá es fórmula = total − COBRO 1): el 2do pago queda en cobro2/caja2/comprobante2 y el estado pasa a
      // '2do pago' (eso sí va al Excel). La col Z sigue con la caja de la SEÑA (decisión de Gaspar 15-oct): si el saldo
      // entró a otra caja, se avisa en la respuesta y por WhatsApp a Gaspar para que lo vea en la conciliación.
      if (request.method === 'POST' && /^\/admin\/pedidos\/\d+\/segundo-pago$/.test(path)) {
        const _pr = await getSessionRole(env, session.user);
        if (!['admin', 'comercial'].includes(_pr)) return json({ error: 'forbidden' }, 403);
        await ensurePedidosSchema(env);
        const id = parseInt(path.split('/')[3], 10);
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const ref = await env.DB.prepare("SELECT numero, fecha, IFNULL(comercial_id,'joaco') AS com, origen, IFNULL(telefono,'') AS tel, IFNULL(cartel,'') AS cartel FROM pedidos WHERE id = ?").bind(id).first();
        if (!ref) return json({ error: 'pedido no encontrado' }, 404);
        if (_pr === 'comercial' && ref.com !== await resolveComercial(env, { sessionUser: session.user })) return json({ error: 'ese pedido es de otro vendedor' }, 403);
        let metodo = String(body.pago_metodo || '').toLowerCase() === 'efectivo' ? 'efectivo' : 'transferencia';
        let caja = cajaCanon(body.caja);
        if (metodo === 'efectivo') caja = 'Efectivo';
        else if (caja === 'Efectivo') metodo = 'efectivo';
        if (!caja) return json({ error: 'Falta a qué caja pagó', campo: 'caja' }, 400);
        const importe = Math.round(Number(body.importe) * 100) / 100;
        if (!(importe > 0)) return json({ error: 'Falta el importe del 2do pago', campo: 'importe' }, 400);
        const compKey = (metodo !== 'efectivo' && esKeyComprobantePedido(body.comprobante_key)) ? String(body.comprobante_key) : '';
        if (metodo !== 'efectivo') {
          if (!compKey) return json({ error: 'Falta el comprobante del 2do pago', campo: 'comprobante' }, 400);
          let _existe = null; try { _existe = env.MEDIA ? await env.MEDIA.head(compKey) : true; } catch (_) { _existe = true; }
          if (!_existe) return json({ error: 'No encuentro ese comprobante: subilo de nuevo', campo: 'comprobante' }, 400);
        }
        const compWamid = compKey ? (String(body.comprobante_wamid || '').slice(0, 200) || null) : null;
        let _grp = "numero = ? AND fecha = ? AND IFNULL(comercial_id,'joaco') = ?";
        const _grpArgs = [ref.numero, ref.fecha, ref.com];
        if (ref.origen === 'crm' && ref.tel) { _grp += " AND origen = 'crm' AND IFNULL(telefono,'') = ?"; _grpArgs.push(ref.tel); }
        const g = await env.DB.prepare(`SELECT COALESCE(SUM(precio),0) + COALESCE(SUM(precio_dimmer),0) AS t, MAX(pagado) AS pagado, CASE WHEN SUM(CASE WHEN IFNULL(origen,'') = 'crm' THEN 0 ELSE 1 END) = 0 THEN MAX(IFNULL(pagado,0)) WHEN MAX(ABS(IFNULL(pagado,0) + IFNULL(restante,0) - IFNULL(precio,0) - IFNULL(precio_dimmer,0))) <= 1 OR MIN(IFNULL(pagado,0)) <> MAX(IFNULL(pagado,0)) THEN SUM(IFNULL(pagado,0)) ELSE MAX(IFNULL(pagado,0)) END AS sena, CASE WHEN SUM(CASE WHEN IFNULL(origen,'') = 'crm' THEN 0 ELSE 1 END) > 0 AND (MAX(ABS(IFNULL(pagado,0) + IFNULL(restante,0) - IFNULL(precio,0) - IFNULL(precio_dimmer,0))) <= 1 OR MIN(IFNULL(pagado,0)) <> MAX(IFNULL(pagado,0))) THEN 1 ELSE 0 END AS por_fila, MIN(id) AS min_id, MAX(CASE WHEN lower(IFNULL(estado_pago,'')) = 'cuenta corriente' THEN 1 ELSE 0 END) AS cc, MAX(IFNULL(caja,'')) AS caja, MAX(cobro2) AS cobro2, MAX(IFNULL(comprobante_key,'')) AS ck1, MAX(IFNULL(pago_metodo,'')) AS pm FROM pedidos WHERE ${_grp}`).bind(..._grpArgs).first();
        // Cuenta corriente (Sin Frontera): se cobra en su Excel, acá no se registra (pasarlo a '1er pago' lo trababa en el tablero).
        if (g && Number(g.cc) === 1) return json({ error: 'Es cuenta corriente (Sin Frontera): se cobra en su Excel, no acá' }, 409);
        // Pedido cargado SIN PAGO (pago_metodo 'pendiente', sin seña): este pago es el 1er COBRO, no un saldo. Va a pagado
        // (COBRO 1 en la planilla), la caja a la col Z (syncCajaPedidos) y el comprobante como el de la seña; si cubre
        // el total queda '2do pago' (pagó todo), si no '1er pago' con lo que falte. Corta el recordatorio de cobro solo.
        // Reintento del front (se cortó la respuesta y el pago ya había entrado como 1er cobro): no se registra de nuevo.
        if (body.primer_cobro === true && g && g.pm !== 'pendiente') {
          if (Math.abs((Number(g.pagado) || 0) - importe) <= 1 && g.cobro2 == null) {
            const rsI = { results: await pedidosConDiseno(env, 'WHERE ' + _grp.replace(/\b(numero|fecha|comercial_id|origen|telefono)\b/g, 'pedidos.$1') + ' ORDER BY pedidos.id', _grpArgs, { interno: _pr === 'admin', fotos: true }) };
            return json({ ok: true, numero: ref.numero, pedidos: rsI.results || [], avisos: ['Ese pago ya estaba registrado'], primer_cobro: true });
          }
          return json({ error: 'Ese pedido ya tiene un pago registrado: recargá la lista' }, 409);
        }
        if (g && g.pm === 'pendiente' && !(Number(g.pagado) > 0) && g.cobro2 == null) {
          const totalSp = Number(g.t) || 0;
          const restSp = Math.max(0, totalSp - importe);
          const estadoSp = restSp <= 1 ? '2do pago' : '1er pago';
          const nowSp = new Date().toISOString();
          let usadoSp = null;
          if (compKey) { try { usadoSp = await env.DB.prepare(`SELECT numero, cartel FROM pedidos WHERE (comprobante_key = ? OR comprobante2_key = ?) AND NOT (${_grp}) LIMIT 1`).bind(compKey, compKey, ..._grpArgs).first(); } catch (_) {} }
          // Condicional: dos clics / un reintento a la vez no lo registran dos veces.
          const upSp = await env.DB.prepare(`UPDATE pedidos SET estado_pago = ?, pagado = ?, restante = ?, caja = ?, pago_metodo = ?, comprobante_key = ?, comprobante_wamid = ?, caja_sync_attempts = 0, caja_sync_err = NULL, mirror_dirty = 1, mirror_attempts = 0, mirror_error = NULL, updated_at = ? WHERE ${_grp} AND pago_metodo = 'pendiente' AND IFNULL(pagado,0) = 0`)
            .bind(estadoSp, importe, restSp, caja, metodo, compKey || null, compWamid, nowSp, ..._grpArgs).run();
          if (!(upSp && upSp.meta && upSp.meta.changes > 0)) return json({ error: 'Ese pedido ya tiene un pago registrado: recargá la lista' }, 409);
          // La plata entró: la OC del chat deja de estar POR PAGAR (al cargarlo sin pago se había dejado abierta a propósito).
          try { const igSp = /^@|[a-z_.]/i.test(ref.tel) ? await igsidDeUsuario(env, ref.tel) : ''; await ocCerrarPorPedido(env, [ref.tel, igSp], estadoSp); } catch (_) {}
          const fmSp = (n) => '$' + Math.round(n).toLocaleString('es-AR');
          const avisosSp = [restSp > 1 ? 'Pago registrado (el pedido se había cargado sin pago)' : 'Pago registrado: ya no te recuerdo cobrarlo'];
          if (restSp > 1) avisosSp.push(`Queda debiendo ${fmSp(restSp)}${_pr === 'admin' ? ': te sigo recordando por el saldo' : ''}`);
          else if (importe > totalSp + 1) avisosSp.push(`Pagó ${fmSp(importe - totalSp)} de más`);
          if (usadoSp) avisosSp.push(`Ojo: ese comprobante también está cargado en el pedido #${usadoSp.numero}${usadoSp.cartel ? ' (' + String(usadoSp.cartel).slice(0, 40) + ')' : ''}`);
          const rsSp = { results: await pedidosConDiseno(env, 'WHERE ' + _grp.replace(/\b(numero|fecha|comercial_id|origen|telefono)\b/g, 'pedidos.$1') + ' ORDER BY pedidos.id', _grpArgs, { interno: _pr === 'admin', fotos: true }) };
          return json({ ok: true, numero: ref.numero, pedidos: rsSp.results || [], avisos: avisosSp, primer_cobro: true });
        }
        // El comprobante de la seña no puede ser también el del saldo (el caso típico de "Usar como comprobante" sobre la
        // foto equivocada). Si ese archivo ya es comprobante de OTRO pedido, se registra igual pero se avisa.
        if (compKey && g && g.ck1 === compKey) return json({ error: 'Ese comprobante es el de la seña de este pedido: elegí el del saldo', campo: 'comprobante' }, 400);
        let _usadoEn = null;
        if (compKey) { try { _usadoEn = await env.DB.prepare(`SELECT numero, cartel FROM pedidos WHERE (comprobante_key = ? OR comprobante2_key = ?) AND NOT (${_grp}) LIMIT 1`).bind(compKey, compKey, ..._grpArgs).first(); } catch (_) {} }
        const total = g ? Number(g.t) || 0 : 0;
        // Seña del pedido entero: en los del CRM se repite en cada fila (MAX); en los importados del Excel va repartida por fila (SUM).
        const pagado1 = g && g.sena != null ? Number(g.sena) || 0 : 0;
        const saldo = Math.max(0, total - pagado1);
        const restante = Math.max(0, total - pagado1 - importe);
        // Si no salda, queda '1er pago' (con lo cobrado en cobro2): no sale del taller y se le sigue recordando el cobro. El importe es
        // TODO lo cobrado del saldo (si ya había un pago parcial, este lo reemplaza: el modal propone el saldo entero).
        const estadoPago = restante <= 1 ? '2do pago' : '1er pago';
        const now = new Date().toISOString();
        // Importado del Excel (seña por fila): el saldo va en UNA fila (repetido en cada una, el Dashboard lo sumaba N veces).
        // IFNULL(cobro2,-1) = lo leído: dos registros a la vez no se pisan sin aviso.
        const porFila = !!g && Number(g.por_fila) === 1;
        const up2 = await env.DB.prepare(`UPDATE pedidos SET estado_pago = ?, cobro2 = ?, caja2 = ?, pago2_metodo = ?, comprobante2_key = ?, comprobante2_wamid = ?, cobro2_at = ?, restante = CASE WHEN ? = 0 OR id = ? THEN ? ELSE 0 END, mirror_dirty = 1, mirror_attempts = 0, mirror_error = NULL, updated_at = ? WHERE ${_grp} AND IFNULL(cobro2, -1) = ?`)
          .bind(estadoPago, importe, caja, metodo, compKey || null, compWamid, now, porFila ? 1 : 0, g ? Number(g.min_id) || 0 : 0, restante, now, ..._grpArgs, (g && g.cobro2 != null) ? Number(g.cobro2) : -1).run();
        if (!(up2 && up2.meta && up2.meta.changes > 0)) return json({ error: 'Recién se registró otro pago de este pedido: recargá la lista y fijate antes de cargarlo de nuevo' }, 409);
        const fm = (n) => '$' + Math.round(n).toLocaleString('es-AR');
        const avisos = [];
        const caja1 = String((g && g.caja) || '');
        if (g && g.cobro2 != null) avisos.push(`Ya había un pago del saldo de ${fm(Number(g.cobro2))}: quedó el que cargaste ahora como TODO lo cobrado del saldo (reemplaza, no suma)`);
        if (caja1 && caja1 !== caja) avisos.push(`La seña fue a ${caja1} y el saldo a ${caja}: en la planilla queda ${caja1}`);
        if (!caja1) avisos.push('Este pedido no tiene cargada la caja de la seña');
        if (_usadoEn) avisos.push(`Ojo: ese comprobante también está cargado en el pedido #${_usadoEn.numero}${_usadoEn.cartel ? ' (' + String(_usadoEn.cartel).slice(0, 40) + ')' : ''}`);
        if (importe < saldo - 1) avisos.push(`Queda debiendo ${fm(saldo - importe)}: sigue en 1er pago y no se puede mandar hasta que pague todo`);
        else if (importe > saldo + 1) avisos.push(`Pagó ${fm(importe - saldo)} de más`);
        if (caja1 && caja1 !== caja) {
          const txt = `💳 2do pago con otra caja: #${ref.numero} ${String(ref.cartel || '').slice(0, 40)} · seña a ${caja1}, saldo ${fm(importe)} a ${caja} (cargó ${session.user}). En la planilla (col Z) queda ${caja1}.`;
          ctx.waitUntil(avisoInterno(env, { para: 'gaspar', tipo: 'pago2_caja', prioridad: 'P3', clave: 'pago2_caja:' + id + ':' + caja + ':' + importe, texto: txt,
            legacy: () => avisoLanzamientoSendLegacy(env, AVISO_SLUGS_FIJOS.gaspar, txt), legacyDest: AVISO_SLUGS_FIJOS.gaspar }).catch(() => {}));
        }
        const rs3 = { results: await pedidosConDiseno(env, 'WHERE ' + _grp.replace(/\b(numero|fecha|comercial_id|origen|telefono)\b/g, 'pedidos.$1') + ' ORDER BY pedidos.id', _grpArgs, { interno: _pr === 'admin', fotos: true }) };
        return json({ ok: true, numero: ref.numero, pedidos: rs3.results || [], avisos });
      }

      // POST /admin/pedidos/sync-productores → trae el productor del Excel a D1
      // (solo ese campo, por sheet_row). On-demand; también corre solo en el cron.
      if (request.method === 'POST' && path === '/admin/pedidos/sync-productores') {
        await ensurePedidosSchema(env);
        const changed = await syncProductoresFromVentas(env);
        return json({ ok: true, changed });
      }

      // POST /admin/pedidos/import-excel → importa al CRM los pedidos nuevos cargados a
      // mano en el Excel (sync Excel → CRM, on-demand; también corre solo en el cron).
      if (request.method === 'POST' && path === '/admin/pedidos/import-excel') {
        await ensurePedidosSchema(env);
        const imported = await importNewPedidosFromVentas(env);
        return json({ ok: true, imported });
      }

      // POST /admin/pedidos/mirror-resync → marca los pedidos creados en el CRM
      // (origen='crm') como mirror_dirty para que el cron los empuje al Excel.
      // Sirve para el primer push tras activar el espejo, o para forzar re-sync.
      if (request.method === 'POST' && path === '/admin/pedidos/mirror-resync') {
        await ensurePedidosSchema(env);
        const res = await env.DB.prepare("UPDATE pedidos SET mirror_dirty = 1, mirror_attempts = 0, mirror_error = NULL WHERE origen = 'crm'").run();
        return json({ ok: true, marcados: (res.meta && res.meta.changes) || 0 });
      }

      // POST /admin/pedidos/mirror-run → fuerza una corrida del espejo ahora mismo
      // (sin esperar el cron) y devuelve el diagnóstico { checked, pushed } o { error }.
      if (request.method === 'POST' && path === '/admin/pedidos/mirror-run') {
        await ensurePedidosSchema(env);
        const result = await processPedidosMirror(env);
        return json({ ok: true, result });
      }

      // POST /admin/pedidos/trace-ads → traza los pedidos sin ad (cliente -> atribución real)
      // y sincroniza la columna Ad del Excel (match por nombre). Corre solo por cron; esto
      // lo fuerza a mano. Idempotente (solo toca pedidos sin ad y celdas U vacías).
      if (request.method === 'POST' && path === '/admin/pedidos/trace-ads') {
        const r = await traceUntaggedPedidos(env);
        const sync = await syncAdColumnToExcel(env);
        return json({ ok: true, trazados: r.n, scanned: r.scanned, sync });
      }

      // POST /admin/pedidos/trace-backfill?limit=N → barre TODO el histórico de pedidos sin ad
      // (sin límite de 120 días) y los traza (WPP por teléfono, IG por IGSID vía la OC del chat).
      // Batched en varias pasadas dentro del mismo request. Idempotente. Solo Gaspar.
      if (request.method === 'POST' && path === '/admin/pedidos/trace-backfill') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        await ensurePedidosSchema(env);
        const batch = Math.max(1, Math.min(parseInt(url.searchParams.get('limit') || '60'), 120));
        let trazados = 0, scanned = 0, iters = 0;
        // Varias pasadas: cada una toma los primeros `batch` sin ad. Los que se trazan salen del
        // conjunto (ya tienen ad); los que no, quedan pero no frenan (scanned avanza). Cortamos
        // cuando una pasada no traza NADA nuevo (todo lo restante es no-trazable) o a las 10 pasadas.
        while (iters < 10) {
          const r = await traceUntaggedPedidos(env, { allDates: true, limit: batch });
          trazados += r.n; scanned += r.scanned; iters++;
          if (r.n === 0) break; // nada nuevo trazado → el resto no se puede trazar, cortar
        }
        const sync = await syncAdColumnToExcel(env);
        return json({ ok: true, trazados, iters, sync });
      }

      // POST /admin/pedidos/backfill-source → guarda el ad_id EXACTO (source_id/source_campaign) en
      // los pedidos ya trazados que no lo tienen. SEGURO: no cambia labels ni toca los marcados a
      // mano como orgánicos. Batched en un solo request. Solo Gaspar. Idempotente.
      // GET /admin/sin-responder/preview → qué avisaría AHORA la alarma "sin responder" (sin mandar nada): candidatos,
      // si el cliente espera respuesta (IA, cacheada por mensaje), urgencia, motivo y si ya se avisó. Solo Gaspar.
      // GET /admin/cobros/pendientes → pedidos cargados SIN PAGO que hay que cobrar (con el texto del recordatorio).
      // POST /admin/cobros/recordatorio-prueba?id=N → manda YA el recordatorio de ese pedido (o de todos) a Gaspar. Solo Gaspar.
      if (path === '/admin/cobros/pendientes' && request.method === 'GET') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        return json(await processCobrosPendientes(env, { soloListar: true }));
      }
      if (path === '/admin/cobros/recordatorio-prueba' && request.method === 'POST') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        const _cid = parseInt(url.searchParams.get('id') || '0', 10) || 0;
        return json(await processCobrosPendientes(env, { forzar: true, id: _cid || null }));
      }

      // GET /admin/corte/aviso-stats → números del aviso del sitio del corte (enviados, respondieron, visitas, quiénes
      // pusieron su número, pedidos). Solo Gaspar.
      if (request.method === 'GET' && path === '/admin/corte/aviso-stats') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        const st = await corteWebStats(env);
        return json(st.ok ? { ...st, texto: corteWebStatsTexto(st) } : st);
      }
      if (request.method === 'GET' && path === '/admin/sin-responder/preview') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        const items = await sinRespCandidatos(env, Date.now(), { clasificarMax: Math.min(60, parseInt(url.searchParams.get('ia') || '40', 10) || 40) });
        return json({ ok: true, on: (await kvGet(env, 'sin_responder_on', '1')) === '1', horas: parseInt(await kvGet(env, 'sin_responder_horas', '3'), 10) || 3, alertaria: items.filter(x => x.alertar).length, items });
      }

      // POST /admin/pedidos/caja-sync[?id=N] → corre YA el pase de la caja de la seña a la col Z (Pedidos_Corporeo /
      // Pedidos_Directo) y devuelve el detalle (escritos / iguales / cargados a mano / sin fila). Solo Gaspar.
      // ?reintentar=1 vuelve a intentar los que quedaron sin fila o "manual" (resetea los intentos).
      if (request.method === 'POST' && path === '/admin/pedidos/caja-sync') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        await ensurePedidosSchema(env);
        const _id = parseInt(url.searchParams.get('id') || '0', 10);
        if (url.searchParams.get('reintentar') === '1') {
          await env.DB.prepare("UPDATE pedidos SET caja_sync_attempts = 0 WHERE origen = 'crm' AND IFNULL(caja,'') <> '' AND IFNULL(caja_sync,'') <> caja" + (_id > 0 ? ' AND id = ?' : '')).bind(...(_id > 0 ? [_id] : [])).run();
        }
        return json({ ok: true, ...(await syncCajaPedidos(env, _id > 0 ? { ids: [_id] } : {})) });
      }

      // POST /admin/pedidos/vendedor-sync → corre YA el barrido del vendedor de los pedidos de neón al 2026 v4
      // (Pedidos_Directo col C) y devuelve el detalle (escritos / iguales / cargados a mano / errores). Solo Gaspar.
      // Con {forzar:[{id, prev}]} corrige celdas que ya tienen un vendedor (decisión de Gaspar): manda el
      // vendedor del CRM con prev = lo que hoy dice la planilla, así el Apps Script lo reemplaza.
      if (request.method === 'POST' && path === '/admin/pedidos/vendedor-sync') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        const body = await request.json().catch(() => ({}));
        const forzar = Array.isArray(body.forzar) ? body.forzar.slice(0, 50) : [];
        if (forzar.length) {
          const items = [], skip = [];
          for (const f of forzar) {
            const p = await env.DB.prepare('SELECT id, numero, cartel, fecha, sheet_row, es_corporeo, comercial_id, cargado_por FROM pedidos WHERE id = ?').bind(parseInt(f.id, 10) || 0).first();
            const vend = p ? pedidoVendedorNeon(p) : '';
            if (!p || p.es_corporeo || !(p.sheet_row > 1) || String(p.fecha || '') < VEND_NEON_DESDE || !vend) { skip.push(f.id); continue; }
            items.push({ id: p.id, row: p.sheet_row, numero: p.numero, cartel: p.cartel, vend, prev: String(f.prev || '').toLowerCase().trim() });
          }
          return json({ ok: true, forzados: await enviarVendedoresNeon(env, items), skip });
        }
        return json({ ok: true, ...(await barrerVendedoresNeon(env)) });
      }

      if (request.method === 'POST' && path === '/admin/pedidos/backfill-source') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        await ensurePedidosSchema(env);
        let done = 0, withSource = 0, iters = 0;
        while (iters < 12) {
          const r = await backfillPedidoSources(env, 60);
          done += r.done; withSource += r.withsrc; iters++;
          if (r.done < 60) break;
        }
        return json({ ok: true, done, with_source: withSource, iters });
      }

      // GET /admin/ads/funnel?since=&until=&rate= → funnel de carteles por campaña de Meta (panel de control).
      // Cruza el gasto de Meta con leads/presupuestos/ventas de D1, por campaña, anuncio y vendedor. Solo Gaspar.
      if (request.method === 'GET' && path === '/admin/ads/funnel') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        const today = new Date(Date.now() - 3 * 3600 * 1000).toISOString().slice(0, 10);
        const fecha = (v, def) => /^\d{4}-\d{2}-\d{2}$/.test(String(v || '')) ? String(v) : def;
        const since = fecha(url.searchParams.get('since'), today.slice(0, 7) + '-01');
        const until = fecha(url.searchParams.get('until'), today);
        const rate = parseFloat(url.searchParams.get('rate') || '') || 1400;
        const data = await buildAdsFunnel(env, { since, until, rate });
        return json(data);
      }

      // GET /admin/kpis-vendedor?mes=YYYY-MM[&vendedor=slug] → panel de rendimiento. Un vendedor (Joaco/Facu/Agus)
      // recibe SOLO lo suyo (el filtro es acá, no en el front). Gaspar: sin vendedor = comparación de los 3 (montos
      // sin el +5% oculto); con vendedor = el panel de ese vendedor tal cual lo ve él. Nunca comisiones ni sueldos.
      if (request.method === 'GET' && path === '/admin/kpis-vendedor') {
        const esGaspar = sessionUserKey === 'gaspar';
        let slug = '';
        if (!esGaspar) { slug = adhocSenderSlug(session.user); if (!slug) return json({ error: 'forbidden' }, 403); }
        else { const v = funnelVendedor(url.searchParams.get('vendedor') || ''); if (KPI_VENDEDORES.some(x => x.slug === v)) slug = v; }
        if (slug && !KPI_VENDEDORES.some(x => x.slug === slug)) return json({ error: 'forbidden' }, 403); // vendedor nuevo sin panel todavía
        const m = String(url.searchParams.get('mes') || '');
        const mes = /^\d{4}-(0[1-9]|1[0-2])$/.test(m) && m <= kpiMesAR() ? m : kpiMesAR();
        const data = await buildKpisVendedor(env, { mes, slug });
        return json({ ok: true, ...data });
      }
      // POST /admin/kpis-vendedor/meta {slug, mes, monto} → meta de plata del mes (solo Gaspar). Rige para ese mes y
      // para los siguientes que no tengan una propia (kpiMeta toma la última ≤ mes), nunca para los anteriores.
      if (request.method === 'POST' && path === '/admin/kpis-vendedor/meta') {
        if (sessionUserKey !== 'gaspar') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const slug = funnelVendedor(body?.slug || '');
        if (!KPI_VENDEDORES.some(x => x.slug === slug)) return json({ error: 'vendedor inválido' }, 400);
        const mes = /^\d{4}-(0[1-9]|1[0-2])$/.test(String(body?.mes || '')) ? String(body.mes) : kpiMesAR();
        const monto = Math.max(0, Math.round(Number(body?.monto) || 0));
        await kvSet(env, `meta_plata:${slug}:${mes}`, String(monto));
        return json({ ok: true, slug, mes, monto });
      }

      // POST /admin/ads/spend-sync {since,until} → trae el gasto de Meta Ads a meta_ad_spend. Solo Gaspar.
      if (request.method === 'POST' && path === '/admin/ads/spend-sync') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        let b = {}; try { b = await request.json(); } catch (_) {}
        const res = await syncMetaAdSpend(env, { since: b.since, until: b.until });
        return json(res, res.ok ? 200 : 502);
      }

      // POST /admin/ads/campaign-vertical {campaign_id, vertical:'carteles'|'cursos'|''} → cómo cuenta una campaña
      // en el funnel (pisa la clasificación automática por nombre); '' vuelve a automático. Solo Gaspar.
      if (request.method === 'POST' && path === '/admin/ads/campaign-vertical') {
        if (session.user !== 'Gaspar') return json({ error: 'forbidden' }, 403);
        let b = {}; try { b = await request.json(); } catch (_) {}
        const cid = String(b.campaign_id || '').replace(/[^\d]/g, '');
        const v = String(b.vertical || '');
        if (!cid || ['carteles', 'cursos', ''].indexOf(v) < 0) return json({ error: 'bad_request' }, 400);
        await ensureMetaSpendSchema(env);
        if (v) await env.DB.prepare("INSERT INTO meta_campaign_vertical (campaign_id, vertical, by_user, updated_at) VALUES (?,?,?,?) ON CONFLICT(campaign_id) DO UPDATE SET vertical=excluded.vertical, by_user=excluded.by_user, updated_at=excluded.updated_at").bind(cid, v, session.user, new Date().toISOString()).run();
        else await env.DB.prepare("DELETE FROM meta_campaign_vertical WHERE campaign_id = ?").bind(cid).run();
        return json({ ok: true, campaign_id: cid, vertical: v });
      }

      // GET /admin/pedidos/mirror-debug → testea el path POST worker→Apps Script con un
      // pedido_ping (NO escribe nada) y reporta si llegó al doPost. Diagnóstico.
      if (request.method === 'GET' && path === '/admin/pedidos/mirror-debug') {
        if (!env.APPS_SCRIPT_URL) return json({ error: 'no APPS_SCRIPT_URL' });
        try {
          const j = await appsScriptPost(env, { action: 'pedido_ping' });
          return json({ ok: true, reached: !!(j && j.pong), response: j });
        } catch (e) {
          return json({ error: String((e && e.message) || e) });
        }
      }

      // GET /admin/pedidos/mirror-failures → lista los pedidos que la red de seguridad
      // marcó con error de espejo (mirror_error no nulo). Para revisarlos y corregirlos.
      if (request.method === 'GET' && path === '/admin/pedidos/mirror-failures') {
        await ensurePedidosSchema(env);
        const rs = await env.DB.prepare("SELECT id, numero, fecha, cartel, estado_pedido, estado_pago, mirror_attempts, mirror_error FROM pedidos WHERE mirror_error IS NOT NULL ORDER BY id").all();
        return json({ ok: true, fallos: rs.results || [] });
      }

      // ============================================================
      // Briefs (panel de cotización conversacional)
      // ============================================================

      // GET /admin/briefs?estado=&comercial_id=&disenador_id=&limit=
      // Incluye:
      //   - first_chat_key + chat_count (capturas del chat — para thumb del kanban)
      //   - first_render_key + render_count (renders del diseñador)
      if (request.method === 'GET' && path === '/admin/briefs') {
        const estado = url.searchParams.get('estado');
        let comercialId = url.searchParams.get('comercial_id');
        const disenadorId = url.searchParams.get('disenador_id');
        // Enforcement por rol: un COMERCIAL (Joaco/Nadia) SOLO ve SUS propios briefs — no puede
        // ver los del otro ni tocando la API a mano. Admin (Gaspar) y diseñador (Emma) ven TODOS.
        const _briefRole = await getSessionRole(env, session.user);
        if (_briefRole === 'comercial') comercialId = await resolveComercial(env, { sessionUser: session.user });
        if (_briefRole === 'disenador') comercialId = null;   // Emma no filtra por vendedor (no sabe de quién es cada brief)
        const limit = Math.min(parseInt(url.searchParams.get('limit') || '500'), 2000);
        const where = [];
        const args = [];
        // GUARD anti "brief sin foto": Emma (diseñador) NO ve briefs SIN NINGUNA imagen — cuando la
        // subida de la foto de Joaco falla (hipo de red), el brief queda sin la referencia y no sirve
        // para cotizar. Se oculta de la cola de Emma pero SIGUE visible para Joaco (comercial), que lo
        // abre y le sube la foto → recién ahí (chat_count > 0) aparece para Emma. Admin (Gaspar) ve todo.
        if (_briefRole === 'disenador') where.push("EXISTS (SELECT 1 FROM brief_imagenes bi WHERE bi.brief_id = b.id)");
        if (estado)      { where.push('b.estado = ?');       args.push(estado); }
        if (comercialId) { where.push('b.comercial_id = ?'); args.push(comercialId); }
        if (disenadorId) { where.push('b.disenador_id = ?'); args.push(disenadorId); }
        // Filtro por teléfono (wa_id): lo usa "Cargar pedido" desde la OC del chat para traer
        // el brief del cliente y auto-completar cm de neón / tramos. cliente_wa_id se guarda como
        // dígitos (== wa_id del chat), pero por las dudas comparamos también contra la versión
        // normalizada por si algún brief viejo quedó con '+' o espacios.
        const phoneQ = (url.searchParams.get('phone') || '').replace(/\D/g, '');
        // wa_id completo (54…) → igualdad. Tipeado corto en "Cargar pedido" (ej. 1164791648, sin el 549) → por
        // los últimos 8 dígitos (mismo criterio que la conciliación de pagos por teléfono).
        if (phoneQ && (phoneQ.startsWith('54') || phoneQ.length < 8)) { where.push("REPLACE(REPLACE(REPLACE(b.cliente_wa_id,'+',''),' ',''),'-','') = ?"); args.push(phoneQ); }
        else if (phoneQ) { where.push("substr(REPLACE(REPLACE(REPLACE(b.cliente_wa_id,'+',''),' ',''),'-',''), -8) = ?"); args.push(phoneQ.slice(-8)); }
        // Filtro por NOMBRE del diseño/cartel: lo usa "Cargar pedido" para matchear el brief
        // cuando NO hay teléfono WA (pedidos por Instagram) o el brief quedó sin cliente_wa_id.
        // Match EXACTO normalizado (lower/trim) contra cliente_nombre o diseno para no traer
        // falsos positivos por substring (ej. "chicle" no debe matchear "La bichicleta").
        // Sin espacios ni puntuación: "CREO en Jose C. Paz" (pedido) = "Creo en Jose C Paz" (brief). Sigue siendo
        // igualdad, no substring.
        const nombreQ = nombreAplastado(url.searchParams.get('nombre'));
        if (nombreQ) { where.push(`(${sqlNombreAplastado('b.cliente_nombre')} = ? OR ${sqlNombreAplastado("COALESCE(b.diseno,'')")} = ?)`); args.push(nombreQ, nombreQ); }
        const sql = `
          SELECT b.*,
                 (SELECT r2_key FROM brief_imagenes WHERE brief_id = b.id AND tipo = 'chat'   ORDER BY orden, id LIMIT 1) AS first_chat_key,
                 (SELECT COUNT(*)  FROM brief_imagenes WHERE brief_id = b.id AND tipo = 'chat')                            AS chat_count,
                 (SELECT r2_key FROM brief_imagenes WHERE brief_id = b.id AND tipo = 'render' ORDER BY orden, id LIMIT 1) AS first_render_key,
                 (SELECT COUNT(*)  FROM brief_imagenes WHERE brief_id = b.id AND tipo = 'render')                          AS render_count
          FROM briefs b
          ${where.length ? 'WHERE ' + where.join(' AND ') : ''}
          ORDER BY b.updated_at DESC
          LIMIT ?
        `;
        args.push(limit);
        const rs = await env.DB.prepare(sql).bind(...args).all();
        return json({ briefs: _briefRole === 'disenador' ? (rs.results || []).map(briefSinVendedor) : (rs.results || []) });
      }

      // GET /admin/briefs/:id  →  detalle + hilo interno + imágenes
      if (request.method === 'GET' && /^\/admin\/briefs\/\d+$/.test(path)) {
        const id = path.split('/').pop();
        const brief = await env.DB.prepare('SELECT * FROM briefs WHERE id = ?').bind(id).first();
        if (!brief) return json({ error: 'not found' }, 404);
        const msgs = await env.DB.prepare(
          'SELECT * FROM brief_messages WHERE brief_id = ? ORDER BY created_at ASC'
        ).bind(id).all();
        const imgs = await env.DB.prepare(
          'SELECT * FROM brief_imagenes WHERE brief_id = ? ORDER BY orden ASC, id ASC'
        ).bind(id).all();
        if ((await getSessionRole(env, session.user)) === 'disenador') return json({ brief: briefSinVendedor(brief), messages: [], imagenes: imgs.results || [] });
        return json({ brief, messages: msgs.results || [], imagenes: imgs.results || [] });
      }

      // POST /admin/briefs  →  crear (form simplificado: solo titulo es virtualmente obligatorio)
      if (request.method === 'POST' && path === '/admin/briefs') {
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        // Vendedor del brief: el usuario logueado que lo carga (o el vendedor del chat).
        const comercial_id = await resolveComercial(env, { bodyComercial: body.comercial_id, sessionUser: session.user, phone: body.cliente_wa_id });
        const now = new Date().toISOString();
        const cols = [
          'cliente_wa_id', 'cliente_nombre', 'origen_lead', 'estado', 'tipo', 'diseno', 'corporea_json',
          'alto_cm', 'ancho_cm', 'm2', 'neon_mt', 'tramos', 'medidas_libre',
          'precio_trans', 'precio_negro', 'precio_final',
          'descuento', 'recargo', 'reventa', 'comision_joaco',
          'comercial_id', 'disenador_id', 'notas',
          'urgente', 'modificar',
          'created_at', 'updated_at'
        ];
        const vals = [
          body.cliente_wa_id || '', body.cliente_nombre || null, body.origen_lead || '',
          body.estado || 'nuevo', body.tipo || null, body.diseno || null, body.corporea_json ?? null,
          body.alto_cm ?? null, body.ancho_cm ?? null, body.m2 ?? null, body.neon_mt ?? null, body.tramos ?? 0,
          body.medidas_libre || null,
          body.precio_trans ?? null, body.precio_negro ?? null, body.precio_final ?? null,
          body.descuento ?? 0, body.recargo ?? 0, body.reventa ?? 0, body.comision_joaco ?? 0,
          comercial_id, body.disenador_id || null, body.notas || null,
          body.urgente ?? 0, body.modificar ?? 0,
          now, now
        ];
        const placeholders = cols.map(() => '?').join(',');
        const result = await env.DB.prepare(
          `INSERT INTO briefs (${cols.join(',')}) VALUES (${placeholders})`
        ).bind(...vals).run();
        const id = result.meta.last_row_id;
        const brief = await env.DB.prepare('SELECT * FROM briefs WHERE id = ?').bind(id).first();
        return json({ brief: (await getSessionRole(env, session.user)) === 'disenador' ? briefSinVendedor(brief) : brief }, 201);
      }

      // PATCH /admin/briefs/:id  →  editar specs / cambiar estado / asignar
      if (request.method === 'PATCH' && /^\/admin\/briefs\/\d+$/.test(path)) {
        const id = path.split('/').pop();
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const editable = [
          'cliente_nombre', 'cliente_wa_id', 'origen_lead', 'estado', 'tipo', 'diseno', 'corporea_json',
          'alto_cm', 'ancho_cm', 'm2', 'neon_mt', 'tramos', 'medidas_libre',
          'precio_trans', 'precio_negro', 'precio_final',
          'descuento', 'recargo', 'reventa', 'comision_joaco',
          'disenador_id', 'intentos_followup', 'notas', 'sheet_row',
          'urgente', 'modificar',
          // Modo comparación IA vs Emma (diseñador IA). ia_* separadas de las de Emma.
          'ia_modo', 'ia_alto_cm', 'ia_neon_mt', 'ia_tramos', 'ia_precio_trans', 'ia_feedback', 'ia_feedback_nota'
        ];
        const sets = [];
        const args = [];
        for (const k of editable) {
          if (!(k in body)) continue;
          // Guard defensivo: nunca pisar un teléfono ya cargado con vacío. Si
          // un caller manda cliente_wa_id='' (ej. una auto-grabación sin el
          // campo en el DOM), lo ignoramos para no borrar el número del cliente.
          // Para borrarlo a propósito hay que mandar origen_lead='ig' (que sí
          // se permite cambiar) — el teléfono queda guardado pero no se usa.
          if (k === 'cliente_wa_id') {
            const nv = String(body[k] ?? '').replace(/\D/g, '');
            if (!nv) continue; // vacío → no tocar
            sets.push(`${k} = ?`); args.push(nv);
            continue;
          }
          sets.push(`${k} = ?`); args.push(body[k]);
        }
        if (!sets.length) return json({ error: 'nothing to update' }, 400);
        sets.push('updated_at = ?');
        args.push(new Date().toISOString());
        args.push(id);
        await env.DB.prepare(`UPDATE briefs SET ${sets.join(', ')} WHERE id = ?`).bind(...args).run();
        const brief = await env.DB.prepare('SELECT * FROM briefs WHERE id = ?').bind(id).first();
        return json({ brief: (await getSessionRole(env, session.user)) === 'disenador' ? briefSinVendedor(brief) : brief });
      }

      // POST /admin/briefs/:id/messages  →  agregar mensaje al hilo interno (fase 3)
      if (request.method === 'POST' && /^\/admin\/briefs\/\d+\/messages$/.test(path)) {
        const id = path.split('/')[3];
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        if (!body.autor_id || !body.tipo) return json({ error: 'missing fields' }, 400);
        const now = new Date().toISOString();
        const result = await env.DB.prepare(
          'INSERT INTO brief_messages (brief_id, autor_id, tipo, contenido, is_final, created_at) VALUES (?,?,?,?,?,?)'
        ).bind(id, body.autor_id, body.tipo, body.contenido || null, body.is_final ? 1 : 0, now).run();
        await env.DB.prepare('UPDATE briefs SET updated_at = ? WHERE id = ?').bind(now, id).run();
        return json({ id: result.meta.last_row_id }, 201);
      }

      // DELETE /admin/briefs/:id  →  borra brief + sus imágenes (R2 + DB) + sus mensajes.
      // Solo se debe llamar desde rol comercial/admin (el frontend gatea, acá confiamos).
      if (request.method === 'DELETE' && /^\/admin\/briefs\/\d+$/.test(path)) {
        const id = path.split('/').pop();
        const brief = await env.DB.prepare('SELECT id FROM briefs WHERE id = ?').bind(id).first();
        if (!brief) return json({ error: 'not found' }, 404);
        // Borrar imágenes de R2 (mejor esfuerzo).
        const imgs = await env.DB.prepare('SELECT r2_key FROM brief_imagenes WHERE brief_id = ?').bind(id).all();
        if (env.MEDIA) {
          for (const row of (imgs.results || [])) {
            try { await env.MEDIA.delete(row.r2_key); } catch(e) { /* ignorar */ }
          }
        }
        // Borrar filas dependientes en orden.
        await env.DB.prepare('DELETE FROM brief_imagenes WHERE brief_id = ?').bind(id).run();
        await env.DB.prepare('DELETE FROM brief_messages WHERE brief_id = ?').bind(id).run();
        await env.DB.prepare('DELETE FROM briefs WHERE id = ?').bind(id).run();
        return noContent();
      }

      // POST /admin/briefs/:id/enviar  →  marca brief como enviado.
      // El envío real al cliente (WhatsApp) y la escritura al Sheet ya las hace
      // el frontend (cot-send-wa-btn / cot-save-btn en app.js). Este endpoint
      // solo registra el avance de estado + el sheet_row para trazabilidad.
      if (request.method === 'POST' && /^\/admin\/briefs\/\d+\/enviar$/.test(path)) {
        const id = path.split('/')[3];
        let body = {};
        try { body = await request.json(); } catch {}
        const now = new Date().toISOString();
        await env.DB.prepare(
          'UPDATE briefs SET estado = ?, enviado_at = ?, updated_at = ?, sheet_row = COALESCE(?, sheet_row), precio_final = COALESCE(?, precio_final) WHERE id = ?'
        ).bind('enviado', now, now, body.sheet_row ?? null, body.precio_final ?? null, id).run();
        // Quién lo mandó (mig. 048; aparte para que el envío no falle si la columna no está).
        try { await env.DB.prepare('UPDATE briefs SET enviado_por = ? WHERE id = ?').bind(autorSlug(session.user), id).run(); } catch (_) {}
        const brief = await env.DB.prepare('SELECT * FROM briefs WHERE id = ?').bind(id).first();
        return json({ brief: (await getSessionRole(env, session.user)) === 'disenador' ? briefSinVendedor(brief) : brief });
      }

      // PUT /admin/briefs/:id/imagen?tipo=chat|boceto|render  →  sube imagen a R2 + inserta.
      // Body: bytes raw del archivo. Headers: Content-Type: image/png|jpeg|webp|etc.
      // tipo:
      //   - 'chat'   → captura del cliente, sube Joaco
      //   - 'boceto' → boceto vectorizado de cotización, sube Emma
      //   - 'render' → render generado por IA (o subido manual), Emma
      // Default: 'chat'.
      if (request.method === 'PUT' && /^\/admin\/briefs\/\d+\/imagen$/.test(path)) {
        const briefId = path.split('/')[3];
        const tipoRaw = url.searchParams.get('tipo') || 'chat';
        const tipo = ['chat', 'boceto', 'render'].includes(tipoRaw) ? tipoRaw : 'chat';
        if (!env.MEDIA) return json({ error: 'R2 not configured' }, 500);
        // Este endpoint es SOLO para imágenes; si el content-type no viene como image/*
        // (pegado sin type / octet-stream desde el front), asumimos jpeg en vez de rechazar
        // con 400 — rechazar acá era una de las causas de "briefs sin foto de Joaco".
        let ct = (request.headers.get('content-type') || '').split(';')[0].trim().toLowerCase();
        if (!ct.startsWith('image/')) ct = 'image/jpeg';

        const buf = await request.arrayBuffer();
        if (!buf || buf.byteLength === 0) return json({ error: 'empty body' }, 400);
        if (buf.byteLength > 10 * 1024 * 1024) return json({ error: 'image too large (>10MB)' }, 413);

        const brief = await env.DB.prepare('SELECT id FROM briefs WHERE id = ?').bind(briefId).first();
        if (!brief) return json({ error: 'brief not found' }, 404);

        const ext = (ct.split('/')[1] || 'bin').replace(/[^a-z0-9]/gi, '').slice(0, 8) || 'bin';
        const r2Key = `briefs/${briefId}/${tipo}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
        try {
          await env.MEDIA.put(r2Key, buf, { httpMetadata: { contentType: ct } });
        } catch (e) {
          return json({ error: 'r2 put failed: ' + e.message }, 500);
        }

        // Orden = max(orden) + 1 dentro del brief + tipo.
        const ordRow = await env.DB.prepare(
          'SELECT COALESCE(MAX(orden), -1) + 1 AS next_ord FROM brief_imagenes WHERE brief_id = ? AND tipo = ?'
        ).bind(briefId, tipo).first();
        const orden = ordRow?.next_ord ?? 0;
        const now = new Date().toISOString();
        const result = await env.DB.prepare(
          'INSERT INTO brief_imagenes (brief_id, r2_key, content_type, size_bytes, orden, created_at, tipo) VALUES (?,?,?,?,?,?,?)'
        ).bind(briefId, r2Key, ct, buf.byteLength, orden, now, tipo).run();
        await env.DB.prepare('UPDATE briefs SET updated_at = ? WHERE id = ?').bind(now, briefId).run();
        return json({
          id: result.meta.last_row_id,
          brief_id: parseInt(briefId, 10),
          r2_key: r2Key,
          content_type: ct,
          size_bytes: buf.byteLength,
          orden,
          tipo,
          created_at: now
        }, 201);
      }

      // POST /admin/briefs/:id/generar-render  →  pipeline IA completo en paralelo:
      //   1. Toma como input el boceto si existe; si no, la captura de chat más reciente.
      //   2. Llama gemini-3-pro-image para generar el render (~$0.04).
      //   3. Llama gemini-2.5-flash para estimar ancho_cm, alto_cm, neon_mt (~$0.001).
      //   4. Guarda el render en R2 + actualiza el brief con las medidas estimadas.
      //   5. Devuelve la imagen del render + los params + flag dif_vs_cliente.
      // Idea: con esto Joaco solo tiene que mandar capturas del chat y el AI
      // saca todo lo necesario para cotizar, salteando al diseñador.
      // POST /admin/render-adhoc — render IA "suelto" (SIN brief): lo usa el
      // cotizador rápido de #presupuestos para hacer un mockup al toque sin pasar
      // por el flujo del panel. Recibe una foto (multipart) + notas opcionales,
      // genera el render con Gemini y lo devuelve en base64. El front lo muestra y,
      // al enviar el presupuesto, lo manda como foto + caption (igual que el panel).
      if (request.method === 'POST' && path === '/admin/render-adhoc') {
        if (!env.GEMINI_API_KEY) return json({ error: 'Falta configurar GEMINI_API_KEY en el worker' }, 503);
        const ctType = request.headers.get('Content-Type') || '';
        if (!ctType.includes('multipart/form-data')) return json({ error: 'expected multipart/form-data' }, 400);
        let fd; try { fd = await request.formData(); } catch { return json({ error: 'invalid form-data' }, 400); }
        const file = fd.get('file');
        if (!file || typeof file.arrayBuffer !== 'function') return json({ error: 'missing file' }, 400);
        const buf = await file.arrayBuffer();
        if (!buf || buf.byteLength < 64) return json({ error: 'imagen inválida o vacía' }, 400);
        const mime = (file.type || 'image/jpeg').split(';')[0].trim();
        const notas = String(fd.get('notas') || '').trim();
        const contexto = notas ? `NOTAS / INSTRUCCIONES ESPECÍFICAS PARA ESTE DISEÑO (tomalas en cuenta):\n${notas}` : '';
        const renderResult = await generarRenderConGemini(env, buf, mime, contexto);
        if (!renderResult || renderResult.error) {
          return json({ error: 'render: ' + ((renderResult && renderResult.error) || 'sin respuesta de la IA') }, 502);
        }
        return json({ ok: true, mime: renderResult.mime, base64: renderResult.base64 });
      }

      // POST /admin/rectify-perspective  →  endereza la perspectiva de una foto a vista
      // frontal (herramienta del diseñador). Body: imagen cruda (Content-Type image/*).
      // Reusa la cañería de Gemini image con GEMINI_RECTIFY_PROMPT. Devuelve { ok, base64, mime }.
      if (request.method === 'POST' && (path === '/admin/img-tool' || path === '/admin/rectify-perspective')) {
        if (!env.GEMINI_API_KEY) return json({ error: 'Falta configurar GEMINI_API_KEY en el worker' }, 503);
        // modo: rectify (perspectiva -> frontal) | vectorize (silueta B&N para Illustrator).
        // La ruta vieja /admin/rectify-perspective queda como rectify por retrocompat.
        const mode = path === '/admin/rectify-perspective' ? 'rectify' : (url.searchParams.get('mode') || 'rectify');
        const basePrompt = mode === 'vectorize' ? GEMINI_VECTORIZE_PROMPT : GEMINI_RECTIFY_PROMPT;
        const ct = (request.headers.get('content-type') || '').split(';')[0].trim();
        if (!ct.startsWith('image/')) return json({ error: 'Mandá la imagen cruda con Content-Type image/*' }, 400);
        let buf;
        try { buf = await request.arrayBuffer(); } catch (e) { return json({ error: 'No pude leer la imagen: ' + e.message }, 400); }
        if (!buf || buf.byteLength < 100) return json({ error: 'Imagen vacía o demasiado chica' }, 400);
        if (buf.byteLength > 12 * 1024 * 1024) return json({ error: 'Imagen muy grande (máx 12 MB)' }, 400);
        const notes = (url.searchParams.get('notes') || '').trim();
        const extraTexto = notes ? ('Aclaración adicional del diseñador (respetala): ' + notes) : '';
        // Herramientas del disenador (rectificar/vectorizar): modelo PRO (mejor
        // correccion geometrica y detalle). Es low-volume, no afecta el costo de
        // los renders (que van en flash). Override por env si hace falta.
        const r = await generarRenderConGemini(env, buf, ct, extraTexto, { basePrompt, model: env.GEMINI_IMGTOOL_MODEL || 'gemini-3-pro-image', ref: 'imgtool:' + mode });
        if (!r.ok) return json({ error: r.error || 'No se pudo procesar la imagen' }, 502);
        return json({ ok: true, base64: r.base64, mime: r.mime });
      }

      // POST /admin/img-mockup  →  monta el render de un cartel sobre la foto del local
      // (montaje hiperrealista). Body JSON: { canvas, render, canvasMime, renderMime } en
      // base64 crudo. 'canvas' = la foto del local CON el recuadro marcado (dónde va el cartel).
      if (request.method === 'POST' && path === '/admin/img-mockup') {
        if (!env.GEMINI_API_KEY) return json({ error: 'Falta configurar GEMINI_API_KEY en el worker' }, 503);
        let body; try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        const canvasB64 = String((body && body.canvas) || '');
        const renderB64 = String((body && body.render) || '');
        if (!canvasB64 || !renderB64) return json({ error: 'Faltan las dos imágenes (local marcado + render del cartel)' }, 400);
        if (canvasB64.length > 24 * 1024 * 1024 || renderB64.length > 24 * 1024 * 1024) return json({ error: 'Imagen muy grande' }, 400);
        const notes = String((body && body.notes) || '').trim();
        const extraTexto = notes ? ('Aclaración adicional del diseñador (respetala): ' + notes) : '';
        const r = await generarRenderConGemini(env, null, (body && body.canvasMime) || 'image/png', extraTexto, {
          basePrompt: GEMINI_MOCKUP_PROMPT,
          mainBase64: canvasB64,
          extraImages: [{ base64: renderB64, mime: (body && body.renderMime) || 'image/png' }],
          ref: 'mockup'
        });
        if (!r.ok) return json({ error: r.error || 'No se pudo generar el montaje' }, 502);
        return json({ ok: true, base64: r.base64, mime: r.mime });
      }

      // POST /admin/wa/etiquetar-sin-cotizar  →  corre el sync completo (destilda los ya
      // cotizados + etiqueta los nuevos con +20hs) y devuelve la lista. Solo admin; scan
      // pesado, no poll. El cron lo corre solo; esto es para refrescar a mano.
      if (request.method === 'POST' && path === '/admin/wa/etiquetar-sin-cotizar') {
        const role = await getSessionRole(env, session.user);
        if (role !== 'admin') return json({ error: 'forbidden' }, 403);
        try { return json({ ok: true, ...(await syncSinCotizar(env, { addPass: true })) }); }
        catch (e) { return json({ error: String(e && e.message || e) }, 500); }
      }

      // GET /admin/wa/reflote-segment  →  cuenta el segmento cualificado del reflote (dry-run,
      // no manda nada). Solo admin; scan de wa_messages (15 días), no poll.
      if (request.method === 'GET' && path === '/admin/wa/reflote-segment') {
        const role = await getSessionRole(env, session.user);
        if (role !== 'admin') return json({ error: 'forbidden' }, 403);
        try { const seg = await computeRefloteSegment(env); delete seg.rows; return json({ ok: true, ...seg }); }
        catch (e) { return json({ error: String(e && e.message || e) }, 500); }
      }

      // GET /admin/wa/sin-cotizar-status  →  estado liviano de la alarma para el poll del
      // front (count + max_created_at + nombres). Solo lee contact_labels (barato).
      // Admin + comercial (Joaco). NO escanea wa_messages.
      if (request.method === 'GET' && path === '/admin/wa/sin-cotizar-status') {
        const role = await getSessionRole(env, session.user);
        if (role !== 'admin' && role !== 'comercial') return json({ error: 'forbidden' }, 403);
        try {
          const labelId = await ensureLabelId(env, SIN_COTIZAR_LABEL_NAME, SIN_COTIZAR_LABEL_COLOR);
          // Scope por vendedor (mismo patrón que la lista de chats): cada comercial ve
          // solo lo suyo. Secundario (Nadia) → assigned_to = su slug; principal (Joaco)
          // → lo NO asignado a un secundario (incluye assigned_to NULL por el LEFT JOIN);
          // admin (Gaspar) → todo. uslug sale de la lista fija VENDEDORES_SECUNDARIOS → seguro.
          const uslug = String(session.user || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
          const esSecundario = role === 'comercial' && VENDEDORES_SECUNDARIOS.includes(uslug);
          let filtroVend = '';
          if (role === 'comercial') {
            filtroVend = esSecundario
              ? ` AND s.assigned_to = '${uslug}'`
              : ` AND (s.assigned_to IS NULL OR s.assigned_to NOT IN (${VENDEDORES_SECUNDARIOS.map(v => `'${v}'`).join(',')}))`;
          }
          const lista = (await env.DB.prepare(
            "SELECT cl.phone, cl.created_at, s.contact_name AS name FROM contact_labels cl LEFT JOIN wa_chats_summary s ON s.phone = cl.phone WHERE cl.label_id = ?" + filtroVend + " ORDER BY cl.created_at DESC"
          ).bind(labelId).all()).results || [];
          return json({
            ok: true, label_id: labelId, count: lista.length,
            max_created_at: lista[0] ? lista[0].created_at : null,
            nombres: lista.slice(0, 6).map(r => (r.name && r.name.trim()) ? r.name.trim() : ('+' + r.phone))
          });
        } catch (e) { return json({ error: String(e && e.message || e) }, 500); }
      }

      // GET /admin/wa/oc-urgente-status  →  popup "Pedido por vender URGENTE": OC enviada
      // hace +3h (y menos de 48h) sin que el cliente respondiera. Scope por VENDEDOR (quién
      // mandó la OC, columna oc_enviadas.vendedor): secundario (Nadia) ve las suyas; principal
      // (Joaco) las no-secundarias; admin (Gaspar) todas. Filtra cartel!='' para excluir las
      // filas históricas seedeadas (sin parsear). Barato: lee oc_enviadas + un NOT EXISTS.
      // Popup "🧾 OC sin pagar": las OC abiertas del vendedor (admin: todas), con el estado y la marca "dijo que pagó".
      if (request.method === 'GET' && path === '/admin/oc/pendientes') {
        const role = await getSessionRole(env, session.user);
        if (role !== 'admin' && role !== 'comercial') return json({ error: 'forbidden' }, 403);
        const b = await buildOcAbiertas(env);
        if (!b) return json({ ok: true, items: [], urgent_max: '' });
        const slug = ocSlugSesion(session.user);
        const items = role === 'admin' ? Object.values(b.porVend).flat() : (b.porVend[slug] || []);
        items.sort((x, y) => (y.urgente - x.urgente) || ((y.dias || 0) - (x.dias || 0)));
        const urg = items.filter(x => x.urgente3h).map(x => x.ref || '').sort();
        return json({ ok: true, items, urgent_max: urg.length ? urg[urg.length - 1] : '' });
      }
      // Marcar una OC desde el popup: {phone, accion:'pagado'|'baja', motivo?}. 'pagado' se VERIFICA (pedido cargado o
      // comprobante); si no se confirma queda "dijo que pagó" y sigue apareciendo. 'baja' (con motivo) saca POR PAGAR.
      // El vendedor solo puede marcar SUS OC; admin, cualquiera. Todo queda en oc_estado_log.
      if (request.method === 'POST' && path === '/admin/oc/marcar') {
        const role = await getSessionRole(env, session.user);
        if (role !== 'admin' && role !== 'comercial') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const phone = String(body.phone || '').replace(/\D/g, '');
        const accion = String(body.accion || '');
        if (!phone || !['pagado', 'baja'].includes(accion)) return json({ error: 'faltan datos' }, 400);
        const motivo = String(body.motivo || '').replace(/\s+/g, ' ').trim().slice(0, 160);
        if (accion === 'baja' && !motivo) return json({ error: 'elegí el motivo' }, 400);
        const b = await buildOcAbiertas(env);
        const it = b ? Object.values(b.porVend).flat().find(x => x.phone === phone) : null;
        if (!it) return json({ ok: true, ya_cerrada: true });   // ya no tiene POR PAGAR (la cerró otro / el comprobante)
        const slug = ocSlugSesion(session.user);
        if (role !== 'admin' && it.dueno !== slug) return json({ error: 'esa OC es de otro vendedor' }, 403);
        await ensureOcEstado(env);
        const nowIso = new Date().toISOString(), por = String(session.user || '');
        const log = (resultado) => env.DB.prepare('INSERT INTO oc_estado_log (phone, accion, resultado, motivo, por, at, cartel, importe, dueno) VALUES (?,?,?,?,?,?,?,?,?)').bind(phone, accion, resultado, motivo, por, nowIso, it.cartel || '', it.importe || '', it.dueno || '').run().catch(() => null);
        if (accion === 'baja') {
          await porPagarTag(env, phone, false);
          await env.DB.prepare("INSERT INTO oc_estado (phone, estado, motivo, por, at, oc_ts) VALUES (?, 'baja', ?, ?, ?, ?) ON CONFLICT(phone) DO UPDATE SET estado='baja', motivo=excluded.motivo, por=excluded.por, at=excluded.at, oc_ts=excluded.oc_ts").bind(phone, motivo, por, nowIso, it.ts_out || it.ref || nowIso).run();
          await log('baja');
          return json({ ok: true, baja: true });
        }
        const v = await ocVerificarPago(env, it);
        if (v.verificado) {
          try { await env.DB.prepare('DELETE FROM oc_estado WHERE phone = ?').bind(phone).run(); } catch (_) {}
          await log('pagado_' + v.via);
          return json({ ok: true, verificado: true, via: v.via, detalle: v.detalle });
        }
        await env.DB.prepare("INSERT INTO oc_estado (phone, estado, motivo, por, at, oc_ts) VALUES (?, 'reclamado', '', ?, ?, ?) ON CONFLICT(phone) DO UPDATE SET estado='reclamado', motivo='', por=excluded.por, at=excluded.at, oc_ts=excluded.oc_ts").bind(phone, por, nowIso, it.ts_out || it.ref || nowIso).run();
        await log('reclamado_sin_confirmar');
        return json({ ok: true, verificado: false });
      }
      if (request.method === 'GET' && path === '/admin/wa/oc-urgente-status') {
        const role = await getSessionRole(env, session.user);
        if (role !== 'admin' && role !== 'comercial') return json({ error: 'forbidden' }, 403);
        try {
          const uslug = String(session.user || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
          const esSecundario = role === 'comercial' && VENDEDORES_SECUNDARIOS.includes(uslug);
          let filtroVend = '';
          if (role === 'comercial') {
            filtroVend = esSecundario
              ? ` AND o.vendedor = '${uslug}'`
              : ` AND (o.vendedor IS NULL OR o.vendedor NOT IN (${VENDEDORES_SECUNDARIOS.map(v => `'${v}'`).join(',')}))`;
          }
          let lista = [];
          try {
            lista = (await env.DB.prepare(
              "SELECT o.wamid, o.phone, o.cartel, o.importe, o.canal, o.ts_out, s.contact_name AS name" +
              " FROM oc_enviadas o LEFT JOIN wa_chats_summary s ON s.phone = o.phone" +
              // julianday: ts_out es ISO con 'T' y datetime() devuelve 'AAAA-MM-DD HH:MM:SS' → comparar strings fallaba y
              // el popup salía recién al día siguiente (no a las 3 h).
              " WHERE julianday(o.ts_out) <= julianday('now','-3 hours') AND julianday(o.ts_out) >= julianday('now','-48 hours')" +
              "   AND o.cartel != '' AND o.pagado_at IS NULL" + filtroVend +
              "   AND NOT EXISTS (SELECT 1 FROM wa_messages m WHERE m.phone = o.phone AND m.direction='inbound' AND m.msg_type!='status' AND m.ts > o.ts_out)" +
              " ORDER BY o.ts_out DESC LIMIT 30"
            ).all()).results || [];
          } catch (_) { lista = []; }
          return json({
            ok: true, count: lista.length,
            max_created_at: lista[0] ? lista[0].ts_out : null,
            items: lista.slice(0, 8).map(r => ({
              phone: r.phone,
              nombre: (r.cartel && r.cartel.trim()) ? r.cartel.trim() : ((r.name && r.name.trim()) ? r.name.trim() : ('+' + r.phone)),
              importe: r.importe || '', canal: r.canal || 'wa'
            }))
          });
        } catch (e) { return json({ error: String(e && e.message || e) }, 500); }
      }

      // POST /admin/oc/test-aviso  →  dispara a mano el aviso "OC ENVIADA" a Gaspar + hermano
      // (usa la última OC real, o {phone,cartel,importe} del body). Para probar la notif. Admin.
      if (request.method === 'POST' && path === '/admin/oc/test-aviso') {
        const role = await getSessionRole(env, session.user);
        if (role !== 'admin') return json({ error: 'forbidden' }, 403);
        let oc = null;
        try {
          const b = await request.json().catch(() => ({}));
          if (b && b.phone) oc = { phone: String(b.phone).replace(/\D/g, ''), cartel: String(b.cartel || 'TEST'), importe: String(b.importe || '$0'), canal: 'wa' };
        } catch (_) {}
        if (!oc) {
          try {
            const m = await env.DB.prepare("SELECT phone, body FROM wa_messages WHERE direction='outbound' AND msg_type!='status' AND body LIKE '%Orden de compra:%' ORDER BY ts DESC LIMIT 1").first();
            if (m) oc = parseOC(m.body, m.phone);
          } catch (_) {}
        }
        if (!oc || !oc.phone) return json({ error: 'no hay OC para probar' }, 404);
        const ok = await notifyOCEnviada(env, oc);
        return json({ ok, delivered: ok, oc });
      }

      // POST /admin/oc/check-pagos  →  corre el vigilador de comprobantes a mano (opcional
      // ?phone=<tel> para un solo chat, ?force=1 para re-OCRear aunque ya se haya chequeado).
      // Devuelve qué imágenes vio, el veredicto OCR y si hizo el swap de etiquetas. Admin.
      if (request.method === 'POST' && path === '/admin/oc/check-pagos') {
        const role = await getSessionRole(env, session.user);
        if (role !== 'admin') return json({ error: 'forbidden' }, 403);
        const ph = url.searchParams.get('phone') || null;
        const force = url.searchParams.get('force') === '1';
        const rep = await processCartelPagos(env, { phone: ph, force });
        return json({ ok: true, checked: rep.length, report: rep });
      }

      // ===== Módulo Servicio de Corte (vertical B2B/alumnos) =====
      // GET /admin/corte/alumnos?q=  →  lista de alumnos (espejo de LTV_Alumnos). Admin.
      // POST /admin/corte/cargar-tanda {fecha:'12/10/2026', dry_run:true|false} → carga las piezas de esa fecha de
      // Venta_Insumos en su tanda (teléfono por nombre exacto en LTV, entrega desde la planilla de cortes, sin neón).
      // dry_run (default) solo devuelve el reporte. Idempotente. Admin.
      if (request.method === 'POST' && path === '/admin/corte/cargar-tanda') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        // Carga completa: primero las piezas de la landing de ese lunes, después la planilla y la entrega.
        const r = await corteCargarTandaCompleta(env, { fecha: body.fecha, dryRun: body.dry_run !== false, incluirSospechosas: body.incluir_sospechosas === true });
        return json(r, r.error && !r.nuevas ? 400 : 200);
      }
      // GET /admin/corte/sin-telefono?tanda_id= → clientes de la tanda SIN teléfono (no se les puede cobrar) + sugerencias.
      if (request.method === 'GET' && path === '/admin/corte/sin-telefono') {
        const _r = await getSessionRole(env, session.user);
        if (_r !== 'admin') return json({ error: 'forbidden' }, 403);
        const tandaId = parseInt(url.searchParams.get('tanda_id'), 10) || 0;
        let rows = [];
        try { rows = (await env.DB.prepare("SELECT cliente_nombre, COUNT(*) n, SUM(precio) total FROM corte_pedidos WHERE (telefono IS NULL OR telefono='') AND IFNULL(producto,'')!='NEON' AND lower(cliente_nombre)!='neon' AND estado_pago NOT IN ('pagado','interno')" + (tandaId ? " AND tanda_id=?" : "") + " GROUP BY cliente_nombre ORDER BY cliente_nombre").bind(...(tandaId ? [tandaId] : [])).all()).results || []; } catch (_) {}
        const ltv = rows.length ? await corteLtv(env) : { ok: true, rows: [] };
        const out = [];
        for (const r of rows) out.push({ nombre: r.cliente_nombre, piezas: r.n, total: r.total || 0, sugerencias: await corteSugerenciasTel(env, r.cliente_nombre, ltv.ok ? ltv.rows : []) });
        return json({ ok: true, sin_telefono: out, ltv_error: ltv.ok ? '' : ltv.error });
      }
      // POST /admin/corte/asignar-telefono {tanda_id?, cliente_nombre, telefono, forzar?} → asigna el teléfono a las
      // piezas SIN teléfono de ese cliente y lo recuerda (corte_tel_override) para las próximas tandas. Si el número
      // figura en LTV a nombre de OTRA persona, frena (409) salvo forzar:true.
      if (request.method === 'POST' && path === '/admin/corte/asignar-telefono') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const nombre = String(body.cliente_nombre || '').trim();
        const tel = corteTel(body.telefono);
        if (!nombre) return json({ error: 'falta el cliente' }, 400);
        if (!tel) return json({ error: 'teléfono inválido (tiene que quedar 549 + código de área + número, 13 dígitos)' }, 400);
        const [ltv, ov] = await Promise.all([corteLtv(env), corteTelOverrides(env)]);
        // Si LTV no se puede leer, NO se asigna sin confirmar (no se pudo verificar que el número no sea de otra persona).
        let otro = null;
        if (!ltv.ok) otro = { nombre: 'NO VERIFICADO (no pude leer LTV_Alumnos: ' + ltv.error + ')', fuente: 'LTV' };
        else otro = corteTelDeOtro(tel, nombre, await corteDuenios(env, ltv.rows, ov));
        if (otro && body.forzar !== true) return json({ ok: false, conflicto: otro.nombre, fuente: otro.fuente, error: 'Ese teléfono figura a nombre de ' + otro.nombre + ' (' + otro.fuente + ')' }, 409);
        const tandaId = parseInt(body.tanda_id, 10) || 0;
        const nowIso = new Date().toISOString();
        let n = 0;
        try { const u = await env.DB.prepare("UPDATE corte_pedidos SET telefono=?, updated_at=? WHERE cliente_nombre=? AND (telefono IS NULL OR telefono='') AND IFNULL(producto,'')!='NEON'" + (tandaId ? " AND tanda_id=?" : "")).bind(tel, nowIso, nombre, ...(tandaId ? [tandaId] : [])).run(); n = (u.meta && u.meta.changes) || 0; } catch (e) { return json({ error: String((e && e.message) || e) }, 500); }
        // Se recuerda para las próximas tandas SOLO si el nombre tiene nombre y apellido (con uno solo sería volver al
        // "teléfono por nombre de pila").
        const recordado = corteTokens(nombre).length >= 2;
        if (recordado) { try { await env.DB.prepare("INSERT INTO corte_tel_override (nombre_norm, nombre, telefono, created_by, created_at) VALUES (?,?,?,?,?) ON CONFLICT(nombre_norm) DO UPDATE SET telefono=excluded.telefono, nombre=excluded.nombre, created_by=excluded.created_by, created_at=excluded.created_at").bind(corteNormNombre(nombre), nombre, tel, String(session.user || ''), nowIso).run(); } catch (_) {} }
        // La clave del paquete cambia de 'n:'+nombre a teléfono: se migran N° de paquete, medidas, contacto y historial.
        let paquetesMigrados = 0;
        try { paquetesMigrados = await corteMigrarPaquetesTel(env, nombre, tel, tandaId); } catch (_) {} // idempotente (también levanta asignaciones previas)
        // + la dirección desglosada y las correcciones de logística (corte_direcciones, por cliente).
        let direccionMigrada = 0;
        try { direccionMigrada = await corteMigrarDireccionTel(env, nombre, tel); } catch (_) {}
        return json({ ok: true, telefono: tel, piezas: n, forzado: !!otro, recordado, paquetes_migrados: paquetesMigrados, direccion_migrada: direccionMigrada });
      }
      // POST /admin/corte/sync-entrega {tanda_id?} → trae la entrega (retira/envío) de la planilla de cortes ahora. Admin.
      if (request.method === 'POST' && path === '/admin/corte/sync-entrega') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const r = await corteSyncEntrega(env, { soloTandaId: parseInt(body.tanda_id, 10) || 0, notify: true });
        return json(r, r.error ? 502 : 200);
      }
      if (request.method === 'GET' && path === '/admin/corte/alumnos') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        const q = (url.searchParams.get('q') || '').trim().toLowerCase();
        let rows = [];
        try {
          if (q) {
            rows = (await env.DB.prepare(
              "SELECT id, nro_cliente, nombre, telefono, datos_envio, cantidad_pedidos, importe_acumulado FROM corte_alumnos WHERE lower(nombre) LIKE ? OR telefono LIKE ? ORDER BY nombre LIMIT 500"
            ).bind('%' + q + '%', '%' + q.replace(/\D/g, '') + '%').all()).results || [];
          } else {
            rows = (await env.DB.prepare(
              "SELECT id, nro_cliente, nombre, telefono, datos_envio, cantidad_pedidos, importe_acumulado FROM corte_alumnos ORDER BY nombre LIMIT 500"
            ).all()).results || [];
          }
        } catch (_) {}
        return json({ ok: true, alumnos: rows });
      }
      // GET /admin/corte/pedidos  →  pedidos de corte (para el tablero). Admin.
      if (request.method === 'GET' && path === '/admin/corte/pedidos') {
        const _cpRole = await getSessionRole(env, session.user);
        if (!['admin', 'disenador', 'produccion'].includes(_cpRole)) return json({ error: 'forbidden' }, 403);
        let rows = [];
        // Las piezas PENDIENTES (pedido / matriz_lista / cortado) vienen SIEMPRE, sin importar lo viejas que
        // sean: antes era "las últimas 500 por updated_at" y una matriz vieja sin hacer se caía de la cola
        // de Emma cuando la tabla crecía. El resto, solo lo movido en los últimos 180 días (historial/semanas).
        // + datos del cartel del CRM para las piezas de neón propio (productor, fecha, estado del pedido).
        // Columnas del despacho (despachado_at, entregado_at, pago_metodo...) antes del SELECT c.* → el tablero las recibe.
        const _despOk = await ensureCorteDespachoSchema(env);
        try {
          await ensureCorteNeonSchema(env);
          const desde = new Date(Date.now() - 180 * 86400000).toISOString();
          rows = (await env.DB.prepare(
            `SELECT c.*, p.productor AS ped_productor, p.fecha AS ped_fecha, p.estado_pedido AS ped_estado
               FROM corte_pedidos c LEFT JOIN pedidos p ON p.id = c.pedido_id
              WHERE (c.estado IN ('pedido','matriz_lista','cortado') OR c.updated_at >= ?) AND c.estado != 'prueba'
              ORDER BY c.updated_at DESC, c.id DESC LIMIT 3000`
          ).bind(desde).all()).results || [];
        } catch (_) {
          try { rows = (await env.DB.prepare("SELECT * FROM corte_pedidos ORDER BY updated_at DESC, id DESC LIMIT 500").all()).results || []; } catch (_) {}
        }
        // Medidas reales de los paquetes (las carga Neyen al embalar; las ve logística) de las tandas recientes.
        let paquetes = [];
        // + la línea de logística de la tarjeta de Neyen (N°, contacto, envío pagado, cargado/despachado).
        try { await ensureCortePaquetesSchema(env); paquetes = (await env.DB.prepare("SELECT tanda_id, cliente_key, largo, ancho, alto, peso, bultos, medido_at, contactado, cargado" + (_despOk ? ", numero, contacto_estado, contacto_at, envio_pagado, despachado_at" : "") + ((_despOk && await ensureLogiTablaSchema(env).catch(() => false)) ? ", transporte, transporte_conf" : "") + " FROM corte_paquetes WHERE tanda_id IN (SELECT id FROM corte_tandas ORDER BY id DESC LIMIT 4)").all()).results || []; } catch (_) {}
        const precio_m2 = parseInt(await kvGet(env, 'corte_precio_m2', '175000'), 10) || 175000;
        if (_cpRole !== 'admin') rows.forEach(cortePiezaSinVendedor);   // Emma/Corte: sin el vendedor
        return json({ ok: true, pedidos: rows, paquetes, precio_m2, role: _cpRole, user: String(session.user || '').toLowerCase() });
      }
      // ===== LOGÍSTICA =====
      // Errores con el contrato del circuito de despacho: {error:'<codigo>', motivo?:'<texto para mostrar>'}.
      const _logiErrDb = () => json({ error: 'db', motivo: 'No se pudo leer la base. Probá de nuevo en un momento.' }, 500);
      // GET /admin/logistica/paquetes?tanda_id= → paquetes de ENVÍO (+ sin definir) de la tanda, con N° estable, contacto,
      // envío pagado, pedido pagado, listo/bloqueo, arrastre e historial (logisticaArmar). Logística ve 2 tandas; admin 8.
      // + planilla: dir desglosada (IA cacheada por hash del texto de LTV; acá se desglosan las pendientes, una llamada por
      // request; la carga la espera hasta LOGI_DIR_ESPERA_MS y si tarda más termina en segundo plano) con las correcciones
      // de logística, faltan, transporte (elegido o sugerido), costo del envío y seguimiento.
      // Arriba: transportes = lista del select (los de base + los que agregó logística; logiTransportesLista).
      if (request.method === 'GET' && path === '/admin/logistica/paquetes') {
        const _r = await getSessionRole(env, session.user);
        if (!['logistica', 'admin'].includes(_r)) return json({ error: 'forbidden' }, 403);
        try { return json(await logisticaPaquetes(env, parseInt(url.searchParams.get('tanda_id'), 10) || 0, { rol: _r, parsear: true, ctx })); }
        catch (_) { return _logiErrDb(); }
      }
      // POST /admin/logistica/contacto {tanda_id, key, accion, nota?, operador?} → estado de contacto del lunes.
      //  escrito (al tocar WhatsApp) · no_contesta (+1 intento; al 3° avisa a Gaspar, 1 vez) · envio_pagado · deshacer_envio ·
      //  avisar (manda a Gaspar "Logística · N° 07 Nombre: <nota>", máx 1 cada 5 min por paquete). Toda acción queda en
      //  logistica_log. → {ok, paquete}
      if (request.method === 'POST' && path === '/admin/logistica/contacto') {
        const _r = await getSessionRole(env, session.user);
        if (!['logistica', 'admin'].includes(_r)) return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const tandaId = parseInt(body.tanda_id, 10) || 0, key = String(body.key || '').slice(0, 80);
        const accion = String(body.accion || '');
        if (!tandaId || !key) return json({ error: 'faltan_datos', motivo: 'Faltan datos del paquete' }, 400);
        if (!['escrito', 'no_contesta', 'envio_pagado', 'deshacer_envio', 'avisar'].includes(accion)) return json({ error: 'accion', motivo: 'Acción desconocida' }, 400);
        const nota = String(body.nota || '').replace(/\s+/g, ' ').trim();
        if (accion === 'avisar' && !nota) return json({ error: 'nota', motivo: 'Escribí en la nota qué querés avisar' }, 400);
        if (accion === 'avisar' && nota.length > 300) return json({ error: 'nota', motivo: 'El aviso puede tener hasta 300 letras' }, 400);
        const operador = logiOperador(body, session), usuario = String(session.user || ''), quienPor = logiQuien(session, operador);
        let pq;
        try { pq = await logisticaPaqueteDe(env, _r, tandaId, key, false); } catch (_) { return _logiErrDb(); }
        if (pq.status) return json(pq.body, pq.status);
        const P = pq.paquete, I = P._int;
        const nowIso = new Date().toISOString();
        const pre = [env.DB.prepare('INSERT INTO corte_paquetes (tanda_id, cliente_key) VALUES (?, ?) ON CONFLICT(tanda_id, cliente_key) DO NOTHING').bind(tandaId, key)];
        if (I.her) pre.push(logiFijarHerenciaStmt(env, tandaId, key, I.her));
        if (accion === 'avisar') {
          try { await env.DB.batch(pre); } catch (_) { return _logiErrDb(); }
          // Tope GLOBAL (todas las semanas y paquetes): máx 20 avisos por hora a Gaspar. El freno por paquete solo no alcanza
          // (con 40 paquetes por semana y 2 semanas visibles se podían mandar ~80 WhatsApp cada 5 min). Ventana fija desde el
          // primer aviso, contador atómico en kv_cache. Si el contador falla, sigue valiendo el freno por paquete.
          let cuenta = null;
          try { cuenta = await env.DB.prepare("INSERT INTO kv_cache (k, v, updated_at) VALUES ('logistica_avisos', '1', ?) ON CONFLICT(k) DO UPDATE SET v = CASE WHEN kv_cache.updated_at < ? THEN '1' ELSE CAST(CAST(kv_cache.v AS INTEGER) + 1 AS TEXT) END, updated_at = CASE WHEN kv_cache.updated_at < ? THEN excluded.updated_at ELSE kv_cache.updated_at END RETURNING v").bind(nowIso, isoHace(3600 * 1000), isoHace(3600 * 1000)).first(); } catch (_) {}
          if (cuenta && (parseInt(cuenta.v, 10) || 0) > 20) return json({ error: 'espera', motivo: 'Se mandaron muchos avisos en la última hora. Si es urgente, llamá a Neon.' }, 429);
          // Freno atómico: 1 aviso por paquete cada 5 min (doble toque, o insistir).
          let claim = null;
          try { claim = await env.DB.prepare('UPDATE corte_paquetes SET aviso_at=? WHERE tanda_id=? AND cliente_key=? AND (aviso_at IS NULL OR aviso_at < ?) RETURNING aviso_at').bind(nowIso, tandaId, key, isoHace(5 * 60 * 1000)).first(); } catch (_) {}
          if (!claim) return json({ error: 'espera', motivo: 'Ya avisaste hace un momento' }, 429);
          try { await precotizNotifyGaspar(env, 'Logística · N° ' + cortePad2(P.numero) + ' ' + String(P.cliente || '').trim() + ': ' + nota + (operador ? ' (' + operador + ')' : ''), { tipo: 'logistica', prioridad: 'P2' }); } catch (_) {}
          try { await logiLogStmt(env, tandaId, key, 'avisar', nota, operador, usuario).run(); } catch (_) {}
        } else {
          const st = [...pre, logiContactoStmt(env, accion, tandaId, key, nowIso, quienPor)];
          st.push(logiLogStmt(env, tandaId, key, accion, nota, operador, usuario));
          try { await env.DB.batch(st); } catch (_) { return _logiErrDb(); }
          // 3 intentos sin respuesta → aviso a Gaspar, UNA sola vez por paquete.
          if (accion === 'no_contesta') await logiAvisoNoContesta(env, P, tandaId, key, nowIso);
        }
        let fin;
        try { fin = await logisticaPaqueteDe(env, _r, tandaId, key, true); } catch (_) { return json({ ok: true }); }
        return fin.status ? json({ ok: true }) : json({ ok: true, paquete: fin.paquete });
      }
      // POST /admin/logistica/marcar {tanda_id, key, cargado?, nota?, contactado? (compat), operador?}
      //  · cargado=true (martes, "cargado en el camión"): se recalcula el paquete EN EL SERVER (misma regla que la lista) y
      //    si falta algo → 409 {error:'no_despachar', motivo:'Pedido impago'|'Entrega sin definir'|'Falta pagar el envío'}.
      //    Sin override, ni para admin (para eso está "Marcar pagado"). OK → las piezas pendientes del paquete (incluye
      //    arrastre) pasan a 'despachado' con despachado_at. Si alguna estaba 'cortado' (sin embalar) → aviso a Gaspar.
      //  · cargado=false → vuelven a 'embalado' SOLO las piezas de ESE despacho (mismo despachado_at). Solo el mismo día AR
      //    (o admin): si no, 409 'Ya no se puede deshacer'.
      //  · nota: autosave del front (se pisa; no va al historial). → {ok, paquete}
      if (request.method === 'POST' && path === '/admin/logistica/marcar') {
        const _r = await getSessionRole(env, session.user);
        if (!['logistica', 'admin'].includes(_r)) return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const tandaId = parseInt(body.tanda_id, 10) || 0, key = String(body.key || '').slice(0, 80);
        if (!tandaId || !key) return json({ error: 'faltan_datos', motivo: 'Faltan datos del paquete' }, 400);
        const hayCargado = typeof body.cargado === 'boolean', hayNota = typeof body.nota === 'string', hayContactado = typeof body.contactado === 'boolean';
        if (!hayCargado && !hayNota && !hayContactado) return json({ error: 'nada', motivo: 'Nada para guardar' }, 400);
        let pq;
        try { pq = await logisticaPaqueteDe(env, _r, tandaId, key, false); } catch (_) { return _logiErrDb(); }
        if (pq.status) return json(pq.body, pq.status);
        const P = pq.paquete;
        const nowIso = new Date().toISOString(), quien = logiOperador(body, session), usuario = String(session.user || ''), quienPor = logiQuien(session, quien);
        const insRow = env.DB.prepare('INSERT INTO corte_paquetes (tanda_id, cliente_key) VALUES (?, ?) ON CONFLICT(tanda_id, cliente_key) DO NOTHING').bind(tandaId, key);
        if (hayCargado) { // misma regla que la columna "Enviado" de la tabla (logiDespacho)
          const err = await logiDespacho(env, _r, tandaId, key, P, body.cargado, quien, usuario, quienPor);
          if (err) return json(err.body, err.status);
        }
        const sets = [], binds = [];
        if (hayContactado) { sets.push('contactado=?, contactado_at=?, contactado_por=?'); binds.push(body.contactado ? 1 : 0, body.contactado ? nowIso : null, quienPor); }
        if (hayNota) { sets.push('nota=?, nota_at=?, nota_por=?'); binds.push(body.nota.slice(0, 1000), nowIso, quienPor); }
        if (sets.length) {
          try { await env.DB.batch([insRow, env.DB.prepare('UPDATE corte_paquetes SET ' + sets.join(', ') + ' WHERE tanda_id=? AND cliente_key=?').bind(...binds, tandaId, key)]); } catch (_) { return _logiErrDb(); }
        }
        let fin;
        try { fin = await logisticaPaqueteDe(env, _r, tandaId, key, true); } catch (_) { return json({ ok: true }); }
        return fin.status ? json({ ok: true }) : json({ ok: true, paquete: fin.paquete });
      }
      // POST /admin/logistica/celda {tanda_id, key, campo, valor, operador?} → edita UNA celda de la tabla de logística
      // (logistica|admin; semana permitida para el rol, igual que /contacto). Campos (LOGI_CELDA_CAMPOS):
      //  · recibe, dni, calle, localidad, provincia, cp, tel_alt, obs → corrección de la dirección (corte_direcciones.edit_json,
      //    por campo, aunque sea vacía; vale para las próximas semanas; NO se escribe en LTV).
      //  · transporte (cualquier texto ≤40, transporte_conf=1: uno nuevo entra en la lista para todos; '' lo borra y vuelve
      //    el sugerido) · envio_costo (entero 0..10.000.000 o '') ·
      //    seguimiento (≤80) · bultos (1..20 o '') · nota (≤1000, como /marcar) · contacto_estado ('' | escrito | no_contesta |
      //    confirmado; no_contesta suma un intento y al 3° avisa a Gaspar, como /contacto) · envio_pagado (bool, como /contacto)
      //    · enviado (bool, la misma regla de /marcar cargado: 409 {error:'no_despachar', motivo}).
      //  Cada cambio deja una fila en logistica_log ('celda:<campo>', nota = valor nuevo hasta 120). Sin cambio real no escribe.
      //  → {ok, paquete} (mismo shape que el GET) | 400 {error, motivo} | 403 | 404 | 409 | 500
      if (request.method === 'POST' && path === '/admin/logistica/celda') {
        const _r = await getSessionRole(env, session.user);
        if (!['logistica', 'admin'].includes(_r)) return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const tandaId = parseInt(body.tanda_id, 10) || 0, key = String(body.key || '').slice(0, 80), campo = String(body.campo || '');
        if (!tandaId || !key) return json({ error: 'faltan_datos', motivo: 'Faltan datos del paquete' }, 400);
        if (!LOGI_CELDA_CAMPOS.includes(campo)) return json({ error: 'campo', motivo: 'Esa columna no se puede editar' }, 400);
        const v = logiCeldaValor(campo, body.valor);
        if (v.error) return json({ error: v.error, motivo: v.motivo }, 400);
        if (!(await ensureLogiTablaSchema(env))) return json({ error: 'db', motivo: 'No se pudo preparar la base. Probá de nuevo.' }, 500);
        const operador = logiOperador(body, session), usuario = String(session.user || ''), quienPor = logiQuien(session, operador);
        let pq;
        // Para un campo de dirección se lee LTV (copia en memoria de 3 min): la corrección queda atada al texto vigente.
        try { pq = await logisticaPaqueteDe(env, _r, tandaId, key, LOGI_DIR_CAMPOS.includes(campo)); } catch (_) { return _logiErrDb(); }
        if (pq.status) return json(pq.body, pq.status);
        const P = pq.paquete, I = P._int, M = I.mkCur || {}, nowIso = new Date().toISOString();
        // La nota del historial se arma al usarla (el transporte puede cambiar de grafía más abajo).
        const notaLog = () => (typeof v.valor === 'boolean' ? (v.valor ? 'sí' : 'no') : String(v.valor == null ? '' : v.valor)).replace(/\s+/g, ' ').trim().slice(0, 120);
        const logSt = () => logiLogStmt(env, tandaId, key, 'celda:' + campo, notaLog(), operador, usuario);
        // Fila del paquete + "envío pagado" heredado del arrastre fijado en ESTA semana (igual que /contacto y /marcar).
        const pre = [env.DB.prepare('INSERT INTO corte_paquetes (tanda_id, cliente_key) VALUES (?, ?) ON CONFLICT(tanda_id, cliente_key) DO NOTHING').bind(tandaId, key)];
        if (I.her) pre.push(logiFijarHerenciaStmt(env, tandaId, key, I.her));
        const upd = (sql, ...b) => env.DB.prepare('UPDATE corte_paquetes SET ' + sql + ' WHERE tanda_id=? AND cliente_key=?').bind(...b, tandaId, key);
        let st = null;
        if (LOGI_DIR_CAMPOS.includes(campo)) {
          let f = null;
          try { f = await env.DB.prepare('SELECT edit_json, edit_hash FROM corte_direcciones WHERE cliente_key=?').bind(key).first(); } catch (_) { return _logiErrDb(); }
          // Hash del texto de LTV vigente (null = la planilla no se leyó bien ahora: no se toca edit_hash). Si las correcciones
          // guardadas son de otro texto (ya no se muestran: dir_edit_vieja), se descartan y se arranca de cero con esta.
          const hAct = (P._dirH === undefined) ? null : P._dirH;
          const ed = logiEditVieja(f && f.edit_hash, hAct) ? {} : (logiJson(f && f.edit_json) || {});
          // json_set por campo (atómico: dos personas corrigiendo campos distintos a la vez no se pisan). El descarte de las
          // viejas se decide en el mismo UPDATE (misma regla que logiEditVieja) para no borrar una corrección recién hecha.
          // edit_hash: el vigente; sin planilla (null) o sin texto ('') se conserva el que había.
          if (!(Object.prototype.hasOwnProperty.call(ed, campo) && String(ed[campo]) === v.valor)) {
            st = [env.DB.prepare("INSERT INTO corte_direcciones (cliente_key, edit_json, edit_por, edit_at, edit_hash) VALUES (?, json_object(?, ?), ?, ?, ?) ON CONFLICT(cliente_key) DO UPDATE SET "
              + "edit_json=json_set(CASE WHEN json_valid(corte_direcciones.edit_json) AND NOT (IFNULL(excluded.edit_hash,'')!='' AND corte_direcciones.edit_hash IS NOT NULL AND corte_direcciones.edit_hash!=excluded.edit_hash) THEN corte_direcciones.edit_json ELSE '{}' END, ?, ?), "
              + "edit_por=excluded.edit_por, edit_at=excluded.edit_at, "
              + "edit_hash=CASE WHEN IFNULL(excluded.edit_hash,'')='' AND corte_direcciones.edit_hash IS NOT NULL THEN corte_direcciones.edit_hash ELSE excluded.edit_hash END")
              .bind(key, campo, v.valor, quienPor, nowIso, hAct, '$.' + campo, v.valor), logSt()];
          }
        } else if (campo === 'transporte') {
          // Uno que ya está en la lista con otra grafía ("moto propia" / "Moto Propia") se guarda como el de la lista.
          if (v.valor) { try { v.valor = logiTransporteNorm(v.valor, await logiTransportesLista(env)); } catch (_) {} }
          const cur = M.transporte ? String(M.transporte) : '';
          if (!(cur === v.valor && (v.valor === '' ? !I.her : +M.transporte_conf === 1))) st = [...pre, upd('transporte=?, transporte_conf=?', v.valor || null, v.valor ? 1 : 0), logSt()];
        } else if (campo === 'envio_costo') {
          const cur = (M.envio_costo == null || M.envio_costo === '') ? null : +M.envio_costo;
          if (I.her || cur !== v.valor) st = [...pre, upd('envio_costo=?', v.valor), logSt()];
        } else if (campo === 'seguimiento') {
          if (String(M.seguimiento || '') !== v.valor) st = [...pre, upd('seguimiento=?', v.valor || null), logSt()];
        } else if (campo === 'bultos') {
          const cur = (parseInt(M.bultos, 10) || 0) > 0 ? parseInt(M.bultos, 10) : null;
          if (cur !== v.valor) st = [...pre, upd('bultos=?', v.valor), logSt()];
        } else if (campo === 'nota') {
          if (String(M.nota || '') !== v.valor) st = [...pre, upd('nota=?, nota_at=?, nota_por=?', v.valor, nowIso, quienPor), logSt()];
        } else if (campo === 'contacto_estado') {
          // En la tabla el contacto es su propia columna: se guarda lo elegido (no se pasa solo a 'listo' por el envío pagado).
          if (v.valor === 'no_contesta') st = [...pre, upd("intentos=IFNULL(intentos,0)+1, contacto_estado='no_contesta', contacto_at=?", nowIso), logSt()];
          else if (I.her || String(M.contacto_estado || '') !== v.valor) st = [...pre, upd('contacto_estado=?, contacto_at=?', v.valor, v.valor ? nowIso : null), logSt()];
        } else if (campo === 'envio_pagado') {
          if (!!P.envio_pagado !== v.valor) st = [...pre, logiContactoStmt(env, v.valor ? 'envio_pagado' : 'deshacer_envio_tabla', tandaId, key, nowIso, quienPor), logSt()];
        } else if (campo === 'enviado') {
          // La MISMA regla que /marcar cargado (nunca se despacha con deuda ni sin el envío pagado; deshacer acotado).
          const err = await logiDespacho(env, _r, tandaId, key, P, v.valor, operador, usuario, quienPor, { ok: 'celda:enviado', undo: 'celda:enviado', notaOk: 'sí', notaUndo: 'no' });
          if (err) return json(err.body, err.status);
        }
        if (st) {
          try { await env.DB.batch(st); } catch (_) { return _logiErrDb(); }
          if (campo === 'contacto_estado' && v.valor === 'no_contesta') await logiAvisoNoContesta(env, P, tandaId, key, nowIso);
        }
        let fin;
        try { fin = await logisticaPaqueteDe(env, _r, tandaId, key, true); } catch (_) { return json({ ok: true }); }
        return fin.status ? json({ ok: true }) : json({ ok: true, paquete: fin.paquete });
      }
      // POST /admin/logistica/resumen {tanda_id, tipo:'martes', operador?} → "Terminé de cargar": aviso a Gaspar con lo que
      // se cargó y lo que quedó en el taller (con el motivo). Máx 1 cada 10 min por tanda. → {ok, texto}
      if (request.method === 'POST' && path === '/admin/logistica/resumen') {
        const _r = await getSessionRole(env, session.user);
        if (!['logistica', 'admin'].includes(_r)) return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const tandaId = parseInt(body.tanda_id, 10) || 0;
        if (!tandaId) return json({ error: 'faltan_datos', motivo: 'Falta la semana' }, 400);
        if (String(body.tipo || 'martes') !== 'martes') return json({ error: 'tipo', motivo: 'Tipo de resumen desconocido' }, 400);
        let tandas;
        try { tandas = await logisticaTandas(env, _r); } catch (_) { return _logiErrDb(); }
        const tanda = tandas.find(t => t.id === tandaId);
        if (!tanda) return json({ error: 'tanda', motivo: 'Esa semana ya no se puede modificar' }, 403);
        const kRes = 'logistica_resumen:' + tandaId, nowIso = new Date().toISOString();
        let claim = null;
        try { claim = await env.DB.prepare('INSERT INTO kv_cache (k, v, updated_at) VALUES (?, ?, ?) ON CONFLICT(k) DO UPDATE SET v=excluded.v, updated_at=excluded.updated_at WHERE kv_cache.updated_at < ? RETURNING k').bind(kRes, nowIso, nowIso, isoHace(10 * 60 * 1000)).first(); } catch (_) {}
        if (!claim) return json({ error: 'espera', motivo: 'Ya mandaste el resumen hace un momento' }, 429);
        let a;
        try { a = await logisticaArmar(env, tanda, { esUltima: tanda.id === tandas[0].id, conDirecciones: false }); }
        catch (_) { try { await env.DB.prepare("UPDATE kv_cache SET updated_at='1970-01-01T00:00:00.000Z' WHERE k=? AND v=?").bind(kRes, nowIso).run(); } catch (_) {} return _logiErrDb(); }
        const paqs = a.clientes.filter(c => c.logi).map(c => c.logi).sort((x, y) => (x.numero || 0) - (y.numero || 0));
        const cargados = paqs.filter(p => p.despachado);
        const quedan = paqs.filter(p => !p.despachado && p.ids.length);
        const operador = logiOperador(body, session);
        let texto = 'Logística · Envío del martes ' + corteMartesTxt(tanda.fecha_corte) + ': enviados ' + cargados.length
          + (quedan.length ? ' · quedan en el taller: ' + quedan.map(p => cortePad2(p.numero) + ' ' + String(p.cliente || '').trim() + ' (' + (p.bloqueo || 'no se envió') + ')').join(', ') : ' · no quedó nada en el taller');
        if (texto.length > 1400) texto = texto.slice(0, 1390) + '…';
        if (operador) texto += ' · ' + operador;
        try { await precotizNotifyGaspar(env, texto, { tipo: 'logistica', prioridad: 'P2' }); } catch (_) {}
        try { await logiLogStmt(env, tandaId, '', 'resumen', texto, operador, String(session.user || '')).run(); } catch (_) {}
        return json({ ok: true, texto });
      }
      // Vigía de logística (processLogiVigia).
      //  POST {eventos:[{tipo:'error'|'uso', accion, detalle?, key?, ms?}], operador?} → lo que pasa en la pantalla y el server
      //    no ve (errores de la página, sin conexión, WhatsApp / Copiar / Excel / Imprimir, "Enviado" frenado por impago).
      //  GET ?fecha=AAAA-MM-DD (solo admin) → estado del vigía, eventos del día y lo que avisaría ahora (sin mandar nada).
      if (path === '/admin/logistica/vigia') {
        const _r = await getSessionRole(env, session.user);
        if (request.method === 'POST') {
          if (!['logistica', 'admin'].includes(_r)) return json({ error: 'forbidden' }, 403);
          let body; try { body = await request.json(); } catch { body = {}; }
          const evs = (Array.isArray(body.eventos) ? body.eventos : []).slice(0, 25).filter(e => e && (e.tipo === 'error' || e.tipo === 'uso') && e.accion);
          if (!evs.length) return json({ ok: true, n: 0 });
          if (!(await ensureLogiVigiaSchema(env))) return json({ error: 'db' }, 500);
          const usuario = String(session.user || ''), operador = String(body.operador || '');
          try { await env.DB.batch(evs.map(e => logiVigiaStmt(env, { usuario, operador, origen: 'front', tipo: e.tipo, accion: e.accion, cliente_key: e.key, ms: e.ms, detalle: e.detalle }))); }
          catch (_) { return json({ error: 'db' }, 500); }
          return json({ ok: true, n: evs.length });
        }
        if (request.method === 'GET') {
          if (_r !== 'admin') return json({ error: 'forbidden' }, 403);
          try { return json(await logiVigiaEstado(env, url.searchParams.get('fecha'))); } catch (_) { return _logiErrDb(); }
        }
      }
      // POST /admin/logistica/password {password} → SOLO admin: crea/actualiza el usuario "logistica" con esa contraseña
      // (hash) y lo activa. Mientras no tenga contraseña queda INACTIVO (un usuario activo sin hash entra sin contraseña).
      // Cambiarla cierra las sesiones abiertas de logística.
      if (request.method === 'POST' && path === '/admin/logistica/password') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const pw = String(body.password || '');
        if (pw.length < 8) return json({ error: 'la contraseña tiene que tener al menos 8 caracteres' }, 400);
        const hash = await sha256hex(pw);
        try {
          await env.DB.prepare("INSERT INTO users_panel (id, nombre, rol, activo, password_hash, created_at) VALUES ('logistica', 'Logística', 'logistica', 1, ?, ?) ON CONFLICT(id) DO UPDATE SET password_hash=excluded.password_hash, rol='logistica', activo=1").bind(hash, new Date().toISOString()).run();
          // Sesiones de logística: el nombre se compara normalizado EN JS (el lower() de SQLite solo baja ASCII: una sesión
          // creada como "LOGÍSTICA" sobrevivía al cambio de contraseña). Solo las vigentes (las vencidas no sirven igual).
          const ses = (await env.DB.prepare('SELECT token, user FROM sessions WHERE expires_at > ?').bind(new Date().toISOString()).all()).results || [];
          const del = ses.filter(s => esUsuarioLogistica(s.user)).map(s => s.token);
          if (del.length) await env.DB.batch(del.map(t => env.DB.prepare('DELETE FROM sessions WHERE token = ?').bind(t)));
          try { await env.DB.prepare("DELETE FROM kv_cache WHERE k = 'login_fail:logistica'").run(); } catch (_) {}
        } catch (e) { return json({ error: String((e && e.message) || e) }, 500); }
        return json({ ok: true, usuario: 'logistica' });
      }
      // ===== SIN FRONTERA (usuario externo; ver esUsuarioSinFrontera) =====
      // Ellos: Producción (corpóreos con ticket, sin precio) + Mis pedidos (sus compras) + los archivos de eso + el estado.
      // Gaspar: lo mismo (para ver lo que ven) + contraseña del usuario + sus números + pedidos vinculados a mano.
      // ===== Tablero de producción de NEÓN (/admin/neon/*): todo el equipo menos productores, Sin Frontera y cursos =====
      if (path.startsWith('/admin/neon/')) {
        const ctx = await neonCtx(env, session);
        if (!['admin', 'comercial', 'produccion', 'logistica'].includes(ctx.rol)) return json({ error: 'forbidden' }, 403);
        // De producción, el tablero es solo de Neyen (despachos). Aníbal no tiene nada que marcar acá (Gaspar 17-oct).
        if (ctx.rol === 'produccion' && ctx.slug !== 'neyen') return json({ error: 'forbidden' }, 403);
        try { await ensureNeonTableroSchema(env); } catch (_) {}
        // GET /admin/neon/tablero → las tarjetas que le tocan ver a cada uno (vendedor: las suyas + cuántas hay del resto).
        if (request.method === 'GET' && path === '/admin/neon/tablero') {
          try { return json(await neonTablero(env, ctx)); } catch (e) { return json({ ok: false, error: 'No se pudo leer el tablero. Probá de nuevo en un momento.' }, 500); }
        }
        // GET /admin/neon/archivo?p=<id>&k=d|f[&i=n][&w=] → el diseño o una foto del terminado de un cartel que puede ver.
        if (request.method === 'GET' && path === '/admin/neon/archivo') {
          const pid = parseInt(url.searchParams.get('p'), 10) || 0, k = url.searchParams.get('k') === 'f' ? 'f' : 'd', i = Math.max(0, Math.min(20, parseInt(url.searchParams.get('i'), 10) || 0));
          if (!pid) return json({ error: 'falta p' }, 400);
          const fr = await neonTableroFilas(env, { ids: [pid] });
          const r = fr[0];
          if (!r) return json({ error: 'not found' }, 404);
          if (ctx.rol === 'comercial' && String(r.comercial_id || 'joaco') !== ctx.com) return json({ error: 'forbidden' }, 403);
          if (ctx.rol === 'logistica') {
            if (k === 'd') return json({ error: 'forbidden' }, 403);
            const gq = await neonGrupoDe(env, pid);
            if (!gq.yo || gq.yo._i < 5) return json({ error: 'forbidden' }, 403);
          }
          let key = '';
          if (k === 'd') key = String(r.corte_foto || r.foto_diseno_key || '').trim();
          else { const f = await env.DB.prepare('SELECT r2_key FROM pedido_prod_fotos WHERE pedido_id = ? ORDER BY id LIMIT 1 OFFSET ?').bind(pid, i).first(); key = f ? String(f.r2_key || '') : ''; }
          if (!key) return json({ error: 'not found' }, 404);
          return sfServirR2(env, key, url);
        }
        let body; try { body = await request.json(); } catch { body = {}; }
        const ids = [...new Set((Array.isArray(body.ids) ? body.ids : (body.pedido_id ? [body.pedido_id] : [])).map(x => parseInt(x, 10)).filter(n => n > 0))].slice(0, 90);
        const now = new Date().toISOString();
        // POST /admin/neon/accion {accion, ids, etapa?, motivo?}
        //   tomar / soltar   (Emma o Gaspar): "lo tomo" = el cartel pasa a En diseño y corte (estampa diseno_inicio_at en su pieza).
        //   recibido / no_recibido (Neyen o Gaspar): llegó al taller. Es un dato, no frena nada.
        //   ubicar (Gaspar): neon_piso = etapa mínima donde mostrarlo ('' = lo calcula solo). Para los que no se pueden ubicar.
        if (request.method === 'POST' && path === '/admin/neon/accion') {
          const acc = String(body.accion || '');
          if (!ids.length) return json({ error: 'faltan los carteles' }, 400);
          const ph = ids.map(() => '?').join(',');
          if (acc === 'tomar' || acc === 'soltar') {
            if (ctx.rol !== 'admin') return json({ error: 'Solo Gaspar' }, 403);
            const u = acc === 'tomar'
              ? await env.DB.prepare('UPDATE corte_pedidos SET diseno_inicio_at = COALESCE(diseno_inicio_at, ?), diseno_inicio_por = COALESCE(diseno_inicio_por, ?) WHERE pedido_id IN (' + ph + ") AND producto = 'NEON' AND estado = 'pedido'").bind(now, ctx.quien, ...ids).run()
              : await env.DB.prepare('UPDATE corte_pedidos SET diseno_inicio_at = NULL, diseno_inicio_por = NULL WHERE pedido_id IN (' + ph + ") AND producto = 'NEON' AND estado = 'pedido'").bind(...ids).run();
            return json({ ok: true, n: (u.meta && u.meta.changes) || 0 });
          }
          if (acc === 'recibido' || acc === 'no_recibido') {
            if (!(ctx.rol === 'admin' || (ctx.rol === 'produccion' && ctx.slug === 'neyen'))) return json({ error: 'Solo Neyen o Gaspar' }, 403);
            const u = acc === 'recibido'
              ? await env.DB.prepare('UPDATE pedidos SET recibido_at = COALESCE(recibido_at, ?), recibido_por = COALESCE(recibido_por, ?) WHERE id IN (' + ph + ') AND IFNULL(es_corporeo,0) = 0').bind(now, ctx.quien, ...ids).run()
              : await env.DB.prepare('UPDATE pedidos SET recibido_at = NULL, recibido_por = NULL WHERE id IN (' + ph + ') AND IFNULL(es_corporeo,0) = 0').bind(...ids).run();
            return json({ ok: true, n: (u.meta && u.meta.changes) || 0 });
          }
          if (acc === 'ubicar') {
            if (ctx.rol !== 'admin') return json({ error: 'Solo Gaspar' }, 403);
            const et = String(body.etapa || '');
            if (et && NEON_IDX[et] == null) return json({ error: 'etapa inválida' }, 400);
            if (et === 'enviado') return json({ error: 'Para cerrar uno que ya salió, usá "Marcar enviado" (así la planilla queda en Entregado).' }, 400);
            const mot = String(body.motivo || '').trim().slice(0, 200);
            let tIds = ids;
            if (et && NEON_IDX[et] >= NEON_IDX.pago) { const s = new Set(); for (const id of ids) { const gq = await neonGrupoDe(env, id); (gq.fr.length ? gq.fr.map(x => x.id) : [id]).forEach(x => s.add(x)); } tIds = [...s].slice(0, 90); }
            const u = await env.DB.prepare('UPDATE pedidos SET neon_piso = ?, neon_piso_at = ?, neon_piso_por = ?, neon_piso_motivo = ? WHERE id IN (' + tIds.map(() => '?').join(',') + ') AND IFNULL(es_corporeo,0) = 0').bind(et || null, et ? now : null, et ? ctx.quien : null, et ? mot : null, ...tIds).run();
            try { await prodLog(env, tIds.map(id => ({ pedido_id: id, campo: 'etapa', de: '', a: et || '(automática)', por: ctx.quien + (mot ? ' · ' + mot : '') }))); } catch (_) {}
            return json({ ok: true, n: (u.meta && u.meta.changes) || 0 });
          }
          return json({ error: 'acción inválida' }, 400);
        }
        // POST /admin/neon/despacho {pedido_id, modo, transporte?, seguimiento?, deshacer?} → salió (todo el pedido de neón).
        // Neyen, logística (solo "salió por envío") y Gaspar. Pone estado_pedido 'Entregado' (va a la planilla). Deshacer:
        // el mismo día (Gaspar siempre).
        if (request.method === 'POST' && path === '/admin/neon/despacho') {
          if (!ctx.despacha) return json({ error: 'Solo Neyen, logística o Gaspar' }, 403);
          const pid = ids[0];
          if (!pid) return json({ error: 'falta el cartel' }, 400);
          const { base, fr, serv, yo } = await neonGrupoDe(env, pid);
          if (!base || !yo) return json({ error: 'no encuentro ese cartel' }, 404);
          const adm = ctx.rol === 'admin', forzar = adm && !!body.forzar;
          if (body.deshacer) {
            if (yo._etapa !== 'enviado' || !yo.despachado_at) return json({ error: 'ese pedido no está marcado como enviado desde el tablero' }, 409);
            if (ctx.rol === 'logistica' && String(yo.despacho_modo || '') !== 'envio') return json({ error: 'Logística solo deshace los que salieron por envío. Pedíselo a Gaspar o a Neyen.' }, 403);
            const hoyAR = new Date(Date.now() - 3 * 3600e3).toISOString().slice(0, 10), diaAR = new Date(new Date(yo.despachado_at).getTime() - 3 * 3600e3).toISOString().slice(0, 10);
            if (!adm && diaAR !== hoyAR) return json({ error: 'Solo se puede deshacer el mismo día. Pedíselo a Gaspar.' }, 409);
            const dids = fr.concat(serv || []).filter(x => x.despachado_at).map(x => x.id);
            await env.DB.prepare("UPDATE pedidos SET estado_pedido = CASE WHEN IFNULL(despacho_prev_estado,'') = '' OR lower(despacho_prev_estado) LIKE 'entregad%' THEN 'para enviar' ELSE despacho_prev_estado END, despachado_at = NULL, despachado_por = NULL, despacho_modo = NULL, despacho_transporte = NULL, despacho_seguimiento = NULL, despacho_prev_estado = NULL, mirror_dirty = 1, mirror_attempts = 0, mirror_error = NULL, updated_at = ? WHERE id IN (" + dids.map(() => '?').join(',') + ')').bind(now, ...dids).run();
            try { await env.DB.prepare('INSERT INTO pedido_estado_log (pedido_id, numero, fecha, comercial_id, telefono, de, a, por, ts) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)').bind(pid, base.numero, base.fecha, base.comercial_id || 'joaco', base.telefono || '', 'Entregado', String(yo.despacho_prev_estado || 'para enviar'), ctx.quien + ' (deshizo el envío)', now).run(); } catch (_) {}
            return json({ ok: true, deshecho: true });
          }
          const modo = String(body.modo || '');
          if (!NEON_DESPACHO_MODOS[modo]) return json({ error: 'modo inválido' }, 400);
          if (ctx.rol === 'logistica' && modo !== 'envio') return json({ error: 'logística solo marca "salió por envío"' }, 403);
          if (yo._etapa === 'enviado') return json({ ok: true, sin_cambios: true });
          if (yo._etapa !== 'enviar' && !forzar) return json({ error: yo._etapa === 'pago' ? 'Todavía no está pagado: no sale.' : 'Todavía no está para enviar.', etapa: yo._etapa }, 409);
          // Gaspar 17-oct: "no se puede mandar algo que no está saldado" → ni forzado.
          if (fr.some(x => !x._pagado)) return json({ error: 'No está saldado: no sale. Cuando pague todo, registralo en Pedidos.', etapa: yo._etapa }, 409);
          // Sale el pedido entero: si otro cartel del pedido no está para enviar, no sale ninguno (Gaspar puede forzar).
          const faltan = fr.filter(x => x.id !== yo.id && x._etapa !== 'enviar' && x._etapa !== 'enviado');
          if (faltan.length && !forzar) return json({ error: faltan.length === 1 ? 'Otro cartel del pedido todavía no está para enviar.' : faltan.length + ' carteles del pedido todavía no están para enviar.', etapa: yo._etapa }, 409);
          const gids = fr.filter(x => x._etapa !== 'enviado').map(x => x.id).concat((serv || []).filter(x => !/^entregad/i.test(String(x.estado_pedido || ''))).map(x => x.id)), ph = gids.map(() => '?').join(',');
          const trans = String(body.transporte || '').trim().slice(0, 80), seg = String(body.seguimiento || '').trim().slice(0, 120);
          await env.DB.prepare("UPDATE pedidos SET despacho_prev_estado = IFNULL(estado_pedido,''), despachado_at = ?, despachado_por = ?, despacho_modo = ?, despacho_transporte = ?, despacho_seguimiento = ?, estado_pedido = 'Entregado', mirror_dirty = 1, mirror_attempts = 0, mirror_error = NULL, updated_at = ? WHERE id IN (" + ph + ')').bind(now, ctx.quien, modo, trans || null, seg || null, now, ...gids).run();
          try { await env.DB.prepare('INSERT INTO pedido_estado_log (pedido_id, numero, fecha, comercial_id, telefono, de, a, por, ts) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)').bind(pid, base.numero, base.fecha, base.comercial_id || 'joaco', base.telefono || '', base.estado_pedido || '', 'Entregado', ctx.quien + ' · ' + NEON_DESPACHO_MODOS[modo], now).run(); } catch (_) {}
          return json({ ok: true, n: gids.length });
        }
        return json({ error: 'not found' }, 404);
      }
      if (path.startsWith('/admin/sinfrontera/')) {
        const sfExt = esUsuarioSinFrontera(session.user);
        if (!sfExt && (await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        try { await ensureSinFronteraSchema(env); } catch (_) { return json({ error: 'db', motivo: 'No se pudo preparar la base. Probá de nuevo.' }, 500); }
        // GET /admin/sinfrontera/produccion → corpóreos en producción (sfProduccion).
        if (request.method === 'GET' && path === '/admin/sinfrontera/produccion') return json(await sfProduccion(env, { admin: !sfExt }));
        // GET /admin/sinfrontera/pedidos → sus pedidos (sfPedidos).
        if (request.method === 'GET' && path === '/admin/sinfrontera/pedidos') return json(await sfPedidos(env, { admin: !sfExt }));
        // GET /admin/sinfrontera/archivo?t=&i= | ?p=[&f=] [&w=] [&dl=1] → foto del ticket, diseño o foto del cartel terminado.
        if (request.method === 'GET' && path === '/admin/sinfrontera/archivo') {
          const key = await sfArchivoKey(env, url.searchParams);
          return key ? await sfServirR2(env, key, url) : json({ error: 'not found' }, 404);
        }
        // POST /admin/sinfrontera/estado {pedido_id, estado, quien?} → estado de producción de un corpóreo con ticket
        // (pedidos.prod_estado + pedido_prod_log). Cuando Sin Frontera lo deja listo o entregado, le avisa a Gaspar.
        if (request.method === 'POST' && path === '/admin/sinfrontera/estado') {
          let body; try { body = await request.json(); } catch { body = {}; }
          const pid = parseInt(body.pedido_id, 10) || 0, estado = String(body.estado || '');
          // '' = Por empezar (volver al principio o deshacer la primera movida).
          if (!pid || !(estado === '' || SF_ESTADOS.some(e => e[0] === estado))) return json({ error: 'datos', motivo: 'Elegí un estado de la lista.' }, 400);
          let ped = null;
          try { ped = await env.DB.prepare("SELECT p.cartel, IFNULL(p.prod_estado, '') AS prod_estado, p.numero, p.fecha, IFNULL(p.comercial_id, 'joaco') AS com, IFNULL(p.telefono, '') AS tel, IFNULL(p.estado_pedido, '') AS estado_pedido, (SELECT MAX(numero) FROM corporeo_tickets t WHERE t.pedido_id = p.id) AS ticket FROM pedidos p WHERE p.id = ? AND IFNULL(p.es_corporeo, 0) = 1 AND p.id NOT IN (SELECT pedido_id FROM sinfrontera_excluidos)").bind(pid).first(); } catch (_) {}
          if (!ped || !ped.ticket) return json({ error: 'nada', motivo: 'Ese corpóreo no está en producción.' }, 404);
          // Estado que ve el tablero: sin estado propio y el pedido ya Entregado (desde Pedidos) = entregado (igual que sfProduccion).
          const efPrev = ped.prod_estado || (/^entregad/i.test(ped.estado_pedido) ? 'entregado' : '');
          if (efPrev === estado) return json({ ok: true, estado, sin_cambios: true });
          const quien = String(body.quien || '').replace(/\s+/g, ' ').trim().slice(0, 40);
          const por = sfExt ? (quien ? quien + ' · Sin Frontera' : 'Sin Frontera') : String(session.user || '');
          const nowIso = new Date().toISOString();
          // Sin tocar updated_at: el estado de producción no va a la planilla (y así no se cruza con el espejo de pedidos).
          let ch = 0;
          try { const u = await env.DB.prepare("UPDATE pedidos SET prod_estado = ?, prod_estado_at = ? WHERE id = ? AND IFNULL(es_corporeo, 0) = 1 AND IFNULL(prod_estado, '') = ?").bind(estado, nowIso, pid, ped.prod_estado).run(); ch = (u && u.meta && u.meta.changes) || 0; }
          catch (_) { return json({ error: 'db', motivo: 'No se pudo guardar. Probá de nuevo.' }, 500); }
          if (!ch) return json({ error: 'cambio', motivo: 'Alguien lo cambió recién. Actualizá la lista y probá de nuevo.' }, 409);
          await prodLog(env, [{ pedido_id: pid, campo: 'estado', de: efPrev, a: estado, por }]);
          // Entregado = el pedido también queda Entregado (Gaspar, 15-oct); si lo vuelven atrás, vuelve a En produccion. Solo la
          // fila del corpóreo (en un pedido mixto el neón sigue su camino) y sin tocar updated_at: estado_pedido de los
          // corpóreos no va a la planilla. Queda en pedido_estado_log como cualquier cambio de estado.
          let estadoPedido = null;
          if (estado === 'entregado' && !/^entregad/i.test(ped.estado_pedido)) estadoPedido = 'Entregado';
          else if (efPrev === 'entregado' && estado !== 'entregado' && /^entregad/i.test(ped.estado_pedido)) estadoPedido = 'En produccion';
          if (estadoPedido) {
            try {
              await env.DB.prepare('UPDATE pedidos SET estado_pedido = ? WHERE id = ?').bind(estadoPedido, pid).run();
              try { await env.DB.prepare('INSERT INTO pedido_estado_log (pedido_id, numero, fecha, comercial_id, telefono, de, a, por, ts) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)').bind(pid, ped.numero, ped.fecha, ped.com, ped.tel, ped.estado_pedido, estadoPedido, por, nowIso).run(); } catch (_) {}
            } catch (_) { estadoPedido = null; }
          }
          // Avisos a Gaspar: En ensamble = las piezas pasan a su taller; listo y entregado.
          const _ord = ['', ...SF_ESTADOS.map(e => e[0])], _avanza = _ord.indexOf(estado) > _ord.indexOf(efPrev);
          if (sfExt && _avanza && (estado === 'en_ensamble' || estado === 'listo' || estado === 'entregado')) {
            const txt = 'Sin Frontera: el corpóreo "' + String(ped.cartel || '').trim() + '" (ticket #' + ped.ticket + ') ' + (estado === 'en_ensamble' ? 'pasó a ensamble: las piezas van a tu taller.' : estado === 'listo' ? 'está listo para entregar.' : 'ya está entregado.') + (quien ? ' Lo marcó ' + quien + '.' : '');
            const pr = avisoAdmin(env, txt, { tipo: 'sinfrontera_estado', prioridad: 'P2', clave: 'sf:' + pid + ':' + estado }).catch(() => {});
            try { ctx.waitUntil(pr); } catch (_) { await pr; }
          }
          return json({ ok: true, estado, at: nowIso, por, estado_pedido: estadoPedido || '' });
        }
        // ---- De acá para abajo, solo Gaspar ----
        if (sfExt) return json({ error: 'forbidden' }, 403);
        // POST /admin/sinfrontera/excluir {pedido_id, sacar: true|false} → "No lo hace Sin Frontera": lo saca de su tablero (no lo
        // ven ni pueden moverlo ni bajar sus archivos) o lo vuelve a sumar. No toca el pedido ni su estado.
        if (request.method === 'POST' && path === '/admin/sinfrontera/excluir') {
          let body; try { body = await request.json(); } catch { body = {}; }
          const pid = parseInt(body.pedido_id, 10) || 0;
          if (!pid) return json({ error: 'datos', motivo: 'Falta el pedido.' }, 400);
          try {
            if (body.sacar === false) await env.DB.prepare('DELETE FROM sinfrontera_excluidos WHERE pedido_id = ?').bind(pid).run();
            else await env.DB.prepare('INSERT OR IGNORE INTO sinfrontera_excluidos (pedido_id, por, at) VALUES (?, ?, ?)').bind(pid, String(session.user || ''), new Date().toISOString()).run();
          } catch (_) { return json({ error: 'db', motivo: 'No se pudo guardar. Probá de nuevo.' }, 500); }
          return json({ ok: true, sacado: body.sacar !== false });
        }
        // POST /admin/sinfrontera/password {password} → crea/actualiza el usuario "sinfrontera" con esa contraseña (hash) y lo
        // activa. No existe hasta que se la pone Gaspar (un usuario activo sin hash entraría sin contraseña). Cambiarla cierra
        // las sesiones abiertas de Sin Frontera.
        if (request.method === 'POST' && path === '/admin/sinfrontera/password') {
          let body; try { body = await request.json(); } catch { body = {}; }
          const pw = String(body.password || '');
          if (pw.length < 8) return json({ error: 'la contraseña tiene que tener al menos 8 caracteres' }, 400);
          const hash = await sha256hex(pw);
          try {
            await env.DB.prepare("INSERT INTO users_panel (id, nombre, rol, activo, password_hash, created_at) VALUES ('sinfrontera', 'Sin Frontera', 'sinfrontera', 1, ?, ?) ON CONFLICT(id) DO UPDATE SET password_hash=excluded.password_hash, rol='sinfrontera', activo=1").bind(hash, new Date().toISOString()).run();
            const ses = (await env.DB.prepare('SELECT token, user FROM sessions WHERE expires_at > ?').bind(new Date().toISOString()).all()).results || [];
            const del = ses.filter(s => esUsuarioSinFrontera(s.user)).map(s => s.token);
            if (del.length) await env.DB.batch(del.map(t => env.DB.prepare('DELETE FROM sessions WHERE token = ?').bind(t)));
            try { await env.DB.prepare("DELETE FROM kv_cache WHERE k = 'login_fail:sinfrontera'").run(); } catch (_) {}
          } catch (e) { return json({ error: String((e && e.message) || e) }, 500); }
          return json({ ok: true, usuario: 'sinfrontera' });
        }
        // GET|POST /admin/sinfrontera/config → sus números (kv sinfrontera_tels), los pedidos vinculados a mano y si el usuario ya
        // tiene contraseña. POST {telefonos?: [...], vincular?: [ids], desvincular?: [ids]}.
        if (path === '/admin/sinfrontera/config' && (request.method === 'GET' || request.method === 'POST')) {
          if (request.method === 'POST') {
            let body; try { body = await request.json(); } catch { body = {}; }
            if (Array.isArray(body.telefonos)) await kvSet(env, 'sinfrontera_tels', JSON.stringify(sfNormTels(body.telefonos)));
            const lim = a => [...new Set((Array.isArray(a) ? a : []).map(x => parseInt(x, 10)).filter(x => x > 0))].slice(0, 100);
            const nowIso = new Date().toISOString(), st = [];
            for (const id of lim(body.vincular)) st.push(env.DB.prepare('INSERT OR IGNORE INTO sinfrontera_pedidos (pedido_id, por, at) VALUES (?, ?, ?)').bind(id, String(session.user || ''), nowIso));
            for (const id of lim(body.desvincular)) st.push(env.DB.prepare('DELETE FROM sinfrontera_pedidos WHERE pedido_id = ?').bind(id));
            if (st.length) { try { await env.DB.batch(st); } catch (_) { return json({ error: 'db', motivo: 'No se pudo guardar. Probá de nuevo.' }, 500); } }
          }
          let usr = null;
          try { usr = await env.DB.prepare("SELECT activo, CASE WHEN IFNULL(password_hash, '') <> '' THEN 1 ELSE 0 END AS con_clave FROM users_panel WHERE id = 'sinfrontera'").first(); } catch (_) {}
          let vinc = [];
          try { vinc = ((await env.DB.prepare('SELECT pedido_id FROM sinfrontera_pedidos ORDER BY pedido_id').all()).results || []).map(r => r.pedido_id); } catch (_) {}
          const ped = await sfPedidos(env, { planilla: false });
          return json({ ok: true, telefonos: await sfTels(env), vinculados: vinc, pedidos_ids: (ped.pedidos || []).map(p => p.id), usuario: { existe: !!usr, activo: !!(usr && +usr.activo === 1), con_clave: !!(usr && +usr.con_clave === 1) } });
        }
        return json({ error: 'not found' }, 404);
      }
      // POST /admin/corte/paquete {tanda_id, key, largo, ancho, alto, peso?, bultos?} → medidas REALES del paquete (Neyen al
      // embalar). Reemplazan a la estimación en la vista de logística.
      if (request.method === 'POST' && path === '/admin/corte/paquete') {
        const _r = await getSessionRole(env, session.user);
        if (!['admin', 'produccion'].includes(_r)) return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const tandaId = parseInt(body.tanda_id, 10) || 0, key = String(body.key || '').slice(0, 80);
        const num = (v, max) => { const n = parseFloat(String(v == null ? '' : v).replace(',', '.')); return (n > 0 && n <= max) ? Math.round(n * 10) / 10 : null; };
        const largo = num(body.largo, 400), ancho = num(body.ancho, 400), alto = num(body.alto, 400), peso = num(body.peso, 200);
        // Bultos vacíos/inválidos → NULL: el UPDATE conserva lo que ya había (p. ej. lo que cargó logística en la tabla),
        // en vez de pisarlo con 1. Quien lee trata NULL como 1.
        const _b = parseInt(body.bultos, 10);
        const bultos = (_b > 0) ? Math.min(20, _b) : null;
        if (!tandaId || !key) return json({ error: 'faltan datos' }, 400);
        if (!(largo && ancho && alto)) return json({ error: 'largo, ancho y alto en cm (números)' }, 400);
        await ensureCortePaquetesSchema(env);
        try {
          await env.DB.prepare("INSERT INTO corte_paquetes (tanda_id, cliente_key, largo, ancho, alto, peso, bultos, medido_por, medido_at) VALUES (?,?,?,?,?,?,?,?,?) ON CONFLICT(tanda_id, cliente_key) DO UPDATE SET largo=excluded.largo, ancho=excluded.ancho, alto=excluded.alto, peso=excluded.peso, bultos=COALESCE(excluded.bultos, corte_paquetes.bultos), medido_por=excluded.medido_por, medido_at=excluded.medido_at")
            .bind(tandaId, key, largo, ancho, alto, peso, bultos, String(session.user || ''), new Date().toISOString()).run();
        } catch (e) { return json({ error: String((e && e.message) || e) }, 500); }
        return json({ ok: true });
      }
      // POST /admin/corte/pago-manual (SOLO admin) {telefono? | nombre?, tanda_ids?, metodo:'efectivo'|'transferencia'|'otro',
      // nota?, dry_run?} → marca PAGADO a mano lo que el cliente debe (CORTE_PAGABLE_SQL: no neón, precio>0, sin pagar; en
      // cualquier etapa, así también entra un adelanto), de todas sus tandas o de las que vengan. Condicional por id (lo que el vigía ya marcó no se toca), con
      // updated_at (el tablero lo ve). Quema en corte_pago_check los comprobantes entrantes de 72 h (el vigía no los rearma).
      // Planilla: una llamada por fecha de la hoja (caja 'Efectivo' si fue efectivo; si no, vacía), si corte_sheet_pago_on.
      // NO le manda nada al cliente. dry_run → solo devuelve lo que marcaría.
      if (request.method === 'POST' && path === '/admin/corte/pago-manual') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const metodo = String(body.metodo || '').toLowerCase().trim();
        if (!['efectivo', 'transferencia', 'otro'].includes(metodo)) return json({ error: 'metodo', motivo: 'Elegí cómo pagó: efectivo, transferencia u otro' }, 400);
        const sel = corteClienteSel(body);
        if (!sel) return json({ error: 'cliente', motivo: 'Falta el teléfono o el nombre del cliente' }, 400);
        if (!(await ensureCorteDespachoSchema(env))) return json({ error: 'db', motivo: 'No se pudo preparar la base. Probá de nuevo.' }, 500);
        try { await ensureCorteHojaSchema(env); } catch (_) {}
        const tandaIds = [...new Set((Array.isArray(body.tanda_ids) ? body.tanda_ids : []).map(x => parseInt(x, 10)).filter(Boolean))].slice(0, 50);
        const nota = String(body.nota || '').replace(/\s+/g, ' ').trim().slice(0, 300);
        const dry = body.dry_run === true;
        let rows;
        try {
          rows = ((await env.DB.prepare('SELECT id, tanda_id, telefono, cliente_nombre, hoja_cliente, hoja_fecha, diseno_nombre, producto, precio FROM corte_pedidos WHERE ' + sel.where + ' AND ' + CORTE_PAGABLE_SQL + (tandaIds.length ? ' AND tanda_id IN (' + tandaIds.map(() => '?').join(',') + ')' : '') + ' ORDER BY tanda_id, id').bind(...sel.binds, ...tandaIds).all()).results || []).filter(sel.match);
        } catch (e) { return json({ error: 'db', motivo: 'No se pudo leer la base. Probá de nuevo.' }, 500); }
        const fechaT = {};
        const tIds = [...new Set(rows.map(r => r.tanda_id).filter(Boolean))];
        if (tIds.length) { try { ((await env.DB.prepare('SELECT id, fecha_corte FROM corte_tandas WHERE id IN (' + tIds.map(() => '?').join(',') + ')').bind(...tIds).all()).results || []).forEach(t => { fechaT[t.id] = t.fecha_corte || ''; }); } catch (_) {} }
        const pieza = r => ({ id: r.id, tanda_id: r.tanda_id, fecha: r.hoja_fecha || fechaT[r.tanda_id] || '', diseno: r.diseno_nombre || r.producto || '', precio: Number(r.precio) || 0 });
        const totalDe = arr => Math.round(arr.reduce((s, r) => s + (Number(r.precio) || 0), 0));
        if (dry) return json({ ok: true, dry_run: true, piezas: rows.map(pieza), total: totalDe(rows), planilla: [] });
        if (!rows.length) return json({ error: 'nada', motivo: 'No tiene nada pendiente de pago' }, 409);
        const nowIso = new Date().toISOString(), quien = String(session.user || '');
        const ids = rows.map(r => r.id), ph = ids.map(() => '?').join(',');
        let hechas = [];
        try {
          await env.DB.prepare(`UPDATE corte_pedidos SET estado_pago='pagado', pago_metodo=?, pago_manual_por=?, pago_manual_at=?, pago_nota=?, updated_at=? WHERE id IN (${ph}) AND estado_pago IN ('pendiente','cobrando','parcial')`).bind(metodo, quien, nowIso, nota, nowIso, ...ids).run();
          const okIds = new Set(((await env.DB.prepare(`SELECT id FROM corte_pedidos WHERE id IN (${ph}) AND estado_pago='pagado' AND pago_manual_at=?`).bind(...ids, nowIso).all()).results || []).map(r => r.id));
          hechas = rows.filter(r => okIds.has(r.id));
        } catch (e) { return json({ error: 'db', motivo: 'No se pudo marcar el pago. Probá de nuevo.' }, 500); }
        if (!hechas.length) return json({ error: 'nada', motivo: 'Ya estaba pagado' }, 409);
        // Comprobantes recientes del teléfono → vistos (el vigía no los toma como pago de un cobro futuro). Si al teléfono le
        // queda OTRO cobro en curso (otra semana en 'cobrando': el admin destildó esa semana), los que llegaron DESPUÉS de ese
        // cobro no se queman: pueden ser el pago de esa semana y el vigía tiene que verlos. Referencia ≈
        // MIN(updated_at) de esas piezas (el cobro las estampa; después solo crece → en la duda se quema, como antes).
        if (sel.tel) {
          try { await env.DB.prepare('CREATE TABLE IF NOT EXISTS corte_pago_check (wamid TEXT PRIMARY KEY, phone TEXT, monto REAL, es_comprobante INTEGER, checked_at TEXT)').run(); } catch (_) {}
          try {
            let hasta = '';
            try { const q = await env.DB.prepare("SELECT MIN(updated_at) AS ref FROM corte_pedidos WHERE telefono=? AND estado_pago='cobrando' AND precio>0").bind(sel.tel).first(); hasta = (q && q.ref) || ''; } catch (_) {}
            const ims = (await env.DB.prepare("SELECT wamid FROM wa_messages WHERE phone=? AND direction='inbound' AND msg_type IN ('image','document') AND wamid IS NOT NULL AND wamid!='' AND ts > ?" + (hasta ? ' AND ts < ?' : '')).bind(sel.tel, isoHace(72 * 3600 * 1000), ...(hasta ? [hasta] : [])).all()).results || [];
            if (ims.length) await env.DB.batch(ims.map(m => env.DB.prepare('INSERT OR IGNORE INTO corte_pago_check (wamid, phone, monto, es_comprobante, checked_at) VALUES (?, ?, NULL, 0, ?)').bind(m.wamid, sel.tel, nowIso)));
          } catch (_) {}
        }
        // La cuenta de pagos en cuotas (corte_pago_parcial) deja de servir si ya no le queda nada en 'parcial'.
        if (sel.tel) { try { await env.DB.prepare("DELETE FROM corte_pago_parcial WHERE phone=? AND NOT EXISTS (SELECT 1 FROM corte_pedidos WHERE telefono=? AND estado_pago='parcial')").bind(sel.tel, sel.tel).run(); } catch (_) {} }
        // Planilla (Venta_Insumos): una vez por FECHA de la hoja, con el nombre TAL CUAL en la hoja (hoja_cliente). Un error
        // transitorio (token/HTTP) va a la cola de reintentos del vigía (clave por cliente+fecha: no se pisan entre sí).
        const planilla = [];
        if ((await kvGet(env, 'corte_sheet_pago_on', '1')) === '1') {
          const caja = metodo === 'efectivo' ? 'Efectivo' : '';
          const grupos = {};
          for (const r of hechas) {
            const f = r.hoja_fecha || fechaT[r.tanda_id] || '(sin fecha)';
            const g = (grupos[f] = grupos[f] || { fecha: f, total: 0, nombres: {} });
            g.total += Number(r.precio) || 0;
            const nm = String(r.hoja_cliente || r.cliente_nombre || '').trim();
            if (nm) g.nombres[nm] = (g.nombres[nm] || 0) + 1;
          }
          for (const g of Object.values(grupos)) {
            const cliente = (Object.entries(g.nombres).sort((a, b) => b[1] - a[1])[0] || [''])[0];
            const tot = Math.round(g.total);
            let sr = null;
            try { sr = await corteMarcarPagadoSheet(env, cliente, tot, caja, g.fecha === '(sin fecha)' ? '' : g.fecha); } catch (e) { sr = { error: 'error de planilla', _exc: true }; }
            if (sr && sr.ok) planilla.push({ fecha: g.fecha, ok: true });
            else {
              const err = String((sr && sr.error) || 'error de planilla');
              planilla.push({ fecha: g.fecha, ok: false, error: err });
              if ((sr && sr._exc) || /token|HTTP/i.test(err)) await corteSheetPendingAdd(env, (sel.tel || sel.key) + '|' + g.fecha, cliente, tot, caja);
            }
          }
        }
        return json({ ok: true, dry_run: false, piezas: hechas.map(pieza), total: totalDe(hechas), planilla });
      }
      // POST /admin/corte/retiro (admin|produccion) {telefono? | nombre?, ids?, deshacer?} → "Retiró" en el taller: las piezas
      // del cliente con entrega='retira' en 'cortado'/'embalado' (de cualquier tanda; o solo esos ids) pasan a 'entregado'.
      // Con deuda (regla única) → 409 impago (decisión: primero "Marcar pagado"). Deshacer: vuelven a 'embalado' las del
      // último retiro (mismo entregado_at); producción solo el mismo día AR, admin siempre.
      if (request.method === 'POST' && path === '/admin/corte/retiro') {
        const _r = await getSessionRole(env, session.user);
        if (!['admin', 'produccion'].includes(_r)) return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const sel = corteClienteSel(body);
        if (!sel) return json({ error: 'cliente', motivo: 'Falta el teléfono o el nombre del cliente' }, 400);
        if (!(await ensureCorteDespachoSchema(env))) return json({ error: 'db', motivo: 'No se pudo preparar la base. Probá de nuevo.' }, 500);
        const idsF = [...new Set((Array.isArray(body.ids) ? body.ids : []).map(x => parseInt(x, 10)).filter(Boolean))].slice(0, 300);
        const fIds = idsF.length ? ' AND id IN (' + idsF.map(() => '?').join(',') + ')' : '';
        const nowIso = new Date().toISOString(), quien = String(session.user || '');
        if (body.deshacer === true) {
          let rows;
          try { rows = ((await env.DB.prepare("SELECT id, telefono, cliente_nombre, entregado_at FROM corte_pedidos WHERE " + sel.where + " AND estado='entregado' AND entregado_at IS NOT NULL AND IFNULL(producto,'')!='NEON'" + fIds).bind(...sel.binds, ...idsF).all()).results || []).filter(sel.match); }
          catch (_) { return json({ error: 'db', motivo: 'No se pudo leer la base. Probá de nuevo.' }, 500); }
          if (!rows.length) return json({ error: 'nada', motivo: 'No hay nada para deshacer' }, 409);
          const ultimo = rows.map(r => r.entregado_at).sort().pop();
          if (_r !== 'admin' && corteArYmd(ultimo) !== corteArYmd(nowIso)) return json({ error: 'no_deshacer', motivo: 'Ya no se puede deshacer' }, 409);
          const ids = rows.filter(r => r.entregado_at === ultimo).map(r => r.id);
          let n = 0;
          try { const u = await env.DB.prepare(`UPDATE corte_pedidos SET estado='embalado', entregado_at=NULL, entregado_por=NULL, updated_at=? WHERE id IN (${ids.map(() => '?').join(',')}) AND estado='entregado' AND entregado_at=?`).bind(nowIso, ...ids, ultimo).run(); n = (u.meta && u.meta.changes) || 0; }
          catch (_) { return json({ error: 'db', motivo: 'No se pudo deshacer. Probá de nuevo.' }, 500); }
          return json({ ok: true, piezas: n });
        }
        let rows;
        try { rows = ((await env.DB.prepare("SELECT id, telefono, cliente_nombre FROM corte_pedidos WHERE " + sel.where + " AND entrega='retira' AND estado IN ('cortado','embalado') AND IFNULL(producto,'')!='NEON' AND lower(IFNULL(cliente_nombre,''))!='neon'" + fIds).bind(...sel.binds, ...idsF).all()).results || []).filter(sel.match); }
        catch (_) { return json({ error: 'db', motivo: 'No se pudo leer la base. Probá de nuevo.' }, 500); }
        if (!rows.length) return json({ error: 'nada', motivo: 'No hay piezas para entregar' }, 409);
        const deuda = await corteDeudaKeys(env);
        if (corteTieneDeuda(deuda, sel.key, [body.nombre, ...rows.map(r => r.cliente_nombre)])) return json({ error: 'impago', motivo: 'Falta el pago: avisale a Gaspar' }, 409);
        const ids = rows.map(r => r.id);
        let n = 0;
        // Sin entrega_manual: 'entregado' ya queda fuera de la sync con la planilla, y así el "Deshacer" no deja la pieza
        // trabada en 'retira' para siempre (la marca no se podía restaurar: no se sabe si ya estaba puesta por el admin).
        try { const u = await env.DB.prepare(`UPDATE corte_pedidos SET estado='entregado', entregado_at=?, entregado_por=?, updated_at=? WHERE id IN (${ids.map(() => '?').join(',')}) AND estado IN ('cortado','embalado') AND entrega='retira'`).bind(nowIso, quien, nowIso, ...ids).run(); n = (u.meta && u.meta.changes) || 0; }
        catch (_) { return json({ error: 'db', motivo: 'No se pudo marcar el retiro. Probá de nuevo.' }, 500); }
        return json({ ok: true, piezas: n });
      }
      // GET /admin/corte/etiquetas?tanda_id= (admin|produccion; sin tanda_id = la más reciente con fecha de corte) → una
      // entrada por cliente (y otra si además retira piezas en el taller), con el N° estable de la semana (los asigna si
      // falta), dirección (la corregida/completada por logística o el texto de LTV: logiDirEtiqueta), cantidades y bultos.
      // Incluye el arrastre de envío. Sin montos. Orden por N°. Sin LTV leída (ni la copia en memoria) van TODAS sin
      // dirección, como antes: el front no imprime (ltv_error) en vez de sacar unas con el texto guardado y otras sin nada.
      if (request.method === 'GET' && path === '/admin/corte/etiquetas') {
        const _r = await getSessionRole(env, session.user);
        if (!['admin', 'produccion'].includes(_r)) return json({ error: 'forbidden' }, 403);
        let ultima = null, tanda = null;
        try {
          ultima = await env.DB.prepare("SELECT id, fecha_corte FROM corte_tandas WHERE fecha_corte IS NOT NULL AND fecha_corte!='' ORDER BY id DESC LIMIT 1").first();
          const pedida = parseInt(url.searchParams.get('tanda_id'), 10) || 0;
          tanda = pedida ? await env.DB.prepare("SELECT id, fecha_corte FROM corte_tandas WHERE id=? AND fecha_corte IS NOT NULL AND fecha_corte!=''").bind(pedida).first() : ultima;
        } catch (_) { return json({ error: 'db', motivo: 'No se pudo leer la base. Probá de nuevo.' }, 500); }
        if (!tanda) return json({ error: 'tanda', motivo: 'No hay una semana de corte cargada' }, 404);
        let a;
        try { a = await logisticaArmar(env, tanda, { esUltima: !!(ultima && ultima.id === tanda.id), conDirecciones: true }); }
        catch (_) { return json({ error: 'db', motivo: 'No se pudo leer la base. Probá de nuevo.' }, 500); }
        const cant = arr => arr.reduce((s, x) => s + (Math.max(1, parseInt(x.cantidad, 10) || 1)), 0);
        const etiquetas = [];
        for (const c of a.clientes) {
          if (c.logi) etiquetas.push({ numero: c.numero, key: c.key, cliente: c.nombre, telefono: c.telefono, entrega: c.logi.entrega, direccion: a.ltv_ok ? logiDirEtiqueta(c.logi) : '', piezas: cant(c.logi.piezas), insumos: cant(c.logi.insumos), bultos: Math.max(1, parseInt(c.logi.paquete && c.logi.paquete.bultos, 10) || 1), arrastre: c.logi.arrastre });
          if (c.ret.length) {
            const rv = c.ret.filter(p => p.estado === 'cortado' || p.estado === 'embalado'); // lo que está en el taller
            const lr = rv.length ? rv : c.ret;
            etiquetas.push({ numero: c.numero, key: c.key, cliente: c.nombre, telefono: c.telefono, entrega: 'retira', direccion: '', piezas: cant(lr.filter(p => corteMedidaPieza(p))), insumos: cant(lr.filter(p => !corteMedidaPieza(p))), bultos: c.logi ? 1 : Math.max(1, parseInt(c.mkCur.bultos, 10) || 1), arrastre: null });
          }
        }
        etiquetas.sort((x, y) => ((x.numero == null ? 1e9 : x.numero) - (y.numero == null ? 1e9 : y.numero)) || ((x.entrega === 'retira') - (y.entrega === 'retira')));
        return json({ ok: true, tanda: { id: tanda.id, fecha: tanda.fecha_corte, martes: corteMartesTxt(tanda.fecha_corte) }, ltv_error: a.ltv_error, etiquetas });
      }
      // POST /admin/corte/backfill-despacho (SOLO admin) {tanda_ids, excluir?: [teléfonos | claves 'n:...' | nombres],
      // dry_run? (default TRUE)} → las piezas viejas que ya salieron pero quedaron 'embalado' (nadie las marcaba): no neón,
      // 'embalado' y PAGADAS (pagado/interno) o en $0 (no son deuda, nunca se cobran: si quedaban 'embalado' volvían como
      // paquete fantasma por arrastre). Envío → 'despachado'; retira → 'entregado'; sin definir → no se tocan. Fecha =
      // martes de esa semana a las 12:00 AR. NO toca updated_at (si no, 180 días de historia vuelven al tablero).
      // El dry_run trae además `impagas`: la deuda (regla única) de esas semanas y anteriores, por cliente, para limpiarla
      // con "Marcar pagado" ANTES de prender la logística (si no, esos clientes figuran "Pedido impago" y no se cargan).
      if (request.method === 'POST' && path === '/admin/corte/backfill-despacho') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const tandaIds = [...new Set((Array.isArray(body.tanda_ids) ? body.tanda_ids : []).map(x => parseInt(x, 10)).filter(Boolean))].slice(0, 60);
        if (!tandaIds.length) return json({ error: 'faltan_datos', motivo: 'Pasá tanda_ids' }, 400);
        const dry = body.dry_run !== false;
        if (!(await ensureCorteDespachoSchema(env))) return json({ error: 'db', motivo: 'No se pudo preparar la base. Probá de nuevo.' }, 500);
        const exKeys = new Set(), exNombres = new Set();
        for (const s of (Array.isArray(body.excluir) ? body.excluir : [])) {
          const t = String(s || '').trim(); if (!t) continue;
          exKeys.add(t);
          const dig = t.replace(/\D/g, ''); if (dig.length >= 8 && dig.length === t.replace(/[\s+\-()]/g, '').length) exKeys.add(dig);
          const nn = corteNormNombre(t.startsWith('n:') ? t.slice(2) : t); if (nn && !/^\d+$/.test(nn)) exNombres.add(nn);
        }
        const ph = tandaIds.map(() => '?').join(',');
        let tandas, rows;
        try {
          tandas = (await env.DB.prepare(`SELECT id, fecha_corte FROM corte_tandas WHERE id IN (${ph})`).bind(...tandaIds).all()).results || [];
          rows = (await env.DB.prepare(`SELECT id, tanda_id, telefono, cliente_nombre, entrega FROM corte_pedidos WHERE tanda_id IN (${ph}) AND estado='embalado' AND (estado_pago IN ('pagado','interno') OR IFNULL(precio,0)<=0) AND IFNULL(producto,'')!='NEON' AND lower(IFNULL(cliente_nombre,''))!='neon' ORDER BY tanda_id, cliente_nombre, id`).bind(...tandaIds).all()).results || [];
        } catch (_) { return json({ error: 'db', motivo: 'No se pudo leer la base. Probá de nuevo.' }, 500); }
        const nowIso = new Date().toISOString();
        const tInfo = {};
        tandas.forEach(t => { const d = corteMartesDate(t.fecha_corte); tInfo[t.id] = { fecha: t.fecha_corte || '', ts: d ? new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), 15)).toISOString() : nowIso }; });
        const grupos = {};
        for (const p of rows) {
          const k = corteClaveCliente(p);
          if (exKeys.has(k) || (p.telefono && exKeys.has(String(p.telefono))) || exNombres.has(corteNormNombre(p.cliente_nombre))) continue;
          const gk = p.tanda_id + '|' + k + '|' + (p.entrega || '');
          const nuevo = p.entrega === 'envio' ? 'despachado' : (p.entrega === 'retira' ? 'entregado' : null);
          (grupos[gk] = grupos[gk] || { tanda_id: p.tanda_id, fecha: (tInfo[p.tanda_id] || {}).fecha || '', cliente: p.cliente_nombre, telefono: p.telefono || '', entrega: p.entrega || 'sin definir', ids: [], nuevo_estado: nuevo }).ids.push(p.id);
        }
        const detalle = Object.values(grupos);
        const piezas = detalle.filter(g => g.nuevo_estado).reduce((s, g) => s + g.ids.length, 0);
        if (!dry) {
          const stmts = detalle.filter(g => g.nuevo_estado).map(g => {
            const ts = (tInfo[g.tanda_id] || {}).ts || nowIso, phI = g.ids.map(() => '?').join(',');
            return g.nuevo_estado === 'despachado'
              ? env.DB.prepare(`UPDATE corte_pedidos SET estado='despachado', despachado_at=? WHERE id IN (${phI}) AND estado='embalado' AND (estado_pago IN ('pagado','interno') OR IFNULL(precio,0)<=0)`).bind(ts, ...g.ids)
              : env.DB.prepare(`UPDATE corte_pedidos SET estado='entregado', entregado_at=?, entregado_por='backfill' WHERE id IN (${phI}) AND estado='embalado' AND (estado_pago IN ('pagado','interno') OR IFNULL(precio,0)<=0)`).bind(ts, ...g.ids);
          });
          try { for (let i = 0; i < stmts.length; i += 50) await env.DB.batch(stmts.slice(i, i + 50)); }
          catch (e) { return json({ error: 'db', motivo: 'Falló a mitad del backfill (lo hecho queda hecho; se puede volver a correr).', detalle }, 500); }
        }
        // Deuda vieja (solo en el dry_run): cualquier pieza que cuente como deuda en esas semanas o anteriores, por cliente.
        let impagas = [];
        if (dry) {
          try {
            const maxT = Math.max(...tandaIds);
            const dr = (await env.DB.prepare('SELECT tanda_id, telefono, cliente_nombre, estado_pago, COUNT(*) AS n, COALESCE(SUM(precio),0) AS total FROM corte_pedidos WHERE ' + CORTE_DEUDA_SQL + ' AND (tanda_id IS NULL OR tanda_id <= ?) GROUP BY tanda_id, telefono, cliente_nombre, estado_pago ORDER BY tanda_id, cliente_nombre').bind(maxT).all()).results || [];
            const fT = {};
            const dIds = [...new Set(dr.map(r => r.tanda_id).filter(Boolean))];
            if (dIds.length) ((await env.DB.prepare('SELECT id, fecha_corte FROM corte_tandas WHERE id IN (' + dIds.map(() => '?').join(',') + ')').bind(...dIds).all()).results || []).forEach(t => { fT[t.id] = t.fecha_corte || ''; });
            const porCli = {};
            for (const r of dr) {
              const k = corteClaveCliente(r);
              const c = (porCli[k] = porCli[k] || { key: k, cliente: r.cliente_nombre, telefono: r.telefono || '', piezas: 0, total: 0, tandas: [] });
              c.piezas += Number(r.n) || 0; c.total += Math.round(Number(r.total) || 0);
              c.tandas.push({ tanda_id: r.tanda_id, fecha: fT[r.tanda_id] || '', estado_pago: r.estado_pago, piezas: Number(r.n) || 0, total: Math.round(Number(r.total) || 0) });
            }
            impagas = Object.values(porCli);
          } catch (_) { impagas = null; } // null = no se pudo leer (distinto de "no hay")
        }
        return json({ ok: true, dry_run: dry, detalle, piezas, ...(dry ? { impagas } : {}) });
      }
      // POST /admin/corte/pedido → colas operativas: transición de estado + carga de datos, por rol.
      // body { id, action, ... }. action: 'medidas' (Emma: ancho_real/alto_real/matriz → matriz_lista + precio),
      // 'cortado' (Aníbal/produccion), 'embalado' (Neyen/produccion: entrega retira/envio), 'estado' (admin libre).
      if (request.method === 'POST' && path === '/admin/corte/pedido') {
        const _role = await getSessionRole(env, session.user);
        if (!['admin', 'disenador', 'produccion'].includes(_role)) return json({ error: 'forbidden' }, 403);
        try { await ensureCorteNeonSchema(env); } catch (_) {} // columnas nuevas (disenado_at) antes de los UPDATE
        let body; try { body = await request.json(); } catch { body = {}; }
        const action = String(body.action || '');
        const nowIso = new Date().toISOString();
        const _slug = String(session.user || '').toLowerCase();
        // Fechas del despacho coherentes con el estado (las leen el copiloto y el deshacer de logística): al entrar a
        // despachado/entregado se estampan (si no tenían); al volver a un estado anterior se limpian.
        const _desp = await ensureCorteDespachoSchema(env);
        const _despSet = (est) => _desp ? { sql: ", despachado_at = CASE WHEN ?='despachado' THEN COALESCE(despachado_at, ?) WHEN ?='entregado' THEN despachado_at ELSE NULL END, entregado_at = CASE WHEN ?='entregado' THEN COALESCE(entregado_at, ?) ELSE NULL END", binds: [est, nowIso, est, est, nowIso] } : { sql: '', binds: [] };
        // Producción (Neyen/Aníbal) NO puede hacer retroceder piezas que ya salieron (una pantalla vieja o el Deshacer de
        // Neyen devolvían a 'cortado' piezas despachadas). El admin sí.
        const _noSalidas = _role !== 'admin' ? " AND estado NOT IN ('despachado','entregado')" : '';
        // Acciones MASIVAS (sin id puntual): Aníbal corta toda la tanda; Neyen embala el paquete de un cliente.
        if (action === 'cortado_bulk') {
          if (!['admin', 'produccion'].includes(_role)) return json({ error: 'forbidden' }, 403);
          try { const rr = await env.DB.prepare("UPDATE corte_pedidos SET estado='cortado', productor=?, updated_at=? WHERE estado='matriz_lista'").bind(_slug, nowIso).run(); return json({ ok: true, action, n: (rr.meta && rr.meta.changes) || 0 }); } catch (e) { return json({ error: String((e && e.message) || e) }, 500); }
        }
        if (action === 'embalado_bulk') {
          if (!['admin', 'produccion'].includes(_role)) return json({ error: 'forbidden' }, 403);
          const tel = String(body.telefono || '').replace(/\D/g, '');
          if (!tel) return json({ error: 'falta telefono' }, 400);
          // Embalar NO toca la entrega: la única fuente es la planilla de cortes (sync). Antes mandaba 'retira' por default y
          // pisaba lo correcto (Martin Guaragna quedó "retira" yendo por envío, 5/10). Se ignora body.entrega a propósito
          // (también la de pestañas con el app.js viejo cacheado).
          try { const rr = await env.DB.prepare("UPDATE corte_pedidos SET estado='embalado', updated_at=? WHERE estado='cortado' AND telefono=?").bind(nowIso, tel).run(); return json({ ok: true, action, n: (rr.meta && rr.meta.changes) || 0 }); } catch (e) { return json({ error: String((e && e.message) || e) }, 500); }
        }
        // Selección múltiple: mueve una LISTA de pedidos (ids) al estado destino. produccion solo puede
        // cortado/embalado; admin puede cualquier estado. Usado por la barra de acciones masivas del board.
        if (action === 'avanzar_bulk') {
          if (!['admin', 'produccion'].includes(_role)) return json({ error: 'forbidden' }, 403);
          const ids = (Array.isArray(body.ids) ? body.ids : []).map(x => parseInt(x, 10)).filter(Boolean).slice(0, 300);
          const est = String(body.estado || '');
          if (!ids.length) return json({ error: 'sin ids' }, 400);
          if (!['pedido', 'matriz_lista', 'cortado', 'embalado', 'cobrado', 'despachado', 'entregado'].includes(est)) return json({ error: 'estado inválido' }, 400);
          if (_role !== 'admin' && !['cortado', 'embalado'].includes(est)) return json({ error: 'solo admin puede mover a ese estado' }, 403);
          const ph = ids.map(() => '?').join(',');
          try {
            let rr;
            // disenado_at: si la pieza estaba 'pedido' y se la saltea a un paso posterior, ese es su momento de diseño
            // (en SQLite los SET leen los valores VIEJOS → 'estado' en el CASE es el estado anterior al UPDATE).
            const _dis = `disenado_at = CASE WHEN estado='pedido' AND ?<>'pedido' THEN COALESCE(disenado_at, ?) ELSE disenado_at END`;
            // Embalar: solo piezas 'cortado' (no hace retroceder despachadas/entregadas) y sin tocar la entrega (ver embalado_bulk).
            if (est === 'embalado') rr = await env.DB.prepare(`UPDATE corte_pedidos SET ${_dis}, estado='embalado', updated_at=? WHERE id IN (${ph}) AND estado='cortado'`).bind(est, nowIso, nowIso, ...ids).run();
            else if (est === 'cortado') { const d = _despSet('cortado'); rr = await env.DB.prepare(`UPDATE corte_pedidos SET ${_dis}, estado='cortado', productor=?, updated_at=?${d.sql} WHERE id IN (${ph})${_noSalidas}`).bind(est, nowIso, _slug, nowIso, ...d.binds, ...ids).run(); }
            else { const d = _despSet(est); rr = await env.DB.prepare(`UPDATE corte_pedidos SET ${_dis}, estado=?, updated_at=?${d.sql} WHERE id IN (${ph})`).bind(est, nowIso, est, nowIso, ...d.binds, ...ids).run(); }
            if (est === 'cortado' || est === 'embalado') await neonCorteStamp(env, ids, est === 'cortado' ? 'cortado_at' : 'separado_at');
            if (est === 'embalado') await neonCorteStamp(env, ids, 'cortado_at');
            return json({ ok: true, action, estado: est, n: (rr.meta && rr.meta.changes) || 0 });
          } catch (e) { return json({ error: String((e && e.message) || e) }, 500); }
        }
        // Entrega a mano (SOLO admin) {ids, entrega:'envio'|'retira'} → entrega_manual=1: la sincronización con la planilla ya
        // no la pisa. Sirve para destrabar un 'sin definir' sin esperar a la planilla. No toca despachadas/entregadas ni neón.
        if (action === 'entrega') {
          if (_role !== 'admin') return json({ error: 'solo admin' }, 403);
          const ids = (Array.isArray(body.ids) ? body.ids : (body.id ? [body.id] : [])).map(x => parseInt(x, 10)).filter(Boolean).slice(0, 300);
          const ent = String(body.entrega || '');
          if (!ids.length) return json({ error: 'sin ids' }, 400);
          if (!['envio', 'retira'].includes(ent)) return json({ error: 'entrega inválida (envio o retira)' }, 400);
          if (!_desp) return json({ error: 'no se pudo preparar la base' }, 500);
          try { const rr = await env.DB.prepare(`UPDATE corte_pedidos SET entrega=?, entrega_manual=1, updated_at=? WHERE id IN (${ids.map(() => '?').join(',')}) AND estado NOT IN ('despachado','entregado') AND IFNULL(producto,'')!='NEON'`).bind(ent, nowIso, ...ids).run(); return json({ ok: true, action, entrega: ent, n: (rr.meta && rr.meta.changes) || 0 }); } catch (e) { return json({ error: String((e && e.message) || e) }, 500); }
        }
        // Acciones sobre un pedido puntual (requieren id).
        const id = parseInt(body.id, 10);
        if (!id) return json({ error: 'falta id' }, 400);
        const ped = await env.DB.prepare("SELECT * FROM corte_pedidos WHERE id=?").bind(id).first();
        if (!ped) return json({ error: 'pedido no existe' }, 404);
        try {
          if (action === 'medidas') {
            if (!['admin', 'disenador'].includes(_role)) return json({ error: 'solo el diseñador' }, 403);
            // Solo piezas que esperan su matriz: un doble envío o una pantalla vieja no puede devolver a
            // 'matriz_lista' una pieza que Aníbal ya cortó.
            if (ped.estado !== 'pedido') return json({ error: 'esa pieza ya no está para diseñar (se actualizó la lista)' }, 409);
            const ancho = parseFloat(String(body.ancho_real != null ? body.ancho_real : '').replace(',', '.')) || 0;
            const alto = parseFloat(String(body.alto_real != null ? body.alto_real : '').replace(',', '.')) || 0;
            if (!(ancho > 0 && alto > 0)) return json({ error: 'ancho y alto (cm) requeridos' }, 400);
            const cant = Math.max(1, parseInt(ped.cantidad, 10) || 1);
            // Neón PROPIO: sin precio (no se cobra, decisión de Gaspar) y entra a la tanda de la semana en
            // que Emma la diseña (no a la de cuando se cargó el pedido) → cuenta en el corte real.
            const esNeonPropio = String(ped.producto || '') === 'NEON';
            const _m2 = esNeonPropio ? 0 : (parseInt(await kvGet(env, 'corte_precio_m2', '175000'), 10) || 175000); // el mismo de la landing
            const precio = esNeonPropio ? 0 : (ancho / 100) * (alto / 100) * _m2 * cant; // exacto, sin redondear
            const matrizKey = String(body.matriz_key != null ? body.matriz_key : (ped.matriz_key || ''));
            const matrizUrl = String(body.matriz_drive_url != null ? body.matriz_drive_url : (ped.matriz_drive_url || ''));
            let tandaId = ped.tanda_id;
            if (esNeonPropio) { const _t = await corteTandaActual(env); if (_t) tandaId = _t.id; }
            await env.DB.prepare("UPDATE corte_pedidos SET ancho_real=?, alto_real=?, precio=?, matriz_key=?, matriz_drive_url=?, tanda_id=?, estado='matriz_lista', disenado_at=?, updated_at=? WHERE id=?").bind(ancho, alto, precio, matrizKey, matrizUrl, tandaId, nowIso, nowIso, id).run();
            return json({ ok: true, id, estado: 'matriz_lista', precio });
          }
          if (action === 'cortado') {
            if (!['admin', 'produccion'].includes(_role)) return json({ error: 'forbidden' }, 403);
            const d = _despSet('cortado');
            const u = await env.DB.prepare(`UPDATE corte_pedidos SET estado='cortado', productor=?, updated_at=?${d.sql} WHERE id=?${_noSalidas}`).bind(_slug, nowIso, ...d.binds, id).run();
            if (!((u.meta && u.meta.changes) || 0)) return json({ error: 'esa pieza ya salió (despachada o entregada): no se puede volver atrás' }, 409);
            await neonCorteStamp(env, [id], 'cortado_at');
            return json({ ok: true, id, estado: 'cortado' });
          }
          if (action === 'embalado') {
            if (!['admin', 'produccion'].includes(_role)) return json({ error: 'forbidden' }, 403);
            // No toca la entrega (sale solo de la planilla de cortes; ver embalado_bulk).
            const d = _despSet('embalado');
            const u = await env.DB.prepare(`UPDATE corte_pedidos SET estado='embalado', updated_at=?${d.sql} WHERE id=?${_noSalidas}`).bind(nowIso, ...d.binds, id).run();
            if (!((u.meta && u.meta.changes) || 0)) return json({ error: 'esa pieza ya salió (despachada o entregada): no se puede volver atrás' }, 409);
            return json({ ok: true, id, estado: 'embalado', entrega: ped.entrega || '' });
          }
          if (action === 'estado') {
            if (_role !== 'admin') return json({ error: 'solo admin' }, 403);
            const est = String(body.estado || '');
            if (!['pedido', 'matriz_lista', 'cortado', 'embalado', 'cobrado', 'despachado', 'entregado'].includes(est)) return json({ error: 'estado inválido' }, 400);
            const d = _despSet(est);
            await env.DB.prepare(`UPDATE corte_pedidos SET disenado_at = CASE WHEN estado='pedido' AND ?<>'pedido' THEN COALESCE(disenado_at, ?) ELSE disenado_at END, estado=?, updated_at=?${d.sql} WHERE id=?`).bind(est, nowIso, est, nowIso, ...d.binds, id).run();
            return json({ ok: true, id, estado: est });
          }
        } catch (e) { return json({ error: String((e && e.message) || e) }, 500); }
        return json({ error: 'action desconocida' }, 400);
      }
      // GET /admin/corte/cobros → preview de la cobranza: pedidos con precio, cortados/embalados, sin pagar,
      // agrupados por cliente, con total + estado de ventana 24h + el mensaje armado. Admin. NO manda nada.
      if (request.method === 'GET' && path === '/admin/corte/cobros') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let rows = [];
        // Las piezas de NEÓN PROPIO (producto='NEON') NO se cobran: sin este filtro aparecían como "clientes"
        // sin teléfono en "Cobrar la semana" (pasaba con las 15 filas 'neon' cargadas a mano el 28-sep).
        try { rows = (await env.DB.prepare("SELECT id, telefono, cliente_nombre, diseno_nombre, medida_declarada, cantidad, precio FROM corte_pedidos WHERE precio > 0 AND estado_pago='pendiente' AND estado IN ('cortado','embalado','despachado','entregado') AND IFNULL(producto,'TRANS')!='NEON' ORDER BY telefono, id").all()).results || []; } catch (_) {}
        const grupos = {};
        for (const p of rows) {
          const k = p.telefono || ('id' + p.id);
          if (!grupos[k]) grupos[k] = { telefono: p.telefono || '', cliente_nombre: p.cliente_nombre || '', piezas: [], total: 0 };
          grupos[k].piezas.push({ id: p.id, diseno: p.diseno_nombre, medida: p.medida_declarada, cantidad: p.cantidad, precio: p.precio });
          grupos[k].total += Number(p.precio) || 0;
        }
        const nowMs = Date.now(); const out = [];
        for (const k of Object.keys(grupos)) {
          const g = grupos[k];
          let ventana = false;
          if (g.telefono) { try { const li = await env.DB.prepare("SELECT MAX(ts) AS t FROM wa_messages WHERE phone=? AND direction='inbound'").bind(g.telefono).first(); ventana = !!(li && li.t && (nowMs - new Date(li.t).getTime()) < 24 * 3600 * 1000); } catch (_) {} }
          g.ventana_abierta = ventana;
          g.mensaje = corteCobroMsg(g);
          out.push(g);
        }
        return json({ ok: true, clientes: out });
      }
      // POST /admin/corte/cobrar → manda el cobro a los clientes seleccionados (body {telefonos:[...]}). Recalcula
      // el total en el server (no confía en el front). Texto libre si la ventana 24h está abierta; si no, marca
      // "necesita plantilla". Al mandar, deja los pedidos en estado_pago='cobrando' (para el vigía). Admin.
      if (request.method === 'POST' && path === '/admin/corte/cobrar') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const tels = Array.isArray(body.telefonos) ? body.telefonos.map(t => String(t).replace(/\D/g, '')).filter(Boolean) : [];
        if (!tels.length) return json({ error: 'sin telefonos' }, 400);
        const nowIso = new Date().toISOString(); const nowMs = Date.now(); const res = [];
        // recobrar_tels: clientes a los que se les RE-ENVÍA el cobro aunque ya estén 'cobrando' (ej. se corrigió el
        // pedido después de cobrar). Es una lista EXPLÍCITA (el front la arma con los que marcó "re-envío" en la
        // confirmación); el viejo flag global recobrar:true se ignora a propósito. tanda_id: acota todo a esa tanda.
        const recobrarSet = new Set(Array.isArray(body.recobrar_tels) ? body.recobrar_tels.map(t => String(t).replace(/\D/g, '')).filter(Boolean) : []);
        const tandaId = parseInt(body.tanda_id, 10) || 0;
        const tf = tandaId ? ' AND tanda_id=?' : '';
        const tb = tandaId ? [tandaId] : [];
        // CONTROL DE TELÉFONO: si el número figura en LTV a nombre de OTRA persona, ese cobro NO sale (caso real 5-oct:
        // "Gonzalo Alganaraz" tenía el teléfono de "Gonzalo Martin Forns Herrera"). forzar_tels = los que el admin confirmó.
        const forzarSet = new Set(Array.isArray(body.forzar_tels) ? body.forzar_tels.map(t => String(t).replace(/\D/g, '')).filter(Boolean) : []);
        const [ltvGuard, ovGuard] = await Promise.all([corteLtv(env), corteTelOverrides(env)]);
        const dueniosGuard = ltvGuard.ok ? await corteDuenios(env, ltvGuard.rows, ovGuard) : {};
        try { await env.DB.prepare("CREATE TABLE IF NOT EXISTS corte_cobro_lock (phone TEXT PRIMARY KEY, ts TEXT)").run(); } catch (_) {}
        try { await env.DB.prepare("CREATE TABLE IF NOT EXISTS corte_detalle_sent (phone TEXT PRIMARY KEY, cobro_at TEXT, sent_at TEXT)").run(); } catch (_) {}
        // Etiqueta "Servicio de corte": se asegura en cada cobro → el filtro rápido de la bandeja siempre los incluye.
        let corteLabelId = null;
        try { corteLabelId = await ensureLabelId(env, 'Servicio de corte', '#14b8a6'); } catch (_) {}
        // El loop corre en ctx.waitUntil: si el admin cierra la pestaña o se corta la conexión a mitad del envío,
        // el worker igual lo termina (no quedan candados tomados ni clientes a medio procesar).
        const work = (async () => {
        for (const tel of [...new Set(tels)]) {
          // CANDADO POR CLIENTE (90s): si corren dos pedidos de cobro a la vez (doble click, o el botón vuelve a
          // habilitarse por un refresco mientras se envía), solo UNO le manda el cobro a cada cliente. Caso real:
          // 5-oct, 19 clientes recibieron la plantilla de cobro DOS veces. FAIL-CLOSED: si el candado mismo falla,
          // NO se manda (mejor que el admin reintente a que el cliente reciba el cobro dos veces).
          const lockNow = new Date().toISOString(), lockStale = new Date(Date.now() - 90 * 1000).toISOString();
          let lk = null;
          try { lk = await env.DB.prepare("INSERT INTO corte_cobro_lock (phone, ts) VALUES (?, ?) ON CONFLICT(phone) DO UPDATE SET ts=excluded.ts WHERE corte_cobro_lock.ts < ? RETURNING phone").bind(tel, lockNow, lockStale).first(); }
          catch (_) { res.push({ tel, ok: false, error: 'no se pudo tomar el candado (reintentá)' }); continue; }
          if (!lk) { res.push({ tel, ok: false, error: 'ya se le mandó el cobro hace instantes (esperá un minuto)' }); continue; }
          const soltarLock = async () => { try { await env.DB.prepare("DELETE FROM corte_cobro_lock WHERE phone=? AND ts=?").bind(tel, lockNow).run(); } catch (_) {} };
          // RE-COBRO SIN PASAR POR 'pendiente': si está en recobrar_tels, entran también las filas que ya estaban
          // 'cobrando' (nunca pagado/parcial). Antes se bajaban a 'pendiente' durante el envío y, si el comprobante
          // llegaba justo en ese hueco, el vigía no encontraba qué marcar y el pago se perdía.
          const estados = recobrarSet.has(tel) ? "('pendiente','cobrando')" : "('pendiente')";
          let rows = [];
          try { rows = (await env.DB.prepare("SELECT id, cliente_nombre, diseno_nombre, medida_declarada, cantidad, precio, estado_pago FROM corte_pedidos WHERE telefono=? AND precio>0 AND estado_pago IN " + estados + " AND estado IN ('cortado','embalado','despachado','entregado') AND IFNULL(producto,'TRANS')!='NEON'" + tf).bind(tel, ...tb).all()).results || []; } catch (_) {}
          if (!rows.length) { await soltarLock(); res.push({ tel, ok: false, error: recobrarSet.has(tel) ? 'nada para cobrar' : 'nada pendiente (si ya se le cobró, usá re-envío)' }); continue; }
          // Se controlan TODOS los nombres del cobro (si un teléfono tiene piezas de dos clientes, eso mismo es un conflicto)
          // contra todos los dueños conocidos del número (LTV + asignaciones + otros clientes del corte). Si LTV no se pudo
          // leer, NO se manda sin confirmar.
          let confl = null, nomConfl = rows[0].cliente_nombre;
          if (!ltvGuard.ok) confl = { nombre: 'NO VERIFICADO (no pude leer LTV_Alumnos: ' + ltvGuard.error + ')', fuente: 'LTV' };
          else {
            const nombresCob = [...new Set(rows.map(x => String(x.cliente_nombre || '').trim()).filter(Boolean))];
            for (const n of nombresCob) {
              const otroCob = nombresCob.find(o => !corteMismaPersona(o, n));
              const o = otroCob ? { nombre: otroCob, fuente: 'mismo cobro' } : corteTelDeOtro(tel, n, dueniosGuard);
              if (o) { confl = o; nomConfl = n; break; }
            }
          }
          if (confl && !forzarSet.has(tel)) { await soltarLock(); res.push({ tel, ok: false, conflicto: confl.nombre, fuente: confl.fuente, nombre: nomConfl, error: 'NO SE MANDÓ: ese teléfono figura a nombre de ' + confl.nombre + ' (' + confl.fuente + ')' }); continue; }
          const esRecobro = rows.some(x => x.estado_pago === 'cobrando');
          const g = { telefono: tel, cliente_nombre: rows[0].cliente_nombre, piezas: rows.map(r => ({ diseno: r.diseno_nombre, medida: r.medida_declarada, cantidad: r.cantidad, precio: r.precio })), total: rows.reduce((s, r) => s + (Number(r.precio) || 0), 0) };
          let ventana = false;
          try { const li = await env.DB.prepare("SELECT MAX(ts) AS t FROM wa_messages WHERE phone=? AND direction='inbound'").bind(tel).first(); ventana = !!(li && li.t && (nowMs - new Date(li.t).getTime()) < 23 * 3600 * 1000); } catch (_) {}
          // El texto libre YA ES el desglose → marcamos el detalle como enviado ANTES de mandarlo: si el vigía corre
          // mientras sale el mensaje, no manda un segundo desglose. Si el envío falla, se restaura la marca previa.
          let prevDet = null, detMarcado = false;
          if (ventana) {
            try { prevDet = await env.DB.prepare("SELECT cobro_at, sent_at FROM corte_detalle_sent WHERE phone=?").bind(tel).first(); } catch (_) {}
            try { await env.DB.prepare("INSERT INTO corte_detalle_sent (phone, cobro_at, sent_at) VALUES (?,?,?) ON CONFLICT(phone) DO UPDATE SET cobro_at=excluded.cobro_at, sent_at=excluded.sent_at").bind(tel, lockNow, lockNow).run(); detMarcado = true; } catch (_) {}
          }
          const restaurarDet = async () => {
            if (!detMarcado) return;
            try {
              if (prevDet) await env.DB.prepare("UPDATE corte_detalle_sent SET cobro_at=?, sent_at=? WHERE phone=? AND sent_at=?").bind(prevDet.cobro_at, prevDet.sent_at, tel, lockNow).run();
              else await env.DB.prepare("DELETE FROM corte_detalle_sent WHERE phone=? AND sent_at=?").bind(tel, lockNow).run();
            } catch (_) {}
          };
          // En ventana → texto libre (desglose completo). Fuera de ventana → plantilla aprobada
          // corte_cobro_semanal ({{1}}=nombre, {{2}}=total). Ambas dejan los pedidos en 'cobrando' (para el vigía).
          let r, via;
          try {
            if (ventana) { via = 'texto'; r = await corteSend(env, tel, corteCobroMsg(g)); }
            else {
              const _nom = String(g.cliente_nombre || '').trim().split(/\s+/)[0] || '';
              const _tot = '$' + Number(g.total || 0).toLocaleString('es-AR');
              via = 'plantilla';
              r = await waSendTemplate(env, tel, 'corte_cobro_semanal', 'es_AR', [_nom, _tot]);
              if (r && r.ok) { try { await env.DB.prepare("INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, status, context_id, automated) VALUES (?, ?, 'outbound', ?, '', 'text', ?, 'sent', '', 1)").bind(new Date().toISOString(), r.id || ('corte-cobro-tpl:' + tel + ':' + Date.now()), tel, '[plantilla corte_cobro_semanal] total ' + _tot).run(); } catch (_) {} }
            }
          } catch (_) { r = { ok: false }; } // una excepción del envío no puede dejar el candado tomado
          if (r && r.ok) {
            // Pasan a 'cobrando' EXACTAMENTE las filas que se cobraron en este mensaje (por id). Las que el vigía haya
            // marcado pagado/parcial mientras salía el mensaje NO se tocan.
            const cobIds = rows.map(x => x.id);
            try { await env.DB.prepare("UPDATE corte_pedidos SET estado_pago='cobrando', updated_at=? WHERE estado_pago IN ('pendiente','cobrando') AND id IN (" + cobIds.map(() => '?').join(',') + ")").bind(nowIso, ...cobIds).run(); } catch (_) {}
            // Dedup del DETALLE para este cobro:
            //  · salió como TEXTO → ya quedó marcado ANTES del envío (ese mensaje ES el desglose; caso Daniel, 5-oct).
            //  · salió como PLANTILLA (solo total) → borramos la marca: el desglose sale cuando conteste.
            if (via !== 'texto') { try { await env.DB.prepare("DELETE FROM corte_detalle_sent WHERE phone=?").bind(tel).run(); } catch (_) {} }
            else if (!detMarcado) { try { await env.DB.prepare("INSERT INTO corte_detalle_sent (phone, cobro_at, sent_at) VALUES (?,?,?) ON CONFLICT(phone) DO UPDATE SET cobro_at=excluded.cobro_at, sent_at=excluded.sent_at").bind(tel, nowIso, nowIso).run(); } catch (_) {} }
            if (corteLabelId) { try { await env.DB.prepare("INSERT OR IGNORE INTO contact_labels (phone, label_id, created_at) VALUES (?, ?, datetime('now'))").bind(tel, corteLabelId).run(); } catch (_) {} }
            res.push({ tel, ok: true, total: g.total, via, recobro: esRecobro });
          } else { await restaurarDet(); await soltarLock(); res.push({ tel, ok: false, error: 'no se pudo enviar', total: g.total, via }); }
        }
        return res;
        })();
        ctx.waitUntil(work.catch(() => {}));
        return json({ ok: true, resultados: await work, ltv_error: ltvGuard.ok ? '' : ltvGuard.error });
      }
      // POST /admin/corte/enviar-detalle {telefonos, tanda_id?} → manda el DESGLOSE a clientes que no lo recibieron
      // (ej. pagaron directo con el comprobante). Si ya pagaron todo → recibo (sin pedir transferencia); si no → el
      // detalle de cobro. Solo con ventana abierta (inbound en 24h). Reserva atómica en corte_detalle_sent: no duplica
      // con el vigía ni si se llama dos veces. Admin.
      if (request.method === 'POST' && path === '/admin/corte/enviar-detalle') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        const tels = Array.isArray(body.telefonos) ? [...new Set(body.telefonos.map(t => String(t).replace(/\D/g, '')).filter(Boolean))] : [];
        if (!tels.length) return json({ error: 'sin telefonos' }, 400);
        const tandaId = parseInt(body.tanda_id, 10) || 0;
        const tf = tandaId ? ' AND tanda_id=?' : '';
        const tb = tandaId ? [tandaId] : [];
        try { await env.DB.prepare("CREATE TABLE IF NOT EXISTS corte_detalle_sent (phone TEXT PRIMARY KEY, cobro_at TEXT, sent_at TEXT)").run(); } catch (_) {}
        const res = [];
        for (const tel of tels) {
          let rows = [];
          try { rows = (await env.DB.prepare("SELECT cliente_nombre, diseno_nombre, medida_declarada, cantidad, precio, estado_pago FROM corte_pedidos WHERE telefono=? AND precio>0 AND IFNULL(producto,'TRANS')!='NEON' AND estado_pago IN ('pagado','cobrando','parcial')" + tf).bind(tel, ...tb).all()).results || []; } catch (_) {}
          if (!rows.length) { res.push({ tel, ok: false, error: 'sin pedidos cobrados' }); continue; }
          let ventana = false;
          try { ventana = !!(await env.DB.prepare("SELECT 1 AS x FROM wa_messages WHERE phone=? AND direction='inbound' AND msg_type!='status' AND ts > ? LIMIT 1").bind(tel, isoHace(23 * 3600 * 1000)).first()); } catch (_) {}
          if (!ventana) { res.push({ tel, ok: false, error: 'fuera de ventana de 24h (no se puede mandar texto)' }); continue; }
          const now = new Date().toISOString();
          let claimed = null;
          try { claimed = await env.DB.prepare("INSERT INTO corte_detalle_sent (phone, cobro_at, sent_at) VALUES (?,?,?) ON CONFLICT(phone) DO UPDATE SET sent_at=excluded.sent_at WHERE corte_detalle_sent.sent_at IS NULL OR corte_detalle_sent.sent_at='' RETURNING phone").bind(tel, now, now).first(); } catch (_) {}
          if (!claimed) { res.push({ tel, ok: false, error: 'ya tenía el detalle' }); continue; }
          const g = { cliente_nombre: rows[0].cliente_nombre, piezas: rows.map(r => ({ diseno: r.diseno_nombre, medida: r.medida_declarada, cantidad: r.cantidad, precio: r.precio })), total: rows.reduce((s, r) => s + (Number(r.precio) || 0), 0) };
          const pagado = rows.every(r => r.estado_pago === 'pagado');
          let ok = false;
          try { const r = await corteSend(env, tel, pagado ? corteReciboMsg(g) : corteCobroMsg(g)); ok = !!(r && r.ok); } catch (_) {}
          if (!ok) { try { await env.DB.prepare("UPDATE corte_detalle_sent SET sent_at=NULL WHERE phone=? AND sent_at=?").bind(tel, now).run(); } catch (_) {} }
          res.push({ tel, ok, nombre: g.cliente_nombre, total: g.total, tipo: pagado ? 'recibo' : 'detalle_cobro', error: ok ? undefined : 'no se pudo enviar' });
        }
        return json({ ok: true, resultados: res });
      }
      // POST /admin/corte/aviso → manda la plantilla corte_aviso_migracion ({{1}}=nombre) a una lista de
      // teléfonos (body {telefonos}), o por default a los clientes de la tanda (cortado/embalado). Con
      // pausa entre envíos y dedup (no reenvía si ya se avisó en 30 días). Admin. Es el aviso de "los
      // pedidos y pagos ahora van por este número".
      if (request.method === 'POST' && path === '/admin/corte/aviso') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let body; try { body = await request.json(); } catch { body = {}; }
        let tels = Array.isArray(body.telefonos) ? body.telefonos.map(t => String(t).replace(/\D/g, '')).filter(Boolean) : [];
        if (!tels.length) {
          try { tels = ((await env.DB.prepare("SELECT DISTINCT telefono FROM corte_pedidos WHERE telefono!='' AND estado IN ('cortado','embalado','despachado','entregado')").all()).results || []).map(r => r.telefono); } catch (_) { tels = []; }
        }
        tels = [...new Set(tels)];
        if (!tels.length) return json({ error: 'sin telefonos' }, 400);
        const res = [];
        for (const tel of tels) {
          try { const ya = await env.DB.prepare("SELECT 1 FROM wa_messages WHERE phone=? AND direction='outbound' AND body LIKE '%[aviso corte migracion]%' AND ts > ? LIMIT 1").bind(tel, isoHace(30 * 86400 * 1000)).first(); if (ya) { res.push({ tel, ok: false, skip: 'ya avisado' }); continue; } } catch (_) {}
          let nom = '';
          try { const a = await env.DB.prepare("SELECT nombre FROM corte_alumnos WHERE telefono=? LIMIT 1").bind(tel).first(); nom = (a && a.nombre) || ''; } catch (_) {}
          if (!nom) { try { const p = await env.DB.prepare("SELECT cliente_nombre FROM corte_pedidos WHERE telefono=? LIMIT 1").bind(tel).first(); nom = (p && p.cliente_nombre) || ''; } catch (_) {} }
          const _nom = String(nom || '').trim().replace(/([a-záéíóúüñ])([A-ZÁÉÍÓÚÜÑ])/g, '$1 $2').split(/\s+/)[0] || 'hola';
          const r = await waSendTemplate(env, tel, 'corte_aviso_migracion', 'es_AR', [_nom]);
          if (r && r.ok) {
            try { await env.DB.prepare("INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, status, context_id, automated) VALUES (?, ?, 'outbound', ?, '', 'text', ?, 'sent', '', 1)").bind(new Date().toISOString(), r.id || ('corte-aviso:' + tel + ':' + Date.now()), tel, '[aviso corte migracion]').run(); } catch (_) {}
            res.push({ tel, ok: true });
          } else { res.push({ tel, ok: false, error: (r && r.error) || 'no se pudo enviar' }); }
          await new Promise(s => setTimeout(s, 1500));
        }
        return json({ ok: true, enviados: res.filter(x => x.ok).length, total: tels.length, resultados: res });
      }
      // GET /admin/corte/tanda → info de la tanda de la semana: archivo, m² vendidos/cortados, aprovechamiento.
      if (request.method === 'GET' && path === '/admin/corte/tanda') {
        const _r = await getSessionRole(env, session.user);
        if (!['admin', 'disenador', 'produccion'].includes(_r)) return json({ error: 'forbidden' }, 403);
        const t = await corteTandaActual(env);
        if (!t) return json({ error: 'sin tanda' }, 500);
        // m² VENDIDOS = piezas de alumnos (se cobran). m² INTERNOS = neón propio de Neon Infinito (no se
        // cobran). El APROVECHAMIENTO usa los dos: salen de las mismas placas que corta Aníbal.
        let m2vend = 0, m2int = 0, npze = 0;
        try { const rs = await env.DB.prepare("SELECT ancho_real, alto_real, cantidad, producto FROM corte_pedidos WHERE tanda_id=? AND ancho_real>0 AND alto_real>0").bind(t.id).all(); for (const p of (rs.results || [])) { const m2 = (Number(p.ancho_real) / 100) * (Number(p.alto_real) / 100) * (Math.max(1, parseInt(p.cantidad, 10) || 1)); if (String(p.producto || '') === 'NEON') m2int += m2; else m2vend += m2; npze++; } } catch (_) {}
        const m2cort = Number(t.m2_cortados) || 0;
        const m2usado = m2vend + m2int;
        return json({ ok: true, semana: t.semana, role: _r, archivo_matriz: !!t.archivo_matriz_key, archivo_matriz_link: t.archivo_matriz_link || '', archivo_placas: !!t.archivo_placas_key, m2_vendidos: Math.round(m2vend * 100) / 100, m2_internos: Math.round(m2int * 100) / 100, m2_cortados: m2cort, aprovechamiento: m2cort > 0 ? Math.round((m2usado / m2cort) * 1000) / 10 : null, piezas_relevadas: npze });
      }
      // GET /admin/corte/resumen → contador liviano para el badge del menú "Corte" (Emma lo pollea sin
      // cargar toda la cola): piezas de neón propio listas para diseñar y las que esperan la foto del vendedor.
      if (request.method === 'GET' && path === '/admin/corte/resumen') {
        const _r = await getSessionRole(env, session.user);
        if (!['admin', 'disenador', 'produccion'].includes(_r)) return json({ error: 'forbidden' }, 403);
        let paraDisenar = 0, esperandoFoto = 0;
        await ensureCorteNeonSchema(env);
        try {
          // Sin contar las de pedidos que ya se entregaron / están para enviar (el cartel ya existe: no hay matriz que hacer).
          const r = await env.DB.prepare("SELECT SUM(CASE WHEN IFNULL(c.foto_key,'')='' AND c.pedido_id IS NOT NULL THEN 0 ELSE 1 END) AS lista, SUM(CASE WHEN IFNULL(c.foto_key,'')='' AND c.pedido_id IS NOT NULL THEN 1 ELSE 0 END) AS espera FROM corte_pedidos c LEFT JOIN pedidos p ON p.id = c.pedido_id WHERE c.producto='NEON' AND c.estado='pedido' AND lower(trim(IFNULL(p.estado_pedido,''))) NOT IN ('entregado','para enviar')").first();
          paraDisenar = (r && r.lista) || 0; esperandoFoto = (r && r.espera) || 0;
        } catch (_) {}
        return json({ ok: true, neon_para_disenar: paraDisenar, neon_esperando_foto: esperandoFoto });
      }
      // POST /admin/corte/tanda/archivo?name=... → Emma sube la matriz (body = archivo raw) → R2 + Drive (best-effort).
      if (request.method === 'POST' && path === '/admin/corte/tanda/archivo') {
        const _r = await getSessionRole(env, session.user);
        if (!['admin', 'disenador'].includes(_r)) return json({ error: 'forbidden' }, 403);
        const _u = new URL(request.url);
        const name = (_u.searchParams.get('name') || 'matriz').replace(/[^\w.\- ]/g, '_').slice(0, 120);
        const buf = await request.arrayBuffer().catch(() => null);
        if (!buf || buf.byteLength < 8) return json({ error: 'archivo vacío' }, 400);
        if (buf.byteLength > 80 * 1024 * 1024) return json({ error: 'archivo mayor a 80MB' }, 400);
        const t = await corteTandaActual(env);
        const key = 'corte/tandas/' + (t ? t.id : 'x') + '/matriz-' + Date.now() + '-' + name;
        const mime = request.headers.get('content-type') || 'application/octet-stream';
        try { await env.MEDIA.put(key, buf, { httpMetadata: { contentType: mime } }); } catch (e) { return json({ error: 'no se pudo guardar en R2' }, 500); }
        let driveLink = '';
        try { const dr = await driveUploadFile(env, DRIVE_FOLDER_MATRICES, (t ? t.semana + '-' : '') + name, mime, buf); if (dr.ok) driveLink = dr.link || dr.id || ''; } catch (_) {}
        try { await env.DB.prepare("UPDATE corte_tandas SET archivo_matriz_key=?, archivo_matriz_link=?, updated_at=? WHERE id=?").bind(key, driveLink, new Date().toISOString(), t.id).run(); } catch (_) {}
        return json({ ok: true, size: buf.byteLength, drive: driveLink ? true : false });
      }
      // GET /admin/corte/tanda/archivo → descarga la matriz de la tanda (para Aníbal). produccion/disenador/admin.
      if (request.method === 'GET' && path === '/admin/corte/tanda/archivo') {
        const _r = await getSessionRole(env, session.user);
        if (!['admin', 'disenador', 'produccion'].includes(_r)) return json({ error: 'forbidden' }, 403);
        const t = await corteTandaActual(env);
        if (!t || !t.archivo_matriz_key) return json({ error: 'sin archivo' }, 404);
        const obj = await env.MEDIA.get(t.archivo_matriz_key);
        if (!obj) return json({ error: 'no encontrado' }, 404);
        const fname = (t.archivo_matriz_key.split('/').pop() || 'matriz').replace(/^matriz-\d+-/, '');
        // CON CORS: el front (otro origen) descarga con fetch; sin estos headers el navegador bloqueaba la respuesta.
        return new Response(obj.body, { headers: cors({ 'Content-Type': obj.httpMetadata?.contentType || 'application/octet-stream', 'Content-Disposition': 'attachment; filename="' + fname + '"', 'Access-Control-Expose-Headers': 'Content-Disposition' }) });
      }
      // POST /admin/corte/disenos-pack {ids} → "Descargar diseños y recibir medidas" (tablero de neón de Emma).
      // Devuelve un ZIP con la foto de cada pieza de neón POR DISEÑAR (nombre = N° · diseño · medida) + medidas.txt,
      // y manda las medidas por WhatsApp (plantilla UTILITY disenos_neon_medidas) a Emma y a Gaspar → Gaspar sabe
      // que Emma arrancó. Mismo set de piezas dentro de 30 min = no se re-avisa (doble clic / re-descarga).
      // El resultado del aviso viaja en el header X-Medidas (JSON url-encoded). disenador/admin.
      if (request.method === 'POST' && path === '/admin/corte/disenos-pack') {
        const _r = await getSessionRole(env, session.user);
        if (!['admin', 'disenador'].includes(_r)) return json({ error: 'forbidden' }, 403);
        if (!env.MEDIA) return json({ error: 'R2 no configurado' }, 500);
        await ensureCorteNeonSchema(env);
        let body; try { body = await request.json(); } catch { body = {}; }
        const ids = [...new Set((Array.isArray(body.ids) ? body.ids : []).map(x => parseInt(x, 10)).filter(Boolean))].slice(0, 40);
        if (!ids.length) return json({ error: 'no hay diseños para descargar' }, 400);
        const ph = ids.map(() => '?').join(',');
        // Solo piezas que siguen POR DISEÑAR y tienen foto (lo mismo que ve Emma en la columna). tipo 'web': los pedidos de la
        // landing de corte (acrílico de alumnos) — mismo ZIP, sin el aviso de medidas por WhatsApp (es de neón).
        const esWeb = body.tipo === 'web';
        const rows = (await env.DB.prepare(
          `SELECT id, pedido_numero, cliente_nombre, diseno_nombre, medida_declarada, cantidad, foto_key, created_at FROM corte_pedidos
            WHERE id IN (${ph}) AND ${esWeb ? "producto != 'NEON'" : "producto = 'NEON'"} AND estado = 'pedido' AND IFNULL(foto_key, '') <> ''
            ORDER BY created_at, id`
        ).bind(...ids).all()).results || [];
        if (!rows.length) return json({ error: 'esos diseños ya no están por diseñar (se actualizó la lista)' }, 409);
        if (!esWeb && _r === 'disenador') await neonCorteStamp(env, rows.map(r => r.id), 'diseno_inicio_at', session.user);
        const nowD = new Date();
        const ar = new Date(nowD.getTime() - 3 * 3600 * 1000);
        const p2 = (n) => String(n).padStart(2, '0');
        const cuandoAR = `${p2(ar.getUTCDate())}/${p2(ar.getUTCMonth() + 1)} ${p2(ar.getUTCHours())}:${p2(ar.getUTCMinutes())}`;
        const lineas = rows.map(r => {
          const m = corteMedidaNeon(r), cant = Math.max(1, parseInt(r.cantidad, 10) || 1);
          if (esWeb) return `${String(r.cliente_nombre || 'cliente').trim()} · ${String(r.diseno_nombre || 'diseño').trim()} ${m.txt || 'sin medida'}${cant > 1 ? ' x' + cant : ''}`;
          return `${r.pedido_numero ? '#' + r.pedido_numero + ' ' : ''}${String(r.diseno_nombre || 'cartel').trim()} ${m.txt || 'sin medida'}${cant > 1 ? ' x' + cant : ''}`;
        });
        // --- Aviso por WhatsApp (en paralelo con el armado del ZIP) ---
        // sin_aviso (solo admin): bajar el ZIP sin mandar WhatsApp (pruebas / re-descargas de Gaspar).
        const sinAviso = esWeb || (_r === 'admin' && body.sin_aviso === true);
        const avisar = (async () => {
          if (sinAviso) return { estado: 'sin_aviso' };
          const sig = rows.map(r => r.id).sort((a, b) => a - b).join(',');
          try {
            const last = await env.DB.prepare("SELECT v FROM kv_cache WHERE k = 'corte_disenos_aviso_last'").first();
            const lv = last ? JSON.parse(last.v) : null;
            if (lv && lv.sig === sig && (nowD.getTime() - Date.parse(lv.at)) < 30 * 60 * 1000) return { estado: 'ya_avisado' };
          } catch (_) {}
          const phones = {};
          try { for (const x of (await env.DB.prepare("SELECT usuario, phone FROM agenda_phones WHERE usuario IN ('disenador', 'gaspar')").all()).results || []) phones[x.usuario] = x.phone; } catch (_) {}
          const destinos = [...new Set([phones.disenador || '5491128982635', phones.gaspar || '5491155604999'])];
          const tramos = tramosPlantilla(lineas);
          let tplOk = 0, txtOk = 0, sinVentana = 0, fallos = 0;
          for (const ph2 of destinos) {
            let okTpl = true;
            for (const t of tramos) {
              let r = null;
              try { r = await waSendTemplate(env, ph2, 'disenos_neon_medidas', 'es_AR', [String(rows.length), t.slice(0, 900), cuandoAR]); } catch (_) {}
              if (!r || !r.ok) { okTpl = false; break; }
            }
            if (okTpl) { tplOk++; continue; }
            // Plantilla todavía sin aprobar (o error) → texto libre, PERO solo con la ventana de 24 h abierta: fuera de
            // ella waSend devuelve ok y Meta lo rebota después (131047) → se contaría como enviado sin haber llegado.
            let ventana = false;
            try {
              const w = await env.DB.prepare("SELECT MAX(ts) AS t FROM wa_messages WHERE phone = ? AND direction = 'inbound' AND msg_type != 'status'").bind(normalizeArPhone(ph2) || ph2).first();
              ventana = !!(w && w.t && Date.now() - Date.parse(w.t) < 23 * 3600 * 1000);
            } catch (_) {}
            if (!ventana) { sinVentana++; continue; }
            let okTxt = true;
            for (const b of bloquesTexto(`Diseños de neón para hacer (${rows.length}) · ${cuandoAR}\n`, lineas.map(l => '• ' + l))) {
              let r = null;
              try { r = await waSendText(env, ph2, b); } catch (_) {}
              if (!r || !r.ok) { okTxt = false; break; }
            }
            if (okTxt) txtOk++; else fallos++;
          }
          const llegaron = tplOk + txtOk;
          // Dedup solo si a alguien le llegó (si no, que el próximo toque reintente).
          if (llegaron > 0) {
            try { await env.DB.prepare('INSERT INTO kv_cache (k, v, updated_at) VALUES (?, ?, ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v, updated_at = excluded.updated_at').bind('corte_disenos_aviso_last', JSON.stringify({ sig, at: nowD.toISOString(), por: String(session.user || '') }), nowD.toISOString()).run(); } catch (_) {}
          }
          const estado = llegaron === 0 ? 'fallo' : (llegaron < destinos.length ? 'parcial' : (tplOk === destinos.length ? 'plantilla' : 'texto'));
          return { estado, plantilla: tplOk, texto: txtOk, sin_ventana: sinVentana, fallos, destinos: destinos.length };
        })();
        // --- ZIP: una foto por pieza, nombre legible y único + medidas.txt ---
        const san = (x) => String(x || '').replace(/[\\/:*?"<>|\u0000-\u001f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 80);
        const files = [], usados = new Set(), faltan = [];
        for (const r of rows) {
          let obj = null;
          try { obj = await env.MEDIA.get(r.foto_key); } catch (_) {}
          if (!obj) { faltan.push(r); continue; }
          const data = new Uint8Array(await obj.arrayBuffer());
          const ct = String((obj.httpMetadata && obj.httpMetadata.contentType) || '');
          const extKey = (String(r.foto_key).match(/\.([a-z0-9]{2,5})$/i) || [])[1];
          const ext = (extKey || (ct.includes('png') ? 'png' : ct.includes('webp') ? 'webp' : 'jpg')).toLowerCase();
          const m = corteMedidaNeon(r), cant = Math.max(1, parseInt(r.cantidad, 10) || 1);
          const base = san([esWeb ? (r.cliente_nombre || 'cliente') : (r.pedido_numero ? String(r.pedido_numero) : ''), r.diseno_nombre || (esWeb ? 'diseño' : 'cartel'), m.ancho && m.alto ? `${m.ancho}x${m.alto}cm` : '', cant > 1 ? 'x' + cant : ''].filter(Boolean).join(' - ')) || ('pieza ' + r.id);
          let nm = `${base}.${ext}`, k = 2;
          while (usados.has(nm.toLowerCase())) nm = `${base} (${k++}).${ext}`;
          usados.add(nm.toLowerCase());
          files.push({ name: nm, data });
        }
        const txt = `${esWeb ? 'Pedidos web de corte para diseñar' : 'Diseños de neón para hacer'} · ${cuandoAR}\r\n\r\n` + lineas.join('\r\n') + (faltan.length ? `\r\n\r\nSin foto en el servidor: ${faltan.map(r => (r.pedido_numero ? '#' + r.pedido_numero + ' ' : '') + (r.diseno_nombre || '')).join(', ')}` : '') + '\r\n';
        files.push({ name: 'medidas.txt', data: new TextEncoder().encode(txt) });
        const aviso = await avisar;
        const fname = `disenos-${esWeb ? 'web' : 'neon'}-${ar.getUTCFullYear()}-${p2(ar.getUTCMonth() + 1)}-${p2(ar.getUTCDate())}.zip`;
        return new Response(zipStore(files, nowD), { headers: cors({
          'Content-Type': 'application/zip',
          'Content-Disposition': 'attachment; filename="' + fname + '"',
          'X-Medidas': encodeURIComponent(JSON.stringify({ ...aviso, piezas: rows.length, fotos: files.length - 1 })),
          'Access-Control-Expose-Headers': 'Content-Disposition, X-Medidas',
          'Cache-Control': 'no-store'
        }) });
      }
      // POST /admin/corte/tanda/placas?name=&m2= → Aníbal sube placas (body opcional) + carga m² cortados. produccion/admin.
      if (request.method === 'POST' && path === '/admin/corte/tanda/placas') {
        const _r = await getSessionRole(env, session.user);
        if (!['admin', 'produccion'].includes(_r)) return json({ error: 'forbidden' }, 403);
        const _u = new URL(request.url);
        const m2 = parseFloat(String(_u.searchParams.get('m2') || '').replace(',', '.'));
        const name = (_u.searchParams.get('name') || '').replace(/[^\w.\- ]/g, '_').slice(0, 120);
        const t = await corteTandaActual(env);
        if (!t) return json({ error: 'sin tanda' }, 500);
        let key = t.archivo_placas_key || '', driveLink = t.archivo_placas_link || '';
        const buf = await request.arrayBuffer().catch(() => null);
        if (buf && buf.byteLength > 8) {
          if (buf.byteLength > 80 * 1024 * 1024) return json({ error: 'archivo mayor a 80MB' }, 400);
          key = 'corte/tandas/' + t.id + '/placas-' + Date.now() + '-' + (name || 'placas');
          const mime = request.headers.get('content-type') || 'application/octet-stream';
          try { await env.MEDIA.put(key, buf, { httpMetadata: { contentType: mime } }); } catch (_) {}
          try { const dr = await driveUploadFile(env, DRIVE_FOLDER_ANIBAL, t.semana + '-' + (name || 'placas'), mime, buf); if (dr.ok) driveLink = dr.link || dr.id || ''; } catch (_) {}
        }
        const m2f = (!isNaN(m2) && m2 > 0) ? m2 : (Number(t.m2_cortados) || 0);
        try { await env.DB.prepare("UPDATE corte_tandas SET m2_cortados=?, archivo_placas_key=?, archivo_placas_link=?, updated_at=? WHERE id=?").bind(m2f, key, driveLink, new Date().toISOString(), t.id).run(); } catch (_) {}
        return json({ ok: true, m2_cortados: m2f, drive: driveLink ? true : false });
      }
      // GET /admin/corte/drive-test → sube un archivito de prueba a la carpeta de matrices (verifica acceso). Admin.
      if (request.method === 'GET' && path === '/admin/corte/drive-test') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        const bytes = new TextEncoder().encode('prueba de acceso del software de Neon Infinito al Drive - ' + new Date().toISOString());
        const r = await driveUploadFile(env, DRIVE_FOLDER_MATRICES, 'test-acceso-software.txt', 'text/plain', bytes);
        return json(r);
      }
      // POST /admin/corte/run  →  dispara el bot de corte a mano (diagnóstico). Admin. Devuelve el estado.
      if (request.method === 'POST' && path === '/admin/corte/run') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let err = null;
        try { await processCortePilot(env); } catch (e) { err = String((e && e.message) || e); }
        const tp = String(await kvGet(env, 'corte_bot_test_phone', '')).replace(/\D/g, '');
        let conv = null, peds = 0, lastBot = null;
        try { conv = await env.DB.prepare("SELECT estado, intencion_preguntada, substr(last_processed_ts,11,8) AS lp FROM corte_conversaciones WHERE phone=?").bind(tp).first(); } catch (_) {}
        try { const r = await env.DB.prepare("SELECT count(*) AS n FROM corte_pedidos WHERE telefono=? AND created_at > datetime('now','-40 minutes')").bind(tp).first(); peds = (r && r.n) || 0; } catch (_) {}
        try { const lb = await env.DB.prepare("SELECT substr(body,1,140) AS body FROM wa_messages WHERE phone=? AND direction='outbound' AND automated=1 AND ts > ? ORDER BY ts DESC LIMIT 1").bind(tp, isoHace(20 * 60 * 1000)).first(); lastBot = lb && lb.body; } catch (_) {}
        // diag: corre el pipeline (ctx + IA) para el test phone y reporta qué devuelve. SOLO con ?diag=1
        // (gasta una llamada extra a la IA). El bombeo rápido llama sin diag → liviano.
        let diag = undefined;
        if (new URL(request.url).searchParams.get('diag') === '1') {
          diag = {};
          try {
            const ctx = await buildChatContext(env, tp, 40);
            diag.ctx = ctx ? ('fullText len ' + String((ctx.fullText || '')).length) : 'NULL';
            if (ctx) {
              const imgs = await precotizImageBlocks(env, tp, 3, 3);
              diag.imgs = imgs.length;
              const out = await corteLlm(env, ctx.fullText, imgs, undefined, { phone: tp, by: 'diag' });
              diag.llm = out.ok ? { ok: true, data: out.data } : { ok: false, error: out.error, raw: out.raw };
            }
          } catch (e) { diag.exc = String((e && e.message) || e); }
        }
        return json({ ok: true, err, test_phone: tp, conv, pedidos_recientes: peds, ultimo_bot: lastBot, diag });
      }
      // POST /admin/corte/simulate → corre SOLO el cerebro (corteLlm) sobre un transcript sintético, sin
      // mandar nada. Para testear escenarios. Body: { text, imgKey? }. imgKey = key R2 de una imagen a adjuntar.
      if (request.method === 'POST' && path === '/admin/corte/simulate') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let body = {};
        try { body = await request.json(); } catch (_) {}
        const text = String(body.text || '');
        if (!text) return json({ error: 'falta text' }, 400);
        let imgs = [];
        if (body.imgKey && env.MEDIA) {
          try {
            const obj = await env.MEDIA.get(String(body.imgKey));
            if (obj) {
              const buf = await obj.arrayBuffer();
              let mime = sniffImageMime(buf) || 'image/jpeg';
              if (/^image\/(png|jpeg|webp|gif)$/.test(mime)) imgs.push({ type: 'image', source: { type: 'base64', media_type: mime, data: abToBase64(buf) } });
            }
          } catch (_) {}
        }
        let pre = '';
        if (body.nuevo === true) pre = '[DATOS DEL CLIENTE (interno): Es cliente NUEVO, no está en la base. NO tenemos sus datos de envío.]\n\n';
        else if (body.nuevo === false) pre = '[DATOS DEL CLIENTE (interno): Cliente registrado. Ya tenemos sus datos de envío.]\n\n';
        const out = await corteLlm(env, pre + text, imgs, body.ahora, { by: 'simulate' });
        return json({ ok: out.ok, imgs: imgs.length, data: out.data, error: out.error });
      }
      // POST /admin/corte/vigia-sweep → corre SOLO el vigía de pagos sobre TODOS los clientes en cobranza
      // (estado_pago='cobrando'). Detecta comprobante (imagen/PDF), lo OCRea, marca pagado/parcial y avisa a Gaspar.
      // NO corre el LLM ni responde conversacionalmente — sirve para procesar pagos con el bot apagado.
      if (request.method === 'POST' && path === '/admin/corte/vigia-sweep') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let phones = [];
        try { phones = ((await env.DB.prepare("SELECT DISTINCT telefono FROM corte_pedidos WHERE estado_pago='cobrando' AND telefono IS NOT NULL AND telefono!=''").all()).results || []).map(r => r.telefono); } catch (_) {}
        const detalle = [];
        for (const ph of phones) {
          let hit = false, err = '';
          try { hit = await corteVigiaPago(env, ph, { hours: 336 }); } catch (e) { err = String((e && e.message) || e); } // ventana amplia (2 sem): el sweep recupera comprobantes viejos
          let ep = '', nom = '';
          try { const r = await env.DB.prepare("SELECT MAX(estado_pago) AS ep, MAX(cliente_nombre) AS nom FROM corte_pedidos WHERE telefono=?").bind(ph).first(); if (r) { ep = r.ep || ''; nom = r.nom || ''; } } catch (_) {}
          detalle.push({ telefono: ph, nombre: nom, procesado: hit, estado_pago: ep, err });
        }
        const pagados = detalle.filter(o => o.estado_pago === 'pagado').length;
        const parciales = detalle.filter(o => o.estado_pago === 'parcial').length;
        const pendientes = detalle.filter(o => o.estado_pago === 'cobrando').length;
        return json({ ok: true, revisados: phones.length, pagados, parciales, pendientes, detalle });
      }
      // POST /admin/corte/ocr-test {key} → corre analyzePaymentProof sobre una key R2 y devuelve el JSON crudo. Admin.
      if (request.method === 'POST' && path === '/admin/corte/ocr-test') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let body = {}; try { body = await request.json(); } catch (_) {}
        const key = String(body.key || '');
        if (!key) return json({ error: 'falta key' }, 400);
        const out = await analyzePaymentProof(env, key, /\.pdf$/i.test(key) ? 'application/pdf' : '', { by: 'ocr-test' });
        return json({ ok: true, key, proof: out });
      }
      // GET /admin/corte/sheet-test → confirma identidad + acceso de la SA del worker a Venta_Insumos (sin escribir).
      if (request.method === 'GET' && path === '/admin/corte/sheet-test') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let email = ''; try { email = (JSON.parse(env.GOOGLE_SA_KEY || '{}').client_email) || ''; } catch (_) {}
        const token = await sheetsAccessToken(env);
        let read = null, err = '';
        if (token) {
          try { const r = await fetch(`https://sheets.googleapis.com/v4/spreadsheets/${CORTE_SHEET_ID}/values/Venta_Insumos!A1:J1`, { headers: { Authorization: 'Bearer ' + token } }); const j = await r.json().catch(() => ({})); if (r.ok) read = (j.values && j.values[0]) || []; else err = (j.error && j.error.message) || ('HTTP ' + r.status); } catch (e) { err = String((e && e.message) || e); }
        } else err = 'sin token (falta GOOGLE_SA_KEY o firma falló)';
        return json({ ok: !!read, sa_email: email, header: read, error: err });
      }
      // POST /admin/corte/sheet-marcar {cliente,total} → prueba/forzado del marcado "pagado" en Venta_Insumos. Admin.
      if (request.method === 'POST' && path === '/admin/corte/sheet-marcar') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let body = {}; try { body = await request.json(); } catch (_) {}
        const res = await corteMarcarPagadoSheet(env, String(body.cliente || ''), Number(body.total) || 0, String(body.caja || ''));
        return json(res);
      }
      // GET /admin/corte/preguntas → preguntas que el bot no supo responder (base de conocimiento a curar). Admin.
      if (request.method === 'GET' && path === '/admin/corte/preguntas') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let rows = [];
        try { rows = (await env.DB.prepare("SELECT id, phone, pregunta, motivo, respondida, substr(created_at,1,19) AS ts FROM corte_preguntas ORDER BY respondida ASC, id DESC LIMIT 200").all()).results || []; } catch (_) {}
        let kb = '';
        try { kb = String(await kvGet(env, 'corte_knowledge', '') || ''); } catch (_) {}
        // Propuestas de aprendizaje pendientes (correcciones del copiloto → líneas para el KB).
        let propuestas = [];
        try { await ensureImprovementsSchema(env); propuestas = (await env.DB.prepare("SELECT id, title, rationale, evidence, proposed_content, confidence, substr(created_at,1,19) AS ts FROM framework_improvements WHERE vertical='corte' AND status='pending' ORDER BY id DESC LIMIT 50").all()).results || []; } catch (_) {}
        return json({ ok: true, preguntas: rows, knowledge: kb, propuestas });
      }
      // POST /admin/corte/aprender → corre la síntesis del corte (correcciones del copiloto + preguntas → propuestas al KB). Admin.
      if (request.method === 'POST' && path === '/admin/corte/aprender') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let body = {}; try { body = await request.json(); } catch (_) {}
        const res = await synthesizeCorteKnowledge(env, { force: body?.force !== false, createdBy: session.user });
        return json(res);
      }
      // POST /admin/corte/knowledge → suma/reemplaza el CONOCIMIENTO ADICIONAL del bot (kv corte_knowledge).
      // body { add:"texto" } agrega un renglón; { set:"texto" } reemplaza todo. Opcional { marcar_respondida:id }.
      if (request.method === 'POST' && path === '/admin/corte/knowledge') {
        if ((await getSessionRole(env, session.user)) !== 'admin') return json({ error: 'forbidden' }, 403);
        let body = {}; try { body = await request.json(); } catch (_) {}
        let kb = '';
        try { kb = String(await kvGet(env, 'corte_knowledge', '') || ''); } catch (_) {}
        if (typeof body.set === 'string') kb = body.set.trim();
        else if (typeof body.add === 'string' && body.add.trim()) kb = (kb ? (kb + '\n') : '') + '- ' + body.add.trim();
        try { await kvSet(env, 'corte_knowledge', kb); } catch (_) {}
        if (body.marcar_respondida) { try { await env.DB.prepare("UPDATE corte_preguntas SET respondida=1 WHERE id=?").bind(parseInt(body.marcar_respondida, 10)).run(); } catch (_) {} }
        return json({ ok: true, knowledge: kb });
      }

      // GET /admin/analytics/precotiz-funnel  →  funnel pre-cotización de carteles por mes
      // + cohorte revivible (últimos 60 días sin presupuesto). Solo admin; query pesada
      // (scan de wa_messages) — no llamar en polls.
      if (request.method === 'GET' && path === '/admin/analytics/precotiz-funnel') {
        const role = await getSessionRole(env, session.user);
        if (role !== 'admin') return json({ error: 'forbidden' }, 403);
        return analyticsPrecotizFunnel(env, url);
      }

      // POST /admin/briefs/:id/generar-render  →  pipeline IA completo en paralelo:
      if (request.method === 'POST' && /^\/admin\/briefs\/\d+\/generar-render$/.test(path)) {
        const briefId = path.split('/')[3];
        if (!env.GEMINI_API_KEY) return json({ error: 'Falta configurar GEMINI_API_KEY en el worker' }, 503);
        if (!env.MEDIA) return json({ error: 'R2 not configured' }, 500);

        const brief = await env.DB.prepare('SELECT * FROM briefs WHERE id = ?').bind(briefId).first();
        if (!brief) return json({ error: 'brief not found' }, 404);

        // Prioridad de imagen input: boceto > captura de chat más reciente.
        let inputRow = await env.DB.prepare(
          "SELECT r2_key, content_type, tipo FROM brief_imagenes WHERE brief_id = ? AND tipo = 'boceto' ORDER BY orden DESC, id DESC LIMIT 1"
        ).bind(briefId).first();
        let inputOrigen = 'boceto';
        if (!inputRow) {
          inputRow = await env.DB.prepare(
            "SELECT r2_key, content_type, tipo FROM brief_imagenes WHERE brief_id = ? AND tipo = 'chat' ORDER BY orden DESC, id DESC LIMIT 1"
          ).bind(briefId).first();
          inputOrigen = 'chat';
        }
        if (!inputRow) return json({ error: 'No hay imagen para generar (subí un boceto o una captura del cliente)' }, 400);

        const obj = await env.MEDIA.get(inputRow.r2_key);
        if (!obj) return json({ error: 'imagen no encontrada en R2' }, 404);
        const inputBuf = await obj.arrayBuffer();

        // Contexto para AMBOS prompts: lo que Joaco escribió, lo que ya está en
        // el brief Y las notas del usuario (instrucciones específicas para esta
        // generación, ej: "letras en cursiva", "color verde", "agregar marco", etc.).
        const contextoLines = [];
        if (brief.cliente_nombre) contextoLines.push(`Cliente / título: ${brief.cliente_nombre}`);
        if (brief.medidas_libre) contextoLines.push(`Medidas que pidió el cliente: ${brief.medidas_libre}`);
        if (brief.ancho_cm) contextoLines.push(`Ancho ya definido: ${brief.ancho_cm} cm`);
        if (brief.alto_cm) contextoLines.push(`Alto ya definido: ${brief.alto_cm} cm`);
        if (brief.neon_mt) contextoLines.push(`Neón ya definido: ${brief.neon_mt} m`);
        if (brief.notas && String(brief.notas).trim()) {
          contextoLines.push(`\nNOTAS / INSTRUCCIONES ESPECÍFICAS PARA ESTE DISEÑO (tomalas en cuenta):\n${String(brief.notas).trim()}`);
        }
        let contexto = contextoLines.join('\n');

        // Corpóreas (tipo='corporea'): prompt distinto (letra 3D maciza, no neón) +
        // contexto del caso visual A-E (según qué caras son translúcidas/opacas) que
        // se antepone. NO se estima neón/ancho/alto como en carteles — las medidas las
        // carga el usuario en el form, así que params queda null.
        const esCorporea = brief.tipo === 'corporea';
        if (esCorporea) {
          contexto = corporeaContexto(brief) + (contexto ? `\n\n${contexto}` : '');
        }

        // En PARALELO: render (caro, lento) + params (barato, rápido).
        // Si una falla y la otra OK, devolvemos lo que hay y reportamos el error parcial.
        const [renderResult, paramsResult] = await Promise.all([
          generarRenderConGemini(env, inputBuf, inputRow.content_type, contexto, esCorporea ? { basePrompt: GEMINI_CORPOREA_RENDER_PROMPT } : {}),
          esCorporea ? Promise.resolve({ ok: false, error: null }) : estimarParametrosConGemini(env, inputBuf, inputRow.content_type, contexto)
        ]);

        // Render es lo crítico: si falla, error duro (sin render no hay nada que devolver).
        if (renderResult.error) return json({ error: 'render: ' + renderResult.error, params_error: paramsResult.error }, 502);

        // Guardar el render en R2.
        let renderBuf;
        try { renderBuf = Uint8Array.from(atob(renderResult.base64), c => c.charCodeAt(0)).buffer; }
        catch (e) { return json({ error: 'no se pudo decodificar la imagen de Gemini' }, 500); }
        const ext = (renderResult.mime.split('/')[1] || 'png').replace(/[^a-z0-9]/gi, '').slice(0, 8) || 'png';
        const r2Key = `briefs/${briefId}/render-ia-${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
        await env.MEDIA.put(r2Key, renderBuf, { httpMetadata: { contentType: renderResult.mime } });

        const ordRow = await env.DB.prepare(
          "SELECT COALESCE(MAX(orden), -1) + 1 AS next_ord FROM brief_imagenes WHERE brief_id = ? AND tipo = 'render'"
        ).bind(briefId).first();
        const now = new Date().toISOString();
        const result = await env.DB.prepare(
          "INSERT INTO brief_imagenes (brief_id, r2_key, content_type, size_bytes, orden, created_at, tipo) VALUES (?,?,?,?,?,?, 'render')"
        ).bind(briefId, r2Key, renderResult.mime, renderBuf.byteLength, ordRow?.next_ord ?? 0, now).run();

        // La IA SOLO SUGIERE medidas — NO sobreescribe los campos del brief.
        // El diseñador (Emma) las completa a mano: la IA puede errar y la diseñadora
        // sabe las medidas reales. La response devuelve los valores estimados como
        // referencia (se muestran en un cartel de sugerencia en el frontend), pero
        // ancho_cm / alto_cm / neon_mt del brief quedan tal cual estaban.
        let paramsOut = null;
        if (paramsResult.ok) {
          paramsOut = {
            ancho_cm: paramsResult.ancho_cm,
            alto_cm: paramsResult.alto_cm,
            neon_mt: paramsResult.neon_mt,
            razonamiento: paramsResult.razonamiento,
            dif_vs_cliente: paramsResult.dif_vs_cliente
          };
        }
        await env.DB.prepare('UPDATE briefs SET updated_at = ? WHERE id = ?').bind(now, briefId).run();

        return json({
          id: result.meta.last_row_id, brief_id: parseInt(briefId, 10),
          r2_key: r2Key, content_type: renderResult.mime, tipo: 'render', created_at: now,
          input_origen: inputOrigen,
          params: paramsOut,
          params_error: paramsResult.error || null
        }, 201);
      }

      // POST /admin/briefs/:id/generar-ia  →  DISEÑADOR IA en 2 etapas (planner gemini-2.5-pro
      // que razona el criterio de Emma + imagen gemini-3-pro-image) con aspecto forzado.
      // Guarda el boceto en R2 + ia_boceto_key / ia_plan / ia_generado_at. La MEDICIÓN
      // (neón/alto/tramos) la hace el frontend por CV sobre el boceto y la guarda vía PATCH ia_*.
      if (request.method === 'POST' && /^\/admin\/briefs\/\d+\/generar-ia$/.test(path)) {
        const briefId = path.split('/')[3];
        if (!env.GEMINI_API_KEY || !env.MEDIA) return json({ error: 'falta GEMINI_API_KEY o MEDIA' }, 503);
        const b = await env.DB.prepare("SELECT tipo, medidas_libre, notas, ancho_cm, alto_cm FROM briefs WHERE id=?").bind(briefId).first();
        if (!b) return json({ error: 'brief no existe' }, 404);
        const img = await env.DB.prepare("SELECT r2_key, content_type FROM brief_imagenes WHERE brief_id=? AND tipo='chat' ORDER BY orden DESC, id DESC LIMIT 1").bind(briefId).first();
        if (!img) return json({ error: 'el brief no tiene imagen de referencia del cliente (chat)' }, 400);
        const obj = await env.MEDIA.get(img.r2_key);
        if (!obj) return json({ error: 'no se encontró la referencia en R2' }, 404);
        const buf = await obj.arrayBuffer();
        const mime = (img.content_type || 'image/png').split(';')[0];
        const ctxParts = [];
        if (b.medidas_libre) ctxParts.push('Medida pedida por el cliente: ' + b.medidas_libre + '.');
        if (b.notas) ctxParts.push('Tipografía / nota del pedido: ' + b.notas + '.');
        ctxParts.push('Ubicación: ' + (b.tipo === 'EXT' ? 'exterior' : 'interior') + '.');
        // Si Emma todavía no cargó ancho/alto, los sacamos de la medida que pidió el
        // cliente (medidas_libre) para poder forzar el aspecto y darle los cm al planner.
        let aW = b.ancho_cm, aH = b.alto_cm;
        if ((!aW || !aH) && b.medidas_libre) {
          const ml = String(b.medidas_libre).toLowerCase();
          const nums = (ml.match(/[0-9]+(?:[.,][0-9]+)?/g) || []).map(x => parseFloat(x.replace(',', '.')));
          const conv = (v) => (/\bm\b|mt|metro/.test(ml) && v > 0 && v < 10) ? v * 100 : v;
          if (nums.length >= 2 && /x/.test(ml)) { if (!aW) aW = Math.round(conv(nums[0])); if (!aH) aH = Math.round(conv(nums[1])); }
          else if (nums.length >= 1 && !aW) aW = Math.round(conv(nums[0]));
        }
        if (aW && aH) ctxParts.push('El cartel mide ' + aW + ' cm de ancho por ' + aH + ' cm de alto (relación ' + (aW / aH).toFixed(1) + ':1).');
        else if (aW) ctxParts.push('El cartel mide aproximadamente ' + aW + ' cm de ancho.');
        const ctxTxt = ctxParts.join('\n');
        const aspect = iaAspectFromDims(aW, aH);
        // ETAPA 1 — planner (texto+visión) razona el plan con el criterio de Emma
        let planText = null;
        try {
          const planFull = GEMINI_IA_PLAN_PROMPT + '\n\nCONTEXTO DEL PEDIDO:\n' + ctxTxt;
          const pbody = { contents: [{ parts: [{ text: planFull }, { inline_data: { mime_type: mime, data: abToBase64(buf) } }] }], generationConfig: { temperature: 0.3 } };
          const pr = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-pro:generateContent?key=${env.GEMINI_API_KEY}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(pbody) });
          if (pr.ok) { const pd = await pr.json(); planText = pd?.candidates?.[0]?.content?.parts?.map(x => x.text).filter(Boolean).join('') || null; try { await geminiTrackUsage(env, 'gemini-2.5-pro', 'ia-plan', pd?.usageMetadata, 'ia-plan-' + briefId); } catch (_) {} }
        } catch (_) {}
        // ETAPA 2 — imagen dibuja el plan
        const extraTexto = 'CONTEXTO DEL PEDIDO:\n' + ctxTxt + (planText ? '\n\n═══ PLAN DEL DISEÑO (seguilo EXACTO) ═══\n' + planText : '');
        const iaImgModel = env.GEMINI_IA_IMAGE_MODEL || 'gemini-3-pro-image';
        const opts = { basePrompt: GEMINI_IA_IMG_PROMPT, ref: 'ia-boceto-' + briefId, model: iaImgModel };
        if (aspect) opts.aspectRatio = aspect;
        const r = await generarRenderConGemini(env, buf, mime, extraTexto, opts);
        if (!r.ok) return json({ error: 'diseño IA: ' + r.error }, 502);
        let bytes;
        try { bytes = Uint8Array.from(atob(r.base64), c => c.charCodeAt(0)); } catch (e) { return json({ error: 'no se pudo decodificar la imagen' }, 500); }
        const ext = (r.mime.split('/')[1] || 'jpeg').replace(/[^a-z0-9]/gi, '').slice(0, 8) || 'jpeg';
        const key = `briefs/${briefId}/ia-boceto-${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
        await env.MEDIA.put(key, bytes, { httpMetadata: { contentType: r.mime } });
        const now = new Date().toISOString();
        await env.DB.prepare("UPDATE briefs SET ia_boceto_key=?, ia_plan=?, ia_generado_at=?, ia_modo=COALESCE(NULLIF(ia_modo,''),'ambos'), ia_feedback=NULL, updated_at=? WHERE id=?")
          .bind(key, planText || '', now, now, briefId).run();
        return json({ ok: true, ia_boceto_key: key, content_type: r.mime, plan: planText, aspect, generado_at: now });
      }

      // DELETE /admin/briefs/:id/imagen/:imgId  →  borra de R2 + DB.
      if (request.method === 'DELETE' && /^\/admin\/briefs\/\d+\/imagen\/\d+$/.test(path)) {
        const parts = path.split('/');
        const briefId = parts[3];
        const imgId = parts[5];
        const row = await env.DB.prepare(
          'SELECT r2_key FROM brief_imagenes WHERE id = ? AND brief_id = ?'
        ).bind(imgId, briefId).first();
        if (!row) return json({ error: 'not found' }, 404);
        try { if (env.MEDIA) await env.MEDIA.delete(row.r2_key); } catch (e) { /* ignorar fallos de R2 */ }
        await env.DB.prepare('DELETE FROM brief_imagenes WHERE id = ?').bind(imgId).run();
        await env.DB.prepare('UPDATE briefs SET updated_at = ? WHERE id = ?').bind(new Date().toISOString(), briefId).run();
        return noContent();
      }

      // ===== DEBUG: test download de media desde el worker =====
      if (request.method === 'GET' && /^\/admin\/360\/media-test\/\d+$/.test(path)) {
        const mediaId = path.split('/').pop();
        try {
          const result = await downloadMedia(env, mediaId);
          if (!result) return json({ error: 'downloadMedia returned null', mediaId });
          return json({ ok: true, mediaId, ...result });
        } catch (e) {
          return json({ error: e.message, mediaId });
        }
      }

      // ===== 360dialog webhook config (echoes de WA Business) =====
      // GET ver config actual, PUT actualizar fields suscritos.
      if (request.method === 'GET' && path === '/admin/360/webhook') {
        if (!env.D360_API_KEY) return json({ error: 'D360_API_KEY not configured' }, 500);
        try {
          const r = await fetch('https://waba-v2.360dialog.io/v1/configs/webhook', {
            headers: { 'D360-API-KEY': env.D360_API_KEY, 'Accept': 'application/json' }
          });
          const text = await r.text();
          let body; try { body = JSON.parse(text); } catch { body = text; }
          return json({ status: r.status, body });
        } catch (e) {
          return json({ error: e.message }, 500);
        }
      }
      if (request.method === 'POST' && path === '/admin/360/webhook') {
        if (!env.D360_API_KEY) return json({ error: 'D360_API_KEY not configured' }, 500);
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        try {
          const r = await fetch('https://waba-v2.360dialog.io/v1/configs/webhook', {
            method: 'POST',
            headers: { 'D360-API-KEY': env.D360_API_KEY, 'Content-Type': 'application/json', 'Accept': 'application/json' },
            body: JSON.stringify(body)
          });
          const text = await r.text();
          let resp; try { resp = JSON.parse(text); } catch { resp = text; }
          return json({ status: r.status, body: resp });
        } catch (e) {
          return json({ error: e.message }, 500);
        }
      }

      // ===== Team chat (chat global del equipo, flotante) =====
      // Reusa brief_messages con brief_id = 0 (hilo general, no atado a un brief).
      if (request.method === 'GET' && path === '/admin/team-chat') {
        const limit = Math.min(parseInt(url.searchParams.get('limit') || '100'), 500);
        const rs = await env.DB.prepare(
          'SELECT * FROM brief_messages WHERE brief_id = 0 ORDER BY created_at DESC LIMIT ?'
        ).bind(limit).all();
        const _msgs = (rs.results || []).reverse();
        // Emma no ve qué vendedor escribe (podría deducir de quién es un brief): los vendedores salen como 'vendedor'.
        if ((await getSessionRole(env, session.user)) === 'disenador') for (const m of _msgs) { const a = String(m.autor_id || '').toLowerCase(); if (!['gaspar', 'disenador', 'emma', 'emmanuel'].includes(a)) m.autor_id = 'vendedor'; }
        return json({ messages: _msgs });
      }
      if (request.method === 'POST' && path === '/admin/team-chat') {
        let body;
        try { body = await request.json(); } catch { return json({ error: 'invalid json' }, 400); }
        if (!body.autor_id || !body.contenido) return json({ error: 'missing fields' }, 400);
        const now = new Date().toISOString();
        const result = await env.DB.prepare(
          'INSERT INTO brief_messages (brief_id, autor_id, tipo, contenido, created_at) VALUES (0,?,?,?,?)'
        ).bind(body.autor_id, body.tipo || 'text', body.contenido, now).run();
        return json({ id: result.meta.last_row_id, created_at: now }, 201);
      }
      // PUT /admin/team-chat/imagen?autor=joaco  →  sube imagen a R2 + mensaje tipo='image'.
      if (request.method === 'PUT' && path === '/admin/team-chat/imagen') {
        if (!env.MEDIA) return json({ error: 'R2 not configured' }, 500);
        const ct = request.headers.get('content-type') || '';
        if (!ct.startsWith('image/')) return json({ error: 'only image/* allowed' }, 400);
        const autor = url.searchParams.get('autor') || 'joaco';
        const buf = await request.arrayBuffer();
        if (!buf || buf.byteLength === 0) return json({ error: 'empty body' }, 400);
        if (buf.byteLength > 10 * 1024 * 1024) return json({ error: 'too large (>10MB)' }, 413);
        const ext = (ct.split('/')[1] || 'bin').replace(/[^a-z0-9]/gi, '').slice(0, 8) || 'bin';
        const r2Key = `teamchat/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
        try { await env.MEDIA.put(r2Key, buf, { httpMetadata: { contentType: ct } }); }
        catch (e) { return json({ error: 'r2 put failed: ' + e.message }, 500); }
        const now = new Date().toISOString();
        const result = await env.DB.prepare(
          'INSERT INTO brief_messages (brief_id, autor_id, tipo, contenido, created_at) VALUES (0,?,?,?,?)'
        ).bind(autor, 'image', r2Key, now).run();
        return json({ id: result.meta.last_row_id, r2_key: r2Key, tipo: 'image', autor_id: autor, contenido: r2Key, created_at: now }, 201);
      }

      // ===== Producción de NEÓN (/admin/prod/*) — productores con usuario propio (15-oct-2026) =====
      // Los productores SOLO llegan acá (muro de /admin). Cada uno ve y toca únicamente SUS carteles; lo de Gaspar
      // (alta de productores, asignar, pagar) exige rol admin. Ver productorDeSesion / calcManoObra.
      if (path.startsWith('/admin/prod/')) {
        if (!(await ensureProdSchema(env))) return json({ error: 'db' }, 500);
        const _pzRol = await productorDeSesion(env, session.user);
        if (_pzRol && _pzRol.error) return json({ error: 'No se pudo verificar el usuario. Probá de nuevo en un momento.' }, 503);
        const _pzYo = _pzRol || (await prodExtraDeSesion(env, session.user));
        const _rolP = (_pzYo && !_pzYo.extra) ? 'productor' : await getSessionRole(env, session.user);
        const _esAdm = _rolP === 'admin';
        const _quien = String(session.user || '');
        const _soloAdmin = () => _esAdm ? null : json({ error: 'forbidden' }, 403);
        // El cartel ¿es de este productor? (el admin puede todo). Devuelve la fila o una Response de error.
        const _cartelDe = async (pid) => {
          const r = await env.DB.prepare('SELECT id, productor_id, prod_estado, prod_pagado_at, cantidad, es_corporeo FROM pedidos WHERE id = ?').bind(pid).first();
          if (!r || +r.es_corporeo) return json({ error: 'cartel no encontrado' }, 404);
          if (!_esAdm && (!_pzYo || String(r.productor_id || '') !== _pzYo.id)) return json({ error: 'ese cartel no es tuyo' }, 403);
          return r;
        };

        // GET /admin/prod/productores → productores (admin) con lo que tienen asignado, terminado y adeudado.
        if (request.method === 'GET' && path === '/admin/prod/productores') {
          const no = _soloAdmin(); if (no) return no;
          const prods = await prodProductores(env);
          const agg = (await env.DB.prepare(
            "SELECT productor_id AS id, SUM(CASE WHEN prod_estado <> 'terminado' THEN 1 ELSE 0 END) AS en_curso, " +
            "SUM(CASE WHEN prod_estado = 'terminado' AND prod_pagado_at IS NULL THEN 1 ELSE 0 END) AS sin_pagar, " +
            "SUM(CASE WHEN prod_estado = 'terminado' AND prod_pagado_at IS NULL THEN COALESCE(mo_monto,0) ELSE 0 END) AS adeudado " +
            "FROM pedidos WHERE COALESCE(productor_id,'') <> '' AND es_corporeo = 0 AND (prod_pagado_at IS NULL) GROUP BY productor_id"
          ).all()).results || [];
          const porId = {}; for (const a of agg) porId[a.id] = a;
          return json({ productores: prods.map(p => ({ ...p, en_curso: +(porId[p.id] || {}).en_curso || 0, sin_pagar: +(porId[p.id] || {}).sin_pagar || 0, adeudado: Math.round(+(porId[p.id] || {}).adeudado || 0) })) });
        }
        // POST /admin/prod/productores {usuario, nombre, password} → crea un productor o le cambia nombre/contraseña (admin).
        // usuario = con lo que entra (minúsculas, sin espacios). Nunca toma un usuario de otro rol.
        if (request.method === 'POST' && path === '/admin/prod/productores') {
          const no = _soloAdmin(); if (no) return no;
          let body; try { body = await request.json(); } catch { body = {}; }
          const id = prodSlug(body.usuario).replace(/\s+/g, '');
          const nombre = String(body.nombre || '').trim().slice(0, 40) || id;
          const pw = String(body.password || '');
          if (!/^[a-z0-9._-]{3,20}$/.test(id)) return json({ error: 'el usuario tiene que tener entre 3 y 20 letras o números, sin espacios' }, 400);
          if (PROD_RESERVADOS.includes(id)) return json({ error: 'ese usuario ya es de alguien del equipo, elegí otro' }, 400);
          const ex = await env.DB.prepare('SELECT rol FROM users_panel WHERE id = ?').bind(id).first();
          if (ex && ex.rol !== 'productor') return json({ error: 'ese usuario ya existe con otro rol, elegí otro' }, 400);
          if (!ex && pw.length < 8) return json({ error: 'la contraseña tiene que tener al menos 8 caracteres' }, 400);
          if (pw && pw.length < 8) return json({ error: 'la contraseña tiene que tener al menos 8 caracteres' }, 400);
          const now = new Date().toISOString();
          if (!ex) {
            await env.DB.prepare("INSERT INTO users_panel (id, nombre, rol, activo, password_hash, created_at) VALUES (?, ?, 'productor', 1, ?, ?)").bind(id, nombre, await sha256hex(pw), now).run();
          } else {
            if (pw) await env.DB.prepare("UPDATE users_panel SET nombre = ?, password_hash = ?, activo = 1 WHERE id = ? AND rol = 'productor'").bind(nombre, await sha256hex(pw), id).run();
            else await env.DB.prepare("UPDATE users_panel SET nombre = ? WHERE id = ? AND rol = 'productor'").bind(nombre, id).run();
            if (pw) await cerrarSesionesDe(env, id);
          }
          _prodSesCache.delete(id);
          return json({ ok: true, productor: { id, nombre } });
        }
        // POST /admin/prod/productores/estado {usuario, activo} → dar de baja (cierra sus sesiones) o reactivar (admin).
        if (request.method === 'POST' && path === '/admin/prod/productores/estado') {
          const no = _soloAdmin(); if (no) return no;
          let body; try { body = await request.json(); } catch { body = {}; }
          const id = prodSlug(body.usuario).replace(/\s+/g, '');
          const act = body.activo ? 1 : 0;
          const ex = await env.DB.prepare("SELECT COALESCE(password_hash,'') AS h FROM users_panel WHERE id = ? AND rol = 'productor'").bind(id).first();
          if (!ex) return json({ error: 'productor no encontrado' }, 404);
          // Activo sin contraseña = entra sin contraseña: para reactivar hay que ponerle una.
          if (act && !ex.h) return json({ error: 'primero ponele una contraseña (así se activa)' }, 400);
          await env.DB.prepare("UPDATE users_panel SET activo = ? WHERE id = ? AND rol = 'productor'").bind(act, id).run();
          _prodSesCache.delete(id);
          if (!act) await cerrarSesionesDe(env, id);
          return json({ ok: true });
        }
        // GET /admin/prod/tablero → todo lo de producción para Gaspar: carteles de neón de los últimos 120 días que
        // siguen en curso o sin pagar (con precio y mano de obra), y los productores.
        if (request.method === 'GET' && path === '/admin/prod/tablero') {
          const no = _soloAdmin(); if (no) return no;
          const desde = new Date(Date.now() - 120 * 864e5).toISOString().slice(0, 10);
          const carteles = await prodCarteles(env,
            "WHERE p.es_corporeo = 0 AND ((p.fecha >= ? AND (COALESCE(p.productor_id,'') <> '' OR COALESCE(p.estado_pedido,'') NOT IN ('Entregado','para enviar'))) OR (COALESCE(p.productor_id,'') <> '' AND p.prod_pagado_at IS NULL)) ORDER BY p.fecha DESC, p.id DESC LIMIT 600",
            [desde], false);
          return json({ carteles, productores: await prodProductores(env) });
        }
        // POST /admin/prod/asignar {pedido_ids:[], productor_id} → asigna (o saca, con '') el productor de esos carteles (admin).
        if (request.method === 'POST' && path === '/admin/prod/asignar') {
          const no = _soloAdmin(); if (no) return no;
          let body; try { body = await request.json(); } catch { body = {}; }
          const ids = (Array.isArray(body.pedido_ids) ? body.pedido_ids : []).map(Number).filter(n => n > 0).slice(0, 200);
          const pid = prodSlug(body.productor_id).replace(/\s+/g, '');
          if (!ids.length) return json({ error: 'faltan los carteles' }, 400);
          let prod = null;
          if (pid) {
            prod = (await prodProductores(env)).find(p => p.id === pid) || null;
            if (!prod || prod.baja) return json({ error: 'ese productor no existe o está dado de baja' }, 400);
          }
          const rows = [];
          for (let i = 0; i < ids.length; i += 90) { const l = ids.slice(i, i + 90); rows.push(...(((await env.DB.prepare(`SELECT id, productor_id, prod_estado, prod_pagado_at, es_corporeo FROM pedidos WHERE id IN (${l.map(() => '?').join(',')})`).bind(...l).all()).results) || [])); }
          // Cambiarle el productor a un cartel que ya se está armando o está terminado: pedir confirmación (el trabajo y su
          // pago pasan al nuevo). Sin forzar → 409 con el detalle para que el front pregunte.
          const enCurso = rows.filter(r => !+r.es_corporeo && !r.prod_pagado_at && String(r.productor_id || '') && String(r.productor_id || '') !== pid && ['en_armado', 'terminado'].includes(String(r.prod_estado || '')));
          if (enCurso.length && !body.forzar) return json({ error: 'confirmar', confirmar: true, carteles: enCurso.map(r => ({ id: r.id, estado: r.prod_estado, productor_id: r.productor_id })) }, 409);
          const now = new Date().toISOString(), stmts = [], log = [], saltados = [];
          for (const r of rows) {
            if (+r.es_corporeo) { saltados.push({ id: r.id, motivo: 'es corpóreo' }); continue; }
            if (r.prod_pagado_at) { saltados.push({ id: r.id, motivo: 'ya está pagado' }); continue; }
            if (String(r.productor_id || '') === pid) continue;
            if (pid) stmts.push(env.DB.prepare("UPDATE pedidos SET productor_id = ?, productor = ?, prod_estado = CASE WHEN COALESCE(prod_estado,'') = '' THEN 'pendiente' ELSE prod_estado END, prod_estado_at = CASE WHEN COALESCE(prod_estado,'') = '' THEN ? ELSE prod_estado_at END, prod_asignado_at = ? WHERE id = ?").bind(pid, String(prod.nombre || pid), now, now, r.id));
            else stmts.push(env.DB.prepare("UPDATE pedidos SET productor_id = '', productor = '', prod_estado = CASE WHEN prod_estado = 'terminado' THEN prod_estado ELSE '' END, prod_asignado_at = NULL WHERE id = ?").bind(r.id));
            log.push({ pedido_id: r.id, campo: 'productor', de: r.productor_id || '', a: pid, por: _quien });
          }
          if (stmts.length) await env.DB.batch(stmts);
          await prodLog(env, log);
          try { await moActualizar(env, ids); } catch (_) {}
          return json({ ok: true, cambiados: stmts.length, saltados, carteles: await prodCartelesPorIds(env, ids) });
        }
        // POST /admin/prod/pagar {pedido_ids:[], pagado:true|false} → marca la producción como pagada (o lo deshace) (admin).
        if (request.method === 'POST' && path === '/admin/prod/pagar') {
          const no = _soloAdmin(); if (no) return no;
          let body; try { body = await request.json(); } catch { body = {}; }
          const ids = (Array.isArray(body.pedido_ids) ? body.pedido_ids : []).map(Number).filter(n => n > 0).slice(0, 300);
          if (!ids.length) return json({ error: 'faltan los carteles' }, 400);
          const now = new Date().toISOString();
          // Antes de congelar: que la mano de obra esté calculada con los datos de hoy. Sin mano de obra (faltan tramos o
          // medidas) no se congela: se devuelve en 'saltados' (salvo forzar).
          let aPagar = ids, saltados = [];
          if (body.pagado) {
            try { await moActualizar(env, ids); } catch (_) {}
            if (!body.forzar) {
              const sinMo = [];
              for (let i = 0; i < ids.length; i += 90) { const l = ids.slice(i, i + 90); sinMo.push(...(((await env.DB.prepare(`SELECT id FROM pedidos WHERE id IN (${l.map(() => '?').join(',')}) AND mo_monto IS NULL`).bind(...l).all()).results) || []).map(x => x.id)); }
              saltados = sinMo.map(id => ({ id, motivo: 'falta la mano de obra (tramos o medidas)' }));
              aPagar = ids.filter(id => !sinMo.includes(id));
            }
          }
          let cambiados = 0;
          for (let i = 0; i < aPagar.length; i += 90) {
            const l = aPagar.slice(i, i + 90), ph = l.map(() => '?').join(',');
            const r = body.pagado
              ? await env.DB.prepare(`UPDATE pedidos SET prod_pagado_at = ?, prod_pagado_por = ? WHERE id IN (${ph}) AND COALESCE(productor_id,'') <> '' AND prod_pagado_at IS NULL`).bind(now, _quien, ...l).run()
              : await env.DB.prepare(`UPDATE pedidos SET prod_pagado_at = NULL, prod_pagado_por = '' WHERE id IN (${ph}) AND prod_pagado_at IS NOT NULL`).bind(...l).run();
            cambiados += (r && r.meta && r.meta.changes) || 0;
          }
          await prodLog(env, aPagar.map(id => ({ pedido_id: id, campo: 'pagado', de: body.pagado ? '' : 'si', a: body.pagado ? 'si' : '', por: _quien })));
          return json({ ok: true, cambiados, saltados, carteles: await prodCartelesPorIds(env, ids) });
        }
        // GET /admin/prod/mis → los carteles del productor (sin precio de venta): en curso, terminados sin pagar y lo
        // pagado de los últimos 60 días. El admin puede ver los de cualquiera con ?productor=<usuario>.
        if (request.method === 'GET' && path === '/admin/prod/mis') {
          const quien = _esAdm ? prodSlug(url.searchParams.get('productor')).replace(/\s+/g, '') : (_pzYo && _pzYo.id);
          if (!quien) return json({ error: _esAdm ? 'falta ?productor=' : 'forbidden' }, _esAdm ? 400 : 403);
          const hace60 = new Date(Date.now() - 60 * 864e5).toISOString();
          const carteles = await prodCarteles(env, "WHERE p.productor_id = ? AND p.es_corporeo = 0 AND (p.prod_pagado_at IS NULL OR p.prod_pagado_at >= ? OR IFNULL(p.prod_estado,'') <> 'terminado') ORDER BY CASE p.prod_estado WHEN 'en_armado' THEN 0 WHEN 'pendiente' THEN 1 ELSE 2 END, p.fecha, p.id", [quien, hace60], true);
          const prod = _pzYo || (await prodProductores(env)).find(p => p.id === quien) || null;
          return json({ productor: prod ? { id: prod.id, nombre: prod.nombre } : { id: quien, nombre: quien }, carteles });
        }
        // POST /admin/prod/estado {pedido_id, estado, forzar?} → el productor pone el estado de SU cartel. 'terminado'
        // exige las fotos del cartel terminado (una por cartel); el admin puede forzarlo. Pagado = ya no se cambia.
        if (request.method === 'POST' && path === '/admin/prod/estado') {
          let body; try { body = await request.json(); } catch { body = {}; }
          const pidN = Number(body.pedido_id) || 0, est = String(body.estado || '');
          if (!PROD_ESTADOS.includes(est)) return json({ error: 'estado inválido' }, 400);
          const r = await _cartelDe(pidN); if (r instanceof Response) return r;
          if (!String(r.productor_id || '')) return json({ error: 'ese cartel todavía no tiene productor' }, 400);
          // Pagado: queda congelado para el productor, salvo marcarlo terminado si Gaspar le pagó por adelantado (si no, la tarjeta
          // quedaba trabada en Montando).
          if (r.prod_pagado_at && !_esAdm && !(est === 'terminado' && String(r.prod_estado || '') !== 'terminado')) return json({ error: 'ese cartel ya está pagado, no se puede cambiar' }, 409);
          if (est === 'terminado') {
            const nf = +(await env.DB.prepare('SELECT COUNT(*) AS n FROM pedido_prod_fotos WHERE pedido_id = ?').bind(pidN).first()).n || 0;
            const req = prodFotosRequeridas(r);
            if (nf < req && !(_esAdm && body.forzar)) return json({ error: req > 1 ? `subí una foto de cada cartel terminado (${req}) antes de marcarlo` : 'subí la foto del cartel terminado antes de marcarlo', faltan: req - nf }, 400);
          }
          if (String(r.prod_estado || '') === est) return json({ ok: true, sin_cambios: true });
          const now = new Date().toISOString();
          await env.DB.prepare('UPDATE pedidos SET prod_estado = ?, prod_estado_at = ?, prod_terminado_at = CASE WHEN ? = \'terminado\' THEN ? ELSE NULL END WHERE id = ?').bind(est, now, est, now, pidN).run();
          await prodLog(env, [{ pedido_id: pidN, campo: 'estado', de: r.prod_estado || '', a: est, por: _quien }]);
          // Reabrió un cartel terminado y el pedido estaba 'para enviar' porque lo puso el tablero (sync): vuelve a 'En produccion'
          // (todo el grupo, con espejo y log) para que Pedidos y la planilla no digan 'para enviar' mientras lo rehacen.
          if (String(r.prod_estado || '') === 'terminado' && est !== 'terminado') {
            try {
              const gq = await neonGrupoDe(env, pidN);
              const ids = [...new Set([pidN, ...(gq.fr || []).map(x => x.id), ...(gq.serv || []).map(x => x.id)])];
              const pe = await env.DB.prepare("SELECT estado_pedido FROM pedidos WHERE id = ?").bind(pidN).first();
              const lg = await env.DB.prepare("SELECT por FROM pedido_estado_log WHERE pedido_id IN (" + ids.map(() => '?').join(',') + ") AND lower(a) LIKE 'para enviar%' ORDER BY ts DESC LIMIT 1").bind(...ids).first();
              const sigueParaEnviar = (gq.fr || []).length && gq.fr.every(x => ['enviar', 'enviado'].includes(x._etapa));
              if (pe && /^para enviar/i.test(String(pe.estado_pedido || '')) && lg && String(lg.por || '') === 'tablero' && !sigueParaEnviar) {
                const u = await env.DB.prepare("UPDATE pedidos SET estado_pedido = 'En produccion', mirror_dirty = 1, mirror_attempts = 0, mirror_error = NULL, updated_at = ? WHERE id IN (" + ids.map(() => '?').join(',') + ") AND lower(IFNULL(estado_pedido,'')) LIKE 'para enviar%'").bind(now, ...ids).run();
                if (((u.meta && u.meta.changes) || 0) && gq.base) await env.DB.prepare('INSERT INTO pedido_estado_log (pedido_id, numero, fecha, comercial_id, telefono, de, a, por, ts) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)').bind(pidN, gq.base.numero, gq.base.fecha, gq.base.comercial_id || 'joaco', gq.base.telefono || '', 'para enviar', 'En produccion', 'tablero', now).run();
              }
            } catch (_) {}
          }
          return json({ ok: true, carteles: await prodCarteles(env, 'WHERE p.id = ?', [pidN], !_esAdm) });
        }
        // PUT /admin/prod/foto?pedido_id=N (imagen cruda) → foto del cartel terminado (el productor de ese cartel o el admin).
        if (request.method === 'PUT' && path === '/admin/prod/foto') {
          const pidN = Number(url.searchParams.get('pedido_id')) || 0;
          const r = await _cartelDe(pidN); if (r instanceof Response) return r;
          if (r.prod_pagado_at && !_esAdm && String(r.prod_estado || '') === 'terminado') return json({ error: 'ese cartel ya está pagado' }, 409);
          if (!env.MEDIA) return json({ error: 'R2 not configured' }, 500);
          const cl = parseInt(request.headers.get('content-length') || '0', 10) || 0;
          if (cl > 12 * 1024 * 1024) return json({ error: 'la foto pesa más de 12MB' }, 413);
          const buf = await request.arrayBuffer().catch(() => null);
          if (!buf || !buf.byteLength) return json({ error: 'la foto llegó vacía' }, 400);
          if (buf.byteLength > 12 * 1024 * 1024) return json({ error: 'la foto pesa más de 12MB' }, 413);
          // El tipo sale de los BYTES (no del header): un productor no puede subir un SVG/HTML que se sirva con el token de otro.
          const _b = new Uint8Array(buf.slice(0, 12));
          const _asc = (a, b) => String.fromCharCode(..._b.slice(a, b));
          const ct = (_b[0] === 0xFF && _b[1] === 0xD8 && _b[2] === 0xFF) ? 'image/jpeg'
            : (_b[0] === 0x89 && _asc(1, 4) === 'PNG') ? 'image/png'
            : (_asc(0, 4) === 'RIFF' && _asc(8, 12) === 'WEBP') ? 'image/webp'
            : (_asc(4, 8) === 'ftyp' && /^(heic|heix|hevc|mif1|msf1|heim|heis)$/.test(_asc(8, 12))) ? 'image/heic' : '';
          if (!ct) return json({ error: 'eso no es una foto (JPG, PNG, WEBP o HEIC)' }, 400);
          const nYa = +(await env.DB.prepare('SELECT COUNT(*) AS n FROM pedido_prod_fotos WHERE pedido_id = ?').bind(pidN).first()).n || 0;
          if (nYa >= 12) return json({ error: 'ya tiene 12 fotos' }, 400);
          const ext = (ct.split('/')[1] || 'jpg').replace(/[^a-z0-9]/gi, '').slice(0, 8) || 'jpg';
          const ym = new Date(Date.now() - 3 * 3600e3).toISOString().slice(0, 7).replace('-', '');
          const key = `pedidos/prod/${ym}/${pidN}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
          try { await env.MEDIA.put(key, buf, { httpMetadata: { contentType: ct } }); } catch (e) { return json({ error: 'no se pudo guardar la foto' }, 500); }
          await env.DB.prepare('INSERT INTO pedido_prod_fotos (pedido_id, r2_key, subido_por, created_at) VALUES (?,?,?,?)').bind(pidN, key, _quien, new Date().toISOString()).run();
          return json({ ok: true, key, carteles: await prodCarteles(env, 'WHERE p.id = ?', [pidN], !_esAdm) });
        }
        // POST /admin/prod/foto/borrar {foto_id} → saca una foto (no si el cartel ya está terminado y quedaría sin las que pide).
        if (request.method === 'POST' && path === '/admin/prod/foto/borrar') {
          let body; try { body = await request.json(); } catch { body = {}; }
          const f = await env.DB.prepare('SELECT id, pedido_id, r2_key FROM pedido_prod_fotos WHERE id = ?').bind(Number(body.foto_id) || 0).first();
          if (!f) return json({ error: 'foto no encontrada' }, 404);
          const r = await _cartelDe(f.pedido_id); if (r instanceof Response) return r;
          if (r.prod_pagado_at && !_esAdm && String(r.prod_estado || '') === 'terminado') return json({ error: 'ese cartel ya está pagado' }, 409);
          if (r.prod_estado === 'terminado' && !_esAdm) {
            const nf = +(await env.DB.prepare('SELECT COUNT(*) AS n FROM pedido_prod_fotos WHERE pedido_id = ?').bind(f.pedido_id).first()).n || 0;
            if (nf - 1 < prodFotosRequeridas(r)) return json({ error: 'el cartel está terminado: subí otra foto antes de sacar esta' }, 400);
          }
          await env.DB.prepare('DELETE FROM pedido_prod_fotos WHERE id = ?').bind(f.id).run();
          try { if (env.MEDIA) await env.MEDIA.delete(f.r2_key); } catch (_) {}
          return json({ ok: true, carteles: await prodCarteles(env, 'WHERE p.id = ?', [f.pedido_id], !_esAdm) });
        }
        // GET /admin/prod/img/<key>?token= → imagen de un cartel (diseño o terminado). El productor solo las de SUS carteles.
        if (request.method === 'GET' && path.startsWith('/admin/prod/img/')) {
          const key = decodeURIComponent(path.slice('/admin/prod/img/'.length));
          if (!/^(pedidos|briefs)\/[\w\-./]+$/.test(key) || key.indexOf('..') >= 0) return json({ error: 'imagen inválida' }, 400);
          if (!_esAdm) {
            let ok = false;
            if (_pzYo) {
              const a = await env.DB.prepare('SELECT 1 AS x FROM pedido_prod_fotos f JOIN pedidos p ON p.id = f.pedido_id WHERE f.r2_key = ? AND p.productor_id = ? LIMIT 1').bind(key, _pzYo.id).first();
              const b = a ? null : await env.DB.prepare('SELECT 1 AS x FROM corte_pedidos c JOIN pedidos p ON p.id = c.pedido_id WHERE c.foto_key = ? AND p.productor_id = ? LIMIT 1').bind(key, _pzYo.id).first();
              const d = (a || b) ? null : await env.DB.prepare('SELECT 1 AS x FROM pedidos WHERE foto_diseno_key = ? AND productor_id = ? LIMIT 1').bind(key, _pzYo.id).first();
              ok = !!(a || b || d);
            } else ok = ['comercial', 'disenador'].includes(_rolP); // vendedores: ven las fotos de producción en Pedidos
            if (!ok) return json({ error: 'forbidden' }, 403);
          }
          if (!env.MEDIA) return json({ error: 'R2 not configured' }, 500);
          const obj = await env.MEDIA.get(key);
          if (!obj) return json({ error: 'not found' }, 404);
          const _ctImg = String((obj.httpMetadata && obj.httpMetadata.contentType) || '').toLowerCase();
          return new Response(obj.body, { headers: { ...cors(), 'Content-Type': /^image\/(jpeg|png|webp|heic|heif|gif)$/.test(_ctImg) ? _ctImg : 'application/octet-stream', 'Cache-Control': 'private, max-age=86400', 'X-Content-Type-Options': 'nosniff', 'Content-Security-Policy': "default-src 'none'; sandbox" } });
        }
        // POST /admin/prod/recalcular-mo {pedido_ids?} → recalcula la mano de obra (admin). Sin ids: los carteles de neón
        // en curso o sin pagar de los últimos 120 días (sirve tras cambiar los parámetros o al arrancar).
        if (request.method === 'POST' && path === '/admin/prod/recalcular-mo') {
          const no = _soloAdmin(); if (no) return no;
          let body; try { body = await request.json(); } catch { body = {}; }
          let ids = (Array.isArray(body.pedido_ids) ? body.pedido_ids : []).map(Number).filter(n => n > 0);
          if (!ids.length) {
            const desde = new Date(Date.now() - 120 * 864e5).toISOString().slice(0, 10);
            ids = ((await env.DB.prepare("SELECT id FROM pedidos WHERE es_corporeo = 0 AND prod_pagado_at IS NULL AND fecha >= ? LIMIT 800").bind(desde).all()).results || []).map(r => r.id);
          }
          let n = 0; for (let i = 0; i < ids.length; i += 100) n += await moActualizar(env, ids.slice(i, i + 100));
          return json({ ok: true, revisados: ids.length, cambiados: n });
        }
        // POST /admin/prod/excel-sync → corre YA el envío de mano de obra y productor al 2026 v4 (admin).
        if (request.method === 'POST' && path === '/admin/prod/excel-sync') {
          const no = _soloAdmin(); if (no) return no;
          return json({ ok: true, ...(await barrerMoDirecto(env)) });
        }
        return json({ error: 'not found' }, 404);
      }

      // GET /admin/users-panel  →  lista de usuarios del panel (comerciales/diseñadores/admin)
      if (request.method === 'GET' && path === '/admin/users-panel') {
        const rs = await env.DB.prepare(
          'SELECT id, nombre, rol, activo FROM users_panel WHERE activo = 1 ORDER BY rol, nombre'
        ).all();
        return json({ users: rs.results || [] });
      }

      return json({ error: 'not found' }, 404);
    }

    return json({ error: 'not found' }, 404);
  },

  // ===== Cron Trigger =====
  // Corre cada 5 min. Procesa: 1) mensajes programados, 2) followups (solo a las 13:00 UTC).
  async scheduled(event, env, ctx) {
    // Índices de performance (1 sola vez, guard kv). Evita full-scans que saturan D1.
    ctx.waitUntil(ensurePerfIndexes(env));
    // Cola de auto-respuestas (minicurso): corre en CADA tick, incluido el cron
    // dedicado de cada minuto, para que la demora sea ~1-2 min y no más.
    ctx.waitUntil(processAutoReplyQueue(env));
    // Espejo de pedidos al Excel de Ventas (gateado por flag kv 'pedidos_mirror_on';
    // no hace nada hasta que se active tras deployar el Apps Script).
    // SOLO en el cron de cada minuto (*/1): en ambos crons (*/1 y */5), los minutos múltiplos de 5
    // lo disparaban 2× EN PARALELO y, como el APPEND de un pedido nuevo (sheet_row=0) no tiene
    // reserva atómica (a diferencia del write-back, que sí chequea updated_at), apendeaba el mismo
    // pedido DOS veces → filas duplicadas en el Sheet (caso corpóreo LOOP #359, 8-sep). Gatearlo a
    // un cron lo evita, sin perder latencia (igual corre cada minuto). Mismo criterio que el piloto.
    if (event.cron === '* * * * *') ctx.waitUntil(processPedidosMirror(env));
    // Procesar respuestas pendientes del gate de feedback del minicurso:
    // espera 2 min al cliente, junta todos los mensajes, manda a la IA y decide.
    ctx.waitUntil(processMinicursoGiftPending(env));
    // Idem para la campaña de cursos (respuesta al template 1): espera 2 min,
    // junta todos los mensajes, IA decide entre encolar cursos_evento o revelar.
    ctx.waitUntil(processCursosCampaignPending(env));
    // Recuperar media (imagenes/videos/audios) que fallaron en el webhook por
    // race condition con Meta. Reintenta los media_id raw recientes (<2 hs);
    // los viejos ya caducaron en Meta y no tiene sentido reintentarlos.
    ctx.waitUntil(processPendingMedia(env));
    // Cola de goteo del broadcast de cursos: procesa los queued con due_at
    // vencido. Encolados vía POST /admin/wa/cursos-broadcast-schedule.
    ctx.waitUntil(processCursosBroadcastQueue(env));
    // Goteo del broadcast de JUNIO 2026. Encolado vía /admin/wa/junio-broadcast-schedule.
    ctx.waitUntil(processJunioBroadcastQueue(env));
    // Goteo del broadcast "1 cupo · Comunidad Al Infinito" a no-pagadores del form de junio.
    ctx.waitUntil(processCupoBroadcastQueue(env));
    ctx.waitUntil(processCustomBroadcasts(env));
    ctx.waitUntil(processBroadcastReplies(env));
    ctx.waitUntil(processBroadcastFollowups(env));
    ctx.waitUntil(processCursosFlow(env));
    // Backfill del reenvío de comprobantes a Gaspar (lanzamiento, hoy+mañana):
    // reintenta los inbound media que el reenvío en vivo no logró mandar (glitch
    // de Meta o ventana 24h momentáneamente cerrada). Idempotente vía kv_cache,
    // se auto-apaga pasada la ventana, y si no hay pendientes no hace nada.
    ctx.waitUntil(processGasparResendBackfill(env));
    ctx.waitUntil(processCentinelaRuteo(env));   // centinela de ruteo: cura/avisa perdidos·duplicados·mal-segmentados (self-throttle 30min)
    ctx.waitUntil(processSinResponder(env));     // alarma "sin responder": lead cotizado/con intención sin contestar +Nh → digest al vendedor + Gaspar (self-throttle 15min, gate sin_responder_on)
    // Recordatorio de COBRO de los pedidos cargados sin pago (10 y 18 AR, lun-sáb; cada 10 min dentro de esa hora con claim).
    if (new Date().getUTCMinutes() % 10 === 0) ctx.waitUntil(processCobrosPendientes(env));
    // Resúmenes del aviso del sitio del corte a Gaspar (kv corte_web_resumenes).
    if (new Date().getUTCMinutes() % 5 === 0) ctx.waitUntil(processCorteWebResumen(env));
    // Piloto de pre cotización automática (carteles): capta leads del 20% y los
    // releva con freno de mano. Gateado internamente (kill-switch OFF por defecto
    // + horario 8-22 AR). Corre en cada tick para responder en ~1-2 min.
    // SOLO en el cron de cada minuto (*/1). Antes corría en ambos crons (*/1 y */5) y en los
    // minutos múltiplos de 5 se disparaba 2 veces en paralelo -> doble procesamiento/envío. Las
    // reservas atómicas ya evitan el duplicado, pero gatearlo a un cron evita el trabajo doble.
    if (event.cron === '* * * * *') {
      ctx.waitUntil(processPrecotizPilot(env));
      ctx.waitUntil(processCortePilot(env));   // bot de corte: cada minuto para responder rápido (gate corte_bot_on)
      ctx.waitUntil(processCorteVigiaAuto(env)); // vigía de pagos: corre SIEMPRE (aunque el bot esté off) para el día de cobro (gate corte_vigia_on)
      ctx.waitUntil(processCorteEntregaSync(env)); // entrega retira/envío desde la planilla de cortes (1×hora, 8-21 AR; kill-switch corte_entrega_sync_on)
      // Nudge del piloto: persigue leads a medias que se callaron (cada 15 min; gate 9-21 AR adentro).
      // OJO: usamos getUTCMinutes() INLINE, no la var `minute` (que recién se declara con const más
      // abajo, línea ~10932 -> referenciarla acá era ReferenceError por TDZ en cada tick */1).
      if (new Date().getUTCMinutes() % 15 === 0) ctx.waitUntil(processPrecotizNudges(env));
    }
    // Landing del minicurso gratuito: opener a los 45 min (plantilla) + branch por
    // IA + follow-up 23h. Gateado (kill-switch OFF por defecto + horario 8-22 AR).
    // Corre en cada tick para responder rápido; guardia anti-choque con el flujo de ads.
    ctx.waitUntil(processMinicursoLanding(env));
    // Landing del LANZAMIENTO (Fase Semilla): mismo mecanismo (opener a los 45 min por
    // plantilla). NO-OP hasta que se configure kv 'lanzamiento_opener_tpl' + kv
    // 'lanzamiento_landing_on'='1' — los leads solo se acumulan en la tabla mientras tanto.
    ctx.waitUntil(processLanzamientoLanding(env));
    // Re-envío del nuevo link del grupo a los que recibieron el link viejo (grupo lleno).
    // OFF por defecto (kv 'resend_evento_link_on'); gotea en lotes y se apaga solo al terminar.
    ctx.waitUntil(processResendEventoLink(env));
    // Recordatorio del evento (Fase Semilla): goteo a los anotados. Master switch OFF por
    // defecto (kv 'evento_recordatorio_on'); no manda nada hasta prenderlo.
    ctx.waitUntil(processEventoRecordatorio(env));
    ctx.waitUntil(processSorteoDia2(env));
    // Envío masivo goteo "lanzamiento agosto" (Comunidad Al Infinito): plantilla
    // cupo_comunidad_junio a los ~521 del form clase 1 sin pagar. OFF por defecto
    // (kv 'lanz_ago_on'); no manda nada hasta prenderlo.
    ctx.waitUntil(processLanzAgosto(env));
    ctx.waitUntil(processComunidadPromo(env));   // drip Pack Emprendedor a los 14 días del alta
    ctx.waitUntil(processEventoPres(env));       // difusión seminario presencial (kv 'seminario_on')
    // MiniSupernova SOLO en el cron */1 (NO en el */5 simultáneo): así nunca corren dos ticks en
    // paralelo en los minutos múltiplos de 5 y el tope de 50/día es EXACTO (sin carrera entre ticks
    // que lean el mismo contador de enviados-hoy y cada uno mande su cupo). Patrón de processPrecotizPilot.
    if (event.cron === '* * * * *') ctx.waitUntil(processMiniSupernova(env));   // difusión a alumnos (kv 'minisupernova_on')
    // Tick rápido (cron */1): solo la cola, no el resto de tareas pesadas.
    if (event.cron === '* * * * *') return;
    // Guardia de gasto del lanzamiento: avisa a Gaspar si el gasto de plantillas se dispara
    // (p.ej. el botón de la landing volvió a apuntar al grupo en vez del walink). Se auto-gatea.
    ctx.waitUntil(processLaunchGuard(env));
    ctx.waitUntil(processScheduledMessages(env));
    // Órdenes de compra: detecta las OC salientes nuevas → etiqueta "POR PAGAR" + avisa a
    // Gaspar/hermano + snapshot (métrica del reporte + popup "Pedido por vender URGENTE").
    ctx.waitUntil(processOrdenesCompra(env));
    // Vigilador de pago: en los chats "POR PAGAR", cuando entra un comprobante (OCR) →
    // saca "POR PAGAR" y pone "Cartel primer pago".
    ctx.waitUntil(processCartelPagos(env));
    // Levanta audios que el webhook bajó a R2 pero no logró transcribir en vivo.
    ctx.waitUntil(processPendingTranscripts(env));
    // Refresca el token largo de IG antes de que venza (se autogatea a 1 vez/día).
    ctx.waitUntil(igMaybeRefreshToken(env));
    // Cada ~30 min: traer del Excel de Ventas el campo `productor` (Gaspar lo carga ahí).
    if (new Date().getUTCMinutes() % 30 < 5) ctx.waitUntil(syncProductoresFromVentas(env));
    // Cada ~15 min: importar los pedidos nuevos del Excel -> trazarles el ad automáticamente.
    if (new Date().getUTCMinutes() % 15 < 5) ctx.waitUntil((async () => {
      try { await importNewPedidosFromVentas(env); } catch (_) {}
      try { await traceUntaggedPedidos(env); } catch (_) {}
      // Red de seguridad de la matriz de Emma: carteles de neón del CRM sin pieza de corte → se crea.
      try { await ensureCortePiezasNeonPendientes(env); } catch (_) {}
      // Vendedor de los pedidos de neón → 2026 v4 (Pedidos_Directo col C): relleno + reintentos.
      try { await barrerVendedoresNeon(env); } catch (_) {}
      // Mano de obra y productor de los pedidos de neón nuevos → 2026 v4 (Pedidos_Directo, columnas MO y PRODUCTOR).
      try { await barrerMoDirecto(env); } catch (_) {}
      // Tablero de neón: 'para enviar' en la planilla cuando el pedido está terminado y pagado (kv neon_estado_sync_on).
      try { await neonSyncEstados(env); } catch (_) {}
      // Registro de envíos: se borra lo de más de 120 días.
      try { await env.DB.prepare('DELETE FROM wa_envios_log WHERE ts < ?').bind(new Date(Date.now() - 120 * 864e5).toISOString()).run(); } catch (_) {}
      // Precios de los insumos del sitio del corte desde la planilla (COGS, mes en curso).
      try { await corteInsumosPreciosSheet(env, { refrescar: true }); } catch (_) {}
      // Caja de la seña → col Z de Pedidos_Corporeo / Pedidos_Directo (reintentos, IMPORTRANGE atrasado, cambios).
      try { await syncCajaPedidos(env); } catch (_) {}
    })());
    // 1×/hora: sincronizar la columna Ad al Excel desde D1 (match por nombre, drift-proof, solo huecos).
    if (new Date().getUTCMinutes() < 5) ctx.waitUntil(syncAdColumnToExcel(env));
    // Follow-ups en horario hábil AR (8-20): campaña de cursos + minicurso (4h sin responder).
    const hAR = (new Date(event.scheduledTime).getUTCHours() - 3 + 24) % 24;
    if (hAR >= 8 && hAR < 20) {
      ctx.waitUntil(processCursosFollowup(env));
      ctx.waitUntil(processMinicursoFollowup(env));
    }
    // Followups de Apps Script solo a las 13:00 UTC (10:00 AR)
    const hour = new Date(event.scheduledTime).getUTCHours();
    if (hour === 13) ctx.waitUntil(runScheduled(env));
    // Sync diario del mapa de anuncios de IG (post promocionado -> ad_id + campaña), para darle
    // a los leads de IG la misma trazabilidad que WhatsApp. No-op hasta que exista META_ADS_TOKEN.
    if (hour === 13) ctx.waitUntil(syncIgAdMap(env));
    // Sync del mapa de campañas de Meta para los leads de CTWA (WhatsApp): resuelve el ad_id de la
    // referral -> nombre de campaña/ad y backfillea wa_ad_attributions (venía siempre NULL). Diario.
    if (hour === 13) ctx.waitUntil(syncMetaAdMap(env));
    // GASTO de Meta por campaña y por anuncio (panel Funnel de Ads), una vez por hora (minuto 0): a las
    // 10 AR refresca 10 días (Meta ajusta el gasto hasta ~72h); el resto de las horas, los últimos 2 días
    // (así el mes en curso incluye el gasto de hoy). No-op sin META_ADS_TOKEN.
    if (new Date(event.scheduledTime).getUTCMinutes() < 5) {
      const dias = hour === 13 ? 10 : 1;
      ctx.waitUntil(syncMetaAdSpend(env, { since: new Date(Date.now() - 3 * 3600 * 1000 - dias * 24 * 3600 * 1000).toISOString().slice(0, 10) }));
    }
    // Follow-up automático de presupuestos del cotizador: solo horario hábil AR (8-20).
    // Usa hAR (calculado más arriba en este mismo handler) para consistencia
    // con processCursosFollowup/processMinicursoFollowup.
    // Seguimientos de presupuesto: NO los domingos (hora AR). Los que caen domingo
    // salen el lunes a primera hora (8 AR); el lunes ampliamos la ventana a 72h para
    // levantar el backlog del finde sin perder ninguno (el dedup evita repetir).
    const dowAR = new Date(new Date(event.scheduledTime).getTime() - 3 * 3600 * 1000).getUTCDay(); // 0=domingo
    if (hAR >= 8 && hAR <= 20 && dowAR !== 0) ctx.waitUntil(processPresupuestoFollowups(env, { maxAgeHours: dowAR === 1 ? 72 : 48 }));
    // Anti-colgados "⏳ Te toca": PAUSADO 2026-07-12 a pedido de Gaspar ("no lo usamos
    // tanto, hay que verlo bien después"). El código de processColgados queda intacto;
    // para reactivar, descomentar la línea de abajo.
    // if (hAR >= 8 && hAR <= 20) ctx.waitUntil(processColgados(env));
    // Motor de recuperación post-migración de número (drena a ritmo controlado, 9-20h).
    if (hAR >= 9 && hAR <= 20) ctx.waitUntil(processRecoveryQueue(env));
    // Aviso a Gaspar cuando el dataset ya tiene suficientes QualifiedLead (CAPI) para cambiar la campaña.
    if (hAR >= 9 && hAR <= 20) ctx.waitUntil(maybeCapiReadyNotice(env));
    // Aviso de arranque del equipo (a Gaspar): ping en tiempo real cuando cada uno arranca a
    // trabajar + resumen a las 9 AR de quién arrancó y quién no. Dedup por día adentro. Corre cada */5.
    ctx.waitUntil(maybeAvisoArranque(env));
    // Vigía de logística: avisa a Gaspar si la pantalla de logística falla o queda un dato raro, la primera vez que anda
    // cada función y un resumen a las 13 y las 19 AR (kv 'logistica_vigia_on'; 7-22 AR adentro).
    ctx.waitUntil(processLogiVigia(env));
    // Pedidos de corte por la web: filas de la planilla de Emma, resumen del cierre (sábado 12 h) y carga automática de la
    // tanda (sáb 21 h, dom 21 h, lun 7:30). Kill-switches: corte_hoja_auto_on, corte_autocarga_on.
    ctx.waitUntil(corteLandingCron(env));
    // Recordatorios de la Agenda del equipo (reuniones/tareas). Gate kv 'agenda_recordatorios_on'
    // (default OFF hasta aprobar la plantilla). Dedup por (evento, ocurrencia, usuario, tipo) adentro.
    ctx.waitUntil(maybeAgendaRecordatorios(env));
    // Reporte diario de ventas a las 21:00 AR (a Gaspar + su hermano). Dedup por día adentro.
    if (hAR === 21) ctx.waitUntil(maybeReporteDiario(env));
    if (hAR === 21) ctx.waitUntil(maybeReporteHoras(env));
    // Reporte diario de la campaña MiniSupernova a las 21:00 AR (a Gaspar + Bruno). Dedup por día adentro.
    if (hAR === 21) ctx.waitUntil(maybeReporteMiniSupernova(env));
    // Guía de Producción (evento 8-sep): (1) reporte a Gaspar+Bruno con la cantidad de guías
    // enviadas, DESPUÉS de las 19hs AR; (2) a partir del JUEVES 18hs AR, las conversaciones
    // ocultas de la guía pasan a la bandeja de Abril (cursos). Ambas gateadas por kv de tiempo
    // absoluto (guia_produccion_reporte_at / _reveal_at) + dedup adentro, así corren en cualquier tick.
    ctx.waitUntil(maybeGuiaReporte(env));
    ctx.waitUntil(maybeGuiaReveal(env));
    // Aviso "leads para llamar" (fup 1 del presupuesto sin respuesta) a las 9 AR.
    // + lista "para llamar" de Agus (bandejas Agus + Joaco, misma base). En SERIE: las dos corren la misma
    // query pesada; en paralelo duplicaban la carga sobre D1 en el mismo tick.
    if (hAR === 9) ctx.waitUntil((async () => { await maybeReporteLlamar(env); await maybeListaAgus(env); })());
    // 10 AR (lun-sáb): a cada vendedor, SUS órdenes de compra sin pagar (kv lista_oc_on; default apagado).
    if (hAR === 10) ctx.waitUntil(maybeListaOC(env));
    // Plantillas "al toque": mandar las que Meta ya aprobó (horario hábil AR 8-21).
    if (hAR >= 8 && hAR < 21) ctx.waitUntil(processPendingTemplateSends(env));
    if (hAR === 5) ctx.waitUntil(maybeAdhocCleanup(env));   // limpieza diaria de plantillas ad-hoc viejas (kv adhoc_cleanup_on/_days)
    // Monitor de status de templates: 1 vez por hora, no cada 5 min. El polling
    // es fallback; lo ideal es suscribir al webhook field 'message_template_status_update'
    // en el hub de 360dialog (lo manejamos abajo en notifyTemplateStatusChange).
    const minute = new Date(event.scheduledTime).getUTCMinutes();
    if (minute < 5) ctx.waitUntil(monitorTemplateStatus(env));
    // Alarma "sin cotizar": cada 5 min DESTILDA a los que Joaco ya cotizó (dinámico,
    // barato); a :00 y :30 (8-22 AR) además ESCANEA y etiqueta los nuevos con +20hs.
    if (minute % 5 === 0) ctx.waitUntil(syncSinCotizar(env, { addPass: (minute % 30 === 0 && hAR >= 8 && hAR <= 22) }));
    // Avisos internos (Etapa 1): reconciliador de entregas + cola de silencio / tope / pausados + resúmenes de
    // resumen_horas (ventana :05-:20, lun-sáb) + purga diaria a las 5 AR. Solo en el cron */5 (nunca en el */1) y
    // en serie dentro de una medición de filas leídas (freno de costo). No hace nada con aviso_interno_modo='off'.
    ctx.waitUntil(processAvisosTick(env, { hAR, dowAR, minute }));
    // Escalación + limpieza de los "sin cotizar" con +10 días: 1 vez/día (10 AM AR),
    // avisa a Gaspar y los saca de la lista activa de Joaco. Lock diario adentro.
    if (hAR === 10 && minute === 0) ctx.waitUntil(escalarSinCotizarViejos(env));
    // Reflote de presupuesto: barrido SEMANAL (lunes 9 AM AR). Encola el segmento
    // cualificado de WA en el goteo de broadcast (rama IA prendida, sin ocultar).
    // Gated por kv reflote_on='1' + lock diario adentro.
    if (dowAR === 1 && hAR === 9 && minute === 0) ctx.waitUntil(processRefloteSweep(env));
    // Ranking semanal de insumos por ITEMS → Gaspar + hermano, MARTES 9 AR. Corre en
    // cada tick de las 9 (dedup por semana adentro) para tolerar un fallo puntual de red.
    if (dowAR === 2 && hAR === 9) ctx.waitUntil(maybeRankingInsumosSemanal(env));
    // Análisis de chats nuevos: 1 vez por hora (procesa hasta 15 chats que
    // tengan actividad nueva desde su último análisis o que nunca se analizaron).
    // Ignora phones internos. Idempotente: si no hay nada que analizar, no hace nada.
    if (minute < 5) ctx.waitUntil(processAnalysisPending(env));
    // Fase 2C: síntesis de mejoras al playbook. Antes corría SOLO lunes 13:00 (una ventana de 5
    // min por semana); si ese tick fallaba se perdía la semana entera y sin rastro. Ahora se
    // chequea 1 vez/día (13:00 UTC = 10 AR) y corre si pasaron ~7 días desde la última síntesis
    // -> self-healing (un día perdido lo agarra el siguiente). Igual tiene su gate de feedback y
    // NUNCA toca el playbook solo (deja propuestas 'pending' para que Gaspar apruebe).
    if (hour === 13 && minute < 5) {
      ctx.waitUntil(maybeWeeklySynthesis(env));
    }
  }
};

export default handler;

// Cron handler: procesa chats con actividad nueva. Limit conservador (5/hora)
// para respetar rate limits del tier 1 de Anthropic API (8k output tokens/min,
// 50 req/min). Si subimos de tier (agregando créditos) podemos aumentar.
// Tras el backfill inicial, los chats con actividad nueva por día son ~30-50,
// se procesan en ~10-12 horas con este ritmo.
async function processAnalysisPending(env) {
  if (!env.ANTHROPIC_API_KEY) return;
  try {
    const rs = await env.DB.prepare(
      `WITH chat_stats AS (
         SELECT phone, MAX(ts) AS last_ts, COUNT(*) AS n_msgs
         FROM wa_messages WHERE msg_type != 'reaction'
           AND phone NOT IN (SELECT phone FROM wa_internal_phones)
         GROUP BY phone
         HAVING n_msgs >= 3
       )
       SELECT cs.phone FROM chat_stats cs
       LEFT JOIN wa_conversations c ON c.phone = cs.phone
       WHERE c.last_analyzed_at IS NULL OR c.last_analyzed_at < cs.last_ts
          OR c.analysis_version < ?
       ORDER BY cs.last_ts DESC
       LIMIT 5`
    ).bind(ANALYSIS_PROMPT_VERSION).all();
    const phones = (rs.results || []).map(r => r.phone);
    if (!phones.length) return;
    // Procesamos secuencial (no Promise.all) para no superar el rate limit
    // de requests/minuto del API. Con 5 chats × ~3s c/u = 15s wall time.
    for (const p of phones) {
      try { await analyzeChatWithClaude(env, p, 'sonnet'); } catch (_) {}
    }
  } catch (_) {}
}

// ===== Monitor de templates: notifica al admin cuando cambia el status =====
async function monitorTemplateStatus(env) {
  if (!env.ADMIN_NOTIFY_PHONE) return;
  let _waM;
  try { _waM = getWaClient(env); } catch (_) { return; }
  if (_waM.provider === 'meta' && (!env.WA_BUSINESS_ACCOUNT_ID || !env.WA_TOKEN)) return;
  try {
    await env.DB.prepare('CREATE TABLE IF NOT EXISTS template_status_cache (name TEXT PRIMARY KEY, status TEXT NOT NULL, updated_at TEXT NOT NULL)').run();
    // 360dialog pagina de a 100 → recorrer con offset (sino las plantillas de la
    // página 2+ nunca se monitorean y no se notifica su aprobación/rechazo).
    const templates = [];
    for (let _off = 0; _off < 3000; _off += 100) {
      const sep = _waM.templatesUrl().includes('?') ? '&' : '?';
      const r = await fetch(`${_waM.templatesUrl()}${sep}limit=100&offset=${_off}&fields=name,status,category`, { headers: _waM.headers });
      if (!r.ok) break;
      const data = await r.json().catch(() => ({}));
      const batch = data?.data || data?.waba_templates || [];
      templates.push(...batch);
      if (batch.length < 100) break;
    }
    // [Etapa 1] También se guarda la CATEGORÍA (mig 051): la cadena de los avisos internos solo usa UTILITY. Se
    // compara status Y categoría, así la primera pasada después del deploy completa la categoría de todas (las
    // filas viejas la tienen vacía) y un cambio de categoría sin cambio de status ya no pasa desapercibido.
    const conCat = await ensureTplCategoryCol(env);
    for (const t of templates) {
      const name = t.name;
      const status = String(t.status || '').toUpperCase();   // 360dialog devuelve 'approved' en minúsculas; normalizamos
      const category = String(t.category || '').toUpperCase();
      if (!name || !status) continue;
      const cached = await env.DB.prepare(conCat ? "SELECT status, COALESCE(category, '') AS category FROM template_status_cache WHERE name = ?" : 'SELECT status FROM template_status_cache WHERE name = ?').bind(name).first();
      const prevStatus = cached?.status || null;
      const prevCat = conCat ? String(cached?.category || '') : category;
      if (prevStatus === status && prevCat === category) continue; // sin cambio
      if (conCat) {
        await env.DB.prepare(
          'INSERT INTO template_status_cache (name, status, category, updated_at) VALUES (?, ?, ?, ?) ON CONFLICT(name) DO UPDATE SET status = excluded.status, category = excluded.category, updated_at = excluded.updated_at'
        ).bind(name, status, category, new Date().toISOString()).run();
      } else {
        await env.DB.prepare(
          'INSERT INTO template_status_cache (name, status, updated_at) VALUES (?, ?, ?) ON CONFLICT(name) DO UPDATE SET status = excluded.status, updated_at = excluded.updated_at'
        ).bind(name, status, new Date().toISOString()).run();
      }
      // Solo notifica si pasó de PENDING a algo decidido (no en la primera carga del cache).
      const becameDecided = prevStatus === 'PENDING' && (status === 'APPROVED' || status === 'REJECTED');
      if (becameDecided) {
        const emoji = status === 'APPROVED' ? '✅' : '❌';
        const msg = `${emoji} Template "${name}" ahora está ${status}.`;
        try { await waSendText(env, env.ADMIN_NOTIFY_PHONE, msg, { esAviso: true }); } catch (_) {}
      }
      // Plantilla de los avisos internos que quedó en otra categoría o pausada/rechazada → P1 a Gaspar.
      await avisoTplCategoriaCheck(env, name, status, category);
    }
  } catch (e) {
    await logWaEvent(env, { to: '', kind: 'template-monitor', ref: '', ok: false, error: e.message });
  }
}

// ===== Scheduled Messages =====
async function processScheduledMessages(env) {
  if (await isWaBillingBlocked(env)) return; // pausado por bloqueo de pago de WhatsApp
  const now = new Date().toISOString();
  let rows;
  try {
    const rs = await env.DB.prepare(
      "SELECT id, phone, body, scheduled_at, created_at, template, template_params, lang FROM scheduled_messages WHERE status = 'pending' AND scheduled_at <= ? ORDER BY scheduled_at ASC LIMIT 50"
    ).bind(now).all();
    rows = rs.results || [];
  } catch (e) {
    // Table might not exist yet
    console.error('scheduled_messages query error:', e);
    return;
  }
  if (!rows.length) return;
  for (const msg of rows) {
    // CANCELAR si el cliente nos volvió a escribir desde que se programó (retomó la
    // conversación) → no mandamos nada, se sigue hablando normal.
    try {
      const since = msg.created_at || '1970-01-01';
      const reply = await env.DB.prepare(
        "SELECT 1 FROM wa_messages WHERE phone = ? AND direction = 'inbound' AND msg_type != 'reaction' AND ts > ? LIMIT 1"
      ).bind(msg.phone, since).first();
      if (reply) {
        await env.DB.prepare("UPDATE scheduled_messages SET status = 'cancelled', error = 'cliente respondió' WHERE id = ?").bind(msg.id).run();
        await logWaEvent(env, { to: msg.phone, kind: 'scheduled-cancel', ref: `sched:${msg.id}`, ok: true, error: 'cliente retomó la conversación' });
        continue;
      }
    } catch (_) {}
    // ¿Ventana de 24h abierta? (último inbound < 24h). Si está abierta y hay texto
    // libre → lo mandamos (personalizado). Si está cerrada → plantilla aprobada.
    let windowOpen = false;
    try {
      const li = await env.DB.prepare("SELECT MAX(ts) AS t FROM wa_messages WHERE phone = ? AND direction = 'inbound'").bind(msg.phone).first();
      windowOpen = !!(li && li.t && (Date.now() - new Date(li.t).getTime()) < 24 * 60 * 60 * 1000);
    } catch (_) {}
    let r, sentBody = msg.body, sentType = 'text';
    if (windowOpen && msg.body) {
      r = await waSendText(env, msg.phone, msg.body);
    } else if (msg.template) {
      let params = []; try { params = JSON.parse(msg.template_params || '[]'); } catch (_) {}
      r = await waSendTemplate(env, msg.phone, msg.template, msg.lang || 'es_AR', Array.isArray(params) ? params : []);
      sentBody = '[plantilla: ' + msg.template + ']'; sentType = 'template';
    } else if (msg.body) {
      r = await waSendText(env, msg.phone, msg.body); // ventana cerrada y sin plantilla: probablemente falle
    } else {
      r = { ok: false, error: 'sin contenido' };
    }
    const sentAt = new Date().toISOString();
    if (r.ok) {
      await env.DB.prepare(
        "UPDATE scheduled_messages SET status = 'sent', sent_at = ?, wamid = ? WHERE id = ?"
      ).bind(sentAt, r.id || '', msg.id).run();
      // Guardar en wa_messages para que aparezca en el chat.
      try {
        await env.DB.prepare(
          'INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
        ).bind(sentAt, r.id || '', 'outbound', msg.phone, '', sentType, sentBody, '', '', 'sent').run();
      } catch (_) {}
    } else {
      await env.DB.prepare(
        "UPDATE scheduled_messages SET status = 'failed', error = ? WHERE id = ?"
      ).bind(r.error || 'unknown error', msg.id).run();
    }
    await logWaEvent(env, { to: msg.phone, kind: 'scheduled', ref: `sched:${msg.id}`, ok: r.ok, messageId: r.id, error: r.error });
  }
}

// ===== Followups =====
// Recibe items: [{ to, name, milestone: 'D30'|'D60'|'D90'|'PPTO', pedidoId?, message? }]
// Si milestone es D30/D60/D90 o PPTO y no hay message, usa la plantilla preconfigurada.
const FOLLOWUP_TEMPLATES = {
  // Reemplazar por nombres de plantillas UTILITY aprobadas en Meta cuando esten listas.
  // Por ahora usa la plantilla aprobada generica para validar el flujo.
  D30:  { name: 'prueba_de_plantilla', lang: 'es' },
  D60:  { name: 'prueba_de_plantilla', lang: 'es' },
  D90:  { name: 'prueba_de_plantilla', lang: 'es' },
  PPTO: { name: 'prueba_de_plantilla', lang: 'es' }
};

async function runFollowups(env, items) {
  const sent = [], skipped = [], errors = [];
  for (const it of items) {
    const to = it?.to;
    const name = it?.name || 'cliente';
    const milestone = it?.milestone || '';
    const ref = it?.pedidoId ? `${milestone}:${it.pedidoId}` : milestone;
    if (!to) { skipped.push({ ref, reason: 'sin telefono' }); continue; }
    if (!normalizeArPhone(to)) { skipped.push({ ref, reason: 'telefono invalido' }); continue; }

    // Idempotencia: si ya se envio hoy un followup con el mismo ref, saltar.
    const today = new Date().toISOString().slice(0, 10);
    try {
      const existing = await env.DB.prepare(
        "SELECT 1 FROM wa_log WHERE ref = ? AND ok = 1 AND substr(ts, 1, 10) = ? LIMIT 1"
      ).bind(ref, today).first();
      if (existing) { skipped.push({ ref, reason: 'ya enviado hoy' }); continue; }
    } catch (_) {}

    let r;
    if (it.message) {
      // texto libre (solo funciona dentro de ventana 24h)
      r = await waSendText(env, to, it.message);
    } else {
      const tpl = FOLLOWUP_TEMPLATES[milestone] || FOLLOWUP_TEMPLATES.PPTO;
      r = await waSendTemplate(env, to, tpl.name, tpl.lang, [name]);
    }
    await logWaEvent(env, { to, kind: 'followup:' + milestone, ref, ok: r.ok, messageId: r.id, error: r.error });
    if (r.ok) sent.push({ ref, id: r.id });
    else errors.push({ ref, error: r.error });
  }
  return { sent: sent.length, skipped: skipped.length, errors: errors.length, detail: { sent, skipped, errors } };
}

// ===== Auto-labeling por keywords =====
// Cuando llega un inbound con texto, analizamos el body buscando keywords
// que matcheen reglas. Si matchea, le aplicamos la etiqueta correspondiente
// al contacto (idempotente vía INSERT OR IGNORE).
//
// Reglas hardcodeadas v1. Si más adelante se quiere editar desde UI, mover
// a una tabla `auto_label_rules (label_id, keywords TEXT, created_at)` y
// loadearla acá. Por ahora, simple y directo.
const AUTO_LABEL_RULES = [
  {
    label: 'interesado curso',
    // Keywords case-insensitive. Match si el body contiene CUALQUIERA.
    // Acentos opcionales: la comparación normaliza ambas puntas.
    keywords: [
      'curso', 'cursos', 'comunidad', 'capacitacion', 'capacitación',
      'aprender', 'taller', 'clase', 'clases', 'alumno', 'alumna',
      'inscribir', 'inscripcion', 'inscripción', 'formacion', 'formación',
      'estudiar', 'aprendizaje', 'enseñan', 'ensenan'
    ]
  },
  {
    label: 'interesado cartel',
    keywords: [
      'cartel', 'carteles', 'neon', 'neón', 'letrero', 'letreros',
      'luminoso', 'luminosa', 'rotulo', 'rótulo', 'logo', 'iluminar',
      'cotizacion', 'cotización', 'cotizar', 'presupuesto', 'precio',
      'medidas', 'diseño', 'render', 'fachada'
    ]
  }
];

function _normalizeForMatch(s) {
  return String(s || '')
    .toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, ''); // saca acentos
}

async function applyAutoLabels(env, phone, body) {
  const haystack = _normalizeForMatch(body);
  if (!haystack) return;
  const matched = [];
  for (const rule of AUTO_LABEL_RULES) {
    for (const kw of rule.keywords) {
      const needle = _normalizeForMatch(kw);
      // Word boundary aproximado: separador o inicio/fin alrededor.
      const re = new RegExp(`(^|[^a-z0-9])${needle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}([^a-z0-9]|$)`);
      if (re.test(haystack)) { matched.push(rule.label); break; }
    }
  }
  if (!matched.length) return;
  // Resolver IDs de las labels que matchearon
  for (const labelName of matched) {
    try {
      const row = await env.DB.prepare('SELECT id FROM labels WHERE name = ?').bind(labelName).first();
      if (!row?.id) continue;
      await env.DB.prepare(
        'INSERT OR IGNORE INTO contact_labels (phone, label_id, created_at) VALUES (?, ?, ?)'
      ).bind(phone, row.id, new Date().toISOString()).run();
    } catch (_) {}
  }
}

// ===== Follow-up automático de presupuestos del cotizador =====
// Detecta presupuestos enviados desde el cotizador (texto que arranca con un prefijo conocido),
// que no fueron respondidos ni recibieron follow-up, y manda un mensaje de insistencia.
// Si algun envio falla y hay ADMIN_NOTIFY_PHONE configurado, manda un WA al admin con el resumen.
// Acepta AMBOS prefijos (viejo + nuevo) para no perder presupuestos históricos.
const PRESUPUESTO_PREFIXES_TEXT = [
  'Te comparto el presupuesto con la información detallada!',
  'Te comparto la información detallada!'
];
const PRESUPUESTO_PREFIX_TEXT = PRESUPUESTO_PREFIXES_TEXT[0]; // back-compat
const FOLLOWUP_PRESUPUESTO_TEXT = 'Aca te dejamos el presupuesto! Decinos que te parece? si hay algun cambio o ajuste que quieras hacer, tambien si tenes foto de donde lo vas a poner te podemos hacer un montaje digital de como quedaría!';
const FOLLOWUP_PRESUPUESTO_PREFIX_TEXT = 'Aca te dejamos el presupuesto!';

// ===== Variantes de follow-up de presupuesto =====
// Lógica de selección por fecha (AR):
//   - 24-jun a 30-jun (última semana junio): PROMO COPA + foto.
//   - Resto del tiempo: texto según monto del presupuesto (≷ $300.000).
//     - 'low'  → texto suave ("Holaa, cómo estás?")
//     - 'high' → texto pro ("Buenas! Avisanos qué te pareció")
//
// Detección del monto: regex que toma el MAYOR $XXX del body — captura el
// precio principal del cartel ignorando los accesorios chiquitos (Slim,
// Control, App). Si no parsea, default a 'low'.
const PROMO_COPA_START_UTC = '2026-06-24T03:00:00Z'; // 24-jun 00:00 AR (UTC-3)
const PROMO_COPA_END_UTC   = '2026-07-01T03:00:00Z'; // 1-jul 00:00 AR (UTC-3)
const PROMO_COPA_R2_KEY = 'promo/copa-mundial-junio.jpg';
const PROMO_COPA_CAPTION = 'Te quería avisar que estamos regalando copas del mundo a todos los que compren esta semana!\n\nAvísame si querías avanzar con el pedido, o si queres que te llamemos y te asesoremos!';
const FOLLOWUP_PRESUPUESTO_LOW_TEXT = 'Holaa, cómo estás? Pudiste chequear el presupuesto? Cualquier cosa podemos llamarte para asesorarte! Quedamos a disposición!';
const FOLLOWUP_PRESUPUESTO_HIGH_TEXT = 'Buenas! Avisanos qué te pareció el presupuesto! Si te cierra el precio, o si querés que veamos de mejorar los números.\nTe podemos llamar para asesorarte, o coordinamos una visita si estas por Capital federal o GBA.';
const FOLLOWUP_AMOUNT_THRESHOLD = 300000;
// Señales de que el cliente YA avanzó al cierre/compra → NO le mandamos follow-up
// automático (no se spamea a quien está comprando). Solo aparecen en el cierre
// (datos de pago / orden de compra), nunca en el presupuesto.
const FUP_CIERRE_MARKERS = ['neoninfinito.ok', 'orden de compra', 'datos de pago', '3840200500000051390011'];

// Prefijos de TODOS los possibles follow-ups (legacy + nuevos) para dedup.
// Si conv contiene un outbound que comience con CUALQUIERA de estos, ya tuvo
// follow-up y no se le manda otro.
const ALL_FOLLOWUP_PREFIXES_TEXT = [
  FOLLOWUP_PRESUPUESTO_PREFIX_TEXT,            // 'Aca te dejamos el presupuesto!' (legacy)
  'Te quería avisar que estamos regalando',    // copa
  'Holaa, cómo estás? Pudiste chequear',       // < 300k
  'Buenas! Avisanos qué te pareció',           // ≥ 300k
  '[plantilla: seguimiento_presupuesto]'       // contingencia ventana cerrada (template)
];

function extractPresupuestoAmount(body) {
  if (!body) return 0;
  // Toma el MAYOR número con $ del body. En el cotizador, el precio principal
  // del cartel siempre es mayor que los accesorios (Slim $18.7k, Control $25k,
  // App $38k). Si querés ser más estricto, cambia a "primer match después de
  // 'Base acrílica transparente'", pero el max es más robusto a cambios de
  // formato del cotizador.
  let max = 0;
  const re = /\$\s*([\d.]+)/g;
  let m;
  while ((m = re.exec(String(body))) !== null) {
    const raw = m[1].replace(/\./g, '');
    const n = parseInt(raw, 10);
    if (!isNaN(n) && n > max) max = n;
  }
  return max;
}

// Sube un buffer a Meta vía /media, devuelve el media_id (o null si falla).
// El media_id sirve para mandar mensajes type='image'|'video'|'document' SIN
// re-uploadear cada vez (válido por ~30 días).
async function uploadMediaToMeta(env, buf, mime, fileName) {
  try {
    const wa = getWaClient(env);
    if (wa.provider === 'meta' && !env.WA_TOKEN) return null;
    const fd = new FormData();
    fd.append('messaging_product', 'whatsapp');
    fd.append('file', new Blob([buf], { type: mime }), fileName);
    fd.append('type', mime);
    const r = await fetch(wa.mediaUploadUrl(), {
      method: 'POST',
      headers: wa.headers,
      body: fd
    });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) return null;
    return data.id || null;
  } catch (_) { return null; }
}

// Devuelve el media_id de Meta para una imagen en R2, cacheando el resultado
// en kv_cache. TTL 7 días — Meta caduca media_ids a ~30 días pero re-upload
// más frecuente es trivial. Si la imagen no está en R2, devuelve null y el
// caller debe fallback a texto.
async function getPromoMediaId(env, r2Key) {
  if (!env.MEDIA || !env.DB) return null;
  const cacheKey = 'promo_media:' + r2Key;
  // 1) Try cache válido.
  try {
    const row = await env.DB.prepare("SELECT v, updated_at FROM kv_cache WHERE k = ?").bind(cacheKey).first();
    if (row?.v && row.updated_at) {
      const ageMs = Date.now() - new Date(row.updated_at).getTime();
      if (ageMs < 7 * 24 * 60 * 60 * 1000) return row.v;
    }
  } catch (_) {}
  // 2) Re-upload desde R2.
  try {
    const obj = await env.MEDIA.get(r2Key);
    if (!obj) return null;
    const buf = await obj.arrayBuffer();
    const mime = obj.httpMetadata?.contentType || 'image/jpeg';
    const fileName = r2Key.split('/').pop() || 'image.jpg';
    const mediaId = await uploadMediaToMeta(env, buf, mime, fileName);
    if (!mediaId) return null;
    try {
      await env.DB.prepare(
        "INSERT INTO kv_cache (k, v, updated_at) VALUES (?, ?, ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v, updated_at = excluded.updated_at"
      ).bind(cacheKey, mediaId, new Date().toISOString()).run();
    } catch (_) {}
    return mediaId;
  } catch (_) { return null; }
}

async function waSendImage(env, to, mediaId, caption, opts = {}) {
  const num = normalizeArPhone(to);
  if (!num) return { ok: false, status: 400, error: 'numero invalido' };
  return waSend(env, {
    messaging_product: 'whatsapp',
    to: num,
    type: 'image',
    image: { id: mediaId, caption: caption || undefined }
  }, opts);
}

async function waSendDocument(env, to, mediaId, filename, caption, opts = {}) {
  const num = normalizeArPhone(to);
  if (!num) return { ok: false, status: 400, error: 'numero invalido' };
  return waSend(env, {
    messaging_product: 'whatsapp',
    to: num,
    type: 'document',
    document: { id: mediaId, filename: filename || undefined, caption: caption || undefined }
  }, opts);
}

async function waSendVideo(env, to, mediaId, caption) {
  const num = normalizeArPhone(to);
  if (!num) return { ok: false, status: 400, error: 'numero invalido' };
  return waSend(env, {
    messaging_product: 'whatsapp',
    to: num,
    type: 'video',
    video: { id: mediaId, caption: caption || undefined }
  });
}

async function processPresupuestoFollowups(env, opts = {}) {
  if (await isWaBillingBlocked(env)) return; // pausado por bloqueo de pago de WhatsApp
  const now = Date.now();
  // Follow-up a las 23h del envío del presupuesto: lo más tarde posible DENTRO de
  // la ventana de 24h de WhatsApp para que salga como TEXTO LIBRE GRATIS (no
  // plantilla paga). Si el cron lo agarra con la ventana del cliente todavía
  // abierta → gratis; si ya cerró → plantilla paga (ver bloque windowOpen abajo).
  // Ventana de selección 23h–48h; corre solo en horario hábil 8-20.
  const minAgeAgo = new Date(now - 23 * 60 * 60 * 1000).toISOString();   // edad mínima: 23h
  const maxAgeAgo = new Date(now - (opts.maxAgeHours || 48) * 60 * 60 * 1000).toISOString();   // edad máxima: 48h normal, 72h los lunes (backlog del domingo)

  // 1) Presupuestos del cotizador enviados hace entre 24h y 48h.
  //
  // Antes: WHERE body LIKE 'prefix1%' OR body LIKE 'prefix2%'
  // Problema: D1 tira "LIKE or GLOB pattern too complex" cuando wa_messages
  // crece mucho (vimos esto en producción con ~1.5M rows). El planner no
  // puede aplicar el LIKE eficientemente y aborta.
  //
  // Fix: usar substr(body, 1, N) = 'prefix' — comparación exacta de prefijo
  // sin pattern matching. Más rápido y sin el límite de complejidad.
  // Tomamos 26 chars iniciales, suficiente para distinguir ambos formatos:
  //   'Te comparto el presupuesto' (formato nuevo)
  //   'Te comparto la información' (formato viejo)
  const pfx1 = PRESUPUESTO_PREFIXES_TEXT[0].substring(0, 26);
  const pfx2 = PRESUPUESTO_PREFIXES_TEXT[1].substring(0, 26);
  let rows;
  try {
    const rs = await env.DB.prepare(
      "SELECT phone, ts, body, sender_name FROM wa_messages " +
      "WHERE direction = 'outbound' " +
      "  AND ts >= ? AND ts <= ? " +
      "  AND length(phone) <= 14 " +   // excluir Instagram (phone = ID largo): el FUP es de WhatsApp; mandarlo por WA a un IG-id rebota
      "  AND (substr(body, 1, 26) = ? OR substr(body, 1, 26) = ?) " +
      "ORDER BY ts DESC"
    ).bind(maxAgeAgo, minAgeAgo, pfx1, pfx2).all();
    rows = rs.results || [];
  } catch (e) {
    await logWaEvent(env, { to: '', kind: 'cron-pp-followup', ref: '', ok: false, error: 'query: ' + e.message });
    return;
  }
  // 2) Latest presupuesto por teléfono (ventana 23-48h = candidatos automáticos)
  const byPhone = new Map();
  for (const r of rows) {
    const ex = byPhone.get(r.phone);
    if (!ex || new Date(r.ts) > new Date(ex.ts)) byPhone.set(r.phone, r);
  }

  if (!byPhone.size) return;

  const failures = [];
  let sent = 0;
  let skippedInvalid = 0;
  // ID de la etiqueta "FUP": si un vendedor se la pone a un chat, es porque lo sigue
  // él a mano → lo salteamos del fupeo automático (pedido de Gaspar).
  let fupLabelId = null;
  try { const _fl = await env.DB.prepare("SELECT id FROM labels WHERE name = 'FUP' LIMIT 1").first(); fupLabelId = _fl && _fl.id; } catch (_) {}
  // Reintentos acotados de la PLANTILLA de seguimiento (ver campaignSendFail). Solo frena la rama de
  // plantilla: en una caída de plantillas el FUP por texto libre (ventana abierta) sigue saliendo.
  const tplSt = await campaignState(env, 'pp-followup-tpl');
  await ensureSendRetryTable(env);

  for (const p of byPhone.values()) {
    // Freno manual: chat con etiqueta "FUP" puesta → NO mandamos el seguimiento automático.
    if (fupLabelId) {
      try { const _h = await env.DB.prepare("SELECT 1 FROM contact_labels WHERE phone = ? AND label_id = ? LIMIT 1").bind(p.phone, fupLabelId).first(); if (_h) continue; } catch (_) {}
    }
    // 3) Conversación posterior al presupuesto
    let conv;
    try {
      const rs = await env.DB.prepare(
        'SELECT direction, body, ts, status FROM wa_messages WHERE phone = ? AND ts > ? ORDER BY ts LIMIT 200'
      ).bind(p.phone, p.ts).all();
      conv = rs.results || [];
    } catch (_) { continue; }

    // Dedup ROBUSTO y directo (NO depende del LIMIT 200 del conv de arriba): en chats muy
    // largos el conv no incluía el FUP recién mandado → se re-enviaba en CADA tick del cron
    // (ej.: a Gaspar le salió 3 veces en 15'). Si ya salió un FUP automatizado (el texto que
    // arranca con 'Hola ' o la plantilla) DESPUÉS de este presupuesto, no re-mandamos.
    try {
      // Cubre TODAS las variantes (high 'Buenas!', low 'Holaa', copa, legacy, plantilla)
      // derivando los prefijos de la MISMA lista que el dedup de conv, así no se
      // desincronizan. Antes esta condición solo miraba 'Hola ' y la plantilla → las
      // variantes reales ('Buenas!' / 'Holaa') se colaban, y en chats largos (conv >
      // LIMIT 200) el FUP viejo quedaba fuera del conv → se re-enviaba en CADA tick del
      // cron (a Gaspar le llegó cada 5'). El LIKE por prefijo NO depende del LIMIT.
      const dupLike = ALL_FOLLOWUP_PREFIXES_TEXT.map(() => "body LIKE ? ESCAPE '\\'").join(' OR ');
      const dupParams = ALL_FOLLOWUP_PREFIXES_TEXT.map(pref => pref.replace(/([%_\\])/g, '\\$1') + '%');
      // IFNULL(status,'')!='failed': un FUP que REBOTÓ (marcado 'failed' por el status
      // webhook, típ. 131047 ventana cerrada) NO cuenta como enviado → se reintenta (por
      // plantilla, ver windowOpen abajo). Antes quedaba deduped y el lead sin seguimiento.
      const dupFup = await env.DB.prepare(
        "SELECT 1 FROM wa_messages WHERE phone = ? AND direction = 'outbound' AND automated = 1 AND IFNULL(status,'') != 'failed' AND ts > ? " +
        "AND (" + dupLike + ") LIMIT 1"
      ).bind(p.phone, p.ts, ...dupParams).first();
      if (dupFup) continue;
    } catch (_) {}

    // ¿Respondió el cliente? ANTES: si respondía CUALQUIER cosa, se salteaba el
    // follow-up. AHORA (pedido de Gaspar, 18/06): el FUP de las 23h TAMBIÉN va a los
    // que respondieron con un NO-COMPROMISO ("dale, lo pienso", "hablo con mi socio",
    // "gracias, me comunico") — esos demostraron interés y valen MÁS que los mudos.
    // Solo NO mandamos el FUP automático en dos casos:
    //   (a) Ya avanzó al CIERRE / compró → no spamear a quien está comprando.
    //   (b) Dejó una PREGUNTA puntual sin responder (última inbound con "?" o pidiendo
    //       factura) → lo contesta una persona (queda en "⏳ Te toca"); mandar
    //       "¿pudiste verlo?" encima de una pregunta sin responder sería tonto.
    // NO duplicar: si ya le escribimos hace poco (≤12h), no mandamos el FUP
    // automático. Cubre el caso de Joaco mandando un seguimiento MANUAL y el cron
    // disparando otro encima minutos después. El presupuesto en sí tiene ≥23h, así
    // que nunca cuenta acá — solo cuentan los mensajes posteriores (manuales).
    if (conv.some(m => m.direction === 'outbound' && m.status !== 'failed' && (now - new Date(m.ts).getTime()) < 12 * 60 * 60 * 1000)) continue;
    // No molestar a quien YA compró / está cerrando.
    if (conv.some(m => m.direction === 'outbound' && FUP_CIERRE_MARKERS.some(k => (m.body || '').toLowerCase().includes(k)))) continue;
    // Pregunta puntual sin responder → la contesta una persona (queda en "⏳ Te toca");
    // mandar "¿pudiste verlo?" encima de una pregunta sin responder sería tonto.
    const ultimoMsg = conv[conv.length - 1];
    if (ultimoMsg && ultimoMsg.direction === 'inbound' && /\?|factura/i.test(ultimoMsg.body || '')) continue;
    // ¿Ya tiene follow-up (cualquier variante: legacy, copa, low, high)?
    // Si el outbound posterior arranca con ALGUNO de los prefijos conocidos,
    // ya recibió follow-up.
    if (conv.some(m => m.direction === 'outbound' && m.status !== 'failed' && ALL_FOLLOWUP_PREFIXES_TEXT.some(pref => (m.body || '').startsWith(pref)))) continue;

    // 4) Decidir qué variante mandar según fecha y monto.
    // - Entre 24-jun y 30-jun: PROMO COPA (imagen + caption) a TODOS.
    // - Resto del tiempo: texto según monto (≷ $300k).
    const ahoraIso = new Date().toISOString();
    // Copa DESACTIVADA por pedido de Gaspar — se manda el follow-up NORMAL (high/low por monto).
    // Para reactivar: const inCopaPromo = ahoraIso >= PROMO_COPA_START_UTC && ahoraIso < PROMO_COPA_END_UTC;
    const inCopaPromo = false;
    const monto = extractPresupuestoAmount(p.body);
    let variantBody, variantKind;
    if (inCopaPromo) {
      variantBody = PROMO_COPA_CAPTION;
      variantKind = 'copa';
    } else if (monto >= FOLLOWUP_AMOUNT_THRESHOLD) {
      variantBody = FOLLOWUP_PRESUPUESTO_HIGH_TEXT;
      variantKind = 'high';
    } else {
      variantBody = FOLLOWUP_PRESUPUESTO_LOW_TEXT;
      variantKind = 'low';
    }

    // Helper para insertar el marker (sent o failed) — ambos casos previenen
    // que el próximo cron re-encuentre este presupuesto como pendiente.
    // Guarda el cuerpo de la variante real que se mandó (para dedup futuro).
    // Si es copa, también persistimos la R2 key del promo asset en media_url
    // para que el chat del CRM renderice la imagen (no "Imagen no disponible").
    const insertMarker = async (status, wamid, bodyToStore) => {
      try {
        const mediaUrl = variantKind === 'copa' ? PROMO_COPA_R2_KEY : '';
        await env.DB.prepare(
          'INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status, automated) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)'
        ).bind(new Date().toISOString(), wamid, 'outbound', p.phone, '', variantKind === 'copa' ? 'image' : 'text', bodyToStore || variantBody, mediaUrl, '', status).run();
      } catch (_) {}
    };

    // 5) Pre-validar: si el teléfono no normaliza, marcamos como fallido
    // permanente y no gastamos call al API ni notificamos al admin.
    if (!normalizeArPhone(p.phone)) {
      await insertMarker('failed', 'fu-invalid:' + p.phone, null);
      await logWaEvent(env, { to: p.phone, kind: 'pp-followup', ref: 'pp-fu:' + p.phone, ok: false, error: 'numero invalido (skip)' });
      skippedInvalid++;
      continue;
    }

    // Skip si el phone está marcado como unreachable. Insertamos marker
    // 'skipped' para no re-evaluarlo en cada cron (idempotencia).
    if (await isUnreachable(env, p.phone)) {
      await insertMarker('skipped', 'fu-unreachable:' + p.phone, null);
      continue;
    }

    // 6.0) CONTINGENCIA ventana cerrada: el texto libre solo puede salir si el
    // cliente escribió hace <24h. Como el follow-up sale días después del
    // presupuesto, casi siempre la ventana está cerrada → Meta rechaza el texto.
    // Si la ventana está cerrada, mandamos la plantilla aprobada (sí sale fuera
    // de las 24h). La ventana se mide por el último inbound del cliente.
    let windowOpen = false;
    try {
      const li = await env.DB.prepare("SELECT MAX(ts) AS t FROM wa_messages WHERE phone = ? AND direction = 'inbound'").bind(p.phone).first();
      windowOpen = !!(li && li.t && (now - new Date(li.t).getTime()) < 24 * 60 * 60 * 1000);
    } catch (_) {}
    // Si YA hubo un intento de FUP que REBOTÓ (status='failed', típ. 131047 ventana cerrada),
    // NO confiar en windowOpen: el último inbound de la DB puede estar desfasado (mensajes
    // re-importados en la migración del número → ts recientes falsos → texto libre que rebota).
    // Forzamos la plantilla, que sí sale fuera de la ventana de 24h.
    if (windowOpen) {
      try {
        const prevFail = await env.DB.prepare("SELECT 1 FROM wa_messages WHERE phone = ? AND direction = 'outbound' AND automated = 1 AND status = 'failed' AND ts > ? LIMIT 1").bind(p.phone, p.ts).first();
        if (prevFail) windowOpen = false;
      } catch (_) {}
    }
    if (!windowOpen) {
      // Flujo de plantilla pausado (caída de cuenta/plantilla) o este presupuesto en espera de
      // reintento / ya dado por perdido → no intentar en este tick. ref = ts del presupuesto: un
      // presupuesto NUEVO al mismo cliente arranca con intentos limpios.
      if (campaignPaused(tplSt)) continue;
      if ((await campaignRetryGate(env, 'pp-followup-tpl', p.phone, p.ts)).skip) continue;
      const firstName = capitalizeName((p.sender_name || '').split(/\s+/)[0]) || 'amigo/a';
      const rt = await waSendTemplate(env, p.phone, 'seguimiento_presupuesto', 'es_AR', [firstName]);
      if (rt.ok) {
        // Marker 'sent' → dedup (body reconocido por ALL_FOLLOWUP_PREFIXES_TEXT).
        sent++;
        await campaignSendOk(env, tplSt, p.phone, p.ts);
        try {
          await env.DB.prepare(
            'INSERT OR IGNORE INTO wa_messages (ts, wamid, direction, phone, sender_name, msg_type, body, media_url, context_id, status, automated) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)'
          ).bind(new Date().toISOString(), rt.id || ('fu-tpl:' + p.phone), 'outbound', p.phone, '', 'template', '[plantilla: seguimiento_presupuesto]', '', '', 'sent').run();
        } catch (_) {}
      } else {
        // Reintento ACOTADO (antes: sin marker → reintento cada 5' durante las ~25h de la ventana de
        // selección; el 25/26-sep 9 FUPs se perdieron tras 168 intentos c/u). Plantilla pending/pausada
        // o cuenta bloqueada → pausa sin gastar intentos (y sin avisar: es ruido). Agotado o
        // permanente → va al resumen al admin con el motivo real.
        const f = await campaignSendFail(env, tplSt, { phone: p.phone, ref: p.ts, res: rt, logKind: 'pp-followup-tpl' });
        if (f.action === 'failed') failures.push({ phone: p.phone, name: p.sender_name || '', error: describeSendFailure(rt) + ' (plantilla, ' + f.attempts + ' intento' + (f.attempts === 1 ? '' : 's') + ')' });
      }
      await new Promise(rs => setTimeout(rs, 600));
      continue;
    }

    // 6) Enviar (ventana ABIERTA). Si es copa, intentamos imagen+caption; si no
    // hay media disponible (R2 vacío, upload a Meta falla), caemos a texto solo.
    let r;
    if (variantKind === 'copa') {
      const mediaId = await getPromoMediaId(env, PROMO_COPA_R2_KEY);
      if (mediaId) {
        r = await waSendImage(env, p.phone, mediaId, PROMO_COPA_CAPTION);
      } else {
        // Fallback: sin imagen, solo el caption como texto.
        r = await waSendText(env, p.phone, PROMO_COPA_CAPTION);
      }
    } else {
      r = await waSendText(env, p.phone, variantBody);
    }
    if (r.ok) {
      sent++;
      await insertMarker('sent', r.id || '', null);
      await clearSendFail(env, 'ppfu:' + p.phone);
    } else {
      // Transitorio y bajo el tope → NO marcamos (reintenta el próximo cron, sin
      // avisar para no spamear). Permanente o tope alcanzado → marcar failed +
      // avisar con el motivo REAL (no el genérico "fuera de ventana").
      const n = await bumpSendFail(env, 'ppfu:' + p.phone);
      if (isTransientSendError(r) && n < SEND_FAIL_CAP) {
        // dejar pendiente para que el próximo cron lo reintente
      } else {
        await insertMarker('failed', 'fu-fail:' + p.phone + ':' + Date.now(), null);
        await clearSendFail(env, 'ppfu:' + p.phone);
        failures.push({ phone: p.phone, name: p.sender_name || '', error: describeSendFailure(r) });
      }
    }
    await logWaEvent(env, { to: p.phone, kind: 'pp-followup-' + variantKind, ref: 'pp-fu:' + p.phone, ok: r.ok, messageId: r.id, error: r.error });
    await new Promise(rs => setTimeout(rs, 600)); // delay anti rate-limit
  }

  // 5) Si fallaron envíos y hay número de admin configurado, mandar resumen
  if (failures.length && env.ADMIN_NOTIFY_PHONE) {
    const lines = failures.slice(0, 10).map(f => `• ${f.name || f.phone} (${f.phone}): ${f.error}`).join('\n');
    const more = failures.length > 10 ? `\n…y ${failures.length - 10} más` : '';
    const summary = `⚠ Follow-ups de presupuesto que no salieron (${failures.length}):\n${lines}${more}\n\n(El motivo real va al lado de cada uno. Los transitorios se reintentan solos; estos ya agotaron los reintentos o son permanentes.)`;
    try { await avisoAdmin(env, summary, { tipo: 'fup_fallido', prioridad: 'P2' }); } catch (_) {}
  }

  if (sent > 0 || failures.length > 0) {
    await logWaEvent(env, { to: '', kind: 'cron-pp-summary', ref: '', ok: true, error: `sent=${sent} failed=${failures.length}` });
  }
}

// ===== Anti-colgados: leads tibios esperando respuesta (pelota de NUESTRO lado) =====
// Marca con la etiqueta "⏳ Te toca" toda conversación donde mandamos presupuesto, el
// cliente RESPONDIÓ, y la última palabra es de él hace ≥90 min. La etiqueta se SACA
// sola cuando contestamos. 2x/día (10 y 17 AR) manda un resumen a los internos
// (Joaco + Gaspar). Objetivo: que ningún lead tibio se cuelgue por olvido. El FUP
// automático solo cubre a los que quedaron MUDOS; esto cubre el hueco de los que
// respondieron y se dejan enfriar. Ver playbook §A4.1.
const COLGADO_LABEL_NAME = '⏳ Te toca';
const COLGADO_LABEL_COLOR = '#f59e0b';
const COLGADO_MIN_MS = 90 * 60 * 1000;                                // 1h30 esperando
const COLGADO_INTERNAL_PHONES = ['5491137593269', '5491155604999'];   // Joaco, Gaspar

async function processColgados(env) {
  const now = Date.now();
  const labelId = await ensureLabelId(env, COLGADO_LABEL_NAME, COLGADO_LABEL_COLOR);
  if (!labelId) return;

  // 1) Presupuestos enviados en los últimos 12 días (prefijo exacto, sin LIKE → sin
  //    el límite de complejidad de D1; mismos prefijos que usa el FUP).
  const since = new Date(now - 12 * 24 * 60 * 60 * 1000).toISOString();
  const pfx1 = PRESUPUESTO_PREFIXES_TEXT[0].substring(0, 26);
  const pfx2 = PRESUPUESTO_PREFIXES_TEXT[1].substring(0, 26);
  let presRows;
  try {
    const rs = await env.DB.prepare(
      "SELECT phone, MAX(ts) AS pres_ts FROM wa_messages " +
      "WHERE direction='outbound' AND ts >= ? AND (substr(body,1,26)=? OR substr(body,1,26)=?) " +
      "GROUP BY phone"
    ).bind(since, pfx1, pfx2).all();
    presRows = rs.results || [];
  } catch (e) {
    await logWaEvent(env, { to: '', kind: 'cron-colgados', ref: '', ok: false, error: 'query: ' + e.message });
    return;
  }

  // 2) Determinar quiénes están colgados (respondieron + última palabra de ellos + ≥90 min).
  //    Nunca el equipo: los fijos + todo wa_internal_phones (Agus/Facu/Abril/Emma/Bruno…).
  const internos = new Set(COLGADO_INTERNAL_PHONES);
  try { for (const r of ((await env.DB.prepare('SELECT phone FROM wa_internal_phones').all()).results || [])) internos.add(String(r.phone)); } catch (_) {}
  const colgados = [];
  for (const p of presRows) {
    if (internos.has(p.phone)) continue;
    let conv;
    try {
      const rs = await env.DB.prepare(
        "SELECT direction, ts, sender_name FROM wa_messages WHERE phone=? AND ts>? ORDER BY ts LIMIT 200"
      ).bind(p.phone, p.pres_ts).all();
      conv = rs.results || [];
    } catch (_) { continue; }
    if (!conv.length) continue;
    if (!conv.some(m => m.direction === 'inbound')) continue;          // mudo → lo cubre el FUP
    const last = conv[conv.length - 1];
    if (last.direction !== 'inbound') continue;                         // ya contestamos → no es colgado
    const waitedMs = now - new Date(last.ts).getTime();
    if (waitedMs < COLGADO_MIN_MS) continue;                            // todavía no llegó al umbral
    try { if (await env.DB.prepare("SELECT 1 FROM archived_chats WHERE phone=?").bind(p.phone).first()) continue; } catch (_) {}
    let name = '';
    try { const c = await env.DB.prepare("SELECT name FROM wa_contacts WHERE phone=?").bind(p.phone).first(); name = (c && c.name) || ''; } catch (_) {}
    if (!name) { const inb = [...conv].reverse().find(m => m.direction === 'inbound' && m.sender_name); name = (inb && inb.sender_name) || ''; }
    colgados.push({ phone: p.phone, waitingMin: Math.round(waitedMs / 60000), name });
  }
  const colgadoSet = new Set(colgados.map(c => c.phone));

  // 3) Aplicar la etiqueta a los colgados.
  for (const c of colgados) {
    try { await env.DB.prepare("INSERT OR IGNORE INTO contact_labels (phone, label_id, created_at) VALUES (?, ?, ?)").bind(c.phone, labelId, new Date().toISOString()).run(); } catch (_) {}
  }
  // 4) Sacar la etiqueta de los que YA NO están colgados (contestamos / avanzaron / se archivaron).
  try {
    const tagged = (await env.DB.prepare("SELECT phone FROM contact_labels WHERE label_id=?").bind(labelId).all()).results || [];
    for (const t of tagged) {
      if (!colgadoSet.has(t.phone)) {
        try { await env.DB.prepare("DELETE FROM contact_labels WHERE phone=? AND label_id=?").bind(t.phone, labelId).run(); } catch (_) {}
      }
    }
  } catch (_) {}

  // 5) Resumen a los internos 2x/día (10:00 y 17:00 AR), dedup por kv_cache.
  const hAR = (new Date().getUTCHours() - 3 + 24) % 24;
  const minute = new Date().getUTCMinutes();
  if ((hAR === 10 || hAR === 17) && minute < 5 && colgados.length > 0) {
    const dateKeyAR = new Date(now - 3 * 60 * 60 * 1000).toISOString().slice(0, 10);
    const slotKey = `colgados-summary:${dateKeyAR}:${hAR}`;
    let already = false;
    try { already = !!(await env.DB.prepare("SELECT v FROM kv_cache WHERE k=?").bind(slotKey).first()); } catch (_) {}
    if (!already && !(await isWaBillingBlocked(env))) {
      const top = colgados.sort((a, b) => b.waitingMin - a.waitingMin).slice(0, 12);
      const lines = top.map(c => {
        const hrs = c.waitingMin >= 60 ? `${Math.floor(c.waitingMin / 60)}h${String(c.waitingMin % 60).padStart(2, '0')}` : `${c.waitingMin}min`;
        return `• ${c.name || ('+' + c.phone)} — hace ${hrs}`;
      }).join('\n');
      const more = colgados.length > 12 ? `\n…y ${colgados.length - 12} más` : '';
      const msg = `⏳ *Leads esperándote* (${colgados.length})\nRespondieron el presupuesto y tienen la pelota de nuestro lado 👇\n\n${lines}${more}\n\nEntrá al CRM → Chat → filtro "${COLGADO_LABEL_NAME}" y respondeles. No los dejes enfriar! 🔥`;
      for (const ph of COLGADO_INTERNAL_PHONES) {
        try { await waSendText(env, ph, msg); } catch (_) {}
        await new Promise(r => setTimeout(r, 400));
      }
      try { await env.DB.prepare("INSERT INTO kv_cache (k, v, updated_at) VALUES (?, ?, ?) ON CONFLICT(k) DO UPDATE SET v=excluded.v, updated_at=excluded.updated_at").bind(slotKey, String(colgados.length), new Date().toISOString()).run(); } catch (_) {}
    }
  }

  if (colgados.length > 0) {
    await logWaEvent(env, { to: '', kind: 'cron-colgados', ref: '', ok: true, error: `colgados=${colgados.length}` });
  }
}

async function runScheduled(env) {
  const url = env.APPS_SCRIPT_FOLLOWUPS_URL;
  if (!url) {
    await logWaEvent(env, { to: '', kind: 'cron', ref: '', ok: false, error: 'APPS_SCRIPT_FOLLOWUPS_URL no configurado' });
    return;
  }
  let items;
  try {
    const r = await fetch(url, { method: 'GET' });
    const j = await r.json();
    items = Array.isArray(j?.items) ? j.items : [];
  } catch (e) {
    await logWaEvent(env, { to: '', kind: 'cron', ref: '', ok: false, error: 'fetch apps script: ' + e.message });
    return;
  }
  if (!items.length) {
    await logWaEvent(env, { to: '', kind: 'cron', ref: '', ok: true, error: '0 followups pendientes' });
    return;
  }
  const result = await runFollowups(env, items);
  await logWaEvent(env, {
    to: '', kind: 'cron-summary', ref: '',
    ok: true, error: `sent=${result.sent} skipped=${result.skipped} errors=${result.errors}`
  });
}

async function reportHandler(env, url, _admin) {
  const userFilter = url.searchParams.get('user') || '';
  const from = url.searchParams.get('from') || '';
  const to   = url.searchParams.get('to')   || '';
  let where = 'undo = 0';
  const params = [];
  if (userFilter) { where += ' AND user = ?'; params.push(userFilter); }
  if (from)       { where += ' AND ts >= ?'; params.push(from); }
  if (to)         { where += ' AND ts <= ?'; params.push(to); }
  const rs = await env.DB.prepare(
    `SELECT user, item_kind, action, ts FROM events WHERE ${where} ORDER BY ts DESC LIMIT 5000`
  ).bind(...params).all();
  return json({ rows: rs.results || [] });
}
